INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/AA/AASSC/06397', 'Airport Terminal Operations Executive', 'aerospace-aviation', 'Aerospace & Aviation', 4.0, 'The Airport Terminal Operations Executive is tasked with the responsibility of performing tasks that cover the Terminal and Airside areas of an airport. They are also responsible for safety and security aspects of the operations and manage customer & stakeholder expectations.', 480, 540, '401–600', 'Version', '29 Sep 2022', '29 Sep 2025', 'Aerospace and Aviation Sector Skill Council (AASSC)', 'AASSC (Aerospace and Aviation Sector Skill Council)', 'Airport Terminal Operations Executive', 'Airport Terminal Operations Supervisor (level 5)', 'General Qualification', 'N.A.', '{"Theory":"150","Practical":"270","EmployabilitySkills":"60","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "1", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 19_19_25.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/AA/AASSC/06399', 'Airport Terminal Operations Manager Operations', 'aerospace-aviation', 'Aerospace & Aviation', 6.0, 'The Airport Operations Manager is responsible for overall management of Airport Operational functions and to provide Safety and Security oversight. S/he is also responsible for managing contingencies and enhance customer experience through process improvements. In the course of performance of these functions, they are also expected to manage people and stakeholders both internal and external.', 570, 660, '601–800', 'Version', '29 Sep 2022', '29 Sep 2025', 'Aerospace and Aviation Sector Skill Council (AASSC)', 'AASSC (Aerospace and Aviation Sector Skill Council)', 'Airport Terminal Operations Manager', 'Airport Terminal Operations Senior Manager (level 7)', 'General Qualification', 'N.A.', '{"Theory":"240","Practical":"330","EmployabilitySkills":"60","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "2", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 19_19_25.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/AA/AASSC/06398', 'Airport Terminal Operations Supervisor', 'aerospace-aviation', 'Aerospace & Aviation', 5.0, 'The Airport Terminal Operations Supervisor is responsible for Supervision of daily operations and ensure that they are safe and secure. He/she also is responsible for supervising the handling of contingencies, emergencies and enhance customer experience through process improvements. Additionally, they are expected to manage people and stakeholders.', 570, 630, '601–800', 'Version', '29 Sep 2022', '29 Sep 2025', 'Aerospace and Aviation Sector Skill Council (AASSC)', 'AASSC (Aerospace and Aviation Sector Skill Council)', 'Airport Terminal Operations Supervisor', 'Airport Terminal Operations Manager (level 6)', 'General Qualification', 'N.A.', '{"Theory":"240","Practical":"330","EmployabilitySkills":"60","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "3", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 19_19_25.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/AA/AASSC/06511', 'Airline Customer Service Executive', 'aerospace-aviation', 'Aerospace & Aviation', 4.0, 'Airline Customer Service Executive, is responsible for the administrative and customer service functions.
Customer service executives are responsible for meeting the needs and safety requirements of passengers
and airport personnel. They assist customers before and after a flight.', 480, 570, '401–600', 'Version', '17 Nov 2022', '17 Nov 2025', 'Aerospace and Aviation Sector Skill Council (AASSC)', 'AASSC (Aerospace and Aviation Sector Skill Council)', 'Airline Customer Service Executive', 'Airline Customer Service Executive,Supervisor terminal services,Duty manager – terminal services,Airport manager,GM Airport Services', 'General Qualification', 'N.A.', '{"Theory":"150","Practical":"270","EmployabilitySkills":"60","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "4", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 19_19_25.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
