INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-AA-04186-2025-V1-AASSC', 'Airline First Officer - Ground Level', 'aerospace-aviation', 'Aerospace & Aviation', 5.0, 'An Airline First Officer (Ground Level) assists in pre-flight planning, operational coordination, and aircraft readiness checks to support efficient and safe flight operations. They collaborate with flight crews, ground staff, and dispatch teams to ensure compliance with safety protocols and regulations. This role serves as a preparatory stage for full in-flight responsibilities as a licensed First Officer.', 2160, 2160, '1201–2400', 'Version', '08 May 2025', '08 May 2028', 'Aerospace and Aviation Sector Skill Council (AASSC)', 'Aerospace and Aviation Sector Skill Council', 'Airline Operations', 'Cadet First Officer', 'General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"880","Practical":"1060","EmployabilitySkills":"60","OJT_Mandatory":"160"}', false, '{}'::text[], '{"source_row": "9", "qualification_type": "General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 19_19_25.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
