INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-AA-04187-2025-V2-AASSC', 'Airport Safety Officer', 'aerospace-aviation', 'Aerospace & Aviation', 4.0, 'The Airport Safety Officer is responsible for maintaining a safe and secure environment within the airport premises, including airside and landside areas. Their duties involve regular inspections, hazard identification, monitoring compliance with safety procedures, and responding to emergencies such as accidents, spills, fires, or security breaches. They ensure that airport operations comply with aviation safety regulations, organizational protocols, and environmental standards. The crew coordinates ground handling teams, air traffic control, emergency response units, and maintenance personnel to proactively manage risks and uphold operational safety standards.', 450, 450, '401–600', 'Version', '08 May 2025', '08 May 2028', 'Aerospace and Aviation Sector Skill Council (AASSC)', 'Aerospace and Aviation Sector Skill Council', 'Airport Safety', 'Senior Airport Safety Officer', 'General Qualification', 'N.A.', '{"Theory":"170","Practical":"190","EmployabilitySkills":"30","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "14", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 19_19_25.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
