INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-AA-04191-2025-V2-AASSC', 'Aerospace Composite Technician', 'aerospace-aviation', 'Aerospace & Aviation', 4.0, 'Aerospace Composite Technician is responsible for performing composite operation on aerospace parts and understanding the part drawings and its process sheets, and understanding the safety points and precautions for manufacturing composite parts.', 630, 630, '601–800', 'Version', '08 May 2025', '08 May 2028', 'Aerospace and Aviation Sector Skill Council (AASSC)', 'Aerospace and Aviation Sector Skill Council', 'Composites and Plastics Production', 'Aerospace Composites and Plastic Engineer', 'Future Skills Qualification', 'N.A.', '{"Theory":"210","Practical":"330","EmployabilitySkills":"60","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "16", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 19_19_25.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-AA-04192-2025-V2-AASSC', 'Airport Warehouse Coordinator', 'aerospace-aviation', 'Aerospace & Aviation', 4.0, 'Airport Warehouse Coordinator is responsible for supervising and controlling the activities of ground crew in loading, unloading, securing and staging of aircraft cargo in and around the airport premises. He must ensure all cargo is moved from storage area to aircraft and vice versa in a safe and timely manner. He will also be responsible for handling accounting and record keeping activities of the warehouse', 420, 420, '401–600', 'Version', '08 May 2025', '08 May 2028', 'Aerospace and Aviation Sector Skill Council (AASSC)', 'Aerospace and Aviation Sector Skill Council', 'Cargo Terminal Operations', 'Supervisor - Airport Warehouse Coordinator', 'General Qualification', 'N.A.', '{"Theory":"135","Practical":"195","EmployabilitySkills":"30","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "17", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 19_19_25.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-AA-03904-2025-V2-AASSC', 'Airline Flight Load Controller', 'aerospace-aviation', 'Aerospace & Aviation', 5.0, 'The Load controller undertakes load distribution and calculation to ensure intended flight operates with the safety envelope as prescribed in the organizations operations manual', 390, 390, '201–400', 'Version', '08 May 2025', '30 Apr 2028', 'Aerospace and Aviation Sector Skill Council (AASSC)', 'Aerospace and Aviation Sector Skill Council', 'Airline Operations', 'Senior Flight Load Controller', 'General Qualification', 'N.A.', '{"Theory":"90","Practical":"120","EmployabilitySkills":"60","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "18", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 19_19_25.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-AA-03902-2025-V2-AASSC', 'Airline Ground Support Equipment Operator', 'aerospace-aviation', 'Aerospace & Aviation', 4.0, 'An Airline Ground Support Equipment (GSE) Operator is responsible for operating and maintaining ground support equipment, such as tugs, belt loaders, and aircraft tractors. This role ensures the safe and efficient movement of aircraft and luggage on the ground. Operators must be trained in safety protocols, equipment handling, and airport operations.', 390, 390, '201–400', 'Version', '06 May 2025', '30 Apr 2028', 'Aerospace and Aviation Sector Skill Council (AASSC)', 'Aerospace and Aviation Sector Skill Council', 'Loading and unloading', 'Supervisor Ground Support Equipment; 
Airline Ground Support Equipment Operator', 'General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"105","Practical":"135","EmployabilitySkills":"30","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "19", "qualification_type": "General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 19_19_25.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-AG-00092-2023-V1-ASCI', 'Vriksh Sanrakshak', 'agriculture', 'Agriculture', 4.0, 'A Vriksh Sanrakshak is responsible for planting, maintaining, and removing trees, woody plants and shrubs. The individual is required to prune trees, woody plants and shrubs and remove diseased or potentially dangerous ones. This involves climbing trees and manoeuvring in and around them. The person also maintains the health of trees, woody plants and shrubs, which involves pest and disease management and the application of fertilizers, soil health management and irrigation. The individual also uses and maintains various hand and power tools for carrying out relevant tasks.', 390, 390, '201–400', 'Version', '05 Jan 2023', '05 Jan 2026', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India (ASCI)', 'Agro-Forestry Management', 'Vriksh Sanrakshak (L4), Arboriculture Supervisor (L5)', 'General Qualification', 'N.A.', '{"Theory":"120","Practical":"150","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "1", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-AG-00093-2023-V1-ASCI', 'Precision Farming Technician', 'agriculture', 'Agriculture', 5.0, 'A Precision Farming Technician is responsible for using the relevant technologies in agricultural activities to enhance productivity and profitability while ensuring sustainability and protection of the land resources. The individual uses relevant technologies and equipment such as Geographic Information System (GIS), Global Positioning System (GPS), drones, a variety of sensors, and relevant computer software to collect and analyze different types of data from agricultural fields. The person identifies and makes appropriate improvements in the field based on data analysis. The individual is also responsible for regular maintenance of mechanical controls, sensors, GPS and GIS systems, etc.', 480, 480, '401–600', 'Version', '05 Jan 2023', '05 Jan 2026', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India (ASCI)', 'Precision Farming', 'Precision Farming Technician, Supervisor-Precision Farming', 'General Qualification', 'N.A.', '{"Theory":"120","Practical":"150","EmployabilitySkills":"90","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "2", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-FI-00144-2023-V1-MSU', 'Large Cardamom Organic Cultivation and Management', 'agriculture', 'Agriculture', 4.0, 'This qualification is designed to provide theoretical knowledge and practical skills in a selection of suitable cardamom varieties based on agroecological situations and market demand, soil and climatic conditions required for successful organic cultivation, nursery management for disease-free planting material production, laying out the plantation field and planting of seedlings and suckers, intercultural operations like weeding and hoeing, water management including design and method of irrigation, operating farm machinery, maintaining farm equipment, on farm inputs production for nutrient pests and diseases management viz. Farmyard manure, vermicompost, biofertilizer, enriched compost. fermented plant extracts etc. and their application, understanding the manure, fertilizer, and biopesticides requirement and their application, harvesting of capsules using the specialized equipment and suckers differentiation, participating in the inspection, grading, sorting, storage, and other operations during post-harvest management of cardamom like packing, loading farm produce into trucks/carts and requirement for transportation, storage facilities, marketing (marketing through FPOS, regulated market, retail marketing) and selling the farm produce.', 480, 480, '401–600', 'Version', '31 Jan 2023', '31 Jan 2026', 'Medhavi Skill University', 'Medhavi Skills University', 'Large Cardamom Cultivator; Large Cardamom Seedlings Cultivator; Large Cardamom Harvester; Large Cardamom Grower; Large Cardamom Processor; Field Worker', '●	Vertical - Large Cardamom Farming Trainer, Farming Community Leader
●	Horizontal - Large Cardamom Seedlings cultivator and trader
●	Academic: Diploma in Agriculture or Food Processing', 'General Qualification', 'N.A.', '{"Theory":"182","Practical":"298","EmployabilitySkills":"00","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "3", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-AG-00371-2023-V1-ASCI', 'Agri Commodity Fumigation Operator', 'agriculture', 'Agriculture', 4.0, 'An Agri Commodity Fumigation Operator is responsible for assessing and preparing the worksite and relevant equipment for the fumigation of agricultural commodities, carrying out and monitoring fumigation, and ensuring health and safety at the fumigation worksite.', 390, 390, '201–400', 'Version', '29 Mar 2023', '29 Mar 2026', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India(ASCI)', 'Commodity Management', 'Agri Commodity Fumigation Operator (NSQF Level -4), Agri Commodity Quality Assayer (NSQF Level -5)', 'General Qualification', 'N.A.', '{"Theory":"120","Practical":"150","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "4", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-5.5-AG-00352-2023-V1-ASCI', 'Agri Commodity Procurement Manager', 'agriculture', 'Agriculture', 5.5, 'An Agri Commodity Procurement Manager is responsible for managing the procurement of agricultural commodities. The individual develops and implements the procurement strategy. The person selects appropriate suppliers and manages procurements and supplier relationships. The individual is also responsible for financial reviews, assessing customer satisfaction, and taking appropriate measures to achieve cost-efficiency, sustainability and customer satisfaction.', 600, 600, '401–600', 'Version', '29 Mar 2023', '29 Mar 2026', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India (ASCI)', 'Commodity Management', 'Agri Commodity Procurement Manager (NSQF Level -5), Risk Analyst Manager-Agri Commodity (NSQF Level -6)', 'General Qualification', 'N.A.', '{"Theory":"180","Practical":"210","EmployabilitySkills":"90","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "5", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-AG-00350-2023-V1-ASCI', 'Agri Commodity Quality Assayer', 'agriculture', 'Agriculture', 5.0, 'An Agri Commodity Quality Assayer is responsible for ensuring the quality standards concerning agricultural commodities are met in an organization. The individual develops the relevant quality standards and manual, coordinates quality audits, and checks adherence to the applicable quality standards by conducting quality checks.', 510, 510, '401–600', 'Version', '29 Mar 2023', '29 Apr 2026', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India (ASCI)', 'Commodity Management', 'Agri Commodity Quality Assayer (NSQF Level -5), Agri Commodity Procurement Manager (NSQF Level -6)', 'General Qualification', 'N.A.', '{"Theory":"150","Practical":"150","EmployabilitySkills":"90","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "6", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-AG-00345-2023-V1-ASCI', 'Agri Warehouse Supervisor', 'agriculture', 'Agriculture', 5.0, 'An Agri Warehouse Supervisor is responsible for supervising and coordinating the activities of warehouse workers involved in the receipt, handling and dispatch of agricultural produce. The individual is responsible for monitoring and maintaining the optimum stock levels and ensuring efficient warehouse operations.', 510, 510, '401–600', 'Version', '29 Mar 2023', '29 Mar 2026', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India (ASCI)', 'Post-Harvest Supply Chain Management', 'Agri Warehouse Supervisor Traceability (NSQF Level -6), Traceability Officer (NSQF Level -6)', 'General Qualification', 'N.A.', '{"Theory":"150","Practical":"150","EmployabilitySkills":"90","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "7", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-AG-00374-2023-V1-ASCI', 'Essential Oil Extractor', 'agriculture', 'Agriculture', 3.0, 'An Essential Oil Extractor is responsible for extracting essential oils from the harvested Medicinal and Aromatic Plants (MAPs). In the process, the individual collects the relevant MAPs, uses the appropriate equipment to extract essential oils and follows the appropriate oil extraction methods. The person also assists in marketing the extracted oils.', 270, 270, '201–400', 'Version', '29 Mar 2023', '29 Mar 2026', 'Agriculture Skill Council of India (ASCI)', 'AgricultureSkillCouncilofIndia(ASCI)', 'Essential Oil Extractor, Medicinal and Aromatic Plants Cultivation', 'Essential Oil Extractor (L3), Medicinal plants grower (NSQF Level-4)', 'General Qualification', 'N.A.', '{"Theory":"90","Practical":"120","EmployabilitySkills":"30","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "8", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-AG-00373-2023-V1-ASCI', 'Gardener cum Nursery Raiser', 'agriculture', 'Agriculture', 4.0, 'A Gardener cum Nursery Raiser is responsible for setting up and maintaining the garden and raising seedlings and saplings of a variety of plants. This individual maintains the seedlings and saplings during nursery propagation and harvests and transplants them in the garden. The individual also maintains the trees and plants in the garden and performs regular gardening activities.', 360, 390, '201–400', 'Version', '29 Mar 2023', '29 Mar 2026', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India (ASCI)', 'Landscaping, Gardening & Urban Farming', 'Gardener Cum Nursery Raiser(L3),Heritage Gardener (NSQF Level-5)', 'General Qualification', 'N.A.', '{"Theory":"120","Practical":"180","EmployabilitySkills":"60","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "9", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-AG-00375-2023-V1-ASCI', 'Goat/Sheep Farmer', 'agriculture', 'Agriculture', 3.0, 'A Goat/Sheep Farmer is responsible for establishing the goat/sheep farm, procuring and rearing goats/sheep, and managing their feeding and health. The individual also breeds goats/sheep and markets them and their produce.', 270, 300, '201–400', 'Version', '29 Mar 2023', '29 Mar 2026', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India (ASCI)', 'Small Ruminants & Others', 'Goat/Sheep Farmer(L3), Livestock Service Provider (NSQF Level- 4)', 'General Qualification', 'N.A.', '{"Theory":"90","Practical":"150","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "10", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-AG-00363-2023-V1-ASCI', 'Group Farming Practitioner', 'agriculture', 'Agriculture', 4.0, 'A Group Farming Practitioner is responsible for facilitating and participating in the formation of a variety of groups, such as Common Interest Group (CIGs)/Farmer Interest Groups (FIGs)/Self Help Groups (SHGs)/ Producer Groups (PGs), to serve the common interests of farmers. The individual facilitates the adoption of the latest farming technologies and practices among the group members. The person is also responsible for performing basic farm management, assimilating market information, and undertaking farm waste management.', 360, 420, '401–600', 'Version', '29 Mar 2023', '29 Mar 2026', 'Agriculture Skill Council of India (ASCI)', 'AgricultureSkillCouncilofIndia(ASCI)', 'Agri-Entrepreneurship & Rural Enterprises', 'Group Farming Practitioner(L3), Agri Service Input Dealer (NSQF Level-5)', 'General Qualification', 'N.A.', '{"Theory":"120","Practical":"180","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "11", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-5.5-AG-00344-2023-V1-ASCI', 'Institution Development Manager', 'agriculture', 'Agriculture', 5.5, 'An Institution Development Manager is responsible for developing community institutions to effectively allocate and sustainably use material and financial resources to achieve the set objectives. The person is responsible for organizing the community into various informal/ formal institutions and building their capacities.', 570, 570, '401–600', 'Version', '29 Mar 2023', '29 Mar 2026', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India (ASCI)', 'Agri-Entrepreneurship & Rural Enterprises', 'Institution Development Manager (L5), Agri-Clinic & Agri- Business Center Manager (NSQF Level-6)', 'General Qualification', 'N.A.', '{"Theory":"180","Practical":"180","EmployabilitySkills":"90","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "12", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-AG-00364-2023-V1-ASCI', 'Lac Cultivator', 'agriculture', 'Agriculture', 3.0, 'A Lac Cultivator is responsible for the complete lac cultivation process. It includes growing host trees to be inoculated with brood lac, pruning the host trees and inoculating them with brood lac, and monitoring and maintaining the lac crop. The individual is also responsible for harvesting lac crop and carrying out its post-harvest processing', 270, 270, '201–400', 'Version', '29 Mar 2023', '29 Mar 2026', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India (ASCI)', 'Agro-Forestry Management', 'Lac Cultivator (L3), Lac Trader (NSQF Level-4)', 'General Qualification', 'N.A.', '{"Theory":"90","Practical":"120","EmployabilitySkills":"30","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "13", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-AG-00368-2023-V1-ASCI', 'Makhana Grower cum Processor', 'agriculture', 'Agriculture', 4.0, 'A Makhana Grower cum processor is responsible for growing makhana and its processing. During the process, the individual prepares the selected water body or land for makhana cultivation, raises and transplants makhana seedlings or broadcasts makhana seeds in the water body, and maintains the makhana. The person is also responsible for harvesting makhana seeds, its post-harvest management and marketing. The individual may also prepare makhana products.', 390, 420, '401–600', 'Version', '29 Mar 2023', '29 Mar 2026', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India (ASCI)', 'Fruit Crops Cultivation', 'Makhana Grower cum Processor (NSQF Level-4), Farm Supervisor (NSQF Level-5)', 'General Qualification', 'N.A.', '{"Theory":"120","Practical":"180","EmployabilitySkills":"60","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "14", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-AG-00376-2023-V1-ASCI', 'Piggery Farmer', 'agriculture', 'Agriculture', 3.0, 'A Piggery Farmer is responsible for rearing pigs on pig farms. The individual establishes a pig farm, performs feed and health management of pigs and markets them. The person may procure pigs for breeding and undertake pig breeding. Similarly, the individual may also undertake pig fattening.', 270, 270, '201–400', 'Version', '29 Mar 2023', '29 Mar 2026', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India (ASCI)', 'Small Ruminants & Others', 'Piggery Farmer (NSQF Level- 3), Livestock Service Provider (NSQF Level- 4)', 'General Qualification', 'N.A.', '{"Theory":"90","Practical":"120","EmployabilitySkills":"30","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "15", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-AG-00377-2023-V1-ASCI', 'Spice Crop Cultivator', 'agriculture', 'Agriculture', 4.0, 'A Spice Crop Cultivator is responsible for cultivating spice crops and, during the process, performs various activities, such as selecting the site and preparing the field, nursery propagation of seedlings, soil fertility, weed, irrigation and Integrated Pest and Disease (IPDM) management. The individual is also responsible for harvesting, post-harvest management and marketing of spice crops. The individual may cultivate different types of spice crops', 390, 600, '401–600', 'Version', '29 Mar 2023', '29 Mar 2026', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India (ASCI)', 'Spice Crops Cultivation', 'Spice Crop Cultivator (L4), Farm Supervisor (NSQF Level- 5)', 'General Qualification', 'N.A.', '{"Theory":"120","Practical":"150","EmployabilitySkills":"60","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "16", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-AG-00366-2023-V1-ASCI', 'Vineyard Grower', 'agriculture', 'Agriculture', 4.0, 'A Vineyard Grower is responsible for growing grapes. In the process, the individual selects and prepares the land for establishing a vineyard and plants and maintains grape vines, including nutrient, pest, and disease management. The person is also responsible for harvesting mature grapes, storing them safely and marketing them to the relevant buyers and markets. The person supervises vineyard workers in large vineyards.', 390, 390, '201–400', 'Version', '29 Mar 2023', '29 Mar 2026', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India (ASCI)', 'Fruit Crops Cultivation', 'Vineyard Grower (L4), Farm Supervisor (NSQF Level-5)', 'General Qualification', 'N.A.', '{"Theory":"120","Practical":"150","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "17", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-AG-00378-2023-V1-ASCI', 'Water Resource Community Mobilizer', 'agriculture', 'Agriculture', 4.0, 'A Water Resource Community Mobilizer: Watershed Management, Springshed Management, Groundwater Management is responsible for mobilizing the village community to develop and manage water resources. The individual helps organize the community into community institutions and build their capacities. The person is also responsible for active community participation to ensure the successful execution and sustenance of the water resource interventions. The individual assists in planning, implementing, monitoring and reviewing watershed/ springshed/ groundwater programs.', 390, 450, '401–600', 'Version', '29 Mar 2023', '29 Mar 2026', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India (ASCI)', 'Watershed Management', 'Water Resource Community Mobilizer(L3.5), Water Resource Coordinator (NSQF Level -4.5)', 'General Qualification', 'N.A.', '{"Theory":"130","Practical":"170","EmployabilitySkills":"60","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "18", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
