INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-02-AG-01011-2023-V1-ASCI & Version 1.0', 'Flower Grower', 'agriculture', 'Agriculture', 2.0, 'A Flower Grower performs various activities in the process of cultivating flower crop such as selecting the site; preparing the field; propagating saplings in the nursery; transplanting the sapling, and maintaining
the plants. The person is also responsible for carrying out harvesting, post-harvesting processing and marketing of the flower crop.', 210, 450, '401–600', 'Version', '29 Sep 2023', '29 Sep 2026', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India
                        Unit No. 101, First Floor, Greenwoods Plaza, Block ''B'', Greenwoods City, Sector 45, Gurugram -122009, Haryana.', 'Floriculture Farming', 'Flower Grower, Assistant Floriculturist', 'General Qualification', 'N.A.', '{"Theory":"100","Practical":"110","EmployabilitySkills":"00","OJT_Mandatory":"00"}', false, '{}'::text[], '{"source_row": "54", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-AG-02425-2024-V1-ASCI', 'Organic Farm and Business Promoter', 'agriculture', 'Agriculture', 5.0, 'The individual is responsible for providing technical expertise in organic farming practices. The individual will have the expertise to facilitate in certification and marketing of organic produce. The person will also foster backward and forward linkages in the value chains, facilitate financial linkages and access to credit for farmers, farmer groups and agribusiness organisations. The individual may provide capacity building services, and strengthen the business potential of the Farmer groups by helping develop an economically viable and environmentally sustainable business plan and execute it.', 480, 480, '401–600', 'Version', '30 Apr 2024', '30 Apr 2027', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India
                                                                        Unit No. 101, First Floor, Greenwoods Plaza, Block ''B'', Greenwoods City, Sector 45, Gurugram -122009, Haryana', 'Farm Management (Agriculture information management)', 'Organic Farm & Business Facilitator (L5), Organic Produce Auditor (L6)/ Organic Produce Exporter (L6)', 'General Qualification', 'N.A.', '{"Theory":"225","Practical":"195","EmployabilitySkills":"00","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "55", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-4.5-AG-02424-2024-V1-ASCI', 'Carbon Farming Practitioner', 'agriculture', 'Agriculture', 4.5, 'The individual is responsible for adopting a whole farm approach to enhance the storage of carbon into soil/trees and or reduce CO2 and other greenhouse gas emissions using various land, water and crop management practices.', 480, 480, '401–600', 'Version', '30 Apr 2024', '30 Apr 2027', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India
                                                                        Unit No. 101, First Floor, Greenwoods Plaza, Block ''B'', Greenwoods City, Sector 45, Gurugram -122009, Haryana', 'Agro-forestry Management (Field Crop and Vegetable Grower)', 'Carbon Farming Practitioner (L4.5), Farm Supervisor (L5)', 'Future Skills Qualification', 'N.A.', '{"Theory":"230","Practical":"160","EmployabilitySkills":"00","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "56", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QC-5.5-AG-02423-2024-V1-ASCI', 'Digital Agriculture Extension Promoter', 'agriculture', 'Agriculture', 5.5, 'The individual is responsible for advising and facilitating farmers towards the successful integration of digital technologies into agricultural practices at farmer’s level and at a broader level with the agri-food systems. The person is involved in collecting and analyzing the agricultural data for facilitating data- driven decision making. The person is also responsible for creating digital content and disseminating it through various digital media platforms.', 570, 690, '601–800', 'Version', '30 Apr 2024', '30 Apr 2027', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India
                                                                        Unit No. 101, First Floor, Greenwoods Plaza, Block ''B'', Greenwoods City, Sector 45, Gurugram -122009, Haryana.', 'Precision Farming (Agriculture information management)', 'Digital Agriculture Extension Promoter (L 5.5), Digital Farm Advisor (L6)', 'Future Skills Qualification', 'N.A.', '{"Theory":"185","Practical":"145","EmployabilitySkills":"00","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "57", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
