INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-AG-02610-2024-V2-ASCI', 'Power Tiller Operator', 'agriculture', 'Agriculture', 3.0, 'A Power Tiller Operator operates a power tiller as part of tilling operations at a farm. S/he also uses the power tiller for other farm operations by attaching relevant attachments to it. The individual is also responsible for carrying out periodical repair and maintenance of the power tiller.', 270, 270, '201–400', 'Version', '30 May 2024', '30 May 2027', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India (ASCI)', 'Farm Machinery, Equipment Operation and maintenance (Operator, Farm Machines)', 'Power Tiller Operator (L3), Tractor Operator (L4)', 'General Qualification', 'N.A.', '{"Theory":"90","Practical":"120","EmployabilitySkills":"30","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "84", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-AG-02608-2024-V2-ASCI', 'Plant Tissue Culture Technician', 'agriculture', 'Agriculture', 4.0, 'A Plant Tissue Technician performs several activities such as preparing the lab, culture media and mother plant, extracting, preparing, planting and maintaining explants. The person also transplants the tissue cultured plants and maintains record of laboratory operations.', 390, 390, '201–400', 'Version', '30 May 2024', '30 May 2027', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India (ASCI)', 'Agricultural Technicians, Others (Research & Development)', 'Plant Tissue Culture Technician (L5), Plant Tissue Lab Culture Supervisor (L5)', 'General Qualification', 'N.A.', '{"Theory":"90","Practical":"120","EmployabilitySkills":"60","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "85", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-AG-02612-2024-V2-ASCI', 'Custom Hiring Centre In-charge (Agri machinery)', 'agriculture', 'Agriculture', 5.0, 'A Custom Hiring Centre In-charge (Agri machinery) is responsible for providing hiring services to small and marginal farmers for various crop- specific machineries, tools and equipment used in different farm operations. For this purpose, the individual sets up a centre and makes these available for hiring to farmers on demand basis.', 480, 480, '401–600', 'Version', '30 May 2024', '30 May 2027', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India (ASCI)', 'Farm Machinery, Equipment Operation, and maintenance (Agriculture Engineering Technician)', 'Custom Hiring Centre In-charge (Agri machinery) (L5), Sales Manager (Agri Machinery) (L6)', 'General Qualification', 'N.A.', '{"Theory":"90","Practical":"180","EmployabilitySkills":"90","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "86", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-2.5-AG-02611-2024-V2-ASCI', 'Pesticide & Fertilizer Applicator', 'agriculture', 'Agriculture', 2.5, 'A Pesticide and fertilizer applicator is responsible for proper application of pesticides and fertilizers on various crops. S/he will also be responsible for monitoring of pests in the crop and take appropriate measures for not only the protection of crops but also increase the yields.', 270, 270, '201–400', 'Version', '30 May 2024', '30 May 2027', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India (ASCI)', 'Farm Management (Farm Machinery Operators, Other)', 'Pesticide & Fertilizer Applicator (L2.5), Kisan Drone Operator (L3)', 'General Qualification', 'N.A.', '{"Theory":"90","Practical":"120","EmployabilitySkills":"60","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "87", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-2.5-AG-02614-2024-V2-ASCI', 'Flower Packager and Palletizer', 'agriculture', 'Agriculture', 2.5, 'A Flower Packager and Palletizer identifies harvested flowers of good quality, processes and then packs them for being transported to domestic/ international markets while maintaining the processing standards. The person also creates flower seed pellets using the appropriate machinery.', 270, 270, '201–400', 'Version', '30 May 2024', '30 May 2027', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India (ASCI)', 'Floriculture Farming (Nursery Workers and Gardeners, Other)', 'Flower Packager and Palletizer (L2.5), Floral Sales Associate (L3)', 'General Qualification', 'N.A.', '{"Theory":"90","Practical":"120","EmployabilitySkills":"30","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "88", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-AG-02615-2024-V2-ASCI', 'Harvesting Machinery Operator', 'agriculture', 'Agriculture', 4.0, 'A Harvesting Machinery Operator is responsible for operating and carrying out minor repair and maintenance of harvesting and post harvesting machinery such as reaper, thresher, chaff cutter, etc. The individual may also upskill her/ himself to operate post- harvest machineries such as cleaner and grader, dryer, oil expeller, etc.', 390, 420, '401–600', 'Version', '30 May 2024', '30 May 2027', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India (ASCI)', 'Farm Machinery, Equipment Operation and maintenance (Farm Machinery Operators, Other)', 'Harvesting Machinery Operator (L4),  Repair and Maintenance Supervisor/Entrepreneur (Agri Machinery) (L5)', 'General Qualification', 'N.A.', '{"Theory":"90","Practical":"150","EmployabilitySkills":"60","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "89", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
