INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-AG-02609-2024-V2-ASCI', 'Repair and Maintenance Technician (Farm Machinery)', 'agriculture', 'Agriculture', 4.0, 'A Repair and Maintenance Technician (Farm Machinery) is responsible for carrying out service and maintenance of farm machineries such as disc plough and harrow, seed driller, plant protection equipment, reaper, thresher, chaff cutter, sugarcane crusher, etc.', 390, 390, '201–400', 'Version', '30 May 2024', '30 May 2027', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India (ASCI)', 'Farm Machinery, Equipment Operation and maintenance (Farm Machinery Operators, Other)', 'Repair and Maintenance Technician (Farm Machinery) (L4), Repair and Maintenance Supervisor (Farm Machinery) (L5)', 'General Qualification', 'N.A.', '{"Theory":"105","Practical":"135","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "91", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-AG-02613-2024-V2-ASCI', 'Repair and Maintenance Supervisor (Farm Machinery)', 'agriculture', 'Agriculture', 5.0, 'A Repair and Maintenance Supervisor (Farm Machinery) is responsible for ensuring timely availability of repair and maintenance services to farmers, in order to enhance agricultural mechanization.', 480, 480, '401–600', 'Version', '30 May 2024', '30 May 2027', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India (ASCI)', 'Farm Machinery, Equipment Operation and maintenance (Agriculture Engineering Technician)', 'Repair and Maintenance Supervisor (Farm Machinery) (L5), Farm Workshop Manager (L6)', 'General Qualification', 'N.A.', '{"Theory":"90","Practical":"180","EmployabilitySkills":"90","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "92", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-2.5-AG-02836-2024-V1-DYMT', 'Soil Testing Junior Technician', 'agriculture', 'Agriculture', 2.5, '•	To enhance the quality and fertility of soil, a soil-testing technician conducts routine soil analyses in a lab or field, and aids soil scientists or chemists when required. 
•	They collect appropriate soil samples, dry them in an oven, and sift them to attain the desired particle size. Employing precise measurements and standardized procedures, they ascertain the physical and chemical attributes of the soil, encompassing shear strength, permeability, composition, moisture content, and carbon, nitrogen levels. 
•	Under the guidance of Senior soil  technician or chemist, they can adjust the soil composition by adding or removing chemicals, and fertilizers to rectify deficiencies, and apply organic methods of nutrient management to boost fertility, among other objectives. 
•	They meticulously document measurements and observations for further examination and future reference. 
•	Additionally, they prepare requisite standard chemicals and solutions for sample testing and uphold cleanliness and orderliness in the laboratory.', 360, 420, '401–600', 'Version', '25 Jul 2024', '25 Jul 2027', 'Divya Yogi Mandir Trust', 'Divya Yog Mandir Trust
Registered Office: Kripalu Bagh Ashram, Kankhal, Haridwar-249408, Uttarakhand, India 
