INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-AG-02925-2024-V1-ASCI', 'Tropical/Sub-tropical Fruit Grower', 'agriculture', 'Agriculture', 4.0, 'The individual is responsible for cultivating tropical/sub-tropical fruits as per the recommended practices in the given agro-climatic zone and achieve the expected yield. This includes various activities such as preparation, planting, nurturing of crop, harvest and post-harvest of the tropical/subtropical fruit crops and ensuring the sale of the same', 390, 570, '401–600', 'Version', '27 Aug 2024', '27 Feb 2026', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India (ASCI)', 'Fruit Crop Cultivation (Cultivator, Fruit)', 'Tropical/Subtropical Fruit Grower, Horticulture Farm Supervisor', 'General Qualification', 'N.A.', '{"Theory":"120","Practical":"150","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "94", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-AG-03235-2024-V2-ASCI', 'Mushroom Grower', 'agriculture', 'Agriculture', 4.0, 'A Mushroom Grower performs various activities in the process of cultivating mushroom such as preparing mushroom compost, spawning, maintenance, harvesting and post-harvest processing of mushroom.', 390, 390, '201–400', 'Version', '22 Oct 2024', '22 Oct 2027', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India (ASCI)', 'Field Crop and Vegetable Growers (Agri-Entrepreneurship & Rural Enterprises)', 'Mushroom Grower (L4), Agri-produce retailer/trader (L5)', 'General Qualification', 'N.A.', '{"Theory":"120","Practical":"210","EmployabilitySkills":"30","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "95", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-AG-02924-2024-V1-ASCI', 'Horticulturist (Protected Cultivation)', 'agriculture', 'Agriculture', 5.0, 'The Horticulturist (Protected Cultivation) undertakes various activities which involves preparation of soil deciding on planting material, planting, nurturing and harvesting in a protected environment such as greenhouse, polyhouse, shade-net house or tunnels or synthetic mulches. The individual is also involved in the setup and maintenance of the structure and the environment inside the structures.', 480, 660, '601–800', 'Version', '27 Aug 2024', '27 Feb 2026', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India (ASCI)', 'Precision Farming (Gardeners, Horticultural and Nursery Growers)', 'Horticulturist (Protected Cultivation), Greenhouse Manager', 'General Qualification', 'N.A.', '{"Theory":"120","Practical":"180","EmployabilitySkills":"90","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "96", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-04-AG-02985-2024-V1-ASCI', 'Basics of Cage Culture Fish Farming', 'agriculture', 'Agriculture', 4.0, 'A Cage Culture Fish Farmer rears different variety of fish in marine/brackish/freshwater cages. The person is responsible for preparing, installing and maintaining the cages for fish farming. The individual is also responsible for harvesting and marketing the reared fish.', 45, 45, '1–200', 'Version', '27 Aug 2024', '27 Aug 2027', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India (ASCI)', 'Aquaculture, Aquaculture Workers', 'NA-', 'National Occupational Standard', 'N.A.', '{"Theory":"15","Practical":"30","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "97", "qualification_type": "National Occupational Standard", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-AG-03351-2024-V1-CUTM', 'Aquaponics Cultivator', 'agriculture', 'Agriculture', 4.0, 'The Individual is responsible to understand that Aquaponics is a productive, innovative and sustainable approach to food production that combines hydroponics—the practice of growing plants in water—with aquaculture, the rearing of aquatic animals. Fish faces serve as a natural fertilizer for the plants in this recirculating system.', 510, 510, '401–600', 'Version', '22 Oct 2024', '21 Oct 2027', 'Centurion University of Technology and Management (CUTM)', 'Centurion University of Technology and Management (CUTM)', 'Cultivator', 'Aquaponics Supervisor', 'General Qualification', 'N.A.', '{"Theory":"150","Practical":"180","EmployabilitySkills":"60","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "98", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-3.5-AG-03354-2024-V1-CUTM', 'Pollinator Habitat Maker', 'agriculture', 'Agriculture', 3.5, 'A Pollinator Habitat Maker will be responsible for fabricating and maintaining natural habitat for supporting and sustaining biological species causing pollination. Broadly, the job of the designer will include designing the landscape of the habitat using appropriate methods, selection of plant species, selection of pollinating species and strategies for the conservation of habitat. The work will further include engaging the public to raise awareness about managing pollination, pollinators and pollinator habitat.', 360, 360, '201–400', 'Version', '22 Oct 2024', '21 Oct 2027', 'Centurion University of Technology and Management (CUTM)', 'Centurion University of Technology and Management', 'Pollination', 'Pollinator Habitat Conservation Ecologist', 'General Qualification', 'N.A.', '{"Theory":"110","Practical":"190","EmployabilitySkills":"30","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "99", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-AG-03353-2024-V1-CUTM', 'Topiary Garden Artist', 'agriculture', 'Agriculture', 4.0, 'The individual is responsible to understand quality parameters of Topiary Garden Artist. Trainee able to disseminate the knowledge and skills related to topiary to new generations of gardeners. Handle different artistic aspects of topiary techniques. Add value to the garden, parks and office gardens. Outcomes of topiary maintenance encompass the preservation of design, plant health, long-term sustainability of living sculptures and maintain their aesthetic and artistic roles in the garden or landscape in their specific environments. Understand the roles and responsibilities as topiary trainer experts.', 420, 420, '401–600', 'Version', '22 Oct 2024', '21 Oct 2027', 'Centurion University of Technology and Management (CUTM)', 'Centurion University of Technology and Management', 'Gardener', 'Topiary Designer', 'General Qualification', 'N.A.', '{"Theory":"140","Practical":"200","EmployabilitySkills":"30","OJT_Mandatory":"50"}', false, '{}'::text[], '{"source_row": "100", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-AG-03352-2024-V1-CUTM', 'Seaweed Grower and Processor', 'agriculture', 'Agriculture', 4.0, 'The Individual is responsible to understand about Seaweed Grower and Processor, check water quality, nutrition, and health benefits and indirectly evaluate the quality parameters of fish and fishery products.', 510, 510, '401–600', 'Version', '22 Oct 2024', '21 Oct 2027', 'Centurion University of Technology and Management (CUTM)', 'Centurion University of Technology and Management', 'Post-Harvest', 'Seaweed Processing Facility Junior Supervisor', 'General Qualification', 'N.A.', '{"Theory":"150","Practical":"180","EmployabilitySkills":"60","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "101", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-AG-03355-2024-V1-CUTM', 'Vermimanuring Technician', 'agriculture', 'Agriculture', 4.0, 'The Individual is responsible to understand the vermimanuring and production of vermimanuring, selection of composting material (organic and inorganic) and worm species, vermibed preparation and value addition of vermicomposting and by-products for the sustainable agriculture production.', 570, 570, '401–600', 'Version', '22 Oct 2024', '21 Oct 2027', 'Centurion University of Technology and Management (CUTM)', 'Centurion University of Technology and Management', 'Animal Producers and Related Workers, Other', 'Vermicompost  Production Jr. Supervisor', 'General Qualification', 'N.A.', '{"Theory":"190","Practical":"230","EmployabilitySkills":"30","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "102", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-AG-03350-2024-V1-CUTM', 'Remote Sensing Junior Analyst (Agriculture)', 'agriculture', 'Agriculture', 5.0, 'This advanced course transfers complex information into actionable insights. These analyst use their expertise in earth observation data to bring valuable insights to farmers and the agricultural industry as a whole which includes monitoring crop health and growth, soil and water management and  weather forecasting that empowers farmers and ultimately contribute to a more sustainable and productive agricultural sector.', 630, 630, '601–800', 'Version', '22 Oct 2024', '21 Oct 2027', 'Centurion University of Technology and Management (CUTM)', 'Centurion University of Technology and Management', 'Cartographers and Surveyors', 'Remote Sensing Analysis Manager', 'Cross Sectoral Qualification', 'N.A.', '{"Theory":"160","Practical":"260","EmployabilitySkills":"60","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "103", "qualification_type": "Cross Sectoral Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-AG-03236-2024-V2-ASCI', 'Fish Seed Grower', 'agriculture', 'Agriculture', 4.0, 'A Fish Seed Grower is responsible for raising the seeds of varieties of fish species. The person oversees the preparation of pond and the culture activities including the harvesting and post-harvest management of seeds.', 450, 450, '401–600', 'Version', '22 Oct 2024', '22 Oct 2027', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India (ASCI)', 'Aquaculture Workers', 'Fish Seed Grower (L4), Aquaculture Technical Supervisor (L5)', 'General Qualification', 'N.A.', '{"Theory":"150","Practical":"210","EmployabilitySkills":"60","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "104", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-AG-03416-2024-V2-ASCI', 'Tractor Service Mechanic', 'agriculture', 'Agriculture', 4.0, 'A Tractor Service Mechanic performs routine checks, carries out maintenance and repair of tractor engine and other parts. S/he also assembles repaired and serviced parts, checks the performance of the transmission, hydraulic and auto-electrical systems, etc.', 390, 450, '401–600', 'Version', '26 Nov 2024', '26 Nov 2027', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India (ASCI)', 'Motor Vehicle Mechanics and Repairers (Farm Machinery, Equipment Operation and maintenance)', 'Tractor Service Mechanic(L4), Repair and Maintenance supervisor (Farm machinery)/ Custom Hiring in-charge (L5)', 'General Qualification', 'N.A.', '{"Theory":"90","Practical":"180","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "105", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-04-AG-03276-2024-V1-ASCI', 'Essentials of Agri Services and Input Retailing', 'agriculture', 'Agriculture', 4.0, 'This Occupational standard unit is about understanding the judicious and balanced use of agri-inputs, promoting nutrient management for fertilizer use efficiency and sustainable practices through products and best practices ensuring agricultural productivity and sustainability and the use of various e-platforms for better agri- advisory to the farmers.', 22, 22, '1–200', 'Version', '22 Oct 2024', '22 Oct 2027', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India (ASCI)', 'N/A', 'N/A', 'Future Skills Qualification,Micro Credentials,Upskilling Qualification', 'N.A.', '{"Theory":"14.5","Practical":"8","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "106", "qualification_type": "Future Skills Qualification,Micro Credentials,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-04-AG-03277-2024-V1-ASCI', 'Essentials of Internal Control Inspections (Organic Standards)', 'agriculture', 'Agriculture', 4.0, 'This OS unit deals with the internal control inspections conducted for ensuring the integrity of organic farming practices under the Grower Group certification for NPOP Standard.', 30, 30, '1–200', 'Version', '22 Oct 2024', '22 Oct 2027', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India (ASCI)', 'N/A.', 'N/A.', 'Future Skills Qualification,Micro Credentials,Upskilling Qualification', 'N.A.', '{"Theory":"16","Practical":"14","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "107", "qualification_type": "Future Skills Qualification,Micro Credentials,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-AG-03413-2024-V2-ASCI', 'Livestock Service Provider', 'agriculture', 'Agriculture', 4.0, 'A Livestock Service Provider (LSP), also known as a Community Animal Health Worker (CAHW), Community Resource Person (Veterinary), or Animal Health Worker (AHW), is a person selected from his/her community to provide livestock extension and development-related services along with a set of "Minor Veterinary services" required for the given job role. The Minor Veterinary Services will be as per the notification under the Indian Veterinary Council Act (No.52 of 1984).', 450, 540, '401–600', 'Version', '26 Nov 2024', '26 Nov 2027', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Information Management (Livestock Health Management)', 'Livestock Service Provider (L4), Veterinary Field Assistant/ Veterinary Clinical Assistant(L5)/ Livestock Green Management Promoter (L5)', 'General Qualification', 'N.A.', '{"Theory":"120","Practical":"210","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "108", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-AG-03418-2024-V2-ASCI', 'Poultry Farm Worker', 'agriculture', 'Agriculture', 3.0, 'The Poultry Farm Worker carry out daily operations on the poultry farm for raising birds for egg/meat production. This includes managing the birds by feeding, watering, litter management and collecting eggs. The individual also performs the routines in maintenance of the poultry house, equipment and other heating and cooling system as and when needed. They also follow proper bio- security measures as recommended in the poultry farm.', 270, 270, '201–400', 'Version', '26 Nov 2024', '26 Nov 2027', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India (ASCI)', 'Poultry Producers (Poultry Farming)', 'Poultry Farm Worker (Level 3), Small Poultry Farmer ( Level 4)', 'General Qualification', 'N.A.', '{"Theory":"90","Practical":"150","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "109", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-AG-03414-2024-V2-ASCI', 'Artificial Insemination Technician', 'agriculture', 'Agriculture', 4.0, 'An Artificial Insemination Technician (AI Technician) also known as Multipurpose Artificial Insemination Technician in rural India (MAITRIs), Gopalmitra, Pranibandhu, etc. is a person preferably selected from his/her own community, primarily to assist farmers in cattle breeding and management of dairy animals. He/she normally works under the direct supervision and monitoring of any registered development / private / producer-led agency. An Artificial Insemination Technician needs to work under the direct or distant supervision of a registered veterinarian while offering services notified as Minor Veterinary Services under the provision of the Indian Veterinary Council Act ( No.52 of 1984 ).', 390, 420, '401–600', 'Version', '26 Nov 2024', '26 Nov 2027', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India (ASCI)', 'Livestock Workers/Other Livestock Workers (Livestock Health Management)', 'Artificial Insemination Technician (L4), AI Supervisor (L5)/Animal Lab Assistant(L5)', 'General Qualification', 'N.A.', '{"Theory":"110","Practical":"160","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "110", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-AG-03415-2024-V2-ASCI', 'Greenhouse Operator', 'agriculture', 'Agriculture', 3.0, 'A Greenhouse Operator assists in setting up and maintaining a greenhouse. The person is also responsible for planting, maintaining, harvesting and marketing different types of plants, vegetables and flowers in a greenhouse.', 300, 270, '201–400', 'Version', '26 Nov 2024', '26 Nov 2027', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India (ASCI)', 'Gardeners, Horticultural and Nursery Growers (Precision Farming)', 'Greenhouse Operator (L3), Greenhouse Installer (L4)', 'General Qualification', 'N.A.', '{"Theory":"90","Practical":"150","EmployabilitySkills":"60","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "111", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-AG-03419-2024-V2-ASCI', 'Poultry Hatchery Operator', 'agriculture', 'Agriculture', 3.0, 'A Poultry Hatchery Operator is responsible for assessing the functioning of the incubation equipment and deciding on the specifications of the setters.', 300, 300, '201–400', 'Version', '26 Nov 2024', '26 Nov 2027', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India (ASCI)', 'Poultry Producers', 'Poultry Hatchery Operator (Level 3), Senior Poultry Hatchery Operator (Level 4)', 'General Qualification', 'N.A.', '{"Theory":"90","Practical":"150","EmployabilitySkills":"30","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "112", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-AG-03417-2024-V2-ASCI', 'Combine Harvester Machine Operator', 'agriculture', 'Agriculture', 4.0, 'A Combine Harvester Machine operator prepares a combine harvester machine for operation, operates it to harvest crop and carries out routine maintenance and repair of the harvester to keep it operational during the critical harvesting period.', 390, 390, '201–400', 'Version', '26 Nov 2024', '26 Nov 2027', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India (ASCI)', 'Harvesting Machine Operator (Farm Machinery, Equipment Operation and Maintenance)', 'Combine Harvester Machine Operator (L4),Custom Hiring Centre In-charge (Agri machinery) (L5)', 'General Qualification', 'N.A.', '{"Theory":"60","Practical":"120","EmployabilitySkills":"60","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "113", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-AG-03420-2024-V2-ASCI', 'Poultry Hatchery Supervisor', 'agriculture', 'Agriculture', 5.0, 'A Poultry Hatchery Supervisor is responsible	 for overseeing various activities involved in the incubation process. The individual at work receives and grade eggs, manage incubation practice, grade and pack chicks, estimates and organizes required resources, maintain equipment, building and environment for hatching chicks according to market standards', 480, 480, '401–600', 'Version', '26 Nov 2024', '26 Nov 2027', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India (ASCI)', 'Poultry Producers', 'Poultry Hatchery Supervisor (Level 5), Hatchery Manager (Level 6)', 'General Qualification', 'N.A.', '{"Theory":"90","Practical":"150","EmployabilitySkills":"90","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "114", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-AG-03563-2025-V2-ASCI', 'Assistant Gardener', 'agriculture', 'Agriculture', 3.0, 'An Assistant Gardener helps in setting up and maintaining garden and garden features under the gardener’s supervision. The person also carries out harvesting and basic marketing activities along with preparing the garden for outdoor events and activities.', 300, 300, '201–400', 'Version', '18 Feb 2025', '18 Feb 2028', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India', 'Landscaping, Gardening and Urban Farming', 'Assistant Gardener(L3), Master Gardener (L4)', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"90","Practical":"150","EmployabilitySkills":"30","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "115", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-AG-03566-2025-V2-ASCI', 'Micro-Irrigation Technician', 'agriculture', 'Agriculture', 4.0, 'A Micro-Irrigation Technician is responsible for planning, installing, testing and commissioning micro-irrigation systems in the field to ensure uninterrupted supply of water for farm operations.', 390, 390, '201–400', 'Version', '18 Feb 2025', '18 Feb 2028', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India', 'Precision Farming', 'Micro irrigation Technician (L4), Precision Farming Technician (L5)', 'Apprenticeship Qualification,Future Skills Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"105","Practical":"195","EmployabilitySkills":"60","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "116", "qualification_type": "Apprenticeship Qualification,Future Skills Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-AG-03565-2025-V2-ASCI', 'Tractor Operator', 'agriculture', 'Agriculture', 4.0, 'A Tractor Operator operates a tractor for various farm operations, uses additional machinery and implements according to the task, and performs basic repair and maintenance to keep the tractor operational.', 390, 390, '201–400', 'Version', '18 Feb 2025', '18 Feb 2028', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India', 'Tractor Operator, Farm (Farm Machinery, Equipment Operation and Maintenance)', 'Tractor Operator (L4), Custom Hiring Service Provider (L5)', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"90","Practical":"150","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "117", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-2.5-AG-03557-2025-V2-ASCI', 'Fishery Hatchery Production Worker', 'agriculture', 'Agriculture', 2.5, 'The fishery hatchery production worker assists in pre-spawning, spawning and post-spawning activities and performs general maintenance of the hatchery.', 240, 240, '201–400', 'Version', '18 Feb 2025', '18 Feb 2028', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India', 'Hatchery Production Worker (Aquaculture Workers)', 'Fishery Hatchery Production Worker (L2.5), Fishery Hatchery Assistant (L3)', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"80","Practical":"130","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "118", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-AG-03561-2025-V2-ASCI', 'Shrimp Farmer', 'agriculture', 'Agriculture', 4.0, 'A Shrimp Farmer performs various activities such as selecting the shrimp species to be cultured, setting up the shrimp farm, procuring and stocking the shrimp seeds and monitoring the culture system. The person is also responsible for feeding, sampling, aerating, harvesting and marketing the shrimps.', 390, 390, '201–400', 'Version', '18 Feb 2025', '18 Feb 2028', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India', 'Aquaculture Workers', 'Shrimp Farmer (L4), Aquaculture Technical Supervisor (L5)', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"120","Practical":"180","EmployabilitySkills":"60","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "119", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-AG-03562-2025-V2-ASCI', 'Aquaculture Technical Supervisor', 'agriculture', 'Agriculture', 5.0, 'An Aquaculture Technical Supervisor (Also Known as Aquaculture Technician) is responsible for ensuring the preparation of the pond for aquaculture, maintaining a healthy growth of the cultured species and harvesting them using the recommended methods. The person may also use the Bio floc and Recirculating Aquaculture System (RAS) technologies.', 480, 600, '401–600', 'Version', '18 Feb 2025', '18 Feb 2028', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India', 'Aquaculture Workers (Aquaculture)', 'Aquaculture technical supervisor (L5), Aquaculture Manager (L6)', 'Apprenticeship Qualification,Future Skills Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"90","Practical":"180","EmployabilitySkills":"90","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "120", "qualification_type": "Apprenticeship Qualification,Future Skills Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-AG-03567-2025-V2-ASCI', 'Non-Timber Forest Produce Harvester', 'agriculture', 'Agriculture', 3.0, 'A Non-Timber Forest Producer harvests different types of Non-Timber Forest Produce (NTFP) and Medicinal and Aromatic Plants (MAPs) from the identified unrestricted areas. The person identifies the relevant NTFP and MAPs and harvests them using suitable harvesting practices while complying with the relevant laws and regulations', 270, 270, '201–400', 'Version', '18 Feb 2025', '18 Feb 2028', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India (ASCI)', 'Gatherer, Medicinal Herbs (Agro-Forestry Management)', 'Non-Timber Forest Produce Harvester (L3), Medicinal and Aromatic Plants Grower (L4)', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"80","Practical":"130","EmployabilitySkills":"30","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "121", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-2.5-AG-03556-2025-V2-ASCI', 'Aquaculture Worker', 'agriculture', 'Agriculture', 2.5, 'An Aquaculture Worker is responsible for assisting in performing pre-stocking, stocking and post-stocking activities. The person also assists in performing harvesting, post-harvesting and regular repair and maintenance activities', 270, 270, '201–400', 'Version', '18 Feb 2025', '18 Feb 2028', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India (ASCI)', 'Aquaculture Workers (Aquaculture)', 'Aquaculture Worker (L2.5), Aquaculture Farm Assistant (L3)', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"100","Practical":"140","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "122", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-AG-03560-2025-V2-ASCI', 'Ornamental Fish Farmer', 'agriculture', 'Agriculture', 4.0, 'An Ornamental Fish Famer is responsible for breeding, seed production and rearing of seeds of different types of ornamental fish of domestic and export value. The individual may also set up and maintain marine and freshwater aquariums and possess knowledge on aquarium accessories like aerator, filters, feeding, aquatic weeds and other substratum materials', 390, 450, '401–600', 'Version', '18 Feb 2025', '18 Feb 2028', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India (ASCI)', 'Aquaculture Workers (Aquaculture)', 'Ornamental Fish Farmer (L4), Aquaculture Technical Supervisor (L5)', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"90","Practical":"150","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "123", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-AG-03564-2025-V2-ASCI', 'Quality Seed Grower', 'agriculture', 'Agriculture', 4.0, 'A Quality Seed Grower produces a variety of high-quality seed crops under the supervision of a field supervisor from the seed production company. The person is responsible for preparing the field, sowing, maintaining, harvesting and performing post-harvest processing of the foundation and certified seeds as per the instructions of the seed production company.', 390, 390, '201–400', 'Version', '18 Feb 2025', '18 Feb 2028', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India (ASCI)', 'Seed Grower/Quality Seed Grower', 'Quality Seed Grower (L4), Seed Analysis-In charge (L5)', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"120","Practical":"150","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "124", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-AG-03559-2025-V2-ASCI', 'Freshwater Aquaculture Farmer', 'agriculture', 'Agriculture', 4.0, 'A Freshwater Aquaculture Farmer is responsible for the purchase of quality seeds, managing pre-stocking and post-stocking practices, including rearing, sampling and harvesting for the production of healthy commercially important freshwater fish and other aquatic organisms and marketing them.', 390, 390, '201–400', 'Version', '18 Feb 2025', '18 Feb 2028', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India (ASCI)', 'Pisciculturist (Aquaculture)', 'Freshwater Aquaculture Farmer (L4), Aquaculture Technical Supervisor (L5)', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"90","Practical":"180","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "125", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-AG-03558-2025-V2-ASCI', 'Fisheries Extension Associate', 'agriculture', 'Agriculture', 4.0, 'A Fisheries Extension Associate is responsible for educating and assisting the fishing community members in best industry practices by arranging training sessions, demonstrations, panel discussions etc. The individual also helps the community in setting up self-help groups, cooperative societies and FPOs, and also connect with the relevant authorities to resolve their concerns.', 390, 390, '201–400', 'Version', '18 Feb 2025', '18 Feb 2028', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India (ASCI)', 'Farming, Forestry and Fisheries Advisors (Assistance Fisheries)', 'Fisheries Extension Associate (L4), Fisheries Extension Officer (L5)', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"90","Practical":"210","EmployabilitySkills":"60","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "126", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-AG-03555-2025-V2-ASCI', 'Agriculture Machinery Demonstrator', 'agriculture', 'Agriculture', 5.0, 'An Agriculture Machinery Demonstrator demonstrates and teaches the operations of various agricultural machineries such as tractor, power tiller, disc plough, harrow, seed drill, planter, irrigation system, harvest, etc. to the farmers.', 480, 480, '401–600', 'Version', '18 Feb 2025', '18 Feb 2026', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India (ASCI)', 'Farm Machinery Operators, Other', 'Agriculture Machinery Demonstrator (L5), Farm Workshop Manager (L6)', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"120","Practical":"180","EmployabilitySkills":"90","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "127", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-AG-03533-2025-V2-ASCI', 'Bamboo Cultivator', 'agriculture', 'Agriculture', 3.0, 'A Bamboo cultivator is responsible for propagating bamboo saplings in a nursery; transplanting them into the field, and maintaining and harvesting bamboo culms. The individual is also responsible for marketing the harvested bamboos culms.', 270, 270, '201–400', 'Version', '18 Feb 2025', '18 Feb 2028', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India (ASCI)', 'Bamboo Grower', 'Bamboo Cultivator (L3),Timber Grower(L4)/Forest Nursery Raiser(L4)', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"90","Practical":"150","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "128", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-AG-03541-2025-V2-ASCI', 'Coconut Grower cum Primary Processor', 'agriculture', 'Agriculture', 4.0, 'A Coconut grower cum Primary Processor is responsible for growing coconut and performs various activities such as selecting a suitable site, raising coconut seedlings in the nursery, transplanting the seedlings and maintaining the crop. The individual is also responsible for harvesting, processing and marketing the coconut produce.', 390, 390, '201–400', 'Version', '18 Feb 2025', '18 Feb 2026', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India (ASCI)', 'Coconut Grower', 'Coconut Grower cum Primary Processor (L4), Plantation Supervisor (L5)', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"120","Practical":"210","EmployabilitySkills":"60","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "129", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-AG-03544-2025-V2-ASCI', 'Dairy Farmer - Entrepreneur', 'agriculture', 'Agriculture', 4.0, 'A Dairy Farmer takes various decisions for the viability and sustainability of the dairy farm. He / She ensures proper care of dairy animals, their health and productivity, milking and marketing of the produced milk. The job is to be performed in an efficient manner to allow the production of high-quality milk and promote animal well-being and comfort', 390, 390, '201–400', 'Version', '18 Feb 2025', '18 Feb 2028', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India (ASCI)', 'Farmer, Dairy/Dairy Farmer/Entrepreneur', 'Dairy Farmer - Entrepreneur (L4), Dairy Farm Supervisor(L5)', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"120","Practical":"180","EmployabilitySkills":"60","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "130", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-2.5-AG-03543-2025-V2-ASCI', 'Dairy Worker', 'agriculture', 'Agriculture', 2.5, 'A Dairy Worker has to perform the duties of caring, feeding and milking for the livestock on the dairy farm. The individual should take proper care of dairy animals which involves maintaining the animal areas, lots and barns clean and free from manure and extraneous objects.', 240, 240, '201–400', 'Version', '18 Feb 2025', '18 Feb 2028', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India (ASCI)', 'Dairy Farm Worker, General/Dairy Worker', 'Dairy Worker (L 2.5), Dairy Farm Assistant (L3)', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"90","Practical":"120","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "131", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-AG-03547-2025-V2-ASCI', 'Sericulturist', 'agriculture', 'Agriculture', 3.0, 'A Sericulturist is responsible for rearing silkworms to obtain raw silk fibre from them. The individual procures silkworm eggs; arranges to hatch them; hatches and rears silkworms during their developmental stages; harvests and processes cocoon to extract raw silk fibre from them. The person also propagates and maintains mulberry trees for mulberry leaves to feed silkworms.', 270, 270, '201–400', 'Version', '18 Feb 2025', '18 Feb 2026', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India (ASCI)', 'Rearer, Silkworm/ Sericulturist', 'Sericulturist (L3), Seed Cocoon Producer Level (L4)', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"90","Practical":"150","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "132", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-AG-03549-2025-V2-ASCI', 'Beekeeper', 'agriculture', 'Agriculture', 3.0, 'A Beekeeper is responsible for carrying out beekeeping operations which include preparing for and setting up beehives; procuring and introducing bees in hives, and maintaining the bees and beehives. The individual is also responsible for harvesting, processing and marketing honey and related produce.', 270, 270, '201–400', 'Version', '18 Feb 2025', '18 Feb 2028', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India (ASCI)', 'Beekeeper', 'Beekeeper (L3), Floriculturist (L4)', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"90","Practical":"150","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "133", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-2.5-AG-03551-2025-V2-ASCI', 'Agriculture Warehouse Worker', 'agriculture', 'Agriculture', 2.5, 'An Agriculture Warehouse is responsible for carrying out various activities at a warehouse such as unloading, varieties of agricultural produce received at the warehouse, sorting and grading the produce, preparing the storage area and sorting the produce, maintaining the produce and loading the produce in the transport vehicle. The individual is also responsible for assisting in maintaining various records and carrying out minor repair and maintenance activities in the warehouse. The person carries out these activities under supervision.', 240, 240, '201–400', 'Version', '18 Feb 2025', '18 Feb 2028', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India (ASCI)', 'Warehouse Worker', 'Agriculture Warehouse Worker (L 2.5), Agriculture Warehouse Assistant (L 3)', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"80","Practical":"130","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "134", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-AG-03546-2025-V2-ASCI', 'Small Poultry Farmer', 'agriculture', 'Agriculture', 4.0, 'A Small Poultry Farmer is responsible for raising different types of domestic birds for the purpose of egg
and/or meat production. The person takes various decisions for the viability and sustainability of the
poultry farm. The individual ensures proper care of the poultry birds, their health and productivity, meat
and/or egg production and marketing of the produce', 390, 390, '201–400', 'Version', '18 Feb 2025', '18 Feb 2028', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India (ASCI)', 'Farmer, Poultry/Broiler Farm Supervisor', 'Small Poultry Farmer (L4), Poultry Farm Supervisor (L5)', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"120","Practical":"180","EmployabilitySkills":"60","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "135", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-AG-03531-2025-V2-ASCI', 'Solar Pump Technician', 'agriculture', 'Agriculture', 4.0, 'A Solar Pump Technician performs various activities such as conducting site assessment and installing solar panel, battery, pump and plumbing system. The individual also monitors the solar pump and carries out its repair and maintenance.', 390, 390, '201–400', 'Version', '18 Feb 2025', '18 Feb 2028', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India (ASCI)', 'Agricultural Technicians', 'Solar Pump Technician (L4), Sales Associate (Solar Setup) (L5)', 'Apprenticeship Qualification,Future Skills Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"105","Practical":"195","EmployabilitySkills":"60","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "136", "qualification_type": "Apprenticeship Qualification,Future Skills Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-AG-03540-2025-V2-ASCI', 'Organic Grower', 'agriculture', 'Agriculture', 4.0, 'The job of an organic grower involves cultivation of organic crops as per the organic package of practices recommended for a particular agro climate zone, using approaches like diversity, cattle integration, on- farm input generation, biomass recycling, natural resource use optimization in exclusion of synthetic inputs directly or indirectly and sell the organic produce as per the competitive market prices without distress sale.', 390, 390, '201–400', 'Version', '18 Feb 2025', '18 Feb 2028', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India (ASCI)', 'Cultivator, Crop', 'Organic Grower (L4), Farm Supervisor / Organic Standards and Quality Supervisor (L5)', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"120","Practical":"150","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "137", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-AG-03554-2025-V2-ASCI', 'Agri Service Input Dealer', 'agriculture', 'Agriculture', 5.0, 'An Agri-Input Dealer is responsible for making various agricultural inputs available to farmers according to the season and advising them on good farming practices such as integrated nutrient management, integrated pest management, irrigation systems, use of farm implements and machineries', 480, 480, '401–600', 'Version', '18 Feb 2025', '18 Feb 2028', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India (ASCI)', 'Sales Workers not elsewhere classified', 'Agri Service input Dealer (L5), Agri-Clinic & Agri-Business Centre Manager (L6)', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"120","Practical":"150","EmployabilitySkills":"90","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "138", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-AG-03552-2025-V2-ASCI', 'Agriculture Extension Service Provider', 'agriculture', 'Agriculture', 4.0, 'An Agriculture Extension Service Provider is responsible for conducting training sessions and demonstrations for farmers to explain various agricultural practices and use of a variety of agricultural machineries, tools, implements and equipment. The individual assists the farmers in establishing forward and backward linkages and increase agricultural production.', 390, 420, '401–600', 'Version', '18 Feb 2025', '18 Feb 2028', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Extension Service Provider', 'Agriculture Extension Service Provider (L4), Agri Service Input Dealer (L5)', 'Apprenticeship Qualification,Future Skills Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"105","Practical":"165","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "139", "qualification_type": "Apprenticeship Qualification,Future Skills Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-AG-03553-2025-V2-ASCI', 'Agriculture Field Officer', 'agriculture', 'Agriculture', 4.0, 'An Agriculture Field Officer is responsible for promoting relevant agricultural loan and insurance products to farmers. The individual identifies and connects with the potential borrowers; determines their eligibility; collects required information and documents for the loan application and coordinates with the credit officer for the processing of the loan application. The person is also responsible for monitoring the repayments, coordinating with farmers to ensure timely repayments, and carrying out appropriate documentation during the loan cycle. Coordinating timely insurance premium payments and insurance claim settlements are also individual’s responsibilities.', 390, 390, '201–400', 'Version', '18 Feb 2025', '18 Feb 2028', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Field Officer', 'Agriculture Field Officer (L4), Agri Service Input Dealer (L5)', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"120","Practical":"180","EmployabilitySkills":"60","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "140", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-AG-03535-2025-V2-ASCI', 'Cotton Cultivator', 'agriculture', 'Agriculture', 3.0, 'A Cotton Cultivator undertakes the cultivation of cotton crops and performs various activities such as selecting and preparing the farm, procuring, treating and sowing the cotton seeds. The individual is also responsible for maintaining the cotton crop, harvesting and marketing it.', 270, 270, '201–400', 'Version', '18 Feb 2025', '18 Feb 2028', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India (ASCI)', 'Cotton Cultivator', 'Cotton Cultivator (L3), Cotton Cultivator cum Ginner/ Organic Grower (L4)', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"90","Practical":"150","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "141", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-AG-03538-2025-V2-ASCI', 'Medicinal and Aromatic Plants Grower', 'agriculture', 'Agriculture', 4.0, 'A Medicinal and Aromatic Plants (MAPs) Grower is responsible for growing medicinal and aromatic plants. In the process, the individual selects a suitable site for cultivation; prepares the site; carries out cultivation and harvests the plants on their maturity. The person also performs post- harvest processing of MAPs including cleaning, packing and labelling.', 390, 390, '201–400', 'Version', '18 Feb 2025', '18 Feb 2028', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India (ASCI)', 'Medicinal and Aromatic Plant Cultivators', 'Medicinal and Aromatic Plants Grower (L4), Farm Supervisor (L5)', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"120","Practical":"180","EmployabilitySkills":"60","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "142", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-AG-03534-2025-V2-ASCI', 'Cereal Crop Cultivator', 'agriculture', 'Agriculture', 3.0, 'A Cereal Crop Cultivator cultivates varieties of cereal crops as per the package of practices recommended for a particular cereal crop and agro climate zone to achieve yields as per the genetic potential of a given variety. The individual is also responsible for harvesting and marketing the produce.', 300, 390, '201–400', 'Version', '18 Feb 2025', '18 Feb 2028', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India (ASCI)', 'Cultivator, Crop', 'Cereal Crop Cultivator (L3), Organic Grower (L4)', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"120","Practical":"150","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "143", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-AG-03545-2025-V2-ASCI', 'Brackish water Aquaculture Farmer', 'agriculture', 'Agriculture', 4.0, 'A Brackish water Aquaculture Farmer is responsible for setting up a brackish water aquaculture farm, stocking, rearing and harvesting brackish water organisms such as fish and crustaceans. The person is also responsible for sorting, grading and marketing them.', 390, 450, '401–600', 'Version', '18 Feb 2025', '18 Feb 2028', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India (ASCI)', 'Pisciculturist', 'Brackish water Aquaculture Farmer (L4), Aquaculture Technician Supervisor (L5)', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"90","Practical":"180","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "144", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-AG-03542-2025-V2-ASCI', 'Floriculturist', 'agriculture', 'Agriculture', 4.0, 'A Floriculturist performs various activities in the process of cultivating flower crop such as selecting the site; preparing the field; propagating saplings in the nursery; transplanting the sapling, and maintaining the plants. The person is also responsible for carrying out harvesting, post-harvesting processing and marketing of the flower crop.', 390, 630, '601–800', 'Version', '18 Feb 2025', '18 Feb 2028', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India (ASCI)', 'Floriculturist- (Open Cultivation)', 'Floriculturist (L4), Horticulture Supervisor (L5)', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"120","Practical":"180","EmployabilitySkills":"60","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "145", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-AG-03537-2025-V2-ASCI', 'Pulses Cultivator', 'agriculture', 'Agriculture', 3.0, 'A Pulses Cultivator undertakes the cultivation of pulses at the farm level. The individual is also responsible for harvesting and marketing the pulses. The person also undertakes integrated pest and disease management, along with weed management as part of the job role.', 270, 270, '201–400', 'Version', '18 Feb 2025', '18 Feb 2028', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India (ASCI)', 'Pulses Cultivator', 'Pulses Cultivator (L3), Organic grower (L4)', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"100","Practical":"140","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "146", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-AG-03539-2025-V2-ASCI', 'Oilseed Crop Grower', 'agriculture', 'Agriculture', 4.0, 'An Oilseed Crop Grower is responsible for cultivating varieties of oilseed and performs macro and micronutrient management along with pest and disease management in the process. The individual is also responsible for harvesting, processing and marketing oilseeds', 390, 510, '401–600', 'Version', '18 Feb 2025', '18 Feb 2026', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India', 'Field Crop and Vegetable Growers, Other', 'Oilseed Crop Grower (L4), Farm Supervisor (L5)', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"120","Practical":"180","EmployabilitySkills":"60","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "147", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-AG-03548-2025-V2-ASCI', 'Vermicompost Producer', 'agriculture', 'Agriculture', 3.0, 'The individual is expected to be competent in producing good quality vermicompost using correct species of earthworms, materials, vermicomposting techniques in appropriate site/location. The individual also undertakes basic entrepreneurial activities for small enterprise and sell the produced compost as per the competitive market prices', 270, 270, '201–400', 'Version', '18 Feb 2025', '18 Feb 2028', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India (ASCI)', 'Farm Management (Field Crop and Vegetable Growers, Other)', 'Vermicompost Producer (L3), Organic Grower (L4)', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"90","Practical":"120","EmployabilitySkills":"60","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "148", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-AG-03532-2025-V2-ASCI', 'Soil & Water Testing Lab Technician', 'agriculture', 'Agriculture', 4.0, 'The individual is responsible for cleaning of laboratory equipment utilizing proper cleaning protocols and procedures, processing soil, manure/ compost, plant and water samples for testing and maintaining records, preparation of chemical solutions used in the laboratory, data entry and dissemination of soil and water health cards. The person may conduct soil testing on farm field using the soil testing kit. The individual may also collect, label and dispatch soil and water samples to the Soil & Water Testing Lab for analysis.', 390, 390, '201–400', 'Version', '18 Feb 2025', '18 Feb 2026', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India (ASCI)', 'Laboratory Assistant, Soil', 'Soil & Water Testing Lab Technician (L4), Soil & Water Testing Lab Analyst (L5)', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"90","Practical":"150","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "149", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-AG-03550-2025-V2-ASCI', 'Packhouse Worker', 'agriculture', 'Agriculture', 3.0, 'A Packhouse Worker performs a number of activities at a packhouse such as unloading, washing,	sorting, ripening, grading and storing different types of horticultural produce. The person also de-greens citrus produce, packs, weighs and loads different types of produce for shipping.', 270, 270, '201–400', 'Version', '18 Feb 2025', '18 Feb 2028', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India (ASCI)', 'Post-Harvest Supply Chain Management (Supervisor and Foreman, Checking, Sorting, Packing and Related Activities)', 'Packhouse worker (L3), Ripening Chamber Technician (L4)', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"90","Practical":"150","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "150", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-AG-03536-2025-V2-ASCI', 'Solanaceous Crop Cultivator', 'agriculture', 'Agriculture', 3.0, 'The job of the Solanaceous Crop Cultivator involves cultivation of solanaceous crop as per the package of 
practices recommended for a particular agronomic climate zone, type of soil, rainfall pattern and climatic 
condition to achieve the yield as per the genetic potential of given variety and sell the produce as per the 
competitive market prices without distress sale.', 270, 270, '201–400', 'Version', '18 Feb 2025', '18 Feb 2028', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India', 'Vegetable Crops Cultivation', 'Solanaceous Crop Cultivator (L3), Vegetable Grower (L4)', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"90","Practical":"150","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "151", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-AG-03272-2024-V2-ASCI', 'Vegetable Grower', 'agriculture', 'Agriculture', 4.0, 'A vegetable grower carries out various activities in a farm for cultivation of vegetables, which include preparation of farm for cultivation, planting of seedlings, maintenance of the crop, harvesting and marketing of produce.', 390, 540, '401–600', 'Version', '22 Oct 2024', '22 Oct 2027', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India (ASCI)', 'Cultivator, Vegetables (Vegetable Crops Cultivation)', 'Vegetable grower (L4), Horticulture Farm Supervisor (L5)', 'General Qualification', 'N.A.', '{"Theory":"90","Practical":"180","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "152", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-AG-03905-2025-V2-ASCI', 'Sugarcane Cultivator', 'agriculture', 'Agriculture', 3.0, 'The sugarcane cultivator undertakes the cultivation of sugarcane crop at the farm level. The individual is also responsible for harvesting and marketing the sugarcane crop. The person undertakes integrated pest and disease management, along with weed management as part of the job role.', 270, 270, '201–400', 'Version', '08 May 2025', '08 May 2028', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India', 'Sugarcane Cultivator', 'Sugarcane cultivator (L3), Sugarcane Grower cum Miller (L4)', 'Apprenticeship Qualification,General Qualification', 'N.A.', '{"Theory":"90","Practical":"150","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "153", "qualification_type": "Apprenticeship Qualification,General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-AG-03914-2025-V2-ASCI', 'Chilling Plant Technician', 'agriculture', 'Agriculture', 4.0, 'A Chilling Plant Technician performs work in the repair, maintenance, service, modification,
 troubleshooting, inspection and monitoring of the operation of the chilling system used for chilling milk.', 390, 390, '201–400', 'Version', '08 May 2025', '08 May 2028', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India', 'Food and Related Products Machine Operators', 'Chilling Plant Technician (L4), Milk Procurement & Input Supervisor(L5)', 'Apprenticeship Qualification,General Qualification', 'N.A.', '{"Theory":"90","Practical":"120","EmployabilitySkills":"60","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "154", "qualification_type": "Apprenticeship Qualification,General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-AG-03907-2025-V2-ASCI', 'Bulk Milk Cooler (BMC) Operator', 'agriculture', 'Agriculture', 4.0, 'A Bulk Milk Cooler (BMC) Operator is responsible for operating a large storage tank used for cooling and holding milk at a certain temperature until it can be picked up by a milk hauler.', 390, 390, '201–400', 'Version', '06 Jun 2025', '30 Apr 2028', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India', 'Operator, Farm Machines', 'Milk Procurement & Input Supervisor(L5)', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"90","Practical":"150","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "155", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-2.5-AG-03906-2025-V2-ASCI', 'Tea Plantation Worker', 'agriculture', 'Agriculture', 2.5, 'A Tea Plantation Worker is responsible for assisting in carrying out tea cultivation. It includes assisting in nursery and field preparation, assisting in propagating saplings in the nursery, transplanting the saplings, and maintaining and also post- harvest processing of tea crop.', 240, 240, '201–400', 'Version', '08 May 2025', '30 Apr 2028', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India', 'Tea Plantation Worker', 'Tea Plantation Worker(L2.5), Tea Grower (Small Entrepreneur) (L3)', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"80","Practical":"130","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "156", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-04-AG-04181-2025-V1-ASCI', 'Fundamentals of Animal Vaccination', 'agriculture', 'Agriculture', 4.0, 'This OS unit is about practicing vaccination in livestock, promotion of animal health, and delivering effective livestock extension services by paraprofessionals. It also emphasizes on disease prevention, reducing antimicrobial resistance, and minimizing zoonotic disease risks. Additionally, it also covers communication skills, workplace resilience, and collaboration with livestock health partners for improved animal care and productivity.', 30, 30, '1–200', 'Version', '08 May 2025', '08 May 2028', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India', 'NIL', 'NIL', 'General Qualification,Micro Credentials,Upskilling Qualification', 'N.A.', '{"Theory":"20","Practical":"10","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "157", "qualification_type": "General Qualification,Micro Credentials,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-AG-03920-2025-V2-ASCI', 'Inland Capture Fisherman cum Primary Processor', 'agriculture', 'Agriculture', 3.0, 'An Inland Capture Fisherman cum Primary Processor is responsible for capturing different species of fish in 
inland water bodies such as rivers and lakes and carrying out primary fish processing. The individual is also 
responsible for using and maintaining the fishing craft and gear along with other equipment used in inland 
capture fisheries. The person may also prepare fish-based products.', 270, 270, '201–400', 'Version', '08 May 2025', '30 Apr 2028', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India', 'Fisherman, Inland Water', 'Inland Capture Fisherman cum Primary Processor (L3), Freshwater aquaculture Farmer (L4)', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"60","Practical":"150","EmployabilitySkills":"60","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "158", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-AG-03918-2025-V2-ASCI', 'Marine Capture Fisherman cum Primary Processor', 'agriculture', 'Agriculture', 3.0, 'A Marine Fisher cum Primary Processor is responsible for capturing a variety of marine fish. The individual 
uses and maintains the relevant equipment and boat/vessel during the operations. The person is also 
responsible for maintaining the quality of the captured fish and marketing it.', 270, 270, '201–400', 'Version', '08 May 2025', '30 Apr 2028', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India', 'Fisherman, Deep Sea/Marine Capture Fisherman', 'Deep Sea Fisher (L4)', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"70","Practical":"140","EmployabilitySkills":"60","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "159", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-AG-03908-2025-V2-ASCI', 'Mariculture Farmer', 'agriculture', 'Agriculture', 4.0, 'A Mariculture Farmer is responsible for managing the overall operations of a mariculture farm including the fabrication and installation of pens/ rafts/ cages, procuring and stocking seeds, maintaining the stocked organisms and harvesting them on maturity. The person may also carry out pearl culture to produce pearls by rearing pearl oysters.', 390, 450, '401–600', 'Version', '08 May 2025', '08 May 2028', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India', 'Aquaculture Workers', 'Mariculture Farmer (L4), Aquaculture Technical Supervisor (L5)', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"90","Practical":"180","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "160", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-AG-03921-2025-V2-ASCI', 'Deep Sea Fisher', 'agriculture', 'Agriculture', 4.0, 'A Deep Sea Fisher captures fish in the deep sea within the Exclusive Economic Zone (EEZ) on mechanized vessels of size less than 24m overall length (OAL). The Deep Sea Fisher is also responsible for processing and storing fish so that spoilage can be reduced and the best fish is provided to the customer.', 390, 390, '201–400', 'Version', '08 May 2025', '08 May 2028', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill council of India', 'Fisherman, Deep Sea/Marine Capture Fisherman', 'Deep Sea Fisher (L4), Marine fishing cadet (L5)', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"90","Practical":"120","EmployabilitySkills":"60","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "161", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-AG-03919-2025-V2-ASCI', 'Fishing Boat Driver (Small Mechanized vessel)', 'agriculture', 'Agriculture', 4.0, 'A Fishing Boat Driver (Small Mechanized Vessel) is responsible for steering the small mechanised 
boat in the sea. The individual follows the planned route to navigate between the harbour and  identified fishing location. The person also prepares the boat for fishing operation and carries out  its minor repair and maintenance.', 390, 390, '201–400', 'Version', '08 May 2025', '08 May 2028', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India', 'Inland and Coastal Water Fishery Workers, Other', 'Fishing Boat Driver (Small Mechanized vessels) (L4), Marine fishing cadet (L5)', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"60","Practical":"150","EmployabilitySkills":"60","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "162", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-AG-00289-2025-V2-ASCI', 'Hydroponics Technician', 'agriculture', 'Agriculture', 4.0, 'A Hydroponics Technician grows plants in a controlled environment using alternative materials 
instead of soil as per the hydroponics farming method. The individual is also responsible for setting 
and maintaining a hydroponic farm apart from maintaining, harvesting and marketing the plants 
grown at the farm.', 390, 390, '201–400', 'Version', '08 May 2025', '08 May 2028', 'Agriculture Skill Council of India (ASCI)', 'Agriculture Skill Council of India', 'Agricultural Technicians, Others', 'Hydroponics Technician(L4), Horticulture Supervisor (Garden/Nursery/ Turf) (L5)', 'Apprenticeship Qualification,Future Skills Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"90","Practical":"120","EmployabilitySkills":"60","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "163", "qualification_type": "Apprenticeship Qualification,Future Skills Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
