INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-2.5-AP-01870-2024-V1.1-AMHSSC', 'Washing Machine Operator', 'apparel', 'Apparel', 2.5, 'Washing Machine Operator is responsible to perform various types of washings for apparel and garments, made ups and home furnishing articles. The washings are intended to achieve desired finish reflected in terms of improved performance, cleanliness, luster, feel, drape, softness with combinations of time, temperature, process conditions and chemical formulations specific to product class. The operator should be able to interpret and understand technical specifications and ensure correct wash cycle is used for product type.', 300, 300, '201–400', 'Version', '17 Nov 2022', '01 Nov 2026', 'Apparel, Madeups & HomeFurnishing Sector Skill Council (AMHSSC)', 'Apparel, Made-ups & Home Furnishing Sector Skill Council', 'Sampling', 'Processing Supervisor- Dyeing and Printing', 'General Qualification', 'N.A.', '{"Theory":"78","Practical":"192","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "3", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_12.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-2.5-AP-01869-2024-V1.1-AMHSSC', 'Finisher and Packer', 'apparel', 'Apparel', 2.5, 'Finisher & Packer is responsible for monitoring production, quality and delivery of Packed products ready to dispatch while maintaining the quality parameters as per priority and specifications. The operation consists of finishing & packaging process activities from Checking, Ironing, folding, inner packing, outer packing, labeling, marking, inner layer etc.  To finally packed in carton or as special instruction defined by buyer.', 300, 300, '201–400', 'Version', '17 Nov 2022', '01 Nov 2026', 'Apparel, Madeups & HomeFurnishing Sector Skill Council (AMHSSC)', 'Apparel, Made-ups & Home Furnishing Sector Skill Council', 'Finisher & Packer', 'Washing Machine Operator (Horizontal)', 'General Qualification', 'N.A.', '{"Theory":"108","Practical":"162","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "4", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_12.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-02-AP-01865-2024-V1.1-AMHSSC , Version 4.0', 'Hand Embroiderer (Addawala)', 'apparel', 'Apparel', 2.0, 'A Hand Embroiderer and/or an Addawala embroider decorative designs as per the tracings or customer requirements on fabric & other materials by hand, using needle & thread. The hand embroiderer uses a variety of sewing techniques to create different kinds of embroidery stitches & effects such as Cross stitch, French knot stitch, Bullion knot stitch, Shade work, Applique work, English Smocking etc. The job requires the hand embroiderer to have the skills to stitch a variety of stitches with precision and accuracy to obtain the desired look.', 270, 270, '201–400', 'Version', '17 Nov 2022', '01 Nov 2026', 'Apparel, Madeups & HomeFurnishing Sector Skill Council (AMHSSC)', 'Apparel, Made-ups & Home Furnishing Sector Skill Council
3rd floor, Flat No. A-312 To A-323, Somdatt Chamber-I,
Bhikaji Cama Place, 
Africa Avenue,
New Delhi - 110066

Mr. Amit Singh and Ms. Priya Mathur 
	jdqs@sscamh.com, jdqs1@sscamh.com', 'Hand Embroidery(Addawala)', 'Vertical -  Embroidery Machine Operator (Zigzag Machine)', 'General Qualification', 'N.A.', '{"Theory":"78","Practical":"162","EmployabilitySkills":"30","OJT_Mandatory":"00"}', false, '{}'::text[], '{"source_row": "5", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_12.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-2.5-AP-01866-2024-V1.1-AMHSSC, Version 4.0', 'Sewing Machine Operator', 'apparel', 'Apparel', 2.5, 'A Sewing Machine Operator also called a Stitcher or Machinist is an important job-role associated with Apparel sector, Made-Ups and Home Furnishing Industry. The primary responsibility of a machinist is to stitch/ sew fabric panels, fur fabric panels, or synthetic materials to produce apparels or made up with desired quality.', 300, 300, '201–400', 'Version', '17 Nov 2022', '01 Nov 2026', 'Apparel, Madeups & HomeFurnishing Sector Skill Council (AMHSSC)', 'A Sewing Machine Operator also called a Stitcher or Machinist is an important job-role associated with Apparel sector, Made-Ups and Home Furnishing Industry. The primary responsibility of a machinist is to stitch/ sew fabric panels, fur fabric panels, or synthetic materials to produce', 'Sewing', 'Vertical - Specialized Sewing Machine Operator', 'General Qualification', 'N.A.', '{"Theory":"78","Practical":"192","EmployabilitySkills":"30","OJT_Mandatory":"00"}', false, '{}'::text[], '{"source_row": "6", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_12.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
