INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-03-AP-02338-2024-V1-AMHSSC', 'Darzi - Advanced', 'apparel', 'Apparel', 3.0, 'Darzi is a skilled tailor versed with making customized various types of dresses. The job thus involves taking measurement, cutting fabric as per measurement and sewing with the help of ordinary sewing machines. The person also does alteration works of stitched dress materials to correct and fit as per customer requirements. Further with PM Vishwakarma scheme the aim is to achieve Up gradation of Vishwakarmas to power tools for Darzi and to provide support to enhance the capacity, productivity and quality of products.', 120, 120, '1–200', 'Version', '15 Mar 2024', '15 Mar 2027', 'Apparel, Madeups & HomeFurnishing Sector Skill Council (AMHSSC)', 'Apparel, Made-ups & Home Furnishing Sector Skill Council
Submitting Body Contact Details- Mr. Amit Singh and Ms. Priya Mathur 
jdqs@sscamh.com, jdqs1@sscamh.com', 'N/A', 'N/A', 'General Qualification', 'N.A.', '{"Theory":"120","Practical":"00","EmployabilitySkills":"00","OJT_Mandatory":"00"}', false, '{}'::text[], '{"source_row": "10", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_12.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-AP-01772-2024-V1.1-AMHSSC,  Version 3.0', 'Advance Pattern Maker (CAD/CAM)', 'apparel', 'Apparel', 5.0, 'The advance pattern maker uses the CAD system to recreate the pattern design techniques by transferring ideas to the computer, digitizing and modifying patterns and also using the CAM to get the patterns and lays cut out in the actual sizes', 510, 510, '401–600', 'Version', '30 Dec 2021', '30 Dec 2024', 'Apparel, Madeups & HomeFurnishing Sector Skill Council (AMHSSC)', 'Apparel, Made-ups & Home Furnishing Sector Skill Council', 'Pattern Making', 'Production Manager', 'General Qualification', 'N.A.', '{"Theory":"156","Practical":"294","EmployabilitySkills":"60","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "11", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_12.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-AP-01779-2024-V1.1-AMHSSC,  Version 3.0', 'Factory Compliance Auditor', 'apparel', 'Apparel', 5.0, 'A Factory Compliance Auditor is responsible for conducting regular audits in the apparel factory to check if the unit is functioning in accordance to the industry regulations, standards and policies. The Compliance Auditor prepares a detailed report of the audit findings with remarks on system adequacy, system conformance or deviation if any, and overall system performance. He/she is responsible for helping protect the organization''s assets by conducting internal audits and inspections to ensure that the equipment and operations are in compliance with laws, corporate guidelines, best practices, and contractual agreements.', 540, 540, '401–600', 'Version', '30 Sep 2021', '30 Sep 2024', 'Apparel, Madeups & HomeFurnishing Sector Skill Council (AMHSSC)', 'Apparel, Made-ups & Home Furnishing Sector Skill Council', 'Finishing', 'Compliance Manager', 'General Qualification', 'N.A.', '{"Theory":"186","Practical":"294","EmployabilitySkills":"60","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "12", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_12.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-AP-03234-2024-V1-UPSCVT', 'Chikankari & Zardosi Artisan', 'apparel', 'Apparel', 3.0, 'Chikankari artisanship requires mastery of various hand embroidery stitches, fabric knowledge, design interpretation, color theory, quality control, cultural appreciation, and adaptability. Key competencies include mastery of various stitches, understanding of fabrics, ability to replicate traditional designs, understanding color combinations, and ensuring high-quality craftsmanship. Cultural appreciation and adaptability are also essential. Qualifying often involves apprenticeship under experienced karigars or formal training programs and workshops. This traditional embroidery art form is a culturally significant and adaptable art form.', 600, 600, '401–600', 'Version', '25 Jul 2024', '24 Jul 2027', 'State Council of Vocational Training (SCVT)', 'State Council for Vocational Training, U.P.', 'N/A', 'Craftsman', 'General Qualification', 'N.A.', '{"Theory":"120","Practical":"330","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "13", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_12.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-02-AP-03279-2024-V2-AMHSSC', 'Layerman (Fabric)', 'apparel', 'Apparel', 2.0, 'A Layerman (Fabric) is employed in the pre-production side of manufacturing. The key responsibility of a Layerman (Fabric) is to inspect the fabric to identify the presence of any basic fabric faults: and carry out laying and cutting of the fabric as per specified length for garment production.', 240, 240, '201–400', 'Version', '22 Oct 2024', '22 Oct 2027', 'Apparel, Madeups & HomeFurnishing Sector Skill Council (AMHSSC)', 'AMHSSC', 'Laying', 'Fabric Checker', 'General Qualification', 'N.A.', '{"Theory":"78","Practical":"102","EmployabilitySkills":"30","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "14", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_12.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-2.5-AP-03283-2024-V2-AMHSSC', 'Pressman - Stitched Items', 'apparel', 'Apparel', 2.5, 'A pressman-stitched Item also called an Ironer, irons garment components and finished garments. The primary responsibility of a pressman-stitched Item is to iron the garments and fold them according to customer specifications.', 300, 300, '201–400', 'Version', '22 Oct 2024', '22 Oct 2027', 'Apparel, Madeups & HomeFurnishing Sector Skill Council (AMHSSC)', 'AMHSSC', 'Ironing', 'Finisher and Packer', 'General Qualification', 'N.A.', '{"Theory":"78","Practical":"162","EmployabilitySkills":"30","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "15", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_12.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-AP-03282-2024-V2-AMHSSC', 'Pattern Master - Apparel', 'apparel', 'Apparel', 4.0, 'Pattern Master - Apparel uses ordinary and basic hand operated equipment and tools for measuring, marking and cutting to create patterns on non- textile cheaper substrate (usually hard paper board) for each size within given range of apparel and/or garment design, made ups and home furnishing articles. A complete pattern consists of various components cut to size and thus a full pattern for a particular garment, made ups and home furnishing article comprises various shapes and sizes of paper boards cut and preserved as set. The Pattern Master - Apparel must be able to read and interpret design details and create pattern as per final product requirements.', 420, 420, '401–600', 'Version', '22 Oct 2024', '22 Oct 2027', 'Apparel, Madeups & HomeFurnishing Sector Skill Council (AMHSSC)', 'AMHSSC', 'Pattern Making', 'Advanced Pattern Maker', 'General Qualification', 'N.A.', '{"Theory":"96","Practical":"204","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "16", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_12.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-06-AP-03281-2024-V2-AMHSSC', 'Export Manager – Stitched Items', 'apparel', 'Apparel', 6.0, 'An Export Manager - Stitched Items is responsible for leading and managing the entire process of international shipment of goods. Their work includes analysis of the foreign trade logistics, management and supervision of all shipment related documents and ensuring shipping compliance. The Export Manager - Stitched Items is a key member of the organization and will expect to be a great communicator together with the ability to establish and maintain relationships both internally and externally.', 600, 600, '401–600', 'Version', '22 Oct 2024', '22 Oct 2027', 'Apparel, Madeups & HomeFurnishing Sector Skill Council (AMHSSC)', 'AMHSSC', 'Export Operations', 'Sourcing Manager', 'General Qualification', 'N.A.', '{"Theory":"174","Practical":"276","EmployabilitySkills":"90","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "17", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_12.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-06-AP-03284-2024-V2-AMHSSC', 'Sourcing Manager - Stitched Items', 'apparel', 'Apparel', 6.0, 'Sourcing Manager - Stitched Items in an apparel, made-ups and home furnishing industry is primarily concerned with procurement of fabrics, trims & accessories as per design needs and/or as per sample requirements received from merchandiser. The role is supervising the functionary of purchase departments. He/she is concerned with identifying suitable suppliers for materials assessed on the basis of price, quality, reliability, time and long-term business relations. He/ She must supervise all negotiations and prepare appropriate documents for same', 600, 600, '401–600', 'Version', '22 Oct 2024', '22 Oct 2027', 'Apparel, Madeups & HomeFurnishing Sector Skill Council (AMHSSC)', 'AMHSSC', 'Merchandising', 'General Manager Sourcing', 'General Qualification', 'N.A.', '{"Theory":"174","Practical":"276","EmployabilitySkills":"90","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "18", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_12.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-06-AP-03280-2024-V2-AMHSSC', 'Boutique Manager', 'apparel', 'Apparel', 6.0, 'Boutique Manager is a skilled designer with business acumen for managing shop to make fashion wear, made ups and home furnishings. The job involves thorough understanding of designs, being aware of latest trends, ability to convince clients for a design, capable of pattern making and skilled in stitching. Boutique manager also motivate and inspire their team to achieve productivity and sales goals to assure a great customer experience and optimum profitability', 600, 600, '401–600', 'Version', '22 Oct 2024', '22 Oct 2027', 'Apparel, Madeups & HomeFurnishing Sector Skill Council (AMHSSC)', 'AMHSSC', 'Boutique Operations', 'BOUTIQUE MANAGER (ENTREPRENEURSHIP )', 'General Qualification', 'N.A.', '{"Theory":"144","Practical":"306","EmployabilitySkills":"90","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "19", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_12.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-AP-03278-2024-V2-AMHSSC', 'Cutting Supervisor-(Fabric)', 'apparel', 'Apparel', 5.0, 'Cutting Supervisor(Fabric) is responsible for monitoring cutting operations, quality and smooth running of cutting processes with junior management cadres working as a team. He/she needs to supervise and coordinate activities of workers engaged in cutting fabric as per buyer specifications.', 510, 510, '401–600', 'Version', '22 Oct 2024', '22 Oct 2027', 'Apparel, Madeups & HomeFurnishing Sector Skill Council (AMHSSC)', 'AMHSSC', 'Department Supervisor', 'Cutting Manager', 'General Qualification', 'N.A.', '{"Theory":"126","Practical":"264","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "20", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_12.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-AP-03220-2024-V2-DGT', 'COMPUTER AIDED EMBROIDERY & DESIGN', 'apparel', 'Apparel', 4.0, 'The individual will be able to impart theoretical instructions, demonstrate practical skills, evaluate and grade trainees of Computer Aided Embroidery & designing CITS) trade in industrial workshops, ITIs/Vocational Training Institutes etc.', 1350, 1350, '1201–2400', 'Version', '22 Oct 2024', '21 Oct 2027', 'Directorate General of Training (DGT)', 'DGT', 'Manual Training Teacher/ Craft Instructor, Framer-Computerized Embroidery Machine, Sewers, Embroiderers and Related Workers, Other', 'Technical Instructor in a vocational training Institute/ technical Institution, Supervisor in Industries', 'General Qualification', 'N.A.', '{"Theory":"450","Practical":"750","EmployabilitySkills":"0","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "21", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_12.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
