INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-AP-01773-2024-V2-AMHSSC', 'Fashion Designer', 'apparel', 'Apparel', 5.0, 'Fashion designers are the creative visionaries behind new clothing lines, collections, and trends and have the skills and knowledge to develop fashion design briefs and manage the development of design concepts for commercial production.', 570, 570, '401–600', 'Version', '17 Dec 2024', '17 Dec 2027', 'Apparel, Madeups & HomeFurnishing Sector Skill Council (AMHSSC)', 'Apparel Made-ups and Home Furnishings Sector Skill Council', 'Designing', 'Fashion Buyer (Vertical)', 'General Qualification', 'N.A.', '{"Theory":"156","Practical":"294","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "26", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_12.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-AP-01777-2024-V2-AMHSSC', 'Production Supervisor- Sewing', 'apparel', 'Apparel', 5.0, 'A Production Supervisor-Sewing guides activities of operators and/or other employees engaged in the process of manufacturing, inspection, processing and related activity. Production Supervisor plans and allocates resources and monitors schedules.', 570, 570, '401–600', 'Version', '17 Dec 2024', '17 Dec 2027', 'Apparel, Madeups & HomeFurnishing Sector Skill Council (AMHSSC)', 'AMHSSC', 'Department Supervision', 'QC Executive - Sewing Line (Horizontal)
Production Manager (Vertical)', 'General Qualification', 'N.A.', '{"Theory":"156","Practical":"294","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "27", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_12.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-AP-03425-2024-V1-WBSC', 'Garment Maker', 'apparel', 'Apparel', 3.0, 'The Garment Maker is responsible for the end-to-end process of garment production from material selection to final quality checks. This role requires proficiency in sewing techniques, pattern drafting and cost estimation to ensure high-quality finished products that meet design specifications.', 390, 510, '401–600', 'Version', '17 Dec 2024', '16 Dec 2027', 'West Bengal State Council of Technical & Vocational Education and Skill Development (WBSCTVESD)', 'West Bengal State Council of Technical & Vocational Education and Skill Development', 'Garment Maker', 'Specialized Sewing Machine Operator', 'General Qualification', 'N.A.', '{"Theory":"70","Practical":"230","EmployabilitySkills":"30","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "28", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_12.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-2.5-AP-03424-2024-V2-RUDSETI', 'Tailor', 'apparel', 'Apparel', 2.5, 'This program aims to foster self-employment opportunities in the field of dressmaking. By equipping rural youth with the necessary skills and knowledge, this program empowers them to become successful entrepreneurs in the apparel industry.

Anticipating a rising demand for these tailors, even in rural areas and small towns, this program prepares participants to establish their own ventures, such as tailoring shops, stitching units and boutiques, upon successful completion and certification.', 240, 330, '201–400', 'Version', '03 Mar 2017', '17 Dec 2027', 'National Academy of RUDSETI, Karnataka', 'NCVET', 'Tailor', 'Master Tailor, Custom Tailor, Tailoring Instructor, Costume Designer, Entrepreneur', 'General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"60","Practical":"120","EmployabilitySkills":"30","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "29", "qualification_type": "General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_12.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-AP-01767-2024-V2-AMHSSC', 'Sampling Tailor', 'apparel', 'Apparel', 4.0, 'A sampling tailor is responsible for developing garment sample as per buyers’ specifications in the apparel industry. A sampling tailor should be able to perform basic fabric cutting operations and stitch garments of various designs with different necklines, sleeves, collar etc. as per the quality standards. This job requires the individual to have thorough knowledge of measurements, garment styles and components, sampling & apparel production processes and should be able to sew garments with different materials & trims.', 420, 420, '401–600', 'Version', '18 Feb 2025', '18 Feb 2028', 'Apparel, Madeups & HomeFurnishing Sector Skill Council (AMHSSC)', 'Apparel, Made-ups & Home Furnishing Sector Skill Council', 'Tailoring', 'Sampling Coordinator (Vertical)
Specialized Sewing Machine Operator (Horizontal)', 'General Qualification', 'N.A.', '{"Theory":"96","Practical":"234","EmployabilitySkills":"60","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "30", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_12.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-AP-03568-2025-V2-AMHSSC', 'Advance Pattern Maker (CAD/CAM)', 'apparel', 'Apparel', 5.0, 'The advance pattern maker uses the CAD system to recreate the pattern design techniques by transferring ideas to the computer, digitizing and modifying patterns and also using the CAM to get the patterns and lays cut out in the actual sizes', 510, 510, '401–600', 'Version', '18 Feb 2025', '18 Feb 2028', 'Apparel, Madeups & HomeFurnishing Sector Skill Council (AMHSSC)', 'Apparel, Made-ups & Home Furnishing Sector Skill Council', 'Pattern Making', 'Production Manager', 'General Qualification', 'N.A.', '{"Theory":"96","Practical":"294","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "31", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_12.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-AP-03578-2025-V2-AMHSSC', 'QC Executive - Stitched Items', 'apparel', 'Apparel', 5.0, 'QC Executive is responsible for ensuring that physical inspections are conducted at all stages of production to secure quality and check that all technical details are received; verified & signed off prior to starting production. QC executive also establishes quality plans, parameters and inspection systems, records deviations and sends feedback to the concerned department. He/ she oversees all aspects of sewing related quality control function and ensures product meets organizational standards and buyer requirements.', 570, 570, '401–600', 'Version', '18 Feb 2025', '18 Feb 2028', 'Apparel, Madeups & HomeFurnishing Sector Skill Council (AMHSSC)', 'Apparel, Made-ups & Home Furnishing Sector Skill Council', 'Quality Control', 'Quality Manager', 'General Qualification', 'N.A.', '{"Theory":"156","Practical":"294","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "32", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_12.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-AP-03569-2025-V2-AMHSSC', 'Assistant Designer- Apparel, Home and Made ups', 'apparel', 'Apparel', 4.0, 'The assistant designer primarily aids the fashion designer in creation of design range. He/she does hands on work to turn ideas into actual products. Some of their duties involve market study, perceiving trends underline, predict and forecast trends setting in for forthcoming season, identify theme, create mood board based on theme, develop designs for entire range of products in relation to the theme and subsequently to generate techpack for each style within the range of products. Finally, to work with team to develop a prototype based on techpack.', 420, 420, '401–600', 'Version', '18 Feb 2025', '18 Feb 2028', 'Apparel, Madeups & HomeFurnishing Sector Skill Council (AMHSSC)', 'Apparel, Made-ups & Home Furnishing Sector Skill Council', 'Designing', 'Fashion Designer (Vertical) 
Sampling Tailor (Horizontal)', 'General Qualification', 'N.A.', '{"Theory":"96","Practical":"204","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "33", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_12.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-AP-03571-2025-V2-AMHSSC', 'Embroidery Machine Operator', 'apparel', 'Apparel', 3.0, 'An Embroidery Machine Operator is responsible for operating the embroidery machine to embroider decorative designs on fabric/garments in the apparel industry. The embroidery machine operator must be able to perform different kinds of stitches and decorative work such as running shade work, cording & satin stitch, eyelet work, applique work, shade work and round, cut work and open work, pin stitch & pitch stitch, chain embroidery & fancy embroidery.', 390, 390, '201–400', 'Version', '18 Feb 2025', '18 Feb 2028', 'Apparel, Madeups & HomeFurnishing Sector Skill Council (AMHSSC)', 'Apparel, Made-ups & Home Furnishing Sector Skill Council', 'Machine Embroidery Operation', 'Sampling Coordinator (Embroidery)', 'General Qualification', 'N.A.', '{"Theory":"108","Practical":"222","EmployabilitySkills":"30","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "34", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_12.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-AP-03572-2025-V2-AMHSSC', 'Export Executive-Stitched Items', 'apparel', 'Apparel', 5.0, 'An Export Executive-Stitched Items is responsible for managing all the processes in the export department of a company also plans and coordinates the international shipment of goods. During the course of their work, they may negotiate with a variety of people, such as shippers, agents and vendors, and are expected to have excellent customer service skills in dealing with customers/buyers. Their work includes preparation & management of all shipment related documents, interpret export financing methods and terms of payment, handle the Central Excise/Customs Clearance: Regulations, Procedures and Documentation. An Export Executive-Stitched Items needs to have thorough knowledge of Indian and Foreign trade policies & operations to ensure effective management of the exports business.', 510, 510, '401–600', 'Version', '18 Feb 2025', '18 Feb 2028', 'Apparel, Madeups & HomeFurnishing Sector Skill Council (AMHSSC)', 'Apparel, Made-ups & Home Furnishing Sector Skill Council', 'Export Operations', 'Export Manager', 'General Qualification', 'N.A.', '{"Theory":"246","Practical":"174","EmployabilitySkills":"60","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "35", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_12.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-2.5-AP-03573-2025-V2-AMHSSC', 'Fabric Cutter', 'apparel', 'Apparel', 2.5, 'The Fabric Cutter (apparel, made-ups and home furnishing) is responsible for bulk cutting with precision of fabrics manually or with the help of electrically operated fabric cutter keeping the pattern placement on the marker and various markings and specifications like style number, name, notches, etc. in mind. Effectively and efficiently monitor the entire cutting process as per specifications and standards.', 300, 300, '201–400', 'Version', '18 Feb 2025', '18 Feb 2028', 'Apparel, Madeups & HomeFurnishing Sector Skill Council (AMHSSC)', 'Apparel, Made-ups & Home Furnishing Sector Skill Council', 'Cutting', 'Cutting Supervisor', 'General Qualification', 'N.A.', '{"Theory":"78","Practical":"162","EmployabilitySkills":"30","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "36", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_12.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-06-AP-03574-2025-V2-AMHSSC', 'Factory Compliance Auditor', 'apparel', 'Apparel', 6.0, 'A Factory Compliance Auditor is responsible for conducting regular audits in the apparel factory to check if the unit is functioning in accordance to the industry regulations, standards and policies. The Compliance Auditor prepares a detailed report of the audit findings with remarks on system adequacy, system conformance or deviation if any, and overall system performance. He/she is responsible for helping protect the organization''s assets by conducting internal audits and inspections to ensure that the equipment and operations are in compliance with laws, corporate guidelines, best practices, and contractual agreements.', 600, 600, '401–600', 'Version', '18 Feb 2025', '18 Feb 2028', 'Apparel, Madeups & HomeFurnishing Sector Skill Council (AMHSSC)', 'Apparel, Made-ups & Home Furnishing Sector Skill Council', 'Quality Assessment', 'Compliance Manager', 'General Qualification', 'N.A.', '{"Theory":"174","Practical":"276","EmployabilitySkills":"90","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "37", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_12.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-3.5-AP-03570-2025-V2-AMHSSC', 'Inline Checker - Sewing', 'apparel', 'Apparel', 3.5, 'A checker is an important job-role associated with Apparel sector. The primary responsibility of a checker is to identify the faults in the fabrics, cut components, garment parts or finished products through visual inspection.  As Checker, the individual inspects the accuracy of the dimensions of the stitched parts and the finished apparel. The primary responsibility of a checker is to measure all the dimension of the apparel and ensure they are free from defects.', 420, 420, '401–600', 'Version', '18 Feb 2025', '18 Feb 2028', 'Apparel, Madeups & HomeFurnishing Sector Skill Council (AMHSSC)', 'Apparel, Made-ups & Home Furnishing Sector Skill Council', 'Quality Assurance', 'QC Executive - Sewing Line', 'General Qualification', 'N.A.', '{"Theory":"126","Practical":"204","EmployabilitySkills":"60","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "38", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_12.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-AP-03576-2025-V2-AMHSSC', 'Merchandiser –Fashion, Made-Ups & Home Furnishings', 'apparel', 'Apparel', 5.0, 'The Merchandiser plays a major role right from the process beginning with strategic planning to execution of plan from order booking to final shipment. The critical role of merchandising department can be divided into three major heads: Order Booking Process, Product Development Process and Pre-Production Process. The span of tasks for merchandiser involves getting the right merchandise, in the right place, at the right time, in the right quantities at the right price.', 570, 570, '401–600', 'Version', '18 Feb 2025', '18 Feb 2028', 'Apparel, Madeups & HomeFurnishing Sector Skill Council (AMHSSC)', 'Apparel, Made-ups & Home Furnishing Sector Skill Council', 'Merchandising', 'Sr. Merchandiser', 'General Qualification', 'N.A.', '{"Theory":"306","Practical":"144","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "39", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_12.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-AP-03577-2025-V2-AMHSSC', 'Processing Supervisor (Dyeing &Printing)', 'apparel', 'Apparel', 5.0, 'Processing Supervisor (Dyeing & Printing) is responsible for monitoring production, quality and smooth operation of processes beginning with development of recipe to execution of processes with junior management cadres working as a team. Processing supervisors strategize efficient techniques to maximize the productivity and performance of the staff. He also ensures discharge of effluents as per defined statutory norms.', 480, 480, '401–600', 'Version', '18 Feb 2025', '18 Feb 2028', 'Apparel, Madeups & HomeFurnishing Sector Skill Council (AMHSSC)', 'Apparel, Made-ups & Home Furnishing Sector Skill Council', 'Department Supervision', 'Sampling Coordinator', 'General Qualification', 'N.A.', '{"Theory":"126","Practical":"264","EmployabilitySkills":"60","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "40", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_12.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-AP-03579-2025-V2-AMHSSC', 'Record Keeper-Sewn Items Manufacturing', 'apparel', 'Apparel', 3.0, 'Record keeper is responsible for collecting, preserving, and maintaining data for various processes. He/ She oversee the organization records from their creation and preservation through to disposal The job of record keeper broadly involves collection of data related to accounting and personnel, data related to manufacturing processes containing material movement and various quality related data generated due to inspection/testing/studies carried out at many stages of manufacturing.', 300, 300, '201–400', 'Version', '18 Feb 2025', '18 Feb 2028', 'Apparel, Madeups & HomeFurnishing Sector Skill Council (AMHSSC)', 'Apparel, Made-ups & Home Furnishing Sector Skill Council', 'Department Supervision', 'Checker Inline and Measurement', 'General Qualification', 'N.A.', '{"Theory":"78","Practical":"162","EmployabilitySkills":"30","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "41", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_12.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-AP-03580-2025-V2-AMHSSC', 'Sampling Coordinator', 'apparel', 'Apparel', 5.0, 'A sampling coordinator plans, handled and monitor new product development, regular follow up with all sampling like proto sample, size sets, fit samples and photo shoot samples. He/She acts as a liaison between vendors, buyers and internal team on the status of samples for the product being developed. And, document and maintain a tracking system of samples.', 510, 510, '401–600', 'Version', '18 Feb 2025', '18 Feb 2028', 'Apparel, Madeups & HomeFurnishing Sector Skill Council (AMHSSC)', 'Apparel, Made-ups & Home Furnishing Sector Skill Council', 'Sampling', 'Merchandiser(Horizontal)', 'General Qualification', 'N.A.', '{"Theory":"96","Practical":"294","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "42", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_12.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-AP-03505-2025-V1-MSME', 'SPORTS APPAREL MAKER', 'apparel', 'Apparel', 3.0, 'To create self and wage employment opportunities for fresher’s/ unemployed as well as to upgrade the 
skills of people already work in this field. 
To develop the competencies in Sports Apparel stitching processes and various other operations involved in Sports Apparel manufacturing. 
To give vocational and professional skill access to quality based higher production so more MSMEs may be increase', 450, 450, '401–600', 'Version', '18 Feb 2025', '18 Feb 2028', 'MSME Technology Centre, Ministry of Micro Small And Medium Enterprises, New Delhi', 'MSME TECHNOLOGY CENTRE', 'Garments Making', 'Supervisor', 'General Qualification', 'N.A.', '{"Theory":"110","Practical":"280","EmployabilitySkills":"30","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "43", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_00_12.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2021/AUT/ASDC/04333', 'Automotive Assembly Assistant', 'automotive', 'Automotive', 2.0, 'The individual in this role supports the Automotive Assembly Operator during preparation for assembly work such as bringing auto components and tools, assembling activities such as equipment setup, holding tools etc. and post-assembly activities such as cleaning and maintenance of equipment and work area.', 256, 256, '201–400', 'Version', '29 Jul 2021', '29 Jul 2026', 'Automotive Skills Development Council (ASDC)', 'Automotive Skills Development Council', 'Assembly Operation', 'Automotive Assembly Operator, Automotive Assembly Technician, Assembly Lead Technician, Assembly Master Technician', 'General Qualification', 'N.A.', '{"Theory":"100","Practical":"156","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "1", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_23.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2021/AUT/ASDC/04346', 'Automotive Forging Technician', 'automotive', 'Automotive', 4.0, 'The individual is involved in operating the forging process apparatus and performing various forging andpost-forging activities.', 400, 400, '201–400', 'Version', '29 Jul 2021', '29 Jul 2026', 'Automotive Skills Development Council (ASDC)', 'Automotive Skills Development Council', 'Forging Operation', 'Automotive Forging Lead Technician', 'General Qualification', 'N.A.', '{"Theory":"140","Practical":"260","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "2", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_23.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2021/AUT/ASDC/04340', 'Automotive Machining Master Technician', 'automotive', 'Automotive', 6.0, 'The individual is primarily involved in various machining and new product development processes onCNC/conventional machines such as writing and modifying CNC program, quality verification, resetting ofthe tools, machine PPAP process, six sigma capability study etc.', 560, 560, '401–600', 'Version', '29 Jul 2021', '29 Jul 2026', 'Automotive Skills Development Council (ASDC)', 'Automotive Skills Development Council', 'Machining Operation', 'Automotive Production Manager', 'General Qualification', 'N.A.', '{"Theory":"208","Practical":"352","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "3", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_23.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
