INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2021/AUT/ASDC/04350', 'Automotive Production Equipment Design Engineer', 'automotive', 'Automotive', 6.0, 'The individual at this job is responsible for design details of the equipment- mechanism, fixtures, tools,
gauges and other instruments for manufacturing & measuring the quality standards of the production
process.
1.	Design fixtures, workstation and their mechanisms
2.	Release the drawings and manage the documentation for engineering change
3.	Select and operate 3D Printing machine for product generation
4.	Manage work and resources (Manufacturing)
5.	Interact effectively with team, customers and others', 504, 504, '401–600', 'Version', '29 Jul 2021', '29 Jul 2026', 'Automotive Skills Development Council (ASDC)', 'Automotive Skills Development Council', 'Assembly', 'Automotive Production Equipment, Design Manager', 'General Qualification', 'N.A.', '{"Theory":"202","Practical":"302","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "9", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_23.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
