INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-06-AU-00570-2023-V1-ASDC', 'Automotive Dealership Data Science Specialist', 'automotive', 'Automotive', 6.0, 'The individual at this job is responsible for designing and developing the visualization platforms for end-to-end visibility, after-sales analytics solutions and services, and customer retention strategies based on the customer database. He/She leads the development activities and guide the team on the technical front in analytics solutions and reviewing of code and supports a range of analytical, visualization, and predictive modelling projects along with project management.', 660, 660, '601–800', 'Version', '23 Jun 2023', '23 Jun 2026', 'Automotive Skills Development Council (ASDC)', 'Automotive Skills Development Council', 'Technical Service and Repair', 'Workshop Service head, Service Leader, General Manager (Service)', 'Future Skills Qualification', 'N.A.', '{"Theory":"120","Practical":"180","EmployabilitySkills":"120","OJT_Mandatory":"240"}', false, '{}'::text[], '{"source_row": "22", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_23.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-06-AU-00571-2023-V1-ASDC', 'Automotive Design Safety Specialist', 'automotive', 'Automotive', 6.0, 'The individual at this job is responsible for end-to-end design and development of systems and services (Electrical/Electronic/Mechanical), deployment of standards and review of systems and engineering activities. He/she leads the product engineering activities and guides team on technical functions through technologies, and engineering applications. He/she also develops management processes for team, PD (Product Development) programs and report and record QIP (Quality Improvement Plan) related activities towards achieving product quality excellence.', 660, 660, '601–800', 'Version', '23 Jun 2023', '23 Jun 2026', 'Automotive Skills Development Council (ASDC)', 'Automotive Skills Development Council', 'Automotive Product Designing', 'Automotive Design Safety Head', 'Future Skills Qualification', 'N.A.', '{"Theory":"120","Practical":"180","EmployabilitySkills":"120","OJT_Mandatory":"240"}', false, '{}'::text[], '{"source_row": "23", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_23.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-06-AU-00572-2023-V1-ASDC', 'Automotive IIOT Application Specialist', 'automotive', 'Automotive', 6.0, 'The individual at this job is responsible for managing and monitoring activities of integration of machines, robots, and Automation Systems in Healthy Communication, establish healthy communication using network protocols, remote monitoring and fetch vital machine data using IIOT edge devices within an organization for all its processes, the new development, production and application phases.', 660, 660, '601–800', 'Version', '23 Jun 2023', '23 Jun 2026', 'Automotive Skills Development Council (ASDC)', 'Automotive Skills Development Council', 'N/A', 'Automotive IIOT Application Head, Automotive Plant Head, Automotive Production Engineering Head', 'Future Skills Qualification', 'N.A.', '{"Theory":"120","Practical":"180","EmployabilitySkills":"120","OJT_Mandatory":"240"}', false, '{}'::text[], '{"source_row": "24", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_23.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-06-AU-00573-2023-V1-ASDC', 'Automotive Manufacturing Data Science Specialist', 'automotive', 'Automotive', 6.0, 'The individual at this job is responsible for designing and developing the visualization platforms for end-to-end visibility, after-sales analytics solutions and services, and determining repair cost estimates and allocating repair timelines, recording and creating daily maintenance logs and progress reports. He/She leads the development activities and guide the team on the technical front in analytics solutions and reviewing of code and supports a range of analytical, visualization, and predictive modelling projects along with project management.', 660, 660, '601–800', 'Version', '23 Jun 2023', '23 Jun 2026', 'Automotive Skills Development Council (ASDC)', 'Automotive Skills Development Council', 'Production Engineering', 'Automotive Plant Head, Automotive Production Engineering Head, Automotive Industry 4.0 Head', 'Future Skills Qualification', 'N.A.', '{"Theory":"120","Practical":"180","EmployabilitySkills":"120","OJT_Mandatory":"240"}', false, '{}'::text[], '{"source_row": "25", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_23.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-04-AU-01302-2023-V1-IACE', 'Introduction to Electric Vehicles', 'automotive', 'Automotive', 4.0, 'This comprehensive micro credential offers an overview of automotive systems, electrical systems in EVs and their safety aspects. It introduces electric vehicles (EVs), including two-wheeler EVs, and provides insights into their motors, other systems and their operations. In the evolving field of automotive electrification, this credential imparts the necessary knowledge and skills to de-energize the EV.', 30, 30, '1–200', 'Version', '01 Nov 2023', '30 Oct 2026', 'International Automobile Centre of Excellence (iACE)', 'International Automobile Centre of Excellence', 'N/A', 'N/A', 'Micro Credentials', 'N.A.', '{"Theory":"15","Practical":"15","EmployabilitySkills":"00","OJT_Mandatory":"00"}', false, '{}'::text[], '{"source_row": "26", "qualification_type": "Micro Credentials", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_23.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-4.5-AU-01260-2023-V1-IACE', 'JUNIOR SUPERVISOR - Registered Vehicle Scrapping Facility (RVSF)', 'automotive', 'Automotive', 4.5, 'This course provides participants with the necessary knowledge and skills for safe and responsible end-of-life vehicle (ELV) de-pollution and dismantling. It covers topics such as safety, hazards and risks associated with vehicle dismantling, ELV guidance for waste handling, personal protective equipment training, personnel safety, Tools, and equipment. The course aims to ensure compliance with regulations and promote environmental responsibility in the automotive industry.', 510, 510, '401–600', 'Version', '01 Nov 2023', '30 Oct 2026', 'International Automobile Centre of Excellence (iACE)', 'International Automobile Centre of Excellence', 'Junior Supervisor - Registered vehicle Scrapping Facility', 'Junior Supervisor (Lv4.5)➡️ Workshop Supervisor/Asst Manager (Lv5)➡️ Operations Manager (Lv5.5)', 'Future Skills Qualification', 'N.A.', '{"Theory":"135","Practical":"210","EmployabilitySkills":"60","OJT_Mandatory":"105"}', false, '{}'::text[], '{"source_row": "27", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_23.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
