INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-5.5-AU-02234-2024-V1-ASDC', 'Fundamentals of Automotive Functional Safety Design', 'automotive', 'Automotive', 5.5, 'This NOS unit is about preparing comprehensively to perform design-analysis-development-validation of safety systems with the understanding of statutory and industry standards pertaining to functional safety. This NOS unit is about performing engineering design and the product development of Electrical/Electronic (E/E) systems It’s about performing simulations (CAE) of CAD models (mechanical & electrical) to best correlate with the physical tests (lab & field).', 60, 60, '1–200', 'Version', '15 Mar 2024', '15 Mar 2027', 'Automotive Skills Development Council (ASDC)', 'Automotive Skills Development Council', 'Automotive Product
Designing', 'N/A', 'Future Skills Qualification', 'N.A.', '{"Theory":"15","Practical":"45","EmployabilitySkills":"00","OJT_Mandatory":"00"}', false, '{}'::text[], '{"source_row": "36", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_23.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-5.5-AU-02225-2024-V1-ASDC', 'Fundamentals of Connected Vehicle (V2X) Technology', 'automotive', 'Automotive', 5.5, 'This NOS unit is about designing smart systems for communication between vehicle and everything around (V2X).  It’s also about skilling on designing fail-safe systems with good understanding of associated hazards and the methodical risk mitigation process in vehicle development.', 60, 60, '1–200', 'Version', '15 Mar 2024', '15 Mar 2027', 'Automotive Skills Development Council (ASDC)', 'Automotive Skills Development Council', 'Automotive Product Designing', 'N/A', 'Future Skills Qualification', 'N.A.', '{"Theory":"15","Practical":"45","EmployabilitySkills":"00","OJT_Mandatory":"00"}', false, '{}'::text[], '{"source_row": "37", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_23.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-5.5-AU-02231-2024-V1-ASDC', 'Fundamentals of Electric Vehicle Battery Pack Design', 'automotive', 'Automotive', 5.5, 'This NOS unit is about preparing for the most discussed field of electric vehicles and the emerging trends in battery usage in the age of circular economy. This NOS unit is about designing EV battery pack in sustainable-optimal-durable-economical manner. It’s as well about skilling on designing, analyzing, validating, maintaining and disposing battery pack and associated systems like charging station, on-board charging and on-the-go charging mechanisms.', 60, 60, '1–200', 'Version', '15 Mar 2024', '15 Mar 2027', 'Automotive Skills Development Council (ASDC)', 'Automotive Skills Development Council', 'Automotive Product Designing', 'N/A', 'Future Skills Qualification', 'N.A.', '{"Theory":"15","Practical":"45","EmployabilitySkills":"00","OJT_Mandatory":"00"}', false, '{}'::text[], '{"source_row": "38", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_23.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-5.5-AU-02232-2024-V1-ASDC', 'Fundamentals of Electric Vehicle Powertrain Design', 'automotive', 'Automotive', 5.5, 'This NOS unit is about preparing for the fast evolving field of electric vehicle powertrain and its universal design for alternative fuel mobility. This NOS unit is about designing EV powertrain’s mechanical and electromechanical components in a frugal-optimal-reliable manner. It’s as well about skilling on designing, simulating and validating powertrain parts and sub-units.', 60, 60, '1–200', 'Version', '15 Mar 2024', '15 Mar 2027', 'Automotive Skills Development Council (ASDC)', 'Automotive Skills Development Council', 'Automotive Product Designing', 'N/A', 'Future Skills Qualification', 'N.A.', '{"Theory":"15","Practical":"45","EmployabilitySkills":"00","OJT_Mandatory":"00"}', false, '{}'::text[], '{"source_row": "39", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_23.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
