INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-4.5-AU-01832-2024-V1-ASDC', 'Automobile Technology', 'automotive', 'Automotive', 4.5, 'The Light Vehicle Automotive Technician will work in the service, diagnosis and repair sector of light vehicles in either independent workshops or the vehicle manufacturers’ affiliated workshops. The Light Vehicle Automotive Technician will be able to service, diagnose, and repair a range of light vehicles using service and repair information, and a wide range of diagnostic and service tools.', 510, 510, '401–600', 'Version', '06 Feb 2024', '06 Feb 2026', 'Automotive Skills Development Council (ASDC)', 'Automotive Skills Development Council', 'N/A', 'Lead Technician', 'Future Skills Qualification', 'N.A.', '{"Theory":"84","Practical":"84","EmployabilitySkills":"00","OJT_Mandatory":"342"}', false, '{}'::text[], '{"source_row": "46", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_23.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-4.5-AU-01833-2024-V1-ASDC', 'Car Painting', 'automotive', 'Automotive', 4.5, 'Car painters (refinishers) are responsible for reinstating the pre-accident paint finish to cars after the structure and/or the panels have been repaired or replaced. They may also be asked to completely repaint a whole vehicle either to change its colour or reinstate its newness. Car painters may also become involved in matching colours to an original colour no longer available or to colours that prove difficult to match. A car painter must match the colour, shade, and texture of the adjoining panels that are not being painted.', 510, 510, '401–600', 'Version', '06 Feb 2024', '06 Feb 2026', 'Automotive Skills Development Council (ASDC)', 'Automotive Skills Development Council', 'N/A', 'Painting lead technician
Painting master technician', 'Future Skills Qualification', 'N.A.', '{"Theory":"84","Practical":"84","EmployabilitySkills":"00","OJT_Mandatory":"342"}', false, '{}'::text[], '{"source_row": "47", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_23.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-4.5-AU-01813-2024-V1-ASDC', 'Industrial Control', 'automotive', 'Automotive', 4.5, 'Industrial Control contains elements of both electrical installations and automation installations, with greater emphasis on automation installation. The industrial control practitioner requires a wide range of technical skills, such as installing conduits, cables, instruments, I/O devices and Programmable Logic Controllers. The industrial control practitioner also designs electrical circuits, programs Programmable Logic Controllers, parametrizes bus systems and configures Human Machine Interfaces.', 510, 510, '401–600', 'Version', '06 Feb 2024', '06 Feb 2026', 'Automotive Skills Development Council (ASDC)', 'Automotive Skills Development Council', 'N/A', 'Engineer Supervisor', 'Future Skills Qualification', 'N.A.', '{"Theory":"84","Practical":"84","EmployabilitySkills":"00","OJT_Mandatory":"342"}', false, '{}'::text[], '{"source_row": "48", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_23.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-4.5-AU-01820-2024-V1-ASDC', 'Industry 4.0', 'automotive', 'Automotive', 4.5, 'The role of the Digital Production Systems Technician is to understand the business case for enhancement, and to design and implement technical responses accordingly. Assembled and commissioned hardware in virtual and real context using various digital tools and technology provide the basis for programming, and the design and implementation of cyber security measures on real and virtual production processes.', 510, 510, '401–600', 'Version', '06 Feb 2024', '06 Feb 2026', 'Automotive Skills Development Council (ASDC)', 'Automotive Skills Development Council', 'N/A', 'Engineer Supervisor', 'Future Skills Qualification', 'N.A.', '{"Theory":"84","Practical":"84","EmployabilitySkills":"00","OJT_Mandatory":"342"}', false, '{}'::text[], '{"source_row": "49", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_23.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-4.5-AU-01819-2024-V1-ASDC', 'Robot Systems Integration', 'automotive', 'Automotive', 4.5, 'The robot system integrator must provide technical solutions to the robotization of all or part of a system by incorporating a multi-articulating arm, together with the associated handling tools or special processes (such as handling, machining, painting, and welding), to increase competitiveness and supporting the ergonomics, health and safety of the users and people around them.', 510, 510, '401–600', 'Version', '06 Feb 2024', '06 Feb 2026', 'Automotive Skills Development Council (ASDC)', 'Automotive Skills Development Council', 'N/A', 'Automation and Robotics Engineer Level 6
Automotive Robotics and Automation Simulation Engineer Level 6,
Automotive Robotics and Automation Manager Level 7', 'Future Skills Qualification', 'N.A.', '{"Theory":"84","Practical":"84","EmployabilitySkills":"00","OJT_Mandatory":"342"}', false, '{}'::text[], '{"source_row": "50", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_23.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-4.5-AU-01811-2024-V1-ASDC', 'Welding', 'automotive', 'Automotive', 4.5, 'A welder prepares and joins a range of metals and metallic alloys using mainly processes where an electric arc is the heat source. Electric arc processes utilize a gas shield or a flux to protect the molten weld area from contamination by the surrounding atmosphere. A welder needs to be able to interpret engineering drawings, standards and symbols and correctly translate these requirements into accurate structures and fabrications.', 510, 510, '401–600', 'Version', '06 Feb 2024', '06 Feb 2026', 'Automotive Skills Development Council (ASDC)', 'Automotive Skills Development Council', 'N/A', 'Welding Lead Technician
Welding Master Technician', 'Future Skills Qualification', 'N.A.', '{"Theory":"84","Practical":"84","EmployabilitySkills":"00","OJT_Mandatory":"342"}', false, '{}'::text[], '{"source_row": "51", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_23.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
