INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-4.5-AU-02197-2024-V1-ASDC', 'Automobile Lead Technician (Diagnostics)', 'automotive', 'Automotive', 4.5, 'The qualification "Automobile Lead Technician (Diagnostics)" is likely to be designed for individuals who aspire to become experts in diagnosing and troubleshooting complex automotive issues. This role often involves leading a team of technicians and playing a pivotal role in identifying and resolving challenging vehicle malfunctions, utilizing advanced diagnostic tools, and staying abreast of the latest automotive technologies.', 1200, 1200, '1001–1200', 'Version', '15 Mar 2024', '15 Mar 2027', 'Automotive Skills Development Council (ASDC)', 'Automotive Skills Development Council', 'Automobile Service', 'Specialization and Expertise, Management Roles, Automotive Engineering, Technical Support and Consulting', 'Future Skills Qualification', 'N.A.', '{"Theory":"270","Practical":"480","EmployabilitySkills":"120","OJT_Mandatory":"330"}', false, '{}'::text[], '{"source_row": "62", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_23.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
