INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-03-AU-02555-2024-V1-SAMITI', 'Nano Entrepreneurship in Car Washing Service', 'automotive', 'Automotive', 3.0, 'The Nano Level Qualification for Entrepreneurship in Car Washing is designed to equip individuals with the skills and knowledge required to establish and manage small-scale car washing businesses. This qualification focuses on the practical aspects of car washing, including proper washing techniques, use of cleaning agents, and equipment maintenance. It also covers essential business management concepts such as budgeting, scheduling, inventory management, and customer service. Participants will learn marketing and sales strategies to attract and retain customers, as well as sustainable practices to ensure a no to low environmental impact.', 60, 60, '1–200', 'Version', '30 May 2024', '29 May 2027', 'Samadhan Samiti', 'Samadhan Samiti, 2nd Floor, Siddhivinayak Building, 27/1/B Samadhan Tower, Gokhale Marg, Lucknow, Uttar Pradesh, Pincode - 226001', 'Car Washing Service Provider', 'Nascent Phase Entrepreneur, Expansion Phase Entrepreneur, Diversification Phase Entrepreneur, Franchising or Chain Establishment Entrepreneur, Specialization Entrepreneur, Technology Integration Entrepreneur', 'Cross Sectoral Qualification,National Occupational Standard', 'N.A.', '{"Theory":"40","Practical":"20","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "71", "qualification_type": "Cross Sectoral Qualification,National Occupational Standard", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_23.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-4.5-AU-03002-2024-V1-IACE', 'Introduction to Automotive Electronics', 'automotive', 'Automotive', 4.5, 'This comprehensive micro credential offers an overview of automotive systems, automotive electronics in vehicles. It introduces basic of electrical system and provide insights about automotive sensors and working of each sensors. In the evolving field of automotive electrification, this credential imparts the necessary knowledge about various driver train in EV-HV.', 30, 30, '1–200', 'Version', '27 Aug 2024', '26 Aug 2027', 'International Automobile Centre of Excellence (iACE)', 'International Automobile Centre of Excellence', 'Not Applicable', 'Not Applicable', 'Micro Credentials', 'N.A.', '{"Theory":"15","Practical":"15","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "72", "qualification_type": "Micro Credentials", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_23.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-4.5-AU-03003-2024-V1-IACE', 'Introduction to Automotive Systems', 'automotive', 'Automotive', 4.5, 'This comprehensive micro credential offers an overview of automotive systems and some of its systems and subsystems. It introduces Automotive Systems, and provides insights into Engine & its components, other systems like Brake Systems, Anti-Lock Braking System, HVAC System and their operations. In the evolving field of automotive industry, this credential imparts the necessary knowledge and skills to identify and diagnose faults in automobile using OBD scan tool.', 30, 30, '1–200', 'Version', '27 Aug 2024', '26 Aug 2027', 'International Automobile Centre of Excellence (iACE)', 'International Automobile Centre of Excellence', 'Not Applicable', 'Not Applicable', 'Micro Credentials', 'N.A.', '{"Theory":"15","Practical":"15","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "73", "qualification_type": "Micro Credentials", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_23.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
