INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-3.5-AU-03446-2024-V1-SS', 'Entrepreneurship in Car Washing Service', 'automotive', 'Automotive', 3.5, 'Entrepreneurship in Car Washing Service is a qualification designed to prepare individuals for starting and managing small-scale car washing businesses. It covers a range of essential topics such as business planning, operations management, customer service, health and safety compliance, marketing and promotion, financial management, and environmental sustainability. Participants learn how to develop a business plan, conduct market research, set pricing strategies, and manage day-to-day operations including equipment maintenance, etc. The qualification emphasizes the importance of providing high-quality customer service, understanding and complying with health, and safety regulations. Overall, it prepares learners to effectively start, operate and manage a car washing business.', 90, 90, '1–200', 'Version', '17 Dec 2024', '16 Dec 2027', 'Samadhan Samiti', 'Samadhan Samiti, 2nd Floor, Siddhivinayak Building, 27/1/B Samadhan Tower, Gokhale Marg, Lucknow, Uttar Pradesh, Pincode - 226001', 'Car Washing Service Provider', 'N/A', 'Cross Sectoral Qualification,National Occupational Standard', 'N.A.', '{"Theory":"60","Practical":"30","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "117", "qualification_type": "Cross Sectoral Qualification,National Occupational Standard", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_23.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-AU-04195-2025-V1-ASDC', 'Automotive Welding Simulation Trainee (using AR)', 'automotive', 'Automotive', 4.0, 'An augmented reality (AR) welding technician uses AR technology to learn, practice, and refine welding skills. An AR welding technician primarily uses augmented reality technology to perform welding process by visualizing weld paths, inspecting welds in real-time, and ensuring accuracy by overlaying digital information onto the physical work area, while still performing the core responsibilities of a traditional welder, such as preparing materials, setting up welding equipment, and executing various welding techniques.', 480, 720, '601–800', 'Version', '08 May 2025', '08 May 2028', 'Automotive Skills Development Council (ASDC)', 'Automotive Skills Development Council', 'Welding Operations', 'Automotive AR Welding Simulation Trainer', 'Future Skills Qualification,General Qualification,OEM Qualification', 'N.A.', '{"Theory":"120","Practical":"210","EmployabilitySkills":"30","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "118", "qualification_type": "Future Skills Qualification,General Qualification,OEM Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_23.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-4.5-AU-04194-2025-V1-ASDC', 'Automotive Welding Machine Trainer', 'automotive', 'Automotive', 4.5, 'The individual is using pre-set lesson plans and training materials to plan and conduct training sessions for welding team to impart competency-based skills and knowledge.', 480, 480, '401–600', 'Version', '08 May 2025', '08 May 2028', 'Automotive Skills Development Council (ASDC)', 'Automotive Skills Development Council', 'Metal Joining', 'Training and Development Manager', 'General Qualification', 'N.A.', '{"Theory":"160","Practical":"200","EmployabilitySkills":"30","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "119", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_23.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-02-AU-04193-2025-V1-ASDC', 'Automotive Press Shop Assistant', 'automotive', 'Automotive', 2.0, 'The individual in this role supports the Press Shop Technician during preparation for pressing work such as bringing material and tools, pressing activities such as equipment setup, holding tools etc. and post-pressing activities such as cleaning and maintenance of equipment and work area.', 270, 270, '201–400', 'Version', '08 May 2025', '08 May 2028', 'Automotive Skills Development Council (ASDC)', 'Automotive Skills Development Council', 'Sheet Metal Forming', 'Automotive Press shop technician', 'General Qualification', 'N.A.', '{"Theory":"90","Practical":"120","EmployabilitySkills":"30","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "120", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_23.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/BW/BWSSC/06575', 'Assistant Beauty Therapist', 'beauty-wellness', 'Beauty & Wellness', 3.0, 'An Assistant Beauty Therapist needs to be aware of basic beauty therapy, basic hair styling, basic make-up, and pedicure and manicure services maintaining health, hygiene and safety at the workplace. The job holder needs to be knowledgeable about
various beauty products, tools and equipment. The person needs to assist the senior therapists/ stylists for various services in the salon.', 420, 450, '401–600', 'Version', '17 Nov 2022', '17 Nov 2025', 'Beauty & Wellness Sector Skill Council (B&WSSC)', 'Beauty & Wellness Sector Skill Council', 'Skincare Services under Beauty and Salons Sub-sector', 'This entry should refer to one or more of the followings:
-	access to other qualifications at the same NSQF level - Assistant Nail Technician; Assistant Beauty & Wellness Consultant; Assistant Cosmetologist (Level-3)
-	access to related qualification(s) at the next NSQF level - Beauty Therapist,
Professional Make-up Artist; Cosmetologist (Level-4)', 'Upskilling Qualification', 'N.A.', '{"Theory":"110","Practical":"220","EmployabilitySkills":"60","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "1", "qualification_type": "Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/BW/BWSSC/06578', 'Assistant Hair Dresser and Stylist', 'beauty-wellness', 'Beauty & Wellness', 3.0, 'An Assistant Hair Dresser & Stylist shampoos and condition hair and scalp, blow dries hair, provides basic haircuts, colours hair, and provides Indian head massage to clients by maintaining health, safety and hygiene at workplace. They assist the
hair dresser & stylist in providing other advanced hair dressing & styling services', 390, 390, '201–400', 'Version', '31 Aug 2021', '17 Nov 2025', 'Beauty & Wellness Sector Skill Council (B&WSSC)', 'Beauty & Wellness Sector Skill Council', 'Hair Dressing & Styling Services under Beauty and Salons Sub-sector', 'This entry should refer to one or more of the following:
- access to other qualifications at the same NSQF level – Assistant Cosmetologist (Level-3)
- access to related qualification(s) at the next NSQF level - Hair Dresser & Stylist; Cosmetologist (Level-4)', 'Heritage/Traditional Qualification', 'N.A.', '{"Theory":"100","Practical":"200","EmployabilitySkills":"60","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "2", "qualification_type": "Heritage/Traditional Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/BW/BWSSC/06581', 'Assistant Nail Technician', 'beauty-wellness', 'Beauty & Wellness', 3.0, 'An Assistant Nail Technician performs various duties such as manicure and pedicure and assists the nail technician in providing advanced nailcare services like nail art, nail tips and nail enhancement. The Assistant Nail Technician needs to be knowledgeable on structure and function of nails, various nailcare services maintaining health, safety and hygiene at workplace, and range of nail products.', 330, 330, '201–400', 'Version', '31 Aug 2021', '17 Nov 2025', 'Beauty & Wellness Sector Skill Council (B&WSSC)', 'Beauty & Wellness Sector Skill Council', 'Nailcare Services under Beauty and Salons Sub-sector', 'This entry should refer to one or more of the following:
-	access to other qualifications at the same NSQF level – Pedicurist & Manicurist; Assistant Beauty & Wellness Consultant (Level-3)
-	access to related qualification(s) at the next NSQF level - Nail
Technician (Level-4)', 'Heritage/Traditional Qualification', 'N.A.', '{"Theory":"80","Practical":"160","EmployabilitySkills":"60","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "3", "qualification_type": "Heritage/Traditional Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/BW/BWSSC/06585', 'Assistant Spa Therapist', 'beauty-wellness', 'Beauty & Wellness', 3.0, 'An Assistant Spa Therapist needs to know basic spa therapy, by maintaining health, hygiene, and safety at workplace. They need to be knowledgeable about various spa products and massage techniques. Assistant Spa Therapist is expected to assist the Spa Therapist in providing the spa services', 390, 390, '201–400', 'Version', '31 Aug 2021', '17 Nov 2025', 'Beauty & Wellness Sector Skill Council (B&WSSC)', 'Beauty & Wellness Sector Skill Council', 'Spa Services under Alternate Therapy & Rejuvenation Sub-sector', 'This entry should refer to one or more of the following:
-access to other qualifications at the same NSQF level – Pedicurist & Manicurist (Level-3)
-access to related qualification(s) at the next NSQF level - Spa
Therapist (Level-4)', 'Heritage/Traditional Qualification', 'N.A.', '{"Theory":"90","Practical":"180","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "4", "qualification_type": "Heritage/Traditional Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/BW/BWSSC/06576', 'Beauty Therapist', 'beauty-wellness', 'Beauty & Wellness', 4.0, 'A beauty therapist is a professionally trained individual who specializes in beauty services for both face and body. A beauty therapist performs various duties such as providing skincare services, apply makeup, removal of unwanted hair, and manicure and pedicure services by maintaining health, safety and hygiene at workplace. The
person needs to be knowledgeable on various beauty and make-up products, and a range of beauty services.', 510, 510, '401–600', 'Version', '31 Aug 2021', '17 Nov 2025', 'Beauty & Wellness Sector Skill Council (B&WSSC)', 'Beauty & Wellness Sector Skill Council', 'Skincare Services under Beauty and Salons Sub-sector', 'This entry should refer to one or more of the following:
-access to other qualifications at the same NSQF level – Cosmetologist; Nail Technician (Level-4)
-access to related qualification(s) at the next NSQF level - Senior Beauty Therapist; Beauty Advisor, Senior Cosmetologist (Level-5)', 'Multi-Skill Qualification', 'N.A.', '{"Theory":"130","Practical":"260","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "5", "qualification_type": "Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/BW/BWSSC/06584', 'Bridal, Fashion and Portfolio Makeup Artist', 'beauty-wellness', 'Beauty & Wellness', 5.0, 'A Bridal Fashion and Portfolio Make-up Artist is a professionally trained individual in make-up techniques using corrective, highlighting, shading, and air brush make-ups to deliver high quality professional make up. He/ She provides client consultation on various beauty & make-up products; and performs various services such as skincare and make-up by maintaining health, safety and hygiene at workplace. He/ She needs to be knowledgeable on the skin structure, basic beauty therapies, various make-up
techniques and range of beauty and make-up products.', 600, 600, '401–600', 'Version', '31 Aug 2021', '17 Nov 2025', 'Beauty & Wellness Sector Skill Council (B&WSSC)', 'Beauty & Wellness Sector Skill Council', 'Make-up Services under
Beauty and Salons Sub-sector', 'Senior Cosmetologist, Level- 5;
Makeup Trainer; Beauty Manager/Floor Manager – Salon; Beauty Services Specialist
at Level- 6', 'Dual/Flexi Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"140","Practical":"280","EmployabilitySkills":"90","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "6", "qualification_type": "Dual/Flexi Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/BW/BWSSC/06579', 'Hair Dresser & Stylist', 'beauty-wellness', 'Beauty & Wellness', 4.0, 'A Hair Dresser & Stylist is a professionally trained individual who specialises in haircare, hair dressing and styling. They perform various services like shampooing, hair spa, massage, trimming, cutting, blow drying, styling, hair relaxing and straightening, perming and neutralising, colouring and various treatment for hair damage and repair by maintaining health, safety and hygiene at workplace. A Hair Dresser & Stylist needs to understand the intricacies of hair cutting and styling, while also knowing how to keep the
hair healthy.', 480, 510, '401–600', 'Version', '31 Aug 2021', '17 Nov 2025', 'Beauty & Wellness Sector Skill Council (B&WSSC)', 'Beauty & Wellness Sector Skill Council', 'Hair Dressing & Styling Services under Beauty and Salons Sub-sector', 'This entry should refer to one or more of the following:
-access to other qualifications at the same NSQF level -Cosmetologist (Level-4)
-access to related qualification(s) at the next NSQF level - Senior Hair Dresser & Stylist; Hair Advisor; Senior Cosmetologist (Level-5)', 'Upskilling Qualification', 'N.A.', '{"Theory":"120","Practical":"240","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "7", "qualification_type": "Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/BW/BWSSC/06589', 'Master Wellness Neurotherapist', 'beauty-wellness', 'Beauty & Wellness', 5.0, 'A master wellness neurotherapist is responsible for assessing the state of mental, physical and emotional wellbeing of clients seeking for neurotherapy treatments for overall wellness. The individual should guide or suggest senior neurotherapists by recommending appropriate
wellness neurotherapy treatments to suffice the client’s needs in compliant with relevant organisations quality standards.', 600, 600, '401–600', 'Version', '31 Aug 2021', '17 Nov 2025', 'Beauty & Wellness Sector Skill Council (B&WSSC)', 'Beauty & Wellness Sector Skill Council (B&WSSC)', 'Neurotherapy Services under Alternate Therapy & Rejuvenation Sub-sector', 'Entrepreneur', 'Heritage/Traditional Qualification', 'N.A.', '{"Theory":"120","Practical":"240","EmployabilitySkills":"90","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "8", "qualification_type": "Heritage/Traditional Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/BW/BWSSC/06580', 'Personal Trainer (B&W)', 'beauty-wellness', 'Beauty & Wellness', 4.0, 'The Personal Trainer (B&W) is responsible to plan,demonstrate, and monitor exercises performed by the members. The Personal Trainer (B&W) collects information, plans training programmes, monitors clients’ progressand focuses on individual assigned clients in meeting their fitness goals through effective motivation and continuous dedicated
exercises for overall well-being.', 510, 600, '401–600', 'Version', '17 Nov 2022', '17 Nov 2025', 'Beauty & Wellness Sector Skill Council (B&WSSC)', 'Beauty & Wellness Sector Skill Council (B&WSSC)', 'Fitness Services under Personal Services Sub-sector', 'Personal Training Manager (Level 5)', 'Upskilling Qualification', 'N.A.', '{"Theory":"125","Practical":"265","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "9", "qualification_type": "Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/BW/BWSSC/06594', 'Professional Makeup Artist', 'beauty-wellness', 'Beauty & Wellness', 4.0, 'A Professional Makeup Artist is a professionally trained individual who specializes in fundamental makeup skills to enhance facial aesthetics of the clients for creating custom looks for various formal/informal events/occasions. Basic contouring, colour analysis, corrective makeup, ramp makeup, and fantasy makeup with knowledge of various beauty and makeup products are
covered.', 510, 570, '401–600', 'Version', '17 Nov 2022', '17 Nov 2025', 'Beauty & Wellness Sector Skill Council (B&WSSC)', 'Beauty & Wellness Sector SkillCouncil', 'Makeup services under
Beauty & Salons sub-sector', 'Bridal, Fashion and Portfolio Makeup Artist; Cosmetologist at Level - 5', 'Upskilling Qualification', 'N.A.', '{"Theory":"130","Practical":"260","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "10", "qualification_type": "Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/BW/BWSSC/06577', 'Senior Beauty Therapist', 'beauty-wellness', 'Beauty & Wellness', 5.0, 'A senior beauty therapist is a professionally trained individual who specialises in advance beauty services for both face and body. A senior beauty therapist performs various duties such as providing advance skincare services with electrical equipment, apply makeup, removal of unwanted hair, and hair styling services by maintaining health, safety and hygiene at workplace. The person needs to be knowledgeable on various beauty, hair and make-up products, and a range of beauty treatments like facial electrotherapy, etc.', 600, 600, '401–600', 'Version', '17 Nov 2022', '17 Nov 2025', 'Beauty & Wellness Sector Skill Council (B&WSSC)', 'Beauty & Wellness Sector Skill Council', 'Skincare Services under Beauty and Salons Sub-sector', 'Beauty Advisor, Senior Cosmetologist at Level - 5 Skincare Trainer, Beauty Manager/ Floor Manager – Salon, Beauty Services Specialist at Level – 6', 'Upskilling Qualification', 'N.A.', '{"Theory":"140","Practical":"280","EmployabilitySkills":"90","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "11", "qualification_type": "Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/BW/BWSSC/06588', 'Senior Wellness Neurotherapist', 'beauty-wellness', 'Beauty & Wellness', 4.0, 'A senior wellness neurotherapist is responsible for recommending appropriate wellness neurotherapy procedure to clients with health problems. The individual should be capable of formulating procedure based on required procedure duration, type of pressing techniques, number of repetitions, location in the body, etc.', 540, 540, '401–600', 'Version', '31 Aug 2021', '17 Nov 2025', 'Beauty & Wellness Sector Skill Council (B&WSSC)', 'Beauty & Wellness Sector Skill Council (B&WSSC)', 'Neurotherapy Services under Alternate Therapy & Rejuvenation Sub-sector', 'Master Wellness Neurotherapist at Level 5', 'Upskilling Qualification', 'N.A.', '{"Theory":"120","Practical":"240","EmployabilitySkills":"60","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "12", "qualification_type": "Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/BW/BWSSC/06586', 'Spa Therapist', 'beauty-wellness', 'Beauty & Wellness', 4.0, 'Spa Therapist is responsible to provide a range of professional Spa services agreed with the guests in accordance with the
approved organization’s brand standards of performance and sequences of services.', 450, 450, '401–600', 'Version', '31 Aug 2021', '17 Nov 2025', 'Beauty & Wellness Sector Skill Council (B&WSSC)', 'Beauty & Wellness Sector Skill Council', 'Spa Services under Alternate Therapy & Rejuvenation Sub-sector', 'Spa Trainer; Floor Manager - Spa Centre at Level- 6', 'Upskilling Qualification', 'N.A.', '{"Theory":"100","Practical":"200","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "13", "qualification_type": "Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/BW/BWSSC/06587', 'Wellness Neurotherapist', 'beauty-wellness', 'Beauty & Wellness', 3.0, 'A wellness neurotherapist may carry out the work in a neurotherapy facility or at the client site. The job includes setting up the work area as per requirement, preparation of the set-up, positioning the client and carrying out the requisite rejuvenation procedure. The job holder must adhere to
instructions given by responsible seniors including Master or Senior Wellness Neurotherapist while carrying out therapy and related procedures', 450, 450, '401–600', 'Version', '31 Aug 2021', '17 Nov 2025', 'Beauty & Wellness Sector Skill Council (B&WSSC)', 'Beauty & Wellness Sector Skill Council (B&WSSC)', 'Neurotherapy Services under Alternate Therapy & Rejuvenation Sub-sector', 'Senior Wellness Neurotherapist at Level 4', 'Upskilling Qualification', 'N.A.', '{"Theory":"100","Practical":"200","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "14", "qualification_type": "Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/BW/BWSSC/06592', 'Yoga Instructor (B&W)', 'beauty-wellness', 'Beauty & Wellness', 4.0, 'A Yoga Instructor (B&W) is responsible to demonstrate the yoga postures, asanas, pranayamas, meditation and relaxation techniques for the clients. The individual must exhibit knowledge of the principles and practices of basic Yogic techniques for holistic wellbeing in order to explain and respond to the client’s questions.', 390, 390, '201–400', 'Version', '27 May 2021', '17 Nov 2025', 'Beauty & Wellness Sector Skill Council (B&WSSC)', 'Beauty & Wellness Sector Skill Council (B&WSSC)', 'Yoga Services from Yoga
sub-sector', 'Yoga Trainer (B&W) (Level 5)', 'Upskilling Qualification', 'N.A.', '{"Theory":"80","Practical":"160","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "15", "qualification_type": "Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/BW/BWSSC/06593', 'Yoga Trainer (B&W)', 'beauty-wellness', 'Beauty & Wellness', 5.0, 'A Yoga Trainer (B&W) is a professionally trained individual with an extensive additional training in Yoga for 360-degree wellness; and is able to work with the clients by conducting yoga postures, asanas, pranayamas, meditation and relaxation techniques. The individual must exhibit sound knowledge of the principles and practices of yogic techniques to explain and respond to the client’s questions on general wellbeing and provide trainings to Yoga Instructors.', 510, 570, '401–600', 'Version', '27 May 2021', '17 Nov 2025', 'Beauty & Wellness Sector Skill Council (B&WSSC)', 'Beauty & Wellness Sector Skill Council (B&WSSC)', 'Yoga Services under Yoga sub-sector', 'Senior Yoga Trainer (B&W) (Level 6)', 'Upskilling Qualification', 'N.A.', '{"Theory":"120","Practical":"240","EmployabilitySkills":"90","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "16", "qualification_type": "Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QM-05-BW-00440-2023-V1.1-BWSSC', 'Senior Hair Dresser & Stylist', 'beauty-wellness', 'Beauty & Wellness', 5.0, 'A Senior Hair Dresser & Stylist is a professionally trained individual who specialises in advanced haircare, hair dressing and creative styling. They perform various services like shampooing, hair spa, trimming, creative cutting, blow drying, advanced hair styling, hair relaxing and straightening, perming and neutralising, creative colouring, and various treatment for hair damage and repair by maintaining health, safety and hygiene at workplace. A Hair Dresser & Stylist needs to understand the intricacies of advance hair cutting and styling, while also knowing
how to keep the hair healthy.', 690, 690, '601–800', 'Version', '31 Aug 2021', '17 Nov 2025', 'Beauty & Wellness Sector Skill Council (B&WSSC)', 'Beauty & Wellness Sector Skill Council', 'Hair Dressing & Styling
Services under Beauty and Salons Sub-sector', 'Hair Advisor, Senior Salon Therapist at Level- 5
Beauty Services Specialist, Trainer- Hair Dressing & Styling Services, Hair Studio
Manager at Level- 6', 'Upskilling Qualification', 'N.A.', '{"Theory":"170","Practical":"340","EmployabilitySkills":"90","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "17", "qualification_type": "Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QM-06-BW-00441-2023-V1.1-BWSSC', 'Senior Yoga Trainer (B&W)', 'beauty-wellness', 'Beauty & Wellness', 6.0, 'A Senior Yoga Trainer (B&W) is a professionally trained individual with an advanced training in Yoga for holistic wellness, happiness and harmony; and is able to work with the clients by conducting the advanced yoga asanas, advanced pranayamas, advanced meditations and relaxation techniques to counterbalance unhealthy lifestyle, and manage a healthy body with a sound mind. S/he is also expected to train Yoga Trainers on the intricacies of yoga services to enhance the quality of life.', 570, 660, '601–800', 'Version', '27 May 2021', '17 Nov 2025', 'Beauty & Wellness Sector Skill Council (B&WSSC)', 'Beauty & Wellness Sector Skill Council (B&WSSC)', 'Senior Yoga Trainer (B&W) (Yoga Services)', 'Entrepreneur', 'Upskilling Qualification', 'N.A.', '{"Theory":"110","Practical":"220","EmployabilitySkills":"90","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "18", "qualification_type": "Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
