INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-BW-03600-2025-V2-BWSSC', 'Aesthetic Skin Technician', 'beauty-wellness', 'Beauty & Wellness', 4.0, 'The Aesthetic Skin Technician qualification prepares individuals to provide advanced skin care services in the beauty and wellness industry. This program equips learners with the knowledge and skills to perform non-invasive aesthetic treatments, including skin analysis, facials, exfoliation, chemical peels, and other rejuvenation techniques.
This qualification highlights modern tools like microdermabrasion and LED therapy while emphasizing hygiene, client consultation, and personalized care', 690, 690, '601–800', 'Version', '31 Aug 2021', '18 Mar 2028', 'Beauty & Wellness Sector Skill Council (B&WSSC)', 'Beauty & Wellness Sector Skill Council (B&WSSC)', 'Aesthetic Skin Services under Non-Invasive Cosmetology sub-sector', 'Beauty/Hair Aesthetic Advisor- Level 5', 'General Qualification', 'N.A.', '{"Theory":"180","Practical":"360","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "34", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-BW-03601-2025-V2-BWSSC', 'Cosmetologist', 'beauty-wellness', 'Beauty & Wellness', 4.0, 'A cosmetologist is a professionally trained individual who is an expert in a wide range of services for beauty, hair, nails, makeup and saree draping.', 840, 870, '801–1000', 'Version', '24 Feb 2022', '18 Feb 2028', 'Beauty & Wellness Sector Skill Council (B&WSSC)', 'Beauty & Wellness Sector Skill Council (B&WSSC)', 'Skincare Services', 'Senior Cosmetologist- Level 5', 'General Qualification', 'N.A.', '{"Theory":"255","Practical":"465","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "35", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-BW-02858-2024-V1-WBSC', 'Assistant Beautician', 'beauty-wellness', 'Beauty & Wellness', 3.0, 'Assistant Beauticians provide a wide range of services that include the care of the hair, skin and nails. A beautician’s primary focus is on improving their client’s outward appearance and helping them to feel better about themselves in general.', 390, 420, '401–600', 'Version', '27 Aug 2024', '26 Aug 2027', 'West Bengal State Council of Technical & Vocational Education and Skill Development (WBSCTVESD)', 'West Bengal State Council of Technical & Vocational Education and Skill Development', 'Beauty Parlour Services', 'Beautician', 'General Qualification', 'N.A.', '{"Theory":"70","Practical":"200","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "36", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-BW-04315-2025-V1-BWSSC', 'Beautician', 'beauty-wellness', 'Beauty & Wellness', 3.0, 'A beautician needs to be aware of the basics of beauty therapy, health, hygiene & safety, and should have knowledge of organic beauty products. The beautician is expected to perform basic hair removal, manicures, pedicures, basic facial treatments, hair care services, and mehndi application.', 390, 420, '401–600', 'Version', '04 Jun 2025', '04 Jun 2028', 'Beauty & Wellness Sector Skill Council (B&WSSC)', 'Beauty & Wellness Sector Skill Council (B&WSSC', 'Skincare Services under Beauty and Salons sub sector', 'Beauty Therapist (NSQF Level 4), Cosmetologist (NSQF Level 4), Aesthetic Skin Technician (NSQF Level 4) , Senior Beauty Therapist (NSQF Level 5), Gig Entrepreneur (Salon/Spa Owner)', 'General Qualification', 'N.A.', '{"Theory":"120","Practical":"240","EmployabilitySkills":"30","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "37", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-BW-06575-2025-V2-BWSSC', 'Junior Beauty Therapist', 'beauty-wellness', 'Beauty & Wellness', 3.0, 'A Junior Beauty Therapist needs to be aware of basic beauty therapy, basic hair styling, basic make-up, and pedicure and manicure services maintaining health, hygiene and safety at the workplace. The job holder needs to be knowledgeable about various beauty products, tools and equipment. The person needs to assist the senior therapists/ stylists for various services in the salon.', 450, 450, '401–600', 'Version', '17 Nov 2022', '18 Nov 2028', 'Beauty & Wellness Sector Skill Council (B&WSSC)', 'Beauty & Wellness Sector Skill Council', 'Skincare Services under Beauty and Salons Sub-sector', 'Beauty Therapist ( level 4), Junior Nail Technician; Assistant Beauty & Wellness Consultant; Assistant Cosmetologist (Level-3)', 'General Qualification', 'N.A.', '{"Theory":"120","Practical":"240","EmployabilitySkills":"30","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "38", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-BW-06577-2025-V2-BWSSC', 'Senior Beauty Therapist', 'beauty-wellness', 'Beauty & Wellness', 5.0, 'A senior beauty therapist is a professionally trained individual who specializes in advance beauty services for both face and body. A senior beauty therapist performs various duties such as providing advance skincare services with electrical equipment, apply makeup, removal of unwanted hair, and hair styling services by maintaining health, safety and hygiene at workplace. The person needs to be knowledgeable on various beauty, hair and make-up products, and a range of beauty treatments like facial electrotherapy, etc.', 600, 600, '401–600', 'Version', '17 Nov 2022', '18 Nov 2028', 'Beauty & Wellness Sector Skill Council (B&WSSC)', 'Beauty & Wellness Sector Skill Council', 'Skincare Services under Beauty and Salons Sub-sector', 'Salon Therapist, Beauty Therapist, Senior Beauty Therapist', 'General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"150","Practical":"300","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "39", "qualification_type": "General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-BW-065922025-V2-BWSSC', 'Assistant Beauty & Wellness Consultant', 'beauty-wellness', 'Beauty & Wellness', 3.0, 'An Assistant Beauty and Wellness Consultant is an operational job-role selling products in salons, spas, promotional locations, etc. She/he supports sales and marketing by displaying products, conducting visual hair and skin analysis, matching hair and skin conditions to product categories, selling, tracking and reporting sales information to the sales executive or manager.', 390, 390, '201–400', 'Version', '17 Nov 2022', '18 Nov 2028', 'Beauty & Wellness Sector Skill Council (B&WSSC)', 'Beauty & Wellness Sector Skill Council', 'Beauty & Wellness Products Training, Sales & Consultancy Services under Product and Sales Sub-sector', 'Beauty & Wellness Consultant (Level-4)', 'General Qualification', 'N.A.', '{"Theory":"90","Practical":"180","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "40", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-BW-065842025-V2-BWSSC', 'Bridal, Fashion and Portfolio Makeup Artist', 'beauty-wellness', 'Beauty & Wellness', 5.0, 'A Bridal, Fashion and Portfolio Make-up Artist is a professionally trained individual in make-up techniques using corrective, highlighting, shading, and air brush make-ups to deliver high quality professional make up. He/ She provides client consultation on various beauty & make-up products; and performs various services such as skincare and make-up by maintaining health, safety and hygiene at workplace. He/ She needs to be knowledgeable on the skin structure, basic beauty therapies, various make-up techniques and range of beauty and make-up products.', 660, 660, '601–800', 'Version', '17 Nov 2022', '18 Nov 2028', 'Beauty & Wellness Sector Skill Council (B&WSSC)', 'Beauty & Wellness Sector Skill Council', 'Make-up Services under Beauty and Salons Sub-sector', 'Makeup Trainer; Beauty Manager/Floor Manager – Salon; Beauty Services Specialist at Level- 6', 'General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"170","Practical":"340","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "41", "qualification_type": "General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-BW-065962025-V2-BWSSC', 'Professional Makeup Artist', 'beauty-wellness', 'Beauty & Wellness', 4.0, 'A Professional Makeup Artist enhances facial aesthetics of the clients for creating custom looks for various formal/informal events/occasions. Basic contouring, color analysis, corrective makeup, ramp makeup, and fantasy makeup with knowledge of various beauty and makeup products are covered.', 510, 600, '401–600', 'Version', '17 Nov 2022', '18 Nov 2028', 'Beauty & Wellness Sector Skill Council (B&WSSC)', 'Beauty & Wellness Sector SkillCouncil', 'Makeup services under Beauty & Salons sub-sector', 'Bridal, Fashion and Portfolio Makeup Artist; Cosmetologist at Level - 5', 'General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"140","Practical":"280","EmployabilitySkills":"30","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "42", "qualification_type": "General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-BW-06578-2025-V2-BWSSC', 'Junior Hair Dresser and Stylist', 'beauty-wellness', 'Beauty & Wellness', 3.0, 'A Junior Hair Dresser & Stylist shampoos and condition hair and scalp, blow dries hair, provides basic haircuts, colors hair, and provides Indian head massage to clients by maintaining health, safety and hygiene at workplace. They assist the hair dresser & stylist in providing other advanced hair dressing & styling services.', 390, 420, '401–600', 'Version', '17 Nov 2022', '18 Nov 2028', 'Beauty & Wellness Sector Skill Council (B&WSSC)', 'Beauty & Wellness Sector Skill Council', 'Hair Dressing & Styling Services under Beauty and Salons Sub-sector', 'Hair Dresser & Stylist, Hair Advisor, Cosmetologist', 'General Qualification,Heritage/Traditional Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"110","Practical":"220","EmployabilitySkills":"30","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "43", "qualification_type": "General Qualification,Heritage/Traditional Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-BW-06579-2025-V2-BWSSC', 'Hair Dresser & Stylist', 'beauty-wellness', 'Beauty & Wellness', 4.0, 'A hair dresser & stylist is a professionally trained individual who specializes in haircare treatments. A hair dresser & stylist performs various duties such as shampooing, trimming, cutting, blow drying, coloring and treatment for hair damage and repair. A hair dresser & stylist needs to understand the intricacies of cutting and styling hair, while also knowing how to keep hair healthy.', 480, 510, '401–600', 'Version', '17 Nov 2022', '18 Nov 2028', 'Beauty & Wellness Sector Skill Council (B&WSSC)', 'Beauty & Wellness Sector Skill Council', 'Hair Dressing & Styling Services under Beauty and Salons Sub-sector', 'Senior Hair Dresser & Stylist, Hair Advisor, Senior Cosmetologist', 'General Qualification,Heritage/Traditional Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"120","Practical":"240","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "44", "qualification_type": "General Qualification,Heritage/Traditional Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-BW-04402025-V2-BWSSC', 'Senior Hair Dresser & Stylist', 'beauty-wellness', 'Beauty & Wellness', 5.0, 'A Senior Hair Dresser & Stylist is a professionally trained individual who specializes in advanced haircare, hair dressing and creative styling. They perform various services like shampooing, hair spa, trimming, creative cutting, blow drying, advanced hair styling, hair relaxing and straightening, perming and neutralizing, creative coloring, and various treatment for hair damage and repair by maintaining health, safety and hygiene at workplace. A Hair Dresser & Stylist needs to understand the intricacies of advance hair cutting and styling, while also knowing how to keep the hair healthy.', 630, 660, '601–800', 'Version', '17 Nov 2022', '18 Nov 2028', 'Beauty & Wellness Sector Skill Council (B&WSSC)', 'Beauty & Wellness Sector Skill Council', 'Hair Dressing & Styling Services under Beauty and Salons Sub-sector', 'Hair Advisor, Senior Cosmetologist at Level- 5 

Beauty Services Specialist, Trainer- Hair Dressing & Styling Services, Hair Studio Manager at Level- 6', 'General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"170","Practical":"340","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "45", "qualification_type": "General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-BW-065922025-V2-BWSSC', 'Yoga Trainer (B&W)', 'beauty-wellness', 'Beauty & Wellness', 4.0, 'A Yoga Trainer (B&W) is responsible to demonstrate the yoga postures, asanas, pranayamas, meditation and relaxation techniques for the clients. The individual must exhibit knowledge of the principles and practices of basic Yogic techniques for holistic wellbeing in order to explain and respond to the client’s questions.', 480, 480, '401–600', 'Version', '17 Nov 2022', '18 Nov 2028', 'Beauty & Wellness Sector Skill Council (B&WSSC)', 'Beauty & Wellness Sector Skill Council (B&WSSC)', 'Yoga Services from Yoga sub-sector', 'Master Yoga Trainer', 'General Qualification,Heritage/Traditional Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"110","Practical":"220","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "46", "qualification_type": "General Qualification,Heritage/Traditional Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-5.5-BW-004412025-V2-BWSSC', 'Senior Yoga Instructor (B&W)', 'beauty-wellness', 'Beauty & Wellness', 5.5, 'A Senior Yoga Instructor (B&W) is a professionally trained individual with an advanced training in Yoga for holistic wellness, happiness and harmony; and is able to work with the clients by conducting the advanced yoga asanas, advanced pranayamas, advanced meditations and relaxation techniques to counterbalance unhealthy lifestyle, and manage a healthy body with a sound mind. S/he is also expected to train Yoga Trainers on the intricacies of yoga services to enhance the quality of life.', 600, 660, '601–800', 'Version', '17 Nov 2022', '18 Nov 2028', 'Beauty & Wellness Sector Skill Council (B&WSSC)', 'Beauty & Wellness Sector Skill Council (B&WSSC)', 'Senior Yoga Trainer (B&W) (Yoga Services)', 'Master Yoga Trainer', 'General Qualification,Heritage/Traditional Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"120","Practical":"240","EmployabilitySkills":"90","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "47", "qualification_type": "General Qualification,Heritage/Traditional Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-BW-065812025-V2-BWSSC', 'Junior Nail Technician', 'beauty-wellness', 'Beauty & Wellness', 3.0, 'A Junior Nail Technician performs various duties such as manicure and pedicure and assists the nail technician in providing advanced nailcare services like nail art, nail tips and nail enhancement. The Junior Nail Technician needs to be knowledgeable on structure and function of nails, various nailcare services maintaining health, safety and hygiene at workplace, and range of nail products.', 390, 390, '201–400', 'Version', '17 Nov 2022', '18 Nov 2028', 'Beauty & Wellness Sector Skill Council (B&WSSC)', 'Beauty & Wellness Sector Skill Council', 'Nailcare Services under Beauty and Salons Sub-sector', 'HP- Pedicurist & Manicurist; Assistant Beauty & Wellness Consultant 

VP- Nail Technician', 'General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"100","Practical":"200","EmployabilitySkills":"60","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "48", "qualification_type": "General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-BW-065822025-V2-BWSSC', 'Nail Technician', 'beauty-wellness', 'Beauty & Wellness', 4.0, 'A Nail Technician performs various services such as manicure, pedicure, advanced nail care services like nail art, nail enhancement, nail overlay, gel polish application, refilling, and nail electric nail drilling by maintaining health, safety and hygiene at workplace. The Nail Technician needs to be knowledgeable on the nail structure and various nailcare products and services.', 450, 450, '401–600', 'Version', '17 Nov 2022', '18 Nov 2028', 'Beauty & Wellness Sector Skill Council (B&WSSC)', 'Beauty & Wellness Sector Skill Council', 'Nailcare Services under Beauty and Salons Sub-sector', 'Nail Technician, Nail Art Specialist, Salon Manager, Nail Educator/Trainer, Product Educator, Nail Product Sales Representative', 'General Qualification', 'N.A.', '{"Theory":"110","Practical":"220","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "49", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-BW-065832025-V2-BWSSC', 'Pedicurist and Manicurist', 'beauty-wellness', 'Beauty & Wellness', 3.0, 'A pedicurist and manicurist cleans, shapes, and polishes customer’s finger nails and toe nails. A Pedicurist and Manicurist needs to be aware of the pedicure and manicure services, maintaining health, safety, and hygiene at workplace. They need to be knowledgeable about various nail products.', 390, 420, '401–600', 'Version', '17 Nov 2022', '18 Nov 2028', 'Beauty & Wellness Sector Skill Council (B&WSSC)', 'Beauty & Wellness Sector Skill Council (B&WSSC)', 'Nailcare Services under Beauty and Salons Sub-sector', 'Horizontal Progression- Junior Nail Technician 
Vertical Progression-Nail Technician', 'General Qualification', 'N.A.', '{"Theory":"100","Practical":"200","EmployabilitySkills":"60","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "50", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-BW-065852025-V2-BWSSC', 'Junior Spa Therapist', 'beauty-wellness', 'Beauty & Wellness', 3.0, 'A Junior Spa Therapist needs to be aware of the basics of spa therapy, health and hygiene, safety and needs to be knowledgeable about various products and massage techniques. Junior spa therapist is expected to assist the senior spa therapist in providing spa services', 390, 390, '201–400', 'Version', '17 Nov 2022', '18 Nov 2028', 'Beauty & Wellness Sector Skill Council (B&WSSC)', 'Beauty & Wellness Sector Skill Council', 'Spa Services under Alternate Therapy & Rejuvenation Sub-sector', 'Assistant Massage Therapist level 3

Spa Therapist level 4', 'General Qualification', 'N.A.', '{"Theory":"90","Practical":"180","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "51", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-BW-065862025-V2-BWSSC', 'Spa Therapist', 'beauty-wellness', 'Beauty & Wellness', 4.0, 'The Spa Therapist is responsible to provide a range of professional Spa services agreed with the guests in accordance with the approved organizations brand standards of performance and sequences of services. The individual must exhibit knowledge of the principles and practice of spa therapies. The individual is responsible for setting up and stocking the treatment area and maintaining accurate written records of guest’s treatments.', 480, 480, '401–600', 'Version', '17 Nov 2022', '18 Nov 2028', 'Beauty & Wellness Sector Skill Council (B&WSSC)', 'Beauty & Wellness Sector Skill Council', 'Spa Services under Alternate Therapy & Rejuvenation Sub-sector', 'Junior Spa Therapist, Spa Therapist, Senior Spa Therapist, Spa Supervisor, Spa Manager, Spa Director', 'General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"110","Practical":"220","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "52", "qualification_type": "General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-BW-065872025-V2-BWSSC', 'Wellness Neurotherapist', 'beauty-wellness', 'Beauty & Wellness', 3.0, 'A wellness neurotherapist may carry out the work in a neurotherapy facility or at the client site. The job includes setting up the work area as per requirement, preparation of the set-up, positioning the client and carrying out the requisite rejuvenation procedure. The job holder must adhere to instructions given by responsible seniors including Master or Senior Wellness Neurotherapist while carrying out therapy and related procedures.', 450, 450, '401–600', 'Version', '17 Nov 2022', '18 Nov 2028', 'Beauty & Wellness Sector Skill Council (B&WSSC)', 'Beauty & Wellness Sector Skill Council (B&WSSC)', 'Neurotherapy Services under Alternate Therapy & Rejuvenation Sub-sector', 'Senior Wellness Neurotherapist', 'General Qualification,Heritage/Traditional Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"100","Practical":"200","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "53", "qualification_type": "General Qualification,Heritage/Traditional Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-BW-065882025-V2-BWSSC', 'Senior Wellness Neurotherapist', 'beauty-wellness', 'Beauty & Wellness', 4.0, 'A senior wellness neurotherapist is responsible for recommending appropriate wellness neurotherapy procedure to clients with health problems. The individual should be capable of formulating procedure based on required procedure duration, type of pressing techniques, number of repetitions, location in the body, etc', 540, 540, '401–600', 'Version', '17 Nov 2022', '18 Nov 2028', 'Beauty & Wellness Sector Skill Council (B&WSSC)', 'Beauty & Wellness Sector Skill Council (B&WSSC)', 'Neurotherapy Services under Alternate Therapy & Rejuvenation Sub-sector', 'Master Wellness Neurotherapist', 'General Qualification,Heritage/Traditional Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"120","Practical":"240","EmployabilitySkills":"60","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "54", "qualification_type": "General Qualification,Heritage/Traditional Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-BW-065892025-V2-BWSSC', 'Master Wellness Neurotherapist', 'beauty-wellness', 'Beauty & Wellness', 5.0, 'A master wellness neurotherapist is responsible for assessing the state of mental, physical and emotional wellbeing of clients seeking for neurotherapy treatments for overall wellness. The individual should guide or suggest senior neurotherapists by recommending appropriate wellness neurotherapy treatments to suffice the client’s needs in compliant with relevant organisations quality standards', 600, 600, '401–600', 'Version', '17 Nov 2022', '18 Nov 2028', 'Beauty & Wellness Sector Skill Council (B&WSSC)', 'Beauty & Wellness Sector Skill Council (B&WSSC)', 'Neurotherapy Services under Alternate Therapy & Rejuvenation Sub-sector', 'Entrepreneur', 'Heritage/Traditional Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"120","Practical":"240","EmployabilitySkills":"90","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "55", "qualification_type": "Heritage/Traditional Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-BW-065902025-V2-BWSSC', 'Gym Assistant (B&W)', 'beauty-wellness', 'Beauty & Wellness', 3.0, 'A The Gym Assistant (B&W) provides assistance and support to the clients in the gym. S/he maintains the discipline in the work area with regards to punctuality, personal neatness, cleanliness, and hygiene. S/he ensures that the equipment and free weights should be safely used by the clients', 390, 390, '201–400', 'Version', '17 Nov 2022', '18 Nov 2028', 'Beauty & Wellness Sector Skill Council (B&WSSC)', 'Beauty & Wellness Sector Skill Council (B&WSSC)', 'Fitness Services under Personal Services Sub-sector', 'Yoga Assistant level 3

Personal Trainer level 4', 'General Qualification', 'N.A.', '{"Theory":"90","Practical":"180","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "56", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
