INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-3.5-BF-02169-2024-V1-CII', 'Sales Executive (Banking & Finance)', 'bfsi', 'BFSI', 3.5, 'Individuals in this role will be responsible for promoting and selling the financial products (Banking, Insurance etc.)  and services to individual and corporate customers. He/she plays a crucial role in achieving sales targets, credit cards selling, new account opening, building customer relationships, and contributing to the overall growth and business development of the bank.', 900, 900, '801–1000', 'Version', '15 Mar 2024', '14 Mar 2027', 'Confederation of Indian Industries (CII)', 'Confederation of Indian Industry', 'Sales and Marketing', 'Sr. Sales Executive – (Banking & Finance) (NSQF Level 4)', 'OEM Qualification', 'N.A.', '{"Theory":"120","Practical":"240","EmployabilitySkills":"30","OJT_Mandatory":"510"}', false, '{}'::text[], '{"source_row": "4", "qualification_type": "OEM Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_48.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-BF-00133-2023-V1.1-BFSISSC', 'Accounts Assistant', 'bfsi', 'BFSI', 4.0, 'Accounts Assistant maintains records of receipts, payments and provisions; compiles periodic bank reconciliation statement and depreciation schedules and presents any other defined report to senior(s).', 480, 480, '401–600', 'Version', '30 Jun 2022', '30 Jun 2025', 'Banking financial services and insurance sector skill council (BFSISSC)', 'BFSI Sector Skill Council of India (BFSISSC)', 'LENDING, FUND INVESTMENT & SERVICES, PAYMENTS, BROKING, BFSI PROCESSING', 'Assistant Manager < Deputy Manager< Accounts Manager', 'General Qualification', 'N.A.', '{"Theory":"126","Practical":"144","EmployabilitySkills":"60","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "5", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_48.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-BF-02349-2024-V1.1-BFSISSC', 'Business Correspondent/Facilitator', 'bfsi', 'BFSI', 4.0, 'The individual at work is responsible for sourcing prospective customers, introducing banking products to the unbanked market segment, and facilitating business transactions for the existing customers. The incumbent is also responsible for selling banking products and services, opening accounts, and assisting the bank in collecting receivables including bad debt', 480, 480, '401–600', 'Version', '19 Dec 2018', '24 May 2025', 'Banking financial services and insurance sector skill council (BFSISSC)', 'BFSI Sector Skill Council of India', 'Lending', 'Business Correspondent & Business Facilitator- Insurance Agent (Fund Investment and service)- Mutual Fund Distributor (Fund Investment and service)- RM -Bancassurance/ Insurance (Fund Investment and service)- Financial Inclusion officer (Lending)', 'General Qualification', 'N.A.', '{"Theory":"126","Practical":"144","EmployabilitySkills":"60","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "6", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_48.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-BFSI-01259-2023-V1-ICAI', 'Certified Executive in Financial Planning and Cost & Management Accounting (Defence)', 'bfsi', 'BFSI', 5.0, 'Certified Executive in Financial Planning and Cost & Management Accounting (Defence) is designed specifically for the Defense Personnel. This course is to be conducted by the Institute of Cost Accountants of India in association with Additional Directorate General of Army Education, Ministry of Defense, Govt. of India. This Course is a short term course having 20 modules on Financial Planning & Budgeting. The candidates will be able to learn competencies in Financial Management, Government Financial System, General Financial Rules and Financial Regulations, Capital Procurement in Indian Army, National Budgetary Process, Defence Budget, Revenue Procurement in Indian Army, E-Procurement & Government e Market(GeM), CVC guidelines etc with specific reference to Defence Forces enabling them to perform accounting work in their organization. The detailed course curriculum is enclosed.', 480, 480, '401–600', 'Version', '01 Nov 2023', '01 Nov 2026', 'The Institute of Cost Accountants of India (ICAI)', 'The Institute of Cost Accountants of India', 'Certified Executive in Financial Planning and Cost & Management Accounting (Defence) (Level -5)', 'Professional Progression
Graduation, Certified Executive in Financial Planning and Cost & Management Accounting (Defence) (Level -5), Senior Accountant (Level -5.5)

Academic Progression
CMA Intermediate Course (Level -5), CMA Final Course (Level 5.5), Qualified CMA (Level 6)', 'General Qualification', 'N.A.', '{"Theory":"160","Practical":"140","EmployabilitySkills":"60","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "7", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_48.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-BFSI-02182-2024-V1-ICAI', 'CERTIFICATE IN ACCOUNTING TECHNICIANS (CAT)', 'bfsi', 'BFSI', 4.0, 'To meet the huge demand for entry level Accountants in India, The Institute of Cost Accountants of India has launched a short term Course i.e. Certificate in Accounting Technicians (CAT) for 12th (10+2) passed and Under Graduates. This Course has been introduced in consultation with Ministry of Corporate Affairs, Government of India.

A Certified Accounting Technician (CAT) Course qualified candidate is trained to meet the demands of today''s accounting requirements in addition to participating on the company''s management team. The candidates will be able to learn the competencies in the maintenance of accounts, preparation of Tax Returns, Filling of Returns under Companies Act, Filling of Returns under Income Tax, GST, Customs Act, Export & Import documentation etc.  The detailed course curriculum is enclosed.', 480, 480, '401–600', 'Version', '15 Mar 2024', '15 Mar 2027', 'The Institute of Cost Accountants of India (ICAI)', 'The Institute of Cost Accountants of India', 'CERTIFICATE IN ACCOUNTING TECHNICIANS (CAT)', 'Account Assistant / Accountant - Level 4.5', 'General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"210","Practical":"150","EmployabilitySkills":"30","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "8", "qualification_type": "General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_48.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-BF-00135-2023-V1.1-BFSISSC', 'GST  Assistant', 'bfsi', 'BFSI', 4.0, 'The person appointed by any company, is responsible for maintaining records of accounts for the purpose of making preparing periodic reports around GST from time to time. Individual is authorized to perform functions relating to filling returns by the applicable due dates.', 480, 480, '401–600', 'Version', '30 Jun 2022', '30 Jun 2025', 'Banking financial services and insurance sector skill council (BFSISSC)', 'BFSI Sector Skill Council of India', 'FINANCE & ACCOUNTS', 'Assistant Manager - Taxation > Deputy Manager - Finance / Accounts > Manager - Finance', 'General Qualification', 'N.A.', '{"Theory":"126","Practical":"144","EmployabilitySkills":"60","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "9", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_48.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
