INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-3.5-BF-03458-2025-V1-VBABSS.', 'Introduction to Tally Operations & GST Calculations', 'bfsi', 'BFSI', 3.5, 'The course” Introduction to Tally Operations & GST calculations” enables the student to understand the importance of accounting with special focus for GST entries, familiarity with accounting assumptions and concepts, working knowledge of recording financial transactions on Tally, understanding GST concepts calculations and use of Tally for generating GST reports and liability. Understanding of Tally structure i.e. Creating company, masters and setting security features along with working knowledge of Data Entry.', 120, 120, '1–200', 'Version', '24 Jan 2025', '23 Jan 2028', 'Vidya Bharti Akhil Bhartiya Shiksha Sansthan', 'Vidya Bharti Akhil Bhartiya Shiksha Sansthan', 'Accounts Assistant', 'Accounting operation and GST compliances', 'Cross Sectoral Qualification,Dual/Flexi Qualification,Multi-Skill Qualification,National Occupational Standard,Upskilling Qualification', 'N.A.', '{"Theory":"30","Practical":"60","EmployabilitySkills":"4","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "17", "qualification_type": "Cross Sectoral Qualification,Dual/Flexi Qualification,Multi-Skill Qualification,National Occupational Standard,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_48.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-04-BF-03459-2025-V1-VBABSS', 'Accounting Operations & GST Compliances', 'bfsi', 'BFSI', 4.0, 'The course on “Accounting Operations & GST Compliances”  will impart working knowledge of advanced accounting skills ie. Accounting equations, reconciliations, identifying errors and their rectification. Preparing final accounts, understanding, preparation and filing of GST returns, deposit of GST, Generating E-way bills. Practical working on Tally reports for GST returns, preparing invoices and taking reports from Tally software e.g. Balance sheet, profit and Loss A/C, GSTR/2A & 2B and import and export of data on Tally.', 120, 120, '1–200', 'Version', '24 Jan 2025', '23 Jan 2028', 'Vidya Bharti Akhil Bhartiya Shiksha Sansthan', 'Vidya Bharti Akhil Bhartiya Shiksha Sansthan', 'Accountant', 'Accounts Officer, Finance Manager', 'Cross Sectoral Qualification,Dual/Flexi Qualification,Multi-Skill Qualification,National Occupational Standard,Upskilling Qualification', 'N.A.', '{"Theory":"30","Practical":"60","EmployabilitySkills":"4","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "18", "qualification_type": "Cross Sectoral Qualification,Dual/Flexi Qualification,Multi-Skill Qualification,National Occupational Standard,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_48.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-4.5-BF-03899-2025-V1-IIBF', 'Fundamentals of Retail Banking', 'bfsi', 'BFSI', 4.5, 'IIBF has designed and developed a comprehensive course in Retail Banking to develop skills of the learners desirous of working in Retail Banking vertical of the Banks and Financial Institutions in the BFSI sector. Learners after completion of this course shall gain sufficient proficiency to work as Relationship Managers, Customer Service Executives, Front Desk Managers, Retail Banking Loan Officer, Retail Banking Product Manager, Credit Officer- Retail Banking, Credit Appraising Officer- Retail Banking, and Customer Service Assistants etc.  in retail banking segment of the banks and financial institutions
This course is developed to cover broadly all aspects of retail banking such as Retail Banking products and services, Sales and Marketing, Digital Banking, Payment System, Credit administration, and Monitoring, Recovery, and Legal aspects, Grievances Redressal Mechanism, Soft Skills communication, negotiation, and presentation skills required by any Retail Banking Professional.', 120, 120, '1–200', 'Version', '08 May 2025', '07 May 2028', 'Indian Institute of Banking and Finance (IIBF)', 'Indian Institute of Banking and Finance', 'Frontline Officer', 'Assistant Manager (Credit/Retail Banking)', 'Upskilling Qualification', 'N.A.', '{"Theory":"48","Practical":"72","EmployabilitySkills":"00","OJT_Mandatory":"00"}', false, '{}'::text[], '{"source_row": "19", "qualification_type": "Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_48.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
