INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-4.5-CG-01809-2024-V1-CGSCCGSC', 'CNC Turning', 'capital-goods-manufacturing', 'Capital Goods & Manufacturing', 4.5, 'The individual in this job is responsible for a broad variety of machining processes, such as grinding, welding, electrical discharging, milling and also turning.
The CNC Turning machinist uses a computer to tell the lathe how to move the tools and cut the part to the desired shape. They must also set up the lathe with all the necessary clamping devices, support devices, and cutting tools. These tools can cut almost every material (stainless steel, plastic, soft steel, aluminium, bronze, and so on). But the machinist has to choose well to avoid temperature variations, tool wear or vibration. Those factors influence the product and it can result in poor quality.
When the machine starts cutting material, the machinist makes sure that the dimensions exactly fit the customer specifications. For this, very accurate inspection tools are used. Once the machine is set up, the CNC-Turning machinist also monitors and optimizes the processes, to achieve even faster and better results for all the following parts.', 510, 510, '401–600', 'Version', '06 Feb 2024', '06 Feb 2026', 'Capital Goods and Strategic Skill Council (CGSSC)', 'Capital Goods and Strategic Skill Council', 'Design', 'CNC Programmer, Manufacturing Engineer', 'Future Skills Qualification', 'N.A.', '{"Theory":"150","Practical":"270","EmployabilitySkills":"00","OJT_Mandatory":"50"}', false, '{}'::text[], '{"source_row": "26", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_56.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-4.5-CG-01808-2024-V1-CGSC', 'Mechanical Engineering CAD', 'capital-goods-manufacturing', 'Capital Goods & Manufacturing', 4.5, 'Mechanical engineering computer aided design (CAD) is the use of computer systems to assist in the creation, modification, analysis, or optimization of an engineering design. CAD software is used to increase the productivity of the designer, improve the quality of design, improve communication through documentation, and create a database for manufacturing. CAD output is often in the form of electronic files for print, manufacturing documentation, or other manufacturing processes.
The technical and engineering drawings and images must convey information such as materials, processes, dimensions and tolerances according to application-specific conventions. CAD may be used to design curves and figures in two-dimensional (2D) space or curves, surfaces and solids in three-dimensional (3D) space. CAD is also used to produce computer animation for the special effects used in, for example, advertising and technical manuals.CAD is an important industrial art and is the way projects come true. It is extensively used in many applications, including automotive, ship building and aerospace industries, and in industrial design. The CAD process and outputs are essential to successful solutions for engineering and manufacturing problems. CAD software helps us explore ideas, visualize concepts through photorealistic renderings and movies, and simulates how a design project will perform in the real world.', 510, 510, '401–600', 'Version', '06 Feb 2024', '06 Feb 2026', 'Capital Goods and Strategic Skill Council (CGSSC)', 'Capital Goods and Strategic Skill Council', 'Design', 'Design Engineer, CAD Specialist, Product Development Engineer, Simulation and Analysis Engineer, Entrepreneurship', 'Future Skills Qualification', 'N.A.', '{"Theory":"150","Practical":"270","EmployabilitySkills":"00","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "27", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_56.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-4.5-CG-01810-2024-V1-CGSC', 'CNC Milling', 'capital-goods-manufacturing', 'Capital Goods & Manufacturing', 4.5, 'A CNC Milling Machinist is responsible for the operation and programming of computer numerical control (CNC) milling machines to produce precision components according to engineering specifications. This role involves setting up machines, selecting appropriate tools, and programming CNC software to create toolpaths for efficient material removal. CNC Milling Machinists monitor machine operations, make adjustments as necessary, and conduct regular inspections using precision measuring instruments to ensure the quality of machined parts. Troubleshooting, problem solving, and adherence to safety protocols are essential aspects of the job. Additionally, CNC Milling Machinists may be involved in routine machine maintenance, documentation of machining processes, and collaboration with other team members to optimize workflows and meet production goals. Continuous improvement and staying current with advancements in CNC technology are also key aspects of the role.', 510, 510, '401–600', 'Version', '06 Feb 2024', '06 Feb 2026', 'Capital Goods and Strategic Skill Council (CGSSC)', 'Capital Goods and Strategic Skill Council', 'Design', 'CNC Programmer, Manufacturing Engineer, CAD/CAM Engineer', 'Future Skills Qualification', 'N.A.', '{"Theory":"150","Practical":"270","EmployabilitySkills":"00","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "28", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_56.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
