INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-4.5-IT-00620-2023-V1-SVSU', 'Welding Robot Operator', 'capital-goods-manufacturing', 'Capital Goods & Manufacturing', 4.5, 'The purpose of the qualification is to train the students in Robotic Welding operations and to upskill them in order to make them employable in the field of Automobile Industry and Industry Automation.', 540, 540, '401–600', 'Version', '23 Jun 2023', '23 Jun 2026', 'Shri Vishwakarma Skill University', 'Shri Vishwakarma Skill University', 'Welding', 'Welding Robot Supervisor ->Welding Robot Assistant Manager -> Welding Robot Manager', 'General Qualification', 'N.A.', '{"Theory":"135","Practical":"195","EmployabilitySkills":"90","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "54", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_56.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-5.5-CG-02043-2024-V1-CGSC', 'Digital Factory Automation engineer', 'capital-goods-manufacturing', 'Capital Goods & Manufacturing', 5.5, 'Industry 4.0 plays a vital role in new-age digital factories to achieve desired user-friendly agile,
flexible, and cost-effective, sustainable, self-reliance enterprise integrated horizontally and vertically -
as well as with vendors, suppliers and consumers. Digital factory Implements the system architecture,
performs engineering tasks, reconfigurations, and upgrades. It evangelizes Industry 4.0 cultural
ecosystems and helps relevant skill development thereby upskill and reskill', 600, 600, '401–600', 'Version', '31 Jan 2024', '30 Jan 2027', 'Capital Goods and Strategic Skill Council (CGSSC)', 'Capital Goods & Strategic Skill Council (CGSSC)', 'Design', 'Senior Engineer, Manager, Consultant- Digital Factory', 'Future Skills Qualification', 'N.A.', '{"Theory":"160","Practical":"290","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "55", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_56.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-5.5-CG-02048-2024-V1-CGSC', 'Additive Manufacturing Design and Application Engineer', 'capital-goods-manufacturing', 'Capital Goods & Manufacturing', 5.5, 'The candidate will play a crucial role in advancing the additive manufacturing capabilities, with a focus on computer graphics (CG) applications. As a CG Additive Manufacturing Design & Application Engineer, He/She will be responsible for designing and optimizing 3D printed components for various applications, leveraging your expertise in both additive manufacturing and computer graphics.', 570, 570, '401–600', 'Version', '31 Jan 2024', '30 Jan 2027', 'Capital Goods and Strategic Skill Council (CGSSC)', 'Capital Goods & Strategic Skill Council (CGSSC)', 'Design', 'Senior Engineer, Project Manager/ Consultant', 'Future Skills Qualification', 'N.A.', '{"Theory":"160","Practical":"260","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "56", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_56.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-5.5-CG-02041-2024-V1-CGSC', 'Robotics and Automation COBOTS Engineer', 'capital-goods-manufacturing', 'Capital Goods & Manufacturing', 5.5, 'Industry 4.0 disruptive technologies that includes the robotics, automation with special focus on collaborative robots in short called as COBOTS are game changer for smart digital manufacturing. COBOTS play a vital role in digital manufacturing especially in shop floor productions. COBOTS is the need of the hour. The individual is expected to develop expertise on the basics and concepts of COBOTS, architecture, anatomy, installation, commissioning and configuring and application in manufacturing. He / She develop hands-on experience in programming using ROS (Robot Operating Systems)', 570, 570, '401–600', 'Version', '31 Jan 2024', '30 Jan 2027', 'Capital Goods and Strategic Skill Council (CGSSC)', 'Capital Goods & Strategic Skill Council (CGSSC)', 'design', 'Senior Robotics & Automation Engineer, Specialized COBOTS Consultant', 'Future Skills Qualification', 'N.A.', '{"Theory":"160","Practical":"260","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "57", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_56.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-5.5-CG-02044-2024-V1-CGSC', 'Industrial automation safety engineer', 'capital-goods-manufacturing', 'Capital Goods & Manufacturing', 5.5, 'The industrial automation is a subset of industry 4.0 disruptive technologies that facilitates the digital
manufacturing leading to smart implements of product development. The availability of Industrial
Internet of Things (IIoT) machine-to-machine connectivity enhances the safety of the individuals. The
devices and sensors interconnected with control room and cloud-based analytics provides the
complete portrait of manufacturing systems. The individual engineers need to understand the
concepts, ideas and implementation of industrial automation and also the must unlearn and relearn
the safety practices through capacity building programs', 570, 570, '401–600', 'Version', '31 Jan 2024', '30 Jan 2027', 'Capital Goods and Strategic Skill Council (CGSSC)', 'Capital Goods & Strategic Skill Council (CGSSC)', 'Service', 'Sr. Engineer, Quality Control Manager, Consultant/ Specialist- Industrial Automation Safety', 'Future Skills Qualification', 'N.A.', '{"Theory":"160","Practical":"260","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "58", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_56.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-5.5-CG-02042-2024-V1-CGSC', 'Predictive Maintenance Engineer', 'capital-goods-manufacturing', 'Capital Goods & Manufacturing', 5.5, 'Predictive Maintenance (PdM) Engineer measures and monitors specific asset condition parameters 
(using appropriate condition monitoring techniques, tools/devices, and technologies), their trends, 
taking note of significant changes that could be indicative of an impending failure and regularly 
monitors the condition and performance of assets during their normal operation, to reduce the 
likelihood of failures.  
Performing the data analysis and diagnostics of the asset condition, the PdM specialist attempts to 
predict when equipment failure/component failure could occur (based on certain factors) and initiates 
timely maintenance (scheduled maintenance and corrective maintenance) for prevention of any 
functional failure.', 600, 600, '401–600', 'Version', '31 Jan 2024', '30 Jan 2027', 'Capital Goods and Strategic Skill Council (CGSSC)', 'Capital Goods & Strategic Skill Council', 'Maintenance', 'Specialized Safety Engineer, Quality Control Specialist', 'Future Skills Qualification', 'N.A.', '{"Theory":"160","Practical":"290","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "59", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_56.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-5.5-CG-02046-2024-V1-CGSC', 'Digital Twin engineer', 'capital-goods-manufacturing', 'Capital Goods & Manufacturing', 5.5, 'A Digital Twin engineer will play a pivotal role in developing and maintaining digital twin solutions for our
complex systems and processes. The CG Digital Twin Engineer will collaborate with cross-functional
teams to create virtual replicas that enhance understanding, simulation, and optimization of physical
assets and systems', 570, 570, '401–600', 'Version', '31 Jan 2024', '30 Jan 2027', 'Capital Goods and Strategic Skill Council (CGSSC)', 'Capital Goods and Strategic Skill Council', 'Design', 'Digital Twin- Senior Engineer/ Process Optimization Engineer, Project Manager, Specialist/ Consultant', 'Future Skills Qualification', 'N.A.', '{"Theory":"160","Practical":"260","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "60", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_56.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-5.5-CG-02039-2024-V1-CGSC', 'IIoT SYSTEM ARCHITECTURE ENGINEER', 'capital-goods-manufacturing', 'Capital Goods & Manufacturing', 5.5, 'Industry 4.0 IIOT System Architecture Engineer plays a vital role in new-age Smart e-factories to achieve desired user-friendly agile, flexible, and cost-effective, sustainable, self-reliance enterprise integrated horizontally and vertically - as well as with vendors, suppliers, and consumers. IIOT Implements the system architecture, performs engineering tasks, reconfigurations, and upgrades. It evangelizes Industry 4.0 cultural ecosystems and helps relevant skill development thereby upskill and reskill.', 600, 600, '401–600', 'Version', '31 Jan 2024', '30 Jan 2027', 'Capital Goods and Strategic Skill Council (CGSSC)', 'Capital Goods & Strategic Skill Council (CGSSC)', 'Design', 'Senior Digital Factory Automation Engineer, Digital Factory Manager', 'Future Skills Qualification', 'N.A.', '{"Theory":"160","Practical":"290","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "61", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_56.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-5.5-CG-02040-2024-V1-CGSC', 'IIoT Data Analytics Engineer', 'capital-goods-manufacturing', 'Capital Goods & Manufacturing', 5.5, 'IIoT Data Analytics Engineer facilitate in installation, configuring and connects disruptive sensors and
other devices in the industrial IIoT network using LoRaWAN technology, specified optical fibre cables
and connectors. He/she develop expertise in data collecting, cleaning, formatting, conditional
formatting, data visualization, data consolidation, commissioning and troubleshooting of IIoT systems.
The individual skilled engineers can assemble and test simple devices and systems through device
prototypes.', 570, 570, '401–600', 'Version', '31 Jan 2024', '31 Jan 2027', 'Capital Goods and Strategic Skill Council (CGSSC)', 'Capital Goods and Strategic Skill Council
(CGSSC)', 'Service', 'Specialized Safety Engineer, Quality Control Specialist', 'Future Skills Qualification', 'N.A.', '{"Theory":"130","Practical":"290","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "62", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_56.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-5.5-CG-02047-2024-V1-CGSC', 'Advanced Mechatronics Engineer', 'capital-goods-manufacturing', 'Capital Goods & Manufacturing', 5.5, 'An Advanced Mechatronics Engineer is a professional responsible for designing, developing, and implementing advanced mechatronic systems and solutions within the capital goods industry. Capital goods refer to long-term assets used in the production of goods and services, including machinery, equipment, and technology.', 570, 570, '401–600', 'Version', '31 Jan 2024', '30 Jan 2027', 'Capital Goods and Strategic Skill Council (CGSSC)', 'Capital Goods & Strategic Skill Council (CGSSC)', 'Design', 'Sr. Engineer/ Simulationist, Project Manager Mechatronics', 'Future Skills Qualification', 'N.A.', '{"Theory":"160","Practical":"260","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "63", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_56.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-5.5-CG-02049-2024-V1-CGSC', 'Robotics & Automation PLC SCADA Engineer', 'capital-goods-manufacturing', 'Capital Goods & Manufacturing', 5.5, 'The individual will play a crucial role in designing, implementing, and maintaining Programmable Logic Controller
(PLC) and Supervisory Control and Data Acquisition (SCADA) systems for our cutting-edge robotics and
automation projects. This role offers an exciting opportunity to contribute to the development of innovative
solutions that drive efficiency and productivity in the field of robotics and automation.', 570, 570, '401–600', 'Version', '31 Jan 2024', '30 Jan 2027', 'Capital Goods and Strategic Skill Council (CGSSC)', 'Capital Goods and Strategic Skill Council', 'Design', 'Automation Architect
Automation Director', 'Future Skills Qualification', 'N.A.', '{"Theory":"160","Practical":"260","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "64", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_56.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-5.5-CG-02045-2024-V1-CGSC', 'Augmented Reality System Designer', 'capital-goods-manufacturing', 'Capital Goods & Manufacturing', 5.5, 'Individuals at this job are responsible for designing, maintaining, and evaluating the
implementation for AR/VR projects. They ensure the proper usage of tools and delivery and
also monitor the process during the testing and deployment phase', 570, 570, '401–600', 'Version', '31 Jan 2024', '30 Jan 2027', 'Capital Goods and Strategic Skill Council (CGSSC)', 'Capital Goods and Strategic Skill Council', 'Design', 'AR Process Optimization Engineer, AR System Manager, Specialist- AR Designer, Consultant', 'Future Skills Qualification', 'N.A.', '{"Theory":"160","Practical":"260","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "65", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_56.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-3.5-CG-00774-2023-V1-NTTF', 'CONVENTIONAL AND CNC MACHINIST', 'capital-goods-manufacturing', 'Capital Goods & Manufacturing', 3.5, 'The Candidate will be able to operate Conventional and CNC Machine Tools.
The subjects covered in this Programme are - CNC Technology, Production technology, 
Electrical Technology, Metrology, Material Technology, CAD, and Intensive Practice on 
Conventional and CNC Machine Tools.', 1200, 1200, '1001–1200', 'Version', '31 Aug 2023', '31 Aug 2026', 'Nettur Technical Training Foundation (NTTF)', 'NETTUR TECHNICAL TRAINING FOUNDATION 23/24, II PHASE, PEENYA INDUSTRIAL AREA, BENGALURU – 560058, KARNATAKA', 'Machinist, Machine maintenance, CNC programmer', 'CNC Machine shop supervisor, Conventional/CNC Machinist, CNC Programmer, Machine shop supervisor, Machine Shop Manager in Die & Mould', 'General Qualification', 'N.A.', '{"Theory":"300","Practical":"720","EmployabilitySkills":"60","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "66", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_56.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-4.5-CG-03270-2024-V1-ASAP', 'Fundamentals of Calibration and Quality concepts of Metrological Instruments', 'capital-goods-manufacturing', 'Capital Goods & Manufacturing', 4.5, 'This course offers comprehensive training in metrology, calibration, and quality management for industrial applications. It covers key concepts like accuracy, precision, and traceability, along with hands-on calibration techniques for instruments such as electrical and thermal gauges, pressure meters, and volumetric glassware. Students learn to calculate measurement uncertainties, prepare calibration reports, and address non-conformance through corrective actions, statistical quality control, and FMEA. Real-world case studies enhance problem-solving skills, equipping students to ensure effective quality assurance and compliance in industrial settings.', 45, 45, '1–200', 'Version', '22 Oct 2024', '21 Oct 2027', 'Additional Skill Acquisition Programme, Government of Kerala', 'ADDITIONAL SKILL ACQUISITION PROGRAMME (ASAP) KERALA', 'Calibration Technician', 'Calibration Technician-Engineer-Inspector-Senior Manager', 'General Qualification', 'N.A.', '{"Theory":"15","Practical":"30","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "67", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_56.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
