INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-CG-03928-2025-V2-CGSSC', 'CNC Programmer', 'capital-goods-manufacturing', 'Capital Goods & Manufacturing', 4.0, 'A CNC Programmer is responsible for programming commercial Computer Numerical Control (CNC) factory machines that turn raw materials such as plastic and metals into usable components. The individual is responsible for interpreting technical blueprints, inputting the design specifications, adjusting the machine cutting paths, and performing quality checks on the final product to ensure the desired specifications are achieved. The person is also responsible for carrying out routine machine maintenance and troubleshooting any issues encountered during the manufacturing process.', 540, 540, '401–600', 'Version', '30 Apr 2025', '30 Apr 2028', 'Capital Goods and Strategic Skill Council (CGSSC)', 'Capital Goods and Strategic Skills Council', 'CNC Programmer', 'Multi-Axis CNC Machine Engineer', 'Multi-Skill Qualification', 'N.A.', '{"Theory":"150","Practical":"270","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "86", "qualification_type": "Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_56.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-CG-03941-2025-V2-CGSSC', 'Electro Discharge Machine (EDM) Operator', 'capital-goods-manufacturing', 'Capital Goods & Manufacturing', 4.0, 'A CNC Setter and Operator - Electro Discharge Machine (Spark Erosion) is responsible for setting up the Computer Numerically Controlled (CNC) Electro Discharge Machine (EDM) for use and operating it as per the standard procedure to machine a variety of ferrous and non-ferrous metal components.', 450, 450, '401–600', 'Version', '30 Apr 2025', '30 Apr 2028', 'Capital Goods and Strategic Skill Council (CGSSC)', 'Capital Goods and Strategic Skills Council (CGSSC)', 'Electro Discharge Machine (EDM) Operator', 'Tool & Die Maker , Metal Fabrication Engineer', 'Multi-Skill Qualification', 'N.A.', '{"Theory":"120","Practical":"240","EmployabilitySkills":"30","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "87", "qualification_type": "Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_56.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-02-CG-03939-2025-V2-CGSSC', 'Assistant Manual Metal Arc Welding/Shielded Metal Arc Welding Welder', 'capital-goods-manufacturing', 'Capital Goods & Manufacturing', 2.0, 'The incumbent in the job is primarily involved in all manual metal arc welding (MMAW) and gas cutting
operations performed on carbon and low alloy steels. They support the welder in activities such as
inspection of equipment condition, welding, testing and inspection of welded work pieces.', 270, 270, '201–400', 'Version', '30 Apr 2025', '30 Apr 2028', 'Capital Goods and Strategic Skill Council (CGSSC)', 'Capital Goods and Strategic Skills Council', 'Assistant Manual Metal Arc Welding / Shielded Metal Arc Welding Welder', 'Manual Metal Arc Welding / Shielded Metal Arc Welding Welder , Senior Welder (Pipes & Plates)', 'Multi-Skill Qualification', 'N.A.', '{"Theory":"75","Practical":"165","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "88", "qualification_type": "Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_56.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-CG-03926-2025-V2-CGSSC', 'CNC Operator - Vertical Machining Centre', 'capital-goods-manufacturing', 'Capital Goods & Manufacturing', 4.0, 'A CNC Operator - Vertical Machining Centre is responsible for setting up Vertical Machining Centre (VMC),cutting tools and work holding devices for machining a variety of metal and non-metal components as per the given specifications. The individual conducts trial runs, proves the program in single block mode, and performs the necessary checks before allowing the machine to operate in full program run mode.', 450, 450, '401–600', 'Version', '30 Apr 2025', '30 Apr 2028', 'Capital Goods and Strategic Skill Council (CGSSC)', 'Capital Goods and Strategic Skills Council', 'CNC Operator - Vertical Machining Centre', 'CNC Programmer , Multi Axis CNC Engineer', 'Multi-Skill Qualification', 'N.A.', '{"Theory":"120","Practical":"240","EmployabilitySkills":"30","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "89", "qualification_type": "Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_56.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-6.5IT-04169-2025-V1-MSMETC', 'SENIOR TOOL DESIGNER – CAD/CAM', 'capital-goods-manufacturing', 'Capital Goods & Manufacturing', 6.5, 'They are Responsible for developing tool design and tool manufacturing. They will be able to generate CAD models and product design and validate the same using CAE software. And able to do the process planning and manufacturing of the product. Also, with the application of knowledge and skill of Tool and die technology and CAD/CAM/CAE, the participants can develop their own enterprises.', 1800, 1800, '1201–2400', 'Version', '08 May 2025', '08 May 2028', 'MSME Technology Centre, Ministry of Micro Small And Medium Enterprises, New Delhi', 'MSME Technology Centre', 'Tool Design & CAD/CAM', 'Sr. Manager(Tool
Design)', 'General Qualification', 'N.A.', '{"Theory":"300","Practical":"780","EmployabilitySkills":"120","OJT_Mandatory":"600"}', false, '{}'::text[], '{"source_row": "90", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_56.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-IT-04171-2025-V1-MSMETC', 'ASSISTANT MECHATRONICS SYSTEM DESIGNER', 'capital-goods-manufacturing', 'Capital Goods & Manufacturing', 5.0, 'The qualification contains different modules which are required for the job role of  SR. Mechatronics System Designer, This qualified learner shall be able to:
●	Design and operate the mechatronics system.
●	Prepare and execute logic using PLC / SCADA programming.
●	Prepare Electrical system drawing 
●	Use and control the system using pneumatics and Hydraulic
●	Design industrial Pneumatic layout and circuit diagram
●	Design Electro - Pneumatic layout and circuit diagram
●	Design hydraulic system layout and circuit diagram
●	Design hydraulic system circuit diagram
●	Control panel design for PLC, SCADA, HMI, Motor and drive
●	Mechatronics system design for industrial automation
●	To get an employment in Engineering/ Manufacturing industries and also become an entrepreneur', 1200, 1200, '1001–1200', 'Version', '08 May 2025', '08 May 2028', 'MSME Technology Centre, Ministry of Micro Small And Medium Enterprises, New Delhi', 'MSME Technology Centre', 'Mechatronics System Designer', 'Sr. Mechatronics System Designer', 'Cross Sectoral Qualification', 'N.A.', '{"Theory":"450","Practical":"570","EmployabilitySkills":"120","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "91", "qualification_type": "Cross Sectoral Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_56.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-CG-03925-2025-V2-CGSSC', 'Capital Equipment - Calibration Technician', 'capital-goods-manufacturing', 'Capital Goods & Manufacturing', 4.0, 'This OS unit is about the setting, adjusting and validating mechanical, pneumatic, hydraulic, electrical and electronic measuring and control instruments using the appropriate reference standards and following the approved standard procedures.', 450, 450, '401–600', 'Version', '30 Apr 2025', '31 Oct 2025', 'Capital Goods and Strategic Skill Council (CGSSC)', 'Capital Goods and Strategic Skills Council', 'Calibration and Instrumentation', 'Predictive Maintenance Engineer -L5.5, 
Predicitve Maintenance Data Acquisition Engineer L6', 'General Qualification,Multi-Skill Qualification', 'N.A.', '{"Theory":"120","Practical":"240","EmployabilitySkills":"30","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "92", "qualification_type": "General Qualification,Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_56.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
