INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-CG-03929-2025-V2-CGSSC', 'Jr. Designer (Mechanical)', 'capital-goods-manufacturing', 'Capital Goods & Manufacturing', 5.0, 'Jr. Designer (Mechanical) is responsible for determining the client''s requirements with respect to the
mechanical devices and equipment, creating the design brief, validating the design, allocating resources for each activity, and ensuring the designing process is completed within the agreed deadlines and in compliance with the relevant regulations. The individual identifies and evaluates design options, creates detailed design and models using the appropriate 2D and 3D software and presents them to the relevant stakeholders to get their approval and oversees production.', 540, 540, '401–600', 'Version', '30 Apr 2025', '30 Apr 2028', 'Capital Goods and Strategic Skill Council (CGSSC)', 'Capital Goods and Strategic Skills Council', 'Design', 'Computer Tool and Die Design Engineer -L6', 'General Qualification,Multi-Skill Qualification', 'N.A.', '{"Theory":"170","Practical":"250","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "100", "qualification_type": "General Qualification,Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_56.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-CG-03935-2025-V2-CGSSC', 'Metal Inert Gas/ Metal Active Gas/ Gas Metal Arc Welder (MIG/MAG/GMAW) (Optional: Flux cored Arc Welder (Semi-Automatic))', 'capital-goods-manufacturing', 'Capital Goods & Manufacturing', 4.0, 'The incumbent in the job is responsible for performing metal inert gas/metal active gas welding (MIG/MAG) for welding joints as per welding procedure specification (WPS). The incumbent is also responsible for performing Oxy gas cutting and plasma cutting to cut metal into required specification as per welding procedure specification (WPS).', 360, 480, '401–600', 'Version', '30 Apr 2025', '30 Apr 2028', 'Capital Goods and Strategic Skill Council (CGSSC)', 'Capital Goods and Strategic Skills Council', 'Welding and Cutting', 'Senior Tungsten Inert gas Welder -5, Welding automation engineer -6', 'General Qualification,Multi-Skill Qualification', 'N.A.', '{"Theory":"130","Practical":"200","EmployabilitySkills":"90","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "101", "qualification_type": "General Qualification,Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_01_56.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
