INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-3.5-CP-04136-2025-V2-CIPET', 'Machine Operator – CNC Lathe', 'chemicals-petrochemicals', 'Chemicals & Petrochemicals', 3.5, 'Machine Operator – CNC Lathe is expected to Operate Computerized Numerical Controlled (CNC) Lathe Machine, carrying out operations on conventional lathe machine, Measuring and checking the work piece as per specification, maintain good condition of the machine with regular maintenance and understanding of the potential dangers at the workplace, the practices to minimize risks and how to deal in case of accidents and emergency situations.', 480, 480, '401–600', 'Version', '26 May 2025', '25 May 2028', 'Central Institute of Petrochemicals Engineering & Technology (CIPET)', 'Central Institute of Petrochemicals Engineering & Technology (CIPET) Department of Chemicals & Petrochemicals, Ministry of Chemicals & Fertilizers, Govt. of India CIPET Head office, T.V.K Industrial Estate, Guindy, Chennai', 'Machine Operator', 'Machine Operator-CNC Lathe/Shop floor In-charge in Tool Room, Tool & Die Making, Mould Manufacturing, Capital Goods Manufacturing Industry', 'General Qualification', 'N.A.', '{"Theory":"120","Practical":"300","EmployabilitySkills":"30","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "16", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_03.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_not