INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-4.5-CP-04138-2025-V2-CIPET', 'Quality Control Inspector – Plastics Materials & Products', 'chemicals-petrochemicals', 'Chemicals & Petrochemicals', 4.5, 'The Quality Control Inspector for Plastics Materials & Products will be able to carry out inspection / testing for incoming Plastics Raw Materials and intermediate / finished goods w.r.to IS / ASTM standards /In house SOPs, operate testing equipment and assist in documenting test results.', 540, 540, '401–600', 'Version', '26 May 2025', '25 May 2028', 'Central Institute of Petrochemicals Engineering & Technology (CIPET)', 'Central Institute of Petrochemicals Engineering & Technology (CIPET) Department of Chemicals & Petrochemicals, Ministry of Chemicals & Fertilizers, Govt. of India CIPET Head office, T.V.K Industrial Estate, Guindy, Chennai', 'Quality Control Inspector', 'Testing and Quality Control Specialist – Plastics materials & products', 'General Qualification', 'N.A.', '{"Theory":"120","Practical":"300","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "17", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_03.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-CP-04128-2025-V2-CIPET', 'Testing and Quality Control Specialist - Plastics Materials & Products', 'chemicals-petrochemicals', 'Chemicals & Petrochemicals', 5.0, 'Testing and Quality Control Specialist - Plastics Materials & Products ensures quality control across raw materials, in-process, and finished plastic products. The role involves conducting tests, maintaining compliance with BIS, ASTM, ISO standards, managing QC teams, and implementing process improvements to reduce defects. Testing and QC specialists also oversee documentation, audits, and workplace safety protocols.', 570, 570, '401–600', 'Version', '26 May 2025', '25 May 2028', 'Central Institute of Petrochemicals Engineering & Technology (CIPET)', 'Central Institute of Petrochemicals Engineering & Technology (CIPET) Department of Chemicals & Petrochemicals, Ministry of Chemicals & Fertilizers, Govt. of India CIPET Head office, T.V.K Industrial Estate, Guindy, Chennai', 'Quality Control Specialist', 'Quality Control & Quality Assurance Manager in Plastics and allied Industry', 'General Qualification', 'N.A.', '{"Theory":"120","Practical":"330","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "18", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_03.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-3.5-CP-04117-2025-V2-CIPET', 'Machine Operator - Injection Molding', 'chemicals-petrochemicals', 'Chemicals & Petrochemicals', 3.5, 'The Machine operator Injection molding understands the instructions from Supervisor for completing the work order and helps in handling plastics granules (raw material), operates the Plastic Injection Moulding machines & Quality and Inspection of product as per the requirement.', 600, 600, '401–600', 'Version', '26 May 2025', '25 May 2028', 'Central Institute of Petrochemicals Engineering & Technology (CIPET)', 'Central Institute of Petrochemicals Engineering & Technology (CIPET) Department of Chemicals & Petrochemicals, Ministry of Chemicals & Fertilizers, Govt. of India', 'Machine Operator', 'Shift In-charge/Supervisor in Injection Moulding Industry', 'General Qualification', 'N.A.', '{"Theory":"180","Practical":"360","EmployabilitySkills":"30","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "19", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_03.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-3.5-CP-04116-2025-V2-CIPET', 'Machine Operator – Plastics Processing', 'chemicals-petrochemicals', 'Chemicals & Petrochemicals', 3.5, 'The Machine operator handles the plastic granules (raw material), sets up and operates the plastic processing machines, finishes the product & stores in desired place.', 600, 600, '401–600', 'Version', '26 May 2025', '25 May 2028', 'Central Institute of Petrochemicals Engineering & Technology (CIPET)', 'Central Institute of Petrochemicals Engineering & Technology (CIPET) ,Department of Chemicals & Petrochemicals, Ministry of Chemicals & Fertilizers, Govt. of India CIPET Head office, T.V.K Industrial Estate, Guindy, Chennai', 'Machine Operator', 'Shift In-charge / Supervisor in Plastics Processing Industry', 'General Qualification', 'N.A.', '{"Theory":"180","Practical":"360","EmployabilitySkills":"30","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "20", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_03.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-CO-00090-2023-V1-WBSC', 'Assistant House Wireman and Motor Winder', 'construction', 'Construction', 3.0, 'Install, maintain and repair electrical wiring, and lighting systems. Read technical diagrams and blueprints. Perform general electrical maintenance.  Also rewind and produce coils, replacing and preparing components, such as the stator core for winding.', 600, 600, '401–600', 'Version', '05 Jan 2023', '04 Jan 2026', 'West Bengal State Council of Technical & Vocational Education and Skill Development (WBSCTVESD)', 'West Bengal State Council of Technical & Vocational Education and Skill Development.', 'House Wiring & Motor Winding has a wide scope of employment ranging   from      self-employment, contractual   employment   to Industrial jobs.   On successful completion of this course, the candidates shall be gainfully employed in the industries.', 'Assistant House Wireman & Motor Winder  House Wireman & Motor Winder Senior House Wireman & Motor Winder', 'General Qualification', 'N.A.', '{"Theory":"140","Practical":"250","EmployabilitySkills":"60","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "1", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_11.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-CO-00088-2023-V1-ASAP', 'Marine Structural Fitter and Fabricator', 'construction', 'Construction', 4.0, 'Individuals at this job are responsible for Checking and measuring parts for flaws and other accuracy 
 of fit using gauges, micrometers etc., and removes defects by chipping, filing, scraping, grinding and does other supplementary tooling as necessary. Assembles engines and auxiliary machinery in position using hoisting equipment and other tools. Tests completed assembly and makes necessary adjustments, dismantles partly or completely such machinery in ship as propelling machinery, steam diesel or electric auxiliaries, pumps, cargo-handling machinery anchor-handling gear, ventilating and firefighting equipment, steering gear etc., removes and replaces worn or damaged parts and reassembles them as per drawings under guidance of Marine Engineer using hand and portable tools. Installs below deck auxiliaries such as evaporators, stills, heaters, pumps, condensers and boilers and connects them to steam pipe systems. Tests and inspects installed machinery and equipment during dock and sea trials and removes defects, if any. May attend to minor electrical defects. May assist in keeping watch on engine, boiler and other machinery and assist in their operation.', 660, 660, '601–800', 'Version', '05 Jan 2023', '05 Jan 2026', 'Additional Skill Acquisition Programme, Government of Kerala', 'Additional Skill Acquisition Programme Kerala', 'Marine Structural Fitter and Fabricator', 'Marine Structural Fitter,Workman Grade 2,Workman Grade1,Senior Workman Grade 2,Senior Workman Grade1,Workman Supervisor Grade 2,Workman Supervisor Grade1,Supervisor Grade 2,Supervisor Grade 1,Assistant Engineer,Engineer,Senior Engineer,Manager,Deputy Manager,Senior Manager', 'General Qualification', 'N.A.', '{"Theory":"210","Practical":"420","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "2", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_11.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-4.5-CO-00165-2023-V1-SSDF', 'BASIC SCAFFOLD INSPECTOR', 'construction', 'Construction', 4.5, 'Basic Scaffold Inspector is responsible for Inspection of Scaffolding and certify the compliances of scaffolding platform as per design, relevant specifications and ensure scaffolding safety for use of supported scaffolds up to a height of 20 meters. He is also responsible for advice on maintenance of documents, safe practices & compliances.', 570, 570, '401–600', 'Version', '31 Jan 2023', '31 Jan 2026', 'Safety Skill Development Foundation', 'SAFETY SKILL DEVELOPMENT FOUNDATION', 'Scaffolding Engineering & Management', 'Advance Scaffold Inspector, Scaffold Engineer, Scaffold manager', 'Cross Sectoral Qualification,General Qualification,Multi-Skill Qualification', 'N.A.', '{"Theory":"255","Practical":"165","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "3", "qualification_type": "Cross Sectoral Qualification,General Qualification,Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_11.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-2.5-CO-00750-2023-V1-CDSCI', 'Tile Mason- Basic', 'construction', 'Construction', 2.5, 'A Tile Mason is responsible for installing various types of tiles, such as ceramic, porcelain, glass, or stone tiles, on surfaces in residential, commercial, and industrial settings to create durable and visually appealing surfaces. The individual works as a small entrepreneur, taking responsibility for the basic planning, marketing, branding, and financial, operational, and risk management of the enterprise.', 40, 40, '1–200', 'Version', '14 Sep 2023', '15 Sep 2023', 'Construction Skill Development Council of India (CSDCI)', 'Construction Skill Development Council of India (CSDCI)
CPB - 201 & 202, Block-4B, DLF Corporate Park, Phase - III, MG Road Gurugram - 122002,
Near Guru Dronacharya Metro, Tele -0124-4513915', 'Masonry', 'Tile Mason - Advanced', 'National Occupational Standard', 'N.A.', '{"Theory":"10","Practical":"30","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "4", "qualification_type": "National Occupational Standard", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_11.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-2.5-CO-00749-2023-V1-CDSCI', 'Plaster Mason- Basic', 'construction', 'Construction', 2.5, 'A Plaster Mason is responsible for applying and finishing plaster on the interior and exterior surfaces of buildings. The person creates smooth, durable, and aesthetically pleasing finishes on walls and ceilings. The individual works as a small entrepreneur, taking responsibility for the basic planning, marketing, branding, and financial, operational, and risk management of the enterprise.', 40, 40, '1–200', 'Version', '14 Sep 2023', '14 Sep 2026', 'Construction Skill Development Council of India (CSDCI)', 'Construction Skill Development Council of India (CSDCI)
CPB - 201 & 202, Block-4B, DLF Corporate Park, Phase - III, MG Road Gurugram - 122002,
Near Guru Dronacharya Metro, Tele -0124-4513915', 'Masonry', 'Plaster Mason - Advanced', 'National Occupational Standard', 'N.A.', '{"Theory":"10","Practical":"30","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "5", "qualification_type": "National Occupational Standard", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_11.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-2.5-CO-00748-2023-V1-CDSCI', 'Concrete Mason- Basic', 'construction', 'Construction', 2.5, 'A Concrete Mason is responsible for casting or pouring horizontal and flat concrete slabs, which are used as the foundation or flooring in different types of buildings and structures. It involves concrete mixing and pouring, screeding, finishing and curing. The individual works as a small entrepreneur, taking responsibility for the basic planning, marketing, branding, and financial, operational, and risk management of the enterprise.', 40, 40, '1–200', 'Version', '14 Sep 2023', '14 Sep 2026', 'Construction Skill Development Council of India (CSDCI)', 'Construction Skill Development Council of India (CSDCI)
CPB - 201 & 202, Block-4B, DLF Corporate Park, Phase - III, MG Road Gurugram - 122002,
Near Guru Dronacharya Metro, Tele -0124-4513915', 'Masonry', 'Concrete Mason - Advanced', 'National Occupational Standard', 'N.A.', '{"Theory":"10","Practical":"30","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "6", "qualification_type": "National Occupational Standard", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_11.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-2.5-CO-00747-2023-V1-CDSCI', 'Brick Mason- Basic', 'construction', 'Construction', 2.5, 'A Brick Mason is responsible for constructing and repairing structures, such as walls, partitions, facades, and other masonry structures using bricks, concrete blocks, other building blocks and masonry materials. The individual works as a small entrepreneur, taking responsibility for the basic planning, marketing, branding, and financial, operational, and risk management of the enterprise.', 40, 40, '1–200', 'Version', '14 Sep 2023', '14 Sep 2026', 'Construction Skill Development Council of India (CSDCI)', 'Construction Skill Development Council of India (CSDCI)', 'Masonry', 'Brick Mason - Advanced', 'National Occupational Standard', 'N.A.', '{"Theory":"10","Practical":"30","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "7", "qualification_type": "National Occupational Standard", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_11.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-06-CO-00783-2023-V1-CSDCI', 'BIM Coordinator – Design', 'construction', 'Construction', 6.0, 'A BIM Coordinator - Design is responsible for overviewing the designing of Building Information Modelling (BIM) projects. The individual coordinates between different individuals, e.g. BIM Modeler, BIM Engineer, BIM Manager, etc., for efficient BIM designing as per the client’s requirements. The individual also supports the BIM Manager in bidding for BIM projects.', 600, 600, '401–600', 'Version', '31 Aug 2023', '31 Aug 2026', 'Construction Skill Development Council of India (CSDCI)', 'Construction Skill Development Council of India
Address: Tower 4B, DLF Corporate Park, 201&, 202 4B, Mehrauli-Gurgaon Rd, DLF Phase 3, Gurugram, Haryana 122002', 'Building Information Modeling (BIM)', 'BIM Coordinator, BIM Manager', 'Future Skills Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"150","Practical":"210","EmployabilitySkills":"90","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "8", "qualification_type": "Future Skills Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_11.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-6.5-CO-00781-2023-V1-CSDCI', 'BIM Manager - Construction', 'construction', 'Construction', 6.5, 'A BIM Manager – Construction is responsible for the planning, delivery and efficient management of the BIM Execution Plan (BEP). The individual manages different professionals, such as BIM Coordinators and BIM Modelers for the delivery of BIM construction projects and also acts as the intermediary between designers, clients and architects.', 660, 660, '601–800', 'Version', '31 Aug 2023', '31 Aug 2026', 'Construction Skill Development Council of India (CSDCI)', 'Construction Skill Development Council of India
