INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-CO-00780-2023-V1-CSDCI', 'BIM Modeler', 'construction', 'Construction', 4.0, 'A BIM Modeler is responsible for creating and managing digital BIM models of architectural, structural, Mechanical, Electrical and Plumbing (MEP), or landscape elements for construction and infrastructure projects. The individual collaborates with project stakeholders, including architects, engineers, and contractors, to ensure the successful implementation of BIM processes throughout the project lifecycle.', 420, 660, '601–800', 'Version', '08 Nov 2023', '08 Nov 2023', 'Construction Skill Development Council of India (CSDCI)', 'Construction Skill Development Council of India
