INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-CO-00782-2023-V1-CSDCI', 'BIM Technician – Object Creation', 'construction', 'Construction', 5.0, 'A BIM Technician - Object Creation is responsible for the creation of Building Information Modeling (BIM) objects which are used to create BIM models for building. The individual also defines the properties and names for BIM objects, sets their behaviour and coordinates BIM object quality checks.', 510, 510, '401–600', 'Version', '31 Aug 2023', '31 Aug 2026', 'Construction Skill Development Council of India (CSDCI)', 'Construction Skill Development Council of India
