INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QC-4.5-CO-03362-2024-V1-SSDF', 'LIFTING & RIGGING SUPERVISOR (SAFETY)', 'construction', 'Construction', 4.5, 'The Lifting Supervisor (Safety) is responsible for executing the lifting work in a safe manner on the site. The lifting Supervisor (Safety) co-ordinates and supervises all lifting activities in accordance with the Lifting Plan as well as briefing all lifting team members (i.e., crane operators, riggers, and signal operators) on the Lifting operation. The Rigging Supervisor (Safety)  oversees the rigging team, with responsibility for the mechanics of all support rigging, for example scaffolding, ropes, pulleys and lifting equipment.', 540, 540, '401–600', 'Version', '22 Oct 2024', '22 Oct 2027', 'Safety Skill Development Foundation', 'SAFETY SKILL DEVELOPMENT FOUNDATION', 'Lifting & Rigging Engineering & Management', 'Construction Supervisor L5, Construction Manager L5.5, Project manager L 6', 'Apprenticeship Qualification,Cross Sectoral Qualification,General Qualification,Multi-Skill Qualification', 'N.A.', '{"Theory":"240","Practical":"150","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "61", "qualification_type": "Apprenticeship Qualification,Cross Sectoral Qualification,General Qualification,Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_11.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QC-5.5-CO-03363-2024-V1-SSDF', 'CRANE INSPECTOR (SAFETY)', 'construction', 'Construction', 5.5, 'A Crane Inspector (Safety) is responsible for inspection of cranes to ensure that equipment and machinery used for lifting is in safe working order and in line with strict health and safety guidelines and standards. He is also responsible to bring out, shortcomings if any and submit the inspection report.', 600, 600, '401–600', 'Version', '22 Oct 2024', '22 Oct 2027', 'Safety Skill Development Foundation', 'SAFETY SKILL DEVELOPMENT FOUNDATION', 'Lifting & Rigging Engineering & Management', 'Lifting & Rigging Inspector L 6', 'Apprenticeship Qualification,Cross Sectoral Qualification,General Qualification,Multi-Skill Qualification', 'N.A.', '{"Theory":"270","Practical":"180","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "62", "qualification_type": "Apprenticeship Qualification,Cross Sectoral Qualification,General Qualification,Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_11.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-2.5-CO-00089-2023-V1-WBSC', 'Amin Surveyor Assistant', 'construction', 'Construction', 2.5, 'Assist in conducting surveys on land sites and measure the land/properties.
● Examine previous records and evidence to ensure data accuracy.
● Assist in using equipment and tools to accurately measure land features (e.g. longitudes, latitudes)
● Assist in building maps, sketches, and
charts.', 600, 600, '401–600', 'Version', '05 Jan 2023', '04 Jan 2026', 'West Bengal State Council of Technical & Vocational Education and Skill Development (WBSCTVESD)', 'West Bengal State Council of Technical & Vocational Education and Skill Development', 'Amin Surveyor Assistant / Junior Land Surveyor', 'Amin Surveyor Assistant, Amin Surveyor, Senior Amin, Surveyor', 'General Qualification', 'N.A.', '{"Theory":"115","Practical":"275","EmployabilitySkills":"60","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "63", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_11.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-4.5-CO-03457-2025-V1-TICE', 'Roadway Surveyor', 'construction', 'Construction', 4.5, 'Roadway Surveyor is responsible for conducting precise surveys and measurements of land and infrastructure for highway engineering projects. This role involves the use of advanced tools and technologies such as Total Station, GPS, and AI-based technologies to ensure accuracy and efficiency in data collection and analysis. The individual plays a crucial role in supporting the design, construction, and maintenance of highways, contributing to the overall success of infrastructure projects.', 540, 540, '401–600', 'Version', '17 Jan 2025', '17 Jan 2028', 'Integrated Council for Entrepreneurship and Skilling (ICES)', 'The Institution of Civil Engineers Society', 'Surveying', 'Lead Surveyor (level: 5)', 'General Qualification', 'N.A.', '{"Theory":"120","Practical":"240","EmployabilitySkills":"60","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "64", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_11.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-CO-03456-2025-V1-TICE', 'Quality Technician - Construction', 'construction', 'Construction', 4.0, 'A Quality Technician - Construction is responsible for conducting tests on materials used in highway and infrastructure projects, including soil, aggregate, bitumen, steel, and concrete mixes like GSB, WMM, DBM and BC. The role involves using equipment such as the Universal Testing Machine (UTM) for strength assessments and conducting non-destructive testing (NDT) on concrete. The technician also performs specialized tests like FWD and NSV and is involved in setting up project labs, including lab layout, equipment foundations, and testing platforms. Additionally, the technician prepares lab programs and reports, including DPR and MPR.', 540, 540, '401–600', 'Version', '17 Jan 2025', '17 Jan 2028', 'Integrated Council for Entrepreneurship and Skilling (ICES)', 'The Institution of Civil Engineers Society', 'Quality Assurance and Quality Control', 'Quality Supervisor (L5)', 'General Qualification', 'N.A.', '{"Theory":"120","Practical":"270","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "65", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_11.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-2.5-CO-03455-2025-V1-TICE', 'Foundation of Road Safety', 'construction', 'Construction', 2.5, 'This course is designed to equip participants with the knowledge and skills necessary to promote road safety. The curriculum covers a wide range of topics, including traffic rules and regulations, vehicle maintenance, road infrastructure, emergency response, and the application of technology in road safety. Participants will gain a deeper understanding of the factors contributing to road accidents and learn effective strategies to mitigate risks.', 60, 60, '1–200', 'Version', '17 Jan 2025', '17 Jan 2028', 'Integrated Council for Entrepreneurship and Skilling (ICES)', 'The Institution of Civil Engineers Society', 'Safety and Preparedness Education', 'NA.', 'Cross Sectoral Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"30","Practical":"30","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "66", "qualification_type": "Cross Sectoral Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_11.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-5.5-CO-03517-2025-V1-ASAP', 'Road Construction Engineer', 'construction', 'Construction', 5.5, 'Road construction Engineers are professionals responsible for the overseeing, costing, estimating, planning as well as implementation of construction projects of roads that connect cities, towns, and states. They play a pivotal role in overseeing all aspects of road construction, from the initial planning and design stages to construction and project completion. Their work ensures that roads are built safely, efficiently, and in compliance with the regulations.', 630, 630, '601–800', 'Version', '18 Feb 2025', '18 Feb 2028', 'Additional Skill Acquisition Programme, Government of Kerala', 'ADDITIONAL SKILL ACQUISITION PROGRAMME', 'Highway Engineer', 'Senior Engineer, Deputy Project Engineer, Project Engineer, Senior Project Engineer, Deputy
Manager – Projects, Manager - Projects', 'General Qualification', 'N.A.', '{"Theory":"90","Practical":"30","EmployabilitySkills":"60","OJT_Mandatory":"450"}', false, '{}'::text[], '{"source_row": "67", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_11.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-03-CO-03845-2025-V1-TICE  TRC', 'Introduction to Textile Reinforced Concrete (TRC)', 'construction', 'Construction', 3.0, 'This course on Textile Reinforced Concrete (TRC) focuses on the practical use of TRC in modern construction. It covers. the selection of suitable textile materials, understanding their compatibility with concrete, and applying effective reinforcement techniques. Participants will learn how to use TRC for enhancing structural performance, reducing weight, and achieving innovative design solutions. The course includes understanding in layering textiles, maintaining quality standards, and implementing TRC in various construction applications, highlighting recent advancements and real-world uses of TRC technology.', 30, 30, '1–200', 'Version', '18 Feb 2025', '18 Feb 2028', 'Integrated Council for Entrepreneurship and Skilling (ICES)', 'The Institution of Civil Engineers Society', 'Masonry', 'Advance Concrete Technology (L4)', 'Future Skills Qualification,Micro Credentials', 'N.A.', '{"Theory":"10","Practical":"20","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "68", "qualification_type": "Future Skills Qualification,Micro Credentials", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_11.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-CO-03707-2025-V1-TICE', 'Real Estate Advisor', 'construction', 'Construction', 5.0, 'A Real Estate Advisor assists clients in buying, selling, or renting properties. The role involves understanding market trends, evaluating property values, negotiating deals, and guiding clients throughout the transaction process. The Real Estate Advisor must possess strong knowledge of real estate laws, marketing, and customer service.', 510, 510, '401–600', 'Version', '18 Feb 2025', '18 Feb 2028', 'Integrated Council for Entrepreneurship and Skilling (ICES)', 'The institution of Civil Engineers Society', 'Real Estate', 'Senior Real Estate Advisor (L6)', 'General Qualification', 'N.A.', '{"Theory":"120","Practical":"240","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "69", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_11.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-CO-00788-2023-V2-CSDCI', 'Assistant Bar Bender and Steel Fixer', 'construction', 'Construction', 3.0, 'An Assistant Bar Bender and Steel Fixer is responsible for identification, handling and use of tools and tackles, materials and equipment for bar bending. The responsibilities also include reading and understanding reinforcement bar details from hand sketches and bar bending schedule, performing cutting, threading and manual bending of rebar and fabricating, placing and fixing of reinforcement bar at the desired location using correct ties within specified time and tolerance.', 360, 360, '201–400', 'Version', '31 Aug 2023', '31 Aug 2026', 'Construction Skill Development Council of India (CSDCI)', 'Construction Skill Development Council of India', 'Bar Bending and Fixing', 'Bar Bender and Steel Fixer', 'General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"90","Practical":"180","EmployabilitySkills":"30","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "70", "qualification_type": "General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_11.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-02-CO-03950-2025-V2-CSDCI', 'Helper Electrician', 'construction', 'Construction', 2.0, 'A Helper Electrician is responsible for helping the construction electrician and performing tasks under instructions and supervision. The responsibilities also include performing preparatory works before temporary and permanent electrical installations and handling tools, devices, and materials used to perform electrical works.', 270, 270, '201–400', 'Version', '08 May 2025', '30 Apr 2028', 'Construction Skill Development Council of India (CSDCI)', 'Construction Skill Development Council of India (CSDCI)', 'Construction Electrical Works', 'Assistant Electrician', 'General Qualification', 'N.A.', '{"Theory":"60","Practical":"150","EmployabilitySkills":"30","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "71", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_11.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-CO-03951-2025-V2-CSDCI', 'Assistant Electrician', 'construction', 'Construction', 3.0, 'An Assistant Electrician assists the electrician in electrical work for the installation, repair maintenance of temporary Low Voltage (LV) electrical connections in the construction sites and permanent connections at residential and commercial buildings. The individual is engaged in laying conduits for LV single-phase wiring.', 390, 390, '201–400', 'Version', '08 May 2025', '30 Apr 2028', 'Construction Skill Development Council of India (CSDCI)', 'Construction Skill Development Council of India (CSDCI)', 'Construction Electrical Works', 'Construction Electrician-LV', 'General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"90","Practical":"240","EmployabilitySkills":"30","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "72", "qualification_type": "General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_11.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-CO-03952-2025-V2-CSDCI', 'Construction Electrician-LV', 'construction', 'Construction', 4.0, 'A Construction Electrician - LV is responsible for laying cables, installing, and maintaining equipment like motors, bar cutting machines, bar shearing machines etc., at the construction sites as per the requirement of construction activities. The responsibilities  also include carrying out permanent wiring and assisting the foreman in the  electrification of buildings. The individual uses electrical drawings, diagrams, and related  documents to carry out the activities', 450, 450, '401–600', 'Version', '08 May 2025', '30 Apr 2028', 'Construction Skill Development Council of India (CSDCI)', 'Construction Skill Development Council of India (CSDCI)', 'Construction Electrical Works', 'Foreman-Electrical Works', 'General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"90","Practical":"270","EmployabilitySkills":"30","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "73", "qualification_type": "General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_11.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-3.5-CO-03962-2025-V2-CSDCI', 'Rural Mason', 'construction', 'Construction', 3.5, 'A Rural Mason performs routine rural construction works with either bricks/blocks or bamboo and performs work such as earth work for foundation, layout marking and construction of foundations, walls, installation of sanitary fittings and fixtures in rural toilets, IPS flooring, reinforcement and shuttering work, manual concreting work, fixing of door and window frames and shutters, treatment of bamboo, construction of simple buildings using bamboo, seismic and wind protection measures, construction using CSEB and random rubble masonry work.', 420, 780, '601–800', 'Version', '08 May 2025', '30 Apr 2028', 'Construction Skill Development Council of India (CSDCI)', 'Construction Skill Development Council of India (CSDCI)', 'Masonry-Rural', 'Brick Mason', 'General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"120","Practical":"0","EmployabilitySkills":"30","OJT_Mandatory":"270"}', false, '{}'::text[], '{"source_row": "74", "qualification_type": "General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_11.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-CO-03948-2025-V2-CSDCI', 'Bar Bender and Steel Fixer', 'construction', 'Construction', 4.0, 'A Bar Bender and Steel Fixer is responsible for marking, cutting, bending, fabricating, placing and fixing reinforcement bars at the desired location using appropriate hand or power tools, within the specified time and defined tolerance limits, following safe work practices.', 450, 450, '401–600', 'Version', '08 May 2025', '30 Apr 2028', 'Construction Skill Development Council of India (CSDCI)', 'Construction Skill Development Council of India (CSDCI)', 'Bar Bending and Fixing', 'Foreman Reinforcement', 'General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"120","Practical":"270","EmployabilitySkills":"30","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "75", "qualification_type": "General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_11.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-CO-03949-2025-V2-CSDCI', 'Reinforcement Fitter', 'construction', 'Construction', 4.0, 'A Reinforcement Fitter is responsible for fabricating and fixing reinforcement bars for complex structures, such as arches, domes, and other circular structures in a sequential manner as per the work requirement within the specified time and tolerance. The individual also works with mechanical couplers for the extension of reinforcement bars.', 450, 450, '401–600', 'Version', '08 May 2025', '30 Apr 2028', 'Construction Skill Development Council of India (CSDCI)', 'Construction Skill Development Council of India (CSDCI)', 'Bar Bending and Fixing', 'Forman Reinforcement', 'General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"90","Practical":"270","EmployabilitySkills":"30","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "76", "qualification_type": "General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_11.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-CO-03955-2025-V2-CSDCI', 'Draughtsperson-Civil works', 'construction', 'Construction', 4.0, 'A Draughtsperson-Civil Works is responsible for the preparation, correction, and documentation of all types of drawings prepared for construction and erection works, 
showing all relevant plans, sections, elevations, and details along with other requirements as applicable based on the type of drawing.', 450, 450, '401–600', 'Version', '08 May 2025', '30 Apr 2028', 'Construction Skill Development Council of India (CSDCI)', 'Construction Skill Development Council of India (CSDCI)', 'Draughting', 'BIM Technician - Object Creation', 'General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"90","Practical":"270","EmployabilitySkills":"30","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "77", "qualification_type": "General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_11.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-3.5-CO-03959-2025-V2-CSDCI', 'Mason Tiling', 'construction', 'Construction', 3.5, 'A Mason tiling is responsible for identifying, cutting, grinding, shaping, laying, fixing and finishing the tiles on floors and walls using the appropriate tools and equipment, as per the specified standards, patterns and within the dimensional accuracy.', 390, 390, '201–400', 'Version', '08 May 2025', '30 Apr 2028', 'Construction Skill Development Council of India (CSDCI)', 'Construction Skill Development Council of India (CSDCI)', 'Masonry', 'Foreman Wet Finishing & Flooring', 'General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"90","Practical":"240","EmployabilitySkills":"30","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "78", "qualification_type": "General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_11.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-5.5-CO-03966-2025-V2-CSDCI', 'Surveyor', 'construction', 'Construction', 5.5, 'A Surveyor is responsible for carrying out Construction Site Survey Work using modern and conventional systems by means of using instruments at construction sites. He 
collects, analyzes and manages the geographical data i.e. critical to planning and executing constructions', 600, 600, '401–600', 'Version', '08 May 2025', '30 Apr 2028', 'Construction Skill Development Council of India (CSDCI)', 'Construction Skill Development Council of India (CSDCI)', 'Surveying', 'Senior Surveyor', 'General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"180","Practical":"0","EmployabilitySkills":"90","OJT_Mandatory":"330"}', false, '{}'::text[], '{"source_row": "79", "qualification_type": "General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_11.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-02-CO-03965-2025-V2-CSDCI', 'Assistant Surveyor', 'construction', 'Construction', 2.0, 'An Assistant Surveyor is responsible for assisting the surveyor in various surveying activities undertaken on-site such as operating surveying equipment, recording 
measurements, and assisting in the preparation of maps and plans. This role requires a combination of technical skills, physical stamina, and the ability to work collaboratively in a team environment.', 300, 300, '201–400', 'Version', '08 May 2025', '30 Apr 2028', 'Construction Skill Development Council of India (CSDCI)', 'Construction Skill Development Council of India (CSDCI)', 'Surveying', 'Surveyor', 'General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"60","Practical":"180","EmployabilitySkills":"30","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "80", "qualification_type": "General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_11.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-CO-03956-2025-V2-CSDCI', 'Fabricator', 'construction', 'Construction', 4.0, 'A Fabricator is responsible for conducting various activities, such as surface cleaning, 
edge/ joint preparation, connection of the components/ steel sections, etc., as well as 
the erection of these assemblies.', 450, 450, '401–600', 'Version', '08 May 2025', '30 Apr 2028', 'Construction Skill Development Council of India (CSDCI)', 'Construction Skill Development Council of India (CSDCI)', 'Fabrication', 'Senior Construction Welder', 'General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"90","Practical":"270","EmployabilitySkills":"30","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "81", "qualification_type": "General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_11.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-CO-03963-2025-V2-CSDCI', 'Shuttering Carpenter', 'construction', 'Construction', 4.0, 'A Shuttering Carpenter is responsible for making shutters and assembling system/ 
conventional formwork for RCC structures such as columns, beams, slabs, walls, foundations and other similar structures.', 420, 570, '401–600', 'Version', '08 May 2025', '30 Apr 2028', 'Construction Skill Development Council of India (CSDCI)', 'Construction Skill Development Council of India (CSDCI)', 'Shuttering Carpentry', 'Foreman Formwork', 'General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"90","Practical":"240","EmployabilitySkills":"30","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "82", "qualification_type": "General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_11.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-CO-03958-2025-V2-CSDCI', 'Brick Mason', 'construction', 'Construction', 4.0, 'A Brick Mason, is a skilled tradesperson responsible for constructing, repairing, and maintaining structures made of brick, stone, concrete blocks, or other similar materials. 
The Brick mason is required to perform routine masonry works, such as brickwork, block 
work, laying paver blocks, plastering, brick bat coba waterproofing, random rubble masonry and IPS/Tremix flooring, etc.', 450, 690, '601–800', 'Version', '08 May 2025', '30 Apr 2028', 'Construction Skill Development Council of India (CSDCI)', 'Construction Skill Development Council of India (CSDCI)', 'Masonry', 'Foreman Concrete', 'General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"90","Practical":"270","EmployabilitySkills":"30","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "83", "qualification_type": "General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_11.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-4.5-CO-03964-2025-V2-CSDCI', 'Junior Store Keeper - Construction', 'construction', 'Construction', 4.5, 'A Junior Store Keeper - Construction is responsible for receiving incoming materials, and stacking, storing and issuing materials along with carrying out necessary documentation at the construction sites.', 510, 510, '401–600', 'Version', '08 May 2025', '30 Apr 2028', 'Construction Skill Development Council of India (CSDCI)', 'Construction Skill Development Council of India (CSDCI)', 'Store Keeping', 'Store Keeper – Construction', 'General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"120","Practical":"240","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "84", "qualification_type": "General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_11.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-06-CO-03961-2025-V2-CSDCI', 'Supervisor Structure (Technical)', 'construction', 'Construction', 5.5, 'A Supervisor Structure (Technical) is responsible for planning, managing and allocating resources for various structural works at construction sites; supervising and monitoring concreting, bar bending, system shuttering carpentry and scaffolding activities while ensuring adherence to the applicable health, safety and environmental practices.', 600, 600, '401–600', 'Version', '08 May 2025', '30 Apr 2028', 'Construction Skill Development Council of India (CSDCI)', 'Construction Skill Development Council of India (CSDCI)', 'Masonry', 'Manager Structure (Technical)', 'General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"180","Practical":"0","EmployabilitySkills":"90","OJT_Mandatory":"330"}', false, '{}'::text[], '{"source_row": "85", "qualification_type": "General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_11.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-CO-03953-2025-V2-CSDCI', 'Foreman-Electrical Works (Construction)', 'construction', 'Construction', 5.0, 'A Foreman - Electrician Works (Construction) is responsible for conducting installation, repair, and maintenance of critical electrical connections/ equipment or machinery while planning and utilizing resources to meet electrical work requirements at construction sites or permanent structures.', 570, 570, '401–600', 'Version', '08 May 2025', '30 Apr 2028', 'Construction Skill Development Council of India (CSDCI)', 'Construction Skill Development Council of India (CSDCI)', 'Construction Electrical Works', 'Supervisor-Electrical Work', 'General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"150","Practical":"0","EmployabilitySkills":"60","OJT_Mandatory":"360"}', false, '{}'::text[], '{"source_row": "86", "qualification_type": "General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_11.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-CO-04206-2025-V1-CSDCI', 'Construction Welder', 'construction', 'Construction', 4.0, 'A Construction Welder is responsible for joining, cutting, and repairing metal components at construction sites using various welding techniques. They work with steel structures, pipelines, and other metal frameworks, ensuring high-quality welds that meet industry standards and project specifications.', 480, 1080, '1001–1200', 'Version', '08 May 2025', '30 Apr 2028', 'Construction Skill Development Council of India (CSDCI)', 'Construction Skill Development Council of India (CSDCI)', 'Construction Electrical Works', 'Senior Construction Welder', 'General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"90","Practical":"300","EmployabilitySkills":"30","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "87", "qualification_type": "General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_11.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-3.5-CO-04294-2025-V1-ICES', 'Purchase Executive - Construction', 'construction', 'Construction', 3.5, 'A Purchase Executive – Construction Material is a key professional in the construction industry responsible for learning and applying procurement practices to ensure that materials are sourced efficiently and cost effectively. Learners in this role gain hands-on experience in vendor management, inventory control, and quality assurance. They develop skills in identifying reliable suppliers, comparing prices, and ensuring the timely delivery of construction materials to meet project timelines. By understanding the complete procurement process, learners contribute to smooth project execution while staying within budget and maintaining quality standards.', 450, 450, '401–600', 'Version', '08 May 2025', '08 May 2028', 'Integrated Council for Entrepreneurship and Skilling (ICES)', 'The Institution of Civil Engineers Society', 'Procuring goods, materials and services', 'Purchase Officer (NSQF Level 4)', 'General Qualification', 'N.A.', '{"Theory":"110","Practical":"220","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "88", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_11.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-4.5-CO-04450-2025-V1-ASAP', 'Fundamentals of BIM Integration for MEP Systems in Civil Engineering using Autodesk Revit', 'construction', 'Construction', 4.5, 'This course explores the integration of Building Information Modeling (BIM) into the design, construction, and management of Mechanical, Electrical, and Plumbing (MEP) systems within civil engineering projects. It focuses on the practical application of BIM to coordinate and streamline the process of MEP system design and installation, ensuring greater accuracy and efficiency. Through this course, learners will understand the role of BIM in managing complex MEP systems and how it enhances collaboration between architects, engineers, and contractors.', 60, 60, '1–200', 'Version', '07 Oct 2025', '07 Oct 2028', 'Additional Skill Acquisition Programme, Government of Kerala', 'ADDITIONAL SKILL ACQUISITION PROGRAMME, KERALA', 'Building Architects, other', 'BIM Technician / BIM Modeler', 'OEM Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"22","Practical":"38","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "89", "qualification_type": "OEM Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_11.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-4.5-CO-04449-2025-V1-ASAP', 'Fundamentals of BIM Integration for MEP Systems in Mechanical Engineering using Autodesk Revit', 'construction', 'Construction', 4.5, 'The Fundamentals of BIM Integration for MEP Systems in Mechanical Engineering using Autodesk Revit course provides a comprehensive introduction to Building Information Modeling (BIM) for mechanical, electrical, and plumbing (MEP) applications. This course equips learners with the skills to design, model, and integrate MEP systems using Autodesk Revit, focusing on HVAC, plumbing, and fire protection. Students will gain a solid understanding of Revit’s interface, linking models, working with parameters, and developing detailed construction documentation. The curriculum follows industry standards and includes hands-on training in system design, component customization, and project coordination.', 60, 60, '1–200', 'Version', '07 Oct 2025', '07 Oct 2028', 'Additional Skill Acquisition Programme, Government of Kerala', 'ADDITIONAL SKILL ACQUISITION PROGRAMME, KERALA', 'Building Architects, Other', 'BIM Technician / BIM Modeler', 'OEM Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"24","Practical":"36","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "90", "qualification_type": "OEM Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_11.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-4.5-CO-04448-2025-V1-ASAP', 'Fundamentals of BIM Integration for MEP Systems in Electrical Engineering using Autodesk Revit', 'construction', 'Construction', 4.5, 'This course, "Fundamentals of BIM Integration for MEP Systems in Electrical Engineering using Autodesk Revit", provides a comprehensive introduction to Building Information Modeling (BIM) for electrical systems. Learners will explore Autodesk Revit’s interface, tools, and workflows essential for designing and documenting electrical circuits, lighting layouts, and power distribution systems. The course covers key concepts such as Revit family components, circuit creation, conduit and cable tray routing, linking architectural models, and managing electrical settings. Additionally, students will develop expertise in worksharing, annotation, detailing, and generating schedules for efficient project documentation.', 60, 60, '1–200', 'Version', '07 Oct 2025', '07 Oct 2028', 'Additional Skill Acquisition Programme, Government of Kerala', 'ADDITIONAL SKILL ACQUISITION PRORAMME KERALA', 'Building Architects, Other', 'BIM Technician / BIM Modeler', 'OEM Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"22","Practical":"38","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "91", "qualification_type": "OEM Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_11.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NCVET-QG-04-CO-046442025-V1-ICES', 'Construction Fabricator', 'construction', 'Construction', 4.0, 'A Construction Fabricator assembles, shapes and installs materials like metal, wood, masonry and concrete to create structural elements for buildings and infrastructure. The individual interprets construction drawings, identifies materials and follows the applicable safety and quality standards. The specializations available in the job include masonry, woodworking, metalworking and concreting.', 390, 1230, '1201–2400', 'Version', '07 Oct 2025', '07 Oct 2028', 'Integrated Council for Entrepreneurship and Skilling (ICES)', 'The Institution of Civil Engineers Society', 'Masonry/Shuttering Carpentry/Bar Bending/Fabrication', 'Supervisor Fabricator (NSQF Level: 5)', 'General Qualification,Multi-Skill Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"90","Practical":"180","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "92", "qualification_type": "General Qualification,Multi-Skill Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_11.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NCVET-QG-04-CO-046432025-V1-ICES', 'Interior Finisher', 'construction', 'Construction', 4.0, 'An Interior Finisher is responsible for finishing tasks such as painting, tiling, marble work, false ceiling installation, drywall setup and waterproofing in residential, commercial and industrial buildings. These tasks are completed in residential, commercial and industrial spaces, with a focus on safety, aesthetics, functionality and adherence to environmental guidelines.', 300, 900, '801–1000', 'Version', '07 Oct 2025', '07 Oct 2028', 'Integrated Council for Entrepreneurship and Skilling (ICES)', 'Integrated Council for Entrepreneurship and Skilling', 'Finishing Works', 'Supervisor Finishes (NSQF Level 5.5)', 'General Qualification,Multi-Skill Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"60","Practical":"120","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "93", "qualification_type": "General Qualification,Multi-Skill Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_11.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NCVET-QG-03-CO-046422025-V1-ICES', 'MEP Executive', 'construction', 'Construction', 3.0, 'The MEP Executive provides essential support in the installation, maintenance and repair of Mechanical, Electrical and Plumbing (MEP) systems. This role involves assisting MEP technicians and engineers with various tasks, including reading blueprints, handling tools, performing basic installations and troubleshooting minor issues in line with sector-specific standards. The individual collaborates with other teams on-site or within facilities to ensure MEP systems operate efficiently, safely and in compliance with industry codes and standards.', 300, 660, '601–800', 'Version', '07 Oct 2025', '07 Oct 2028', 'Integrated Council for Entrepreneurship and Skilling (ICES)', 'Integrated Council for Entrepreneurship and Skilling', 'MEP (Mechanical, Electrical and Plumbing)', 'MEP Technician (NSQF Level: 4)', 'General Qualification,Multi-Skill Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"90","Practical":"150","EmployabilitySkills":"30","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "94", "qualification_type": "General Qualification,Multi-Skill Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_11.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-CO-046412025-V1-ICES', 'MEP Technician', 'construction', 'Construction', 4.0, 'The MEP Technician is responsible for installing, maintaining, troubleshooting, and repairing Mechanical, Electrical and Plumbing systems at construction sites or facilities. The role ensures compliance with safety standards, project specifications, preventive maintenance schedules and operational efficiency across all MEP systems.', 450, 810, '801–1000', 'Version', '07 Oct 2025', '07 Oct 2028', 'Integrated Council for Entrepreneurship and Skilling (ICES)', 'Integrated Council for Entrepreneurship and Skilling', 'MEP (Mechanical, Electrical and Plumbing)', 'MEP Supervisor - Maintenance (NSQF Level: 5)', 'General Qualification,Multi-Skill Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"120","Practical":"240","EmployabilitySkills":"30","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "95", "qualification_type": "General Qualification,Multi-Skill Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_11.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NCVET-NG-02-CO-046382025-V1-ICES', 'Introduction to Roads Repair and Maintenance', 'construction', 'Construction', 2.0, 'Introduction to Road Repair and Maintenance NOS involves ensuring the longevity and safety of road
infrastructure through regular upkeep, repairs and restoration activities. This role encompasses identifying and addressing issues such as potholes, cracks, erosion and surface wear, which can compromise the safety and functionality of roads. Technicians and specialists in road repair are responsible for planning, executing and overseeing maintenance tasks, using tools and technologies to ensure that roads remain safe, smooth and durable for daily use.', 120, 120, '1–200', 'Version', '07 Oct 2025', '07 Oct 2028', 'Integrated Council for Entrepreneurship and Skilling (ICES)', 'Integrated Council for Entrepreneurship and Skilling', 'Road and Highway Construction', 'Pavement Layer (NSQF Level 3)', 'General Qualification,National Occupational Standard,Upskilling Qualification', 'N.A.', '{"Theory":"45","Practical":"55","EmployabilitySkills":"0","OJT_Mandatory":"20"}', false, '{}'::text[], '{"source_row": "96", "qualification_type": "General Qualification,National Occupational Standard,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_11.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NCVET-NG-02-CO-046402025-V1-ICES', 'Introduction to Streetscaping', 'construction', 'Construction', 2.0, 'The Standalone NOS “Introduction to Streetscaping” defines planning and basic execution
of road streetscaping activities that aimed at improving traffic safety, pedestrian movement
and environmental sustainability along road corridors. The role involves identifying and
reporting road classification elements, traffic patterns, signage/signal requirements,
roadside infrastructure and plantation arrangements under the supervision of a site engineer
or supervisor. The candidate also participates in basic maintenance and safety-related
activities during streetscaping works.', 120, 120, '1–200', 'Version', '07 Oct 2025', '07 Oct 2028', 'Integrated Council for Entrepreneurship and Skilling (ICES)', 'Integrated Council for Entrepreneurship and Skilling', 'Road and Highway Construction', 'Pavement Layer (NSQF Level 3)', 'General Qualification', 'N.A.', '{"Theory":"45","Practical":"55","EmployabilitySkills":"0","OJT_Mandatory":"20"}', false, '{}'::text[], '{"source_row": "97", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_11.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NCVET-NG-02-CO-046392025-V1-ICES', 'Introduction to Roadside Plantation and Bioengineering', 'construction', 'Construction', 2.0, 'This NOS involves enhancing road safety, stability and environmental sustainability
through the strategic planting of vegetation and application of bioengineering techniques,
considering retaining walls (such as traditional and new techniques). This role focuses on
using natural methods and eco-friendly practices to stabilize slopes, control erosion and
improve the visual, Rainwater harvesting and ecological quality of road corridors.
Professionals in this field are responsible for planning, executing and maintaining
vegetation cover and bioengineering structures that integrate with the built environment to
reduce maintenance costs and environmental impact.', 120, 120, '1–200', 'Version', '07 Oct 2025', '07 Dec 2028', 'Integrated Council for Entrepreneurship and Skilling (ICES)', 'Integrated Council for Entrepreneurship and Skilling', 'Road and Highway Construction', 'Pavement Layer (NSQF Level 3)', 'General Qualification', 'N.A.', '{"Theory":"45","Practical":"55","EmployabilitySkills":"0","OJT_Mandatory":"20"}', false, '{}'::text[], '{"source_row": "98", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_11.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-03-CO-046452025-V1-ICES', 'Applications of AI in Construction Safety', 'construction', 'Construction', 3.0, 'This NOS specifies the skills and competencies required to apply artificial intelligence (AI) technologies to support safety management in construction environments. The individual is responsible for monitoring AI-enabled systems, interpreting risk predictions, validating alerts, reporting anomalies and ensuring coordinated communication on potential hazards. Application responsibilities include the safe use of AI-driven sensors, surveillance platforms, predictive maintenance tools, VR/AR workplace simulations and automated audit dashboards. Emphasis is on accurate risk interpretation, compliance support, emergency preparedness, structured incident reporting and contributing to decision-making alongside safety engineers and supervisors.', 60, 60, '1–200', 'Version', '07 Oct 2025', '07 Oct 2028', 'Integrated Council for Entrepreneurship and Skilling (ICES)', 'Integrated Council for Entrepreneurship and Skilling', 'Safety Works, Future Skills', 'Construction Safety Technician (NSQF Level: 4)', 'Future Skills Qualification,General Qualification', 'N.A.', '{"Theory":"40","Practical":"20","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "99", "qualification_type": "Future Skills Qualification,General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_11.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-05-CO-046372025-V1-ICES', 'Bexel - BIM based Project Management (3D/4D/5D/6D BIM)', 'construction', 'Construction', 5.0, 'A BIM Project Management professional supports digital construction by creating and managing 3D/4D/5D BIM models for planning, cost control and project tracking using open BIM workflows across the project lifecycle.', 75, 75, '1–200', 'Version', '07 Oct 2025', '07 Oct 2028', 'Integrated Council for Entrepreneurship and Skilling (ICES)', 'Integrated Council for Entrepreneurship and Skilling', 'BIM Project Management', 'BIM Analyst (NSQF Level: 5.5)', 'General Qualification,OEM Qualification', 'N.A.', '{"Theory":"30","Practical":"45","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "100", "qualification_type": "General Qualification,OEM Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_11.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-05-CO-046462025-V1-ICES', 'Tunnel Safety Supervisor', 'construction', 'Construction', 5.0, 'The Tunnel Safety Supervisor is responsible for ensuring the safety and regulatory compliance of tunnel operations. This role includes conducting regular safety inspections and audits to identify and mitigate potential hazards, ensuring adherence to safety standards and regulations. The supervisor develops and maintains emergency response plans, conducts safety drills and provides training to personnel on emergency procedures. Additionally, they coordinate with various teams to implement safety measures, continuously assess risks and take corrective actions to prevent accidents and ensure a safe working environment.', 510, 510, '401–600', 'Version', '07 Oct 2025', '07 Oct 2028', 'Integrated Council for Entrepreneurship and Skilling (ICES)', 'Integrated Council for Entrepreneurship and Skilling', 'Safety Works', 'Tunnel Safety Engineer (NSQF Level: 6)', 'General Qualification', 'N.A.', '{"Theory":"90","Practical":"300","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "101", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_11.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-5.5-CO-046472025-V1-ICES', 'Contract Manager (Construction)', 'construction', 'Construction', 5.5, 'A Contract Manager (Construction) is someone who manages the entire contract lifecycle for a company. The contract management services include negotiation, implementation and administration of contracts. With accuracy as the primary benchmark, a contract manager ensures that the contracts are drawn up and executed in compliance with the company’s policies and regulations. Besides curating and executing the contracts, the contract manager’s role entails managing the enforcement of the contract by ensuring that all parties involved adhere to the terms stipulated in the contract. High accuracy and negotiation skills are indispensable qualities that are vital to the contract manager’s job role.', 600, 600, '401–600', 'Version', '07 Oct 2025', '07 Oct 2028', 'Integrated Council for Entrepreneurship and Skilling (ICES)', 'Integrated Council for Entrepreneurship and Skilling', 'Legal Professionals', 'Senior Contract Manager (NSQF Level: 6)', 'General Qualification', 'N.A.', '{"Theory":"180","Practical":"270","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "102", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_11.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/ETR/MEPSC/06152', 'Career and Education Counsellor', 'education-training-research', 'Education, Training & Research', 5.0, 'A Career and Education Counsellor is responsible for providing guidance and support to students and/or job seekers on career and/or educational selection by determining their interest and aptitude. Not only do they give one-on-one support, but also arrange information sessions, orientation program and other services as required. They keep abreast with developments in the education and labour market to link candidates to career and education opportunities in India and abroad. They also provide advice and information to employer clients regarding employment issues and human resources.', 540, 540, '401–600', 'Version', '28 Jul 2022', '27 Jul 2025', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Counselling', 'Student Counsellor, Admission Counsellor, School Counsellor', 'General Qualification', 'N.A.', '{"Theory":"180","Practical":"300","EmployabilitySkills":"60","OJT_Mandatory":"00"}', false, '{}'::text[], '{"source_row": "1", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_20.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-2.5-ET-01489-2023-V1-MSRVVP', 'Ayurveda evam Vanaushadhi - Kanishtha Sahayak आयुर्वेद एवं वनौषधि - कनिष्ठ सहायक', 'education-training-research', 'Education, Training & Research', 2.5, 'The Candidates shall acquire knowledge of basic vedic culture, importance of Ayurveda and introduction and application of medicinal plants mentioned in Vedas.', 240, 240, '201–400', 'Version', '23 Jun 2023', '23 Jun 2026', 'Maharshi Sandipani Rashtriya Vedavidya Pratishtha', 'Maharshi Sandipani Rashtriya Vedavidya Pratishthan, Ujjain', 'N/A', 'Academic Progression - 
● Candidates can proceed to level 3 on completion 
Progression – 
After the completion of program, Candidates will  
● Gain some knowledge of Vedic Literature 
● Acquire some knowledge of Ayurveda
● Know the Basic introduction of main ayurvedic texts 
● Gain some Knowledge of different Ayurveda siddhantas 
● Know Ayurvedic Daily life rules 
● Know Ayurvedic Seasonal Health Calendar 
● Gain some knowledge in amarakosha vanaushadhi varga 
● Gain some Basic knowledge of medicinal plants 
● Know some Basic introduction of medicinal plants mentioned in four vedas.', 'General Qualification', 'N.A.', '{"Theory":"80","Practical":"100","EmployabilitySkills":"30","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "2", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_20.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
