INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-2.5-ET-03479-2025-V1-MSRVVP', 'Yoga Prashikshan Sahayak /योग प्रशिक्षण – सहायक', 'education-training-research', 'Education, Training & Research', 3.0, 'Candidate will got to know about various yoga practices, enriched Indian culture, Yoga in Vedic literature and different texts of yoga, Vedic mantra therapy, Ayurveda and lifestyle etc.', 270, 270, '201–400', 'Version', '17 Dec 2024', '17 Dec 2027', 'Maharshi Sandipani Rashtriya Vedavidya Pratishtha', 'Maharshi Sandipani Rashtriya Vedavidya Pratishthan', 'Yoga Prashikshan', '•	Candidates will gain basic knowledge of yoga and yogic practices (Sukshma vyayama, suryanamaskar, yogasana, pranayama, shatkarma and vedic mantra meditation therapy)
