INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-04-ET-04309-2025-V1-SSDF', 'Fundamentals of Occupational Risk Management in the Chemical Industry', 'education-training-research', 'Education, Training & Research', 4.0, 'Fundamentals of Occupational Risk Management in the Chemical Industry is crucial due to the inherent hazards associated with chemicals and chemical processes. The Micro Credential deals with effective risk management, protecting workers, preventing accidents, and ensure regulatory compliance.', 15, 15, '1–200', 'Version', '08 May 2025', '08 May 2028', 'Safety Skill Development Foundation', 'SAFETY SKILL DEVELOPMENT FOUNDATION', 'Chemical Safety Management', 'N/A', 'Micro Credentials', 'N.A.', '{"Theory":"8","Practical":"7","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "27", "qualification_type": "Micro Credentials", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_20.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-03-ET-04310-2025-V1-SSDF', 'Basics of Emergency Response and Evacuation Preparedness', 'education-training-research', 'Education, Training & Research', 3.0, 'This Micro credential is designed to provide individuals with the necessary knowledge & skills to efficiently handle and address emergencies & evacuations in various situations at workplaces. The main objective is to provide a thorough understanding to effectively manage critical situations, ensuring the safety of individuals, records and assets during emergency situations.', 7, 7, '1–200', 'Version', '08 May 2025', '08 May 2028', 'Safety Skill Development Foundation', 'SAFETY SKILL DEVELOPMENT FOUNDATION', 'Occupational Safety Health & Environment (OSHE) Engineering & Management', 'N/A', 'Micro Credentials', 'N.A.', '{"Theory":"4","Practical":"3.5","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "28", "qualification_type": "Micro Credentials", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_20.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-04-ET-04311-2025-V1-SSDF', 'Fundamentals of Safety Measures in Electrical Switchgear & Protective devices', 'education-training-research', 'Education, Training & Research', 4.0, 'The MC deals with the various devices employed for the purpose of switching, controlling, and safeguarding electrical power circuits, as well as different types of electrical equipment by detecting any faulty conditions within the system through protection relays. Switchgear encompasses circuit breakers, current transformers, voltage transformers, protection relays, measuring instruments, electrical switches, electrical fuses, miniature circuit breakers, lightning arresters or surge arresters, electrical isolators, and other related equipment.', 7, 7, '1–200', 'Version', '08 May 2025', '08 May 2028', 'Safety Skill Development Foundation', 'SAFETY SKILL DEVELOPMENT FOUNDATION', 'Electrical Safety Management', 'N/A', 'Micro Credentials', 'N.A.', '{"Theory":"4","Practical":"3.5","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "29", "qualification_type": "Micro Credentials", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_20.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-03-ET-04312-2025-V1-SSDF', 'Introduction To Confined Space Challenges & Safety Measures', 'education-training-research', 'Education, Training & Research', 3.0, 'The confined spaces like ducts, vessels, boilers, culverts, tunnels, boreholes, manholes, excavations, sumps, inspection pits, experimental hutches etc., present potential hazards to individuals working within them due to factors such as restricted ventilation, limited mobility, and the presence of hazardous substances. The MC deals with confined space safety challenges for workers and measures to be taken, training & emergency preparedness.', 15, 15, '1–200', 'Version', '08 May 2025', '08 May 2028', 'Safety Skill Development Foundation', 'SAFETY SKILL DEVELOPMENT FOUNDATION', 'Construction Engineering & Management', 'N/A', 'Micro Credentials', 'N.A.', '{"Theory":"8","Practical":"7","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "30", "qualification_type": "Micro Credentials", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_20.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-02-ET-04313-2025-V1-SSDF', 'BASICS OF SAFETY REQUIREMENTS IN WORKING AT HEIGHT', 'education-training-research', 'Education, Training & Research', 2.0, 'The Micro Credential deals with challenges & risks related to working at height, measures to reduce the risks, safety precautions to be taken and personal protective equipment to be used while working at height. It also explains the various causes, situations and negligence which lead to accidents with regulations associated with working at elevated positions.', 7, 7, '1–200', 'Version', '08 May 2025', '08 May 2028', 'Safety Skill Development Foundation', 'SAFETY SKILL DEVELOPMENT FOUNDATION', 'Construction Engineering & Management', 'N/A', 'Micro Credentials', 'N.A.', '{"Theory":"4","Practical":"3.5","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "31", "qualification_type": "Micro Credentials", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_20.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-ET-04093-2025-V2-ASAP', 'Communicative English Trainer', 'education-training-research', 'Education, Training & Research', 5.0, 'Individuals at this job are responsible for training young learners spread over diverse professional environments to develop their language skills by leveraging their training & domain knowledge in English. They should be able to render training in English in a structured, deliberate manner in order to inform, influence, and educate the learners', 540, 540, '401–600', 'Version', '30 Dec 2021', '08 May 2028', 'Additional Skill Acquisition Programme, Government of Kerala', 'Additional Skill Acquisition Programme, Government of Kerala', 'Communicative English Trainer', 'English Language trainer/soft skill trainer, Master Trainer, Consultant/Advisor, Team Leader(Training)', 'General Qualification', 'N.A.', '{"Theory":"199","Practical":"251","EmployabilitySkills":"30","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "32", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_20.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-2.5-ERT-04651-2025-V1-VBABSS', 'Fundamentals of MS Office', 'education-training-research', 'Education, Training & Research', 2.5, 'The Fundamental of MS Office provides training in Word, Excel, PowerPoint, Outlook, AI Tools and Teams. It equips the students with practical skills for creating documents, managing data, folders and e-mails, making presentations and conducting online meetings efficiently for personal, academic or professional use.', 75, 75, '1–200', 'Version', '07 Oct 2025', '07 Oct 2028', 'Vidya Bharti Akhil Bhartiya Shiksha Sansthan', 'Vidya Bharti Akhil Bhartiya Shiksha Sansthan', 'Office Assistant', '‘O’ level -> ‘A’ level -> Higher education', 'Cross Sectoral Qualification,Multi-Skill Qualification,National Occupational Standard', 'N.A.', '{"Theory":"30","Practical":"45","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "33", "qualification_type": "Cross Sectoral Qualification,Multi-Skill Qualification,National Occupational Standard", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_20.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-2.5-ERT-046362025-V1-ICES', 'Fundamentals of Disaster Management', 'education-training-research', 'Education, Training & Research', 2.5, 'This course provides trainees with a foundational understanding of disaster management concepts and practices. It aims to equip learners with the knowledge and skills to identify hazards, understand risks and vulnerabilities, comprehend the impact of climate change on disasters and participate effectively in preparedness and safety measures at the individual, school and community levels. The course emphasizes practical application through case studies, activities and mock drills.', 60, 60, '1–200', 'Version', '07 Oct 2025', '07 Oct 2028', 'Integrated Council for Entrepreneurship and Skilling (ICES)', 'Integrated Council for Entrepreneurship and Skilling', 'Safety and Preparedness Education', 'Disaster Preparedness Assistant (NSQF Level: 3)', 'General Qualification,National Occupational Standard', 'N.A.', '{"Theory":"20","Practical":"40","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "34", "qualification_type": "General Qualification,National Occupational Standard", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_20.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2021/EHW/ESSC/04794', 'Field Technician Computing And Peripherals', 'electronics-hw', 'Electronics & HW', 4.0, 'A Field Technician -- Computing & Peripherals is responsible for visiting customer premises to install and carry out repair and maintenance of a desktop computer. The individual carries out installation and troubleshooting of computer peripherals also. The individual may also carry out installation, repair and maintenance of a laptop and relevant peripherals', 510, 510, '401–600', 'Version', '30 Dec 2021', '30 Dec 2026', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'After Sales Service', 'Service Engineer – IT Hardware', 'Multi-Skill Qualification', 'N.A.', '{"Theory":"126","Practical":"174","EmployabilitySkills":"60","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "1", "qualification_type": "Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2021/EHW/ESSC/04792', 'Wiring Harness Assembly Operator', 'electronics-hw', 'Electronics & HW', 3.0, 'The Wiring Harness Assembly Operator is responsible for making a wire harness assembly by cutting, stripping and crimping wires and then soldering, connecting, taping and labeling them on a laying board as per the design specifications. This is followed by testing the components of the assembly.', 390, 390, '201–400', 'Version', '30 Dec 2021', '27 Jan 2027', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'Production-EMS', 'Assistant Supervisor - Production', 'Heritage/Traditional Qualification,Multi-Skill Qualification', 'N.A.', '{"Theory":"120","Practical":"150","EmployabilitySkills":"30","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "2", "qualification_type": "Heritage/Traditional Qualification,Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2021/EHW/ESSC/04790', 'Motor & Controller Repairing Technician', 'electronics-hw', 'Electronics & HW', 4.0, 'The Motor & Controller Repairing Technician is responsible for servicing and repairing of the motor and controller in an Electric Vehicle. Along with that, s/he tests the motor and the controller after servicing; and takes corrective action against any malfunction detected.', 450, 450, '401–600', 'Version', '30 Dec 2021', '30 Dec 2026', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'After Sale Support-EM&B', 'Motor and Controller Repairing Engineer', 'Future Skills Qualification,Multi-Skill Qualification', 'N.A.', '{"Theory":"96","Practical":"144","EmployabilitySkills":"60","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "3", "qualification_type": "Future Skills Qualification,Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2021/EHW/ESSC/04789', 'Battery System Repair Technician', 'electronics-hw', 'Electronics & HW', 4.0, 'The Battery System Repair Technician is responsible for servicing and repairing of the battery system in an Electric Vehicle. Along with that, s/he tests the battery system after servicing; and takes corrective actions against any malfunction detected.', 450, 450, '401–600', 'Version', '30 Dec 2021', '30 Dec 2026', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'After Sale Support-EM&B', 'Engineer – Services', 'Future Skills Qualification,Multi-Skill Qualification', 'N.A.', '{"Theory":"90","Practical":"150","EmployabilitySkills":"60","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "4", "qualification_type": "Future Skills Qualification,Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2021/EHW/ESSC/04788', 'Motor and Controller Design Engineer', 'electronics-hw', 'Electronics & HW', 5.0, 'The Motor and Controller Designer is responsible for designing motor, controller and power transmission control system for electric vehicles. The job covers activities like designing the control system, thorough testing and validation of the design.', 600, 600, '401–600', 'Version', '30 Dec 2021', '30 Dec 2026', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'Product Design & Development-EM&B', 'Motor and Controller Design Lead', 'Future Skills Qualification,General Qualification', 'N.A.', '{"Theory":"144","Practical":"216","EmployabilitySkills":"90","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "5", "qualification_type": "Future Skills Qualification,General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2021/EHW/ESSC/04787', 'Battery System Design Engineer', 'electronics-hw', 'Electronics & HW', 5.0, 'The Battery System Designer is responsible for design and implementation of the control system that ensure battery’s longevity, efficiency and safety of the battery in an Electric Vehicle. The job covers activities like designing the battery system, thorough testing and validation of the design.', 600, 600, '401–600', 'Version', '30 Dec 2021', '30 Dec 2026', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'Product Design & Development-EM&B', 'Manager – Design', 'Future Skills Qualification,Multi-Skill Qualification', 'N.A.', '{"Theory":"144","Practical":"216","EmployabilitySkills":"90","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "6", "qualification_type": "Future Skills Qualification,Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2021/EHW/ESSC/04786', 'Electronic Hardware Assembly Operator', 'electronics-hw', 'Electronics & HW', 4.0, 'An Electronic Hardware Assembly Operator is responsible for installing electronic components inside various devices of an Electric Vehicle. Along with that, s/he reviews blueprints and specification sheets, inspects components, performs quality assurance tests, identifies defects in the assembly process; and takes corrective actions against any malfunction detected.', 450, 450, '401–600', 'Version', '30 Dec 2021', '30 Dec 2026', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'After Sales Support-EM&B', 'Production Supervisor', 'Future Skills Qualification,Multi-Skill Qualification', 'N.A.', '{"Theory":"90","Practical":"150","EmployabilitySkills":"60","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "7", "qualification_type": "Future Skills Qualification,Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2021/EHW/ESSC/04785', 'Battery System Assembly Operator', 'electronics-hw', 'Electronics & HW', 4.0, 'The Battery System Assembly Operator system is responsible for assembling the battery pack for an Electric Vehicle. Along with that, s/he tests the engine management system, climate controls, communications and safety systems; and takes corrective actions against any malfunction detected.', 450, 450, '401–600', 'Version', '30 Dec 2021', '30 Dec 2026', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'Assembly-EM&B', 'Battery System Assembly Supervisor', 'Future Skills Qualification,Multi-Skill Qualification', 'N.A.', '{"Theory":"96","Practical":"144","EmployabilitySkills":"60","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "8", "qualification_type": "Future Skills Qualification,Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/EHW/ESSC/05109', 'TV Repair Technician', 'electronics-hw', 'Electronics & HW', 3.0, 'TV Repair Technician – is responsible for interacting with the customer to install the TV as well as diagnose the problem. The individual also needs to assess possible causes of fault reported and rectify problems/faults.', 420, 420, '401–600', 'Version', '27 Jan 2022', '27 Jun 2025', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'After Sales Service', 'Service Technician – Home Appliances', 'Multi-Skill Qualification', 'N.A.', '{"Theory":"90","Practical":"150","EmployabilitySkills":"30","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "9", "qualification_type": "Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/EHW/ESSC/05110', 'Field Technician – Air Conditioner', 'electronics-hw', 'Electronics & HW', 4.0, 'Field Technician – Air Conditioner provides after sales service to customers where he/she needs to interact with customers to diagnose the problem and assess possible causes. The individual identifies and rectifies minor problems or replaces faulty modules for failed parts or recommends factory repair for bigger faults.', 600, 600, '401–600', 'Version', '27 Jan 2022', '27 Jun 2025', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'After Sales Service', 'Field Engineer- RACW', 'Multi-Skill Qualification', 'N.A.', '{"Theory":"156","Practical":"234","EmployabilitySkills":"60","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "10", "qualification_type": "Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/EHW/ESSC/05111', 'Field Technician – Other Home Appliances', 'electronics-hw', 'Electronics & HW', 4.0, 'Field Technician – is responsible for interacting with the customer to install the appliance as well as diagnose the problem. The individual also needs to assess possible causes of fault reported and rectify problems/faults.', 600, 600, '401–600', 'Version', '27 Jan 2022', '27 Jun 2025', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'After Sales Service', 'Service Engineer- Consumer Durables', 'Multi-Skill Qualification', 'N.A.', '{"Theory":"156","Practical":"234","EmployabilitySkills":"60","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "11", "qualification_type": "Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/EHW/ESSC/05127', 'Service Technician – Home Appliances', 'electronics-hw', 'Electronics & HW', 4.0, 'A Service Technician – Home Appliances is responsible to interact with customers to Install the appliance or diagnose the problem to assess possible causes of malfunction. Once the problem and causes have been identified, the individual rectifies the problems or replaces faulty modules/failed parts or recommends factory repairs.', 600, 600, '401–600', 'Version', '27 Jan 2022', '27 Jun 2025', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'After Sales Service', 'Service Engineer – Consumer Durables', 'Multi-Skill Qualification', 'N.A.', '{"Theory":"156","Practical":"234","EmployabilitySkills":"60","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "12", "qualification_type": "Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/EHW/ESSC/05117', 'IT Coordinator in School', 'electronics-hw', 'Electronics & HW', 4.0, 'The individual at work is responsible for operating and maintaining e-learning hardware as well as updating and operating e-learning application. The individual also assists teachers and students in operating the e-learning applications.', 600, 600, '401–600', 'Version', '27 Jan 2022', '27 Jun 2025', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'E Learning Management', 'IT Supervisor In School', 'Heritage/Traditional Qualification,Multi-Skill Qualification', 'N.A.', '{"Theory":"156","Practical":"234","EmployabilitySkills":"60","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "13", "qualification_type": "Heritage/Traditional Qualification,Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/EHW/ESSC/05123', 'Field Technicians – UPS and Inverter', 'electronics-hw', 'Electronics & HW', 4.0, 'The individual at work installs the newly purchased UPS or inverter and interacts with customers to diagnose problems in them, assess possible causes, rectify faults or replace faulty modules or recommends factory repairs for bigger faults.', 600, 600, '401–600', 'Version', '27 Jan 2022', '27 Jun 2025', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'Sales and After Sales Service', 'Service Engineer- UPS Inverter and Control Panel', 'Heritage/Traditional Qualification,Multi-Skill Qualification', 'N.A.', '{"Theory":"156","Practical":"234","EmployabilitySkills":"60","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "14", "qualification_type": "Heritage/Traditional Qualification,Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/EHW/ESSC/05124', 'PCB Assembly Operator', 'electronics-hw', 'Electronics & HW', 4.0, 'PCB assembly operator is responsible for manually placing different types of components on the PCB as per the design requirements and then soldering them.', 600, 600, '401–600', 'Version', '27 Jan 2022', '27 Jun 2025', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'Manufacturing', 'Assembly Supervisor', 'Multi-Skill Qualification', 'N.A.', '{"Theory":"156","Practical":"234","EmployabilitySkills":"60","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "15", "qualification_type": "Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/EHW/ESSC/05107', 'Welding Operator Electronics', 'electronics-hw', 'Electronics & HW', 3.0, 'A Welding Operator Electronics is responsible for bonding the electro-tinned copper lead wire to the centre of steel and cap, of the resistor by welding process.', 420, 420, '401–600', 'Version', '27 Jan 2022', '27 Jun 2025', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'Production', 'Wire Bonding Operator', 'Future Skills Qualification,Multi-Skill Qualification', 'N.A.', '{"Theory":"90","Practical":"150","EmployabilitySkills":"30","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "16", "qualification_type": "Future Skills Qualification,Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/EHW/ESSC/05125', 'DTH Set-top Box Installer and Service Technician', 'electronics-hw', 'Electronics & HW', 4.0, 'A DTH Set-top Box Installer and Service Technician is responsible for installing the set-top box at customer’s premises, addresses the field serviceable complaints and coordinates with the technical team for activation of new connections.', 600, 600, '401–600', 'Version', '27 Jan 2022', '27 Jun 2025', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'After Sales Service', 'DTH/DAS Set Top Box Service Engineer', 'Multi-Skill Qualification', 'N.A.', '{"Theory":"156","Practical":"234","EmployabilitySkills":"60","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "17", "qualification_type": "Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/EHW/ESSC/05126', 'LED Light Repair Technician', 'electronics-hw', 'Electronics & HW', 4.0, 'A LED Light Repair Technician is responsible for checking the non-functional LED light in a systematic manner to find out the fault; dismantles it; repairs the fault and reassemble the light to make it functional.', 600, 600, '401–600', 'Version', '27 Jan 2022', '27 Jun 2025', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'Installation', 'LED Light Project Engineer', 'Multi-Skill Qualification', 'N.A.', '{"Theory":"150","Practical":"240","EmployabilitySkills":"60","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "18", "qualification_type": "Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/EHW/ESSC/05113', 'Smartphone Assembly Technician', 'electronics-hw', 'Electronics & HW', 4.0, 'A Smartphone assembly technician is responsible for interpreting assembly instructions, blueprint specifications, etc. to assemble or fix smartphone parts/components in correct position and alignment using approved techniques and equipment in a production unit.', 600, 600, '401–600', 'Version', '27 Jan 2022', '27 Jun 2025', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'Manufacturing', 'Assembly Supervisor', 'Heritage/Traditional Qualification,Multi-Skill Qualification', 'N.A.', '{"Theory":"156","Practical":"234","EmployabilitySkills":"60","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "19", "qualification_type": "Heritage/Traditional Qualification,Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/EHW/ESSC/05139', 'Pick-and-Place Assembly Operator', 'electronics-hw', 'Electronics & HW', 4.0, 'A Pick-and-Place Assembly Operator at work programs, operates and maintains the automated pick-and-place machine for placing different types of components on the surface of PCBs for soldering.', 600, 600, '401–600', 'Version', '27 Jan 2022', '27 Jun 2025', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'Assembly and soldering', 'EMS Supervisor', 'Multi-Skill Qualification', 'N.A.', '{"Theory":"156","Practical":"234","EmployabilitySkills":"60","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "20", "qualification_type": "Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/EHW/ESSC/05136', 'Electronics Manufacturing Services Technician', 'electronics-hw', 'Electronics & HW', 4.0, 'Electronics Manufacturing Services Technician in this job job works on SMT machines, circuit boards and soldering equipment. The individual is responsible for the maintenance and troubleshooting of SMT equipment and also assists in the assembly and programming of SMT equipment.', 600, 600, '401–600', 'Version', '27 Jan 2022', '27 Jun 2025', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'Assembly and soldering', 'EMS Supervisor', 'Heritage/Traditional Qualification,Multi-Skill Qualification', 'N.A.', '{"Theory":"156","Practical":"234","EmployabilitySkills":"60","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "21", "qualification_type": "Heritage/Traditional Qualification,Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/EHW/ESSC/05118', 'Solar Panel Installation Technician', 'electronics-hw', 'Electronics & HW', 4.0, 'Solar Panel Installation Technician in this job checks the installation site, understands the layout requirement as per design, assesses precautionary measures to be taken, installs the solar panel as per customers requirement and ensures effective functioning of the system post installation', 600, 600, '401–600', 'Version', '27 Jan 2022', '27 Jun 2025', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'Installation', 'Solar Panel Installation Engineer', 'Future Skills Qualification,Multi-Skill Qualification', 'N.A.', '{"Theory":"156","Practical":"234","EmployabilitySkills":"60","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "22", "qualification_type": "Future Skills Qualification,Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/EHW/ESSC/05138', 'Digital Cable Technician – Access', 'electronics-hw', 'Electronics & HW', 4.0, 'Digital Cable Technician in this job programs, install, maintenance and repair of cable television and set-top box at premises. The technicians work on the trunk line and sub-trunk line, and inspect cable lines, lay cables under or on top of the building and repair cable faults.', 600, 600, '401–600', 'Version', '27 Jan 2022', '27 Jan 2027', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'After Sales Service', 'Digital Cable TV Supervisor- Network', 'Multi-Skill Qualification', 'N.A.', '{"Theory":"156","Practical":"236","EmployabilitySkills":"60","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "23", "qualification_type": "Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/EHW/ESSC/05133', 'HVAC Technician', 'electronics-hw', 'Electronics & HW', 4.0, 'The individual in this job role maintains and repairs heating, air conditioning and ventilation systems in commercial and industrial areas. The individual engages with the client to understand the work requirement and follows organizational norms to complete the work.', 600, 600, '401–600', 'Version', '27 Jan 2022', '27 Jun 2025', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'After Sales Support', 'HVAC Supervisor', 'Future Skills Qualification,Multi-Skill Qualification', 'N.A.', '{"Theory":"156","Practical":"234","EmployabilitySkills":"60","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "24", "qualification_type": "Future Skills Qualification,Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/EHW/ESSC/05128', 'Through-hole Assembly Operator', 'electronics-hw', 'Electronics & HW', 4.0, 'A Through-hole Assembly Operator is responsible for manually fixing components using hand tools, operating and maintaining the automated insertion machine used for placing different types of components on the through-hole PCBs.', 600, 600, '401–600', 'Version', '27 Jan 2022', '27 Jun 2025', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'Assembly and Soldering', 'EMS Supervisor', 'Heritage/Traditional Qualification,Multi-Skill Qualification', 'N.A.', '{"Theory":"156","Practical":"234","EmployabilitySkills":"60","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "25", "qualification_type": "Heritage/Traditional Qualification,Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/EHW/ESSC/05129', 'Wireman Control Panel Electronics', 'electronics-hw', 'Electronics & HW', 3.0, 'The individual at work is responsible for wiring all components present within the panel as per specifications provided by the design engineering team.', 420, 420, '401–600', 'Version', '27 Jan 2022', '27 Jun 2025', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'Manufacturing', 'Electrical Assembly Supervisor – Control
Panel', 'Heritage/Traditional Qualification,Multi-Skill Qualification', 'N.A.', '{"Theory":"90","Practical":"150","EmployabilitySkills":"30","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "26", "qualification_type": "Heritage/Traditional Qualification,Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/EHW/ESSC/05381', 'In-Store Demonstrator', 'electronics-hw', 'Electronics & HW', 3.0, 'In-Store Demonstrator is responsible for effective engagement with the  customers, understanding their buying requirements, explaining the promotions, schemes and offers of the store, assisting them in choosing the right model of appliance/device and completing the sales transaction.', 450, 450, '401–600', 'Version', '24 Feb 2022', '24 Feb 2027', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'Pre sales service', 'Business Development Executive', 'Heritage/Traditional Qualification,Multi-Skill Qualification', 'N.A.', '{"Theory":"90","Practical":"120","EmployabilitySkills":"30","OJT_Mandatory":"210"}', false, '{}'::text[], '{"source_row": "27", "qualification_type": "Heritage/Traditional Qualification,Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/EHW/ESSC/05386', 'Electronics Machine Maintenance Executive', 'electronics-hw', 'Electronics & HW', 4.0, 'The individual at work is carries out scheduled maintenance of machines used on shop floor using manufacturers manual and as per training given by manufacturer in order to have zero unscheduled downtime.', 600, 600, '401–600', 'Version', '24 Feb 2022', '25 Jun 2025', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'Maintenance', 'Maintenance Supervisor, Maintenance Engineer', 'Future Skills Qualification,Multi-Skill Qualification', 'N.A.', '{"Theory":"156","Practical":"234","EmployabilitySkills":"60","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "28", "qualification_type": "Future Skills Qualification,Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/EHW/ESSC/05383', 'Assembly Operator - TV', 'electronics-hw', 'Electronics & HW', 4.0, 'The individual at work is responsible for fitting in the different modules of the television set into the frame using appropriate screws and connectors during the different stages of the assembly process. The individual is expected to minimise errors at every stage since the assembly line is continuously in motion.', 600, 600, '401–600', 'Version', '24 Feb 2022', '24 Jun 2025', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'Assembly- EMS', 'Assembly Supervisor', 'Heritage/Traditional Qualification,Multi-Skill Qualification', 'N.A.', '{"Theory":"150","Practical":"240","EmployabilitySkills":"60","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "29", "qualification_type": "Heritage/Traditional Qualification,Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/EHW/ESSC/05382', 'Assembly Operator - RAC', 'electronics-hw', 'Electronics & HW', 4.0, 'The individual at work is responsible for assembling and wiring up of various components, modules or sub- assemblies and systems to make the complete product.', 600, 600, '401–600', 'Version', '24 Feb 2022', '24 Jun 2025', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'Assembly-EMS', 'Assembly Supervisor, Line Process Auditor', 'Heritage/Traditional Qualification,Multi-Skill Qualification', 'N.A.', '{"Theory":"156","Practical":"234","EmployabilitySkills":"60","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "30", "qualification_type": "Heritage/Traditional Qualification,Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/EHW/ESSC/05380', 'Electrical Assembly Operator - Control Panel', 'electronics-hw', 'Electronics & HW', 3.0, 'The individual at work mounts and installs and connects internal electronic modules devices and components on the control panel.', 450, 450, '401–600', 'Version', '24 Feb 2022', '24 Jun 2025', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'Assembly-I&A', 'Electrical Assembly Supervisor – Control Panel', 'Future Skills Qualification,Multi-Skill Qualification', 'N.A.', '{"Theory":"120","Practical":"210","EmployabilitySkills":"30","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "31", "qualification_type": "Future Skills Qualification,Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/EHW/ESSC/05378', 'Solar LED Technician', 'electronics-hw', 'Electronics & HW', 4.0, 'The individual is capable of installing various types of solar home based LED lighting, outdoor and street lighting as per given instructions. The person should be able to identify faults in a solar PV system and carry out repair at preliminary level in line with given performance parameters. The individual must adhere to all the relevant environmental, safety and regulatory requirements while carrying out his/her job duties.', 600, 600, '401–600', 'Version', '24 Feb 2022', '27 May 2025', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'Installation-S&L', 'Solar LED Project Engineer', 'Future Skills Qualification,Multi-Skill Qualification', 'N.A.', '{"Theory":"156","Practical":"234","EmployabilitySkills":"60","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "32", "qualification_type": "Future Skills Qualification,Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/EHW/ESSC/05376', 'Winding Operator', 'electronics-hw', 'Electronics & HW', 4.0, 'The Winding Operator winds the metal-alloy wire or metalized film on to a core by using an automated or semi-automated winding machines in the process of manufacturing of capacitors and resistors. The individual also sample checks the resistance or capacitance of the winding.', 600, 600, '401–600', 'Version', '24 Feb 2022', '27 May 2025', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'Production-S&C', 'Die Attach and Wire Bonding Engineer', 'Future Skills Qualification,Multi-Skill Qualification', 'N.A.', '{"Theory":"156","Practical":"234","EmployabilitySkills":"60","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "33", "qualification_type": "Future Skills Qualification,Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/EHW/ESSC/05374', 'Incoming Materials Inspector - Electronics Items', 'electronics-hw', 'Electronics & HW', 4.0, 'The Incoming Materials Inspector receives components and modules at the factory premises and verifies that the quantity and specifications of the parts received are as per the respective purchase order. The individual is responsible for inspecting the incoming materials and coordinating with various departments within an organization.', 600, 600, '401–600', 'Version', '24 Feb 2022', '24 Jun 2025', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'Incoming Inspection-EMS', 'Quality Supervisor', 'Heritage/Traditional Qualification,Multi-Skill Qualification', 'N.A.', '{"Theory":"150","Practical":"240","EmployabilitySkills":"60","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "34", "qualification_type": "Heritage/Traditional Qualification,Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/EHW/ESSC/05373', 'Purchase-Executive', 'electronics-hw', 'Electronics & HW', 4.0, 'Also known as Procurement Executive, the individual purchases quality materials in a timely manner at competitive prices to maintain the optimum inventory level. The individual also collects information about the materials required by different departments and selects the appropriate supplier.', 600, 600, '401–600', 'Version', '24 Feb 2022', '24 Jun 2025', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'Purchase and Procurement', 'Purchase Engineer', 'Multi-Skill Qualification', 'N.A.', '{"Theory":"156","Practical":"234","EmployabilitySkills":"60","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "35", "qualification_type": "Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/EHW/ESSC/05372', 'LED Luminary Mechanical Assembly and Testing Technician', 'electronics-hw', 'Electronics & HW', 4.0, 'The individual at work is responsible for fitting together different electronic, electrical and mechanical parts and connect them to make the final LED luminary as per product design as well as testing LED luminaries using different testing equipment.', 600, 600, '401–600', 'Version', '24 Feb 2022', '24 Jun 2025', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'Assembly-S&L', 'LED Light Assembly Engineer', 'Heritage/Traditional Qualification,Multi-Skill Qualification', 'N.A.', '{"Theory":"156","Practical":"234","EmployabilitySkills":"60","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "36", "qualification_type": "Heritage/Traditional Qualification,Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/EHW/ESSC/05371', 'Maintenance Technician', 'electronics-hw', 'Electronics & HW', 3.0, 'he individual at work undertakes periodical preventive maintenance of machines as per the set schedule for the electrical and mechanical systems installed in the factory. The individual is also responsible for attending to any breakdown and repairs to restore temporary or permanent functioning or call expert for significant down time problems.', 450, 450, '401–600', 'Version', '24 Feb 2022', '24 Jun 2025', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'Maintenance', 'Electronics Machine Maintenance Executive', 'Heritage/Traditional Qualification,Multi-Skill Qualification', 'N.A.', '{"Theory":"120","Practical":"210","EmployabilitySkills":"30","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "37", "qualification_type": "Heritage/Traditional Qualification,Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/EHW/ESSC/05638', 'Assistant Installation Computing And Peripherals', 'electronics-hw', 'Electronics & HW', 3.0, 'The individual at work is responsible for installing newly purchased products, troubleshooting system problems and, configuring peripherals such as printers, scanners and network devices.', 450, 450, '401–600', 'Version', '31 Mar 2022', '31 Jul 2025', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'After Sales Service', 'Field Technician - Computing & Peripherals', 'General Qualification', 'N.A.', '{"Theory":"120","Practical":"210","EmployabilitySkills":"30","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "38", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/EHW/ESSC/05636', 'Mobile Phone Hardware Repair Technician', 'electronics-hw', 'Electronics & HW', 4.0, 'The individual at work is responsible for rectifying faults in the mobile phone brought in by the customer. The individual receives the faulty mobile phone, diagnoses the problems, performs front end or hardware level repair as required, resolves software issues and ensures effective functioning before delivering back to customer.', 600, 600, '401–600', 'Version', '31 Mar 2022', '31 Aug 2025', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'After Sales Service', 'Mobile Phone Hardware Service Engineer', 'Multi-Skill Qualification', 'N.A.', '{"Theory":"156","Practical":"234","EmployabilitySkills":"60","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "39", "qualification_type": "Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/EHW/ESSC/05387', 'Assembly Line Operator', 'electronics-hw', 'Electronics & HW', 3.0, 'The individual at work is responsible for assembling the different modules in the IT hardware to complete the product. The individual receives different electronic and electromechanical modules, fits and assembles them together. The operator may assemble multiple modules and/or products by following operating procedures for different models.', 450, 450, '401–600', 'Version', '24 Feb 2022', '24 Jun 2025', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'Assembly-EMS', 'Assembly Supervisor', 'Heritage/Traditional Qualification,Multi-Skill Qualification', 'N.A.', '{"Theory":"120","Practical":"210","EmployabilitySkills":"30","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "40", "qualification_type": "Heritage/Traditional Qualification,Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/EHW/ESSC/05877', 'Drone Manufacturing and Assembly Technician', 'electronics-hw', 'Electronics & HW', 4.0, 'A Drone Manufacturing and Assembly Technician simulates, assembles, tests and debugs drones as part of a Drone manufacturing line, whilst ensuring adherence to standard working practices. The individuals in this job assemble and manufacture drones of varying sizes that are used in various applications such as taking aerial photos or videos, transporting goods, firefighting and emergency operations, power line inspections, clandestine inspections, etc.', 450, 450, '401–600', 'Version', '26 May 2022', '26 Oct 2025', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'Assembly- I & A', 'Assembly Supervisor', 'Future Skills Qualification,Multi-Skill Qualification', 'N.A.', '{"Theory":"96","Practical":"144","EmployabilitySkills":"60","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "41", "qualification_type": "Future Skills Qualification,Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/EHW/NIELIT/06117', 'Repair and Maintenance Technician (Hospital Equipment)', 'electronics-hw', 'Electronics & HW', 4.0, 'A Repair and Maintenance Technician for Hospital Equipment is responsible for ensuring the functionality and reliability of diagnostic, therapeutic, monitoring, and surgical devices used in healthcare facilities. Key responsibilities include diagnosing and repairing faults, performing preventive and corrective maintenance, calibrating equipment for optimal performance, and adhering to safety and regulatory standards.', 420, 420, '401–600', 'Version', '28 Jul 2022', '28 Jul 2025', 'National Institute of Electronics and Information Technology (NIELIT)', 'National Institute of Electronics and Information Technology (NIELIT) NIELIT Bhawan, Plot No. 3, PSP Pocket, Sector-8, Dwarka, New Delhi-110077', 'Electronics Equipment Services', 'Professional:
Sr. Technician
 -> Service Engineer ->Entrepreneur
Academics:
Higher Level Courses in Medical Electronics', 'Future Skills Qualification,General Qualification', 'N.A.', '{"Theory":"150","Practical":"210","EmployabilitySkills":"30","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "42", "qualification_type": "Future Skills Qualification,General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/EHW/NIELIT/06119', 'Repair and Maintenance  Assistant (X-Ray & Ultrasound Machine)', 'electronics-hw', 'Electronics & HW', 3.0, 'The Repair and Maintenance Assistant for X-Ray and Ultrasound Machines specializes in diagnosing, repairing, and maintaining medical imaging devices used in healthcare settings. Their responsibilities include routine maintenance, troubleshooting technical faults, calibrating equipment, and ensuring compliance with safety and healthcare regulations. They are proficient in using diagnostic tools and software, documenting repair activities, and providing technical support to healthcare professionals.', 330, 330, '201–400', 'Version', '28 Jul 2022', '28 Jul 2025', 'National Institute of Electronics and Information Technology (NIELIT)', 'National Institute of Electronics and Information Technology (NIELIT) NIELIT Bhawan, Plot No. 3, PSP Pocket, Sector-8, Dwarka, New Delhi-110077', 'Electronics Equipment Services', 'Professional:
Technician ->Sr. Technician
 -> Service Engineer ->Entrepreneur
Academics:
Higher Level Courses in Medical Electronics', 'Future Skills Qualification', 'N.A.', '{"Theory":"120","Practical":"150","EmployabilitySkills":"30","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "43", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/EHW/NIELIT/06120', 'Repair & Maintenance Assistant (ICCU Equipments)', 'electronics-hw', 'Electronics & HW', 3.0, 'The Repair & Maintenance Assistant for ICCU Equipment specializes in maintaining, troubleshooting, and repairing critical medical devices used in Intensive Coronary Care Units, such as defibrillators, ECG machines, ventilators, and patient monitors. Responsibilities include diagnosing technical faults, performing preventive maintenance and calibration, ensuring compliance with safety and healthcare standards, and documenting repair activities.', 330, 330, '201–400', 'Version', '28 Jul 2022', '28 Jul 2025', 'National Institute of Electronics and Information Technology (NIELIT)', 'National Institute of Electronics and Information Technology (NIELIT) NIELIT Bhawan, Plot No. 3, PSP Pocket, Sector-8, Dwarka, New Delhi-110077', 'Electronics Equipment Services', 'Professional:
Technician-> Sr. Technician
 -> Service Engineer ->Entrepreneur
Academics:
Higher Level Courses in Medical Electronics', 'Future Skills Qualification,General Qualification', 'N.A.', '{"Theory":"120","Practical":"150","EmployabilitySkills":"30","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "44", "qualification_type": "Future Skills Qualification,General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/EHW/NIELIT/06338', 'Certified Repair & Maintenance Assistant (Power Supply, Inverter & UPS)', 'electronics-hw', 'Electronics & HW', 3.0, 'The Certified Repair & Maintenance Assistant specializes in diagnosing, repairing, and maintaining power supply systems, inverters, and UPS units. Their role involves troubleshooting electrical and electronic faults, performing preventive and corrective maintenance, testing and calibrating systems to ensure optimal performance, and adhering to safety protocols.', 360, 360, '201–400', 'Version', '25 Aug 2022', '25 Aug 2025', 'National Institute of Electronics and Information Technology (NIELIT)', 'National Institute of Electronics and  Information Technology, NIELIT Bhawan, Plot No. 3, PSP Pocket, Sector-8, Dwarka, New Delhi-110 077.', 'a)	Technical support of UPS/Inverter
b)	UPS Repair Technician
c)	Inverter Repair Technician
d)	Assembly Operator of UPS/Inverter', 'Academic Progression:
CHM Technician(O-Level)-> CHM-A Level
Professional Progression:
Supervisor-> Maintenance Manager', 'Future Skills Qualification', 'N.A.', '{"Theory":"120","Practical":"180","EmployabilitySkills":"30","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "45", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
