INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-5.5-EH-00737-2023-V1-MUR', 'Embedded IoT Developer', 'electronics-hw', 'Electronics & HW', 5.5, 'The course content includes designing and developing embedded systems and IoT devices, programming microcontrollers and microprocessors, integrating sensors and actuators, implementing wireless communication protocols, and developing software for IoT platforms. Additionally, individuals with these skills may be responsible for managing the product development life cycle, including requirements gathering and analysis, system design and architecture, testing and validation, and production and deployment.
The purpose of the syllabus is to equip students with the necessary skills and knowledge take on a range of roles in the embedded systems and IoT industry, including product development, testing, deployment, and maintenance.', 660, 660, '601–800', 'Version', '31 Aug 2023', '31 Aug 2026', 'Mewar University', 'Mewar University, 
NH - 48 Gangrar, Chittorgarh, Rajasthan-312901
www.mewaruniversity.org', 'Project Engineering', 'Embedded IoT Developer', 'General Qualification', 'N.A.', '{"Theory":"145","Practical":"395","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "53", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
