INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-06-EH-00567-2023-V2-NIELIT & Version 2', 'Embedded Software Engineer', 'electronics-hw', 'Electronics & HW', 6.0, 'Nature: 
❖  The Certificate course is targeted for creating qualified professionals in the field of Embedded & IoT. Qualification has been developed in consultation with industry experts in the domain, aiming at Empowering the future workforce with necessary skills for employment and entrepreneur development of the qualifier.
Purpose: 
❖	The purpose is to develop the skill set required for Design and Development of the Embedded System Applications using suitable Hardware and Software tools. This course offers a range of topics of immediate relevance to industry and makes the participants exactly suitable for Embedded Industry', 960, 960, '801–1000', 'Version', '23 Jun 2023', '23 Jun 2026', 'National Institute of Electronics and Information Technology (NIELIT)', 'NATIONAL INSTITUTE OF ELECTRONICS AND INFORMATION TECHNOLOGY', 'Embedded System Design, IoT Solution', 'Academic: 
Advanced courses in Embedded Real-time systems area like the building of YOCTO Linux for Embedded Systems. 

Professional: 
Embedded Software Engineer –> Team Lead (Embedded Software) –> Project Manager (Embedded Software & Real-Time Systems)', 'Future Skills Qualification', 'N.A.', '{"Theory":"260","Practical":"340","EmployabilitySkills":"120","OJT_Mandatory":"240"}', false, '{}'::text[], '{"source_row": "55", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-EH-01966-2024-V1-NIELIT', 'Biomedical Equipment Maintenance Assistant', 'electronics-hw', 'Electronics & HW', 3.0, 'The course delves into the tools and techniques used for servicing and maintaining medical equipment, including soldering, de-soldering, and the use of test and measuring instruments. It explores the fundamental concepts of electrical current, voltage, and power, enabling learners to understand the working principles of passive components like resistors, capacitors, and inductors. Active components, such as semiconductors and integrated circuits, are also covered in detail, providing insights into their design, testing, and applications in medical instrumentation.

Biomedical instrumentation and measurement form a crucial part of the course, covering topics such as the man-instrument system, physiological systems of the human body, sources of bio-electric potentials, and the use of microscopes. ECG machines, pH meters, patient monitors, and diagnostic equipment are thoroughly examined, including their working principles, testing procedures, and calibration techniques. The course concludes with a focus on employability skills, preparing learners for success in the medical equipment and devices industry.', 300, 300, '201–400', 'Version', '31 Jan 2024', '31 Jan 2027', 'National Institute of Electronics and Information Technology (NIELIT)', 'NATIONAL INSTITUTE OF ELECTRONICS AND INFORMATION TECHNOLOGY', 'Electronics Equipment Services', 'Hospital Equipment Technician', 'General Qualification', 'N.A.', '{"Theory":"90","Practical":"120","EmployabilitySkills":"30","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "56", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-EH-01992-2024-V1-TSSC', 'Assistant Robotics Technician (Introduction)', 'electronics-hw', 'Electronics & HW', 3.0, 'An Assistant Robotics Technician (Introduction) carries out the setup for Testing of small-scale robotics systems followed by its Inspection for desired and rated functionality, while ensuring adherence to standard working practices. The role of the individual is to understand the various parts of a small-scale robotic systems such as robotics arms and rovers used for various applications, testing and learning how to control them. This job role would help them be ready for a job in the small-scale robotics systems industry assisting senior robotics technicians.', 420, 420, '401–600', 'Version', '31 Jan 2024', '31 Jan 2027', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skill Council of India (ESSCI)', 'After Sales Service - I & A', 'Robotics Technician', 'Future Skills Qualification', 'N.A.', '{"Theory":"90","Practical":"180","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "57", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
