INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('•	QG-03-EH-00992-2023-V2-NIELIT', 'Product Assembly Assistant (Solar-LED)', 'electronics-hw', 'Electronics & HW', 3.0, 'The qualification spans diverse subjects concerning electrical and electronic components and devices, emphasizing the design, assembly, and utilization of solar-LED lighting products. Enrollees will acquire crucial skills and knowledge encompassing the conceptualization of electronic components and devices, LED characteristics and specifications, power conversion from AC-DC to DC-DC, LED driver circuit design, assembly of LED lighting products, characteristics of solar PV cells, batteries suitable for solar-LED lighting products, and the design, assembly, and installation of solar-LED lighting products.', 330, 330, '201–400', 'Version', '29 Sep 2023', '29 Sep 2026', 'National Institute of Electronics and Information Technology (NIELIT)', 'NATIONAL INSTITUTE OF ELECTRONICS AND INFORMATION TECHNOLOGY
