INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-3.5-EH-02638-2024-V1-NIELIT', '3D Printing: Design and Development Fundamentals', 'electronics-hw', 'Electronics & HW', 3.5, 'This NOS offers an in-depth exploration of the fundamentals of design and additive manufacturing, with a focus on 3D printing technology. Participants will gain a comprehensive understanding of the significance of 3D printing across various industries. Practical aspects, such as modeling using software, slicing parameters, and operating a 3D printer, including parts identification, safety precautions, and troubleshooting techniques, will be covered. The program equips students with design, problem-solving, and entrepreneurship skills.', 60, 60, '1–200', 'Version', '30 May 2024', '30 May 2027', 'National Institute of Electronics and Information Technology (NIELIT)', 'National Institute of Electronics and Information Technology (NIELIT)', '3D Printing Technology', '3D Printing Technician', 'Future Skills Qualification,OEM Qualification', 'N.A.', '{"Theory":"15","Practical":"45","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "90", "qualification_type": "Future Skills Qualification,OEM Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-EH-02859-2024-V1-WBSCVT', 'Service Assistant (Domestic Electronics Products)', 'electronics-hw', 'Electronics & HW', 3.0, 'Service Assistant (Domestic Electronics Products) will provide service and customer support for the domestic electronics product during field visits or dispatches. Manage all onsite installation, repair, maintenance and test tasks. Diagnose errors or technical problems and determine proper solutions. Produce timely and detailed service reports.', 390, 390, '201–400', 'Version', '25 Jul 2024', '24 Jul 2027', 'West Bengal State Council of Technical & Vocational Education and Skill Development (WBSCTVESD)', 'West Bengal State Council of Technical & Vocational Education and Skill Development', 'Service  Assistant (Domestic Electronics Products)', 'Horizontal Progression:
