INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-EH-02859-2024-V1-WBSC', 'Service  Assistant (Domestic Electronics Products)', 'electronics-hw', 'Electronics & HW', 3.0, 'Service Assistant (Domestic Electronics Products) will provide service and customer support for the domestic electronics product during field visits or dispatches. Manage all onsite installation, repair, maintenance and test tasks. Diagnose errors or technical problems and determine proper solutions. Produce timely and detailed service reports.', 390, 390, '201–400', 'Version', '25 Jul 2024', '24 Jul 2027', 'West Bengal State Council of Technical & Vocational Education and Skill Development (WBSCTVESD)', 'West Bengal State Council of Technical & Vocational Education and Skill Development', 'Service  Assistant (Domestic Electronics Products)', 'Horizontal Progression:
1. Junior Mechanic (Electrical/ Electronics/ Instrumentation)
2. Mechanic Auto Electrical & Electronics
3.  Wireman Control Panel Electronics 
Vertical  Progression:
1. Electronics Mechanic', 'General Qualification', 'N.A.', '{"Theory":"90","Practical":"180","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "141", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-4.5-EH-02556-2024-V1-CRISP', 'Senior Automation Technician', 'electronics-hw', 'Electronics & HW', 4.5, 'A Senior Automation Technician is a professional responsible for designing, implementing, and maintaining automation systems in industrial settings. Their primary goal is to optimize processes, enhance efficiency, and ensure the smooth operation of manufacturing or production facilities. The job description may vary depending on the industry and specific company needs, but generally includes the following responsibilities and Technical & Managerial skills. This qualification pack enables Senior Automation technician to Work on PLC, SCADA, Instrumentation, Electrical Control, Electronic Maintenance and its integration to boost up productivity in process industries.', 450, 450, '401–600', 'Version', '30 May 2024', '30 May 2027', 'Centre for Research and Industrial Staff Performance (CRISP), Bhopal', 'CRISP', 'Industrial Automation', 'Automation Analyst
Automation Engineer', 'Future Skills Qualification,General Qualification,National Occupational Standard,Upskilling Qualification', 'N.A.', '{"Theory":"90","Practical":"210","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "142", "qualification_type": "Future Skills Qualification,General Qualification,National Occupational Standard,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-EH-03422-2024-V3-ESSC', 'Drone Service Technician', 'electronics-hw', 'Electronics & HW', 4.0, 'The Drone Service Technician specializes in troubleshooting, repairing, and optimizing drone systems to ensure peak performance. This role involves diagnosing technical malfunctions, repairing or replacing faulty components, calibrating sensors and control systems, and verify functionality. By adhering to industry standards and safety protocols, the technician ensures that drones are operationally efficient and meet customer requirements. With a focus on precision and technical expertise, the role contributes to the reliability and longevity of drone operations across various applications.', 450, 450, '401–600', 'Version', '17 Dec 2024', '17 Dec 2027', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'After sales Service', 'Drone Operator', 'General Qualification', 'N.A.', '{"Theory":"90","Practical":"150","EmployabilitySkills":"60","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "143", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-EH-03421-2024-V3-ESSC', 'Multi-Skill Technician (Home Appliances)', 'electronics-hw', 'Electronics & HW', 4.0, 'The Multi-Skill Technician (Home Appliances) is responsible for diagnosing, repairing, installing, and maintaining a variety of household electronic appliances, including LED lighting systems, geysers, fans, water purifiers, and mixers/juicers/grinders. The role involves interacting with customers to understand their issues, performing technical diagnostics, replacing faulty components, and ensuring proper functionality through hands-on repairs and testing. With a focus on safety, precision, and customer satisfaction, the technician provides high-quality service while adhering to the latest industry standards and best practices.', 420, 720, '601–800', 'Version', '17 Dec 2024', '17 Dec 2027', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'After sales Service', 'Service Engineer - Consumer Durables', 'Multi-Skill Qualification', 'N.A.', '{"Theory":"105","Practical":"135","EmployabilitySkills":"60","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "144", "qualification_type": "Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-EH-01402-2023-V1-NTTF', 'Technician Electronics and Instrumentation', 'electronics-hw', 'Electronics & HW', 4.0, 'The Candidate will be able to test and develop Electronics, Communication and Embedded System products. Will able to design and develop PCB Boards and electronics systems in Power Electronics, Electronic Instrumentation, Embedded system and IoT.

The subjects covered in this Programme are –Analog and Digital Electronics, Analog Communication, PCB Design, Computer Programming, Electronic Circuit Simulation, Electronic Instrumentation, Circuit Analysis, Industrial Electronics, Microcontroller and Applications, IoT and Employability Skills.', 1200, 1200, '1001–1200', 'Version', '30 Nov 2023', '29 Nov 2026', 'Nettur Technical Training Foundation (NTTF)', 'NETTUR TECHNICAL TRAINING FOUNDATION 23/24, II PHASE, PEENYA INDUSTRIAL AREA, BENGALURU – 560058, KARNATAKA', 'Testing and
developing', 'Vertical Progression: Senior Technician - Engineer - Supervisor – Manager', 'General Qualification', 'N.A.', '{"Theory":"480","Practical":"570","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "145", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-4.5-EH-01403-2023-V1-NTTF', 'Senior Technician Electronics Engineering and Embedded systems', 'electronics-hw', 'Electronics & HW', 4.5, 'The Candidate will be able to do Electronic Hardware Design & Testing, Design & installation of PCB, Testing VLSI systems, Testing Embedded Hardware, Design and develop Electronics circuits, Automation of systems, Implement IoT Systems. Will have Exposure on VLSI design, Communication Protocols, Artificial Intelligence and Machine Learning, Embedded system, PLC and IoT.

The subjects covered in this Programme are – Digital Communication, Advanced Microcontrollers- PIC & ARM, VLSI Technology, Artificial Intelligence and Machine Learning, IoT, Industrial Management, Data Communication, Programmable Logic Controller and Employability Skills. Hands- on projects emphasise design of Electronics Systems using Various Microcontrollers, communication protocols, Power electronics, Artificial Intelligence, IoT and Employability Skills.', 1380, 1380, '1201–2400', 'Version', '30 Nov 2023', '30 Nov 2026', 'Nettur Technical Training Foundation (NTTF)', 'NETTUR TECHNICAL TRAINING FOUNDATION 23/24, II PHASE, PEENYA INDUSTRIAL AREA, BENGALURU – 560058, KARNATAKA', 'Design, Testing & installation', 'Vertical Progression: Senior Technician - Engineer - Supervisor – Manager - General Manager - Entrepreneur', 'General Qualification', 'N.A.', '{"Theory":"390","Practical":"600","EmployabilitySkills":"60","OJT_Mandatory":"330"}', false, '{}'::text[], '{"source_row": "146", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-3.5-EH-01398-2023-V1-NTTF', 'Electrical and Electronics Equipment', 'electronics-hw', 'Electronics & HW', 3.0, 'Fitter - Electrical and Electronics Equipment will be able to identify the components used and carry out sub assembly/assembly of Electrical & Electronics equipments and harnesses in product manufacturing.
The subjects covered in this programme are – 
Engineering Mathematics - I, Technical Communication - I, Electrical and Electronics, Modern Shop Floor Practices, Industrial Orientation, Manufacturing Technology, Engineering Mathematics - II, Technical Communication - II, Basics of Computer, 
Analog Electronics, Engineering Graphics, Testing of Electronics components, Introduction to Wire Harnessing, Employability Skills, Electrical and Electronics Lab, Mechanical Workshop, Analog Electronics Lab, OJT', 1200, 1200, '1001–1200', 'Version', '30 Nov 2023', '30 Nov 2026', 'Nettur Technical Training Foundation (NTTF)', 'NETTUR TECHNICAL TRAINING FOUNDATION 23/24, II PHASE, PEENYA INDUSTRIAL AREA, BENGALURU – 560058, KARNATAKA', 'Assembly & Fitting', 'Vertical Progression: Technician - Senior Technician - Engineer - Supervisor – Manager', 'General Qualification', 'N.A.', '{"Theory":"420","Practical":"135","EmployabilitySkills":"60","OJT_Mandatory":"585"}', false, '{}'::text[], '{"source_row": "147", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-4-EH-01399-2023-V1-NTTF', 'Technician Electrical and Electronics Assembly', 'electronics-hw', 'Electronics & HW', 4.0, 'The candidate will be able to manufacture and assemble various Electrical and Electronic connectors and harness, circuits and components, Industrial electrical- electronic and High-power conditioning, and Aerospace industry. Maintenance and troubleshooting of Power Systems.

The subjects covered in this programme are – 
Industrial Electronics, Digital Electronics, Material Technology, Sensors and Transducers, Assembling and Testing of Product, Soldering Techniques, Microcontrollers and Applications, Pneumatics, Programmable Logic Controller, Quality Management System, Manufacturing Engineering, Wire Harness- Types, Specification and Standards, Employability Skills, Digital Electronics Lab, Industrial Electronics Lab, Sensors and Transducers Lab, Microcontrollers and Applications Lab, PLC Lab, Pneumatics Lab, OJT', 1200, 1200, '1001–1200', 'Version', '30 Nov 2023', '30 Nov 2026', 'Nettur Technical Training Foundation (NTTF)', 'NETTUR TECHNICAL TRAINING FOUNDATION 23/24, II PHASE, PEENYA INDUSTRIAL AREA, BENGALURU – 560058, KARNATAKA', 'Assembly & Fitting', 'Vertical Progression: Senior Technician - Engineer - Supervisor – Manager', 'General Qualification', 'N.A.', '{"Theory":"420","Practical":"150","EmployabilitySkills":"60","OJT_Mandatory":"570"}', false, '{}'::text[], '{"source_row": "148", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-4.5-EH-01400-2023-V1-NTTF', 'Senior Technician-Electrical Equipment Manufacturing', 'electronics-hw', 'Electronics & HW', 4.5, 'The candidate will be able to manufacture and assemble various Electrical and Electronic connectors and harness, circuits and components, Industrial electrical- electronic and High-power conditioning, and Aerospace industry. The Candidate will have exposure on Electrical and Electronic, Power circuits, PCB Technology, Microcontrollers, PLC, Pneumatics, Robotics and IOT and Industry 4.0.

The subjects covered in this programme are – 
Mechanical and Electrical Drives, Safety Health and Environment, Introduction to Robotics, Connector Manufacturing, PCB Technology, Starter Motor Technology, Testing of wire harness, UPS Technology, Assembly Techniques, Advanced Wire Harness Manufacturing, Introduction to IoT and Industry 4.0, Production Management, Industrial Management, Electrical Equipment Maintenance, Professional Ethics, Connector Assembly, Automation in Manufacturing, Employability Skills, Robotics Lab, Wire harness testing lab, IoT Lab, Project/Case Study, OJT', 1200, 1200, '1001–1200', 'Version', '30 Nov 2023', '30 Nov 2026', 'Nettur Technical Training Foundation (NTTF)', 'NETTUR TECHNICAL TRAINING FOUNDATION 23/24, II PHASE, PEENYA INDUSTRIAL AREA, BENGALURU – 560058, KARNATAKA', 'Manufacturing & Assembly', 'Vertical Progression: Engineer - Supervisor – Manager - General Manager - Entrepreneur', 'General Qualification', 'N.A.', '{"Theory":"420","Practical":"105","EmployabilitySkills":"60","OJT_Mandatory":"615"}', false, '{}'::text[], '{"source_row": "149", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-3.5-EH-01404-2023-V1-NTTF', 'Assistant Technician - Electrical', 'electronics-hw', 'Electronics & HW', 3.5, 'Perform different types of Electrical wirings for different applications. Perform simple machining operations. 
Job Holder can Rig up Single Phase AC Circuit wiring for lights and other appliances. Soldering of thimbles to stranded wires and Crimping of Thimbles.

The subjects covered in this Programme are – 
English, Mathematics, Applied science, Electronics, Electrical Engineering, Analog Electronics, Electrical Circuit Analysis, Electrical Material Science, Employability Skill, Applied Science Lab, Electronics Lab, Electrical Engineering Lab, Engineering Drawing/ Fusion 360, Workshop, Basics of Computer Lab, Analog Electronics Lab
Electrical Circuit Analysis Lab, Electrical CAD Lab, Electrical Wiring Lab, OJT', 1200, 1200, '1001–1200', 'Version', '30 Nov 2023', '30 Nov 2026', 'Nettur Technical Training Foundation (NTTF)', 'NETTUR TECHNICAL TRAINING FOUNDATION 23/24, II PHASE, PEENYA INDUSTRIAL AREA, BENGALURU – 560058, KARNATAKA', 'Wiring', 'Vertical Progression: Technician - Senior Technician - Engineer - Supervisor – Manager', 'General Qualification', 'N.A.', '{"Theory":"480","Practical":"570","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "150", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-EH-01405-2023-V1-NTTF', 'Technician-Industrial Electrical', 'electronics-hw', 'Electronics & HW', 4.0, 'Able to use the Sensors, Transducers, and their conditioning circuits. 
Can perform the control of different motors for suitable applications. 
Analyse and troubleshoot different control system components in process industry.
Installing, repairing, and maintaining electrical components of industrial equipment.
The subjects covered in this Programme are – 
Electrical and Electronics Measurement, Digital Electronics, Electrical Machines-I
Solar Technology, Computer Programming C, C++, Control System, Electrical Machines-II, Power Systems Engineering-I, Microcontroller and Applications, Wind Energy, Employability Skill, Programmable Logic Controller, Electrical Machines - I Lab, Computer Programming C, C++ Lab, Electrical and Electronics Measurement Lab, Digital Electronics Lab, Solar Technology Lab, Electrical machines-II Lab, Microcontroller and Applications Lab, Electrical Machine Wiring Lab, Wind Energy Lab, Programmable Logic Controller Lab, OJT', 1200, 1200, '1001–1200', 'Version', '30 Nov 2023', '30 Nov 2026', 'Nettur Technical Training Foundation (NTTF)', 'NETTUR TECHNICAL TRAINING FOUNDATION 23/24, II PHASE, PEENYA INDUSTRIAL AREA, BENGALURU – 560058, KARNATAKA', 'Installation & Repair', 'Vertical Progression:  Senior Technician - Engineer - Supervisor - Manager', 'General Qualification', 'N.A.', '{"Theory":"540","Practical":"510","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "151", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-4.5-EH-01406-2023-V1-NTTF', 'Senior Technician-Electrical and Electronics', 'electronics-hw', 'Electronics & HW', 4.5, 'The Course mainly focus on Power system which includes Generation, Transmission and Distribution, the Course also covers AC and DC machines, Switch Gears, Industrial Electrical Systems, Industrial Drives, Industrial electronics and PLC, Electronics and Automation Engineering. Trainees are being equipped with recent technology developments in Industries related to Power sector and Automation.
 
The subjects covered in this Programme are – 
Switch Gear and Protection, Power Engineering-II, Power Electronics-I, Embedded System, Applied Control System, Artificial Intelligence and Machine Learning, Power Electronics-II, Industrial Management, Industrial drives and Traction system, Estimation, Costing and Utilization of Energy, Employability Skill, Power Electronics-I Lab, Embedded System Lab, IoT Lab, Applied Control System Lab, Artificial Intelligence and Machine Learning Lab, Industrial Drives Lab, Project, OJT', 1350, 1350, '1201–2400', 'Version', '30 Nov 2023', '30 Nov 2026', 'Nettur Technical Training Foundation (NTTF)', 'NETTUR TECHNICAL TRAINING FOUNDATION 23/24, II PHASE, PEENYA INDUSTRIAL AREA, BENGALURU – 560058, KARNATAKA', 'Installation and Maintenance', 'Vertical Progression: Engineer - Supervisor - Manager - General Manager - Entrepreneur', 'General Qualification', 'N.A.', '{"Theory":"450","Practical":"540","EmployabilitySkills":"60","OJT_Mandatory":"300"}', false, '{}'::text[], '{"source_row": "152", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-4.5-EH-03602-2025-V1-ESSCI', 'AI Embedded Product Developer (Electronics) (SIC - Artificial Intelligence)', 'electronics-hw', 'Electronics & HW', 4.5, 'The "SIC - Artificial Intelligence" Qualification will provide a comprehensive introduction to Python 
programming and essential libraries like NumPy and Pandas for data analysis. It will also cover 
data visualization using Matplotlib. The course emphasizes practical programming skills, offering 
hands-on experience to aspiring Python developers. Additionally, it introduces key Machine 
Learning concepts, allowing participants from any background to acquire the skills necessary to 
become an AI Engineer.', 350, 350, '201–400', 'Version', '18 Feb 2025', '18 Feb 2028', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'Product Design', 'Embedded Full Stack IoT Analyst (ELE/Q1404) L-5', 'Future Skills Qualification,OEM Qualification', 'N.A.', '{"Theory":"270","Practical":"80","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "153", "qualification_type": "Future Skills Qualification,OEM Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-04-EH-03726-2025-V1-NIELIT', 'Essentials of Semiconductor Fabrication Technology', 'electronics-hw', 'Electronics & HW', 4.0, 'Implementing the NOS will significantly benefit the semiconductor industry by standardizing skills and knowledge, leading to higher quality and consistency. By aligning training with industry needs, it will enhance employability for individuals seeking careers in this field. Moreover, a skilled and competent workforce fostered by the NOS will contribute to increased productivity and efficiency, ultimately driving innovation and supporting the growth of the semiconductor industry.', 120, 120, '1–200', 'Version', '18 Feb 2025', '18 Feb 2028', 'National Institute of Electronics and Information Technology (NIELIT)', 'National Institute of Electronics and Information Technology (NIELIT)', 'Semiconductor Fabrication Technician', 'MEMS Backend Fabrication Engineer -> Semiconductor Fabrication Engineer', 'Future Skills Qualification', 'N.A.', '{"Theory":"26","Practical":"94","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "154", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-04-EH-03727-2025-V1-NIELIT', 'Fundamentals of Process Technology and Integration in Semiconductor Fabrication', 'electronics-hw', 'Electronics & HW', 4.0, 'The Fundamentals of Process Technology and Integration in Semiconductor Fabrication course will provide significant advantages to the semiconductor industry by ensuring standardized skills and knowledge among the workforce. This alignment with industry requirements ensures the development of expertise in key fabrication processes such as deposition, lithography, etching, doping, and process integration. By equipping professionals with a comprehensive understanding of emerging trends, quality control, and yield management techniques, the course enhances employability and fosters a highly skilled workforce capable of addressing complex fabrication challenges. Through hands-on practical training and exposure to advanced technologies like MEMS and 3D ICs, participants will be prepared to meet industry demands, driving productivity, innovation, and operational efficiency. This initiative supports the semiconductor industry''s growth, technological advancements, and global competitiveness.', 60, 60, '1–200', 'Version', '18 Feb 2025', '18 Feb 2028', 'National Institute of Electronics and Information Technology (NIELIT)', 'National Institute of Electronics and Information Technology (NIELIT)', 'Semiconductor Fabrication Technician', 'MEMS Backend Fabrication Engineer -> Semiconductor Fabrication Engineer', 'Future Skills Qualification', 'N.A.', '{"Theory":"18","Practical":"42","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "155", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-4.5-EH-03728-2025-V1-NIELIT', 'Fundamentals of Cleanroom Operations and Safety', 'electronics-hw', 'Electronics & HW', 4.5, 'This qualification focuses on equipping individuals with the essential knowledge and skills required to operate in and maintain cleanroom environments effectively. Participants will gain foundational knowledge of cleanroom designs, contamination control, safety standards, and best practices. They will also learn how to handle hazardous materials, perform environmental monitoring, and adhere to cleanroom certification standards, making them suitable for roles in manufacturing, pharmaceuticals, and other industries relying on cleanroom technology.', 30, 30, '1–200', 'Version', '18 Feb 2025', '18 Feb 2028', 'National Institute of Electronics and Information Technology (NIELIT)', 'National Institute of Electronics and Information Technology (NIELIT)', 'Semiconductor Fabrication Technician', 'MEMS Backend Fabrication Engineer -> Semiconductor Fabrication Engineer', 'Future Skills Qualification', 'N.A.', '{"Theory":"12","Practical":"18","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "156", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-4.5-EH-03736-2025-V1-NIELIT', 'Essentials of Supply Chain and Materials Management for Semiconductor Fab', 'electronics-hw', 'Electronics & HW', 4.5, 'This Standalone NOS provides understanding of supply chain and materials management specific to the semiconductor fabrication industry. It covers the end-to-end process of managing materials, inventory, and supply chain operations within a semiconductor fab, ensuring efficiency, cost-effectiveness, and high product quality.', 60, 60, '1–200', 'Version', '18 Feb 2025', '18 Feb 2028', 'National Institute of Electronics and Information Technology (NIELIT)', 'National Institute of Electronics and Information Technology (NIELIT)', 'Semiconductor Fabrication Technician', 'MEMS Backend Fabrication Engineer   -> Semiconductor Fabrication Engineer', 'Future Skills Qualification', 'N.A.', '{"Theory":"18","Practical":"42","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "157", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-4.5-EH-03737-2025-V1-NIELIT', 'Essentials of Automation and Process Control in Semiconductor Manufacturing', 'electronics-hw', 'Electronics & HW', 4.5, 'This NOS provides a foundational understanding of automation and process control in semiconductor manufacturing environments. It explores how automated systems are used to ensure precision, consistency, and efficiency in highly complex and cleanroom-based production processes. The course covers key components such as sensors, actuators, PLCs (Programmable Logic Controllers), SCADA systems, and real-time monitoring tools. Emphasis is placed on process stability, control loops (PID), defect reduction, and integration with Manufacturing Execution Systems (MES) and Enterprise Resource Planning (ERP) platforms. Students will also learn how automation contributes to yield improvement, data collection, and compliance with industry standards in a rapidly evolving, high-tech manufacturing landscape.', 90, 90, '1–200', 'Version', '18 Feb 2025', '18 Feb 2028', 'National Institute of Electronics and Information Technology (NIELIT)', 'National Institute of Electronics and Information Technology (NIELIT)', 'Semiconductor Fabrication Technician', 'MEMS Backend Fabrication Engineer -> Semiconductor Fabrication Engineer', 'Future Skills Qualification', 'N.A.', '{"Theory":"27","Practical":"63","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "158", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-4.5-EH-03738-2025-V1-NIELIT', 'Essentials of Semiconductor Production and Quality', 'electronics-hw', 'Electronics & HW', 4.5, 'This standalone NOS is designed to provide students with a solid foundation in semiconductor manufacturing processes and quality management techniques. It covers the key stages of production, including wafer fabrication, assembly, testing, and defect analysis, emphasizing both theoretical understanding and practical skills. Students will gain hands-on experience through lab sessions and project work, enabling them to apply quality assurance methods, optimize production processes, and troubleshoot production issues effectively. This course also introduces advanced trends in semiconductor production and quality standards, preparing students to excel in modern manufacturing environments.', 60, 60, '1–200', 'Version', '18 Feb 2025', '18 Feb 2028', 'National Institute of Electronics and Information Technology (NIELIT)', 'National Institute of Electronics and Information Technology (NIELIT)', 'Semiconductor Fabrication Technician', 'MEMS Backend Fabrication Engineer -> Semiconductor Fabrication Engineer', 'Future Skills Qualification', 'N.A.', '{"Theory":"18","Practical":"42","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "159", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-4.5-EH-03732-2025-V1-NIELIT', 'Essentials of Device Characterization and Testing', 'electronics-hw', 'Electronics & HW', 4.5, 'The Standalone NOS "Essentials of Device Characterization and Testing" focuses on understanding the fundamental techniques used to evaluate and measure the electrical properties of semiconductor devices such as diodes, transistors, and integrated circuits. This includes analyzing parameters like current-voltage (I-V) characteristics, capacitance, mobility, threshold voltage, and response time under various conditions. The goal is to ensure device performance, reliability, and functionality in real-world applications. Accurate characterization and testing are essential in research, quality control, and manufacturing to meet industry standards and design specifications.', 60, 60, '1–200', 'Version', '18 Feb 2025', '18 Feb 2028', 'National Institute of Electronics and Information Technology (NIELIT)', 'National Institute of Electronics and Information Technology (NIELIT)', 'Semiconductor Fabrication Technician', 'MEMS Backend Fabrication Engineer -> Semiconductor Fabrication Engineer', 'Future Skills Qualification', 'N.A.', '{"Theory":"30","Practical":"30","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "160", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-4.5-EH-03729-2025-V1-NIELIT', 'Fundamentals of Photolithography and Mask Making', 'electronics-hw', 'Electronics & HW', 4.5, 'The Standalone NOS "Fundamentals of Photolithography and Mask Making" is designed to provide foundational knowledge and practical skills required for photolithography processes and mask-making in semiconductor manufacturing. Participants will learn the principles of light exposure, photoresist application, and pattern transfer onto substrates. They will develop hands-on expertise in mask design, alignment, etching, and defect inspection. It equips learners to work in cleanroom environments, ensuring compliance with industry standards and safety protocols. It prepares individuals for roles in photolithography operations within the electronics and semiconductor industries, supporting advanced manufacturing processes.', 120, 120, '1–200', 'Version', '18 Feb 2025', '18 Feb 2028', 'National Institute of Electronics and Information Technology (NIELIT)', 'National Institute of Electronics and Information Technology (NIELIT)', 'Semiconductor Fabrication Technician', 'MEMS Backend Fabrication Engineer -> Semiconductor Fabrication Engineer', 'Future Skills Qualification', 'N.A.', '{"Theory":"30","Practical":"90","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "161", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-4.5-EH-03730-2025-V1-NIELIT', 'Fundamentals of Etching Techniques', 'electronics-hw', 'Electronics & HW', 4.5, 'This Standalone NOS provides foundational knowledge and practical skills in semiconductor manufacturing. It covers key processes like oxidation, etching (isotropic, anisotropic, and plasma-based), and advanced techniques such as ion-enhanced and high-density plasma etching. Participants will gain hands-on experience in process characterization, optimization, and integration, culminating in a final project. This course is ideal for those seeking expertise in microfabrication processes.', 30, 30, '1–200', 'Version', '18 Feb 2025', '18 Feb 2028', 'National Institute of Electronics and Information Technology (NIELIT)', 'National Institute of Electronics and Information Technology (NIELIT)', 'Semiconductor Fabrication Technician', 'MEMS Backend Fabrication Engineer   -> Semiconductor Fabrication Engineer', 'Future Skills Qualification', 'N.A.', '{"Theory":"12","Practical":"18","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "162", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-4.5-EH-03731-2025-V1-NIELIT', 'Fundamentals of Thin Film Technology', 'electronics-hw', 'Electronics & HW', 4.5, 'This Standalone NOS provides foundational knowledge and practical skills in semiconductor manufacturing.  The course provides a comprehensive introduction to thin film deposition techniques, including Physical Vapor Deposition (PVD), Chemical Vapor Deposition (CVD), and Atomic Layer Deposition (ALD), covering thin film growth, characterization methods, and real-world applications. Students will gain proficiency in deposition equipment, characterization tools, and process integration, preparing them for roles in electronics, optics, and semiconductor industries.', 30, 30, '1–200', 'Version', '18 Feb 2025', '18 Feb 2028', 'National Institute of Electronics and Information Technology (NIELIT)', 'National Institute of Electronics and Information Technology (NIELIT)', 'Semiconductor Fabrication Technician', 'MEMS Backend Fabrication Engineer   -> Semiconductor Fabrication Engineer', 'Future Skills Qualification', 'N.A.', '{"Theory":"12","Practical":"18","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "163", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-4.5-EH-03734-2025-V1-NIELIT', 'Fundamentals of Design for Manufacturability (DFM)', 'electronics-hw', 'Electronics & HW', 4.5, 'This Standalone NOS provides a comprehensive overview of Design for Manufacturability (DFM). It covers DFM for semiconductor manufacturing and Material Selection and Process Compatibility. It also explores Design for Assembly (DFA) and Tolerance Design and Statistical Process Control (SPC). The course also addresses DFM Implementation and Case Studies including DFM Implementation in Semiconductor and Electronics Industries.', 30, 30, '1–200', 'Version', '18 Feb 2025', '18 Feb 2028', 'National Institute of Electronics and Information Technology (NIELIT)', 'National Institute of Electronics and Information Technology (NIELIT)', 'Semiconductor Fabrication Technician', 'MEMS Backend Fabrication Engineer   -> Semiconductor Fabrication Engineer', 'Future Skills Qualification', 'N.A.', '{"Theory":"12","Practical":"18","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "164", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-4.5-EH-03733-2025-V1-NIELIT', 'Essentials of Process Equipment Maintenance and Troubleshooting', 'electronics-hw', 'Electronics & HW', 4.5, 'This Standalone NOS provides foundational knowledge and practical skills in semiconductor manufacturing. It is a 90-hours program designed to build expertise in maintaining and troubleshooting semiconductor process equipment. The course covers preventive and corrective maintenance, troubleshooting methodologies, cleaning, calibration, equipment upgrades, and safety compliance. Practical sessions provide hands-on experience, preparing learners for roles in equipment maintenance and process optimization in semiconductor manufacturing.', 90, 90, '1–200', 'Version', '18 Feb 2025', '18 Feb 2028', 'National Institute of Electronics and Information Technology (NIELIT)', 'National Institute of Electronics and Information Technology (NIELIT)', 'Semiconductor Fabrication Technician', 'MEMS Backend Fabrication Engineer -> Semiconductor Fabrication Engineer', 'Future Skills Qualification', 'N.A.', '{"Theory":"27","Practical":"63","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "165", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-4.5-EH-03739-2025-V1-NIELIT', 'Essentials of New Product Introduction (NPI) in Semiconductor Manufacturing', 'electronics-hw', 'Electronics & HW', 4.5, 'This course provides a comprehensive understanding of the New Product Introduction (NPI) process in semiconductor fabrication. It covers the key stages of NPI, including design, development, validation, and production. The course emphasizes practical skills for managing the NPI process effectively.', 60, 60, '1–200', 'Version', '18 Feb 2025', '18 Feb 2028', 'National Institute of Electronics and Information Technology (NIELIT)', 'National Institute of Electronics and Information Technology (NIELIT)', 'Semiconductor Fabrication Technician', 'MEMS Backend Fabrication Engineer-> Semiconductor Fabrication Engineer', 'Future Skills Qualification', 'N.A.', '{"Theory":"18","Practical":"42","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "166", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-4.5-EH-03735-2025-V1-NIELIT', 'Essentials of Semiconductors Assembly Test Marking and Packaging', 'electronics-hw', 'Electronics & HW', 4.5, 'This Standalone NOS provides an in-depth understanding of the fundamental concepts and practices involved in semiconductor assembly, test, marking, and packaging (ATMP), with a special emphasis on defect analysis and quality control. The course also addresses the entire process flow from fabricated wafer to final packaging, with a focus on the tools, techniques, and quality control measures critical to producing reliable semiconductor devices.', 180, 180, '1–200', 'Version', '18 Feb 2025', '18 Feb 2028', 'National Institute of Electronics and Information Technology (NIELIT)', 'National Institute of Electronics and Information Technology (NIELIT)', 'Semiconductor Fabrication Technician', 'MEMS Backend Fabrication Engineer   -> Semiconductor Fabrication Engineer', 'Future Skills Qualification', 'N.A.', '{"Theory":"36","Practical":"84","EmployabilitySkills":"0","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "167", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-EH-03967-2025-V4-ESSCI', 'CCTV Installation Technician', 'electronics-hw', 'Electronics & HW', 4.0, 'The individual at work is responsible for installing the CCTV system in the customer premises. The 
individual understands the customer and site requirement, installs the camera and integrates the 
hardware for effective CCTV surveillance system functioning.', 480, 480, '401–600', 'Version', '07 May 2025', '30 Apr 2028', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'After Sales Service', 'Service Engineer – CCTV Installation', 'General Qualification', 'N.A.', '{"Theory":"120","Practical":"180","EmployabilitySkills":"30","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "168", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-EH-02821-2025-V4-ESSC', 'Solar LED Technician', 'electronics-hw', 'Electronics & HW', 4.0, 'The individual is capable of installing various types of solar home-based LED lighting, outdoor and street lighting as per given instructions. The person should be able to identify faults in a solar PV system and carry out repair at a preliminary level in line with given performance parameters. The individual must adhere to all the relevant environmental, safety and regulatory requirements while carrying out his/her job duties.', 450, 450, '401–600', 'Version', '08 May 2025', '08 May 2028', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'Installation-S&L', 'Solar LED Project Supervisor', 'General Qualification', 'N.A.', '{"Theory":"120","Practical":"180","EmployabilitySkills":"30","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "169", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-EH-03991-2025-V3-ESSCI', 'IC Package Engineer', 'electronics-hw', 'Electronics & HW', 5.0, 'An IC Package Engineer is responsible to design complete packages & check Package feasibility & Characterization and validate, He works in coordination with Production as well as Research and Development (R&D) for sample building & Approvals on both types of Electronics as well as Mechanical. He is also responsible for development of New Products & Launching for the same to mass production.', 570, 570, '401–600', 'Version', '07 May 2025', '31 Oct 2025', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'Production-S&C', 'Assistant Manager - IC Package', 'Future Skills Qualification,General Qualification', 'N.A.', '{"Theory":"150","Practical":"180","EmployabilitySkills":"60","OJT_Mandatory":"180"}', false, '{}'::text[], '{"source_row": "170", "qualification_type": "Future Skills Qualification,General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-EH-04208-2025-V4-ESSC', 'Winding Machine Operator (Electronics Component)', 'electronics-hw', 'Electronics & HW', 4.0, 'The Winding Machine Operator (Electronics Component) winds the metal-alloy wire or metalized film onto a core by using an automated or semi-automated winding machine in the process of manufacturing of capacitors and resistors. The individual sample also checks the resistance or capacitance of the winding', 480, 480, '401–600', 'Version', '08 May 2025', '08 May 2028', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council Of India (ESSCI)', 'Production-S&C', 'Die Attach and Wire Bonding Supervisor', 'General Qualification', 'N.A.', '{"Theory":"150","Practical":"180","EmployabilitySkills":"30","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "171", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
