INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-EH-03980-2025-V4-ESSCI', 'Electronic Hardware Design Engineer', 'electronics-hw', 'Electronics & HW', 5.0, 'The individual at work is responsible for undertaking research on new products, working with R&D on developing the schematics, converting them to PCB layout using CAD and other software and generating the Gerber file to pass on to PCB manufacturers.', 570, 570, '401–600', 'Version', '07 May 2025', '30 Apr 2028', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'Research and Design-PCB', 'Electronic Hardware Design - Lead', 'Future Skills Qualification', 'N.A.', '{"Theory":"150","Practical":"180","EmployabilitySkills":"60","OJT_Mandatory":"180"}', false, '{}'::text[], '{"source_row": "187", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-EH-03985-2025-V3-ESSCI', 'Solder Ball Attach - Process Supervisor', 'electronics-hw', 'Electronics & HW', 5.0, 'Solder Ball Attach - Process Supervisor works on Program Preparation for Solder Ball Attach Machine and also, he is responsible for Operation of Machine to complete process and deliver to the next step of Manufacturing. He also needs to coordinate with other departments for smooth functioning.', 570, 570, '401–600', 'Version', '07 May 2025', '31 Oct 2025', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'Production-S&C', 'Assistant Manager - Process', 'Future Skills Qualification,General Qualification', 'N.A.', '{"Theory":"150","Practical":"180","EmployabilitySkills":"60","OJT_Mandatory":"180"}', false, '{}'::text[], '{"source_row": "188", "qualification_type": "Future Skills Qualification,General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-EH-03993-2025-V3-ESSCI', 'Saw Singulation Engineer (Semiconductor)', 'electronics-hw', 'Electronics & HW', 5.0, 'Saw Singulation Engineer (Semiconductor) works on Saw Singulation Process & is responsible for preparing recipe (Process Parameters), Data Analysis, Yield Maintenance & Improvements, Productivity Improvements etc all. He needs to know the complete process of Saw Singulation during IC Packaging to handle the process. Create process for new products.', 570, 570, '401–600', 'Version', '07 May 2025', '31 Oct 2025', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'Production-S&C', 'Assistant Manager - Process', 'Future Skills Qualification,General Qualification', 'N.A.', '{"Theory":"150","Practical":"180","EmployabilitySkills":"60","OJT_Mandatory":"180"}', false, '{}'::text[], '{"source_row": "189", "qualification_type": "Future Skills Qualification,General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-EH-03990-2025-V3-ESSCI', 'Risk and Failure Analysis Engineer (Semiconductor)', 'electronics-hw', 'Electronics & HW', 5.0, 'A Risk and Failure Analysis Engineer (Semiconductor) is responsible to prepare failure analysis flow & to rectify the failures. The individual is also responsible for verification and resolution by working together with several cross-functional teams for reliability flow, test requirements as per JEDEC standards.', 570, 570, '401–600', 'Version', '07 May 2025', '31 Oct 2025', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'Production-S&C', 'Assistant Manager - Quality', 'Future Skills Qualification,General Qualification', 'N.A.', '{"Theory":"150","Practical":"180","EmployabilitySkills":"60","OJT_Mandatory":"180"}', false, '{}'::text[], '{"source_row": "190", "qualification_type": "Future Skills Qualification,General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-5.5-EH-04147-2025-V1-IITG', 'RTL and FPGA based System Designer', 'electronics-hw', 'Electronics & HW', 5.5, 'This course is aimed at providing the front-end knowledge of VLSI systems design including FPGA implementation of learner’s design. RTL design and FPGAs can contribute to environmental sustainability in various ways, primarily through their impact on power efficiency, resource utilization, and flexibility.', 600, 600, '401–600', 'Version', '08 May 2025', '08 May 2028', 'Indian Institute of Technology Guwahati', 'IIT Guwahati, Amingaon, North Guwahati, Guwahati, Assam 781039', 'VLSI Physical Design', 'RTL Design Engineer, FPGA Engineer', 'Future Skills Qualification', 'N.A.', '{"Theory":"185","Practical":"265","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "191", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-EH-03972-2025-V4-ESSCI', 'Embedded Software Engineer', 'electronics-hw', 'Electronics & HW', 5.0, 'An Embedded Software Engineer is responsible for assessing the embedded systems specification 
requirement, develops software, tests and validates the software in coordination with design engineers 
for system integration.', 570, 570, '401–600', 'Version', '07 May 2025', '30 Apr 2028', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'System Software Development-S&C', 'Embedded Product Design Engineer –Technical Lead', 'Future Skills Qualification,General Qualification', 'N.A.', '{"Theory":"150","Practical":"180","EmployabilitySkills":"60","OJT_Mandatory":"180"}', false, '{}'::text[], '{"source_row": "192", "qualification_type": "Future Skills Qualification,General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-EH-03989-2025-V3-ESSCI', 'Quality Analysis & Reliability Supervisor (Semiconductor)', 'electronics-hw', 'Electronics & HW', 5.0, 'A quality analysis and Reliability Supervisor (Semiconductor) works is responsible to prepare Quality analysis flow & to rectify the failures. He/she is also responsible for verification and resolve by working together with several cross functional teams and test requirements as per Joint Electron Device Engineering Council (JEDEC) standards.', 570, 570, '401–600', 'Version', '07 May 2025', '31 Oct 2025', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'Quality Assurance', 'Assistant Manager – Quality', 'Future Skills Qualification,General Qualification', 'N.A.', '{"Theory":"150","Practical":"180","EmployabilitySkills":"60","OJT_Mandatory":"180"}', false, '{}'::text[], '{"source_row": "193", "qualification_type": "Future Skills Qualification,General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-EH-03992-2025-V3-ESSCI', 'Package Design Engineer (Semiconductor)', 'electronics-hw', 'Electronics & HW', 5.0, 'Package Design Engineer (Semiconductor) works on Designing software & responsible for designing & defining layouts for different types of IC Packages. He is also responsible for Test Program preparation for all types of IC Packages available with the product or Research & Development Team. He also assists in the design verifications.', 570, 570, '401–600', 'Version', '07 May 2025', '31 Oct 2025', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'Product Design-S&C', 'Assistant Manager – IC Package', 'Future Skills Qualification,General Qualification', 'N.A.', '{"Theory":"150","Practical":"180","EmployabilitySkills":"60","OJT_Mandatory":"180"}', false, '{}'::text[], '{"source_row": "194", "qualification_type": "Future Skills Qualification,General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-EH-03988-2025-V3-ESSCI', 'Molding Process Engineer (Semiconductor)', 'electronics-hw', 'Electronics & HW', 5.0, 'Molding Process Engineer (Semiconductor) is responsible to work on failure analysis flow & to rectify the failures. He/ she is also responsible for verification and resolve by working together with several cross functional teams. Similarly, he is responsible for reliability flow, Test requirements as per JEDEC standards.', 570, 570, '401–600', 'Version', '07 May 2025', '31 Oct 2025', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'Production-S&C', 'Assistant Manager - Process', 'Future Skills Qualification,General Qualification', 'N.A.', '{"Theory":"150","Practical":"180","EmployabilitySkills":"60","OJT_Mandatory":"180"}', false, '{}'::text[], '{"source_row": "195", "qualification_type": "Future Skills Qualification,General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-06-EH-03968-2025-V3-ESSCI', 'Mechanical Engineering and Plumbing General Manager (Electronics)', 'electronics-hw', 'Electronics & HW', 6.0, 'A Mechanical Engineering and Plumbing General Manager (Electronics) is responsible for planning, managing, monitoring and execution of Mechanical Engineering and Plumbing (MEP) projects at the client premises. The individual is also responsible for preparing the tender proposal and making presentations to secure MEP contracts, identifying the training needs of company personnel and arranging training, recruitments, risk assessment, Profit & Loss (P&L) management, etc.', 660, 660, '601–800', 'Version', '07 May 2025', '30 Apr 2028', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'Engineering-I&A', 'Product Development Head', 'General Qualification', 'N.A.', '{"Theory":"180","Practical":"210","EmployabilitySkills":"60","OJT_Mandatory":"210"}', false, '{}'::text[], '{"source_row": "196", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-EH-03987-2025-V3-ESSCI', 'Laser Marking and Cutting - Process Supervisor', 'electronics-hw', 'Electronics & HW', 5.0, 'A laser marking & cutting process Supervisor is responsible for proper functioning, troubleshooting and maintenance of laser marking & cutting machines, setting up process parameters, new recipes to be incorporated, material characterization and yield monitoring/analysis, etc. for equipment, tools and fixtures. He/she also assists the equipment engineer for any help needed with the laser marking and cutting machines operations.', 570, 570, '401–600', 'Version', '07 May 2025', '30 Apr 2028', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'Production - S&C', 'Assistant Manager - Process', 'Future Skills Qualification,General Qualification', 'N.A.', '{"Theory":"150","Practical":"180","EmployabilitySkills":"60","OJT_Mandatory":"180"}', false, '{}'::text[], '{"source_row": "197", "qualification_type": "Future Skills Qualification,General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-EH-03971-2025-V4-ESSCI', 'IoT Hardware Analyst', 'electronics-hw', 'Electronics & HW', 5.0, 'The individual in this job role prepares a complete blueprint of the hardware including schematics layout, quality verification requirements and performs PCB testing in compliance with regulatory standards to record them in a design document. The individual will also be responsible for working and efficient functioning of the system.', 450, 450, '401–600', 'Version', '07 May 2025', '30 Apr 2028', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'Product Design-S&C', 'Lead – IoT Hardware', 'Future Skills Qualification,General Qualification', 'N.A.', '{"Theory":"90","Practical":"150","EmployabilitySkills":"60","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "198", "qualification_type": "Future Skills Qualification,General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-EH-03898-2025-V1-WBSC', 'Assistant Technician of Creative & Dynamic Lighting System', 'electronics-hw', 'Electronics & HW', 3.0, 'Assistant Technician of  Creative & Dynamic Lighting System’ is designed to equip learners with foundational knowledge and practical skills in the setup, programming, and maintenance of creative and dynamic lighting systems used in events, entertainment, architectural installations, and theatrical productions. Participants will gain hands-on experience with lighting control software and hardware, understand DMX and networked lighting protocols, and learn techniques for designing and operating synchronized lighting shows. The qualification prepares individuals for entry-level roles supporting lighting assistant technicians, and production teams in a variety of creative industries.', 540, 540, '401–600', 'Version', '09 May 2025', '08 May 2028', 'West Bengal State Council for Vocational Training (WBSCVT)', 'West Bengal State Council for Vocational Training (WBSCVT)', 'Lighting Technician', 'CREATIVE &  DYNAMIC LIGHTING SYSTEM TECHNICIAN (NSQF Level-4.0)', 'General Qualification', 'N.A.', '{"Theory":"125","Practical":"325","EmployabilitySkills":"30","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "199", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-06-EH-03973-2025-V3-ESSCI', 'Building Management System Project Manager', 'electronics-hw', 'Electronics & HW', 6.0, 'A Building Management System Project Manager is responsible for the successful delivery of Building Management System (BMS) installation projects. The responsibilities include coordinating with the client to understand their requirements and then working with various teams within the organization for the successful installation, testing, commission and handover of BMS to the client.', 660, 660, '601–800', 'Version', '07 May 2025', '30 Apr 2028', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'Engineering-I&A', 'Mechanical Engineering and Plumbing General Manager', 'General Qualification', 'N.A.', '{"Theory":"180","Practical":"210","EmployabilitySkills":"60","OJT_Mandatory":"210"}', false, '{}'::text[], '{"source_row": "200", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-EH-03979-2025-V3-ESSCI', 'Building Management System Service Engineer', 'electronics-hw', 'Electronics & HW', 5.0, 'A Building Management System Service Engineer is responsible for installing the Building Management System (BMS) at the client premises. The person is also responsible for monitoring the BMS for the correct functioning and carrying out its regular repair and maintenance.', 570, 570, '401–600', 'Version', '07 May 2025', '30 Apr 2028', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'After Sales Service', 'Building Management System Project Manager', 'General Qualification', 'N.A.', '{"Theory":"150","Practical":"180","EmployabilitySkills":"60","OJT_Mandatory":"180"}', false, '{}'::text[], '{"source_row": "201", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-04-EH-046502025-V1-SS', 'Entrepreneurship in Drone Assembling', 'electronics-hw', 'Electronics & HW', 4.0, 'The Qualification for Entrepreneurship in Drone Assembling is designed to equip individuals with the skills and knowledge required to establish and manage drone assembling business. This qualification focuses on the technical aspects of drone assembling, including the understanding of drone components, assembly of drones, and conceptual design. It also covers essential business management concepts such as budgeting, marketing, product development, supply chain management, and customer service.', 120, 120, '1–200', 'Version', '07 Oct 2025', '06 Oct 2028', 'Samadhan Samiti', 'Samadhan Samiti, 2nd Floor, Siddhivinayak Building, 27/1/B Samadhan Tower, Gokhale Marg, Lucknow, Uttar Pradesh, Pincode - 226001', 'Entrepreneurship', 'N/A', 'General Qualification', 'N.A.', '{"Theory":"80","Practical":"40","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "202", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-04-EH-04418-2025-V2-NIELIT', 'Fundamentals of Internet of Things', 'electronics-hw', 'Electronics & HW', 4.0, 'This course is designed to enhance skill development in the IoT sector, targeting students and unemployed youth, including Diploma and Engineering graduates, to boost their employability in IoT hardware and software fields. It also aims to upgrade the skills of professionals already working in IoT and related technologies. The purpose is to demystify IoT and empower the future workforce with the confidence to independently learn and apply these skills.', 90, 90, '1–200', 'Version', '08 May 2025', '08 May 2028', 'National Institute of Electronics and Information Technology (NIELIT)', 'National Institute of Electronics and Information Technology (NIELIT)', 'IoT Solution', 'IoT System Design Engineer', 'Future Skills Qualification', 'N.A.', '{"Theory":"35","Practical":"55","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "203", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-EH-044872025-V2-ESSCI', 'Assembly Line Operator (Electronics Modules)', 'electronics-hw', 'Electronics & HW', 3.0, 'The individual at work is responsible for assembling the different modules in the IT hardware to complete the product. The individual receives different electronic and electromechanical modules, fits and assembles them together. The operator may assemble multiple modules and/or products by following operating procedures for different models.', 390, 390, '201–400', 'Version', '07 Oct 2025', '07 Oct 2028', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'Assembly-EMS', 'Sr. Operator Assembly Line', 'General Qualification', 'N.A.', '{"Theory":"60","Practical":"210","EmployabilitySkills":"30","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "204", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-EH-044862025-V2-ESSCI', 'Customer Service Executive - Electronic Products', 'electronics-hw', 'Electronics & HW', 4.0, 'The individual in this job is responsible for receiving, understanding and responding to customer queries through telephone or e-mail. The individual records the complaints for follow up, coordinates with other departments to resolve technical problems and closes non-technical issues raised by customers on the call itself.', 510, 510, '401–600', 'Version', '07 Oct 2025', '07 Oct 2028', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'After Sales Support', 'Executive Customer Care', 'General Qualification,Multi-Skill Qualification', 'N.A.', '{"Theory":"150","Practical":"210","EmployabilitySkills":"30","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "205", "qualification_type": "General Qualification,Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-EH-044902025-V2-ESSCI', 'DTH Set Top Box Installation & Service Technician', 'electronics-hw', 'Electronics & HW', 4.0, 'A DTH Set-Top Box Installation & Service Technician is responsible for installing set-top boxes at customer locations, using tools such as CRM applications, GPS, and mobile service platforms to plan installations, align antennas, configure signal frequencies, and provide real-time service updates. The technician ensures accurate installation, prompt issue resolution, and tech-enabled customer support through digital feedback systems and coordination with the backend technical team.', 480, 480, '401–600', 'Version', '07 Oct 2025', '07 Oct 2028', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'After Sales Service', 'DTH/DAS Set Top Box Service Supervisor', 'General Qualification', 'N.A.', '{"Theory":"150","Practical":"180","EmployabilitySkills":"30","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "206", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-EH-044852025-V2-ESSCI', 'Assistant Technician – Computer and Peripheral', 'electronics-hw', 'Electronics & HW', 3.0, 'The individual is responsible for installing newly purchased products, troubleshooting system problems and, configuring peripherals such as printers, scanners and network devices.', 450, 450, '401–600', 'Version', '07 Oct 2025', '07 Oct 2028', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'Assembly -  EMS', 'Field Technician – Computing & Peripherals', 'General Qualification', 'N.A.', '{"Theory":"120","Practical":"180","EmployabilitySkills":"30","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "207", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-EH-044892025-V2-ESSCI', 'Assembly Operator - TV', 'electronics-hw', 'Electronics & HW', 4.0, 'The individual at work is responsible for assembling various modules of modern televisions—including LED, QLED, and Smart TVs—into the main frame using appropriate screws, connectors, and tools at different stages of the assembly line. The individual must ensure precision and minimal errors, as the assembly process operates in a continuous flow.', 450, 450, '401–600', 'Version', '07 Oct 2025', '07 Oct 2028', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'Assembly-EMS', 'Assembly Supervisor', 'General Qualification', 'N.A.', '{"Theory":"120","Practical":"180","EmployabilitySkills":"30","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "208", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-EH-044802025-V2-ESSCI', 'Assistant Technician - TV', 'electronics-hw', 'Electronics & HW', 3.0, 'Assistant Technician- TV– is responsible for interacting with the customer to install the TV as well as diagnose the problem. The individual also needs to assess possible causes of fault reported and rectify problems/faults.', 390, 390, '201–400', 'Version', '07 Oct 2025', '07 Oct 2028', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'After Sales Service', 'Assembly Technician - TV', 'General Qualification', 'N.A.', '{"Theory":"90","Practical":"120","EmployabilitySkills":"30","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "209", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-EH-044912025-V2-ESSCI', 'Assembly and Wiring  Assistant Operator- Standard Control Panel', 'electronics-hw', 'Electronics & HW', 3.0, 'The individual at work mounts and installs and connects internal electronic modules devices and components on the control panel.', 420, 420, '401–600', 'Version', '07 Oct 2025', '07 Oct 2028', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'After Sales Service', 'Operator Electrical Assembly – Control Panel', 'General Qualification', 'N.A.', '{"Theory":"120","Practical":"180","EmployabilitySkills":"30","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "210", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-EH-04471-2025-V2-ESSCI', 'Solar Panel Installation Technician', 'electronics-hw', 'Electronics & HW', 4.0, 'Solar Panel Installation Technician in this job checks the installation site, understands the layout requirement as per design, assesses precautionary measures to be taken, installs the solar panel as per customers requirement and ensures effective functioning of the system post installation.', 480, 480, '401–600', 'Version', '07 Oct 2025', '07 Oct 2028', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'Installation', 'Sr. Technician Installation (Solar Panel)', 'General Qualification', 'N.A.', '{"Theory":"120","Practical":"180","EmployabilitySkills":"30","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "211", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-EH-044762025-V2-ESSCI', 'Smartphone Assembly Technician', 'electronics-hw', 'Electronics & HW', 4.0, 'A Smartphone assembly technician is responsible for interpreting assembly instructions, blueprint specifications, etc. to assemble or fix smartphone parts/components in correct position and alignment using approved techniques and equipment in a production unit.', 450, 450, '401–600', 'Version', '07 Oct 2025', '07 Oct 2028', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'Assembly-C&B', 'Assembly Supervisor', 'General Qualification', 'N.A.', '{"Theory":"150","Practical":"180","EmployabilitySkills":"30","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "212", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-EH-04473-2025-V2-ESSCI', 'LED Light Repair Technician', 'electronics-hw', 'Electronics & HW', 4.0, 'A LED Light Repair Technician is responsible for checking the non- functional LED light in a systematic manner to find out the fault; dismantles it; repairs the fault and reassemble the light to make it functional.', 480, 480, '401–600', 'Version', '07 Oct 2025', '07 Oct 2028', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'LED Light Testing and Quality Assurance', 'Sr. Technician (LED Lights)', 'General Qualification', 'N.A.', '{"Theory":"120","Practical":"180","EmployabilitySkills":"30","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "213", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-EH-044842025-V2-ESSCI', 'Purchase Coordinator- Electronics', 'electronics-hw', 'Electronics & HW', 4.0, 'A Purchase Coordinator-Electronics, the individual purchases quality materials in a timely manner at competitive prices to maintain the optimum inventory level. The individual also collects information about the materials required by different departments and selects the appropriate supplier', 510, 510, '401–600', 'Version', '07 Oct 2025', '07 Oct 2028', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'Purchase and Procurement', 'Store Supervisor', 'General Qualification', 'N.A.', '{"Theory":"150","Practical":"180","EmployabilitySkills":"30","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "214", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
