INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-EH-044942025-V2-ESSCI', 'Electronics Manufacturing Services (EMS) Technician', 'electronics-hw', 'Electronics & HW', 4.0, 'Electronics Manufacturing Services (EMS) Technician in this job job works on SMT machines, circuit boards and soldering equipment. The individual is responsible for the maintenance and troubleshooting of SMT equipment and also assists in the assembly and programming of SMT equipment.', 450, 450, '401–600', 'Version', '07 Oct 2025', '07 Oct 2028', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'Assembly and Soldering', 'EMS Supervisor', 'General Qualification', 'N.A.', '{"Theory":"120","Practical":"180","EmployabilitySkills":"30","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "217", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-EH-044952025-V2-ESSCI', 'Field Technician - Air Conditioner', 'electronics-hw', 'Electronics & HW', 4.0, 'Field Technician – Air Conditioner provides after sales service to customers where he/she needs to interact with customers to diagnose the problem and assess possible causes. The individual identifies and rectifies minor problems or replaces faulty modules for failed parts or recommends factory repair for bigger faults.', 480, 480, '401–600', 'Version', '07 Oct 2025', '07 Oct 2028', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'After Sales Service', 'Sr. Technician- RACW', 'General Qualification', 'N.A.', '{"Theory":"120","Practical":"210","EmployabilitySkills":"30","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "218", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-EH-044982025-V2-ESSCI', 'Field Technician - Kitchen Appliances', 'electronics-hw', 'Electronics & HW', 4.0, 'Field Technician – is responsible for interacting with the customer to install the appliance as well as diagnose the problem. The individual also needs to assess possible causes of fault reported and rectify problems/faults.', 540, 540, '401–600', 'Version', '07 Oct 2025', '07 Oct 2028', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'After Sales Service', 'Sr. Technician- Consumer Durables', 'Multi-Skill Qualification', 'N.A.', '{"Theory":"150","Practical":"210","EmployabilitySkills":"30","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "219", "qualification_type": "Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
