INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-EH-044772025-V2-ESSCI', 'Service Technician – Home Appliances', 'electronics-hw', 'Electronics & HW', 4.0, 'A Service Technician – Home Appliances is responsible to interact with customers to Install the appliance or diagnose the problem to assess possible causes of malfunction. Once the problem and causes have been identified, the individual rectifies the problems or replaces faulty modules/failed parts or recommends factory repairs.', 510, 510, '401–600', 'Version', '07 Oct 2025', '07 Oct 2028', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'After Sales Service', 'Sr. technician (Consumer Goods)', 'Multi-Skill Qualification', 'N.A.', '{"Theory":"120","Practical":"210","EmployabilitySkills":"30","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "227", "qualification_type": "Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-EH-044822025-V2-ESSCI', 'Through Hole Assembly Operator', 'electronics-hw', 'Electronics & HW', 4.0, 'A Through Hole Assembly Operator is responsible for manually/automatic fixing components using hand tools, operating and maintaining the automated insertion machine used for placing different types of components on the through-hole PCBs.', 540, 540, '401–600', 'Version', '07 Oct 2025', '07 Oct 2028', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'Assembly and Soldering', 'EMS Supervisor', 'General Qualification', 'N.A.', '{"Theory":"135","Practical":"180","EmployabilitySkills":"30","OJT_Mandatory":"195"}', false, '{}'::text[], '{"source_row": "228", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-EH-044972025-V2-ESSCI', 'Field Technician - UPS And Inverter', 'electronics-hw', 'Electronics & HW', 4.0, 'The individual at work installs the newly purchased UPS or inverter and interacts with customers to diagnose problems in them, assess possible causes, rectify faults or replace faulty modules or recommends factory repairs for bigger faults.', 450, 450, '401–600', 'Version', '07 Oct 2025', '07 Oct 2028', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'Sales and After Sales Service', 'Sr. Technician- UPS Inverter and Control Panel', 'Multi-Skill Qualification', 'N.A.', '{"Theory":"120","Practical":"180","EmployabilitySkills":"30","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "229", "qualification_type": "Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-EH-044792025-V2-ESSCI', 'Assistant Welding Operator (Electronics)', 'electronics-hw', 'Electronics & HW', 3.0, 'A  Assistant Welding Operator Electronics is responsible for bonding the electro-tinned copper lead wire to the center of steel and cap, of the resistor by welding process.', 420, 420, '401–600', 'Version', '07 Oct 2025', '07 Oct 2028', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'Production- S&C', 'Operator (Wire Bonding)', 'General Qualification', 'N.A.', '{"Theory":"90","Practical":"150","EmployabilitySkills":"30","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "230", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-EH-04474-2025-V2-ESSCI', 'Wireman Control Panel Electronics', 'electronics-hw', 'Electronics & HW', 3.0, 'The individual at work is responsible for wiring all components present within the panel as per specifications provided by the design engineering team.', 420, 420, '401–600', 'Version', '07 Oct 2025', '07 Oct 2028', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'Manufacturing', 'Electrical Assembly Supervisor – Control Panel', 'General Qualification', 'N.A.', '{"Theory":"90","Practical":"150","EmployabilitySkills":"30","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "231", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-4.5-EH-045012025-V1-ESSCI', 'Fundamentals of Cleanroom  - Semiconductor  OEM Qualification Name: Cleanroom Technician - Semiconductor  Manufacturing', 'electronics-hw', 'Electronics & HW', 4.5, 'The “Fundamentals of Cleanroom- Semiconductor” is an upskilling course that equips learners with the overview and knowledge to work effectively in a semiconductor manufacturing cleanroom environment. The curriculum emphasizes overview  understanding cleanroom protocols, monitoring equipment, maintaining cleanliness, and ensuring contamination control to meet industry standards.', 30, 30, '1–200', 'Version', '07 Oct 2025', '07 Oct 2028', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'Production-S&C', 'Cleanroom Operations', 'Future Skills Qualification,OEM Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"12","Practical":"18","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "232", "qualification_type": "Future Skills Qualification,OEM Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-4.5-EH-045002025-V1-ESSCI', 'Basics of Semiconductor Manufacturing Process OEM Qualification  Name:  Semiconductor Manufacturing Technician', 'electronics-hw', 'Electronics & HW', 4.5, 'The “Basics of Semiconductor Manufacturing Process” is an upskilling course that offers foundational skills in semiconductor manufacturing, focusing on equipment such as valves, actuators, chillers, sensors, and environmental control systems critical to the manufacturing process. Learners will gain overview of operation, maintenance, safety protocols, and quality standards, preparing them for technical roles in the semiconductor industry.', 30, 30, '1–200', 'Version', '07 Oct 2025', '07 Oct 2028', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'Production-S&C', 'Industrial Safety for Semiconductor Manufacturing', 'Future Skills Qualification,OEM Qualification', 'N.A.', '{"Theory":"12","Practical":"18","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "233", "qualification_type": "Future Skills Qualification,OEM Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-EH-04690-2025-V2-ESSC', 'Multi Skill Technician – Consumer Durables', 'electronics-hw', 'Electronics & HW', 4.0, 'The individual in this multi-skill consumer durable role is responsible for installing, diagnosing, troubleshooting, and repairing a range of household appliances such as refrigerators, televisions, washing machines, water purifiers, and microwave ovens. They also coordinate with the Service Manager or Lead Mechanic to update on repair status and prioritize service tasks.', 660, 1260, '1201–2400', 'Version', '16 Dec 2025', '18 Nov 2028', 'Electronics Sector Skills Council Of India (ESSCI)', 'Electronics Sector Skills Council of India', 'After Sales Service', 'Senior Technician – Consumer Durables', 'Multi-Skill Qualification,OEM Qualification', 'N.A.', '{"Theory":"300","Practical":"600","EmployabilitySkills":"60","OJT_Mandatory":"300"}', false, '{}'::text[], '{"source_row": "234", "qualification_type": "Multi-Skill Qualification,OEM Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_02_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/POW/SCGJ/06461', 'Junior Technician- Solar EV charging station', 'environmental-science', 'Environmental Science', 3.0, 'Junior Technician- Solar EV charging station performs tasks while ensuring safety, quality and good workmanship for installation, usage along with O&M of solar powered Electric Vehicle (EV) charging station as per standard industry practices. He/She may also conduct site surveys and evaluate various parameters to decide the suitability of site for the installation of solar powered EV charging station. Also, the individual performs the regular maintenance for Solar powered charging station.', 330, 330, '201–400', 'Version', '17 Nov 2022', '16 Nov 2025', 'Skill Council for Green Jobs (SCGJ)', 'Skill Council for Green Jobs', 'Technician', 'Vertical Progression: Solar EV Charging Entrepreneur', 'General Qualification', 'N.A.', '{"Theory":"120","Practical":"120","EmployabilitySkills":"30","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "1", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_05_50.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/ES/SCGJ/06459', 'Junior Technician-Solar Cold Storage', 'environmental-science', 'Environmental Science', 3.0, 'Junior Technician-Solar Cold Storage performs installation along with operations and maintenance (O&M) of a solar cold storage/cold room solution while meeting the performance and reliability needs of customers by incorporating quality craftsmanship and complying with all applicable industry standards, quality and safety requirements.', 330, 330, '201–400', 'Version', '17 Nov 2022', '16 Nov 2025', 'Skill Council for Green Jobs (SCGJ)', 'Skill Council for Green Jobs', 'Technician', '(Vertical) Solar Cold Storage Entrepreneur, Level 4', 'General Qualification', 'N.A.', '{"Theory":"90","Practical":"150","EmployabilitySkills":"30","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "2", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_05_50.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/POW/SCGJ/06463', 'Junior Technician-Rooftop Rainwater Harvesting', 'environmental-science', 'Environmental Science', 3.0, 'The individual at work is responsible for performing site survey, and installation of rainwater harvesting systems across different consumer categories/buildings types. The individual will also be responsible for routine maintenance of rainwater harvesting systems.', 330, 330, '201–400', 'Version', '17 Nov 2022', '16 Nov 2025', 'Skill Council for Green Jobs (SCGJ)', 'Skill Council for Green Jobs', 'Technician', 'Vertical Progression: Rooftop Rainwater Harvesting Entrepreneur (Level 4)
Or
Rainwater Harvesting system Designer (Level 4)
Horizontal Progression: NA', 'General Qualification', 'N.A.', '{"Theory":"105","Practical":"135","EmployabilitySkills":"30","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "3", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_05_50.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/ES/SCGJ/06464', 'Rooftop Rainwater Harvesting Entrepreneur', 'environmental-science', 'Environmental Science', 4.0, 'Rooftop Rainwater Harvesting Entrepreneur shall analyse key parameters for rain water harvesting system, estimate cost parameters and oversee its installation and maintenance.', 420, 420, '401–600', 'Version', '17 Nov 2022', '16 Nov 2025', 'Skill Council for Green Jobs (SCGJ)', 'Skill Council for Green Jobs', 'Entrepreneur', 'Vertical Progression: NA
Horizontal Progression: Rainwater Harvesting System Designer (Level 4)', 'General Qualification', 'N.A.', '{"Theory":"105","Practical":"165","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "4", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_05_50.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/ES/SCGJ/06460', 'Solar Cold Storage Entrepreneur', 'environmental-science', 'Environmental Science', 4.0, 'Solar Cold Storage Entrepreneur sets up an enterprise with an aim to provide a service (to Farmers/FPOs etc) for storing perishable agricultural and horticultural produce for increasing their shelf life and realise better price of the produce. This entrepreneur shall use an innovative solar based cold storage solution that can also be powered through the Grid and has thermal energy storage for providing backup during non-sunny hours.', 390, 390, '201–400', 'Version', '17 Nov 2022', '16 Nov 2025', 'Skill Council for Green Jobs (SCGJ)', 'Skill Council for Green Jobs', 'Entrepreneur', 'Level-5 (Vertical) Solar Cold Storage Dealership/Channel Partner', 'Future Skills Qualification,General Qualification', 'N.A.', '{"Theory":"90","Practical":"150","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "5", "qualification_type": "Future Skills Qualification,General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_05_50.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/ES/SCGJ/06462', 'Solar EV Charging Entrepreneur', 'environmental-science', 'Environmental Science', 4.0, 'Solar EV Charging Entrepreneur sets up an enterprise with an aim to provide a charging service to EV users while utilising solar energy (along with Grid power). This entrepreneur shall establish, setup and operate solar integrated EV charging stations/ Charging Point(s) for charging of electric vehicles at various locations to enable faster adoption of EVs across the country by ensuring safe, reliable, accessible, low cost and sustainable EV charging infrastructure. As per the revised guidelines by the Ministry of Power, an entity is free to set up public charging EV stations provided such stations meet the technical, safety, performance standards and protocol laid down by the Ministry of Power, Bureau of Energy Efficiency (BEE) and Central Electricity Authority.', 390, 390, '201–400', 'Version', '17 Nov 2022', '16 Nov 2025', 'Skill Council for Green Jobs (SCGJ)', 'Skill Council for Green Jobs', 'Entrepreneur', 'Solar EV Charging Dealership or Channel Partner (level 5)', 'Future Skills Qualification,General Qualification', 'N.A.', '{"Theory":"90","Practical":"150","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "6", "qualification_type": "Future Skills Qualification,General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_05_50.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/ES/SCGJ/06728', 'Agri-residue Aggregator', 'environmental-science', 'Environmental Science', 3.0, 'Agri-residue Aggregator collects agri-residues from farmers (suppliers) through nodal collection points, assesses quality and quantity of agri-residues and accordingly decides price. He/she appropriately sorts, densifies and stores the bales. He/she also perform sales of the bales based on end requirements', 330, 330, '201–400', 'Version', '30 Jun 2022', '29 Jun 2025', 'Skill Council for Green Jobs (SCGJ)', 'Skill Council for Green Jobs', 'Aggregator', 'The Agri-residue Aggregator (Level 3) to Biomass Depot Operator (Level 4)  to  Supervisor Biomass Depot (Level 5)', 'General Qualification', 'N.A.', '{"Theory":"90","Practical":"120","EmployabilitySkills":"30","OJT_Mandatory":"90","OJT_Recommended":""}', false, '{}'::text[], '{"source_row": "7", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_05_50.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/ES/SCGJ/06730', 'Animal Waste Manure Aggregator', 'environmental-science', 'Environmental Science', 3.0, 'Animal Waste Manure Aggregator is responsible for collection and aggregation of waste manure from different sources and supply it as input material for preparation of organic compost/vermi-compost, bio-gas etc. 
Elective 1:
Biogas Plant Operator: Animal Waste Manure Aggregator can further specialize in biogas plant operation and maintenance by acquiring the skills to become Biogas Plant Operator.
Elective 2:
Compost Plant Operator: Animal Waste Manure Aggregator can further specialize in compost plant operation and maintenance by acquiring the skills to become Compost Plant Operator.', 390, 450, '401–600', 'Version', '30 Jun 2022', '29 Jun 2025', 'Skill Council for Green Jobs (SCGJ)', 'Skill Council for Green Jobs', 'Aggregator', 'Animal Waste Manure Aggregator (Level 3) to Technician - Operations and Maintenance (Compressed Biogas/Waste to Energy) (Level 4)', 'Multi-Skill Qualification', 'N.A.', '{"Theory":"90","Practical":"180","EmployabilitySkills":"30","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "8", "qualification_type": "Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_05_50.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/ES/SCGJ/06731', 'Desludging Operator', 'environmental-science', 'Environmental Science', 3.0, 'The Desludging Operator, also known as Sludge Emptier is an individual, who is responsible for emptying, transport and disposal of faecal sludge from the septic tank/sewer line to desludging site / FSTP / Co-treatment plant. He /She has to operate Sludge Vacuum tank with trucks, pumps, suction hoses, and other machinery/equipment to empty the septic tank./sewer line. Desludging operator would further specialised as an entrepreneur, He / She would be trained  to venture into desludging services for managing Faecal Sludge.', 360, 360, '201–400', 'Version', '29 Sep 2022', '28 Sep 2025', 'Skill Council for Green Jobs (SCGJ)', 'Skill Council for Green Jobs', 'Operator', 'Desludging Operator (Level 3) to Entrepreneur-Faecal Sludge Management (Level 4)', 'General Qualification', 'N.A.', '{"Theory":"90","Practical":"150","EmployabilitySkills":"30","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "9", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_05_50.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/ES/SCGJ/06729', 'Biomass Depot Operator', 'environmental-science', 'Environmental Science', 4.0, 'Biomass Depot Operator is responsible for handling, storage and management of biomass at the storage depot. He/she looks after activities such as procurement of biomass from suppliers/farmers/aggregators, biomass pre-processing / densification and storage in a manner so as to ensure its quality and safety as per required industry standards.', 390, 390, '201–400', 'Version', '30 Jun 2022', '29 Jun 2025', 'Skill Council for Green Jobs (SCGJ)', 'Skill Council for Green Jobs', 'Supply Chain Management', 'Level-5 (Vertical)
Supervisor- Operations and Maintenance (Compressed Biogas/Waste to Energy)', 'General Qualification', 'N.A.', '{"Theory":"90","Practical":"120","EmployabilitySkills":"60","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "10", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_05_50.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-ES-00145-2023-V1-SCGJ', 'Green Hydrogen Plant Entrepreneur', 'environmental-science', 'Environmental Science', 5.0, 'Green Hydrogen Plant Entrepreneur would identify the potential market and the client needs/ requirements to propose the right kind of technically and economically feasible solution to set up green hydrogen plant. He/she is also expected to undertake specific works/sub component installations of a green hydrogen plant.', 480, 480, '401–600', 'Version', '31 Jan 2023', '30 Jan 2026', 'Skill Council for Green Jobs (SCGJ)', 'Skill Council for Green Jobs', 'Entrepreneur', 'Vertical Progression:  Large Scale Green Hydrogen Plant Contractor(Level 6)', 'Future Skills Qualification', 'N.A.', '{"Theory":"155","Practical":"145","EmployabilitySkills":"90","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "11", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_05_50.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-ES-00911-2023-V1-SCGJ & version 1', 'Biomass Pellet Manufacturing Junior Technician', 'environmental-science', 'Environmental Science', 3.0, 'Biomass Pellet Manufacturing Junior Technician is responsible for production, storage, and management of biomass pellets at the plant. He/she looks after activities such as biomass receiving, pre- processing/densification and storage in a manner to maintain its quality and safety as per standards.', 300, 300, '201–400', 'Version', '31 Aug 2023', '31 Aug 2026', 'Skill Council for Green Jobs (SCGJ)', 'Skill Council for Green Jobs', 'Process Line Operator', 'Vertical Progression:  Micro Entrepreneur-Bio-Energy (Biomass Pellet/Small Biogas)(Level 4) 
 or 
Technician-Biomass Pellet/Briquette Manufacturing (Level 4)', 'Future Skills Qualification', 'N.A.', '{"Theory":"100","Practical":"110","EmployabilitySkills":"30","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "12", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_05_50.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-ES-00764-2023-V1-SCGJ', 'Green Hydrogen Plant Junior Technician- Electrolyzer', 'environmental-science', 'Environmental Science', 3.0, 'Green Hydrogen Plant Junior Technician-Electrolyzer would primarily install electrolyzer units along with other Mechanical and Electrical equipment of a green hydrogen plant and perform the associated civil works. He/She would also assist in performing Pre-commissioning checks/tests and install & commission electrolyzer unit along with other sub system in a green hydrogen/green ammonia plant.', 330, 330, '201–400', 'Version', '31 Aug 2023', '30 Aug 2026', 'Skill Council for Green Jobs (SCGJ)', 'Skill Council for Green Jobs', 'Hydrogen Plant Technician', 'Vertical Progression: Green Hydrogen Plant Technician (Level 4)', 'Future Skills Qualification', 'N.A.', '{"Theory":"130","Practical":"110","EmployabilitySkills":"30","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "13", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_05_50.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-ES-00764-2023-V1-SCGJ & version 1', 'Green Hydrogen Plant Junior Technician- Power Sources', 'environmental-science', 'Environmental Science', 3.0, 'The job holder shall perform testing, installation and facility integration of various parts, repairs, troubleshooting, upkeep and maintenance of electrical control systems, protection systems, and other auxiliary equipment and associated tools in integrating power sources with electrolyser for production of Green Hydrogen. He/She will be responsible for the complete installation, maintenance, electric wiring for integrating power sources with electrolyser. This role works closely with the power supply project, testing, plant engineering, process operation, control & operation all types power sources integrating with electrolyser', 360, 360, '201–400', 'Version', '31 Aug 2023', '30 Aug 2026', 'Skill Council for Green Jobs (SCGJ)', 'Skill Council for Green Jobs', 'Hydrogen Plant Technician', 'Vertical Progression:    Junior Technician  Power Sources (Level 3.0)', 'Future Skills Qualification', 'N.A.', '{"Theory":"170","Practical":"100","EmployabilitySkills":"30","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "14", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_05_50.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-ES-00767-2023-V1-SCGJ', 'Green Hydrogen Plant Junior Technician- Storage', 'environmental-science', 'Environmental Science', 3.0, 'Green Hydrogen Plant Junior Technician- Storage would assist in installing Mechanical and Electrical equipment of a green hydrogen/green ammonia storage system along with perform the associated civil works. He/She would also assist in performing Pre-commissioning checks/tests and accordingly commission green hydrogen/green ammonia plant storage system.', 360, 360, '201–400', 'Version', '31 Aug 2023', '30 Aug 2026', 'Skill Council for Green Jobs (SCGJ)', 'Skill Council for Green Jobs', 'Hydrogen Plant Technician', 'Vertical Progression: Green Hydrogen Plant Technician Hydrogen (Level 4)', 'Future Skills Qualification', 'N.A.', '{"Theory":"170","Practical":"100","EmployabilitySkills":"30","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "15", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_05_50.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-ES-00766-2023-V1-SCGJ', 'Green Hydrogen Plant Junior Technician-Desalination', 'environmental-science', 'Environmental Science', 3.0, 'Green Hydrogen Plant Junior Technician-Desalination would install Mechanical and Electrical equipment of Desalination Unit in green hydrogen plant along with perform associated civil works. He/She would also perform Pre-commissioning checks/tests and commission, operation and maintenance of desalination unit in a  Green Hydrogen/Green Ammonia plant.', 360, 360, '201–400', 'Version', '31 Aug 2023', '30 Aug 2026', 'Skill Council for Green Jobs (SCGJ)', 'Skill Council for Green Jobs', 'Hydrogen Plant Technician', 'Vertical Progression: Green Hydrogen Plant Technician (Level 4)', 'Future Skills Qualification', 'N.A.', '{"Theory":"170","Practical":"100","EmployabilitySkills":"30","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "16", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_05_50.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-2.5-ES-00907-2023-V1-SCGJ', 'Solar Domestic Product Assembler', 'environmental-science', 'Environmental Science', 2.5, 'Solar Domestic Product Assembler assembles fabricated parts of small DC light sub assembly units by operating required tools. He/She also test and calibrate the assembled units to ensure the small DC based solar products meet the required quality and safety specifications. The job holder also repairs, refits and handles warranty claims for the concerned assembled units.', 270, 270, '201–400', 'Version', '31 Aug 2023', '30 Aug 2026', 'Skill Council for Green Jobs (SCGJ)', 'Skill Council for Green Jobs', 'Assembler', 'Vertical Progression:   Junior Technician- Solar Manufacturing (Level 3)', 'Future Skills Qualification', 'N.A.', '{"Theory":"125","Practical":"85","EmployabilitySkills":"30","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "17", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_05_50.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-ES-00913-2023-V1-SCGJ', 'Junior Technician- Mechanized Sewer Cleaning', 'environmental-science', 'Environmental Science', 3.0, 'Junior Technician- Mechanized Sewar Cleaning , is an individual, who is responsible for emptying, cleaning, transport and disposal of sludge from the sewer line to a specified site/Co-treatment plant. He /She has to operate and maintain Mechanized sewage cleaning machine, Sludge Vacuum tank with trucks, pumps, suction hoses, and other machinery/equipment to empty the manholes.', 330, 330, '201–400', 'Version', '31 Aug 2023', '30 Aug 2026', 'Skill Council for Green Jobs (SCGJ)', 'Skill Council for Green Jobs', 'Technician', 'Vertical Progression: Entrepreneurship: Entrepreneur- Faecal Sludge Management (Level 4) Organization value chain: Faecal Sludge Treatment Plant O&M Technician(Level 4)', 'Future Skills Qualification', 'N.A.', '{"Theory":"90","Practical":"120","EmployabilitySkills":"30","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "18", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_05_50.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-ES-00915-2023-V1-SCGJ', 'Plastic Recycling Micro Entrepreneur', 'environmental-science', 'Environmental Science', 4.0, 'A Plastic Recycling Micro Entrepreneur sets up a unit for recycling of plastic waste and converting into different recycled products. He/she deals with suppliers of raw material, technology, and other input material required for the recycling process. He has a sound understanding of the recycling process, technologies/ machines used and the end recycled product. During the same, ensures compliance related to setting up the business, statutory compliance for running the business and other type of environmental compliance that are required in the sector. He/she is responsible for financial management, people management, networking, market analysis and overall maintenance and sustenance of the business. He also manages the sales and customers of the recycled products.', 450, 450, '401–600', 'Version', '31 Aug 2023', '30 Aug 2026', 'Skill Council for Green Jobs (SCGJ)', 'Skill Council for Green Jobs', 'Supervisor and Foreman, Plastic Products Making', 'Vertical Progression: Waste Collection Entrepreneur (Level 5)', 'General Qualification', 'N.A.', '{"Theory":"95","Practical":"175","EmployabilitySkills":"60","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "19", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_05_50.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-ES-00914-2023-V1-SCGJ', 'Plastic Recycling Operator', 'environmental-science', 'Environmental Science', 3.0, 'Plastic Recycling Operator is responsible for overall manufacturing of recycled products from plastic waste. He/ she is responsible for ensuring that workers in the unit are working effectively and machines/equipment are working efficiently. He/she is also responsible for making sure that right input in terms of raw material, energy, fuel, pressure, temperature, etc is fed in the machines. He/ she also keeps a check on the health of the machines. He/ she also monitors the quality of the process of recycling and recycled products. Once the products are ready, he/she ensure suitable packing of the products and for maintaining necessary documentation for facility and for dispatch of end product', 360, 360, '201–400', 'Version', '31 Aug 2023', '31 Aug 2026', 'Skill Council for Green Jobs (SCGJ)', 'Skill Council for Green Jobs', 'Technician', 'Vertical Progression: Plastic Recycling Micro - Entrepreneur-Level 4', 'Future Skills Qualification', 'N.A.', '{"Theory":"95","Practical":"145","EmployabilitySkills":"30","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "20", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_05_50.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-3.5-ES-00909-2023-V1-SCGJ', 'Solar Photovoltaic Site Survey Assistant', 'environmental-science', 'Environmental Science', 3.5, 'Solar Photovoltaic Site Survey Assistant performs basic solar site survey and assessment for the installation of  small solar system. He/She conducts a physical solar site survey using various tools and ensures compliance  with state and national regulations, guidelines, along with industry and safety standards for solar Photovoltaic installations. The job holder must show a high level of attention to detail and have good written and verbal skills to communicate with supervisor, solar consumers and fellow team members.', 390, 390, '201–400', 'Version', '31 Aug 2023', '30 Oct 2026', 'Skill Council for Green Jobs (SCGJ)', 'Skill Council for Green Jobs', 'Site Survey', 'Vertical Progression:   Solar Photovoltaic Technician (Level 4.0)', 'General Qualification', 'N.A.', '{"Theory":"185","Practical":"145","EmployabilitySkills":"30","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "21", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_05_50.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-ES-00910-2023-V1-SCGJ', 'Solar Photovoltaic Technician', 'environmental-science', 'Environmental Science', 4.0, 'Solar PV Technician is responsible for installing small solar PV system including grid tied solar rooftop for domestic  consumers, solar street light, Mini & Micro grid etc. The individual at work assesses the installation site, understands the system layout requirement, carry out required safety measures to install small solar projects while ensuring an effective  functioning of the system post installation.', 420, 420, '401–600', 'Version', '31 Aug 2023', '30 Aug 2026', 'Skill Council for Green Jobs (SCGJ)', 'Skill Council for Green Jobs', 'Technician', 'Vertical Progression:  Organizational Vertical- Solar PV Engineer (Level 5.0)
                                         Entrepreneurial Vertical- Solar Photovoltaic Entrepreneur (Level 5.0)', 'General Qualification', 'N.A.', '{"Theory":"200","Practical":"130","EmployabilitySkills":"60","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "22", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_05_50.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
