INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-ES-00669-2023-V1-SCGJ', 'Sewer Entry Professional', 'environmental-science', 'Environmental Science', 3.0, 'Sewer Entry Professional, is an individual, who is responsible for emptying, Cleaning and transport and disposal of sludge from the sewer line to specified site/Co-treatment plant. He /She has to do manual sewage cleaning in the areas having space limitations. He/She can use pumps, blowers, scrapper, Manila Rope and Cloth Ball, Sectional Sewer Rods and other tools/equipment to empty the sewage manholes.', 330, 330, '201–400', 'Version', '31 Aug 2023', '30 Aug 2026', 'Skill Council for Green Jobs (SCGJ)', 'Skill Council for Green Jobs', 'Technician', 'Vertical Progression: Entrepreneurship: Micro-Entrepreneur- Faecal Sludge Management (Level 4)
Organization value chain: Faecal Sludge Treatment Plant O&M Technician(Level 4)', 'Future Skills Qualification', 'N.A.', '{"Theory":"80","Practical":"130","EmployabilitySkills":"30","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "24", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_05_50.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
