INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-04-ES-02095-2024-V1-SCGJ', 'Green Logistics Practices', 'environmental-science', 'Environmental Science', 4.0, 'This standalone NOS is designed to incorporate environmentally sustainable practices and principles into logistics education and training.  This aims to train existing and future professionals in the field of logistics while emphasizing the importance of reducing environmental impacts, optimizing resources, and promoting sustainable operations within the supply chain.

Adopting green skills in logistics sector not only benefits the environment but can also lead to reduced operating costs, improved public perception, and compliance with evolving environmental regulations. It is essential for logistics operators to stay updated on the latest sustainable practices and technologies to remain competitive and environmentally responsible in the logistics and supply chain industry. In that context, the proposed NOS is to introduce generic green skills under logistics sector courses by dove-tailing green skill modules to the current and future logistics course curricula.', 30, 30, '1–200', 'Version', '31 Jan 2024', '30 Jan 2027', 'Skill Council for Green Jobs (SCGJ)', 'Skill Council for Green Jobs
Chief Executive Officer
CBIP Building, Malcha Marg,
Chanakyapuri, New Delhi – 110021
Contact no. and mail: 9871119101, ceogreenjobs@gmail.com', 'Green Logistics', 'Not Applicable', 'Future Skills Qualification', 'N.A.', '{"Theory":"20","Practical":"10","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "29", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_05_50.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
