INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-ES-01756-2023-V1-SCGJ & version 1', 'Nature Conservator Cum Ecotourism Guide', 'environmental-science', 'Environmental Science', 4.0, 'This short-term training programme has theoretical and practical skills. Green Skill Development contributes to preserving and restoring environmental quality for a sustainable future and includes jobs that protect ecosystems and biodiversity, reduce energy and minimize waste and pollution. The programme endeavors to develop green skilled workers having technical knowledge and commitment to sustainable development, which will help in the attainment of the Nationally Determined Contributions (NDCs), Sustainable Development Goals (SDGs), National Biodiversity Targets (NBTs), as well as Waste Management Rules (2016).', 420, 420, '401–600', 'Version', '31 Jan 2024', '31 Jan 2027', 'Skill Council for Green Jobs (SCGJ)', 'Nature Conservator Cum Ecotourism Guide', 'Naturalist/Ecotourism Entrepreneur', 'Vertical Progression:     Ecotourism entrepreneur (Level 5.0)', 'General Qualification', 'N.A.', '{"Theory":"120","Practical":"240","EmployabilitySkills":"00","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "44", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_05_50.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notiona