INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-ES-01970-2024-V1-NIWE', 'WIND FARM ENGINEER', 'environmental-science', 'Environmental Science', 5.0, 'This Qualification will enable the individual to get complete overview about all aspects of Wind Power starting from introduction to wind and its technology, wind resource assessment, installation and commissioning, operation and maintenance aspects of wind farms in a focused manner along with financial and policy aspects. They will oversee the site selection, installation, commissioning of mechanical, electrical and hydraulic components of wind turbines and take care of the safe operation for better performance. They will also guide the manpower working under them.', 540, 540, '401–600', 'Version', '31 Jan 2024', '31 Jan 2027', 'National Institute of Wind Energy', 'National Institute of Wind Energy 
657, 1A2, Velachery - Tambaram Main Road, Pallikaranai
Chennai, Tamil Nadu - 600100
URL: https://niwe.res.in', 'Renewable energy', 'Vertical progression

Wind Engineering Manager, Site / Plant Manager, Construction Manager (Level 6)




Wind Farm Engineer 

Horizontal

Site Survey Engineer, Wind CMS Engineer, Wind Resource Assessment Engineer, Wind Design Engineer, Wind Project Engineer (Level 5)', 'General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"180","Practical":"180","EmployabilitySkills":"60","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "47", "qualification_type": "General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_05_50.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
