INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-ES-02631-2024-V2-SCGJ', 'Solar Water Pumping Junior Engineer', 'environmental-science', 'Environmental Science', 5.0, 'A Solar Water Pumping Junior Engineer specializes in the design, installation and commissioning of the solar PV power plant, its quality assurance and Health & Safety issues. He/she also specializes in designing, installation and commissioning of solar water pumping systems.', 540, 540, '401–600', 'Version', '27 May 2021', '29 May 2027', 'Skill Council for Green Jobs (SCGJ)', 'Skill Council for Green Jobs', 'PV System Installation Engineer', 'Solar Site In-charge (Level 6), Solar PV O&M Engineer', 'General Qualification', 'N.A.', '{"Theory":"165","Practical":"225","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "53", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_05_50.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-ES-00146-2023-V1-SCGJ & version 1', 'Green Hydrogen Plant Technician', 'environmental-science', 'Environmental Science', 4.0, 'Green Hydrogen Plant Technician shall perform testing, installation and facility integration of
electrolyser, repairs, troubleshooting, upkeep and maintenance of electrical control systems,
protection systems, and other auxiliary equipment and associated tools in Green hydrogen
generation facilities. The job holder will be responsible for the continuous supply of renewable
power for its integration with the electrolysers and the other process equipment for generating
Green Hydrogen. This role works closely with the power supply project, testing, plant engineering,
process operation, control & operation across the green hydrogen generation plant.', 420, 420, '401–600', 'Version', '31 Jan 2023', '31 Jan 2026', 'Skill Council for Green Jobs (SCGJ)', 'Skill Council for Green Jobs', 'Hydrogen Plant Technician', 'Vertical Progression: Supervisor-Green Hydrogen System/Green Hydrogen Plant Entrepreneur
(Level 5)', 'Future Skills Qualification', 'N.A.', '{"Theory":"160","Practical":"140","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "54", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_05_50.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-ES-00147-2023-V1-SCGJ & version 1', 'Solar PV Cell Manufacturing Technician', 'environmental-science', 'Environmental Science', 4.0, 'Solar PV Cell Manufacturing Technician performs solar cell manufacturing tasks in a production line, cleans silicon wafer, undertake chemical and thermal processing in making solar cells. The job holder operates various stations including metallization processes and  is also responsible for testing and packaging of solar cells.', 420, 420, '401–600', 'Version', '31 Jan 2023', '31 Jan 2026', 'Skill Council for Green Jobs (SCGJ)', 'Skill Council for Green Jobs', 'Process Line Operator', 'Vertical Progression:  Production Supervisor (Level 5)', 'Future Skills Qualification', 'N.A.', '{"Theory":"130","Practical":"110","EmployabilitySkills":"60","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "55", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_05_50.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-4.5-ES-03442-2024-V1-IGNOU', 'Fundamentals of Plastic Waste Management', 'environmental-science', 'Environmental Science', 4.5, 'The course is designed to provide individuals with a deep understanding of the Plastic waste, the hazards associated with it and importance of its suitable management. The course is related to the skills required to handle and manage the plastic waste in a proper and scientific manner. The NOS will equip the inividuals to segregate the various types of plastic waste into specific categories . The rules, regulations and guidelines related to Plastic Waste Management are also covered in the course.', 120, 120, '1–200', 'Version', '17 Dec 2024', '16 Dec 2027', 'Indira Gandhi National Open University (IGNOU)', 'IGNOU', 'Plastic waste management expert', 'Plastic Waste management Expert, Supervisor, Recycler, Manager', 'National Occupational Standard', 'N.A.', '{"Theory":"50","Practical":"70","EmployabilitySkills":"00","OJT_Mandatory":"00"}', false, '{}'::text[], '{"source_row": "56", "qualification_type": "National Occupational Standard", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_05_50.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-4.5-ES-03450-2024-V1-SCGJ', 'Approaches to Carbon Accounting', 'environmental-science', 'Environmental Science', 4.5, 'This micro credential is designed for individuals who are seeking to deepen their understanding and practical skills in carbon accounting. The course covers essential approaches to measuring and managing greenhouse gas emissions, including the use of key frameworks like the Greenhouse Gas Protocol and ISO 14064. Learners will gain hands-on experience in calculating carbon footprints, tracking emissions across Scopes 1, 2, and 3. Participants will also learn to prepare carbon inventories, develop reports, and learn about global frameworks and standards for carbon accounting.', 30, 30, '1–200', 'Version', '17 Dec 2024', '16 Dec 2027', 'Skill Council for Green Jobs (SCGJ)', 'Skill Council for Green Jobs', 'Environmental Compliance', 'Not Applicable', 'Future Skills Qualification', 'N.A.', '{"Theory":"16","Practical":"14","EmployabilitySkills":"00","OJT_Mandatory":"00"}', false, '{}'::text[], '{"source_row": "57", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_05_50.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-5.5-ES-03453-2024-V1-SCGJ', 'Fundamentals of Business Development for Hydrogen Fuel Cell', 'environmental-science', 'Environmental Science', 5.5, 'The micro-credential course targets professionals in the hydrogen fuel cell industry, providing fundamental knowledge and practical skills for business development. It covers hydrogen fuel cell technology, market analysis, business planning, investment opportunities, and communication and Presentation Skills. Participants will also learn marketing, sales strategies, and methods for identifying and evaluating business opportunities and partnerships. Focused on upskilling business development professionals, the course prepares them to seize opportunities in stationary power, portable power, and transportation industries, driving growth in production, distribution, and market expansion.', 30, 30, '1–200', 'Version', '17 Dec 2024', '16 Dec 2027', 'Skill Council for Green Jobs (SCGJ)', 'Skill Council for Green Jobs', 'Business Development Executive', 'Not Applicable', 'Future Skills Qualification', 'N.A.', '{"Theory":"16","Practical":"14","EmployabilitySkills":"00","OJT_Mandatory":"00"}', false, '{}'::text[], '{"source_row": "58", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_05_50.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-4.5-ES-03451-2024-V1-SCGJ', 'Fundamentals of ESG Compliance', 'environmental-science', 'Environmental Science', 4.5, 'This micro-credential provides a foundational understanding of Environmental, Social, and Governance (ESG) compliance. The course is designed for individuals seeking to develop essential skills in identifying, managing, and reporting ESG factors within an organization. It covers key areas such as regulatory frameworks, risk assessment, compliance strategies, and sustainability reporting. Learners will gain practical knowledge to ensure compliance with ESG standards, identify risks, and contribute to building a sustainable and socially responsible business.', 30, 30, '1–200', 'Version', '17 Dec 2024', '16 Dec 2027', 'Skill Council for Green Jobs (SCGJ)', 'Skill Council for Green Jobs', 'Environmental Compliance', 'Not Applicable', 'Future Skills Qualification', 'N.A.', '{"Theory":"16","Practical":"14","EmployabilitySkills":"00","OJT_Mandatory":"00"}', false, '{}'::text[], '{"source_row": "59", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_05_50.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-04-ES-03452-2024-V1-SCGJ', 'Fundamentals of Hydrogen Fuel Cell', 'environmental-science', 'Environmental Science', 4.0, 'The micro credential offers an in-depth exploration of the concepts and practical applications of hydrogen fuel cells. It aims to provide a solid understanding of hydrogen fuel cell technology, its components, operation, maintenance, and safety aspects. This upskilling primarily focus to existing operator of Diesel Generator or professionals working on internal combustion engine. The content may be also be utilized in university education to ensure that learners have well rounded understanding of the interdisciplinary concepts in hydrogen fuel cell technology.', 30, 30, '1–200', 'Version', '17 Dec 2024', '16 Dec 2027', 'Skill Council for Green Jobs (SCGJ)', 'Skill Council for Green Jobs', 'Technician', 'Not Applicable', 'Future Skills Qualification', 'N.A.', '{"Theory":"16","Practical":"14","EmployabilitySkills":"00","OJT_Mandatory":"00"}', false, '{}'::text[], '{"source_row": "60", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_05_50.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-ES-03678-2025-V1-SCGJ', 'Small Hydro Power Plant Technician', 'environmental-science', 'Environmental Science', 4.0, 'Small Hydro Plant Technician (Jal Urja Mitra) specializes to operate, test and maintain different electrical, hydro-mechanical, civil components of Small Hydro Power plants to meet the performance and reliability needs by incorporating quality workmanship and complying with all applicable codes, standards, and safety requirements', 600, 600, '401–600', 'Version', '18 Feb 2025', '17 Feb 2028', 'Skill Council for Green Jobs (SCGJ)', 'Skill Council for Green Jobs', 'Technician', 'Small hydro Power Plant Operations and Maintenance Engineer (level 5)', 'General Qualification', 'N.A.', '{"Theory":"205","Practical":"215","EmployabilitySkills":"60","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "61", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_05_50.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-ES-03868-2025-V1-TATAPWR', 'Green Energy Supervisor - Solar', 'environmental-science', 'Environmental Science', 5.0, 'A  Green Energy Supervisor – Solar specializes in technology, installation, and maintenance & troubleshooting of photovoltaic (PV) systems to ensure efficient solar energy generation. They are responsible for implementing system design, installing panels, troubleshooting issues, and performing routine maintenance to enhance performance and safety. Their role also involves adhering to industry standards, optimizing energy output, and contributing to the growth of renewable energy solutions.', 510, 510, '401–600', 'Version', '08 May 2025', '07 May 2028', 'The Tata Power Company Limited', 'Tata Power Company limited', 'Site Supervisor', 'Site Supervisor, Solar PV Manager', 'Upskilling Qualification', 'N.A.', '{"Theory":"210","Practical":"180","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "62", "qualification_type": "Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_05_50.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-3.5-ES-03447-2024-V1-SS', 'Entrepreneurship in Solar Water Heater Manufacturing', 'environmental-science', 'Environmental Science', 3.5, 'The qualification for Entrepreneurship in Solar Water Heater Manufacturing is designed to equip individuals with the essential skills and knowledge to establish and manage their own small enterprise in the solar water heater manufacturing sector. It focuses on the technical aspects of solar water heater production, including system components, assembly, and quality standards, along with key entrepreneurial competencies such as business planning, marketing, financial management, and supply chain operations. The program also introduces learners to regulatory frameworks, intellectual property protection, and government initiatives promoting renewable energy ventures, enabling them to build sustainable and efficient solar water heater businesses.', 90, 90, '1–200', 'Version', '17 Dec 2024', '16 Dec 2027', 'Samadhan Samiti', 'Samadhan Samiti, 2nd Floor, Siddhivinayak Building, 27/1/B Samadhan Tower, Gokhale Marg, Lucknow, Uttar Pradesh, Pincode - 226001', 'Renewable Energy', 'N/A', 'Cross Sectoral Qualification', 'N.A.', '{"Theory":"60","Practical":"30","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "63", "qualification_type": "Cross Sectoral Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_05_50.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-4.5-ES-04414-2025-V1-SGSU', 'Junior Supervisor – E-Waste (Recycling and Resource Recovery)', 'environmental-science', 'Environmental Science', 4.5, 'The Junior Supervisor – E-Waste (Recycling and Resource Recovery) qualification equips individuals with the skills to supervise daily operations in e-waste recycling facilities. The role focuses on monitoring team activities, ensuring compliance with safety and environmental regulations, supporting workforce training, and maintaining accurate operational records.', 450, 450, '401–600', 'Version', '07 Oct 2025', '07 Oct 2028', 'Scope Global Skills University, Bhopal', 'Scope Global Skills University (SGSU)', 'E-waste Management', 'E-waste Deputy Manager (Level 5), E-waste Manager (Level 5.5)', 'Cross Sectoral Qualification,Future Skills Qualification', 'N.A.', '{"Theory":"110","Practical":"200","EmployabilitySkills":"60","OJT_Mandatory":"80"}', false, '{}'::text[], '{"source_row": "64", "qualification_type": "Cross Sectoral Qualification,Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_05_50.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/FI/FICSI/06456', 'Food Analyst', 'food-industry-food-processing', 'Food Industry/Food Processing', 4.0, 'A food analyst is responsible for conducting qualitative and quantitative tests to determine the physical and chemical properties of food. They are also responsible for recording and compiling the test results, preparing charts and reports as well preparing and incubating plates with cultures. They define quality assurance targets and procedures and see to their maintenance and continued improvement by reviewing targets, protocols, supplies, processes, equipment, and technologies for quality standards', 510, 510, '401–600', 'Version', '17 Nov 2022', '16 Nov 2025', 'Food Industry Capacity & Skill Initiative (FICSI)', 'Food Industry Capacity & Skill Initiative (FICSI)', 'Quality Analysis/ Assurance', 'Assistant Lab Technician, Food Analyst, Technical Lead, Food Microbiologist', 'General Qualification', 'N.A.', '{"Theory":"120","Practical":"240","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "1", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_01.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/FI/FICSI/06458', 'Internal Food Auditor-Food Processing', 'food-industry-food-processing', 'Food Industry/Food Processing', 6.0, 'This qualification reflects the role of individuals who apply specialist knowledge and skills in food safety for auditing purposes. They conduct a range of audits in different environments to monitor food quality and safety according to relevant legislation, including food standards.', 600, 600, '401–600', 'Version', '17 Nov 2022', '16 Nov 2025', 'Food Industry Capacity & Skill Initiative (FICSI)', 'Food Industry Capacity and Skill Initiative', 'Quality Analysis/ Assurance', 'Quality Assurance Manager', 'General Qualification', 'N.A.', '{"Theory":"150","Practical":"240","EmployabilitySkills":"90","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "2", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_01.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/FI/FICSI/06457', 'Small Food Business Operator', 'food-industry-food-processing', 'Food Industry/Food Processing', 2.0, 'Petty Food Business Operator at work is responsible for the preparation and selling of food products at a particular location.
Petty food business operators (FBO) himself manufacture, sells, any article of food or a petty retailers, hawkers, itinerant vendor or a temporary stall holder or small scale or cottage or any such other industries relating to food business operator.
The Retail/ Street/ Petty Food Business Operator needs to effectively communicate with the guests and follow the basic food and health safety practices.
He should also know and understand the FSSAI registration and licensing requirements.', 300, 300, '201–400', 'Version', '17 Nov 2022', '16 Nov 2025', 'Food Industry Capacity & Skill Initiative (FICSI)', 'Food Industry Capacity and Skill Initiative', 'Food Sales and Retail Operations', 'Food Sales Promoter (level 3)', 'General Qualification', 'N.A.', '{"Theory":"90","Practical":"180","EmployabilitySkills":"30","OJT_Mandatory":"00"}', false, '{}'::text[], '{"source_row": "3", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_01.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/FI/FICSI/06455', 'Supervisor-Food Processing Industries', 'food-industry-food-processing', 'Food Industry/Food Processing', 5.0, 'The individual at work is responsible for supervising of the production process in food manufacturing facility as per the organizational standards. The individual monitors equipment performance to ascertain proper utilization and carries out preventive maintenance in a processing unit compliance with food safety standards of the organization.', 570, 840, '801–1000', 'Version', '17 Nov 2022', '16 Nov 2025', 'Food Industry Capacity & Skill Initiative (FICSI)', 'Food Industry Capacity and Skill Initiative', 'Production', 'In Charge-Food Processing Facility', 'General Qualification', 'N.A.', '{"Theory":"150","Practical":"240","EmployabilitySkills":"60","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "4", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_01.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-3-FI-00359-2023-V1-FICSI', 'Millet Product Processor', 'food-industry-food-processing', 'Food Industry/Food Processing', 3.0, 'A Millet Product Processor is responsible for producing various types of value added millet based products that involves selection of various millets, other raw materials, pre-processing, production, packaging, storage and maintaining their consistency and quality, while meeting defined SOPs.', 240, 360, '201–400', 'Version', '13 Jun 2023', '31 Mar 2027', 'Food Industry Capacity & Skill Initiative (FICSI)', 'Food Industry Capacity and Skill Initiative (FICSI)', 'Processing-Food Grain Milling (including oilseeds)', 'Millet Product Processor (NSQF Level 3), Milling Technician (NSQF Level 4)', 'General Qualification', 'N.A.', '{"Theory":"110","Practical":"220","EmployabilitySkills":"30","OJT_Mandatory":"00"}', false, '{}'::text[], '{"source_row": "5", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_01.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-AG-00577-2023-V1-FICSI', 'Food Lab Instrumentation Specialist', 'food-industry-food-processing', 'Food Industry/Food Processing', 5.0, 'A Lab Instrumentation Specialist is responsible for writing and execution of validation documents for laboratory instrumentation in compliance with Good Manufacturing Practices (GMP). An individual coordinates with instrument vendors and works with a cross functional team to deliver on all system lifecycle documents for the laboratory. In addition, writing Standard Operating Procedures (SOPs) to support running of the laboratory and supporting containment verification of the laboratory. An individual also participates in setting up general running of laboratory – glassware, reagents, consumable, 5S, etc. and ensure safety, consistency and reliability of chemical testing following the Good Laboratory Practices (GLP)', 510, 510, '401–600', 'Version', '23 Jun 2023', '22 Jun 2026', 'Food Industry Capacity & Skill Initiative (FICSI)', 'Food Industry Capacity and Skill Initiative (FICSI)
Shriram Bhartiya Kala Kendra (3rd Floor)
1, Copernicus Marg, New Delhi 110001, Phone: 9711260230', 'Quality Analysis / Assurance', 'Internal Auditor-Food Processing (Level 6)', 'General Qualification', 'N.A.', '{"Theory":"160","Practical":"320","EmployabilitySkills":"30","OJT_Mandatory":"00"}', false, '{}'::text[], '{"source_row": "6", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_01.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
