INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-FI-04000-2025-V2-FICSI', 'Craft Baker', 'food-industry-food-processing', 'Food Industry/Food Processing', 4.0, 'A Craft Baker specializes in producing a diverse range of artisanal bakery products, including breads, buns, cakes, pastries, rusk, and more, on a small scale for the retail market. The role involves sourcing high-quality raw materials, ensuring the production of premium baked goods, and coordinating with vendors for timely product delivery. Throughout the process, the individual follows best practices and implements necessary measures to maintain food safety and hygiene in the workplace.', 450, 450, '401–600', 'Version', '01 May 2025', '30 Apr 2028', 'Food Industry Capacity & Skill Initiative (FICSI)', 'Food Industry Capacity and Skill Initiative (FICSI)', 'Processing-Bread and Bakery', 'Plant Baker (L5)', 'General Qualification', 'N.A.', '{"Theory":"90","Practical":"240","EmployabilitySkills":"30","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "34", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_01.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-FI-03997-2025-V2-FICSI', 'Fruit Pulp Junior Processor', 'food-industry-food-processing', 'Food Industry/Food Processing', 3.0, 'The Fruit Pulp Junior Processor is responsible for handling and processing a variety of fruits to produce high-quality fruit-based products. This role involves overseeing the entire production process, from raw material preparation to the storage of finished products, ensuring adherence to quality and safety standards.', 390, 450, '401–600', 'Version', '01 May 2025', '30 Apr 2028', 'Food Industry Capacity & Skill Initiative (FICSI)', 'FICSI', 'Processing-Fruits and Vegetables', 'Preservation Processor-Fruits and Vegetables (L4)', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"60","Practical":"150","EmployabilitySkills":"30","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "35", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_01.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-FI-03892-2025-V2-FICSI', 'Preservation Technician-Fruits and Vegetables', 'food-industry-food-processing', 'Food Industry/Food Processing', 3.0, 'A Preservation Technician – Fruits and Vegetables is responsible for executing preservation processes such as drying, canning, and freezing to extend the shelf life of produce while maintaining its quality and safety. The individual ensures proper sorting, washing, peeling, blanching, and packing of fruits and vegetables.', 390, 390, '201–400', 'Version', '18 Feb 2025', '17 Feb 2028', 'Food Industry Capacity & Skill Initiative (FICSI)', 'FICSI', 'Processing-Fruits and Vegetables', 'Multiskill Technician - Food Processing Industries (Level 4)', 'General Qualification', 'N.A.', '{"Theory":"90","Practical":"210","EmployabilitySkills":"30","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "36", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_01.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-06-FI-03603-2025-V2-FICSI', 'Quality Assurance Manager (Processed Food Industry)', 'food-industry-food-processing', 'Food Industry/Food Processing', 6.0, 'A Quality Assurance Manager (Processed Food Industry) is responsible for developing, implementing, and monitoring quality management systems to ensure that all food products meet regulatory standards and customer expectations. The individual oversees the entire production process, conduct regular audits, manages food safety protocols, and leads continuous improvement initiatives. The role involves training staff on quality standards, analyzing data to identify areas for improvement, and coordinating with suppliers to ensure the quality of raw materials', 600, 600, '401–600', 'Version', '18 Feb 2025', '17 Feb 2028', 'Food Industry Capacity & Skill Initiative (FICSI)', 'Food Industry Capacity and Skill Initiative (FICSI)', 'Quality Analysis/Assurance', 'Regional QA Manager (L7)', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"150","Practical":"270","EmployabilitySkills":"90","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "37", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_01.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-FI-03894-2025-V2-FICSI', 'Microbiologist (Food)', 'food-industry-food-processing', 'Food Industry/Food Processing', 5.0, 'A Microbiologist (Food) is responsible for analyzing and monitoring the microbial quality of food products to ensure safety and compliance with regulatory standards. The individual conducts various microbiological tests, including advanced techniques such as Enzyme-Linked Immunosorbent Assay (ELISA) and Polymerase Chain Reaction (PCR), to detect both pathogenic and non-pathogenic organisms. The role involves designing and implementing food safety protocols, troubleshooting contamination issues, and collaborating with production and quality teams to improve hygiene practices and product quality.', 510, 510, '401–600', 'Version', '18 Feb 2025', '17 Feb 2028', 'Food Industry Capacity & Skill Initiative (FICSI)', 'Food Industry Capacity and Skill Initiative (FICSI)', 'Quality Analysis/ Assurance', 'Lab In-charge (Microbiology) (Level 6)', 'General Qualification', 'N.A.', '{"Theory":"130","Practical":"200","EmployabilitySkills":"60","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "38", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_01.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-03-FI-04211-2025-V1-FICSI', 'Fundamentals of Managing a Cloud Kitchen', 'food-industry-food-processing', 'Food Industry/Food Processing', 3.0, 'The Fundamentals of Managing a Cloud Kitchen course provides participants with a comprehensive understanding of food production tailored for delivery and takeaway, without the need for a dine-in space. The course covers key aspects including cuisine selection, menu development, and product portfolio planning. Participants will gain insight into the concept and benefits of operating a cloud kitchen, along with guidance on choosing the right location, designing the kitchen layout, selecting essential equipment, and adhering to relevant food safety regulations and licensing requirements.', 90, 90, '1–200', 'Version', '08 May 2025', '07 May 2028', 'Food Industry Capacity & Skill Initiative (FICSI)', 'Food Industry Capacity & Skill Initiative (FICSI)', 'Food Sales and Retail Operations', 'Not Applicable', 'General Qualification', 'N.A.', '{"Theory":"30","Practical":"60","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "39", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_01.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-FI-03895-2025-V2-FICSI', 'Assistant Sanitation Supervisor (Processed Food Industry)', 'food-industry-food-processing', 'Food Industry/Food Processing', 4.0, 'An Assistant Sanitation Supervisor (Processed Food Industry)  is responsible for ensuring the cleanliness and sanitation of the work area in compliance with food safety regulations. This role involves planning, preparing, and supervising cleaning activities while monitoring hygiene practices across the facility. The individual is responsible for maintaining high food safety standards, ensuring all staff adhere to organizational protocols and regulatory guidelines.', 420, 420, '401–600', 'Version', '18 Feb 2025', '17 Feb 2028', 'Food Industry Capacity & Skill Initiative (FICSI)', 'Food Industry Capacity and Skill Initiative (FICSI)', 'Quality Analysis/ Assurance', 'Food Safety Officer (Level 5)', 'General Qualification', 'N.A.', '{"Theory":"90","Practical":"180","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "40", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_01.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-04-FI-04212-2025-V1-FICSI', 'Concept of Food Safety in Processing Unit', 'food-industry-food-processing', 'Food Industry/Food Processing', 4.0, 'This course provides participants with a thorough understanding of food safety fundamentals specific to food processing units. It covers core food safety principles, regulatory requirements of a food processing facility, and effective risk management strategies, enabling professionals to implement protocols that maintain hygiene, prevent contamination, and comply with industry standards for safe food production.', 60, 60, '1–200', 'Version', '08 May 2025', '07 May 2028', 'Food Industry Capacity & Skill Initiative (FICSI)', 'Food Industry Capacity & Skill Initiative (FICSI)', 'Quality Analysis/Assurance', 'Not Applicable', 'General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"20","Practical":"40","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "41", "qualification_type": "General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_01.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-04-FI-04213-2025-V1-FICSI', 'Fundamentals of Food Quality and Testing', 'food-industry-food-processing', 'Food Industry/Food Processing', 4.0, 'This course focuses on the fundamentals of food analysis and testing, covering essential methods for ensuring food quality. Participants will learn to develop quality control systems and conduct physical, chemical, and microbiological tests on both food and packaging. The curriculum includes key topics such as quality monitoring, statistical analysis, regulatory compliance, laboratory management, and sustainable practices. By the end of the course, participants will be equipped to ensure food safety and quality in industrial as well as in professional testing laboratories.', 60, 60, '1–200', 'Version', '08 May 2025', '07 May 2028', 'Food Industry Capacity & Skill Initiative (FICSI)', 'Food Industry Capacity & Skill Initiative (FICSI)', 'Quality Analysis/Assurance', 'Not Applicable', 'General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"20","Practical":"40","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "42", "qualification_type": "General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_01.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
