INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-2.5-HC-00759-2023-V1-HCSSC', 'Basic Sculptor and stone artist (Moortikar)', 'handicrafts-carpets', 'Handicrafts & Carpets', 2.5, 'Sculpting and stone art with local materials involves shaping readily available stones using hand tools. Artisans draw inspiration from their surroundings and cultural heritage, creating meaningful sculptures that reflect tradition and community. This process fosters sustainability, preserves cultural identity, and contributes to local economies.', 40, 40, '1–200', 'Version', '14 Sep 2023', '15 Sep 2023', 'Handicrafts and Carpet Sector Skill Council (HCSSC)', 'Handicrafts and Carpet Sector Skill Council (HCSSC)', 'Stone Crafting', 'Not Applicable', 'National Occupational Standard', 'N.A.', '{"Theory":"11.5","Practical":"28.5","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "2", "qualification_type": "National Occupational Standard", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-2.5-HC-00758-2023-V1-HCSSC', 'Traditional Mat Weaver', 'handicrafts-carpets', 'Handicrafts & Carpets', 2.5, '"Mat weaving is a traditional craft that involves creating flat, flexible mats by interlacing dried straw
orother similar plant materials. These mats are used for various purposes, such as seating, sleeping,
decoration, and even as practical household items"', 40, 40, '1–200', 'Version', '14 Sep 2023', '15 Sep 2023', 'Handicrafts and Carpet Sector Skill Council (HCSSC)', 'Handicrafts and Carpet Sector Skill Council (HCSSC)', 'Weaver', 'Not Applicable', 'National Occupational Standard', 'N.A.', '{"Theory":"11.5","Practical":"28.5","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "3", "qualification_type": "National Occupational Standard", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-2.5-HC-00757-2023-V1-HCSSC', 'Traditional Malakar', 'handicrafts-carpets', 'Handicrafts & Carpets', 2.5, 'A traditional mala maker is an artisan who specializes in creating malas and bouquets which is made from natural flowers and artificial flowers.', 40, 40, '1–200', 'Version', '14 Sep 2023', '15 Sep 2023', 'Handicrafts and Carpet Sector Skill Council (HCSSC)', 'Handicrafts and Carpet Sector Skill Council (HCSSC)', 'Handicrafts', 'Not Applicable', 'National Occupational Standard', 'N.A.', '{"Theory":"11.5","Practical":"28.5","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "4", "qualification_type": "National Occupational Standard", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-2.5-HC-00754-2023-V1-HCSSC', 'Traditional Broom Maker', 'handicrafts-carpets', 'Handicrafts & Carpets', 2.5, '"Traditional broom making is a skilled craft that involves selecting, preparing, and assembling natural
materials like straw, palm leaves to create functional sweeping tools. Artisans carefully bind these
materials to a wooden or bamboo handle, producing brooms with a unique blend of durability and
cultural significance."', 40, 40, '1–200', 'Version', '14 Sep 2023', '15 Sep 2023', 'Handicrafts and Carpet Sector Skill Council (HCSSC)', 'Handicrafts and Carpet Sector Skill Council (HCSSC)', 'Handicrafts', 'Not Applicable', 'National Occupational Standard', 'N.A.', '{"Theory":"11.5","Practical":"28.5","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "5", "qualification_type": "National Occupational Standard", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-2.5-HC-00753-2023-V1-HCSSC', 'Coir Weaver', 'handicrafts-carpets', 'Handicrafts & Carpets', 2.5, '"Coir fiber, extracted from the outer husk of coconuts, is a versatile natural material that artisans use
to create a variety of basic and intricate products. Artisans skillfully work with coir fiber to craft
functional and
decorative items."', 40, 40, '1–200', 'Version', '14 Sep 2023', '15 Sep 2023', 'Handicrafts and Carpet Sector Skill Council (HCSSC)', 'Handicrafts and Carpet Sector Skill Council (HCSSC)', 'Coir Making', 'Not Applicable', 'National Occupational Standard', 'N.A.', '{"Theory":"11.5","Practical":"28.5","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "6", "qualification_type": "National Occupational Standard", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-2.5-HC-00752-2023-V1-HCSSC', 'Traditional Basket Maker', 'handicrafts-carpets', 'Handicrafts & Carpets', 2.5, '"Traditional basket making is an intricate craft that focuses on basket making
which involves weaving jute, moonjh and other village based local materials
into both functional and ornamental baskets. The process intricately involves
and skillful sewing of the strips to construct the foundation and sides of the
basket. This artistry may also encompass the integration of weaving
patterns, culminating in the final steps of shaping the basket and adding
optional handles to infuse a unique, personalized flair"', 40, 40, '1–200', 'Version', '14 Sep 2023', '15 Sep 2023', 'Handicrafts and Carpet Sector Skill Council (HCSSC)', 'Handicrafts and Carpet Sector Skill Council (HCSSC)', 'Stitching, Weaving, Making and Finishing Handicrafts (Bamboo)', 'Not Applicable', 'National Occupational Standard', 'N.A.', '{"Theory":"11.5","Practical":"28.5","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "7", "qualification_type": "National Occupational Standard", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-2.5-HC-00756-2023-V1-HCSSC', 'Potter (Kumhar) including tradtional ceramics and terracotta product maker', 'handicrafts-carpets', 'Handicrafts & Carpets', 2.5, '"Traditional ceramics and terracotta product makers are skilled artisans who
craft a diverse array of objects using clay as their primary medium.
Employing age-old techniques, they shape, Mold, and sculpt the clay,
infusing it with cultural and artistic significance. From intricately glazed
pottery and ornate tiles to rustic terracotta planters and figurines, these
craftsmen play a vital role in preserving heritage while producing functional
and aesthetically pleasing pieces that adorn both everyday life and special
occasions."', 40, 40, '1–200', 'Version', '14 Sep 2023', '19 Sep 2023', 'Handicrafts and Carpet Sector Skill Council (HCSSC)', 'Handicrafts and Carpet Sector Skill Council (HCSSC)', 'Production Management-Ceramics', 'Not Applicable', 'National Occupational Standard', 'N.A.', '{"Theory":"11.5","Practical":"28.5","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "8", "qualification_type": "National Occupational Standard", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
