INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-2.5-HC-00588-2023-V2-HCSSC Version: 2.0', 'Cutting and Threading Operator (Metalware)', 'handicrafts-carpets', 'Handicrafts & Carpets', 2.5, 'The job holder typically works in a team and carries out job duties based on job instructions received. The key job responsibility is to accurately measure and cut metal sheets into desired shape and dimensions within agreed timelines. The worker works under supervision. The individual at work is responsible to drill and create screw threads in the metal craft as per specification.', 330, 330, '201–400', 'Version', '25 Jun 2020', '23 Jun 2026', 'Handicrafts and Carpet Sector Skill Council (HCSSC)', 'The job holder typically works in a team and carries out job duties based on job instructions received. The key job responsibility is to accurately measure and cut metal sheets into desired shape and dimensions within agreed timelines.', 'Metal Craft Making', 'Vertical Progression.Embossing Artisan (Metalware).Horizontal Progression. Casting Operator (Metal Handicrafts)', 'Upskilling Qualification', 'N.A.', '{"Theory":"120","Practical":"210","EmployabilitySkills":"00","OJT_Mandatory":"00"}', false, '{}'::text[], '{"source_row": "19", "qualification_type": "Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range