INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-03-HC-02321-2024-V1-HCSSC', 'Advanced Potter (Kumhar) including traditional ceramics and terracotta product maker', 'handicrafts-carpets', 'Handicrafts & Carpets', 3.0, 'Ceramics and Terracotta Crafting introduces fundamental skills for crafting ceramic and terracotta products which involves preparing raw materials using ball mill, filling molds with slip, creating colors, applying engobing mixtures, operating furnaces, uniform glazing using sprays, shaping clay with jigger machines, creating reusable molds, and mixing raw materials for slip. This course equips learners with foundational knowledge and hands-on techniques in ceramics, enabling them to engage in the artistic process and produce functional and ornamental pottery.', 120, 120, '1–200', 'Version', '15 Mar 2024', '15 Mar 2027', 'Handicrafts and Carpet Sector Skill Council (HCSSC)', 'Handicrafts and Carpet sector skill council-HCSSC 
Tel number(s): 011-26139834 
E-mail address: ceo@hcssc.in', 'N/A', 'N/A', 'General Qualification', 'N.A.', '{"Theory":"120","Practical":"00","EmployabilitySkills":"00","OJT_Mandatory":"00"}', false, '{}'::text[], '{"source_row": "69", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-03-HC-02322-2024-V1-HCSSC', 'Sculptor and Stone Artist (Moortikar)- Advance', 'handicrafts-carpets', 'Handicrafts & Carpets', 3.0, 'Sculpting and stone craft is a meticulous art form where skilled artisans transform raw stone into intricate and captivating sculptures. Guided by a blend of artistic vision and technical precision, sculptors, carve, and shape the stone art and ceramics art, breathing life into their creations. Inlay work complements this process, integrating contrasting materials seamlessly into the stone''s surface, adding depth and embellishment, resulting in a harmonious fusion of textures and colours that enrich the sculpted masterpiece.', 120, 120, '1–200', 'Version', '15 Mar 2024', '15 Mar 2027', 'Handicrafts and Carpet Sector Skill Council (HCSSC)', 'Handicrafts and Carpet Sector Skill Council-HCSSC
Tel number(s): 011-26139834
E-mail address: ceo@hcssc.in', 'N/A', 'N/A', 'General Qualification', 'N.A.', '{"Theory":"120","Practical":"00","EmployabilitySkills":"00","OJT_Mandatory":"00"}', false, '{}'::text[], '{"source_row": "70", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
