INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-HC-03289-2024-V2-HCSSC', 'Leather Toy Maker', 'handicrafts-carpets', 'Handicrafts & Carpets', 3.0, 'The Leather Toy Maker selects galvanized wires or iron and mild steel and makes grass and wood strands while using threads along with different synthetic water colors to make the final toy.', 390, 390, '201–400', 'Version', '31 Aug 2021', '22 Oct 2027', 'Handicrafts and Carpet Sector Skill Council (HCSSC)', 'Handicrafts and Carpet Sector Skill Council', 'Finishing and Painting', 'Merchandiser', 'Upskilling Qualification', 'N.A.', '{"Theory":"120","Practical":"230","EmployabilitySkills":"60","OJT_Mandatory":"00"}', false, '{}'::text[], '{"source_row": "91", "qualification_type": "Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-HC-03290-2024-V2-HCSSC', 'Namda craft Artisan', 'handicrafts-carpets', 'Handicrafts & Carpets', 3.0, 'In making a patterned Namda, the craftsmen need to felt in the design into the Namda fibre itself. This involves a dual process of felting. First, a pattern is laid on the grass or jute mat which is then surfaced with wool spread evenly with the help of a broom locally called manzyen. Then the same process of sprinkling soap water and rolling of the mat is again carried out. On untying, it reveals a beautiful Namda
drawn over with colorful patterns.', 390, 390, '201–400', 'Version', '25 Nov 2021', '22 Oct 2027', 'Handicrafts and Carpet Sector Skill Council (HCSSC)', 'Handicrafts and Carpet Sector Skill Council', 'Product Development and Design-Carpets', 'Carpet Quality Checker, Dyer (Rangsaaz) (Carpet)', 'Upskilling Qualification', 'N.A.', '{"Theory":"70","Practical":"290","EmployabilitySkills":"30","OJT_Mandatory":"00"}', false, '{}'::text[], '{"source_row": "92", "qualification_type": "Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-HC-03291-2024-V2-HCSSC', 'Natural Fibre Product Maker', 'handicrafts-carpets', 'Handicrafts & Carpets', 3.0, 'A Natural Fibre Product Maker is responsible for making different products such as grass coasters, mirror frames, bangles, toys, containers, bowls, bags, baskets, mats and other utility items, by using different grasses like palm leaves, sheetal patti, reed, sikki grass, kasi grass, cona, jute kenaf, flax, hemp, sisal and palmyra etc. The Grass Craft Maker shall be able to make different products of different specifications by using different types of grasses. This job requires the individual to have understanding and knowledge of raw materials to be used for making specific products and techniques used for the same.', 360, 360, '201–400', 'Version', '25 Nov 2021', '22 Oct 2027', 'Handicrafts and Carpet Sector Skill Council (HCSSC)', 'Handicrafts and Carpet Sector Skill Council', 'Natural Fibre Maker', 'Merchandiser', 'Upskilling Qualification', 'N.A.', '{"Theory":"110","Practical":"220","EmployabilitySkills":"30","OJT_Mandatory":"00"}', false, '{}'::text[], '{"source_row": "93", "qualification_type": "Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-HC-03292-2024-V2-HCSSC', 'Traditional Painting Maker - Artisan', 'handicrafts-carpets', 'Handicrafts & Carpets', 3.0, 'Traditional Painting Maker - Artisan creates various types of paintings on different types of canvas by hand, using different types of raw material, colours, tools, drying methods, etc.', 390, 3510, 'Above 2401', 'Version', '25 Nov 2021', '22 Oct 2027', 'Handicrafts and Carpet Sector Skill Council (HCSSC)', 'Handicrafts and Carpet Sector Skill Council', 'Traditional Painting', 'Merchandiser', 'Upskilling Qualification', 'N.A.', '{"Theory":"120","Practical":"240","EmployabilitySkills":"30","OJT_Mandatory":"00"}', false, '{}'::text[], '{"source_row": "94", "qualification_type": "Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-2.5-HC-03530-2025-V1-WBSC', 'Mat Maker', 'handicrafts-carpets', 'Handicrafts & Carpets', 2.5, 'Mat Maker is responsible for crafting high-quality mats using various materials such as fabric, Korai Grass. The candidate will possess expertise in cutting, shaping and assembling materials to create aesthetically pleasing and durable mats on handloom for various purposes including decoration, utility and artistic expression.', 300, 300, '201–400', 'Version', '18 Feb 2025', '17 Feb 2028', 'West Bengal State Council of Technical & Vocational Education and Skill Development (WBSCTVESD)', 'West Bengal State Council of Technical & Vocational Education and Skill Development', 'Mat Maker', 'Vertical Progression:
Creative Mat Weaver', 'General Qualification', 'N.A.', '{"Theory":"70","Practical":"140","EmployabilitySkills":"30","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "95", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
