INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-HE-01989-2024-V2-HSSC', 'Frontline Health Caregiving Assistant  (Elective 1: Home Care, Elective 2: General Hospital Care, Elective 3: Critical Hospital Care)', 'healthcare', 'Healthcare', 3.0, 'Individual in this job provides care to the patient in different settings like Home and Hospital. Their work involves working with basic equipment like Oxygen Concentrator, Oxygen Cylinder, Nebulizer, steam inhalation and Pulse-oximeter. They are also responsible to maintain records manually or digitally as per protocols.', 300, 570, '401–600', 'Version', '31 Jan 2024', '31 Jan 2027', 'Healthcare Sector Skill Council (HSSC)', 'Healthcare Sector Skill Council', 'Patient Care Services', 'Vertical Progression:
