INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-4.5-HE-01828-2024-V1-HSSC', 'India Skills- National (Health & Social Care)', 'healthcare', 'Healthcare', 4.5, 'A health and social care personnel offers a range of support to individual clients and their family and has a continuing responsibility to work professionally and interactively with the client in order to ensure their holistic care needs are met. The health and social care personnel works in diverse environments, including the homes of clients, hospitals, community day care, and residential and nursing homes. He or she manages health, physical, and psychosocial well-being, support of growth and development, caring and rehabilitation.', 510, 510, '401–600', 'Version', '06 Feb 2024', '06 Feb 2026', 'Healthcare Sector Skill Council (HSSC)', 'Healthcare Sector Skill Council', 'Health & Social Care', 'N/A', 'Multi-Skill Qualification', 'N.A.', '{"Theory":"180","Practical":"330","EmployabilitySkills":"00","OJT_Mandatory":"00"}', false, '{}'::text[], '{"source_row": "38", "qualification_type": "Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
