INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-01-HE-03299-2024-V1-HSSC', 'Basics of POSHAK (Poshan Shiksha and Kaushal) for Anganwadi Sahayika', 'healthcare', 'Healthcare', 1.0, 'The Anganwadi Sahayika provides crucial support to the Anganwadi Karyakarta in delivering health, nutrition, and early childhood development services to the community. They assist in organizing activities such as health check-ups, nutrition distribution, and cooking nutritious meals. Additionally, they help in maintaining records, preparing meals, and keeping the Anganwadi center clean and hygienic. Their presence is essential for ensuring the smooth functioning of the center and effective service delivery to beneficiaries.', 15, 15, '1–200', 'Version', '22 Oct 2024', '22 Oct 2027', 'Healthcare Sector Skill Council (HSSC)', 'Healthcare Sector Skill Council', 'Early Child Development', 'Not Applicable', 'Micro Credentials', 'N.A.', '{"Theory":"6","Practical":"9","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "45", "qualification_type": "Micro Credentials", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-02-HE-03298-2024-V1-HSSC', 'Fundamentals of POSHAK- (Poshan Shiksha and Kaushal) for Anganwadi Karyakarta', 'healthcare', 'Healthcare', 2.0, 'The Anganwadi Karyakarta coordinates for health and nutrition education sessions, distributes supplementary nutrition, monitor growth and development of children, and facilitate linkages with healthcare services.', 30, 30, '1–200', 'Version', '22 Oct 2024', '22 Oct 2027', 'Healthcare Sector Skill Council (HSSC)', 'Healthcare Sector Skill Council', 'Early Child Development', 'Not Applicable', 'Micro Credentials', 'N.A.', '{"Theory":"12","Practical":"18","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "46", "qualification_type": "Micro Credentials", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-HE-03297-2024-V1-HSSC', 'Fundamentals of POSHAK (Poshan Shiksha and Kaushal) for Anganwadi Paryavekshika', 'healthcare', 'Healthcare', 3.0, 'The Anganwadi Paryavekshika of Integrated Child Development Services (ICDS) oversees the implementation of various welfare programs aimed at health nutrition across various beneficiaries across her allocated area. She coordinates with Anganwadi Karyakarta , monitors their activities, and ensures the effective delivery of services to the community. Additionally, she plays a pivotal role in assessing the nutritional needs of beneficiaries, understanding problems, taking corrective actions, organizing health camps, and promoting maternal and child health awareness.', 45, 45, '1–200', 'Version', '22 Oct 2024', '22 Oct 2027', 'Healthcare Sector Skill Council (HSSC)', 'Healthcare Sector Skill Council', 'Early Child Development', 'Not Applicable', 'National Occupational Standard', 'N.A.', '{"Theory":"18","Practical":"27","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "47", "qualification_type": "National Occupational Standard", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-HE-03296-2024-V2-HSSC', 'Dresser (Medical)', 'healthcare', 'Healthcare', 3.0, 'A Dresser’s (Medical) main job is to perform dressing of patients, and its related activities as instructed by healthcare professional. The person also maintains the set-up under supervision.', 900, 900, '801–1000', 'Version', '31 Aug 2021', '22 Oct 2027', 'Healthcare Sector Skill Council (HSSC)', 'Healthcare Sector Skill Council', 'Curative Services', 'Vertical Mobility after some years of experience:
Level 3.5: General Duty Assistant- Advanced', 'Apprenticeship Qualification,General Qualification', 'N.A.', '{"Theory":"300","Practical":"300","EmployabilitySkills":"30","OJT_Mandatory":"270"}', false, '{}'::text[], '{"source_row": "48", "qualification_type": "Apprenticeship Qualification,General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-5.5-HE-03258-2024-V1-IGNOU', 'Nurse Manager', 'healthcare', 'Healthcare', 5.5, 'After completing the Qualification pack participants will be able to:
Apply the management principles and elements of management in day-to-day supervision and management of nursing services in clinical and non-clinical areas, public health units, and education institutions. Will collaborate with support services and departments to provide various ancillary and support services for smooth functioning of ward/department. Participate in selection, recruitment, supervision, training of nursing officers, Plan organise staff development activities and participate as team member in various committees. Nurse manager will be able to manage resources and indent in ward. Participate in quality assurance activities, nursing audit, NABH activities and take care of patient safety issues. As accreditation is very crucial and nursing services are crucial part of hospital nurse manager will learn about nursing excellence standards and implement in hospital.

Nurse Manager Job Role QP is essential because responsibilities of nurses are increasing over time and nurse manager needs to be involved in decision making, planning, establishing procedures, be a team member for quality assurance, accreditation and involved in patient safety. This is supported by various studies, national and international reports. Therefore Nurse Manager QP is designed and developed which will enhance managerial skills of nurse managers at national and international level.', 600, 600, '401–600', 'Version', '22 Oct 2024', '22 Oct 2027', 'Indira Gandhi National Open University (IGNOU)', 'Indira Gandhi National Open University (IGNOU)', 'Nurse Manager', 'Nurse Manager - Senior Nurse Manager, Nurse Manager - Senior Public Health Nurse', 'General Qualification', 'N.A.', '{"Theory":"180","Practical":"180","EmployabilitySkills":"60","OJT_Mandatory":"180"}', false, '{}'::text[], '{"source_row": "49", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-HE-03294-2024-V2-HSSC', 'Yoga Wellness Trainer', 'healthcare', 'Healthcare', 4.0, 'Yoga Wellness Trainers lead yoga classes, teach yoga postures, and provide guidance to clients. They create lesson plans, customise practices based on learner''s needs, and ensure proper form and alignment to prevent injuries.', 450, 450, '401–600', 'Version', '24 Jun 2021', '22 Oct 2027', 'Healthcare Sector Skill Council (HSSC)', 'Healthcare Sector Skill Council', 'Yoga', 'Panchakarma Technician (Level 4), Yoga Wellness Specialist (Level 5)', 'Apprenticeship Qualification,Cross Sectoral Qualification,General Qualification', 'N.A.', '{"Theory":"120","Practical":"210","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "50", "qualification_type": "Apprenticeship Qualification,Cross Sectoral Qualification,General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-HE-03293-2024-V1-HSSC', 'Varmam-Marma Therapy Assistant', 'healthcare', 'Healthcare', 3.0, 'The role is to assist in preparing for the Varmam Marma therapy sessions( ancient healing system by stimulating vital energy point in the body ). They work under the supervision of a Ayurveda or Siddha Graduates preparing all required materials such as oils, herbal mixtures, and other therapeutic tools before each session', 480, 480, '401–600', 'Version', '22 Oct 2024', '22 Oct 2027', 'Healthcare Sector Skill Council (HSSC)', 'Healthcare Sector Skill Council', 'Ayurveda and Siddha Therapy', 'Yoga Wellness Trainer (Level 4), Naturopathy Assistant (Level 3)', 'Apprenticeship Qualification,General Qualification', 'N.A.', '{"Theory":"120","Practical":"180","EmployabilitySkills":"30","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "51", "qualification_type": "Apprenticeship Qualification,General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-HE-03295-2024-V2-HSSC', 'KsharaKarma Technician', 'healthcare', 'Healthcare', 4.0, 'They help prepare Kshara and other essential materials for the procedure, ensuring that all tools and equipment used in Ksharakarma are properly cleaned and sterilised. They also support Ayurvedic surgeons before, during, and after Ksharakarma procedures to ensure smooth and efficient care for patients.', 1200, 1200, '1001–1200', 'Version', '20 Nov 2020', '22 Oct 2027', 'Healthcare Sector Skill Council (HSSC)', 'Healthcare Sector Skill Council', 'Ayurveda Therapy', 'Patient Relations Associate', 'Apprenticeship Qualification,General Qualification', 'N.A.', '{"Theory":"390","Practical":"600","EmployabilitySkills":"60","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "52", "qualification_type": "Apprenticeship Qualification,General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-4.5-HC-03366-2024-V1-IGNOU', 'Executive - Emergency Healthcare', 'healthcare', 'Healthcare', 4.5, 'The programme will benefit those who wish to learn first aid as per their interest and also for those who want to pursue careers in which first aid training and certification is necessary for recruitment like assistants and aides working in Nursing homes, mobile Ambulances, industries, constructions sites, schools, sports or water sport coaches, Drivers, Conductors, Fire Marshals, Traffic Police, Army personnel’s, teachers in schools, flight cabin crew members and air-hostesses etc and for those whose organizations have made it mandatory for their workers to undergo first aid training.

Further the programme will be useful to those who are working in various capacities in the jobs where these competencies would be useful. Some examples are e.g. Nursing homes (as assistants/Aides), Drivers/ Conductors, Fire Marshals/Fire Stations, Traffic Police/Army personnel’s, Sports and Physical
Education, Teachers etc.
Proposed  Executive - Emergency Healthcare programme of IGNOU is at 4.5 level and has additional and advanced knowledge and skills required during handling the emergency care like disaster management(Triage), epidemics & pandemic and Psychosocial first aid for victims and their family members and hence has been named as Executive - Emergency Healthcare.', 1080, 1080, '1001–1200', 'Version', '22 Oct 2024', '21 Oct 2027', 'Indira Gandhi National Open University (IGNOU)', 'IGNOU', 'Emergency Care Assistant- Advance', 'Emergency Medical Technician - Advance', 'Future Skills Qualification,General Qualification', 'N.A.', '{"Theory":"240","Practical":"360","EmployabilitySkills":"60","OJT_Mandatory":"420"}', false, '{}'::text[], '{"source_row": "53", "qualification_type": "Future Skills Qualification,General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-HE-03368-2024-V1-SSU', 'Yuva Yogacharya', 'healthcare', 'Healthcare', 5.0, 'The Yuva Yogacharya qualification is a specialised program designed to integrate the practical aspects of yoga, ayurveda, counselling and Business acumen with the teachings of Gurudev Sri Sri Ravishankar ji, founder of the Art of Living Foundation. This program emphasizes a holistic approach to yoga, combining traditional practices with contemporary insights to promote overall well-being and spiritual growth. This qualification prepares individuals to become proficient in practicing and teaching yoga, following the principles laid out by the Art of Living Foundation. This includes understanding yoga''s physical, mental, and spiritual dimensions and Ayurvedic lifestyle and applying these principles to improve personal and communal health. 
A Yuva Yogacharya is a master yoga practitioner and teacher who guides individuals through various yoga practices, including asanas (postures), pranayama (breathing techniques), meditation and relaxation techniques, and Ayurveda and counselling techniques. They are knowledgeable in the philosophy of yoga, Ayurveda, and Healing and capable of creating tailored programs to suit the needs of diverse groups', 570, 570, '401–600', 'Version', '23 Aug 2024', '23 Aug 2027', 'Sri Sri University', 'SRI SRI UNIVERSITY', 'Yoga & Wellness  Trainer/Coach', 'Yuva Yogacharya, Wellness Coach Holistic Health Consultant, Wellness Retreat Coordinator, 
Corporate Wellness Consultant, Author/Content Creator Researcher', 'General Qualification,Multi-Skill Qualification,National Occupational Standard,Upskilling Qualification', 'N.A.', '{"Theory":"250","Practical":"215","EmployabilitySkills":"60","OJT_Mandatory":"105"}', false, '{}'::text[], '{"source_row": "54", "qualification_type": "General Qualification,Multi-Skill Qualification,National Occupational Standard,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-HE-03461-2025-V1-ASAP', 'Ayurveda Therapist', 'healthcare', 'Healthcare', 4.0, 'Ayurvedic Therapists use their expertise in lifestyle intervention and natural Ayurveda therapies to guide clients on ways to prevent ailments and promote health, anti-aging and healing of body and soul. They specialize in understanding and guiding on the basic Ayurveda principles, working of yoga, medication, food and nutrition, rejuvenation therapies, Panchakarma, among others.', 1200, 1200, '1001–1200', 'Version', '27 Jan 2025', '26 Jan 2028', 'Additional Skill Acquisition Programme, Government of Kerala', 'Additional Skill Acquisition Programme, Government of Kerala', 'Ayurveda Therapist Trainee/ Ayurveda Therapist', 'Ayurveda Therapist Trainee -->Casual Therapist -->Temporary Therapist -->Therapist – Probationer       -->Therapist (LD Grade) -->Therapist (UD Grade) -->Therapist (Section Head Grade) -->Therapist (Sr. Section Head Grade)', 'General Qualification', 'N.A.', '{"Theory":"300","Practical":"360","EmployabilitySkills":"90","OJT_Mandatory":"450"}', false, '{}'::text[], '{"source_row": "55", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-2.5-HE-03460-2025-V2-HSSC', 'Yoga Training Assistant', 'healthcare', 'Healthcare', 2.5, 'Yoga Training Assistant play a supportive role and assist the trainer during yoga session by demonstrating poses, assisting learners with adjustments, offering support during group activities, and ensuring the smooth running of the session', 270, 270, '201–400', 'Version', '24 Jun 2021', '24 Feb 2028', 'Healthcare Sector Skill Council (HSSC)', 'Healthcare Sector Skill Council', 'Yoga', 'Naturopathy Assistant (Level 3_', 'Apprenticeship Qualification,General Qualification', 'N.A.', '{"Theory":"60","Practical":"120","EmployabilitySkills":"30","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "56", "qualification_type": "Apprenticeship Qualification,General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
