INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-02-HE-03753-2025-V1-HSSC', 'Fundamental of Occupational Health and Hygiene', 'healthcare', 'Healthcare', 2.0, 'Individuals in this role will be trained to perform and adhere to basic health standards and workplace safety protocols, including WASH practices, hygiene, personal cleanliness, and food safety. The individual will also be able to comply with safety norms for self and others by identifying occupational health hazards, following preventive measures, and applying first aid skills when necessary.', 45, 45, '1–200', 'Version', '18 Feb 2025', '18 Feb 2028', 'Healthcare Sector Skill Council (HSSC)', 'Healthcare Sector Skill Council', 'Environmental & Occupational Health', 'Not Applicable', 'Cross Sectoral Qualification,General Qualification,National Occupational Standard,Upskilling Qualification', 'N.A.', '{"Theory":"21","Practical":"24","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "58", "qualification_type": "Cross Sectoral Qualification,General Qualification,National Occupational Standard,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-HE-03623-2025-V1-HSSC', 'Health and wellness coach', 'healthcare', 'Healthcare', 5.0, 'Health and wellness coaches are the professionals who are trained to coach the client to adopt and adhere to a healthy lifestyle for the promotion of their well-being by identifying risk factors of select chronic diseases, applying biometric findings and suggesting lifestyle recommendations for optimizing health. These professionals follow the prescription/medical advice from a licensed physician or healthcare specialist and work under the limits of competence and authority to coach the client. These professionals do not diagnose or prescribe any medical intervention.', 540, 540, '401–600', 'Version', '18 Feb 2025', '18 Feb 2028', 'Healthcare Sector Skill Council (HSSC)', 'Healthcare Sector Skill Council', 'Social Work & Community Health', 'Not Applicable', 'Cross Sectoral Qualification,Future Skills Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"90","Practical":"120","EmployabilitySkills":"60","OJT_Mandatory":"270"}', false, '{}'::text[], '{"source_row": "59", "qualification_type": "Cross Sectoral Qualification,Future Skills Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-HE-03620-2025-V2-HSSC', 'Garbhini Mitra', 'healthcare', 'Healthcare', 3.0, 'The individual on this job assists the Prasooti Tantra and Stree roga expert from pre-conceptional to post-natal care of the mothers. They also help in performing basic clerical functions including storekeeping and record maintenance of the day-to-day activities under the guidance of the expert.', 360, 360, '201–400', 'Version', '31 Mar 2022', '18 Feb 2028', 'Healthcare Sector Skill Council (HSSC)', 'Healthcare Sector Skill Council', 'Ayurveda Allied', 'NSQF Level 4: Panchakarma Technician, Kshara Karma Technician', 'General Qualification', 'N.A.', '{"Theory":"90","Practical":"120","EmployabilitySkills":"30","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "60", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
