NSQF Level 4: General Duty Assistant Trainee', 'Apprenticeship Qualification,General Qualification', 'N.A.', '{"Theory":"210","Practical":"180","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "65", "qualification_type": "Apprenticeship Qualification,General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
