INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-6.5-HE-04217-2025-V2-HSSC', 'Genetic Counsellor', 'healthcare', 'Healthcare', 6.5, 'The individual is responsible for obtaining clinical, family and health information, advising individuals/families about their risk of inheriting genetic diseases, informing testing options for diagnosis and providing available options to prevent/ treat genetic conditions. They also focus on empowering their patients by helping them understand and adjust to the genetic conditions. Individuals would keep oneself abreast of the latest technologies and future opportunities of broadening the scope of work in context of recent advancements in human genomics and genetic counselling. They should be able to apply genomics in different medical specialties, personalized/precision medicine and disease research.', 1200, 1200, '1001–1200', 'Version', '08 May 2025', '08 May 2028', 'Healthcare Sector Skill Council (HSSC)', 'Healthcare sector skill council', 'Counselling', 'Progression to Diploma/Degree qualifications in the relevant field after training. (NCAHP)', 'Future Skills Qualification', 'N.A.', '{"Theory":"390","Practical":"420","EmployabilitySkills":"90","OJT_Mandatory":"300"}', false, '{}'::text[], '{"source_row": "94", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-HE-04227-2025-V2-HSSC', 'Geriatric Caregiver (Institutional & Homecare)', 'healthcare', 'Healthcare', 4.0, 'Individuals at this job need to provide companionship and compassionate care to Geriatric at various work settings including Home Care set up, community care set-up and assisted living facilities. These professionals act as a companion to Geriatrics and help in maintaining daily living activities, rehabilitation, coping up with ill health condition, supporting in achieving healthcare goals, managing finances, transportation, and other tasks to help the elderly maintain independence and quality of life. Individuals would keep oneself abreast of use of the Recent advancements and applications. They should be able to adapt with changes in individualized care plan for geriatric patients suffering from Alzheimer’s and Dementia.', 450, 660, '601–800', 'Version', '08 May 2025', '08 May 2028', 'Healthcare Sector Skill Council (HSSC)', 'Healthcare sector skill council', 'Special Care Services', 'Vertical Mobility NSQF Level 4.5: 
Geriatric Care Assistant
General Duty Assistant-Advanced', 'Apprenticeship Qualification,Future Skills Qualification,National Occupational Standard', 'N.A.', '{"Theory":"150","Practical":"150","EmployabilitySkills":"30","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "95", "qualification_type": "Apprenticeship Qualification,Future Skills Qualification,National Occupational Standard", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-06-HE-04224-2025-V2-HSSC', 'Duty Manager (Patient Relation Services)', 'healthcare', 'Healthcare', 6.0, 'The individual at this job are involved in planning, organizing, directing and controlling Inpatient & outpatient services. They also collaborate with other department to design, develop and implement process & services of the center. They should be able to adapt with new advancements/software/apps in hospital management systems. Individuals would  keep oneself abreast with with revision of hospital biiling structure, government schemes and policies related to TPA and insurance services.', 600, 600, '401–600', 'Version', '08 May 2025', '08 May 2028', 'Healthcare Sector Skill Council (HSSC)', 'Healthcare sector skill council', 'Healthcare Administration', 'Vertical Mobility
NSQF Level 7: Hospital Administrator (to be developed)', 'Apprenticeship Qualification,General Qualification,National Occupational Standard', 'N.A.', '{"Theory":"270","Practical":"150","EmployabilitySkills":"90","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "96", "qualification_type": "Apprenticeship Qualification,General Qualification,National Occupational Standard", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-5.5-HE-04223-2025-V2-HSSC', 'Deputy Duty Manager (Patient Relation Services)', 'healthcare', 'Healthcare', 5.5, 'The individual at this job maintains a professional work environment in hospital settings by rendering knowledge and skills of team supervision, administrative support, supervisory support, office harmony, crisis handling, office morale, customer service. They assist for planning, implementing and monitoring daily activities of  Inpatient & outpatient services. They should be able to adapt with new advances/software/apps in hospital management systems. Individuals would keep oneself abreast with revision of hospital billing structure, government schemes and policies related to TPA and insurance services.', 600, 600, '401–600', 'Version', '08 May 2025', '08 May 2028', 'Healthcare Sector Skill Council (HSSC)', 'Healthcare sector skill council', 'Healthcare Administration', 'NSQF Level 6: Duty Manager (Patient relation Services) , Healthcare Quality Assurance Manager', 'Apprenticeship Qualification,General Qualification,National Occupational Standard', 'N.A.', '{"Theory":"270","Practical":"150","EmployabilitySkills":"90","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "97", "qualification_type": "Apprenticeship Qualification,General Qualification,National Occupational Standard", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-HE-04228-2025-V2-HSSC', 'Ayurveda Ahara and Poshana Sahayak', 'healthcare', 'Healthcare', 3.0, 'An Ayurveda Ahara & Poshana Sahayak (Ayurveda Diet & Nutrition Assistant) works under the supervision of an Ayurveda Dietician and coordinates with the Ayurveda cook for food preparation as per Ayurvedic principles. They also help Ayurveda Dietician in performing basic clerical functions including storekeeping and record maintenance at workplace', 420, 420, '401–600', 'Version', '17 Nov 2022', '08 May 2028', 'Healthcare Sector Skill Council (HSSC)', 'Healthcare Sector Skill Council', 'Ayurveda Diet', 'Level 4: Yoga Therapy Assistant', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"120","Practical":"150","EmployabilitySkills":"30","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "98", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-06-HE-04229-2025-V2-HSSC', 'Ayurveda Dietician', 'healthcare', 'Healthcare', 6.0, 'An Ayurveda Dietician prepares a diet plan that provides guidelines about when to eat, what to eat, and how to boost health, prevent or manage disease, and maintain wellness. The primary role is to assess nutritional needs and prescribe an ayurvedic diet plan for the client (healthy individual as well as for diseased person). They also supervise and instruct related professionals in preparation of therapeutic or other diets in hospitals, institutions or other establishments', 570, 570, '401–600', 'Version', '20 Nov 2020', '08 May 2028', 'Healthcare Sector Skill Council (HSSC)', 'Healthcare Sector Skill Council', 'Ayurveda Diet', 'Not Applicable', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"150","Practical":"300","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "99", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-HE-04230-2025-V2-HSSC', 'Cupping Therapy Assistant', 'healthcare', 'Healthcare', 3.0, 'A Cupping Therapy Assistant is an allied healthcare professional who assists an AYUSH practitioner in carrying out dry and wet cupping therapy which is creating suction by placing heated cups on skin by hand.', 420, 420, '401–600', 'Version', '20 Nov 2020', '08 May 2028', 'Healthcare Sector Skill Council (HSSC)', 'Healthcare Sector Skill Council', 'Unani Therapy', 'Not Applicable', 'Apprenticeship Qualification,General Qualification', 'N.A.', '{"Theory":"120","Practical":"150","EmployabilitySkills":"30","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "100", "qualification_type": "Apprenticeship Qualification,General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-4.5-HE-00649-2025-V2-HSSC', 'Panchakarma Technician', 'healthcare', 'Healthcare', 4.5, 'The individuals in this job provide panchakarma therapy as per the prescription by creating appropriate and conducive ambience, and ensuring the availability of required materials, herbs and related formulations. These professionals provide support to individuals before, during and after therapy. They also perform basic administrative functions, including record maintenance of daily activities at work place', 1200, 1200, '1001–1200', 'Version', '28 Jul 2022', '08 May 2028', 'Healthcare Sector Skill Council (HSSC)', 'Healthcare Sector Skill Council', 'Ayurveda Therapy', 'Vertical Progression: Patient Relation Associate (Level 5)', 'Apprenticeship Qualification,General Qualification', 'N.A.', '{"Theory":"390","Practical":"600","EmployabilitySkills":"60","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "101", "qualification_type": "Apprenticeship Qualification,General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-HE-04232-2025-V2-HSSC', 'Yoga Therapy Assistant', 'healthcare', 'Healthcare', 4.0, 'Health care professionals who demonstrate and assist to provide yoga therapies to the individuals by making appropriate and conducive ambience, based on the prescriptions, providing support to patient before, during and', 690, 690, '601–800', 'Version', '28 Jul 2022', '08 May 2028', 'Healthcare Sector Skill Council (HSSC)', 'Healthcare Sector Skill Council', 'Yoga', 'Horizontal Progression: Level 4: Yoga Wellness Trainer 
Vertical Progression: Level 5: Patient Relation Associate', 'Apprenticeship Qualification,General Qualification', 'N.A.', '{"Theory":"240","Practical":"210","EmployabilitySkills":"60","OJT_Mandatory":"180"}', false, '{}'::text[], '{"source_row": "102", "qualification_type": "Apprenticeship Qualification,General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-HE-04222-2025-V2-HSSC', 'Patient Relations Associate', 'healthcare', 'Healthcare', 5.0, 'Individuals in this job are responsible for assisting and supporting patients & visitors as per their needs, managing inquiries, resolving issues and ensuring a positive patient experience without giving any opinions / assurances on clinical matters. They also handle consultant/department specific administrative tasks in a healthcare setup including maintaining electronic health records, coordinating online/offline consultations and  supervising hospital front desk activities. They should be able to adapt with new advancements/software/apps in 	Customer Relationship Management (CRM). Individuals would  keep oneself abreast with with revision of hospital biiling structure, government schemes and policies related to TPA and insurance services.', 540, 540, '401–600', 'Version', '08 May 2025', '08 May 2027', 'Healthcare Sector Skill Council (HSSC)', 'Healthcare sector skill council', 'Healthcare Administration', 'Vertical Mobility
NSQF Level 5.5: Deputy Duty Manager (Patient relation Services)', 'Apprenticeship Qualification,General Qualification', 'N.A.', '{"Theory":"180","Practical":"150","EmployabilitySkills":"60","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "103", "qualification_type": "Apprenticeship Qualification,General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-HE-04218-2025-V2-HSSC', 'Telehealth Services Coordinator', 'healthcare', 'Healthcare', 4.0, 'Telehealth Services Coordinator serves as point-of-contact for telehealth services at either referral/patient/primary health care provider''s site or specialty/consultation/secondary/tertiary healthcare provider''s site. They support physicians, patients and other providers in using widespread e-Health services. Their key responsibilities include organizing teleconference, scheduling appointments, setting up telehealth equipment as needed, maintaining inventory, billing, database management with proper
documentation and promoting telehealth services in local community especially in locations where there is limited access to healthcare providers.', 480, 480, '401–600', 'Version', '08 May 2025', '08 May 2028', 'Healthcare Sector Skill Council (HSSC)', 'Healthcare sector skill council', 'Healthcare Technologies', 'Horizontal Mobility: NSQF Level 4: Hospital Front Desk Coordinator
Vertical Mobility
NSQF Level 5: Patient Relation Associate', 'Apprenticeship Qualification,General Qualification', 'N.A.', '{"Theory":"180","Practical":"225","EmployabilitySkills":"30","OJT_Mandatory":"45"}', false, '{}'::text[], '{"source_row": "104", "qualification_type": "Apprenticeship Qualification,General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-4.5-HE-04226-2025-V2-HSSC', 'Geriatric Care Assistant (Hospital/Hospice Care)', 'healthcare', 'Healthcare', 4.5, 'The individual would provide routine individualized care to geriatrics at various work settings including hospitals, hospices, nursing homes, assisted living facilities, home set up, community centers. They assist geriatrics in maintaining activities of daily living, mobility, monitoring vital signs and assisting with medication reminders. They work under supervision of healthcare team to implement the special care plan for geriatric patients suffering from chronic diseases or disorders (including Dementia, Parkinson''s disease, Alzheimer’s, Diabetes, Hypertension, fractures, Arthritis, Osteoporosis, Respiratory Disease, Heart Disease and Implants, Nervous Disorders, Loss of Vision and Hearing, Cancer, Paralysis, Stroke, etc. )
Individuals would keep oneself abreast of use of the Recent advancements and applications.', 600, 600, '401–600', 'Version', '08 May 2025', '08 May 2028', 'Healthcare Sector Skill Council (HSSC)', 'Healthcare sector skill council', 'Special Care Services', 'Vertical Mobility
NSQF Level 5: Patient Relations Associate', 'Apprenticeship Qualification,Future Skills Qualification', 'N.A.', '{"Theory":"210","Practical":"180","EmployabilitySkills":"60","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "105", "qualification_type": "Apprenticeship Qualification,Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-HE-04221-2025-V2-HSSC', 'Hospital Front Desk Coordinator', 'healthcare', 'Healthcare', 4.0, 'Individuals in this job are usually the first contact point in healthcare organizations encountered by
patients and visitors, whether on the phone, online or in person. They assist in billing, scheduling appointments, entering data in hospital information system (HIS) and performing Front Desk/Help Desk activities at Healthcare Facility. They should be able to adapt with new advancements/software/apps in rendering front-office/billing activities. Individuals would perform the billing activities by keeping oneself abreast with revision of hospital billing structure, government schemes and policies related to TPA and insurance services.', 600, 600, '401–600', 'Version', '08 May 2025', '08 May 2028', 'Healthcare Sector Skill Council (HSSC)', 'Healthcare sector skill council', 'Healthcare Administration', 'Vertical Mobility
NSQF Level 5: Patient Relation Associate', 'Apprenticeship Qualification,General Qualification', 'N.A.', '{"Theory":"240","Practical":"150","EmployabilitySkills":"30","OJT_Mandatory":"180"}', false, '{}'::text[], '{"source_row": "106", "qualification_type": "Apprenticeship Qualification,General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-4.5-HE-04219-2025-V2-HSSC', 'General Duty Assistant- Advanced (Elective 1: Critical Care Elective 2: Dialysis Elective 3: Peri-natal care Elective 4: Peri-operative care)', 'healthcare', 'Healthcare', 4.5, 'Individuals on the job provide patient care and help to maintain a conducive environment of various
departments of hospital/home setting. Some of the key responsibilities include maintaining activities of
patients daily living, patients’ comfort, safety and health needs. They monitor or report changes in health
status. This job requires the individual to work in collaboration with doctors and nurses and other healthcare providers and deliver the healthcare services as suggested by them at a hospital or home setting in shifts. Individuals could perform specialized department-wise patient care activities by rendering sound knowledge of type of patients of the specific department.', 1020, 1200, '1001–1200', 'Version', '08 May 2025', '08 May 2028', 'Healthcare Sector Skill Council (HSSC)', 'Healthcare Sector Skill Council', 'Patient Care Services', 'Vertical Mobility
NSQF Level 5: Patient Relation Associate', 'Apprenticeship Qualification,General Qualification', 'N.A.', '{"Theory":"300","Practical":"360","EmployabilitySkills":"60","OJT_Mandatory":"300"}', false, '{}'::text[], '{"source_row": "107", "qualification_type": "Apprenticeship Qualification,General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-4.5-HE-04220-2025-V2-HSSC', 'Central Sterile Service Department (CSSD) Assistant', 'healthcare', 'Healthcare', 4.5, 'The individual at this job are responsible for functions of decontamination, assembly and sterile processing, sterile storage and distribution. They direct personnel of department for sterilization, cleaning and disinfection process. They should be able to adapt with application of automation or robotics in sterilization systems, storage/retrival system and other tasks. Individuals would  keep oneself abreast with advancement in sterilization techniques, software solutions and electronic documentation.', 1200, 1200, '1001–1200', 'Version', '08 May 2025', '08 May 2028', 'Healthcare Sector Skill Council (HSSC)', 'Healthcare sector skill council', 'Non-Direct Care', 'NSQF Level 5: Patient Relation Associate', 'Apprenticeship Qualification,General Qualification', 'N.A.', '{"Theory":"330","Practical":"660","EmployabilitySkills":"60","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "108", "qualification_type": "Apprenticeship Qualification,General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-06-HE-04225-2025-V2-HSSC', 'Healthcare Quality Assurance Manager', 'healthcare', 'Healthcare', 6.0, 'The individual’s main job is to ensure that healthcare organization gets the right guidance to implement quality accreditation/ certification standards and healthcare personnel are guided to follow quality parameters at all times. They should be able to adapt with integration of real-time reporting and advanced data analytics tools/methodolgies in evidence-based healthcare quality management.', 570, 570, '401–600', 'Version', '08 May 2025', '08 May 2028', 'Healthcare Sector Skill Council (HSSC)', 'Healthcare sector skill council', 'Healthcare Quality Management', 'Vertical Mobility:
NSQF Level 4: General Duty Assistant Trainee', 'Apprenticeship Qualification,General Qualification', 'N.A.', '{"Theory":"240","Practical":"150","EmployabilitySkills":"90","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "109", "qualification_type": "Apprenticeship Qualification,General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-04-HE-03760-2025-V1-HSSC', 'Urology equipment and devices services', 'healthcare', 'Healthcare', 4.0, 'This is an upskilling course to prepare individuals with skills to install, set-up, repair, maintain, calibrate and provide biomedical instrumentation Services for urology equipment and devices. They would also be able to provide post-installation instructions to hospital/facility staff along with management of inventory, documentation and supply chain.', 90, 90, '1–200', 'Version', '18 Feb 2025', '18 Feb 2028', 'Healthcare Sector Skill Council (HSSC)', 'Healthcare sector skill council', 'Non-Direct Care', 'N/A', 'Future Skills Qualification,National Occupational Standard,Upskilling Qualification', 'N.A.', '{"Theory":"30","Practical":"30","EmployabilitySkills":"0","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "110", "qualification_type": "Future Skills Qualification,National Occupational Standard,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-HE-03507-2025-V1-NISD', 'Geriatric Care Provider', 'healthcare', 'Healthcare', 4.0, 'This program aims to develop Geriatric Care Providers dedicated to providing high quality care and support to senior citizens.  It offers comprehensive, evidence-based training in geriatric care, equipping caregivers with sub-nursing skills,taking care of an older person who has a chronic illness or disease, elderly in doing their activities of daily living and to fulfill local requirements like shopping, going for physiotherapy, Helping in medications or talking to doctors and nurses on behalf of client/patient, Helping to bathe or dress someone who is frail or disabled; or taking care of household work, meals, or bills for someone who cannot do these things alone (Including taking the elderly to the park/bank on wheel chair) and a deep understanding of the critical role empathy plays in caregiving. 
Additionally, the course emphasizes the importance of self-care to ensure the well-being of caregivers themselves. With a strong focus on practical skills, the training prepares caregivers to deliver effective interventions in family and community settings, promoting the welfare and quality of life of older adults.Building Geriatric Caregivers as Digital Health Assistance', 480, 480, '401–600', 'Version', '18 Feb 2025', '17 Feb 2028', 'National Institute of Social Defence (NISD)', 'National Institute of Social Defence', 'Geriatric Caregiver', 'Geriatric Care Supervisor', 'General Qualification', 'N.A.', '{"Theory":"147","Practical":"165","EmployabilitySkills":"30","OJT_Mandatory":"138"}', false, '{}'::text[], '{"source_row": "111", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-06-HE-00666-2025-V2-HSSC', 'Transplant Coordinator', 'healthcare', 'Healthcare', 6.0, 'The individual would undertake grief counselling of family members of the deceased. They also coordinate live and deceased organ and tissue donation, retrieval, storage, transport for transplantation and engages in organ donation awareness related initiatives. Individuals would keep oneself abreast of the latest technologies and future opportunities of broadening the scope of work in context of emerging era of 3D bioprinting in organ transplantation, drone technologies in human organ transportation and other advancements.', 570, 570, '401–600', 'Version', '08 May 2025', '08 May 2028', 'Healthcare Sector Skill Council (HSSC)', 'Healthcare Sector Skill Council', 'Counselling', 'Progression to Diploma/Degree qualifications in the relevant field after training. (NCAHP)', 'Future Skills Qualification', 'N.A.', '{"Theory":"240","Practical":"210","EmployabilitySkills":"90","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "112", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-5.5-HE-045282025-V1-HSSC', 'Carepreneur- Early Child Development (ECD) Services', 'healthcare', 'Healthcare', 5.5, 'The role of the carepreneur is that of a change-maker and leader, one who combines child development expertise with entrepreneurial skills to create accessible, inclusive, and high-quality early child development services. This qualification is designed to equip aspiring entrepreneurs with the essential skills, knowledge, and tools to establish and lead high-quality early childhood care and learning centers. As the demand for reliable, professional childcare services continues to rise, this program empowers entrepreneurs to create nurturing, developmentally appropriate environments that foster children''s growth while also ensuring operational and business success. The qualification covers a comprehensive range of topics, including legal compliance, financial planning, and operational setup, as well as designing learning activities tailored to different age groups. It also integrates key elements like developmental age-appropriate learning activities, health, hygiene, immunization, nutrition, and safety standards that are critical to providing quality care to children including children with disabilities and sick children with protection from child abuse and neglect.', 540, 540, '401–600', 'Version', '07 Oct 2025', '07 Oct 2028', 'Healthcare Sector Skill Council (HSSC)', 'Healthcare Sector Skill Council', 'Early Child Development', 'N/A', 'General Qualification', 'N.A.', '{"Theory":"120","Practical":"150","EmployabilitySkills":"90","OJT_Mandatory":"180"}', false, '{}'::text[], '{"source_row": "113", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-4.5-HE- 045272025-V1-HSSC', 'Associate cum Coordinator - Early Child Development (ECD) Services', 'healthcare', 'Healthcare', 4.5, 'Associate-cum-Coordinator is a professional responsible for overseeing the implementation, and quality of ECD curriculum and services. The role of the professional is to focus on management, mentoring, monitoring, and ensuring standards in early childhood services. This is in contrast with the role of the worker who directly interacts with children on a daily basis. However, they would work closely with leadership, parents, community and other stakeholders. The course will provide expertise in a wide range of areas, including team coordination, implementation of age-appropriate learning activities, health and safety standards, financial oversight, inventory management, records management while ensuring safety and compliance with legal requirements and ensuring inclusivity for children with developmental delays or disabilities.', 450, 450, '401–600', 'Version', '07 Oct 2025', '07 Oct 2025', 'Healthcare Sector Skill Council (HSSC)', 'Healthcare sector Skill Council', 'Early Child Development', 'Level 5.5: Carepreneur – Early Child Development (ECD) Services', 'General Qualification', 'N.A.', '{"Theory":"120","Practical":"180","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "114", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-HE-045262025-V1-HSSC', 'Child Health Worker-Early Child Development (ECD) Services', 'healthcare', 'Healthcare', 3.0, 'The individual is a trained Childcare Worker who supports the growth, development, early stimulation and well-being of young children. The role involves creating a safe, nurturing, and stimulating environment that fosters holistic development (physical, cognitive, language, social, moral and emotional). The course would be covering a
comprehensive range of topics, including key elements like developmental age-appropriate learning activities, health, wellness, hygiene, immunization, first aid, emergency response, nutrition, Assisted Daily Living Activities, Daily schedule of a child, their comfort techniques, responsive feeding techniques, and safety standards that
are critical to providing quality care to children including children with disabilities and sick children with protection from child abuse and neglect. They would also acquire necessary knowledge, skills, and attitudes to identify and screen developmental delays/disabilities as well as observe, record and report the progress of children in diaries or MCP card in early childhood care and learning centres.', 270, 270, '201–400', 'Version', '07 Oct 2025', '07 Oct 2028', 'Healthcare Sector Skill Council (HSSC)', 'Healthcare Sector Skill Council', 'Early Child Development', 'Level 4: Geriatric Caregiver', 'General Qualification', 'N.A.', '{"Theory":"60","Practical":"90","EmployabilitySkills":"30","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "115", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-04-HE-045252025-V1-HSSC', 'Alzheimer''s and Dementia Care- Fundamentals', 'healthcare', 'Healthcare', 4.0, 'Individuals should be able to adapt to changes in individualized care plans for geriatric patients suffering from Alzheimer’s and Dementia.', 120, 120, '1–200', 'Version', '07 Oct 2025', '07 Oct 2028', 'Healthcare Sector Skill Council (HSSC)', 'Healthcare Skill Sector Council', 'Special care Services', 'Not Applicable', 'Future Skills Qualification', 'N.A.', '{"Theory":"45","Practical":"30","EmployabilitySkills":"00","OJT_Mandatory":"45"}', false, '{}'::text[], '{"source_row": "116", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
