INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-TH-02552-2024-V1-DWSSC', 'House Manager', 'home-management-and-caregiving', 'Home Management and Caregiving', 5.0, 'The individual at work is solely responsible for overseeing and governing the ins and outs of a household in order to assist family in accomplishing daily activities and to ensure that the family is able to operate as smoothly as possible. The individual will manage every detail of the household, from upkeep and maintenance to day to day task lists. He or she may live on-site in the employers home, have a set number of hours per day to come in, or be on call to take on tasks as needed, depending on the needs of the employer and home.', 570, 690, '601–800', 'Version', '15 Mar 2024', '15 Mar 2027', 'Home Management and Care Givers Sector Skill Counil (HMCGSSC)', 'Domestic Workers Sector Skill Council', 'Housekeeping', 'Estate Manager', 'General Qualification', 'N.A.', '{"Theory":"160","Practical":"320","EmployabilitySkills":"90","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "18", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_44.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-HC-02553-2024-V2-DWSSC', 'Child Caretaker (Non-Clinical)', 'home-management-and-caregiving', 'Home Management and Caregiving', 3.0, 'A Child Caretaker (Non-Clinical) is responsible for providing complete care to the children (2 to 6 years) including performing activities of daily living such as bathing, toileting, feeding, putting the children to sleep, etc. One would also be responsible for cooking, making bed, setting up play area, pre-school support, arranging for creative activities and games under the supervision of the parents/ guardians while assuring the safety and security of the children.', 360, 360, '201–400', 'Version', '19 Dec 2018', '15 Mar 2027', 'Home Management and Care Givers Sector Skill Counil (HMCGSSC)', 'Domestic Worker Sector Skill Council', 'Child Care (Non - Clinical)', 'Play School Facilitator cum Caregiver', 'General Qualification', 'N.A.', '{"Theory":"60","Practical":"120","EmployabilitySkills":"60","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "19", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_44.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-HC-02554-2024-V2-DWSSC', 'Elderly Caretaker (Non-Clinical)', 'home-management-and-caregiving', 'Home Management and Caregiving', 3.0, 'An Elderly Caretaker (Non-Clinical) in the informal sector is one of the most crucial operational roles in the domestic worker segment where the caretaker would be providing care to an elderly person who may or may not have any disability. The primary role of the elderly caretaker is to assist elderly person in day to day activities such as walking eating, dressing, toileting, grooming and in running errands. She/ he would also assist the elderly with in cooking and housekeeping duties. Creation and maintenance of a hygienic and pleasant environment for the elderly would also be a part of her/ his duties', 360, 360, '201–400', 'Version', '19 Dec 2018', '15 Mar 2027', 'Home Management and Care Givers Sector Skill Counil (HMCGSSC)', 'Domestic Workers Sector Skill Council', 'Elderly Care (Non-Clinical)', 'Elderly Care Companion', 'General Qualification', 'N.A.', '{"Theory":"60","Practical":"120","EmployabilitySkills":"60","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "20", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_44.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-3.5-HE-02937-2024-V1-DWSSC', 'Assistant Creche Caretaker', 'home-management-and-caregiving', 'Home Management and Caregiving', 3.5, 'Assistant Creche Caretaker is responsible for the physical, emotional, and social well-being of children in a crèche environment. They create a safe and stimulating learning environment, cater to children''s basic needs, and support their development through play and activities.', 420, 420, '401–600', 'Version', '27 Aug 2024', '27 Aug 2027', 'Home Management and Care Givers Sector Skill Counil (HMCGSSC)', 'Home Management and Care Givers Sector Skill Council', 'Child Caregiving', 'Senior Creche Caretaker', 'Future Skills Qualification,General Qualification', 'N.A.', '{"Theory":"132","Practical":"198","EmployabilitySkills":"30","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "21", "qualification_type": "Future Skills Qualification,General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_44.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-4.5-TH-02936-2024-V1-DWSSC', 'Care Homes Supervisor', 'home-management-and-caregiving', 'Home Management and Caregiving', 4.5, 'Care Homes Supervisor is required to assist the management of either of the Childerns Home, Old Age Home or PwD Homes, or their combination. For this purpose, they are also required to organise and supervise various functions and activities in the said care homes such as, cleanliness, hygiene, sanitation, Activities of Daily Living (ADL), nutrition of those cared for, and their safety and security alongwith their rights. They are also required to keep the care homes equipped and functional, and supervise caregiving, growth, rehabilitation and recreation as applicable It is a short-term course.', 510, 750, '601–800', 'Version', '27 Aug 2024', '27 Aug 2027', 'Home Management and Care Givers Sector Skill Counil (HMCGSSC)', 'Home Management and Care Givers Sector Skill Council', 'Caregiving', 'Manager Care Homes', 'Future Skills Qualification,General Qualification', 'N.A.', '{"Theory":"160","Practical":"230","EmployabilitySkills":"60","OJT_Mandatory":"60"}', true, '{}'::text[], '{"source_row": "22", "qualification_type": "Future Skills Qualification,General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_44.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-02-TH-03301-2024-V2-DWSSC', 'General Housekeeper (Household and Small Establishment)', 'home-management-and-caregiving', 'Home Management and Caregiving', 2.0, 'A General Housekeeper (Household and Small Establishment) in the informal sector is a critical operational role in the domestic worker segment, providing various types of housekeeping services at homes, small establishments, care homes, office premises, and so on. She/ he would provide basic housekeeping services – sweeping, dusting, laundry, cleaning of utensils, pet car, bathroom and toilets and garbage disposal. She/ he would also maintain a daily, weekly, long-term cleaning schedule for the house.', 270, 270, '201–400', 'Version', '19 Dec 2018', '22 Oct 2027', 'Home Management and Care Givers Sector Skill Counil (HMCGSSC)', 'Home Management & Care Givers Sector Skill Council', 'Housekeeping', 'Professional Cook/Multipurpose Executive', 'General Qualification', 'N.A.', '{"Theory":"80","Practical":"130","EmployabilitySkills":"30","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "23", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_44.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-02-TH-03300-2024-V2-DWSSC', 'Housekeeper cum Cook (Household and Small Establishment)', 'home-management-and-caregiving', 'Home Management and Caregiving', 2.0, 'A Housekeeper cum Cook (Household and Small Establishment) in the informal sector is a critical operational role in the domestic worker segment, providing housekeeping and cooking services. She/ he would provide basic housekeeping services – cooking, sweeping, dusting, laundry, cleaning of utensils, bathroom and toilets and garbage disposal. Also she/ he would maintain daily, weekly, long-time cleaning schedule for the house & small establishment', 300, 300, '201–400', 'Version', '19 Dec 2018', '22 Oct 2027', 'Home Management and Care Givers Sector Skill Counil (HMCGSSC)', 'Home Management and Care Givers Sector Skill Council', 'Cooking & Cooking', 'Professional Cook/ Multipurpose Executive', 'General Qualification,Heritage/Traditional Qualification,Multi-Skill Qualification', 'N.A.', '{"Theory":"80","Practical":"160","EmployabilitySkills":"30","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "24", "qualification_type": "General Qualification,Heritage/Traditional Qualification,Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_44.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-DW-03625-2025-V1-DWSSC', 'Pest Control Technician (Household and Small Establishment)', 'home-management-and-caregiving', 'Home Management and Caregiving', 3.0, 'A Pest Control Technician plays a pivotal role in managing pest-related issues for households and small establishments. This operational position involves implementing pest control measures and maintaining a pest-free environment. The technician is responsible for assessing, identifying, and addressing pest infestations through various methods and treatments.', 390, 390, '201–400', 'Version', '18 Feb 2025', '18 Feb 2028', 'Home Management and Care Givers Sector Skill Counil (HMCGSSC)', 'Home Management & Care Givers Sector Skill Council', 'Housekeeping, Cleaning', 'Pest Control Supervisor', 'Future Skills Qualification,General Qualification,Heritage/Traditional Qualification', 'N.A.', '{"Theory":"120","Practical":"180","EmployabilitySkills":"30","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "25", "qualification_type": "Future Skills Qualification,General Qualification,Heritage/Traditional Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_44.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-DW-03626-2025-V1-DWSSC', 'Manager Care Homes', 'home-management-and-caregiving', 'Home Management and Caregiving', 5.0, 'A Manager Care Homes is responsible for overseeing the day-to-day operations of a residential care facility, ensuring that high standards of care and support are provided to residents. Their role includes managing staff, maintaining compliance with healthcare regulations, and ensuring the well-being and safety of residents.', 540, 630, '601–800', 'Version', '18 Feb 2025', '18 Feb 2028', 'Home Management and Care Givers Sector Skill Counil (HMCGSSC)', 'Home Management and Care Givers Sector Skill Council', 'Caregiving', 'Director Care Homes', 'General Qualification', 'N.A.', '{"Theory":"140","Practical":"310","EmployabilitySkills":"90","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "26", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_44.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-DW-03624-2025-V1-DWSSC', 'Governess', 'home-management-and-caregiving', 'Home Management and Caregiving', 5.0, 'The individual at work provides care to children, are in charge of physical and emotional health of children and how effectively they integrate into society as responsible adults. The individual is primarily expected to provide education to the school-aged children and is responsible for their intellectual development along with providing general care to the children. They are mainly hired by the parents to focus on the educational and emotional development of children in a private household setting.', 570, 690, '601–800', 'Version', '18 Feb 2025', '18 Feb 2028', 'Home Management and Care Givers Sector Skill Counil (HMCGSSC)', 'Home Management and Care Givers Sector Skill Council', 'Child Care', 'Entrepreneurial Job role', 'General Qualification,Heritage/Traditional Qualification', 'N.A.', '{"Theory":"160","Practical":"320","EmployabilitySkills":"90","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "27", "qualification_type": "General Qualification,Heritage/Traditional Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_44.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-HM-045302025-V2-HMCGSSC', 'Cook (Multi-Cuisine)', 'home-management-and-caregiving', 'Home Management and Caregiving', 4.0, 'The Cook (Multi-Cuisine) is responsible for preparing and serving a variety of dishes—including Chinese, Italian, and Indian cuisines—in residential homes, small institutional kitchens, or domestic settings. The role involves planning nutritious and special-diet menus, executing basic cooking and serving tasks, and maintaining high standards of food safety, kitchen hygiene, and client service.

In addition, the cook must be proficient in handling ingredients efficiently, operating and maintaining modern kitchen appliances, and ensuring timely, hygienic, and consistent meal preparation tailored to the specific dietary preferences and needs of the household or employer.', 480, 480, '401–600', 'Version', '29 Sep 2022', '07 Oct 2028', 'Home Management and Care Givers Sector Skill Counil (HMCGSSC)', 'Home Management and Care Givers Sector Skill Council (HMCGSSC)', 'Cooking', 'Kitchen Supervisor (Level 5)', 'General Qualification', 'N.A.', '{"Theory":"138","Practical":"192","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "28", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_44.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-HM-045312025-V2-HMCGSSC', 'Mother and Newborn Care (Non-Clinical)', 'home-management-and-caregiving', 'Home Management and Caregiving', 3.0, 'The individual is responsible for attending to the physical, emotional, developmental, and social needs of newborns, and new mothers. They provide daily care, assist with feeding and hygiene, monitor health, ensure a safe environment, and support postpartum recovery. The role may be performed in households or care homes and requires adherence to health and safety standards, effective communication, and compassion.', 390, 390, '201–400', 'Version', '29 Sep 2022', '07 Oct 2028', 'Home Management and Care Givers Sector Skill Counil (HMCGSSC)', 'Home Management and Care Givers Sector Skill Council (HMCGSSC)', 'Caregiving (Non - Clinical)', 'Assistant Creche Caretaker, General Care Assistant', 'General Qualification', 'N.A.', '{"Theory":"102","Practical":"198","EmployabilitySkills":"30","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "29", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_44.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-3.5-HM-045292025-V1-HMCGSSC', 'Pet Caretaker', 'home-management-and-caregiving', 'Home Management and Caregiving', 3.5, 'The individual at work is responsible for supervising and taking care of pets such as dogs, cats, birds, horses, cows, or other animals at the pet’s own familiar environment/surroundings or while they are being held in an animal control facility. In addition to caring for pets, the individual may provide some other basic services such as vacuuming pet hairs, cleaning pet cages and cooking specialized food for the pets as per the instruction and requirement and others such services.', 420, 420, '401–600', 'Version', '07 Oct 2025', '07 Oct 2028', 'Home Management and Care Givers Sector Skill Counil (HMCGSSC)', 'Home Management and Care Givers Sector Skill Council (HMCGSSC)', 'Pet Care Service', 'Pet Trainer', 'General Qualification', 'N.A.', '{"Theory":"100","Practical":"200","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "30", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_44.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-3.5-HM-045322025-V1-HMCGSSC', 'Assistant Caregiver - Persons with Disabilities (Non-Clinical)', 'home-management-and-caregiving', 'Home Management and Caregiving', 3.5, 'Assistant Caregivers for Persons with Disabilities (Non-Clinical) provide daily living support to individuals with disabilities e.g. Locomotive Disability, Speech and Hearing Impairment, Low Vision and Visually Impaired. This role involves supporting children (ages 2-10), adolescents (ages 10-18), and adults with physical, social, emotional and special needs, including dementia patients. Basic educational support is also advantageous in this role.', 420, 600, '401–600', 'Version', '07 Oct 2025', '07 Oct 2028', 'Home Management and Care Givers Sector Skill Counil (HMCGSSC)', 'Home Management and Care Givers Sector Skill Council (HMCGSSC)', 'Caregiving (Non-Clinical)', 'Assistant Creche Caretaker & General Care Assistant', 'General Qualification', 'N.A.', '{"Theory":"90","Practical":"180","EmployabilitySkills":"60","OJT_Mandatory":"45"}', false, '{}'::text[], '{"source_row": "31", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_44.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2020/HYC/HSSCI/3770', 'Line Patrolling Man (Oil  Gas)', 'hydrocarbon', 'Hydrocarbon', 3.0, 'The primary role of Line Patrolling Man (Oil &Gas) is patrolling the pipeline and other installations in the assigned area for ensuring security of hydrocarbon pipeline. The person is also responsible for safeguarding the area from theft, criminal acts, emergencies and other contingencies.', 330, 330, '201–400', 'Version', '17 Nov 2022', '16 Nov 2025', 'Hydrocarbon Sector Skill Council (HSSCI)', 'Hydrocarbon Sector Skill Council', 'Pipeline Maintenance', 'Senior Line Patrolling Man', 'General Qualification', 'N.A.', '{"Theory":"90","Practical":"150","EmployabilitySkills":"60","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "1", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_54.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2020/HYC/HSSCI/3769', 'Process Instrument Technician (Oil & Gas)', 'hydrocarbon', 'Hydrocarbon', 4.0, 'The individual in this position is responsible for monitoring and operation of instruments and control equipment installed at oil and gas setup like gas processing plants, oil refineries, fertilizer plants, chemical process plants, gas/oil pipelines, compressor stations etc. The person monitors, adjusts and maintains processing units and equipment in field as well as in control room in calibration and installation in accordance with approved procedures.', 480, 480, '401–600', 'Version', '29 Sep 2023', '28 Sep 2026', 'Hydrocarbon Sector Skill Council (HSSCI)', 'Hydrocarbon Sector Skill Council', 'Operations - Oil & Gas Pipeline, Calibration and Instrumentation, Refineries Operations', 'Vertical Progression - Level 4.5: Senior Process Instrumentation Technician,
Horizontal Progression – Level 4: Refinery Production Technician (O&M)', 'General Qualification', 'N.A.', '{"Theory":"105","Practical":"285","EmployabilitySkills":"30","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "2", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_54.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2020/HYC/HSSCI/3612', 'Excavator-Pipeline', 'hydrocarbon', 'Hydrocarbon', 2.0, 'The individual in this job is responsible for manual excavation work involved in laying oil and gas pipeline and earth backfilling in accordance with safe working practices, plans and approvals. The individual will also check and identify hazard prone areas before starting excavation work for minimising the possible hazards to people and the surrounding environment due to excavation work.', 240, 240, '201–400', 'Version', '17 Nov 2022', '16 Nov 2025', 'Hydrocarbon Sector Skill Council (HSSCI)', 'Hydrocarbon Sector Skill Council', 'Operations-Oil & Gas pipeline', 'Helper-Hydrocarbon Pipeline', 'General Qualification', 'N.A.', '{"Theory":"60","Practical":"120","EmployabilitySkills":"30","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "3", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_54.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2020/HYC/HSSCI/3611', 'Fire Safety Technician (Oil & Gas)', 'hydrocarbon', 'Hydrocarbon', 4.0, 'The main responsibility of the fire safety technician is to ensure adherence to fire safety procedures and conduct firefighting operations in oil and gas industry. He/she conducts inspection of the workplace to ensure safety from fire hazards. The individual is also responsible for maintenance of fire safety equipment and coordination with operation and maintenance team for organising safety awareness programs to ensure the safety of the workers and surrounding', 450, 450, '401–600', 'Version', '17 Nov 2022', '16 Nov 2025', 'Hydrocarbon Sector Skill Council (HSSCI)', 'Hydrocarbon Sector Skill Council', 'Management of Health, Safety and Environment (HSE)', 'Senior Fire Safety Technician', 'General Qualification', 'N.A.', '{"Theory":"120","Practical":"240","EmployabilitySkills":"60","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "4", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_54.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2020/HYC/HSSCI/03997', 'SS (Stainless Steel) Tubing Technician', 'hydrocarbon', 'Hydrocarbon', 4.0, 'The individual in this job is responsible for the installation and maintenance of stainless-steel tubes (SS tubes) at CNG filling stations, oil and gas facilities in accordance with approved procedures and guidelines.', 480, 480, '401–600', 'Version', '17 Nov 2022', '16 Nov 2026', 'Hydrocarbon Sector Skill Council (HSSCI)', 'Hydrocarbon Sector Skill Council', 'Operations - Oil and Gas pipeline', 'Senior Technician SS (Stainless Steel) Tubing', 'General Qualification', 'N.A.', '{"Theory":"120","Practical":"240","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "5", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_54.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2021/HYC/HSSCI/04095', 'Gas Meter Reader', 'hydrocarbon', 'Hydrocarbon', 3.0, 'Gas Meter Reader is responsible to capture gas consumption reading from gas meters installed in consumer’s premises for generation of gas consumption bill. The individual is also responsible for physical inspection of gas meter for any external damage, tampering and similar faults. The person is required to maintain complete record of each visit to consumer premises and their request or any operational queries. They act as the first level of support staff between consumer and gas distribution company.', 330, 330, '201–400', 'Version', '17 Nov 2022', '16 Nov 2025', 'Hydrocarbon Sector Skill Council (HSSCI)', 'Hydrocarbon Sector Skill Council', 'Marketing Services', 'Gas Meter Reader – Supervisor', 'General Qualification', 'N.A.', '{"Theory":"90","Practical":"150","EmployabilitySkills":"60","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "6", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_54.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2021/HYC/HSSCI/04096', 'Pipeline Maintenance Technician (Mechanical)', 'hydrocarbon', 'Hydrocarbon', 4.0, 'The Pipeline Maintenance Technician (Mechanical) is responsible for installation, troubleshooting, repair, preventive maintenance and checking proper functioning of all types of mechanical equipment such as engines, electric motors, pumps, valves, pressure relief devices and related equipment typically associated with oil & gas operations facility and pipelines. The individual is also responsible to maintain records. The person plays a vital role in ensuring that plant and equipment used are in a safe condition and meets safety and technical standards.', 660, 660, '601–800', 'Version', '17 Nov 2022', '16 Nov 2025', 'Hydrocarbon Sector Skill Council (HSSCI)', 'Hydrocarbon Sector Skill Council', 'Pipeline Maintenance', 'Senior Pipeline Maintenance Technician (Mechanical)', 'General Qualification', 'N.A.', '{"Theory":"180","Practical":"390","EmployabilitySkills":"60","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "7", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_54.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2021/HYC/HSSCI/04663', 'Cathodic Protection Technician', 'hydrocarbon', 'Hydrocarbon', 4.0, 'The cathodic protection technician is responsible for the prevention of metallic high-pressure hydrocarbon product pipeline/structure against the corrosion. The individual identifies the corrosion/damage in the pipeline and carry out the installation, commissioning and maintenance of the cathodic protection system. The person makes sure that the system is functioning correctly and providing adequate corrosion protection.', 660, 660, '601–800', 'Version', '17 Nov 2022', '16 Nov 2025', 'Hydrocarbon Sector Skill Council (HSSCI)', 'Hydrocarbon Sector Skill Council', 'Operations - Oil and Gas pipeline', 'Senior Technician-Cathodic Protection', 'General Qualification', 'N.A.', '{"Theory":"210","Practical":"360","EmployabilitySkills":"60","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "8", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_54.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2021/HYC/HSSCI/04664', 'Direct Marketing Agent - Piped Natural Gas (PNG)', 'hydrocarbon', 'Hydrocarbon', 4.0, 'The Direct marketing Agent - Piped Natural Gas (PNG) identify and register the new consumers by undertaking promotional and marketing activities in allocated area, for supply of natural gas as fuel to domestic households, industries and commercial establishments through Piped Natural Gas (PNG) connections.', 420, 420, '401–600', 'Version', '17 Nov 2022', '16 Nov 2025', 'Hydrocarbon Sector Skill Council (HSSCI)', 'Hydrocarbon Sector Skill Council', 'Sales and Services', 'Marketing Supervisor-PNG', 'General Qualification', 'N.A.', '{"Theory":"90","Practical":"210","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "9", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_54.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2021/HYC/HSSCI/04662', 'Project Supervisor - City Gas Distribution (CGD)', 'hydrocarbon', 'Hydrocarbon', 5.0, 'The individual in this position is responsible for supervision of project activities pertaining to all processes involved in CGD pipelines installation, in a stipulated time. The person is responsible for maintaining labour log, safe and secure healthy environment at the project site by adhering to and enforcing safety codes', 570, 570, '401–600', 'Version', '17 Nov 2022', '16 Nov 2025', 'Hydrocarbon Sector Skill Council (HSSCI)', 'Hydrocarbon Sector Skill Council', 'Operations - Oil and Gas pipeline', 'Foreman', 'General Qualification', 'N.A.', '{"Theory":"120","Practical":"300","EmployabilitySkills":"90","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "10", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_54.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2021/HYC/HSSCI/04665', 'Store Keeper (Petroleum Products)', 'hydrocarbon', 'Hydrocarbon', 3.0, 'The individual in this position is responsible for store keeping of petroleum and its allied products. The
person verifies and receives the material as per Purchase Order / Delivery Challan, issues material as per indent/requisition, coordinates scrap disposal, checks inventory and quality of goods and aintains all filing system and records as necessary for material traceability and control.', 330, 330, '201–400', 'Version', '17 Nov 2022', '16 Nov 2025', 'Hydrocarbon Sector Skill Council (HSSCI)', 'Hydrocarbon Sector Skill Council', 'Store Operations', 'Store Supervisor', 'General Qualification', 'N.A.', '{"Theory":"90","Practical":"150","EmployabilitySkills":"60","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "11", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_54.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/HYC/HSSCI/05172', 'Retail Outlet Attendant (Oil & Gas)', 'hydrocarbon', 'Hydrocarbon', 3.0, 'Individuals need to work at fuel station and fill required quantity and appropriate type of fuel (petrol, diesel, and CNG) in the vehicles, while following standard safety procedures. The individuals at the job also need to complete and close financial transaction for the services rendered.', 330, 330, '201–400', 'Version', '17 Nov 2022', '16 Nov 2025', 'Hydrocarbon Sector Skill Council (HSSCI)', 'Hydrocarbon Sector Skill Council', 'Retail Distribution', 'Retail Outlet Supervisor (Oil & Gas)', 'General Qualification', 'N.A.', '{"Theory":"90","Practical":"150","EmployabilitySkills":"60","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "12", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_54.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/HYC/HSSCI/05173', 'LPG Delivery Personnel', 'hydrocarbon', 'Hydrocarbon', 3.0, 'Individuals at this job need to collect LPG cylinders from the godown and deliver and install them in the consumers’ kitchen, while following standard safety procedures. The individual must also complete the financial transaction for the service rendered.', 330, 330, '201–400', 'Version', '17 Nov 2022', '16 Nov 2025', 'Hydrocarbon Sector Skill Council (HSSCI)', 'Hydrocarbon Sector Skill Council', 'LPG Distribution', 'Supervisor-LPG Distribution/Godown', 'General Qualification', 'N.A.', '{"Theory":"90","Practical":"150","EmployabilitySkills":"60","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "13", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_54.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/HYC/HSSCI/05174', 'Tank Lorry Driver - Petroleum Products', 'hydrocarbon', 'Hydrocarbon', 4.0, 'Individual at this Job needs to deliver gasoline, fuel oil, liquefied petroleum gas, lubricant oil etc. to customers. His main work includes positioning of the truck to filling rack, open valves, start pumps, connect the respective hoses to tank, records amount delivered, maintain the check list and drive the truck to the respective outlet.', 450, 450, '401–600', 'Version', '17 Nov 2022', '16 Nov 2025', 'Hydrocarbon Sector Skill Council (HSSCI)', 'Hydrocarbon Sector Skill Council', 'Transportation (Oil & Gas)', 'Movement between different types of Vehicles used in the oil and gas industry', 'General Qualification', 'N.A.', '{"Theory":"120","Practical":"210","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "14", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_54.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/HYC/HSSCI/05175', 'LPG Mechanic', 'hydrocarbon', 'Hydrocarbon', 3.0, 'Individuals at this job need to do installation of LPG cylinders for the new connection at customer’s premises (domestic, commercial and industrial), while following standard safety procedures. The individual is also responsible for creating customer awareness on safe usage of LPG and allied equipment as well as DO’s and DON’T’s in case of emergency and must have technical knowledge for attending complaints of LPG and allied products. The job also requires to carry out mandatory inspection periodically at customer premises and attending emergency complaints within specified timeline. The personnel must demonstrate customer centricity and foresee potential obstacles and hazards that may occur.', 330, 330, '201–400', 'Version', '17 Nov 2022', '16 Nov 2025', 'Hydrocarbon Sector Skill Council (HSSCI)', 'Hydrocarbon Sector Skill Council', 'LPG Installation & Complaint Handling', 'Supervisor-LPG Distribution', 'General Qualification', 'N.A.', '{"Theory":"90","Practical":"150","EmployabilitySkills":"60","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "15", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_54.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/HYC/HSSCI/05176', 'Industrial Electrician (Oil & Gas)', 'hydrocarbon', 'Hydrocarbon', 4.0, 'Industrial Electrician installs, maintains, and performs repair work of electrical, electronic, and electrical wiring for well-functioning in an industrial environment specially in petroleum refinery and demonstrable ability to use electrical and hand tools and electrical drawings and blueprints He has a thorough knowledge of safety procedures and legal regulations and guidelines', 600, 600, '401–600', 'Version', '17 Nov 2022', '16 Nov 2025', 'Hydrocarbon Sector Skill Council (HSSCI)', 'Hydrocarbon Sector Skill Council', 'Refineries', 'Supervisor Industrial Electrician (Oil & Gas)', 'General Qualification', 'N.A.', '{"Theory":"180","Practical":"300","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "16", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_54.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/HYC/HSSCI/05178', 'Industrial Welder (Oil & Gas)', 'hydrocarbon', 'Hydrocarbon', 4.0, 'Industrial welders (Oil & Gas) perform welding using manual and semi-automatic welding equipment to weld different types of metals together (ferrous/non-ferrous), following drawing and welding process specifications. They are specialised in certain types of welding, such as welding in refinery, aerospace precision welding, manufacturing welding, pipeline, automotive and construction welding.', 600, 600, '401–600', 'Version', '17 Nov 2022', '16 Nov 2025', 'Hydrocarbon Sector Skill Council (HSSCI)', 'Hydrocarbon Sector Skill Council', 'Welding', 'Supervisor Industrial Welder (Oil & Gas)', 'General Qualification', 'N.A.', '{"Theory":"180","Practical":"300","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "17", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_54.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/HYC/HSSCI/06144', 'Loading Operator - LPG/Propane', 'hydrocarbon', 'Hydrocarbon', 3.0, 'The individual is responsible to complete loading of LPG/Propane (liquid hydrocarbon) etc. by following the standard operating procedure (SOP). The person is responsible for physical inspection & proper positioning of the tanker, earthing cable connection, checking healthiness /working of Pressure gauge (PG) Temperature gauge (TG) and Lower explosive limit (LEL) meter, Connection of Vapour / liquid arms to the tanker with proper gasket, ensure liquid and vapour line are open. The person communicates with loading control room, taking all required safety measures up to exit of the tanker from Gantry.', 330, 330, '201–400', 'Version', '17 Nov 2022', '16 Nov 2025', 'Hydrocarbon Sector Skill Council (HSSCI)', 'Hydrocarbon Sector Skill Council', 'Operations –LPG/Propane (Gas Processing Plant/ Terminal/ Bottling Plant)', 'Sr. Loading Operator (LPG/Propane)', 'General Qualification', 'N.A.', '{"Theory":"60","Practical":"150","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "18", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_54.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-HY-00415-2023-V1-HSSCI', 'Floor hand Roughneck – Drilling Rig', 'hydrocarbon', 'Hydrocarbon', 4.0, 'The Individual at this job is responsible to pipe in well bore, perform general work around the rig, assist crew members in drilling operation at drilling rig. The person at this job closely works with roustabouts, derrick hands, crew pusher, etc. and assist them in preparatory, operational and maintenance work.', 450, 450, '401–600', 'Version', '03 May 2023', '02 May 2026', 'Hydrocarbon Sector Skill Council (HSSCI)', 'Hydrocarbon Sector Skill Council', 'Exploration & Production', 'Vertical Progression:
NSQF Level 5: Toolpusher
Horizontal Progression:
NSQF Level 4: Derrikhand', 'General Qualification', 'N.A.', '{"Theory":"120","Practical":"210","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "19", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_54.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-HY-00414-2023-V1-HSSCI', 'Hydrocarbon Pipeline Operator', 'hydrocarbon', 'Hydrocarbon', 4.0, 'Individual at this job is responsible to operate the flow of oil/ gas/ fossil fuels through pipeline in oil and gas setup like refinery, processing plants, gas facilities or storage facilities. The person at this job is responsible for identification, maintenance of hydrocarbon pipelines for smooth flow of hydrocarbon product in the pipeline.', 480, 480, '401–600', 'Version', '03 May 2023', '02 May 2026', 'Hydrocarbon Sector Skill Council (HSSCI)', 'Hydrocarbon Sector Skill Council', 'Pipe Fitting (Oil & Gas)', 'Vertical Progression:
NSQF Level 5: Technical Supervisor- Hydrocarbon Pipeline
Horizontal Progression:
NSQF Level 4: Cathodic Protection Technician
NSQF Level 4: Pipe fitter - Oil & Gas', 'General Qualification', 'N.A.', '{"Theory":"90","Practical":"270","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "20", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_54.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-HY-00360-2023-V1-HSSCI', 'Junior Motor Operator/Junior Pump Operator', 'hydrocarbon', 'Hydrocarbon', 3.0, 'The individual at this job is responsible for assisting the motor operator/pump operator in repairing the motor/pump during the breakdown, monitoring the motor/pump to ensure it is functional and maintaining motor/pump to prevent it from any breakdown. The person at this job assists motor operator/pump operator in preparatory, operational and maintenance work during at the oil and gas production sites', 360, 360, '201–400', 'Version', '03 May 2023', '02 May 2026', 'Hydrocarbon Sector Skill Council (HSSCI)', 'Hydrocarbon Sector Skill Council', 'Exploration & Production', 'Vertical Progression:
NSQF Level 4: Motor Operator/Pump Operator', 'General Qualification', 'N.A.', '{"Theory":"90","Practical":"210","EmployabilitySkills":"30","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "21", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_54.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-5.5-HY-00376-2023-V1-HSSCI', 'Lab Chemist/Analyst– Petroleum Products', 'hydrocarbon', 'Hydrocarbon', 5.5, 'Individual at this job is responsible for analyzing samples of oil and gas, perform ASTM/IP/BIS etc test experiments as per defined procedure to determine their composition, quality and value. The person at this job measures the density of liquids, test specific chemical compounds, or perform other tests to identify the physical properties of the substances', 600, 600, '401–600', 'Version', '03 May 2023', '02 May 2026', 'Hydrocarbon Sector Skill Council (HSSCI)', 'Hydrocarbon Sector Skill Council', 'Petroleum Product Testing', 'Vertical Progression:  Sr. Manager - Petroleum Product Testing (Level 6)', 'General Qualification', 'N.A.', '{"Theory":"120","Practical":"330","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "22", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_54.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-HY-00361-2023-V1-HSSCI', 'Mud mix Assistant-Drilling Operation', 'hydrocarbon', 'Hydrocarbon', 3.0, 'Individual at this job is responsible to maintain the flow of mud mix fluid during drilling operation, maintains the mud pumps, tanks, hoses, air compressors, generators, valves to ensure the smoothly flow of mud during drilling operation. The person at this job checks the quantity and quality of the drilling mud, sand content viscosity, specific to gravity of drilling mud mix.', 360, 360, '201–400', 'Version', '03 May 2023', '02 May 2026', 'Hydrocarbon Sector Skill Council (HSSCI)', 'Hydrocarbon Sector Skill Council', 'Exploration & Production', 'Vertical Progression:
NSQF Level 4: Floorhand(roughneck)', 'General Qualification', 'N.A.', '{"Theory":"90","Practical":"180","EmployabilitySkills":"30","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "23", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_54.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-HY-00413-2023-V1-HSSCI', 'Operator – LNG Production', 'hydrocarbon', 'Hydrocarbon', 4.0, 'Individual at this job is responsible for monitoring, operating and maintaining the vast network of pipes, pumps, processing units and control panels in a Liquefied Natural Gas (LNG) plant/terminal. The person at this job operates liquefied natural gas (LNG) liquefaction/re-gasification terminal which includes LNG process systems, infrastructure, power/steam generation, controls and emergency response, and operation of the Distributed Control System (DCS) consoles at LNG terminal', 450, 450, '401–600', 'Version', '03 May 2023', '02 May 2026', 'Hydrocarbon Sector Skill Council (HSSCI)', 'Hydrocarbon Sector Skill Council', 'LNG Production', 'Vertical Progression:
NSQF Level 5: Supervisor LNG Production', 'General Qualification', 'N.A.', '{"Theory":"90","Practical":"240","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "24", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_54.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
