INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-HY-01369-2023-V1-HSSCI', 'Executive Finance – Oil & Gas', 'hydrocarbon', 'Hydrocarbon', 4.0, 'The individual will be able to perform variety of financial tasks viz. dealing with Financial Management and Security Market, designing different kinds of formats, modules, reviews and feedback charts, handling database in the organizations, banks, Financial Institutions and performing basic operations of banks, financial markets, preparing different Financial Products and Financial Statements using General Accounting Principles and trading practices at stock exchanges, NCFM Modules etc.', 420, 420, '401–600', 'Version', '30 Nov 2023', '29 Nov 2026', 'Hydrocarbon Sector Skill Council (HSSCI)', 'Hydrocarbon Sector Skill Council', 'Office management', 'Senior Executive', 'General Qualification', 'N.A.', '{"Theory":"105","Practical":"255","EmployabilitySkills":"30","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "32", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_54.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-HY-01368-2023-V1-HSSCI', 'Executive HR – Oil & Gas', 'hydrocarbon', 'Hydrocarbon', 4.0, 'The HR Executive maintains employee data for the Human Resource (HR) department and compiles all necessary payroll data, enters it into the organization’s data system, calculates each employee’s respective pay, computing statutory and tax related entitlements and deductions and co-ordinates with the accounts department for disbursements and fund transfers.', 420, 420, '401–600', 'Version', '30 Nov 2023', '29 Nov 2026', 'Hydrocarbon Sector Skill Council (HSSCI)', 'Hydrocarbon Sector Skill Council', 'Office management', 'Senior Executive -HR', 'General Qualification', 'N.A.', '{"Theory":"105","Practical":"255","EmployabilitySkills":"30","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "33", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_06_54.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
