INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-OA-00862-2023-V1-IASC', 'Junior Executive- B2B Customer Relation (Automation)', 'instrumentation', 'Instrumentation', 4.0, 'B2B Customer Relation Executive will be a key player in managing and improving relationships with business-to-business (B2B) clients in the context of automation solutions.  Individuals in this job will be able to comprehend customer objectives, provide personalized solutions, and streamline their automation journey in automation technology and procedures. An executive will help in creating long-lasting relationships and ensure that automation services and products are successfully adopted.
Executive deals with Business-to-Business, within the automation and allied industry to primarily analyse the automation need, provide products, services, or solutions related to automation technologies to other businesses.', 420, 420, '401–600', 'Version', '31 Aug 2023', '31 Aug 2026', 'Instrumentation Automation Surveillance & Communication Sector Skill Council ( IASC)', 'Instrumentation Automation Surveillance & Communication Sector Skill Council
B-12, Sector-1, Udhyog Marg, Noida – 201301
E-mail: ceo@iascsectorskillcouncil.in', 'Installation and Commissioning', 'Sr. Executive - B2B Customer Relation', 'Cross Sectoral Qualification', 'N.A.', '{"Theory":"60","Practical":"210","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "1", "qualification_type": "Cross Sectoral Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_14.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
