INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-04-IS-03842-2025-V1-IISSSC', 'Basics of Pot Room Operations in Aluminium Industry', 'iron-steel', 'Iron & Steel', 4.0, 'This micro credential provides a comprehensive overview of Pot Room Operations, covering Fundamentals, Equipment and Maintenance, Crust Management, Bath Chemistry, and Safety Procedures. Participants gain expertise in managing operations, maintaining equipment, optimizing bath chemistry, ensuring metal quality, and responding effectively to emergencies, preparing them for roles in aluminum smelting and Pot Room management.', 30, 30, '1–200', 'Version', '18 Feb 2025', '18 Feb 2028', 'Indian Iron and Steel Sector Skill Council (IISSSC)', 'Indian Iron and Steel Sector Skill Council (IISSSC)', 'Operation and Maintenance', 'Pot Room - Supervisor', 'Micro Credentials', 'N.A.', '{"Theory":"20","Practical":"10","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "36", "qualification_type": "Micro Credentials", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_21.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-04-IS-03841-2025-V1-IISSSC', 'Basics of Pot room transportation in Aluminium Industry', 'iron-steel', 'Iron & Steel', 4.0, 'This micro credential provides a comprehensive overview of Pot Room Operations, encompassing Fundamentals of Pot Room Operations, Material Handling and Transport Procedures, Traffic Management and Scheduling, Maintenance and Vehicle Upkeep, and Safety Procedures and Emergency Response. It equips learners with essential skills to manage pot room activities efficiently, ensuring safe and effective operations in industrial settings.', 30, 30, '1–200', 'Version', '18 Feb 2025', '18 Feb 2028', 'Indian Iron and Steel Sector Skill Council (IISSSC)', 'Indian Iron and Steel Sector Skill Council (IISSSC)', 'Material Handling', 'Supervisor – Pot room Driver', 'Micro Credentials', 'N.A.', '{"Theory":"20","Practical":"10","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "37", "qualification_type": "Micro Credentials", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_21.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
