INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-IS-03629-2025-V1-IISSSC', 'Coupler and Shunting Porter (Steel Plant)', 'iron-steel', 'Iron & Steel', 4.0, 'The individual in this role performs loco crew joining / disengaging Loco / match car with Rolling Stock, wagons etc. and other jobs related to the safe movement on railway track', 480, 480, '401–600', 'Version', '18 Feb 2025', '18 Feb 2028', 'Indian Iron and Steel Sector Skill Council (IISSSC)', 'Indian Iron and Steel Sector Skill Council (IISSSC)', 'Raw Material Handling', 'Locomotive - Supervisor', 'General Qualification', 'N.A.', '{"Theory":"130","Practical":"230","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "39", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_21.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-IS-03630-2025-V1-IISSSC', 'High Speed Rotating Machinery (Steel Plant): Mechanic', 'iron-steel', 'Iron & Steel', 4.0, 'The individual in this role performs mechanical maintenance, of fans, compressors, turbo blowers, sinter fans etc. by following organizational specified procedures and standards.', 450, 450, '401–600', 'Version', '18 Feb 2025', '18 Feb 2028', 'Indian Iron and Steel Sector Skill Council (IISSSC)', 'Indian Iron and Steel Sector Skill Council (IISSSC)', 'Mechanical Maintenance', 'Supervisor - Mechanic: High Speed Rotating Machinery', 'General Qualification', 'N.A.', '{"Theory":"120","Practical":"210","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "40", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_21.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NC-04-IS-03800-2025-V1-IISSSC', 'Basics of Solid Waste Management (Iron & Steel Industry)', 'iron-steel', 'Iron & Steel', 4.0, 'This nano-credential provides a comprehensive understanding of waste management in the iron and steel industry, focusing on fundamental principles, advanced utilization techniques, and strategic implementation for achieving zero waste. Participants gain expertise in identifying and classifying waste types, applying solid waste recycling methods, utilizing by-products like slag and dust, and integrating sustainable practices such as Carbon Capture, Utilization, and Storage (CCUS). Additionally, the credential equips learners to develop and implement waste minimization strategies, optimize resource recovery, and contribute to eco-friendly steel production. This program prepares professionals for impactful roles in waste management and sustainability within the iron and steel sector.', 5, 5, '1–200', 'Version', '18 Feb 2025', '18 Feb 2028', 'Indian Iron and Steel Sector Skill Council (IISSSC)', 'Indian Iron and Steel Sector Skill Council (IISSSC)', 'Operation & Mechanical Maintenance', 'Manager - Waste Management', 'General Qualification', 'N.A.', '{"Theory":"4","Practical":"1","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "41", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_21.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-05-IS-04237-2025-V1-IISSSC', 'Application of AI (Metal Sector)', 'iron-steel', 'Iron & Steel', 5.0, 'This micro credential provides a comprehensive overview of artificial intelligence tailored for the steel industry. Covering fundamental concepts in AI, it delves into deep learning specifically for steel applications, explores integration with automation and robotics, advances AI techniques pertinent to steel manufacturing, and emphasizes AI''s role in decision-making and automation within steel production processes.', 30, 30, '1–200', 'Version', '08 May 2025', '08 May 2028', 'Indian Iron and Steel Sector Skill Council (IISSSC)', 'Indian Iron and Steel Sector Skill Council (IISSSC)', 'Data Handling - Network Managed Services', 'NA.', 'Future Skills Qualification', 'N.A.', '{"Theory":"20","Practical":"10","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "42", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_21.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-05-IS-04238-2025-V1-IISSSC', 'Application of Machine Learning (Metal Sector)', 'iron-steel', 'Iron & Steel', 5.0, 'This micro credential provides a comprehensive overview of machine learning applied to the steel industry. It covers Python fundamentals, explores machine learning and data analytics concepts, delves into core ML techniques, and specifically focuses on their applications in steel production. Participants learn relevant tools and techniques tailored for the steel industry, equipping them with practical skills for data-driven decision-making in steel manufacturing processes.', 30, 30, '1–200', 'Version', '08 May 2025', '08 May 2028', 'Indian Iron and Steel Sector Skill Council (IISSSC)', 'Indian Iron and Steel Sector Skill Council (IISSSC)', 'Data Handling - Network Managed Services', 'NA.', 'Future Skills Qualification', 'N.A.', '{"Theory":"20","Practical":"10","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "43", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_21.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-IS-04235-2025-V1-IISSSC', 'PLC Technician (Advanced)', 'iron-steel', 'Iron & Steel', 5.0, 'A PLC technician is responsible for controlling various processes of industries involving development, testing and commission the PLC, HDMI and SCADA program, finding errors, if any, and then fixing the errors or faults, during the operation of the plant.', 570, 570, '401–600', 'Version', '08 May 2025', '08 May 2028', 'Indian Iron and Steel Sector Skill Council (IISSSC)', 'Indian Iron and Steel Sector Skill Council (IISSSC)', 'Installation and Commissioning', 'PLC system Supervisor Level – 5.5', 'General Qualification', 'N.A.', '{"Theory":"130","Practical":"230","EmployabilitySkills":"60","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "44", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_21.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
