INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-IS-04233-2025-V1-IISSSC', 'Sand Moulder', 'iron-steel', 'Iron & Steel', 3.0, 'The individual in this role will be responsible for making sand moulds using different machine moulding and hand moulding techniques', 420, 420, '401–600', 'Version', '08 May 2025', '08 May 2028', 'Indian Iron and Steel Sector Skill Council (IISSSC)', 'Indian Iron and Steel Sector Skill Council (IISSSC)', 'Foundry', 'Supervisor - Sand Moulder (Level-5)', 'General Qualification', 'N.A.', '{"Theory":"105","Practical":"225","EmployabilitySkills":"30","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "47", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_21.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2020/ITES/ASAP/03802', 'Certificate Course in Coding Skills', 'it-ites', 'IT-ITeS', 5.0, 'Individuals at this job are responsible for developing applications and platforms in any language in order to build a robust hack free system. They will be responsible for evaluating the technical performance of algorithmic models on the system on which it is being deployed. They will be responsible for developing, designing, building, testing and deploying programming solutions.', 270, 270, '201–400', 'Version', '25 Jun 2020', '01 Mar 2026', 'Additional Skill Acquisition Programme, Government of Kerala', 'Additional Skill Acquisition Programme, Government of Kerala.', 'Software Engineer /Project Engineer', 'VERTICAL PROGRESSION 
Engineer Trainee, Project Engineer,  Module Lead, Development Manager 

HORIZONTAL PROGRESSION 
Trainee Coder , Programming Research , Consultant/Entrepreneur', 'Future Skills Qualification,General Qualification', 'N.A.', '{"Theory":"36","Practical":"204","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "1", "qualification_type": "Future Skills Qualification,General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2020/ITES/ITSSC/04331', 'AI – Data Quality Analyst', 'it-ites', 'IT-ITeS', 5.0, 'Individuals at this job are responsible for importing data (public / private, consumer / enterprise) from various internal and external sources. They are responsible for preprocessing the data to meet the desired quality standards or as desired for analysis. They need to have good communication skills to work with stakeholders across multiple teams such as data sciences, product development, etc.', 480, 480, '401–600', 'Version', '19 Dec 2018', '22 Sep 2025', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'IT-ITeS SSC NASSCOM', 'Artificial Intelligence and Big Data Analytics', 'Senior Data Quality Analyst, Senior Business Intelligence Analyst, Senior Visualization Specialist', 'Upskilling Qualification', 'N.A.', '{"Theory":"120","Practical":"210","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "2", "qualification_type": "Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/ITES/NIELIT/05878', 'O Level ‘IT’', 'it-ites', 'IT-ITeS', 4.0, 'After undergoing this qualification, candidate will be able to perform different job roles. The job roles are User Interface (UI) designer, Web Designer, Web Publication Assistant, Office Automation Assistant and IoT Application Integrator. 
The job of a UI designer is to make software interfaces interactive in terms of looks, style and customer’s experience in accessing website/applications. 
The job of a Web Designer is to design the layout of website and coding. Web Designer further focuses on graphics and contents part of web site and its flow. 
The responsibility of a Web Publication Assistant is to upload images, contents, videos and other web site related material on web site. Before uploading material, a Web Publication Assistant ensures that data is correct in all respects.
The responsibility of Office Automation Assistant is to format and edit any type of document using tools. The person is also responsible for maintaining records digitally. 
IoT Application Integrator ensures that all the IoT Devices, IoT Data, IoT Platforms and applications work together in an organization in order to meet business objectives.', 540, 540, '401–600', 'Version', '26 May 2022', '26 May 2027', 'National Institute of Electronics and Information Technology (NIELIT)', 'Examination Wing, NIELIT Headquarters,  National Institute of Electronics and Information Technology (NIELIT) NIELIT Bhawan, Plot No 3, PSP Pocket, Institutional Area, Sector-8, Dwarka, South West Delhi, Delhi -110077', 'i.	User Interface (UI) Designer
ii.	Web Designer
iii.	Web Publication Assistant
iv.	Office Automation Assistant
v.	IoT Application Integrator', 'Academic:
O level->A Level ->B level 
Professional:
User Interface Designer-> UX Designer ->Graphics Designer
Web Designer->Web Developer-> Front-end Developer
Web Publication Assistant-> Sr Web Publication Assistant-> Sr. Web Designer
Office Automation Assistant ->Senior Assistant ->Section Manager
IoT Application Integrator-> IoT Support Engineer-> IoT Application Developer', 'Future Skills Qualification,General Qualification', 'N.A.', '{"Theory":"192","Practical":"288","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "3", "qualification_type": "Future Skills Qualification,General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/ITES/NIELIT/05879', 'A Level (IT)', 'it-ites', 'IT-ITeS', 5.0, 'After undergoing this qualification, candidate will be able to perform primarily following job roles. i. Freelancer (For self-employed) ii. Full Stack Developer iii. Data Scientist/Analyst iv. IoT Architect v. IoT Developer vi. Business Intelligence Analyst vii. Information Security Analyst The Full Stack Developer is responsible to develop both client side and server-side scripting. The Data Scientist fetches information in different formats from the various sources & analyses it for the business purposes. The IoT Architect provides a mechanism to manage data received from various networks and devices like smart phones, cameras etc. IoT Architect designs IoT solution to organizations problems. . The Business Intelligence Analysts are responsible to collect data from multiple sources and industry trends. They analysis data to figure out market and business trends for companies to increase profits and efficiency. They give picture of organization’s competitiveness compare to other player in the same industry. The Security analysts are responsible for ensuring protection of digital assets from unauthorized access. Security analysts are also responsible for generating reports for IT administrators and business managers to evaluate the efficacy of the security policies in place. The NIELIT A Level qualified person can also become Faculty at training/education institute.', 1620, 1620, '1201–2400', 'Version', '26 May 2022', '26 May 2027', 'National Institute of Electronics and Information Technology (NIELIT)', 'Examination Wing, NIELIT Headquarters,  National Institute of Electronics and Information Technology (NIELIT) NIELIT Bhawan, Plot No 3, PSP Pocket, Institutional Area, Sector-8, Dwarka, South West Delhi, Delhi -110077', 'i.	Freelancer (self-employed)
ii.	Full Stack Developer
iii.	Data Scientist/ Data Analyst
iv.	IoT Architect
v.	IoT Developer
vi.	Business Intelligence Analyst
vii.	Information Security Analyst
viii.	Training Faculty', 'Academic:
‘A’ level->’B’ Level 
Professional: -
- Full Stack Developer/ Full Stack Web Developer-> Sr Full Stack Web Developer-> Project Manager
- Data Scientist/Analyst-> Big Data Analytics Architect-> Analytics Manager
-IoT Developer/ Architect -> Sr. IoT Developer/ Architect-> Chief Internet of Things Officer (CIoTO).
- Business Intelligence Analyst -> Business Intelligence Manager-> Business Intelligence Director
- Information Security Analyst-> Information Security Engineer-> Security Architect, IT-> Director of IT Security
-Training Faculty-> Sr Faculty-> Head of Dept
- Freelancer (self- employed/ Entrepreneur)
Age: No Bar', 'Future Skills Qualification', 'N.A.', '{"Theory":"480","Practical":"720","EmployabilitySkills":"0","OJT_Mandatory":"420"}', false, '{}'::text[], '{"source_row": "4", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/ITES/NIELIT/06122', 'Computer Applications Associate  (CAA)', 'it-ites', 'IT-ITeS', 4.0, 'A person who has completed CAA can apply as a computer operator in any firm, can get placed at clerical levels like receptionist, computer operator or cyber café owner, can also work at BPO. CAA certificate holder can execute basic computer tasks and can also become a computer teacher at primary level or can also own Computer teaching Centre for children or adults who wish to learn computer basics.', 450, 450, '401–600', 'Version', '28 Jul 2022', '28 Jul 2025', 'National Institute of Electronics and Information Technology (NIELIT)', 'National Institute of Electronics and  Information Technology, NIELIT Bhawan, Plot No. 3, PSP Pocket, Sector-8, Dwarka, New Delhi-110 077.', 'Office Assistant / Assistant Multimedia Content Creator / Assistant Computer Technician, Technical Support (Desktop), Assistant Network Administrator, IT Support Staff, Web Designer, Graphics Designer, Data Entry Operator, Computer Instructor', 'Professional: Senior Technician 🡪Programmer 🡪 Project Leader  🡪 Project Manager  🡪  Senior manager(Project Planning)
Academic:
NIELIT A level 🡪 B   Level 🡪 C level 
After completion of the course, student can go for further specialised course in Multimedia, Hardware & Networking.', 'General Qualification', 'N.A.', '{"Theory":"150","Practical":"240","EmployabilitySkills":"30","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "5", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/ITES/NIELIT/06334', 'Certified Office Automation and IT Assistant', 'it-ites', 'IT-ITeS', 3.0, '●	A person who has completed Certified Office Automation and IT Assistant (COAITA) can apply as a computer operator, any clerical levels jobs like receptionist, office assistant, computer operator computer teachers at the primary level or become entrepreneurs by running a Computer teaching Centre, BPO etc..', 450, 450, '401–600', 'Version', '25 Aug 2022', '25 Aug 2025', 'National Institute of Electronics and Information Technology (NIELIT)', 'National Institute of Electronics and Information Technology (NIELIT) NIELIT Bhawan, Plot No. 3, PSP Pocket, Sector-8,  Dwarka, New Delhi-110077', '●	Office Assistant /Lower Division Clerk/ Assistant Multimedia Content Creator / Assistant Computer Technician, Assistant Network Administrator, IT Support Staff, Graphics Designer, Data Entry Operator, Computer Instructor', 'Professional: 
Clerical staff→ Data Entry Operator/Junior Technician͢ → Senior Technician → Programmer → Project Leader → Project Manager 
Academic:
IT O level-> IT A level -> IT B level', 'General Qualification', 'N.A.', '{"Theory":"150","Practical":"240","EmployabilitySkills":"30","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "6", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
