INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/ITES/NIELIT/06335', 'IT Application Engineer (B Level - IT)', 'it-ites', 'IT-ITeS', 6.0, 'After undergoing this qualification, candidates will be able to perform primarily following job roles.
i.	Freelancer (For self-employed)
ii.	Full Stack Developer
iii.	Data Scientist/Analyst
iv.	IoT Architect/Developer
v.	Business Intelligence Analyst
vi.	Information Security Analyst
vii.	Training Faculty
viii.	R & D Scientist
ix.	Senior Software Developer
x.	Consultant
xi.	Solution Architect', 2520, 2520, 'Above 2401', 'Version', '25 Aug 2022', '25 Aug 2025', 'National Institute of Electronics and Information Technology (NIELIT)', 'National Institute of Electronics and Information Technology (NIELIT) NIELIT Bhawan, Plot No 3, PSP Pocket, Institutional Area, Sector-8, Dwarka, South West Delhi, Delhi -110077', 'i.	Freelancer (self-employed)
ii.	Full Stack Developer
iii.	Data Scientist/ Data Analyst
iv.	IoT Architect
v.	IoT Developer
vi.	Business Intelligence Analyst
vii.	Information Security Analyst
viii.	Training Faculty
ix.	R & D Scientist
x.	Senior Software Developer
xi.	Consultant
xii.	Solution Architect', 'Academic:
C-Level IT-> M.Tech (CS)->Ph.D
Professional: -
- Full Stack Developer/ Full Stack Web Developer-> Sr Full Stack Web Developer-> Project Manager
- Data Scientist/Analyst-> Big Data Analytics Architect-> Analytics Manager
-IoT Developer/ Architect -> Sr. IoT Developer/ Architect-> Chief Internet of Things Officer
- Business Intelligence Analyst -> Business Intelligence Manager-> Business Intelligence Director
- Information Security Analyst-> Information Security Engineer-> Security Architect, IT-> Director of IT Security
