INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-05-IT-01416-2023-V1-NASSCOM', 'Concepts of Computer Vision', 'it-ites', 'IT-ITeS', 5.0, 'Develop and implement Computer Vision solutions and applications that leverage AI/ML to interpret and analyze visual information', 90, 90, '1–200', 'Version', '30 Apr 2024', '30 Apr 2027', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'IT-ITeS SSC NASSCOM', 'Artificial Intelligence and Big Data Analytics', 'AI- Solution Architect, AI- Data Architect', 'Future Skills Qualification,National Occupational Standard', 'N.A.', '{"Theory":"30","Practical":"30","EmployabilitySkills":"0","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "84", "qualification_type": "Future Skills Qualification,National Occupational Standard", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-IT-02180-2024-V1-NIELIT', 'Scientific Assistant in Data Science for Life Sciences', 'it-ites', 'IT-ITeS', 4.0, 'Nature: 
❖	This Short-term Certificate Course is targeted at creating qualified professionals in the field of Bioinformatics, which will help in the employment or Entrepreneurship development of the qualifier.
❖	This Qualification is aligned to Level 4.

Purpose:
The purpose of this qualification is to train the students of Life Sciences with the basics of Bioinformatics to skill them and increase their employability in the field of Life Sciences and allied disciplines.', 450, 450, '401–600', 'Version', '15 Mar 2024', '15 Mar 2027', 'National Institute of Electronics and Information Technology (NIELIT)', 'National Institute of Electronics and Information Technology', 'Scientific Assistant', 'Academic:
Horizontal: 
Level 4: Bioinformatics ‘O’ Level/ Level 4 Course in Basic Bioinformatics
/Level 4 in IT/Bio-IT.

Vertical:
Level 5: Bioinformatics ‘A’ Level /Advanced-level Bioinformatics Courses like Translational Bioinformatics Associate /Higher level courses in Python Programming using AI/ML
  
Professional: 
Scientific Assistant in Data Science for Life Sciences -> Analyst -> Database curator in industries -> Laboratory Assistant/Junior Technician in Bioinformatics/ Biotechnology/ Molecular Biology/ Drug Discovery/ Pharmaceutical R & D lab', 'Cross Sectoral Qualification,Future Skills Qualification', 'N.A.', '{"Theory":"150","Practical":"210","EmployabilitySkills":"60","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "85", "qualification_type": "Cross Sectoral Qualification,Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-05-IT-02098-2024-V1-NASSCOM', 'Software Container Administration Specialist', 'it-ites', 'IT-ITeS', 5.0, 'Containers have quickly become the de facto solution for agile development and application deployment. Administrators and developers are seeking additional ways to improve application time-to-market and improve maintainability. This course provides the gateway to organizational and digital transformation by providing a comprehensive look at the potential of DevOps using a container-based architecture. 
As a result of attending this course, learners will understand the architecture of Red Hat OpenShift clusters and of Kubernetes applications, and will be able to deploy, manage, and troubleshoot applications on OpenShift. Learners will also be able to identify and escalate application and infrastructure issues to development teams, operation teams, and IT vendors.', 96, 96, '1–200', 'Version', '31 Jan 2024', '31 Jan 2027', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'IT-ITeS SSC nasscom', 'Cloud Computing', 'Enterprise Kubernetes Administration Specialist or OpenShift Administrator', 'Future Skills Qualification,OEM Qualification', 'N.A.', '{"Theory":"43","Practical":"53","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "86", "qualification_type": "Future Skills Qualification,OEM Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-05-IT-02097-2024-V1-NASSCOM', 'Linux Administrator for Datacenter', 'it-ites', 'IT-ITeS', 5.0, 'This course provides the learner with a solid foundation in Linux system administration, for improved ability to manage their infrastructure efficiently. It helps to provide better system reliability, improve efficient system and storage utilization, and respond faster and more accurately to system failures. This course will lay the foundation for new Linux system administrators to efficiently and securely resolve configuration issues, integrate Red Hat Enterprise Linux with other existing systems, manage user and group administration, and use available storage solutions.', 96, 96, '1–200', 'Version', '31 Jan 2024', '31 Jan 2027', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'IT-ITeS SSC nasscom', 'Cloud Computing', 'IT Automation Engineer or Cloud Support Engineer', 'Future Skills Qualification,OEM Qualification', 'N.A.', '{"Theory":"40","Practical":"56","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "87", "qualification_type": "Future Skills Qualification,OEM Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-4.5-IT-02240-2024-V1-NASSCOM', 'Data Analysis – IBM', 'it-ites', 'IT-ITeS', 4.5, 'Prepare for a career in the high-growth field of data analytics. In this program, you’ll learn in-demand skills like Python, Excel, and SQL to get job-ready in as little as 4 months. No prior experience or degree needed. Data analysis is the process of collecting, storing, modeling, and analyzing data that can inform executive decision-making, and the demand for skilled data analysts has never been greater. This program will teach you the foundational data skills employers are seeking for entry-level data analytics roles. It will not only help you start your career in data analytics, but also provides a strong foundation for future career development in other paths such as data science, artificial intelligence, deep learning, or data engineering. You’ll learn the latest skills and tools used by professional data analysts including Excel spreadsheets, Python, Pandas, Numpy, Jupyter Notebooks, Cognos Analytics, and more. You’ll work with a variety of data sources and project scenarios to gain practical experience with data manipulation and applying analytical skills. When you complete the full program, you’ll have a portfolio of projects and a Professional Certificate from IBM to showcase your expertise. You’ll also earn an IBM Digital badge and will gain access to career resources to help you in your job search, including mock interviews and resume support.', 151, 151, '1–200', 'Version', '15 Mar 2024', '15 Mar 2027', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'IT-ITeS SSC nasscom', 'Artificial Intelligence and Big Data Analytics', 'Data Analytics Manager, BI Developer, Data Manager', 'Future Skills Qualification,OEM Qualification', 'N.A.', '{"Theory":"90","Practical":"61","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "88", "qualification_type": "Future Skills Qualification,OEM Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-4.5-IT-02235-2024-V1-NASSCOM', 'Data Analytics- Google', 'it-ites', 'IT-ITeS', 4.5, 'Learners can earn the Data Analytics Certificate, the equivalent of 4 college courses at the bachelor’s degree level. This aims to help open up additional pathways to learners who are interested in higher education, and prepare them for entry-level jobs.', 187, 187, '1–200', 'Version', '15 Mar 2024', '15 Mar 2027', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'IT-ITeS SSC nasscom', 'Artificial Intelligence and Big Data Analytics', 'Data Analytics Manager, BI Developer, Data Manager', 'Future Skills Qualification,OEM Qualification', 'N.A.', '{"Theory":"112","Practical":"75","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "89", "qualification_type": "Future Skills Qualification,OEM Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-05-IT-02243-2024-V1-NASSCOM', 'Data Engineering – IBM', 'it-ites', 'IT-ITeS', 5.0, 'In this program, you’ll learn in-demand skills like Python, SQL, and Databases to get job-ready in less than 5 months. This program will teach you the foundational data engineering skills employers are seeking for entry level data engineering roles, including Python, one of the most widely used programming languages. You’ll also master SQL, RDBMS, ETL, Data Warehousing, NoSQL, Big Data, and Spark with hands-on labs and projects. You’ll learn to use Python programming language and Linux/UNIX shell scripts to extract, transform and load (ETL) data. You’ll also work with Relational Databases (RDBMS) and query data using SQL statements and use NoSQL databases as well as unstructured data. When you complete the full program, you’ll have a portfolio of projects and a Professional Certificate from IBM to showcase your expertise. You’ll also earn an IBM Digital badge and will gain access to career resources to help you in your job search, including mock interviews and resume support. This program is ACE® recommended—when you complete, you can earn up to 12 college credits.', 217, 217, '201–400', 'Version', '15 Mar 2024', '15 Mar 2027', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'IT-ITeS SSC nasscom', 'Artificial Intelligence and Big Data Analytics', 'Data Architect, Data Engineering Manager', 'Future Skills Qualification,OEM Qualification', 'N.A.', '{"Theory":"130","Practical":"87","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "90", "qualification_type": "Future Skills Qualification,OEM Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-05-IT-02244-2024-V1-NASSCOM', 'Data Science – IBM', 'it-ites', 'IT-ITeS', 5.0, 'This program provides learners with job-ready tools and skills, including open- source tools and libraries, Python, databases, SQL, data visualization, data analysis, statistical analysis, predictive modelling, and machine learning algorithms. Learners will learn data science through hands-on practice in the IBM Cloud using real data science tools and real-world data sets. Upon completing this course courses, graduates have built a portfolio of data science projects to provide them with the confidence to head into an entry-level profession in data science.', 165, 165, '1–200', 'Version', '15 Mar 2024', '15 Mar 2027', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'IT-ITeS SSC nasscom', 'Artificial Intelligence and Big Data Analytics', 'Data Scientist, Data Scientist I, Data Scientist II', 'Future Skills Qualification,OEM Qualification', 'N.A.', '{"Theory":"132","Practical":"33","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "91", "qualification_type": "Future Skills Qualification,OEM Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-05-IT-02241-2024-V1-NASSCOM', 'DevOps programming–IBM', 'it-ites', 'IT-ITeS', 5.0, 'This certificate will equip the learners with the key concepts and technical know-how to build their skills and knowledge of DevOps practices, tools and technologies and prepare them for an entry-level role in Software Engineering. The courses in this program will help them develop skill sets in a variety of DevOps philosophies and methodologies including Agile Development, Scrum Methodology, Cloud Native Architecture, Behavior and Test-Driven Development, and Zero Downtime Deployments. The learners will learn to program with the Python language and Linux shell scripts, create projects in GitHub, containerize and orchestrate their applications using Docker, Kubernetes & OpenShift, compose applications with microservices, employ serverless technologies, perform continuous integration and delivery (CI/CD), develop testcases, ensure their code is secure, and monitor & troubleshoot their cloud deployments. Guided by experts at IBM, they will be prepared for success. Labs and projects in this certificate program are designed to equip job-ready hands-on skills that will help them launch a new career in a highly in-demand field. This professional certificate is suitable for both - those who have none or some programming experience, as well as those with and without college degrees.', 221, 221, '201–400', 'Version', '15 Mar 2024', '15 Mar 2027', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'IT-ITeS SSC nasscom', 'Artificial Intelligence and Big Data Analytics', 'DevOps Engineer, Software Engineer', 'Future Skills Qualification,OEM Qualification', 'N.A.', '{"Theory":"133","Practical":"88","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "92", "qualification_type": "Future Skills Qualification,OEM Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-4.5-IT-02236-2024-V1-NASSCOM', 'Digital Marketing & E-commerce- Google', 'it-ites', 'IT-ITeS', 4.5, 'Learners are supposed to gain in-demand skills that prepare them for an entry-level job. Skills they are supposed to gain include: Developing digital marketing and e-commerce strategies; attracting and engaging customers through digital marketing channels like search and email; measuring marketing analytics and sharing insights; building e-commerce stores, analyzing e-commerce performance, and building customer loyalty. Platforms and tools learners are supposed to gain include: Canva, Constant Contact, Google Ads, Google Analytics, Hootsuite, HubSpot,Mailchimp, Shopify, and Twitter.', 166, 166, '1–200', 'Version', '15 Mar 2024', '15 Mar 2027', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'IT-ITeS SSC nasscom', 'Web & Mobile', 'Marketing Strategist, SEO Manager, E-Commerce Manager', 'Future Skills Qualification,OEM Qualification', 'N.A.', '{"Theory":"133","Practical":"33","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "93", "qualification_type": "Future Skills Qualification,OEM Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-05-IT-02242-2024-V1-NASSCOM', 'Full Stack Software Development-IBM', 'it-ites', 'IT-ITeS', 5.0, 'In this program, you’ll develop the skills, tools, and portfolio to have a competitive edge in the job market as an entry level back-end developer in as little as 6 months. Back-end developers are the experts who build and maintain the mechanisms that process data and perform actions behind websites, and the demand for these professionals has never been greater. You’ll learn the latest tools and technologies used by professional back-end developers, including Linux scripting, Git and GitHub, Python, SQL, Databases, Django, Containers with Docker, Kubernetes, and OpenShift, Microservices, Serverless, as well as Application Security, and Monitoring. You will practice working hands-on with these technologies to build the type of server-side systems and services that power modern web and mobile applications. Upon completing the full program, you will have built a portfolio of projects to provide you with the confidence to excel in your interviews and you’ll receive a Professional Certificate from IBM to showcase your proficiency to potential employers. You will also receive access to join IBM’s Talent Network where you’ll receive job opportunities as soon as they are posted, recommendations matched to your skills and interests, and tips and tricks to help you stand apart from the crowd.', 141, 141, '1–200', 'Version', '15 Mar 2024', '15 Mar 2027', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'IT-ITeS SSC nasscom', 'Web & Mobile', 'IT Project Manager, Software Developer, Cloud Application Developer', 'Future Skills Qualification,OEM Qualification', 'N.A.', '{"Theory":"85","Practical":"56","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "94", "qualification_type": "Future Skills Qualification,OEM Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-05-IT-02237-2024-V1-NASSCOM', 'Project Management- Google', 'it-ites', 'IT-ITeS', 4.5, 'Project managers set the plan, guide teammates, manage changes, risks, and stakeholders. Learners are supposed to gain in-demand skills that prepare them for an entry-level job. Skills learners are supposed to gain include: Creating risk management plans; understanding process improvement techniques; managing escalations, team dynamics, and stakeholders; creating budgets and navigating procurement; utilizing project management software, tools, and templates; practicing agile project management, with an emphasis on Scrum. Learners will get introduced to initiating, planning, and running both traditional and agile projects and develop a toolbox to demonstrate their understanding of key project management elements, including managing a schedule, budget, and team.', 152, 152, '1–200', 'Version', '15 Mar 2024', '15 Mar 2027', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'IT-ITeS SSC nasscom', 'Web & Mobile', 'IT Project Manager, Senior Project Manager, Engineering Manager', 'Future Skills Qualification,OEM Qualification', 'N.A.', '{"Theory":"122","Practical":"30","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "95", "qualification_type": "Future Skills Qualification,OEM Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-4.5-IT-02238-2024-V1-NASSCOM', 'UX Design-Google', 'it-ites', 'IT-ITeS', 4.5, 'User experience (UX) designers focus on the interaction that users have with products, like websites, apps, and physical objects. They make those everyday interactions useful, enjoyable, and accessible. Learners of this course are supposed to gain in-demand skills that prepare them for an entry-level job. Participants will learn how to complete the design process from beginning to end, including: Empathizing with users; defining user pain points; coming up with ideas for design solutions; creating wireframes, mockups, and prototypes; testing designs through usability studies; iterating on designs based on feedback. Participants will create designs on paper and in digital design tools like Figma and Adobe XD. By the end of the certificate program, they will have a professional UX portfolio that includes three end-to-end projects, enabling them to apply for jobs.', 234, 234, '201–400', 'Version', '15 Mar 2024', '15 Mar 2027', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'IT-ITeS SSC nasscom', 'Web & Mobile', 'UI/UX Manager, Product Manager, Product Designer', 'Future Skills Qualification,OEM Qualification', 'N.A.', '{"Theory":"140","Practical":"94","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "96", "qualification_type": "Future Skills Qualification,OEM Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-05-IT-02239-2024-V1-NASSCOM', 'Cybersecurity Analysis-IBM', 'it-ites', 'IT-ITeS', 5.0, 'This program will help learners develop knowledge of cybersecurity analyst tools including data protection; endpoint protection; SIEM; and systems and network fundamentals. They will also learn about key compliance and threat intelligence topics important in today’s cybersecurity landscape. Gain skills for incident responses and forensics with real-world cybersecurity case studies. Learners will also get hands-on experience to develop skills via industry specific and open source Security tools.', 128, 128, '1–200', 'Version', '15 Mar 2024', '15 Mar 2027', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'IT-ITeS SSC nasscom', 'Information and Cyber Security', 'Information Security Analyst, Security Analyst, Cybersecurity Analyst', 'Future Skills Qualification,OEM Qualification', 'N.A.', '{"Theory":"77","Practical":"51","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "97", "qualification_type": "Future Skills Qualification,OEM Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-5.5-IT-02181-2024-V1-NIELIT', 'Multiomics Data Analyst', 'it-ites', 'IT-ITeS', 5.5, 'Nature: 
❖	This Short-term Certificate Course is targeted for creating qualified professionals in the field of Multiomics Data, which will help in employment or Entrepreneurship development of the qualifier in the areas of Health Informatics/ Medical Informatics/ Life Sciences, etc. The individual performs research and designing/reshaping of algorithmic models for identification, troubleshooting, and implementation of improvements to existing pipelines. The person also provides lead scientific, technical and knowledge support for revealing hidden patterns and information in biological big data. S/he is a key contributor in building the drug discovery platform for the future.

Purpose:
The purpose of this qualification is to train the students of Life Sciences with advanced-level Bioinformatics and Multiomics Data to upskill them and increase their employability in the field of Life Sciences and allied disciplines. Employability is described in Annexure-B.', 660, 660, '601–800', 'Version', '15 Mar 2024', '15 Mar 2027', 'National Institute of Electronics and Information Technology (NIELIT)', 'National Institute of Electronics and Information Technology', 'Multiomics Data Analyst', 'Academic: 
Horizontal:
• Postgraduate studies in Bioinformatics
• Higher level Life Science research, i.e., Molecular Biology and Cell Biology
• Level 6 in IT/Bio-IT.
Vertical:
• Doctoral studies in Bioinformatics
• Level 7 Courses in Advanced-level Bioinformatics
• Higher level courses in R Programming for Biological Data Analysis. 
Professional:
Multiomics Data Analyst -> Analyst/programmer -> Database/program developer in industries -> Lead Scientist/Bioinformatician in Biotechnology/ Molecular Biology/ Drug Discovery/ Pharmaceutical R & D lab', 'Cross Sectoral Qualification,Future Skills Qualification', 'N.A.', '{"Theory":"240","Practical":"270","EmployabilitySkills":"90","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "98", "qualification_type": "Cross Sectoral Qualification,Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-IT-01490-2023-V1-GU', 'Associate Data Analyst', 'it-ites', 'IT-ITeS', 5.0, 'The Associate Data Analyst Certification (Level 5.0) is an advanced qualification meticulously designed for ambitious undergraduate engineering students who aspire to excel in the dynamic fields of Artificial Intelligence (AI) and Machine Learning (ML). This program is an exceptional opportunity for students with a solid foundation in STEM to further elevate their skills and become adept at harnessing AI and ML techniques to extract actionable insights from complex datasets. Geared toward participants with STEM background, Level 5.0 of this certification signifies a heightened level of expertise in AI and ML, indicating that students have not only grasped the fundamental concepts but are also well-prepared to dive into more intricate applications. Through this certification, students will develop a deep proficiency in various AI and ML methodologies, tools, algorithms, and programming languages, enabling them to tackle real-world challenges with confidence. By strengthening their skills in AI and ML through this certification, students can effectively contribute to the "Make in India" movement by driving innovation, creating technologically advanced products, and bolstering India''s position as a hub for cutting-edge engineering solutions. At the end of this program, one will emerge as sought-after professionals who can seamlessly integrate AI and ML techniques into engineering practices, contributing significantly to innovation and progress within the IT industry.', 690, 810, '801–1000', 'Version', '14 Sep 2023', '13 Sep 2026', 'Ganpat University', 'GANPAT UNIVERSITY', 'The Associate Data Analyst Certification (Level 5.0) is an advanced qualification meticulously designed for ambitious undergraduate engineering students who aspire to excel in the dynamic fields of Artificial Intelligence (AI) and Machine Learning (ML). This program is an exceptional opportunity for students with a solid foundation in STEM to further elevate their skills and become adept at harnessing AI and ML techniques to extract actionable insights from complex datasets.', 'ACADEMIC PROGRESSION After completion of the course he/she can be awarded CERTIFICATE IN Associate Data Analyst (LEVEL 5.0), Further he/she can enroll for vertical progression for UG degree in AI-ML or equivalent (Level 5.5), which can pave the way for PG degree in related programmes. PROFESSIONAL PROGRESSION An Associate Data Analyst can work in Industry for 3 years and with some industry certifications, one can progress to Data Scientist, and further 3 years of experience along with training/certification, one can progress to Data Science Architect.', 'Dual/Flexi Qualification,Future Skills Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"163","Practical":"327","EmployabilitySkills":"60","OJT_Mandatory":"80"}', false, '{}'::text[], '{"source_row": "99", "qualification_type": "Dual/Flexi Qualification,Future Skills Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-05-IT-02727-2024-V1-NASSCOM', 'Exploratory Data Analysis', 'it-ites', 'IT-ITeS', 5.0, 'This NOS is about using a variety of techniques to perform exploratory analysis to describe and summarize data for internal and external clients.', 45, 45, '1–200', 'Version', '30 May 2024', '30 May 2027', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'IT-ITeS SSC NASSCOM', 'Artificial Intelligence and Big Data Analytics', 'After completing this program participants can upskill themselves and apply the knowledge in their application areas.', 'Future Skills Qualification,National Occupational Standard', 'N.A.', '{"Theory":"15","Practical":"30","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "100", "qualification_type": "Future Skills Qualification,National Occupational Standard", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
