INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-05-IT-02658-2024-V1-HCL', 'Essentials of System Administration with Linux OS', 'it-ites', 'IT-ITeS', 5.0, 'A Linux System Administrator is responsible for the design, implementation, and maintenance of Linux-based systems. They ensure the security, stability, and performance of servers and networks. The role involves troubleshooting, system monitoring, and collaborating with other IT professionals.', 210, 210, '201–400', 'Version', '30 May 2024', '30 May 2027', 'HCL Technologies', 'HCL Technologies Ltd. Name: Shanthi Venkatraman Designation: Global Lead - Customer Assurance Email: shanthi.venkatraman@hcl.com Contact No.: +91 9600122611 Website: https://www.hcltech.com/', 'Computer Network and Systems Technician', 'Linux System Engineer, IT Infrastructure Manager, Network Security Specialist', 'Multi-Skill Qualification', 'N.A.', '{"Theory":"90","Practical":"120","EmployabilitySkills":"00","OJT_Mandatory":"00"}', false, '{}'::text[], '{"source_row": "110", "qualification_type": "Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
