INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-05-IT-02678-2024-V1-HCL', 'Essentials of Cyber Safety for Professionals', 'it-ites', 'IT-ITeS', 5.0, 'A Cyber-aware professional implements and maintains robust cybersecurity measures, identifying and mitigating potential threats to safeguard organizational digital assets. They stay updated on the latest cyber threats, technologies, and best practices to ensure a resilient and secure digital environment.', 7, 7, '1–200', 'Version', '30 May 2024', '30 May 2027', 'HCL Technologies', 'HCL Technologies Ltd. Name: Shanthi Venkatraman Designation: Global Lead - Customer Assurance Email: shanthi.venkatraman@hcl.com Contact No.: +91 9600122611 Website: https://www.hcltech.com/', 'All professionals', 'Cyber-aware professional', 'Multi-Skill Qualification', 'N.A.', '{"Theory":"4.5","Practical":"3","EmployabilitySkills":"00","OJT_Mandatory":"00"}', false, '{}'::text[], '{"source_row": "117", "qualification_type": "Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-03-IT-02679-2024-V1-HCL', 'Introduction to Cyber Security for Women', 'it-ites', 'IT-ITeS', 3.0, 'As a Cyber-aware woman, one is dedicated to promoting digital safety and security, actively participating in cybersecurity initiatives. Through knowledge and awareness, she contributes to a safer online environment while inspiring and empowering others in the cybersecurity community.', 7, 7, '1–200', 'Version', '30 May 2024', '30 May 2027', 'HCL Technologies', 'HCL Technologies Ltd. Name: Shanthi Venkatraman Designation: Global Lead - Customer Assurance Email: shanthi.venkatraman@hcl.com Contact No.: +91 9600122611 Website: https://www.hcltech.com/', 'Women', 'Cyber-aware women', 'Multi-Skill Qualification', 'N.A.', '{"Theory":"4.5","Practical":"3","EmployabilitySkills":"00","OJT_Mandatory":"00"}', false, '{}'::text[], '{"source_row": "118", "qualification_type": "Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-03-IT-02680-2024-V1-HCL', 'Introduction to Cyber Security for students', 'it-ites', 'IT-ITeS', 3.0, 'A Cyber-aware student actively engages in learning and implementing cybersecurity principles, demonstrating a commitment to responsible online behavior and promoting digital safety within the academic community.', 7, 7, '1–200', 'Version', '30 May 2024', '30 May 2027', 'HCL Technologies', 'HCL Technologies Ltd. Name: Shanthi Venkatraman Designation: Global Lead - Customer Assurance Email: shanthi.venkatraman@hcl.com Contact No.: +91 9600122611 Website: https://www.hcltech.com/', 'Students', 'Cyber-aware student', 'Multi-Skill Qualification', 'N.A.', '{"Theory":"4.5","Practical":"3","EmployabilitySkills":"00","OJT_Mandatory":"00"}', false, '{}'::text[], '{"source_row": "119", "qualification_type": "Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-05-IT-02681-2024-V1-HCL', 'Essentials of Cyber Security for lawyers', 'it-ites', 'IT-ITeS', 3.0, 'A Cyber-aware lawyer specializes in advising clients on legal aspects of cybersecurity, ensuring compliance with data protection laws, and representing clients in cases related to cybercrimes or breaches. They stay updated on evolving regulations and work to protect clients from legal implications arising in the digital realm.', 7, 7, '1–200', 'Version', '30 May 2024', '30 May 2027', 'HCL Technologies', 'HCL Technologies Ltd. Name: Shanthi Venkatraman Designation: Global Lead - Customer Assurance Email: shanthi.venkatraman@hcl.com Contact No.: +91 9600122611 Website: https://www.hcltech.com/', 'Lawyers', 'Cyber-aware lawyer', 'Multi-Skill Qualification', 'N.A.', '{"Theory":"4.5","Practical":"3","EmployabilitySkills":"00","OJT_Mandatory":"00"}', false, '{}'::text[], '{"source_row": "120", "qualification_type": "Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-05-IT-02659-2024-V1-HCL', 'Essentials of Automation Testing with Scripting', 'it-ites', 'IT-ITeS', 5.0, '1. Individuals in this job are responsible for designing, implementing, and maintaining test automation frameworks that leverage artificial intelligence and machine learning technologies.
2. Primary focus will be on ensuring the robustness, efficiency, and reliability of software applications through the application of AI-driven testing techniques. Collaborate closely with development and quality assurance teams to enhance test processes and contribute to the overall software testing strategy.', 210, 210, '201–400', 'Version', '30 May 2024', '30 May 2027', 'HCL Technologies', 'HCL Technologies Ltd. Name: Shanthi Venkatraman Designation: Global Lead - Customer Assurance Email: shanthi.venkatraman@hcl.com Contact No.: +91 9600122611 Website: https://www.hcltech.com/', 'Software and Application Developers and Analysts', 'AI Test Engineer, Senior AI Test Engineer, AI Test Architect', 'Cross Sectoral Qualification,Future Skills Qualification,Multi-Skill Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"70","Practical":"130","EmployabilitySkills":"00","OJT_Mandatory":"00"}', false, '{}'::text[], '{"source_row": "121", "qualification_type": "Cross Sectoral Qualification,Future Skills Qualification,Multi-Skill Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-4.5-IT-02682-2024-V1-HCL', 'Essentials of Agile Testing Methodologies', 'it-ites', 'IT-ITeS', 4.5, 'Agile Testing Engineer, you will play a crucial role in ensuring the quality and reliability of software products developed using agile methodologies. They will work closely with cross-functional agile teams to plan, execute, and automate tests throughout the software development lifecycle, focusing on delivering high-quality software increments iteratively.', 7, 7, '1–200', 'Version', '30 May 2024', '30 May 2027', 'HCL Technologies', 'HCL Technologies Ltd. Name: Shanthi Venkatraman Designation: Global Lead - Customer Assurance Email: shanthi.venkatraman@hcl.com Contact No.: +91 9600122611 Website: https://www.hcltech.com/', 'Software and Application Developers and Analysts', 'Test Engineer, Senior Test Engineer, Test Architect', 'Multi-Skill Qualification', 'N.A.', '{"Theory":"4","Practical":"3.5","EmployabilitySkills":"00","OJT_Mandatory":"00"}', false, '{}'::text[], '{"source_row": "122", "qualification_type": "Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-4.5-IT-02683-2024-V1-HCL', 'Essentials of Test Planning and Progress Monitoring', 'it-ites', 'IT-ITeS', 4.5, 'Automation tester develops test plan document that provides the software lifecycle, schedule roles and responsibilities, and the progress of the project based on the requirements.', 7, 7, '1–200', 'Version', '30 May 2024', '30 May 2027', 'HCL Technologies', 'HCL Technologies Ltd. Name: Shanthi Venkatraman Designation: Global Lead - Customer Assurance Email: shanthi.venkatraman@hcl.com Contact No.: +91 9600122611 Website: https://www.hcltech.com/', 'Software and Application Developers and Analysts', 'Test Engineer, Senior Test Engineer, Test Architect', 'Multi-Skill Qualification', 'N.A.', '{"Theory":"4","Practical":"3.5","EmployabilitySkills":"00","OJT_Mandatory":"00"}', false, '{}'::text[], '{"source_row": "123", "qualification_type": "Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-05-IT-02684-2024-V1-HCL', 'Getting started with Python Scripts for Automation Testing', 'it-ites', 'IT-ITeS', 5.0, 'Will be responsible for designing, developing, and executing automated test scripts using Python and related libraries/frameworks. He will work closely with the QA team to ensure the quality and reliability of software products through efficient automation testing practices.', 7, 7, '1–200', 'Version', '30 May 2024', '30 May 2027', 'HCL Technologies', 'HCL Technologies Ltd. Name: Shanthi Venkatraman Designation: Global Lead - Customer Assurance Email: shanthi.venkatraman@hcl.com Contact No.: +91 9600122611 Website: https://www.hcltech.com/', 'Software and Application Developers and Analysts', 'Test Engineer, Senior Test Engineer, Test Architect', 'Multi-Skill Qualification', 'N.A.', '{"Theory":"3","Practical":"4.5","EmployabilitySkills":"00","OJT_Mandatory":"00"}', false, '{}'::text[], '{"source_row": "124", "qualification_type": "Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-4.5-IT-02685-2024-V1-HCL', 'Introduction to Integration, System and Acceptance Testing', 'it-ites', 'IT-ITeS', 4.5, 'As an Integration, System, and Acceptance Testing Engineer, they will be responsible for planning, designing, executing, and documenting integration, system, and acceptance tests for software products.  They will work closely with cross-functional teams to ensure that software solutions meet quality standards and functional requirements.', 7, 7, '1–200', 'Version', '30 May 2024', '30 May 2027', 'HCL Technologies', 'HCL Technologies Ltd. Name: Shanthi Venkatraman Designation: Global Lead - Customer Assurance Email: shanthi.venkatraman@hcl.com Contact No.: +91 9600122611 Website: https://www.hcltech.com/', 'Software and Application Developers and Analysts', 'AI Test Engineer, Senior AI Test Engineer, AI Test Architect', 'Multi-Skill Qualification', 'N.A.', '{"Theory":"4","Practical":"3.5","EmployabilitySkills":"00","OJT_Mandatory":"00"}', false, '{}'::text[], '{"source_row": "125", "qualification_type": "Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-4.5-IT-02686-2024-V1-HCL', 'Essentials of Defect Life Cycle Management', 'it-ites', 'IT-ITeS', 4.5, 'Responsible for overseeing the entire defect lifecycle and ensuring effective tracking and resolution of defects identified during the software development process. You will work closely with cross-functional teams to identify, prioritize, and resolve defects to ensure the delivery of high-quality software products.', 7, 7, '1–200', 'Version', '30 May 2024', '30 May 2027', 'HCL Technologies', 'HCL Technologies Ltd. Name: Shanthi Venkatraman Designation: Global Lead - Customer Assurance Email: shanthi.venkatraman@hcl.com Contact No.: +91 9600122611 Website: https://www.hcltech.com/', 'Software and Application Developers and Analysts', 'Test Engineer, Senior Test Engineer, Test Architect', 'Multi-Skill Qualification', 'N.A.', '{"Theory":"4","Practical":"3.5","EmployabilitySkills":"00","OJT_Mandatory":"00"}', false, '{}'::text[], '{"source_row": "126", "qualification_type": "Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-05-IT-02687-2024-V1-HCL', 'Foundation of Data Engineering', 'it-ites', 'IT-ITeS', 5.0, 'In the role of data engineer, one should understand data engineering fundamentals.', 30, 30, '1–200', 'Version', '30 May 2024', '30 May 2027', 'HCL Technologies', 'HCL Technologies Ltd. Name: Shanthi Venkatraman Designation: Global Lead - Customer Assurance Email: shanthi.venkatraman@hcl.com Contact No.: +91 9600122611 Website: https://www.hcltech.com/', 'Database designers and Administrators', 'Data Engineer, Data Analyst, Data Scientist, Principal Data Scientist', 'Multi-Skill Qualification', 'N.A.', '{"Theory":"15","Practical":"15","EmployabilitySkills":"00","OJT_Mandatory":"00"}', false, '{}'::text[], '{"source_row": "127", "qualification_type": "Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-05-IT-02688-2024-V1-HCL', 'Essentials of Python programming and libraries to work with data', 'it-ites', 'IT-ITeS', 5.0, 'In the role of data engineer, one should understand python programming and data structures, implementing advanced python libraries.', 30, 30, '1–200', 'Version', '30 May 2024', '30 May 2027', 'HCL Technologies', 'HCL Technologies Ltd. Name: Shanthi Venkatraman Designation: Global Lead - Customer Assurance Email: shanthi.venkatraman@hcl.com Contact No.: +91 9600122611 Website: https://www.hcltech.com/', 'Database designers and Administrators', 'Data Engineer, Data Analyst, Data Scientist, Principal Data Scientist', 'Multi-Skill Qualification', 'N.A.', '{"Theory":"12","Practical":"18","EmployabilitySkills":"00","OJT_Mandatory":"00"}', false, '{}'::text[], '{"source_row": "128", "qualification_type": "Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-05-IT-02689-2024-V1-HCL', 'SQL and NoSQL for Beginners', 'it-ites', 'IT-ITeS', 5.0, 'In the role of data engineer, one should understand SQL/NoSQL databases, understanding schema, tables and relations, work with structured and unstructured data.', 30, 30, '1–200', 'Version', '30 May 2024', '30 May 2027', 'HCL Technologies', 'HCL Technologies Ltd. Name: Shanthi Venkatraman Designation: Global Lead - Customer Assurance Email: shanthi.venkatraman@hcl.com Contact No.: +91 9600122611 Website: https://www.hcltech.com/', 'Database designers and Administrators', 'Data Engineer, Data Analyst, Data Scientist, Principal Data Scientist', 'Multi-Skill Qualification', 'N.A.', '{"Theory":"15","Practical":"15","EmployabilitySkills":"00","OJT_Mandatory":"00"}', false, '{}'::text[], '{"source_row": "129", "qualification_type": "Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-3.5-IT-02917-2024-V1-DGT', 'INTRODUCTION TO ARTIFICIAL INTELLIGENCE (AI)', 'it-ites', 'IT-ITeS', 3.5, 'Referring to the framework and knowledge progression, a curriculum framework for the 7.5 hours course tailored to the ''AI for All'' category has been prepared. This course aims to augment the existing 120-hour employability skills curriculum with fundamental AI knowledge. The NOS aims to gain a basic understanding of AI, explore generative AI tools in creating various digital content and understand responsible use of AI.', 7, 7, '1–200', 'Version', '25 Jul 2024', '24 Jul 2027', 'Directorate General of Training (DGT)', 'DGT', 'INTRODUCTION TO ARTIFICIAL INTELLIGENCE (AI)', 'AI Professionals', 'Micro Credentials', 'N.A.', '{"Theory":"4.0","Practical":"3.5","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "130", "qualification_type": "Micro Credentials", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
