INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-05-IT-02700-2024-V1-HCL', 'Foundation of Object Oriented Programming using Java', 'it-ites', 'IT-ITeS', 5.0, 'Foundation of Object Oriented Programming using Java module will enable learners to design and develop code using OOPS concepts in line with customer requirements. Understand and implement Java based OOPs principles, apply the required logic to provide a solution for the problems, utilize classes and objects as fundamental building blocks. Implement concept of interfaces to solve exercises, participate in discussion of threads and multi-threading, implement exception handling to create fail safe code.', 30, 30, '1–200', 'Version', '30 May 2024', '30 May 2027', 'HCL Technologies', 'HCL Technologies Ltd. Name: Shanthi Venkatraman Designation: Global Lead - Customer Assurance Email: shanthi.venkatraman@hcl.com Contact No.: +91 9600122611 Website: https://www.hcltech.com/', 'Web developer', 'Java Web Developer, Full Stack Developer, Product Developer, Solution Architect', 'Multi-Skill Qualification', 'N.A.', '{"Theory":"12","Practical":"18","EmployabilitySkills":"00","OJT_Mandatory":"00"}', false, '{}'::text[], '{"source_row": "142", "qualification_type": "Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-05-IT-02701-2024-V1-HCL', 'Essentials of Oracle SQL and Data base connectivity using JDBC', 'it-ites', 'IT-ITeS', 5.0, 'Working with Oracle SQL and Database connectivity using JDBC entails mastering SQL queries for Oracle databases and establishing connections to databases using JDBC in Java applications. This involves querying data, performing transactions, and managing connections, enabling seamless integration of database functionality into Java programs. Through this process, developers gain the ability to manipulate and interact with Oracle databases effectively within their Java applications.', 30, 30, '1–200', 'Version', '30 May 2024', '30 May 2027', 'HCL Technologies', 'HCL Technologies Ltd. Name: Shanthi Venkatraman Designation: Global Lead - Customer Assurance Email: shanthi.venkatraman@hcl.com Contact No.: +91 9600122611 Website: https://www.hcltech.com/', 'Web developer', 'Java Web Developer, Full Stack Developer, Product Developer, Solution Architect', 'Multi-Skill Qualification', 'N.A.', '{"Theory":"12","Practical":"18","EmployabilitySkills":"00","OJT_Mandatory":"00"}', false, '{}'::text[], '{"source_row": "143", "qualification_type": "Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
