INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-05-IT-02997-2024-V1-NASSCOM', 'Digital Application Fundamental Professional Skills', 'it-ites', 'IT-ITeS', 5.0, 'This micro credential course aims to impart fundamental and essential professional skills in the field of digital application. It will help the trainees to achieve foundational skills crucial for modern professional environments.', 7, 7, '1–200', 'Version', '27 Aug 2024', '27 Aug 2027', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'IT-ITeS SSC NASSCOM', 'Design Thinking', 'N/A', 'Micro Credentials', 'N.A.', '{"Theory":"5","Practical":"2.5","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "151", "qualification_type": "Micro Credentials", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-05-IT-02996-2024-V1-NASSCOM', 'Digital Application Fundamentals Responsible AI', 'it-ites', 'IT-ITeS', 5.0, 'This MC will help learners to know ethics of AI and guidelines to use AI responsibly.', 7, 7, '1–200', 'Version', '27 Aug 2024', '27 Aug 2027', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'IT-ITeS SSC NASSCOM', 'Others,AI', 'N/A', 'Micro Credentials', 'N.A.', '{"Theory":"5","Practical":"2.5","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "152", "qualification_type": "Micro Credentials", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-05-IT-02984-2024-V1-NASSCOM', 'Cloud Computing Foundations Google', 'it-ites', 'IT-ITeS', 5.0, 'This program provides individuals with little to no background or experience in cloud computing a detailed overview of concepts covering cloud basics, big data, and machine learning and where and how Google Cloud fits in. The course starts with an overview of cloud computing and dives deeper into two areas - cloud computing infrastructure, and big data and machine learning. It enables learners to develop technical proficiency in cloud computing and launch or pivot to careers in a cloud-first world.', 60, 60, '1–200', 'Version', '27 Aug 2024', '27 Aug 2027', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'IT-ITeS SSC NASSCOM', 'Cloud Computing', 'Cloud Developer -> Cloud DevOps Engineer,
Cloud Developer -> Senior Cloud Developer -> Cloud Solutions Architect', 'National Occupational Standard', 'N.A.', '{"Theory":"35","Practical":"25","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "153", "qualification_type": "National Occupational Standard", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-5.5-IT-02983-2024-V1-NASSCOM', 'Cloud Cybersecurity Google', 'it-ites', 'IT-ITeS', 5.5, 'This learning path consists of a curated collection of on-demand courses that provide authentic, interactive experience using Google Cloud technologies essential to roles in cybersecurity. Cloud security analysts are uniquely positioned as the first line of defense in protecting organizational cloud assets from a wide array of cyber-related crimes. To aid in the fight against these costly and invasive attacks on digital data and cloud infrastructure, cloud security analysts frequently focus their attention on identifying threats, risks, and vulnerabilities. Then, they respond to and defend against a variety of security incidents that can harm organizations.', 90, 90, '1–200', 'Version', '27 Aug 2024', '27 Aug 2027', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'IT-ITeS SSC NASSCOM', 'Cloud Computing', 'Cloud Security Analyst -> Cloud Security Engineer -> Senior Cloud Security,
Engineer/Architect -> Cloud Security Manager', 'National Occupational Standard', 'N.A.', '{"Theory":"70","Practical":"20","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "154", "qualification_type": "National Occupational Standard", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-5.5-IT-02982-2024-V1-NASSCOM', 'Cloud Data Analytics Google', 'it-ites', 'IT-ITeS', 5.5, 'This learning path consists of a curated collection of on-demand courses that provide authentic, interactive experiences using Google Cloud technologies essential to roles in data analytics. A cloud data analyst uses cloud computing to prepare, process, and analyze data to support business decisions. Cloud data analysts play a critical role in translating complex data for stakeholders, enabling data-driven decision making that directly impacts business outcomes.', 90, 90, '1–200', 'Version', '27 Aug 2024', '27 Aug 2027', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'IT-ITeS SSC NASSCOM', 'Cloud Computing', '1. Cloud Data Analyst -> Senior Cloud Data Analyst -> Lead Cloud Data Analyst -> Lead Cloud Data Manager
2. Cloud Data Analyst -> Cloud Data Engineer -> Senior Cloud Data Engineer -> Cloud Solutions Architect', 'National Occupational Standard', 'N.A.', '{"Theory":"67","Practical":"23","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "155", "qualification_type": "National Occupational Standard", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-5.5-IT-02981-2024-V1-NASSCOM', 'Cloud Engineering Google', 'it-ites', 'IT-ITeS', 5.5, 'A Cloud Engineer plans, configures, sets up, and deploys cloud solutions. This learning path guides you through a curated collection of on-demand courses, labs, and skill badges that provide you with real-world, hands-on experience using Google Cloud technologies essential to the Cloud Engineering role. Once learners complete the path, they can check out the Google Cloud Associate Cloud Engineer certification to take the next steps in their professional journey.', 90, 90, '1–200', 'Version', '27 Aug 2024', '27 Aug 2027', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'IT-ITeS SSC NASSCOM', 'Cloud Computing', 'Associate Cloud Engineer -> Cloud Engineer -> Senior Cloud Engineer -> Cloud Solutions Architect', 'National Occupational Standard', 'N.A.', '{"Theory":"55","Practical":"35","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "156", "qualification_type": "National Occupational Standard", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-05-IT-02987-2024-V1-HCL', 'Essentials of Embedded & IoT Development', 'it-ites', 'IT-ITeS', 5.0, 'Embedded IoT Developer for Sustainability Solutions develops embedded systems and IoT solutions to address environmental challenges, integrating renewable energy sources and optimizing resource usage for sustainable development.', 210, 210, '201–400', 'Version', '27 Aug 2024', '27 Aug 2027', 'HCL Technologies', 'HCL Technologies Ltd. Name: Shanthi Venkatraman Designation: Global Lead - Customer Assurance Email: shanthi.venkatraman@hcl.com Contact No.: +91 9600122611 Website: https://www.hcltech.com/', 'Embedded IOT Developer', 'Software Developer, Embedded IOT Developer', 'Multi-Skill Qualification,National Occupational Standard,OEM Qualification', 'N.A.', '{"Theory":"90","Practical":"120","EmployabilitySkills":"00","OJT_Mandatory":"00"}', false, '{}'::text[], '{"source_row": "157", "qualification_type": "Multi-Skill Qualification,National Occupational Standard,OEM Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-05-IT-02988-2024-V1-HCL', 'Essentials of Embedded Development', 'it-ites', 'IT-ITeS', 5.0, 'As an Embedded software engineer, one must develop l software for embedded systems using C and C++, collaboratively with hardware engineers to ensure seamless integration.', 210, 210, '201–400', 'Version', '27 Aug 2024', '27 Aug 2027', 'HCL Technologies', 'HCL Technologies Ltd. Name: Shanthi Venkatraman Designation: Global Lead - Customer Assurance Email: shanthi.venkatraman@hcl.com Contact No.: +91 9600122611 Website: https://www.hcltech.com/', 'Embedded Developer', 'Software Developer, Embedded Developer', 'General Qualification', 'N.A.', '{"Theory":"90","Practical":"120","EmployabilitySkills":"00","OJT_Mandatory":"00"}', false, '{}'::text[], '{"source_row": "158", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-05-IT-02989-2024-V1-HCL', 'Essentials of VLSI Design', 'it-ites', 'IT-ITeS', 5.0, 'As a VLSI design engineer, one must develop algorithms and methodologies for optimizing VLSI designs, collaborate with cross-functional teams to enhance VLSI performance and efficiency.', 210, 210, '201–400', 'Version', '27 Aug 2024', '27 Aug 2027', 'HCL Technologies', 'HCL Technologies Ltd. Name: Shanthi Venkatraman Designation: Global Lead - Customer Assurance Email: shanthi.venkatraman@hcl.com Contact No.: +91 9600122611 Website: https://www.hcltech.com/', 'VLSI Design Engineer', 'Design Engineer, VLSI Design Engineer', 'General Qualification,National Occupational Standard', 'N.A.', '{"Theory":"90","Practical":"120","EmployabilitySkills":"00","OJT_Mandatory":"00"}', false, '{}'::text[], '{"source_row": "159", "qualification_type": "General Qualification,National Occupational Standard", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-5.5-IT-02914-2024-V1-MSME', 'Fundamentals of SAP Business One', 'it-ites', 'IT-ITeS', 5.5, 'After completion of the course trainees will be able to manage, director of a small company and want to implement a new software solution to make your business processes more efficient. He/she can able to use different tool effectively run business processes.', 90, 90, '1–200', 'Version', '27 Aug 2024', '27 Aug 2027', 'MSME Technology Centre, Ministry of Micro Small And Medium Enterprises, New Delhi', 'MSME TECHNOLOGY CENTRE', 'Applications Programmers', 'Manager', 'Cross Sectoral Qualification,Future Skills Qualification,Multi-Skill Qualification', 'N.A.', '{"Theory":"16","Practical":"74","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "160", "qualification_type": "Cross Sectoral Qualification,Future Skills Qualification,Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-05-IT-03357-2024-V1-HCL', 'Essentials of Business Analytics', 'it-ites', 'IT-ITeS', 5.0, 'The "Essentials of Business Analytics with AI" course equips participants with foundational knowledge and practical skills in data analytics, statistical tools, and AI technologies. Through hands-on labs and industry projects, learners explore data extraction, transformation, and cleansing methods, while mastering tools like Excel, with visualization. The course also emphasizes the application of AI and Generative AI for enhancing work productivity. Additionally, participants will engage in real-world projects, applying their knowledge to industry scenarios while ensuring compliance with GDPR regulations.', 90, 90, '1–200', 'Version', '22 Oct 2024', '22 Oct 2027', 'HCL Technologies', 'HCL Technologies Ltd. Name: Shanthi Venkatraman Designation: Global Lead - Customer Assurance Email: shanthi.venkatraman@hcl.com Contact No.: +91 9600122611 Website: https://www.hcltech.com/', 'Business Analyst', 'Executive – Analytics, Sr. Executive - Analytics, Associate Manager - Analytics, Deputy Manager - Analytics, Manager – Analytics, Portfolio Leader – Analytics', 'Cross Sectoral Qualification,Future Skills Qualification', 'N.A.', '{"Theory":"30","Practical":"60","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "161", "qualification_type": "Cross Sectoral Qualification,Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-05-IT-03359-2024-V1-HCL', 'Artificial Intelligence with Large Language Models (AI with LLM)', 'it-ites', 'IT-ITeS', 5.0, 'The " Artificial Intelligence and Larger Language Models Program" provides an in-depth exploration of essential AI techniques, focusing on Generative AI and Large Language Models (LLMs). The course begins with a strong foundation in AI fundamentals, understanding how LLMs are designed, trained, and fine-tuned for various use cases such as text generation, summarization, translation, and question answering. Learners will apply advanced prompt engineering techniques to enhance model performance, followed by mastering the optimization of LLMs to handle complex tasks efficiently. The program introduces ethical considerations in AI, ensuring that AI solutions are developed and deployed responsibly, along with real-world applications for AI-driven tools like chatbots and virtual assistants.', 90, 90, '1–200', 'Version', '22 Oct 2024', '22 Oct 2027', 'HCL Technologies', 'HCL Technologies Ltd. Name: Shanthi Venkatraman Designation: Global Lead - Customer Assurance Email: shanthi.venkatraman@hcl.com Contact No.: +91 9600122611 Website: https://www.hcltech.com/', 'Data Analyst / Scientist', 'Junior AI/ML Engineer, Senior AI/ML Engineer, AI/ML Project Lead, AI Architect/AI Product Manager, Head of AI/LLM Solutions', 'Cross Sectoral Qualification,Future Skills Qualification', 'N.A.', '{"Theory":"30","Practical":"60","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "162", "qualification_type": "Cross Sectoral Qualification,Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-05-IT-03358-2024-V1-HCL', 'Fundamentals of AI and Work productivity tools', 'it-ites', 'IT-ITeS', 5.0, 'The "Fundamentals of AI and Work Productivity Tools" course provides a comprehensive introduction to the essential AI concepts and productivity tools that are transforming modern workplaces. Over the course, learners will explore the power of structured questions to guide AI-driven insights and enhance decision-making, skills to create effective AI prompts for various applications. The course includes training on M365 collaborative tools, emphasizing how these tools can streamline teamwork and communication in a digital environment, fundamentals of data and analytics, along with practical training on various analytics tools, enabling learners to analyze and visualize data effectively. A critical focus is placed on cyber and data security at work, ensuring that participants understand how to protect sensitive information in AI-driven environments.', 90, 90, '1–200', 'Version', '22 Oct 2024', '22 Oct 2027', 'HCL Technologies', 'HCL Technologies Ltd. Name: Shanthi Venkatraman Designation: Global Lead - Customer Assurance Email: shanthi.venkatraman@hcl.com Contact No.: +91 9600122611 Website: https://www.hcltech.com/', 'Office Executive', 'AI Assistant/Office Executive, AI Solutions Engineer, AI Project Manager, Productivity Consultant', 'Cross Sectoral Qualification,Future Skills Qualification,Multi-Skill Qualification', 'N.A.', '{"Theory":"30","Practical":"60","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "163", "qualification_type": "Cross Sectoral Qualification,Future Skills Qualification,Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-05-IT-03360-2024-V1-HCL', 'Essentials of Data Analytics', 'it-ites', 'IT-ITeS', 5.0, 'The "Essentials of Data Analytics" course provides an in-depth exploration of essential data analytics techniques using Python and advanced tools. The course begins with a strong foundation in Python programming, understanding of Python data structures and built-in libraries for handling data efficiently. Learners will apply statistical analysis techniques using Python to interpret and analyze datasets, followed by mastering data visualization to communicate insights effectively. Big Data Analytics, module introduces tools and techniques to manage and analyze large datasets, along with machine learning concepts for predictive analysis and pattern recognition. Participants will also explore Business Intelligence to understand how data-driven strategies influence decision-making across industries.', 90, 90, '1–200', 'Version', '22 Oct 2024', '22 Oct 2027', 'HCL Technologies', 'HCL Technologies Ltd. Name: Shanthi Venkatraman Designation: Global Lead - Customer Assurance Email: shanthi.venkatraman@hcl.com Contact No.: +91 9600122611 Website: https://www.hcltech.com/', 'Data Analyst', 'Jr Data Analyst, Sr. Data Analyst, Associate Manager - Analytics, Deputy Manager - Analytics, Portfolio Leader - Analytics', 'Cross Sectoral Qualification,Future Skills Qualification,Multi-Skill Qualification', 'N.A.', '{"Theory":"30","Practical":"60","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "164", "qualification_type": "Cross Sectoral Qualification,Future Skills Qualification,Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-05-IT-03361-2024-V1-HCL', 'Essentials of Data Centre Networks and Operation Management', 'it-ites', 'IT-ITeS', 5.0, 'Data Center Management program is meticulously crafted to empower learners with the essential competencies needed to embark on a successful career in the field of IT. Recognizing the increasing significance of Data Center management in IT Operations Service Management roles, this program ensures that learners not only acquire technical proficiency but also develop a profound understanding of critical aspects such as security, performance, and compliance with coding standards.', 240, 240, '201–400', 'Version', '22 Oct 2024', '22 Oct 2027', 'HCL Technologies', 'HCL Technologies Ltd. Name: Shanthi Venkatraman Designation: Global Lead - Customer Assurance Email: shanthi.venkatraman@hcl.com Contact No.: +91 9600122611 Website: https://www.hcltech.com/', 'Data Analyst', 'DC Ops Analyst, DC Ops Engineer, IT Operations Service Management Head', 'Multi-Skill Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"120","Practical":"120","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "165", "qualification_type": "Multi-Skill Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
