INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-3.5-IT-03723-2025-V1-NIELIT', 'Fundamentals of Data Curation using Python', 'it-ites', 'IT-ITeS', 3.5, 'The “Data Curation using Python” is designed to equip learners with the essential skills and knowledge required to manage, organize, and maintain data throughout its lifecycle. This course covers key aspects of data curation, including data collection, cleaning, annotation, integration, storage, quality control, and visualization. Students will gain hands-on experience and a solid understanding of the tools and techniques used in the data management field.', 120, 120, '1–200', 'Version', '18 Feb 2025', '18 Feb 2028', 'National Institute of Electronics and Information Technology (NIELIT)', 'National Institute of Electronics and Information Technology (NIELIT)', 'Data Curator Assistant', 'Data Curation Assistant → Data Curation Specialist → Data Analyst → Data Engineer → Data Scientist', 'Future Skills Qualification', 'N.A.', '{"Theory":"45","Practical":"75","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "221", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-IT-03654-2025-V2-NASSCOM', 'IT Customer Care Executive', 'it-ites', 'IT-ITeS', 3.0, 'The IT Customer Care Executive is responsible for addressing customer queries through voice and non-voice channels. They use basic generative artificial intelligence (Gen AI)-based tools and BPM platforms in both voice and non-voice processes. The individual answers customer inquiries, resolves problems, records complaints and collects customer feedback.', 270, 330, '201–400', 'Version', '19 May 2015', '18 Feb 2028', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'Customer Relationship Management (CRM)', 'access to related qualification(s) at the next NSQF level: Associate Customer Care (Voice)', 'Upskilling Qualification', 'N.A.', '{"Theory":"60","Practical":"120","EmployabilitySkills":"30","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "222", "qualification_type": "Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-IT-03649-2025-V2-NASSCOM', 'Junior Software Developer', 'it-ites', 'IT-ITeS', 4.0, 'A Junior Software Developer supports software development activities by writing, testing, and debugging code using basic programming languages such as Python, Java, or JavaScript. They assist in Agile development processes, participate in code reviews, and manage tasks using version control systems like Git. Familiarity with Gen AI-based tools and a focus on learning industry best practices are integral to their role.', 420, 420, '401–600', 'Version', '19 May 2015', '18 Feb 2028', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'Application Development', 'access to related qualification(s) at the next NSQF level: Software Product Developer', 'General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"90","Practical":"240","EmployabilitySkills":"30","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "223", "qualification_type": "General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
