INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-4.5-IT-03788-2025-V1-NASSCOM', 'Foundations of UX Design', 'it-ites', 'IT-ITeS', 4.5, 'The purpose of this NOS is to enable students to explore the fundamentals of User Experience Design, to provide them with a base from where they can upskill themselves for specific User Experience Design job roles', 45, 45, '1–200', 'Version', '18 Feb 2025', '18 Feb 2028', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'Web & Mobile', 'Not Available', 'National Occupational Standard', 'N.A.', '{"Theory":"20","Practical":"25","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "239", "qualification_type": "National Occupational Standard", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-05-IT-03792-2025-V1-NASSCOM', 'Foundations of RPA', 'it-ites', 'IT-ITeS', 4.5, 'This NOS describes the fundamentals of RPA.', 90, 90, '1–200', 'Version', '18 Feb 2025', '18 Feb 2028', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'Robotic Process Automation', 'Not Avaliable', 'National Occupational Standard', 'N.A.', '{"Theory":"44","Practical":"46","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "240", "qualification_type": "National Occupational Standard", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-IT-03642-2025-V2-NASSCOM', 'Application Developer - Web & Mobile', 'it-ites', 'IT-ITeS', 5.0, 'An Application Developer - Web and Mobile designs, develops, and maintains innovative applications that fulfill user needs and business objectives. The role involves managing the entire application lifecycle, ensuring efficient workflows for continuous integration and delivery. The individual collaborates with cross-functional teams to gather requirements, conducts testing, and implements enhancements to optimize performance and user experience. The person also provides ongoing support for existing applications.', 420, 540, '401–600', 'Version', '25 Jun 2020', '18 May 2028', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'Web & Mobile Development', 'Academic progression:  access to related qualification(s) at the same NSQF level: User Experience
Designer, Test Analyst – Web & Mobile, DevOps Analyst – Web & Mobile, Mobile Device Management
Analyst
Professional progression:  access to related qualification(s) at the next NSQF level: Product Manager –
Web & Mobile, Senior User Experience Designer, Application Architect – Web & Mobile, Senior
Application Developer – Web & Mobile, Senior Test Analyst – Web & Mobile, Senior DevOps Analyst –
Web & Mobile', 'Future Skills Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"180","Practical":"210","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "241", "qualification_type": "Future Skills Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-IT-03646-2025-V2-NASSCOM', 'IT Helpdesk Attendant', 'it-ites', 'IT-ITeS', 3.0, 'An IT Helpdesk Attendant ensures the smooth operation of an organization''s IT systems by providing technical support and troubleshooting hardware and software issues. They assist with installing and configuring systems, monitoring networks, and resolving user issues efficiently. Acting as the first point of contact for IT problems, they offer guidance in-person or remotely. Their role minimizes disruptions, optimizes performance, and supports organizational productivity.', 360, 360, '201–400', 'Version', '19 May 2015', '18 Feb 2028', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'IT Support Services/Helpdesk', 'access to related qualification(s) at the next NSQF level:  Associate Technical Support', 'Upskilling Qualification', 'N.A.', '{"Theory":"90","Practical":"180","EmployabilitySkills":"30","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "242", "qualification_type": "Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-IT-03652-2025-V2-NASSCOM', 'Software Test Engineer', 'it-ites', 'IT-ITeS', 4.0, 'A Software Test Engineer is responsible for designing, developing, and coordinating test plans to ensure software quality and compatibility across diverse environments, including programs, hardware, operating systems, and networks. This role involves performing both scheduled and ad-hoc testing, conducting detailed software compatibility assessments, and identifying potential defects.', 300, 450, '401–600', 'Version', '27 Jan 2022', '18 Feb 2028', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'Testing and Quality Assurance', 'access to other qualifications at the next NSQF level – Team Lead Manual/Automation Testing', 'General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"60","Practical":"150","EmployabilitySkills":"60","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "243", "qualification_type": "General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-IT-03655-2025-V2-NASSCOM', 'Domestic Biometric Data Operator', 'it-ites', 'IT-ITeS', 3.0, 'A Domestic Biometric Data Operator is responsible for capturing, authenticating and processing biometric data of target users. Depending on the size and structure of the organization, the tasks may include installing and configuring the computer hardware and software; monitoring and maintaining computer systems and networks, troubleshooting biometrics systems, relevant computer hardware/software issues, and network problems.', 360, 360, '201–400', 'Version', '18 Feb 2025', '18 Feb 2028', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'Customer Relationship Management (CRM)', 'Access to related qualification(s) at the next NSQF level: Associate Customer Care (Voice & Non-Voice)', 'General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"90","Practical":"180","EmployabilitySkills":"30","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "244", "qualification_type": "General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-IT-03650-2025-V2-NASSCOM', 'Web Developer', 'it-ites', 'IT-ITeS', 4.0, 'A Web Developer is responsible for designing, developing, and maintaining web-based applications that incorporate both static and dynamic content. This involves creating user-friendly layouts, coding functional interfaces, and ensuring seamless website performance. They collaborate with application or functional developers to integrate web components into larger solutions or work independently on standalone projects. Their role ensures that websites meet technical requirements and provide superior user experience', 360, 360, '201–400', 'Version', '18 Feb 2025', '18 Feb 2028', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'Application Development', 'access to related qualification(s) at the next NSQF level:  Sr. Web developer', 'General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"90","Practical":"180","EmployabilitySkills":"30","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "245", "qualification_type": "General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-IT-03647-2025-V2-NASSCOM', 'IT Technical Support Executive', 'it-ites', 'IT-ITeS', 4.0, 'An IT Technical Support Executive resolves customer queries and technical issues across various channels, such as voice, non-voice (chat, email), or hybrid formats. The role involves troubleshooting hardware/software problems, providing remote support, documenting resolutions, and ensuring a seamless customer experience. Adherence to organizational protocols, strong communication skills, and the use of technology, including Generative AI, are critical for success.', 330, 510, '401–600', 'Version', '19 May 2015', '18 Feb 2028', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'Product Support', 'access to other qualifications at the same NSQF level – Team Lead - Customer Support', 'General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"90","Practical":"150","EmployabilitySkills":"30","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "246", "qualification_type": "General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-IT-03653-2025-V2-NASSCOM', 'IT Technical Writer', 'it-ites', 'IT-ITeS', 4.0, 'An IT Technical Writer for IT services and application development is responsible for creating technical documentation, such as job aids, help documents, user guides, reference manuals, training materials, online help content, etc. These documents facilitate the transfer of knowledge between application development teams and user teams. They collaborate with cross-functional teams to gather information, utilize documentation tools, and ensure consistency with industry standards. Additionally, they format and publish content across multiple platforms, maintaining and updating documents to reflect changes in products or services.', 360, 360, '201–400', 'Version', '19 May 2015', '18 Feb 2028', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'Application Development', 'access to related qualification(s) at the next NSQF level: Senior IT Technical Writer, Senior Web Developer, Senior Technical Document Writer, Senior UI Developer', 'General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"90","Practical":"180","EmployabilitySkills":"30","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "247", "qualification_type": "General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-IT-03651-2025-V2-NASSCOM', 'Software Product Developer', 'it-ites', 'IT-ITeS', 5.0, 'A Software Product Developer uses specialized knowledge of programming languages and software integration to build products and deliver business solutions. Their responsibilities include application enhancement, debugging, maintenance, and documentation. They handle the full development lifecycle, from coding to deployment, while collaborating with teams to integrate new features and ensure functionality. Additionally, they stay updated on industry trends and technologies.', 480, 480, '401–600', 'Version', '18 Jun 2015', '18 Feb 2028', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'Application Development', 'access to other qualifications at the same NSQF level – Senior Software Developer, Senior Functional Developer.', 'General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"90","Practical":"240","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "248", "qualification_type": "General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-IT-03657-2025-V2-NASSCOM', 'RPA Support Analyst', 'it-ites', 'IT-ITeS', 5.0, 'This qualification trains RPA Support Analysts in bot administration, maintenance, and incident management.  It covers bot ecosystem management, change management procedures, and troubleshooting.  Employability skills are also included.', 480, 480, '401–600', 'Version', '24 Feb 2022', '18 Feb 2028', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'Robotic Process Automation', 'Professional progression: access to related qualification(s) at the next NSQF level –  Senior Robotic Process Automation Support Analyst, Robotic Process Automation Test Engineer, Robotic Process Automation Developer, etc.  
Academic progression: access to other qualifications at the same NSQF level-  Junior Robotic Process Automation Test Engineer, Junior Robotic Process Automation Developer', 'Future Skills Qualification,General Qualification', 'N.A.', '{"Theory":"120","Practical":"210","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "249", "qualification_type": "Future Skills Qualification,General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-5.5-IT-03656-2025-V2-NASSCOM', 'RPA Developer', 'it-ites', 'IT-ITeS', 5.5, 'This qualification trains individuals to become RPA Developers, covering the complete RPA lifecycle.  It begins with foundational knowledge of RPA, business process analysis, and bot design principles, progressing to hands-on development using various tools and programming languages.  The curriculum emphasizes testing, deployment, and monitoring techniques, including security and infrastructure considerations. Advanced topics such as AI integration and cloud-based solutions are also included.  Finally, the qualification integrates essential employability skills training to prepare graduates for the workforce', 540, 540, '401–600', 'Version', '24 Feb 2022', '18 Feb 2028', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'Robotic Process Automation', 'Professional progression: access to related qualification(s) at the next NSQF level – RPA Technical lead, RPA Solution Architect 
Academic progression: access to other qualifications at the same NSQF level- RPA Test Engineer, RPA Implementation Specialist', 'Future Skills Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"168","Practical":"222","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "250", "qualification_type": "Future Skills Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-IT-03648-2025-V2-NASSCOM', 'IT Technical Support Associate', 'it-ites', 'IT-ITeS', 4.0, 'An IT Technical Support Associate is responsible for diagnosing and addressing technical issues impacting production systems by troubleshooting, applying known solutions, and escalating complex cases. The role involves leveraging Gen AI tools for intelligent problem analysis, automating routine tasks, and improving IT Support/Helpdesk workflows. Additionally, they utilize AI-powered ticketing systems to enhance customer experience and drive operational efficiency.', 390, 390, '201–400', 'Version', '19 May 2015', '28 Feb 2028', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'IT Support Services/Helpdesk', 'access to related qualification(s) at the next NSQF level: Team Lead Technical Support (Level 1)', 'General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"120","Practical":"180","EmployabilitySkills":"30","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "251", "qualification_type": "General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-06-IT-03645-2025-V2-NASSCOM', 'Cloud Infrastructure Analyst', 'it-ites', 'IT-ITeS', 6.0, 'Individuals in this job are responsible for designing, maintaining, evaluating, and testing architectures of cloud products and solutions. Cloud Architects also create enterprise policies and guidelines for cloud implementation and governance. They assess cloud vendors and third-party cloud service providers. They also assist in validating customer proposals and project plans for cloud implementation.', 600, 600, '401–600', 'Version', '22 Aug 2019', '18 Feb 2028', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'Cloud Computing', 'Professional progression: access to related qualification(s) at the next NSQF level – Senior Infrastructure Analyst, Senior Site-Reliability Analyst, etc
Academic progression: access to other qualifications at the same NSQF level – Site-Reliability Analyst etc.', 'Future Skills Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"156","Practical":"264","EmployabilitySkills":"60","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "252", "qualification_type": "Future Skills Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-IT-03664-2025-V2-NASSCOM', 'Customer Care Sr. Executive (Voice and Non- Voice)', 'it-ites', 'IT-ITeS', 4.0, 'The individual in this job role is responsible for collecting payments over the phone, chat, or email and converting customer inquiries into sales. They make outbound tele sales calls to promote products or services and close deals. Additionally, they handle customer queries remotely, ensuring a high level of customer satisfaction. This role requires excellent communication skills and the ability to manage customer interactions effectively to drive sales and payment collection.', 390, 390, '201–400', 'Version', '30 Dec 2021', '18 Feb 2028', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'Customer Relationship Management', 'access to related qualification(s) at the next NSQF level: Team Leader/Asst. Manager-Service Desk, Team Leader-Collections', 'General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"109","Practical":"161","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "253", "qualification_type": "General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-IT-03666-2025-V2-NASSCOM', 'Sr. Associate -Desktop Publishing (DTP)', 'it-ites', 'IT-ITeS', 4.0, 'The individual in this job role is responsible for providing and controlling access to publications, ensuring that only authorized personnel can view or edit the content. Additionally, they are responsible for publishing content in various formats, including print, digital, and multimedia, ensuring that it meets quality standards and is delivered on time. The individual must maintain accuracy, consistency, and proper version control throughout the publishing process.', 420, 420, '401–600', 'Version', '30 Dec 2021', '18 Feb 2028', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'Editorial and Desktop Publishing', 'access to related qualification(s) at the next NSQF level: Desktop Publishing Specialist', 'General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"111","Practical":"189","EmployabilitySkills":"30","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "254", "qualification_type": "General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-06-IT-03643-2025-V2-NASSCOM', 'Product Manager- Web & Mobile', 'it-ites', 'IT-ITeS', 6.0, 'A Product Manager – Web and Mobile is responsible for overseeing the full development lifecycle of web and mobile solutions. The role involves creating detailed use cases, aligning business requirements, and understanding customer needs. The individual also shapes the go-to-market strategies and drives customer engagement and retention initiatives to ensure the success of the product', 540, 540, '401–600', 'Version', '25 Jun 2020', '18 Feb 2028', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'Web & Mobile', 'Academic progression: access to related qualification(s) at the same NSQF level: Senior User Experience Designer, Application Architect – Web & Mobile, Senior Application Developer Web & Mobile, Senior Test Analyst – Web & Mobile, Senior DevOps Analyst – Web & Mobile
Professional progression: access to related qualification(s) at the next NSQF level: Senior Product Manager – Web & Mobile, Lead User Experience Designer, Senior Application Architect – Web & Mobile, Lead Application Developer – Web & Mobile, Lead Test Analyst – Web & Mobile, Lead DevOps Analyst – Web & Mobile', 'Future Skills Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"120","Practical":"240","EmployabilitySkills":"60","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "255", "qualification_type": "Future Skills Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-IT-03640-2025-V2-NASSCOM', 'User Experience Designer', 'it-ites', 'IT-ITeS', 5.0, 'A User Experience (UX) Designer is responsible for creating intuitive, user-centric digital experiences. This role involves developing UX design guidelines and best practices, crafting style guides, and establishing design systems for developers. UX Designers conduct business analysis, create user personas, and perform competitive analyses to understand user needs and market positioning. They plan solutions through sitemaps, information architecture, user experience maps, and user flows. The role includes designing detailed wireframes, visual screens, and interface assets such as imagery and animations. UX Designers also conduct usability testing throughout the design stages to ensure a seamless and engaging user experience that aligns with customer requirements.', 480, 480, '401–600', 'Version', '25 Jun 2020', '18 Feb 2028', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'Web & Mobile', 'NSQF Level 6 – Senior User Experience Designer
NSQF Level 7 – Lead User Experience Designer', 'Future Skills Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"137","Practical":"253","EmployabilitySkills":"30","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "256", "qualification_type": "Future Skills Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-IT-03658-2025-V2-NASSCOM', 'Specialist Transactional F&A', 'it-ites', 'IT-ITeS', 5.0, 'A Specialist Transactional F&A plays a critical role in managing and executing financial transactions within an organization, ensuring accuracy, compliance, and timely processing of financial documents. An individual in this role is responsible for maintaining customer accounts, generating and processing invoices and credit notes, handling payments and claims, and resolving financial queries related to accounts payable and receivable. The individual also ensures the secure and confidential handling of customer financial data, upholding data privacy standards.', 480, 480, '401–600', 'Version', '30 Dec 2021', '18 Feb 2028', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'Financial & Accounting', 'Access to related qualification(s) at the next NSQF level – Senior - Transaction Processing, Process Expert/ Specialist - Transaction Processing, Team Leader - Transaction Processing, Process Lead/ Senior Specialist - Transaction Processing, Manager - Transaction Processing, Business Manager/AVP/VP - Transaction Processing, Head of F&A, Head of Geographical Unit/Head of Sales/BD, Head of Company', 'General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"122","Practical":"238","EmployabilitySkills":"30","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "257", "qualification_type": "General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-IT-03510-2025-V2-NIELIT', 'Cyber Security and Social Media Analyst', 'it-ites', 'IT-ITeS', 5.0, 'The Cyber Security and Social Media Analyst qualification is designed to equip learners with essential skills in operating systems, networking, cyber security, cyber forensics, and social media analytics. The course provides hands-on training in configuring secure networks, managing firewalls, detecting and mitigating cyber threats, and analyzing social media data using modern tools. It also introduces learners to AI/ML concepts, server administration, and the use of disruptive technologies like cloud computing. The qualification prepares candidates for diverse roles in cyber security and digital communication, making them industry-ready professionals capable of protecting digital assets and managing online reputations.', 540, 540, '401–600', 'Version', '18 Feb 2025', '18 Feb 2028', 'National Institute of Electronics and Information Technology (NIELIT)', 'National Institute of Electronics and Information Technology (NIELIT)', 'Cyber Security', 'Cyber Security for Cloud Infrastructure', 'Future Skills Qualification', 'N.A.', '{"Theory":"180","Practical":"240","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "258", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-IT-03641-2025-V2-NASSCOM', 'Mobile Device Management Analyst', 'it-ites', 'IT-ITeS', 5.0, 'The qualification in Mobile Device Management focuses on developing and implementing effective strategies for managing mobile devices within an organization. It encompasses the configuration and maintenance of compliance policies, remote installation and management of business applications, and proactive monitoring to secure devices against potential threats. Additionally, this qualification includes integrating Mobile Device Management systems with existing enterprise systems to ensure seamless operations and data security. This role is vital in today''s digital landscape, where mobile technology is integral to business success.', 480, 480, '401–600', 'Version', '25 Jun 2020', '18 Feb 2028', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'Web & Mobile', 'Application Developer – Web & Mobile', 'Future Skills Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"127","Practical":"233","EmployabilitySkills":"30","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "259", "qualification_type": "Future Skills Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-06-IT-03644-2025-V2-NASSCOM', 'Application Architect - Web & Mobile', 'it-ites', 'IT-ITeS', 6.0, 'An Application Architect – Web & Mobile is responsible for designing, maintaining, evaluating, and testing the architectures of web-based and mobile-based products and solutions. The individual develops enterprise-wide policies and guidelines for software implementation, governance, and compliance. Additionally, the person evaluates and selects third-party tools, APIs, and service providers to enhance and optimize software solutions.', 480, 600, '401–600', 'Version', '25 Jun 2020', '18 Feb 2028', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'Web & Mobile', 'Academic progression: access to related qualification(s) at the same NSQF level: Product Manager – Web & Mobile, Senior User Experience Designer, Senior Application Developer Web & Mobile, Senior Test Analyst – Web & Mobile, Senior DevOps Analyst – Web & Mobile
Professional progression: access to related qualification(s) at the next NSQF level: Senior Product Manager – Web & Mobile, Lead User Experience Designer, Senior Application Architect – Web & Mobile, Lead Application Developer – Web & Mobile, Lead Test Analyst – Web & Mobile, Lead DevOps Analyst – Web & Mobile', 'Future Skills Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"120","Practical":"180","EmployabilitySkills":"60","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "260", "qualification_type": "Future Skills Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-IT-04148-2025-V1-IITG', 'Artificial Intelligence/Machine Learning Innovative Analyst', 'it-ites', 'IT-ITeS', 5.0, 'Learners with the ability to extract insights from complex datasets, using statistical and machine learning techniques. They gain proficiency in developing predictive models and algorithms that enable systems to make autonomous decisions based on data. Learners also learn to evaluate model performance and communicate findings effectively through data visualization and storytelling. Moreover, they acquire an understanding of ethical considerations and responsible AI practices, ensuring their work aligns with societal values and norms. Overall, studying data science and AI/ML empowers learners to leverage data-driven approaches for solving real-world problems across diverse industries.', 510, 510, '401–600', 'Version', '08 May 2025', '08 May 2028', 'Indian Institute of Technology Guwahati', 'IIT Guwahati, Amingaon, North Guwahati, Guwahati, Assam 781039', 'Artificial Intelligence/ Machine Learning', 'AI-ML Architect', 'Future Skills Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"220","Practical":"170","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "261", "qualification_type": "Future Skills Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-IT-03499-2025-V1-CDAC', 'Unmanned Aircraft System Developer', 'it-ites', 'IT-ITeS', 5.0, 'The Course is designed to provide comprehensive knowledge and hands-on skills essential for the design, operation, and maintenance of UAS, with a particular emphasis on safe, ethical, and regulatory-compliant practices. The program aims to produce industry-ready professionals equipped to handle a wide range of applications in sectors like agriculture, logistics, surveillance, environmental monitoring, and infrastructure management', 900, 900, '801–1000', 'Version', '18 Feb 2025', '17 Feb 2028', 'Centre for Development of Advanced Computing (CDAC)', 'Centre for Development of Advanced Computing', 'Unmanned Aircraft System Developer', 'UAS  Developer-> UAS Application Engineer->UAS Remote Sensing Professional', 'Future Skills Qualification', 'N.A.', '{"Theory":"240","Practical":"270","EmployabilitySkills":"60","OJT_Mandatory":"330"}', false, '{}'::text[], '{"source_row": "262", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-06-IT-01844-2025-V2-NASSCOM', 'Blockchain Architect', 'it-ites', 'IT-ITeS', 6.0, 'The Blockchain Architect is responsible for designing, developing, and maintaining blockchain-based systems. This role involves defining project requirements, designing system architecture, and developing smart contracts focusing on security. The developer must assess vulnerabilities, ensure scalability, and integrate blockchain solutions with existing systems. Additionally, they establish governance models and adhere to best practices in blockchain management', 570, 570, '401–600', 'Version', '30 Dec 2021', '08 May 2028', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'Blockchain', 'access to related qualification(s) at the next NSQF level –Head, Blockchain', 'Future Skills Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"195","Practical":"195","EmployabilitySkills":"60","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "263", "qualification_type": "Future Skills Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-IT-04331-2025-V2-NASSCOM', 'Blockchain full stack developer', 'it-ites', 'IT-ITeS', 5.0, 'Individuals at this job are responsible for developing the core blockchain. They will be responsible for developing tools, processes, and mechanisms for defining and developing the core blockchain. They will be responsible for defining and documenting technical specifications pertaining to the blockchain solution, including client, consensus algorithm, distributed data management, ledger maintenance, participant incentivization, smart contract/ chain code, and tokenomics.', 510, 510, '401–600', 'Version', '30 Dec 2021', '08 May 2028', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'Blockchain', 'Access to related qualification(s) at the next NSQF level: Blockchain Architect', 'Future Skills Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"159","Practical":"201","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "264", "qualification_type": "Future Skills Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-IT-04332-2025-V2-NASSCOM', 'Drone Software Technician', 'it-ites', 'IT-ITeS', 4.0, 'The drone software technician will collaborate with stakeholders to document functional and non-functional requirements, create architectural diagrams that outline software structure, and design algorithms for navigation and flight control. . The technician will utilize simulation tools to test algorithms and validate software performance in controlled environments before conducting real-world flight tests. Thorough documentation of code and preparing software for deployment will also be key responsibilities, alongside updating it based on user feedback and technological advancements.', 390, 390, '201–400', 'Version', '31 Mar 2022', '08 May 2028', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'Drone Technology', 'Professional progression:   access to related qualification(s) at the next NSQF level –   Application Developer etc.
Academic progression:   access to related qualification (s) at the next NSQF level –   Flight test operator, etc', 'Future Skills Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"92","Practical":"148","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "265", "qualification_type": "Future Skills Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-IT-04205-2025-V1-CGSC', 'Welding Technician - Oil & Gas/Shipbuilding/Railways', 'it-ites', 'IT-ITeS', 4.0, 'A Welding Technician is responsible for executing welding operations in various industries such as Oil & Gas, Shipbuilding & Railways, utilizing augmented reality (AR) technology to enhance precision, efficiency, and safety. This role involves performing high-quality welding on a variety of materials and components while adhering to industry standards and regulations.', 390, 480, '401–600', 'Version', '08 May 2025', '08 May 2028', 'Capital Goods and Strategic Skill Council (CGSSC)', 'Capital Goods and Strategic Skills Council (CGSSC)', 'Welding & Cutting', 'Welding supervisor ( Level 5 ),Welding Automation Engineer(Level 6)', 'Future Skills Qualification', 'N.A.', '{"Theory":"180","Practical":"210","EmployabilitySkills":"30","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "266", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-05-IT-04175-2025-V1-NIELIT', 'Essentials of Data Encryption and Cryptographic Security', 'it-ites', 'IT-ITeS', 5.0, 'The "Essentials of Data Encryption and Cryptographic Security" course provides an in-depth understanding of encryption techniques essential for modern cybersecurity. It covers the fundamentals of encryption, including symmetric (AES, DES, 3DES) and asymmetric encryption (RSA, ECC), digital signatures, and key management strategies. Additionally, students explore steganography, public key infrastructure (PKI), and real-world applications of cryptographic security. Hands-on labs involve implementing encryption algorithms using Python, OpenSSL, and GPG, ensuring practical proficiency. The course culminates in projects on secure communications and key management, equipping students with the necessary skills for data security in diverse applications.', 120, 120, '1–200', 'Version', '08 May 2025', '08 May 2028', 'National Institute of Electronics and Information Technology (NIELIT)', 'National Institute of Electronics and Information Technology', 'Cyber Security', 'Cryptography Engineer', 'Future Skills Qualification', 'N.A.', '{"Theory":"45","Practical":"75","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "267", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-05-IT-04176-2025-V1-NIELIT', 'Essentials of Network Security Measures', 'it-ites', 'IT-ITeS', 5.0, 'This course provides a comprehensive understanding of protecting networks from cyber threats through a blend of theoretical knowledge and hands-on practical training. It begins with the fundamentals of networking and the role of network security, emphasizing its importance in today’s cybersecurity landscape. Students explore various network attacks, including real-world case studies and attack simulations. The course delves into core security principles, such as configuring firewalls, VPNs, IDS/IPS systems, and secure access controls. It also covers network defence strategies, including risk assessment, incident response planning, penetration testing, and using SIEM tools. Finally, students learn about emerging trends in cybersecurity, including AI-based threat detection, the Zero Trust security model, cloud security, and blockchain technology, equipping them with up-to-date knowledge for real-world applications.', 120, 120, '1–200', 'Version', '08 May 2025', '08 May 2028', 'National Institute of Electronics and Information Technology (NIELIT)', 'National Institute of Electronics and Information Technology (NIELIT)', 'Cyber Security', 'Cybersecurity Analyst', 'Future Skills Qualification', 'N.A.', '{"Theory":"45","Practical":"75","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "268", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-04-IT-04173-2025-V2-NIELIT', 'Essentials of AI (Upskilling)', 'it-ites', 'IT-ITeS', 4.0, 'The Standalone NOS “Essentials of AI (Upskilling)” has been meticulously designed to provide a comprehensive foundation in Artificial Intelligence (AI) and its associated domains, equipping participants with the essential skills to explore career opportunities in this transformative field. The curriculum focuses on developing expertise in Python programming, statistical concepts, data science, machine learning, and deep learning while integrating theoretical knowledge with practical applications.
Participants will gain hands-on experience in programming with Python, analyzing data, applying statistical principles, and implementing machine learning and deep learning algorithms. They will also work with industry-relevant tools like NumPy, Pandas, Matplotlib, Seaborn, TensorFlow, Keras, and OpenCV.', 210, 210, '201–400', 'Version', '08 May 2025', '08 May 2028', 'National Institute of Electronics and Information Technology (NIELIT)', 'National Institute of Electronics and Information Technology (NIELIT)', 'AI Development', 'Senior AI/ML/Engineer', 'Future Skills Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"90","Practical":"120","EmployabilitySkills":"00","OJT_Mandatory":"00"}', false, '{}'::text[], '{"source_row": "269", "qualification_type": "Future Skills Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-03-IT-03801-2025-V1-NIELIT', 'Basics of Python Programming', 'it-ites', 'IT-ITeS', 3.0, 'This course provides students with a comprehensive introduction to Python programming essentials. The theory component covers setting up the Python environment, understanding variables and data types, implementing conditional statements and loops, and mastering functions.', 30, 30, '1–200', 'Version', '18 Feb 2025', '18 Feb 2028', 'National Institute of Electronics and Information Technology (NIELIT)', 'National Institute of Electronics and Information Technology (NIELIT)', 'AI Development', 'Not Applicable', 'Future Skills Qualification', 'N.A.', '{"Theory":"10","Practical":"20","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "270", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-06-IT-04198-2025-V1-CGSC', 'Mechanical Automation & Maintenance Engineer', 'it-ites', 'IT-ITeS', 6.0, 'A Mechanical Automation & Maintenance Engineer is a professional responsible for designing, installing,
maintaining, and upgrading mechanical systems, equipment, and machines that are controlled by
automated systems.', 660, 660, '601–800', 'Version', '08 May 2025', '08 May 2028', 'Capital Goods and Strategic Skill Council (CGSSC)', 'Capital Goods and Strategic Skills Council', 'Maintenance', 'Mechanical Automation & Maintenance Manager-Level 6.5', 'Future Skills Qualification,General Qualification', 'N.A.', '{"Theory":"140","Practical":"310","EmployabilitySkills":"60","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "271", "qualification_type": "Future Skills Qualification,General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
