INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-3.5-IT-03825-2025-V1-NIELIT-', 'Basics of Computer Vision', 'it-ites', 'IT-ITeS', 3.5, 'The purpose of this qualification is to train the students in Computer vision so that students may implement computer vision algorithms for image classification, object detection, and tracking and increase their employability in the field of IT/Computer Science. The purpose is to demystify AI and equip the future workforce with the confidence to learn and apply skills independently. The participants will get initial exposure for developing AI models.', 15, 15, '1–200', 'Version', '18 Feb 2025', '18 Feb 2028', 'National Institute of Electronics and Information Technology (NIELIT)', 'National Institute of Electronics and Information Technology (NIELIT)', 'AI Application Development', 'Not Applicable', 'Future Skills Qualification,Micro Credentials', 'N.A.', '{"Theory":"5","Practical":"10","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "279", "qualification_type": "Future Skills Qualification,Micro Credentials", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-3.5-IT-03827-2025-V1-NIELIT', 'Fundamentals of R Programming', 'it-ites', 'IT-ITeS', 3.5, 'The course *Foundational in R Programming* provides a comprehensive introduction to R, focusing on building a solid understanding of its programming basics and environment. Participants will learn to navigate R Studio, execute fundamental commands, and work hands-on with R. Key topics include data handling techniques, such as importing datasets, sampling, and manipulating data efficiently. Through practical sessions, the course equips learners with essential skills to confidently analyze and manage data using R.', 30, 30, '1–200', 'Version', '18 Feb 2025', '18 Feb 2028', 'National Institute of Electronics and Information Technology (NIELIT)', 'National Institute of Electronics and Information Technology (NIELIT)', 'Data Analytics', 'Not Applicable', 'Future Skills Qualification,Micro Credentials', 'N.A.', '{"Theory":"10","Practical":"20","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "280", "qualification_type": "Future Skills Qualification,Micro Credentials", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-IT-04446-2025-V2-ASAP', 'AI-Machine Learning Developer', 'it-ites', 'IT-ITeS', 5.0, 'Individuals in this role are responsible for designing, developing, and deploying AI and Machine Learning applications and platforms. They evaluate the performance of algorithmic models within the deployment environment and ensure optimal system integration. Their responsibilities include building, testing, and implementing end-to-end AI solutions tailored to specific use cases.', 540, 540, '401–600', 'Version', '25 Aug 2022', '07 Oct 2028', 'Additional Skill Acquisition Programme, Government of Kerala', 'ADDITIONAL SKILL ACQUISITION PROGRAMME, KERALA', 'AIML Developer', 'AIML Engineer Trainee, AIML Engineer, Developer, Head of AIML Division, Data Engineer, Data Scientist', 'Future Skills Qualification,General Qualification', 'N.A.', '{"Theory":"110","Practical":"220","EmployabilitySkills":"30","OJT_Mandatory":"180"}', false, '{}'::text[], '{"source_row": "281", "qualification_type": "Future Skills Qualification,General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-04-IT-04417-2025-V2-NIELIT', 'Fundamentals of Information Security', 'it-ites', 'IT-ITeS', 4.0, 'The purpose of this qualification is to equip students with skills in Information Security, enhancing their employability in the IT and Computer Science fields. The aim is to demystify Information Security and empower the future workforce with the confidence to independently learn and apply these essential skills.', 90, 90, '1–200', 'Version', '08 May 2025', '08 May 2028', 'National Institute of Electronics and Information Technology (NIELIT)', 'National Institute of Electronics and Information Technology', 'Cyber Security', 'Information Security Associate', 'Future Skills Qualification', 'N.A.', '{"Theory":"35","Practical":"55","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "282", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-3.5-IT-03828-2025-V1-NIELIT', 'Introduction to Data Analysis Concepts and Techniques', 'it-ites', 'IT-ITeS', 3.5, 'The course “Introduction to Data Analysis Concepts and Techniques” provides a comprehensive introduction to essential methods used in data science. Participants will learn to perform Exploratory Data Analysis (EDA) and create effective visualizations using Matplotlib and Seaborn. The course also covers statistical analysis, time series analysis, and the application of probability concepts in data science. In addition, learners will be introduced to Natural Language Processing (NLP) techniques for sentiment analysis and text classification. Through practical sessions, the course equips participants with the skills to analyze, interpret, and derive meaningful insights from diverse datasets.', 30, 30, '1–200', 'Version', '18 Feb 2025', '18 Feb 2028', 'National Institute of Electronics and Information Technology (NIELIT)', 'National Institute of Electronics and Information Technology (NIELIT)', 'Data Analytics', 'Not Applicable', 'Future Skills Qualification', 'N.A.', '{"Theory":"10","Practical":"20","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "283", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-3.5-IT-03823-2025-V1-NIELIT', 'Introduction to Deep Learning', 'it-ites', 'IT-ITeS', 3.5, 'The purpose of this qualification is to train the students in Deep learning implementation using Python to upskill them and increase their employability in the field of IT/Computer Science. The purpose is to demystify AI and equip the future workforce with the confidence to learn and apply skills independently. The participants will get initial exposure for developing AI models.', 15, 15, '1–200', 'Version', '18 Feb 2025', '18 Feb 2028', 'National Institute of Electronics and Information Technology (NIELIT)', 'National Institute of Electronics and Information Technology', 'AI Application Development', 'Not Applicable', 'Future Skills Qualification', 'N.A.', '{"Theory":"5","Practical":"10","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "284", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-06-IT-045862025-V2-NASSCOM', 'AI Database Administrator', 'it-ites', 'IT-ITeS', 6.0, 'This Qualification is designed to equip participants with essential knowledge and skills for effectively managing databases and computing clusters within various professional environments. Spanning multiple modules, this qualification covers foundational concepts in database management, including the installation and configuration of popular open-source database management systems such as MySQL and PostgreSQL, as well as hands-on experience with SQL commands for data manipulation. Participants will learn advanced topics including data validation, compliance frameworks, automated maintenance, and monitoring techniques to ensure optimal database performance. Furthermore, the qualification emphasizes user access management, security configurations, and the importance of documentation in operational continuity. Beyond technical competencies, the program incorporates employability skills, communication training, and entrepreneurship concepts, preparing participants for real-world responsibilities and career advancement opportunities in database management, IT infrastructure, and related fields.', 480, 480, '401–600', 'Version', '22 Sep 2020', '07 Oct 2028', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'IT-ITeS SSC NASSCOM', 'Artificial Intelligence and Big Data Analytics', '• Academic Progression: Access to other qualifications at the same NSQF level – DevOps Engineer, Data Steward, Security Analyst 
• Professional Progression: Access to related qualification(s) at the next NSQF level – Senior Database Administrator, Senior DevOps Engineer', 'Future Skills Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"131","Practical":"199","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "285", "qualification_type": "Future Skills Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-IT-045822025-V2-NASSCOM', 'AI DevOps Analyst', 'it-ites', 'IT-ITeS', 5.0, 'A DevOps Engineer is a key player in the software development lifecycle, responsible for bridging the gap between development, operations, and quality assurance teams. They design and maintain Continuous Integration and Continuous Delivery (CI/CD) pipelines to automate testing, building, and deployment processes, ensuring high-quality software delivery at speed. Utilizing tools like Terraform and Ansible, they automate the provisioning and configuration of infrastructure across various environments, while also implementing monitoring and logging solutions to optimize application performance. DevOps Engineers incorporate security practices (DevSecOps) into the development lifecycle, manage incident response strategies, and emphasize collaboration and documentation to foster continuous improvement within the organization. Through these efforts, they ensure that applications are robust, scalable, and aligned with business objectives..', 480, 480, '401–600', 'Version', '22 Sep 2020', '07 Oct 2028', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'IT-ITeS SSC NASSCOM', 'Artificial Intelligence and Big Data Analytics', '• Academic Progression: Access to other qualifications at the same NSQF level – Database Administrator, Data Steward 
• Professional Progression: Access to related qualification(s) at the next NSQF level – AI-Solution Architect', 'Future Skills Qualification,General Qualification', 'N.A.', '{"Theory":"180","Practical":"150","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "286", "qualification_type": "Future Skills Qualification,General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-07-IT-01546-2025-V2-NASSCOM', 'AR/VR Test Engineer', 'it-ites', 'IT-ITeS', 5.0, 'An AR/VR Test Engineer ensures the quality and functionality of augmented reality (AR) and virtual reality (VR) applications and hardware.  They design and execute tests, identify and track defects, and collaborate with developers to improve the user experience.  This role requires a strong understanding of software testing methodologies, AR/VR technologies, and relevant development tools.', 480, 480, '401–600', 'Version', '31 Mar 2022', '07 Oct 2028', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'Augmented reality/Virtual reality', 'Professional progression: access to related qualification(s) at the next NSQF level – Senior AR/VR Test Engineer', 'Future Skills Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"120","Practical":"210","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "287", "qualification_type": "Future Skills Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-IT-045942025-V2-NASSCOM', 'Business Intelligence Analyst', 'it-ites', 'IT-ITeS', 5.0, 'This qualification equips candidates with essential skills to collect, clean, validate, analyze, and visualize data for informed decision-making in a business environment. It covers the entire data lifecycle—from sourcing and preprocessing to advanced analysis and reporting—enabling professionals to develop actionable insights, maintain high data quality standards, and communicate findings effectively to stakeholders. Designed for aspiring Business Intelligence Analysts, it prepares individuals to support strategic initiatives through data-driven insights, visualization techniques, and stakeholder engagement.', 480, 480, '401–600', 'Version', '19 Dec 2018', '07 Oct 2028', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'IT-ITeS SSC NASSCOM', 'Artificial Intelligence and Big Data Analytics', 'Sr.Business Intelligence Analyst, Senior Visualization Specialist, Senior Data Quality Analyst', 'Future Skills Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"120","Practical":"210","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "288", "qualification_type": "Future Skills Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-06-IT-045952025-V2-NASSCOM', 'Data Scientist', 'it-ites', 'IT-ITeS', 6.0, 'A data scientist is a skilled professional responsible for collecting, cleaning, analyzing, and interpreting large volumes of data to derive actionable insights that support business decision-making. They employ statistical methods, machine learning algorithms, and various data processing tools to explore data, build predictive models, and validate results. Data scientists also develop scalable data pipelines, ensure data quality, and create visualizations and dashboards to communicate findings effectively. Their role spans across understanding business requirements, designing data strategies, implementing algorithms, deploying models into production environments, and continually monitoring and refining those models to adapt to changing data patterns. Overall, a data scientist bridges the gap between raw data and strategic insights, empowering organizations to make informed, data-driven decisions.', 630, 630, '601–800', 'Version', '19 Dec 2018', '07 Oct 2028', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'IT-ITeS SSC NASSCOM', 'Artificial Intelligence and Big Data Analytics', 'Chief Data Officer', 'Future Skills Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"164","Practical":"286","EmployabilitySkills":"60","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "289", "qualification_type": "Future Skills Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-IT-045832025-V2-NASSCOM', 'AI Machine Learning Analyst', 'it-ites', 'IT-ITeS', 5.0, 'A Machine Learning Analyst is crucial in designing, developing, deploying, and maintaining machine learning models that transform data into actionable insights for addressing business challenges. This professional combines expertise in software engineering, data analysis, and machine learning principles to create systems capable of learning from data and making predictions. Key responsibilities include preparing and processing data to ensure high quality, selecting and creating features, exploring various algorithms for specific tasks, and implementing neural networks using appropriate frameworks. Model training and evaluation are crucial, utilizing hyperparameter tuning and metrics such as accuracy and F1 score to ensure performance. After deployment, the engineer establishes monitoring systems to track performance, data quality, and utilization, identifying signals for model retraining and implementing automated pipelines. Additionally, they ensure efficient deployment through best practices and containerization while creating API endpoints for seamless model interaction. Effective documentation of the development process and stakeholder collaboration are also essential, ensuring that machine learning solutions align with business objectives. Ultimately, a Machine Learning Engineer is vital in harnessing data-driven insights and driving innovation through advanced machine learning technologies.', 480, 480, '401–600', 'Version', '19 Dec 2018', '07 Oct 2028', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'IT- ITeS SSC NASSCOM', 'Artificial Intelligence and Big Data Analytics', 'Data Architect, AI-Solution Architect', 'Future Skills Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"138","Practical":"192","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "290", "qualification_type": "Future Skills Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-IT-03660-2025-V2-NASSCOM', 'XR Designer', 'it-ites', 'IT-ITeS', 5.0, 'The XR Designer role involves understanding user requirements and behaviors through ethnographic research, creating wireframes that detail features and user flows, and defining storytelling elements to enhance the user journey. Designers establish standards for user experience, drive the prototyping process, and conduct usability testing to gather feedback for refining interactions and visual design. They also create and optimize 3D models for AR/VR applications, ensuring high-quality visuals while addressing data privacy by drafting relevant policies. Collaboration and iteration are key as designers refine prototypes based on user insights to deliver a seamless immersive experience.', 480, 480, '401–600', 'Version', '29 Sep 2022', '07 Oct 2028', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'IT-ITeS SSC NASSCOM', 'Augmented Reality/Virtual Reality', 'Senior AR/VR Designer, Lead AR/VR Designer', 'Future Skills Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"115","Practical":"215","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "291", "qualification_type": "Future Skills Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-3.5-IT-03822-2025-V1-NIELIT', 'Machine Learning Fundamentals', 'it-ites', 'IT-ITeS', 3.5, 'The purpose of this qualification is to train the students in Machine Learning implementation using Python to upskill them and increase their employability in the field of IT/Computer Science. Purpose is to demystify machine learning and equip the future workforce with the confidence to learn and apply skills independently.', 15, 15, '1–200', 'Version', '18 Feb 2025', '18 Feb 2028', 'National Institute of Electronics and Information Technology (NIELIT)', 'National Institute of Electronics and Information Technology', 'AI Application Development', 'Not Applicable', 'Future Skills Qualification', 'N.A.', '{"Theory":"6","Practical":"9","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "292", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-06-IT-00471-2025-V2-NASSCOM', 'AR/VR Consultant', 'it-ites', 'IT-ITeS', 6.0, 'An AR/VR Consultant performs a comprehensive analysis of customer requirements, opportunities, costs, and impacts while ensuring data privacy is upheld. It requires creating a functional design for the AR/VR solution that aligns with specified business requirements. Additionally, the consultant must develop project plans and procedures to create solutions and enhance product effectiveness, ensuring that key performance indicators (KPIs) and service goals are met. Setting technical parameters to monitor and manage the performance of the AR/VR architecture and preparing statistical reports on product performance is also essential. Lastly, engaging in innovative research and development within the AR/VR field while staying current with the latest technological trends is crucial to the role. The AR/VR consultant also acts as a strategic advisor and technical expert, guiding businesses through successfully integrating AR/VR technologies into their operations to achieve specific business objectives.  Their role is multifaceted, combining business acumen with technical proficiency.', 570, 570, '401–600', 'Version', '31 Mar 2022', '07 Oct 2028', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'IT-ITeS Sector Skills Council NASSCOM', 'Augmented reality/Virtual reality', 'Professional progression: access to related qualification(s) at the next NSQF level – Senior AR/VR Consultant, etc.
Academic progression: access to other qualifications at the same NSQF level – Associate AR/VR Architect, Senior AR/VR Infrastructure Engineer, etc.', 'Future Skills Qualification', 'N.A.', '{"Theory":"140","Practical":"250","EmployabilitySkills":"60","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "293", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-3.5-IT-03824-2025-V1-NIELIT', 'Fundamentals of Natural Language Processing (NLP)', 'it-ites', 'IT-ITeS', 3.5, 'This Micro Credential equips learners with essential knowledge and practical skills in Natural Language Processing (NLP). It covers key text processing techniques such as tokenization, stemming, lemmatization, and stop-word removal, along with Natural Language Understanding (NLU), POS tagging, and Named Entity Recognition (NER). Learners will explore language models like TF-IDF, Word2Vec, and GloVe and gain hands-on experience using Python and leading NLP libraries for tasks such as sentiment analysis and text classification.', 15, 15, '1–200', 'Version', '18 Feb 2025', '18 Feb 2028', 'National Institute of Electronics and Information Technology (NIELIT)', 'National Institute of Electronics and Information Technology (NIELIT)', 'AI Application Development', 'Not Applicable', 'Future Skills Qualification', 'N.A.', '{"Theory":"6","Practical":"9","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "294", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-IT-04447-2025-V2-ASAP', 'Business Analyst', 'it-ites', 'IT-ITeS', 5.0, 'This comprehensive, application-oriented program is designed to equip learners with the critical knowledge and technical skills required to drive data-driven decision-making in modern businesses. The course blends statistical foundations, data management, machine learning, and storytelling into one integrated learning journey.
Through core modules in R, Python, Excel, and modern business tools, students master techniques in data wrangling, visualization, statistical inference, predictive modeling, and cloud-based big data analytics. Learners are also introduced to emerging technologies like Generative AI for business insights and explore real-time analytics using cloud and big data platforms.
The program emphasizes domain relevance with sector-based electives (e.g., Finance, HR, Pharma, E-commerce) and culminates in a capstone project where students apply their learning to solve real-world business problems using end-to-end analytics workflows. With focused training on project management, communication, and data storytelling, graduates are prepared to lead impactful analytics initiatives across industries.', 510, 600, '401–600', 'Version', '25 Aug 2022', '07 Oct 2028', 'Additional Skill Acquisition Programme, Government of Kerala', 'ADDITIONAL SKILL ACQUISITION PROGRAMME KERALA', 'Data Analyst', 'Business Analyst (BA), Senior BA, Lead BA, Principal BA', 'Future Skills Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"30","Practical":"390","EmployabilitySkills":"60","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "295", "qualification_type": "Future Skills Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-5.5-IT-045972025-V2-NASSCOM', 'IoT Software Analyst', 'it-ites', 'IT-ITeS', 5.5, 'The IoT Software Analyst role, based on the modules you''ve posted, involves designing, developing, testing, and maintaining end-to-end IoT solutions. Key activities include working with connectivity protocols, developing and integrating software at device, platform, and cloud levels, ensuring system reliability, and testing for functionality and performance. The role also emphasizes automation (CI/CD pipelines), configuration management, quality assurance through various testing methods (functional, non-functional, end-to-end), and proper documentation. Skills required include programming , working with IoT platforms, managing source code, employing DevOps tools, and ensuring system security and compliance. Overall, the analyst is crucial in enabling seamless, reliable, and secure IoT systems from development to deployment.', 540, 540, '401–600', 'Version', '25 Aug 2022', '07 Oct 2028', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'Internet of Things', 'Professional progression: access to related qualification(s) at the next NSQF level:   Senior IoT Software Analyst, IoT Solution Architect, IoT Product Manager
Academic progression: access to related qualification(s) at the next NSQF level:  IoT Test Analyst, IoT Product Analyst, IoT Data Analyst', 'Future Skills Qualification', 'N.A.', '{"Theory":"156","Practical":"234","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "296", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-IT-045902025-V2-NASSCOM', 'Cloud Application Developer', 'it-ites', 'IT-ITeS', 5.0, 'A Cloud Application Developer is responsible for designing, developing, and maintaining secure, resilient, and scalable cloud-native applications. The person gathers and validates functional and non-functional requirements, implements modern architectures and DevSecOps practices, and manages the full application lifecycle using continuous integration and delivery (CI/CD) pipelines. The individual also ensures regulatory compliance, application performance, and efficient use of cloud infrastructure and services.', 510, 510, '401–600', 'Version', '28 Jul 2022', '07 Oct 2028', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'Cloud Computing', 'Professional Progression: access to related qualification(s) at the next NSQF level - Senior Cloud Application Developer, Cloud Infrastructure Specialist, Cloud Consultant, etc.
Academic Progression:  access to other qualifications at the same NSQF level – Cloud Infrastructure Analyst, Application Developer - Web & Mobile, etc.', 'Future Skills Qualification', 'N.A.', '{"Theory":"120","Practical":"210","EmployabilitySkills":"60","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "297", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-03-IT-03826-2025-V1-NIELIT', 'Overview of Data Science', 'it-ites', 'IT-ITeS', 3.0, 'The “Overview of Data Science” course provides a comprehensive introduction to the core concepts and practices of data science. It begins by defining data science, highlighting its scope, and exploring its applications across industries. Participants will learn to distinguish data science from related fields such as data analytics and machine learning, gaining clarity on their unique roles.', 7, 7, '1–200', 'Version', '18 Feb 2025', '18 Feb 2028', 'National Institute of Electronics and Information Technology (NIELIT)', 'National Institute of Electronics and Information Technology (NIELIT)', 'Data Analytics', 'Not Applicable', 'Future Skills Qualification', 'N.A.', '{"Theory":"4","Practical":"3.5","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "298", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-5.5-IT-045882025-V2-NASSCOM', 'IT Forensic Analyst', 'it-ites', 'IT-ITeS', 5.5, 'An IT Forensic analyst is responsible for a comprehensive range of tasks aimed at investigating digital incidents and preserving evidence. This includes ensuring necessary authorizations are in place for conducting forensic evidence seizure and securing physical scenes to prevent unauthorized access and protect evidence from alteration or damage. They identify potential sources of data, handle digital devices carefully, and utilize forensic tools to collect both volatile and non-volatile data, ensuring data integrity and proper documentation of chain of custody. The specialist conducts thorough examinations of extracted data, including network traffic, call data records, and emails, while analyzing metadata and digital logs to detect unauthorized access and identify anomalous activities. They participate in incident response activities, develop data recovery methods, and collaborate with law enforcement agencies when necessary. Accurate documentation of investigative activities, including logs and reports summarizing findings and methodologies, is crucial. Additionally, they conduct risk assessments, stay updated on relevant laws and regulations, and implement quality control measures. Continuous learning through workshops and conferences helps the specialist remain informed on new technologies and methodologies in the field, while establishing ethical guidelines ensures privacy considerations are upheld during investigations.', 540, 540, '401–600', 'Version', '25 Aug 2022', '07 Oct 2028', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'Information and Cyber Security', 'Professional progression: Access to related qualification(s) at the next NSQF level – Sr. IT Forensic Specialist, Chief Information Officer, Chief Information Security Officer, etc.
Academic progression: Access to other qualifications at the same NSQF level – Senior Consultant- Network Security, Architect Application Security, Security Infrastructure Specialist, Security Operations Centre Specialist, etc.', 'Future Skills Qualification', 'N.A.', '{"Theory":"136","Practical":"254","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "299", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-06-IT-045872025-V2-NASSCOM', 'Network Security Engineer', 'it-ites', 'IT-ITeS', 6.0, 'The qualification presents a comprehensive approach to network security and compliance management, designed to equip individuals with the essential skills and knowledge required to protect organizational information systems. It encompasses a wide range of topics, including foundational concepts of network security, risk management, compliance with regulatory standards (such as GDPR and PCI-DSS), and practical implementation of security measures like firewalls and intrusion detection systems. Participants engage in evaluating existing security postures, conducting audits, and understanding stakeholder roles in cybersecurity practices. Additionally, the qualification emphasizes hands-on experience with industry-standard tools and software, preparing individuals for real-world challenges in safeguarding digital assets and maintaining regulatory compliance. Overall, this qualification aims to cultivate adept cybersecurity professionals who can effectively contribute to their organizations'' security frameworks.', 600, 600, '401–600', 'Version', '25 Aug 2022', '07 Oct 2028', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'Cybersecurity', 'Professional progression: Access to related qualification(s) at the next NSQF level –Senior Consultant- Network Security, Lead Penetration Tester, Forensics Specialist, Architect- App Security, etc.
Academic progression: Access to other qualifications at the same NSQF level - Penetration Tester, Senior Security Analyst, Senior Analyst- App Security, etc.', 'Future Skills Qualification', 'N.A.', '{"Theory":"152","Practical":"268","EmployabilitySkills":"60","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "300", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-06-IT-045892025-V2-NASSCOM', 'Information Security Analyst', 'it-ites', 'IT-ITeS', 6.0, 'Information Security Analyst serves as a vital defender of an organization''s information systems, using a combination of technical skills, knowledge of compliance frameworks, risk management practices, and effective communication to protect data integrity and support the organization’s overall security posture. They are instrumental in implementing continuous monitoring mechanisms to manage risks and guide compliance strategies, ensuring that the organization adheres to relevant security policies and regulations.', 570, 570, '401–600', 'Version', '25 Aug 2022', '07 Oct 2028', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'Cybersecurity', 'Professional progression: Access to related qualification(s) at the next NSQF level – SOC Specialist, Chief Information Officer, Chief Information Security Officer, etc.
Academic progression: Access to other qualifications at the same NSQF level - Senior Consultant Network Security, Architect Application Security, Security Operations Centre Specialist, Forensics Specialist, etc.', 'Future Skills Qualification', 'N.A.', '{"Theory":"156","Practical":"234","EmployabilitySkills":"60","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "301", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-5.5-IT-045992025-V2-NASSCOM', 'Analyst Endpoint Security', 'it-ites', 'IT-ITeS', 5.5, 'The Endpoint Security Analyst is responsible for implementing and managing security measures for an organization''s endpoint devices and data. This role involves installing and configuring endpoint security tools, monitoring security incidents, and enforcing security policies to ensure compliance with regulations.Key responsibilities include conducting audits of cloud environments, leveraging IT analytics for security reports, and utilizing AI-driven tools for anomaly detection. The analyst manages mobile devices through Mobile Device Management (MDM) solutions and applies data encryption strategies to protect sensitive information.Additionally, the analyst troubleshoots security issues, implements automated responses to incidents, and collaborates with cross-functional teams to communicate findings and recommend improvements. Overall, the Endpoint Security Analyst plays a vital role in identifying vulnerabilities and enhancing the organization''s cybersecurity posture.', 540, 540, '401–600', 'Version', '25 Aug 2022', '07 Oct 2028', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'Cybersecurity', 'Professional progression: Access to related qualification(s) at the next NSQF level – Senior Analyst- Endpoint Security, Senior Analyst- Application security, Senior Security Analyst, Senior- Security Operations Centre, Senior Cloud Security Analyst, etc.
Academic progression: Access to other qualifications at the same NSQF level - Security Analyst, Analyst Endpoint Security, Analyst Security Operations Centre, Cloud Security Analyst, etc.', 'Future Skills Qualification', 'N.A.', '{"Theory":"240","Practical":"150","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "302", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-IT-03661-2025-V2-NASSCOM', 'XR Developer', 'it-ites', 'IT-ITeS', 5.0, 'Individuals in this job role are responsible for developing software for AR/VR/MR experiences for varied industrial use cases. They also customize the solution based on the feedback and are responsible for evaluating and documenting product/software performance reports.They must manage and collaborate with various stakeholders involved in developing AR/VR solution experiences. They must have a strong analytical mindset and a zeal to learn new things.', 480, 480, '401–600', 'Version', '31 Mar 2022', '07 Oct 2028', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'Augmented reality/Virtual reality', 'Professional progression: access to related qualification(s) at the next NSQF level – Senior AR/VR Software Developer, Lead AR/VR Software Developer, etc.
Academic progression: access to other qualifications at the same NSQF level – AR/VR Designer, AR/VR Infrastructure Engineer, etc.', 'Future Skills Qualification', 'N.A.', '{"Theory":"120","Practical":"210","EmployabilitySkills":"60","OJT_Mandatory":"90"}', true, '{"MR"}'::text[], '{"source_row": "303", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-06-IT-045962025-V2-NASSCOM', 'IoT Solution Engineer', 'it-ites', 'IT-ITeS', 6.0, 'The IoT Solution Architect role encompasses designing, maintaining, and securing end-to-end IoT solutions. They analyze business needs, select appropriate platforms, and develop system architectures that integrate hardware, software, and communication protocols. They plan for data flow, quality checks, security architecture, and system interoperability, often incorporating AI, edge computing, and cloud services. They evaluate existing architectures for performance, security, reliability, and scalability, ensuring continuous improvement. Additionally, they design hardware components, oversee integration of IT and OT systems, enforce standards compliance, and validate solution effectiveness through testing. Security is prioritized across all layers, with ongoing updates to safeguard against threats. Overall, the architect ensures solutions meet technical, operational, and business objectives effectively and securely.', 600, 600, '401–600', 'Version', '25 Aug 2022', '07 Oct 2028', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'Internet of Things', 'Professional progression: access to related qualification(s) at the next NSQF level: Lead IoT Solution Architect, Lead IoT Product Manager, Lead IoT Network Specialist
Academic progression: access to related qualification(s) at the next NSQF level:   IoT Product Manager, IoT Network Specialist', 'Future Skills Qualification', 'N.A.', '{"Theory":"150","Practical":"270","EmployabilitySkills":"60","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "304", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-06-IT-045982025-V2-NASSCOM', 'IoT Security Analyst', 'it-ites', 'IT-ITeS', 6.0, 'An IoT Security Analyst is a professional specializing in protecting Internet of Things (IoT) devices, networks, and systems from threats and vulnerabilities. They design, implement, manage, and monitor security measures tailored to IoT environments, ensuring the confidentiality, integrity, and availability of data and operations. Their role involves understanding the unique security challenges of IoT devices—such as limited processing power, diverse protocols, and widespread deployment—and applying best practices, standards, and open-source tools to safeguard these assets. They also conduct vulnerability assessments, develop incident response plans, and ensure compliance with relevant security standards. Overall, an IoT Security Specialist helps organizations maintain resilient and secure IoT ecosystems critical for modern businesses and infrastructure.', 570, 570, '401–600', 'Version', '25 Aug 2022', '07 Oct 2028', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'Internet of Things', 'Professional progression: access to related qualification(s) at the next NSQF level:  Lead IoT Security Specialist, Lead IoT Network Specialist
Academic progression: access to related qualification(s) at the next NSQF level:  IoT Network Specialist', 'Future Skills Qualification', 'N.A.', '{"Theory":"144","Practical":"246","EmployabilitySkills":"60","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "305", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-IT-045812025-V2-NASSCOM', 'AI Data Engineering Analyst', 'it-ites', 'IT-ITeS', 5.0, 'Data Engineering analyst is responsible for designing, implementing, and maintaining the infrastructure that supports the collection, storage, processing, and analysis of data. They develop and manage data pipelines for extracting, transforming, and loading (ETL) data from various sources while ensuring data quality, accuracy, and security.
Key responsibilities include collaborating with stakeholders to identify data needs, managing databases (e.g., MySQL, PostgreSQL), implementing validation and monitoring processes, and utilizing tools like Apache Airflow and Tableau for data management and visualization. Data engineers also enforce data governance and compliance with regulations while continuously improving data processes based on performance metrics and user feedback.
Essential skills include proficiency in programming (especially Python and SQL), knowledge of data modeling and database design, and familiarity with cloud platforms and data security practices.', 480, 480, '401–600', 'Version', '22 Sep 2020', '07 Oct 2028', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'Artificial Intelligence and Big Data Analytics', '• Academic Progression: Access to other qualifications at the same NSQF level – Machine Learning Engineer 
• Professional Progression: Access to related qualification(s) at the next NSQF level –  AI-Data Architect, AI- Solutions Architect', 'Future Skills Qualification', 'N.A.', '{"Theory":"136","Practical":"194","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "306", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-06-IT-045842025-V2-NASSCOM', 'AI Data Architecture Analyst', 'it-ites', 'IT-ITeS', 6.0, 'The AI Data Architecture analyst qualification equips professionals with the essential skills to design, implement, and maintain data architectures that align with organizational goals. Participants will learn to assess business requirements, select appropriate technologies, and manage storage solutions while ensuring compliance with data governance and security standards. The curriculum covers key areas such as data quality assurance, performance optimization, and the implementation of security protocols. Upon completion, individuals will be adept at analyzing existing systems, innovating data integration solutions, and contributing to effective data management strategies, ultimately enabling organizations to leverage their data as a strategic asset for business success.', 570, 570, '401–600', 'Version', '22 Sep 2020', '07 Oct 2028', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'Artificial Intelligence and Big Data Analytics', '• Academic Progression: Access to other qualifications at the same NSQF level – AI Solutions Architect
• Professional Progression: Access to related qualification(s) at the next NSQF level – Enterprise architect', 'Future Skills Qualification', 'N.A.', '{"Theory":"180","Practical":"210","EmployabilitySkills":"60","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "307", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-06-IT-045852025-V2-NASSCOM', 'AI Solution Developer', 'it-ites', 'IT-ITeS', 6.0, 'The AI Solution Developer qualification is designed to equip individuals with the necessary skills and knowledge to design, implement, maintain, and validate AI-based solutions in various organizational contexts. The core competencies include understanding business requirements, evaluating platforms and technologies, implementing data governance, and ensuring compliance with ethical standards in AI. Candidates will learn to apply enterprise architecture principles, effectively manage data, and utilize various tools and methodologies to support the design and deployment of AI solutions. In addition, the qualification emphasizes the importance of monitoring and evaluating solution performance, ensuring ongoing compliance, and adapting to evolving industry standards. It also encompasses modules on employability skills, professional development, communication, and customer service, thereby preparing candidates for success in the workplace.', 570, 570, '401–600', 'Version', '22 Sep 2020', '07 Oct 2028', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'Artificial Intelligence and Big Data Analytics', '•Academic Progression: Access to other qualifications at the same NSQF level – Data Architect, Product Manager
•Professional Progression: Access to related qualification(s) at the next NSQF level – Enterprise architect', 'Future Skills Qualification', 'N.A.', '{"Theory":"180","Practical":"210","EmployabilitySkills":"60","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "308", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-6.5-IT-045912025-V2-NASSCOM', 'Cloud Engineer', 'it-ites', 'IT-ITeS', 6.5, 'A Cloud Engineer is responsible for designing, maintaining, and evaluating secure, scalable Cloud Engineerures aligned with business goals. The individual develops enterprise policies and governance frameworks for cloud adoption, supports the validation of customer proposals and project plans, and assesses the suitability of cloud vendors and third-party service providers to ensure optimal performance, compliance, and cost-efficiency.', 690, 690, '601–800', 'Version', '28 Jul 2022', '07 Oct 2028', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'Cloud Computing', 'Senior Cloud Architect', 'Future Skills Qualification', 'N.A.', '{"Theory":"180","Practical":"300","EmployabilitySkills":"60","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "309", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-6.5-IT-045922025-V2-NASSCOM', 'Cloud Security Analyst', 'it-ites', 'IT-ITeS', 6.5, 'A Cloud Security Analyst ensures that cloud operations align with organizational policies, regulatory requirements, and industry standards. The individual assesses cloud security risks, defines and monitors security controls, conducts audits, coordinates incident response, and tracks compliance through defined KPIs. The person supports secure and compliant cloud adoption across the organization.', 690, 690, '601–800', 'Version', '28 Jul 2022', '07 Oct 2028', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'Cloud Computing', 'Senior Cloud Security Analyst', 'Future Skills Qualification', 'N.A.', '{"Theory":"180","Practical":"300","EmployabilitySkills":"60","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "310", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-6.5-IT-045932025-V2-NASSCOM', 'Cloud Site Reliability Analyst', 'it-ites', 'IT-ITeS', 6.5, 'A Cloud Site Reliability Analyst is responsible for ensuring high availability, scalability, and performance of cloud-based infrastructure by leveraging automation, observability, and continuous improvement practices. The individual proactively manage incidents, define SLIs/SLOs, integrate modern DevOps tools, and contribute to platform resilience using techniques such as chaos engineering and infrastructure as code.', 510, 510, '401–600', 'Version', '28 Jul 2022', '07 Oct 2028', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'Cloud Computing', 'Senior Cloud Security Analyst', 'Future Skills Qualification', 'N.A.', '{"Theory":"120","Practical":"210","EmployabilitySkills":"60","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "311", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-IT-01509-2025-V2-NASSCOM', '3D Printing Modelling Engineer', 'it-ites', 'IT-ITeS', 5.0, 'Individuals at this job are responsible for creating design, conceptualization, development of 3d models in the design software programs and generation of the G-codes for printing the product', 480, 480, '401–600', 'Version', '28 Apr 2022', '07 Oct 2028', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', 'IT-ITeS Sector Skills Council NASSCOM (SSC NASSCOM)', '3D Printing', 'Lead Application Developer', 'General Qualification', 'N.A.', '{"Theory":"125","Practical":"205","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "312", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-3.5-IT-03808-2025-V1-NIELIT', 'Application of Data Annotation in Agriculture', 'it-ites', 'IT-ITeS', 3.5, 'This Micro Credential emphasizes the vital role of data annotation in strengthening modern agricultural practices. It enables students to identify and prepare a variety of agriculture-specific datasets, understand the ethical responsibilities involved in handling sensitive agricultural information, and apply appropriate annotation techniques to support data-driven solutions. The program further highlights how skilled data annotators contribute to the accuracy, quality, and usability of agricultural data used in crop monitoring, resource optimization, and informed decision-making.', 30, 30, '1–200', 'Version', '18 Feb 2025', '18 Feb 2028', 'National Institute of Electronics and Information Technology (NIELIT)', 'National Institute of Electronics and Information Technology (NIELIT)', 'AI Development', 'Not Applicable', 'Future Skills Qualification', 'N.A.', '{"Theory":"10","Practical":"20","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "313", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-3.5-IT-03809-2025-V1-NIELIT', 'Application of Data Annotation in Education', 'it-ites', 'IT-ITeS', 3.5, 'This course enables learners to understand and apply data annotation in the education sector by working with education-specific datasets such as student performance, curriculum content, and assessment data. It emphasizes ethical data handling, privacy compliance, and quality standards while providing hands-on experience with open-source annotation tools. Learners apply techniques like NER and text classification through real-world, project-based educational scenarios.', 30, 30, '1–200', 'Version', '18 Feb 2025', '18 Feb 2028', 'National Institute of Electronics and Information Technology (NIELIT)', 'National Institute of Electronics and Information Technology (NIELIT)', 'AI Development', 'Not Applicable', 'Future Skills Qualification', 'N.A.', '{"Theory":"10","Practical":"20","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "314", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NC-02-IT-04740-2026-V1-NIELIT', 'Yuva AI for All', 'it-ites', 'IT-ITeS', 2.0, 'The Yuva AI for All course is a 4.5-hour program developed by IndiaAI Mission that builds AI literacy by covering fundamentals, evolution, strengths, limitations, and applications. It dives into Machine Learning, Generative AI, LLMs, and prompting via the CRAFT formula, with hands-on use of tools like ChatGPT for learning, content creation, analysis, and problem-solving. Ethical aspects are addressed through the FAST framework, preparing learners for AI agents in the digital world.', 4, 4, '1–200', 'Version', '22 Jan 2026', '22 Jan 2029', 'National Institute of Electronics and Information Technology (NIELIT)', 'National Institute of Electronics and Information Technology', 'Artificial Intelligence Development', 'Not Applicable', 'Future Skills Qualification', 'N.A.', '{"Theory":"4.5","Practical":"0","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "315", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-04-IT-04174-2025-V2-NIELIT', 'Essentials of Cloud Computing and Virtualization (Upskilling)', 'it-ites', 'IT-ITeS', 4.0, 'The Standalone NOS “Essentials of Cloud Computing & Virtualization (Upskilling)” provides a strong foundation in cloud and virtualization, covering networking, deployment models, services, security, and communication skills through theory and practical applications. Participants gain hands-on experience with virtualized environments, cloud solutions, infrastructure provisioning, and security implementation using industry tools and platforms like VMware, Citrix, Hyper-V, VirtualBox, Kubernetes, and Google Cloud.', 210, 210, '201–400', 'Version', '08 May 2025', '08 May 2028', 'National Institute of Electronics and Information Technology (NIELIT)', 'National Institute of Electronics and Information Technology (NIELIT)', 'Cloud Management', 'Cloud Architect', 'Future Skills Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"83","Practical":"127","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "316", "qualification_type": "Future Skills Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_27.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
