INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-LT-04166-2025-V1-MSMETC', 'Technical Supervisor- Advanced Footwear Technology', 'leather', 'Leather', 5.0, 'Learners who attain this qualification are capable in Designing & Pattern Cutting, Clicking, Closing & Lasting making and finishing fields of Footwear and Allied sectors and can get a job in Production, Quality, Designing & Merchandising fields of Footwear sector and also can able to become an entrepreneur

Qualifying learners are capable to design a shoe, cut & assemble upper part of shoe and Lasting & finishing of Shoe', 1200, 1200, '1001–1200', 'Version', '08 May 2025', '08 May 2028', 'MSME Technology Centre, Ministry of Micro Small And Medium Enterprises, New Delhi', 'MSME Technology Centre', 'Shoemaker', 'Asst. Technical Manager', 'Multi-Skill Qualification', 'N.A.', '{"Theory":"300","Practical":"630","EmployabilitySkills":"30","OJT_Mandatory":"240"}', false, '{}'::text[], '{"source_row": "6", "qualification_type": "Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_07_41.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
