INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-05-LS-01047-2023-V1-LSSSDC', 'Retail Chemist Prescription Audit', 'life-sciences', 'Life Sciences', 5.0, 'The professional with Retail Chemist Prescription Audit will be able to gain knowledge and skills needed to excel in promoting pharmaceutical products to retail pharmacies, ensuring accurate sales reporting, and maintaining pharmacovigilance standards. This comprehensive micro credential covers essential areas such as understanding the retail pharmacy landscape, developing effective communication strategies, analyzing sales data for insights, and implementing pharmacovigilance processes. Participants will gain expertise in building relationships with pharmacy professionals, generating meaningful sales reports, and recognizing and reporting adverse drug reactions.', 30, 30, '1–200', 'Version', '29 Sep 2023', '29 Sep 2026', 'Life Sciences Sector Skill Development Council (LSSSDC)', 'Life Sciences Sector Skill Development Council (LSSSDC)', 'Sales and Marketing', 'N/A', 'Micro Credentials', 'N.A.', '{"Theory":"22","Practical":"08","EmployabilitySkills":"00","OJT_Mandatory":"00"}', false, '{}'::text[], '{"source_row": "9", "qualification_type": "Micro Credentials", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-05-LS-01048-2023-V1-LSSSDC', 'Retail Pharmacy Management and Sales', 'life-sciences', 'Life Sciences', 5.0, 'The individual will be able to gain knowledge and skills needed to excel in promoting pharmaceutical products to retail pharmacies, ensuring accurate sales reporting, and maintaining pharmacovigilance standards. This comprehensive microcredential covers essential areas such as understanding the retail pharmacy landscape, developing effective communication strategies, analyzing sales data for insights, and implementing pharmacovigilance processes. Participants will gain expertise in building relationships with pharmacy professionals, generating meaningful sales reports, and recognizing and reporting adverse drug reactions.', 30, 30, '1–200', 'Version', '29 Sep 2023', '29 Sep 2026', 'Life Sciences Sector Skill Development Council (LSSSDC)', 'Life Sciences Sector Skill Development Council (LSSSDC)', 'Sales and Marketing', 'N/A', 'Dual/Flexi Qualification,Micro Credentials,Upskilling Qualification', 'N.A.', '{"Theory":"20","Practical":"10","EmployabilitySkills":"00","OJT_Mandatory":"00"}', false, '{}'::text[], '{"source_row": "10", "qualification_type": "Dual/Flexi Qualification,Micro Credentials,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-04-LS-01049-2023-V1-LSSSDC', 'Foundation Skills for Retail Cashier', 'life-sciences', 'Life Sciences', 4.0, 'The professional with foundation skills for Retail Cashier is able to support  in cash handling and utilizing point of sale (POS) systems, excellent customer service abilities, product knowledge to assist customers, attention to detail for accurate transactions . This includes application of effective communication, time management to ensure efficiency, integrity and trustworthiness in handling money and customer information, and problem-solving capabilities to address challenges that may arise during shifts.', 15, 15, '1–200', 'Version', '29 Sep 2023', '29 Sep 2026', 'Life Sciences Sector Skill Development Council (LSSSDC)', 'Life Sciences Sector Skill Development Council (LSSSDC)', 'Sales and Marketing', 'N/A', 'Dual/Flexi Qualification,General Qualification,Micro Credentials', 'N.A.', '{"Theory":"12","Practical":"03","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "11", "qualification_type": "Dual/Flexi Qualification,General Qualification,Micro Credentials", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-04-LS-01050-2023-V1-LSSSDC', 'Order Management', 'life-sciences', 'Life Sciences', 4.0, 'The Micro Credential on Order Management provides learners with the essential knowledge and skills required to effectively handle and oversee point of sale operations. The program covers various aspects, including payment modes and procedures, transaction processing, customer service, and security measures. Learners will gain an understanding of the different payment modes accepted in retail environments and the procedures involved in processing each type of payment, such as cash, credit cards, and mobile payments. They will learn how to handle transaction errors, resolve payment discrepancies, and follow company-approved procedures for refunds and exchanges.', 30, 30, '1–200', 'Version', '29 Sep 2023', '29 Sep 2026', 'Life Sciences Sector Skill Development Council (LSSSDC)', 'Life Sciences Sector Skill Development Council (LSSSDC)', 'Sales and Marketing', 'N/A', 'Micro Credentials', 'N.A.', '{"Theory":"21","Practical":"09","EmployabilitySkills":"00","OJT_Mandatory":"00"}', false, '{}'::text[], '{"source_row": "12", "qualification_type": "Micro Credentials", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-4.5-LS-01051-2023-V1-LSSSDC', 'Managing Point of Sales (POS)', 'life-sciences', 'Life Sciences', 4.5, 'The Micro-Credential on Managing Point of Sales (POS) equips learners with the essential knowledge and skills required to effectively manage and oversee point-of-sale operations. The program encompasses various key aspects, including payment methods and procedures, transaction processing, customer service, and security measures. Learners will acquire an understanding of the different payment methods accepted in retail environments and the procedures involved in processing each type of payment, such as cash, credit cards, and mobile payments. They will also learn how to handle transaction errors, resolve payment discrepancies, and adhere to company-approved procedures for refunds and exchanges.', 30, 30, '1–200', 'Version', '29 Sep 2023', '29 Sep 2026', 'Life Sciences Sector Skill Development Council (LSSSDC)', 'Life Sciences Sector Skill Development Council (LSSSDC)', 'Sales and Marketing', 'N/A', 'Dual/Flexi Qualification,Micro Credentials,Upskilling Qualification', 'N.A.', '{"Theory":"22","Practical":"08","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "13", "qualification_type": "Dual/Flexi Qualification,Micro Credentials,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-4.5-LS-01052-2023-V1-LSSSDC', 'Payment and Transaction Management', 'life-sciences', 'Life Sciences', 4.5, 'The Micro-Credential on Payment and Transaction Management equips participants with the knowledge and skills needed to effectively manage payment transactions in a retail setting. This program provides a comprehensive understanding of various payment methods, processing procedures, and legal compliance requirements. It emphasizes the development of customer service skills, transaction accuracy, and accountability, all while underscoring the importance of privacy and security when handling customer information', 30, 30, '1–200', 'Version', '29 Sep 2023', '29 Sep 2026', 'Life Sciences Sector Skill Development Council (LSSSDC)', 'Life Sciences Sector Skill Development Council (LSSSDC)', 'Sales and marketing', 'N/A', 'Micro Credentials', 'N.A.', '{"Theory":"20","Practical":"10","EmployabilitySkills":"00","OJT_Mandatory":"00"}', false, '{}'::text[], '{"source_row": "14", "qualification_type": "Micro Credentials", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-5.5-LS-01296-2023-V1-LSSSDC', 'Aggregate Report writing for Regulatory Compliance', 'life-sciences', 'Life Sciences', 5.5, 'This NOS on  Aggregate Report writing for Regulatory Compliance will enable individual to have the capability to independently draft comprehensive Aggregate Reports that adhere to strict regulatory compliance standards, ensuring the accurate and timely submission of critical pharmacovigilance data, and demonstrating proficiency in the application of industry-specific best practices for report writing.', 60, 60, '1–200', 'Version', '01 Nov 2023', '01 Nov 2026', 'Life Sciences Sector Skill Development Council (LSSSDC)', 'Life Sciences Sector Skill Development Council', 'Pharmacovigilance', 'N/A', 'National Occupational Standard', 'N.A.', '{"Theory":"30","Practical":"30","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "15", "qualification_type": "National Occupational Standard", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-5.5-LS-01295-2023-V1-LSSSDC', 'Pharmacovigilance - Case Processing (Incidents/Adverse Event using softwares including AI tools)', 'life-sciences', 'Life Sciences', 5.5, 'This NOS on Pharmacovigilance Case Processing for Incidents/adverse event using software including AI tools will enable individual of adverse event processing, software tools, and advanced AI applications in drug safety. Participants will gain a comprehensive understanding of pharmacovigilance''s role in ensuring drug safety and the potential benefits and ethical considerations of AI integration. Regulatory compliance, data source analysis, and the practical application of AI tools are emphasized throughout the course. By the end, participants will be equipped to navigate the evolving field of pharmacovigilance with a strong focus on AI''s pivotal role in ensuring drug safety, efficiency, and compliance.', 60, 60, '1–200', 'Version', '01 Nov 2023', '01 Nov 2026', 'Life Sciences Sector Skill Development Council (LSSSDC)', 'Life Sciences Sector Skill Development Council (LSSSDC)', 'Pharmacovigilance', 'N/A', 'Future Skills Qualification', 'N.A.', '{"Theory":"30","Practical":"30","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "16", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-05-LS-01298-2023-V1-LSSSDC', 'Basics of Clinical Data Management', 'life-sciences', 'Life Sciences', 5.0, 'The professional with Basics of Clinical Data Management have foundational knowledge and skills in the field of clinical data management (CDM).  This includes understanding of the importance of CDM in clinical research, learn key terminology and concepts, explore data sources in clinical trials, delve into the design of case report forms (CRFs), and understand the critical processes of data entry, cleaning, and quality assurance in CDM. The professional with Basics of Clinical Data Management has good knowledge of regulatory guidelines and data privacy regulations that impact CDM practices.', 15, 15, '1–200', 'Version', '01 Nov 2023', '01 Nov 2026', 'Life Sciences Sector Skill Development Council (LSSSDC)', 'Life Sciences Sector Skill Development Council', 'Clinical Trials', 'N/A', 'Micro Credentials', 'N.A.', '{"Theory":"12","Practical":"03","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "17", "qualification_type": "Micro Credentials", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-05-LS-01299-2023-V1-LSSSDC', 'Advanced Data Capture Techniques in Clinical Data Management', 'life-sciences', 'Life Sciences', 5.0, 'The professional with Advanced Data Capture Techniques in Clinical Data Management is able to perform cutting-edge data capture techniques within the field of clinical data management. This includes Electronic Data Capture (EDC) systems, mobile health (mHealth) data collection, remote patient monitoring (RPM), electronic patient-reported outcomes (ePRO), and the integration of real-world data (RWD) into clinical databases. The professional with Advanced Data Capture Techniques in Clinical Data Management is prepared for roles demanding in-depth theoretical understanding, specialized technical proficiency, and the ability to make informed decisions in the dynamic field of clinical data management.', 30, 30, '1–200', 'Version', '01 Nov 2023', '01 Nov 2026', 'Life Sciences Sector Skill Development Council (LSSSDC)', 'Life Sciences Sector Skill Development Council', 'Clinical Trial', 'N/A', 'Micro Credentials', 'N.A.', '{"Theory":"20","Practical":"10","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "18", "qualification_type": "Micro Credentials", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-5.5-LS-01300-2023-V1-LSSSDC', 'Clinical Data Validation and Quality Control', 'life-sciences', 'Life Sciences', 5.5, 'The professional with Clinical Data Validation and Quality Control is able to  ensuring the accuracy and reliability of clinical data in clinical research industry. This includes  data validation principles, database locking, query management, data reconciliation, and quality control measures in Clinical Data Management (CDM). The professional with Clinical Data Validation and Quality Control has knowledge to manage discrepancies, uphold data integrity, and make informed decisions critical to the success of clinical trials and studies.', 30, 30, '1–200', 'Version', '01 Nov 2023', '01 Nov 2026', 'Life Sciences Sector Skill Development Council (LSSSDC)', 'Life Sciences Sector Skill Development Council (LSSSDC)', 'Clinical Trials', 'N/A', 'Dual/Flexi Qualification,Micro Credentials,Upskilling Qualification', 'N.A.', '{"Theory":"20","Practical":"10","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "19", "qualification_type": "Dual/Flexi Qualification,Micro Credentials,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-5.5-LS-01301-2023-V1-LSSSDC', 'Clinical Data Reporting and Analysis', 'life-sciences', 'Life Sciences', 5.5, 'The Professional with Clinical Data Reporting and Analysis skills is able to support in Clinical Data Management (CDM).  This includes data analysis, safety and efficacy reporting, Clinical Study Reports (CSRs) compilation, advanced data visualization, and meta-analysis.  The professional with Clinical Data Reporting and Analysis skills is proficient in ensuring data quality and compliance, making them indispensable in the healthcare and pharmaceutical sectors, where they contribute to informed decision-making and effective communication of research findings.', 30, 30, '1–200', 'Version', '01 Nov 2023', '01 Nov 2026', 'Life Sciences Sector Skill Development Council (LSSSDC)', 'Life Sciences Sector Skill Development Council', 'Clinical Trials', 'N/A', 'Micro Credentials', 'N.A.', '{"Theory":"20","Practical":"10","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "20", "qualification_type": "Micro Credentials", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-5.5-LS-01267-2023-V1-LSSSDC', 'Analyst- Drug Safety / Pharmacovigilance', 'life-sciences', 'Life Sciences', 5.5, 'Analyst- Drug Safety/ Pharmacovigilance is responsible for the collection of information on ADR/AE and processing of Individual Case Safety Reports (ICSR). The individual is responsible for preparation and submission of Periodic Safety Reports Like PSUR, PBRER, DUSR etc. The person is also expected to render support in development of Risk Management Plan (RMP) and Pharmacovigilance System Master File (PSMF). The individual  is also responsible for Global and local Literature Surveillance using literature databases (e.g. PubMed, Embase).This individual is involved in Processing , maintenance and safety of sensitive personal information in compliance with local regulations and company’s Global Pharmacovigilance requirements. The individual is responsible for permanent organized documented records of for all safety reports', 540, 540, '401–600', 'Version', '01 Nov 2023', '01 Nov 2026', 'Life Sciences Sector Skill Development Council (LSSSDC)', 'Life Sciences Sector Skill Development Council', 'Pharmacovigilance', 'Vertical progression,
1.Pharmacovigilance Scientist (Level 6)', 'Future Skills Qualification', 'N.A.', '{"Theory":"210","Practical":"270","EmployabilitySkills":"60","OJT_Mandatory":"00"}', false, '{}'::text[], '{"source_row": "21", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-5.5-LS-01271-2023-V1-LSSSDC', 'Junior Engineer-EMI/EMC testing for Medical Devices and IVD', 'life-sciences', 'Life Sciences', 5.5, 'Junior Engineer - EMI/EMC testing for Medical Devices and IVD is responsible for planning, conducting, and analysing electromagnetic compatibility tests on medical devices to ensure compliance with regulatory standards. The person is responsible for preparing the documents for reporting the test results and ensures ISO/IEC 17025 testing facility . He/she also carries out the validation of testing protocols and evaluating risk assessment as per ISO 14971', 540, 540, '401–600', 'Version', '01 Nov 2023', '01 Nov 2026', 'Life Sciences Sector Skill Development Council (LSSSDC)', 'Life Sciences Sector Skill Development Council (LSSSDC)', 'Quality-Medical Devices and IVD', 'Vertical Progression,
Engineer - Medical Devices and IVD Testing
(To be developed)', 'Future Skills Qualification', 'N.A.', '{"Theory":"210","Practical":"270","EmployabilitySkills":"60","OJT_Mandatory":"00"}', false, '{}'::text[], '{"source_row": "22", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-4.5-LS-01269-2023-V1-LSSSDC', 'Logistics Associate-Cold Chain Sustainability (Drug Products, Vaccines , Medical Devices and IVD)', 'life-sciences', 'Life Sciences', 4.5, 'A Logistics Associate - Cold Chain Sustainability, person is responsible for ensuring the safe and sustainable transportation and storage of critical products, including drug products, vaccines, medical devices, and in vitro diagnostics (IVD). This role involves collaborating with cross-functional teams, vendors, and stakeholders to uphold the highest standards of cold chain sustainability. He/She is responsible for overseeing the receiving, storage, inventory management, and transportation of temperature-sensitive products, maintaining compliance with regulatory standards, and ensuring the integrity of the cold chain throughout the supply chain process', 480, 480, '401–600', 'Version', '01 Nov 2023', '01 Nov 2026', 'Life Sciences Sector Skill Development Council (LSSSDC)', 'Life Sciences Sector Skill Development Council (LSSSDC)', 'Supply Chain', 'Vertical progression,
1.	Chemist- Retail Pharmacy Option: 1. Regulated Business Operations (Level-5),
2.	Lead Logistics-Life Sciences (level-5) (to be developed)', 'Future Skills Qualification', 'N.A.', '{"Theory":"180","Practical":"240","EmployabilitySkills":"60","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "23", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-4.5-LS-01268-2023-V1-LSSSDC', 'Production Technician: In-Vitro Diagnostic (IVD) Kits (Class A and Class B)', 'life-sciences', 'Life Sciences', 4.5, 'The Production Technician for In-Vitro Diagnostic Kits (Class A and Class B) manufacturing is responsible for operating the machines following Good Manufacturing Practices for the manufacturing of In-Vitro Diagnostic Kits (Class A and Class B). The jobholder verifies the output to ensure that in batch manufacturing, the quality parameters are met and performs basic in-process quality checks to ensure total quality management. He/she do routine analysis of manufacturing procedure. He/She also generates the critical records for every activity performed in compliance with data integrity rules. He/she also analyzes and reports production issues to seniors to solve work related problems. He/she also inspects products to verify conformance to specification.', 450, 450, '401–600', 'Version', '01 Nov 2023', '01 Nov 2026', 'Life Sciences Sector Skill Development Council (LSSSDC)', 'Life Sciences Sector Skill Development Council (LSSSDC)', 'Manufacturing -Medical Devices and IVD', 'Vertical Progression ,
Production Supervisor- Medical Devices and IVD (To be developed),', 'Future Skills Qualification', 'N.A.', '{"Theory":"180","Practical":"210","EmployabilitySkills":"60","OJT_Mandatory":"00"}', false, '{}'::text[], '{"source_row": "24", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-5-LS-01272-2023-V1-LSSSDC', 'PRODUCTION TECHNICIAN: MEDICAL DEVICE - STENTS', 'life-sciences', 'Life Sciences', 5.0, 'The Production Technician for stent manufacturing is responsible for performing various processes like laser cutting, descaling, annealing, electropolishing, Ultrasonic Cleaning, drug coating and primary packaging of stent following Good Manufacturing Practices for the manufacturing of stent. The jobholder verifies the output to ensure that in batch manufacturing the quality parameters are met and ensures basic in-process quality checks for quality management. He/She also generates the critical records for every activity performed in compliance with data integrity rules. He/she also analyzes and report production/maintenance/quality related issues to the senior for solving work related problems. He/she also inspects products to verify conformance to specification.', 480, 1200, '1001–1200', 'Version', '01 Nov 2023', '01 Nov 2026', 'Life Sciences Sector Skill Development Council (LSSSDC)', 'Life Sciences Sector Skill Development Council (LSSSDC)', 'Manufacturing – Medical Devices and IVD', 'Vertical Progression ,
Production Supervisor- Medical Devices and IVD (To be developed)', 'Dual/Flexi Qualification,Future Skills Qualification,Multi-Skill Qualification', 'N.A.', '{"Theory":"195","Practical":"195","EmployabilitySkills":"90","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "25", "qualification_type": "Dual/Flexi Qualification,Future Skills Qualification,Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
