INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-5.5-LS-04435-2025-V2-LSSSDC', 'Life Sciences GMP: Vendor Qualification', 'life-sciences', 'Life Sciences', 5.5, 'The Vendor Qualification Program equips life sciences professionals with skills capable of managing Vendor Qualification and audits in alignment with global life sciences industry regulations. The training covers Vendor Qualification types, step-by-step qualification processes, auditing tools, essential auditor skills, and application of the Six Systems Inspection Model. Through case studies, role-plays, and hands-on exercises, learners gain the competence to ensure vendor compliance and product quality, thereby supporting regulatory and business goals.', 15, 15, '1–200', 'Version', '29 Sep 2025', '29 Sep 2028', 'Life Sciences Sector Skill Development Council (LSSSDC)', 'Life Sciences Sector Skill Development Council (LSSSDC)', 'Generic', 'Not Available', 'Dual/Flexi Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"5","Practical":"10","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "57", "qualification_type": "Dual/Flexi Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-5-LS-04436-2025-V2-LSSSDC', 'Life Sciences GMP: Deviation Investigation and Regulatory Requirements', 'life-sciences', 'Life Sciences', 5.0, 'The Deviation Investigation and Regulatory Requirements Program equips life sciences professionals with foundational knowledge and practical skills in auditing within the life sciences sector, focusing on common audit failures, differences between CDSCO, FDA and European audits, and essential auditor qualifications. Participants will learn to conduct root cause analyses, compare regulatory audit styles, and align auditor competencies with GMP and ISO 19011 standards through practical activities and personal development planning.', 7, 7, '1–200', 'Version', '29 Sep 2025', '29 Sep 2028', 'Life Sciences Sector Skill Development Council (LSSSDC)', 'Life Sciences Sector Skill Development Council (LSSSDC)', 'Generic', 'Not Available', 'Dual/Flexi Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"2.5","Practical":"5","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "58", "qualification_type": "Dual/Flexi Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-5.5-LS-04437-2025-V2-LSSSDC', 'Life Sciences GMP: Investigative Steps and Analytical Tools for Deviation', 'life-sciences', 'Life Sciences', 5.5, 'The Investigative Steps and Analytical Tools for Deviation Program equips life sciences professionals with  necessary tools and methodologies to effectively investigate deviations in pharmaceutical manufacturing processes. Through understanding the structured approach to deviation investigation and applying key analytical tools such as 5 Whys, Fishbone Diagram, and Failure Mode and Effects Analysis (FMEA), learners will gain the ability to identify root causes, mitigate risks, and improve processes.', 15, 15, '1–200', 'Version', '29 Sep 2025', '29 Sep 2028', 'Life Sciences Sector Skill Development Council (LSSSDC)', 'Life Sciences Sector Skill Development Council (LSSSDC)', 'Generic', 'Not Available', 'Dual/Flexi Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"6","Practical":"9","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "59", "qualification_type": "Dual/Flexi Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-5.5-LS-04438-2025-V2-LSSSDC', 'Life Sciences GMP: Deviation types and Investigation Process Mode', 'life-sciences', 'Life Sciences', 5.5, 'The Deviation Types and Investigation Process Model Program equips life sciences professionals to effectively detect, classify, and investigate deviations in pharmaceutical manufacturing. Learners will understand the differences between minor, major, and critical deviations, and apply early detection and reporting methodologies. The course covers components of a robust deviation investigation model and best practices for deviation documentation. Through risk assessment exercises, case studies, and simulation activities, participants will develop practical skills in deviation classification and investigation process design.', 15, 15, '1–200', 'Version', '29 Sep 2025', '29 Sep 2028', 'Life Sciences Sector Skill Development Council (LSSSDC)', 'Life Sciences Sector Skill Development Council (LSSSDC)', 'Generic', 'Not Available', 'Dual/Flexi Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"6","Practical":"9","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "60", "qualification_type": "Dual/Flexi Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-06-LS-04439-2025-V2-LSSSDC', 'Life Sciences GMP: Deviation special Investigation & Reporting', 'life-sciences', 'Life Sciences', 6.0, 'The Deviation special Investigation & Reporting Program equips life sciences professionals with competency in handling Out-of-Specification (OOS) results and conducting thorough, regulatory-compliant investigations in pharmaceutical and life sciences manufacturing. Learners will be trained on regulatory expectations, stepwise investigation procedures, common pitfalls, and documentation best practices. In addition, the program emphasizes the role of Corrective and Preventive Actions (CAPA) and continuous improvement practices to avoid recurrence. Practical exercises, case studies, and peer reviews ensure participants gain hands-on experience in drafting investigation reports and implementing CAPA plans.', 15, 15, '1–200', 'Version', '29 Sep 2025', '29 Nov 2028', 'Life Sciences Sector Skill Development Council (LSSSDC)', 'Life Sciences Sector Skill Development Council (LSSSDC)', 'Generic', 'Not Available', 'Dual/Flexi Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"6","Practical":"9","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "61", "qualification_type": "Dual/Flexi Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-5.5-LS-04441-2025-V2-LSSSDC', 'Life Sciences GMP: Internal Audit Preparation & Compliance Management', 'life-sciences', 'Life Sciences', 5.5, 'The Internal Audit Preparation & Compliance Management   program provides skills on the audit lifecycle, from preparation to execution, reporting, and follow-up. Participants will learn how to plan and organize for internal and external audits, demonstrate effective communication during audits, and perform audits aligned with regulatory standards. The course emphasizes drafting structured audit reports, managing wrap-up meetings, addressing audit findings through CAPA, and formulating responses to 483/EIR/Warning Letters. Practical exercises, role-plays, and mock audits are used to develop real-world auditing skills essential for life sciences industries.', 15, 15, '1–200', 'Version', '29 Sep 2025', '29 Sep 2028', 'Life Sciences Sector Skill Development Council (LSSSDC)', 'Life Sciences Sector Skill Development Council', 'Not Applicable', 'Not Applicable', 'Dual/Flexi Qualification,General Qualification,Micro Credentials,Upskilling Qualification', 'N.A.', '{"Theory":"6","Practical":"9","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "62", "qualification_type": "Dual/Flexi Qualification,General Qualification,Micro Credentials,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-5.5-LS-04442-2025-V2-LSSSDC', 'Life Sciences GMP: Audit Essentials and Auditor Qualification', 'life-sciences', 'Life Sciences', 5.5, 'The Audit Essentials and Auditor Qualification Program equips life sciences professionals with foundational knowledge and practical skills in auditing within the life sciences sector, focusing on common audit failures, differences between CDSCO, FDA and European audits, and essential auditor qualifications. Participants will learn to conduct root cause analyses, compare regulatory audit styles, and align auditor competencies with GMP and ISO 19011 standards through practical activities and personal development planning.', 15, 15, '1–200', 'Version', '29 Sep 2025', '29 Sep 2028', 'Life Sciences Sector Skill Development Council (LSSSDC)', 'Life Sciences Sector Skill Development Council', 'Not Applicable', 'Not Applicable', 'Dual/Flexi Qualification,General Qualification,Micro Credentials,Upskilling Qualification', 'N.A.', '{"Theory":"2.5","Practical":"5","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "63", "qualification_type": "Dual/Flexi Qualification,General Qualification,Micro Credentials,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_ran