INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-5.5-LS-04440-2025-V2-LSSSDC', 'Life Sciences GMP: Basics of Self Inspection & Quality audit', 'life-sciences', 'Life Sciences', 5.5, 'The Basics of Self Inspection & Quality audit Program equips life sciences professionals with essential knowledge and practical skills in regulatory compliance, harmonized Good Manufacturing Practices (GMP), and effective audit management in the life sciences sector. Learners will gain a deep understanding of global regulatory ecosystems, CFR requirements, and the role of self-inspections and audits in maintaining responsible manufacturing and patient safety. Practical exercises will help learners prepare checklists, conduct mock inspections, and develop structured audit programs aligned with industry and regulatory expectations.', 7, 7, '1–200', 'Version', '29 Sep 2025', '29 Sep 2028', 'Life Sciences Sector Skill Development Council (LSSSDC)', 'Life Sciences Sector Skill Development Council', 'Not Applicable', 'Not Applicable', 'Dual/Flexi Qualification,General Qualification,Micro Credentials,Upskilling Qualification', 'N.A.', '{"Theory":"2.5","Practical":"5","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "64", "qualification_type": "Dual/Flexi Qualification,General Qualification,Micro Credentials,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-5-LS-04426-2025-V2-LSSSDC', 'Chemist- Retail Pharmacy', 'life-sciences', 'Life Sciences', 5.0, 'Chemist - Retail Pharmacy is responsible for supporting pharmacy operations by ensuring valid prescription processing, accurate order fulfilment, and effective customer interaction in compliance with regulatory standards. The role involves managing sales transactions, maintaining proper drug storage with cold chain and expiry monitoring, and handling inventory efficiently. The job holder is also expected to uphold the pharmacy ''s professional image, promote responsible use of medicines, and contribute to pharmacovigilance and safe handling of controlled substances, while understanding the basics of retail operations within the Life Sciences industry.', 510, 510, '401–600', 'Version', '29 Sep 2025', '29 Sep 2028', 'Life Sciences Sector Skill Development Council (LSSSDC)', 'Life Sciences Sector Skill Development Council', 'Supply Chain Management', 'Not Available', 'Dual/Flexi Qualification,Future Skills Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"93","Practical":"127","EmployabilitySkills":"60","OJT_Mandatory":"230"}', false, '{}'::text[], '{"source_row": "65", "qualification_type": "Dual/Flexi Qualification,Future Skills Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-06-LS-04425-2025-V2-LSSSDC', 'Associate- Regulatory Affairs and Intellectual Property (Medical Devices) Options: 1. Regulated Business Operations', 'life-sciences', 'Life Sciences', 6.0, 'Associate- Regulatory Affairs and Intellectual Property (Medical Devices) prepares dossiers and liaison with regulatory bodies in India and relevant overseas markets to support appropriate approvals at various levels of technology readiness during product development, as well as for manufacturing, marketing and import license to ensure regulatory and legal compliance of Medical Devices in targeted markets. The job holder also facilitated in securing quality certification like CE, ISO, IEC, BIS, ICMED etc for the medical devices. The job role holder carries out proper documentation and reporting for dossier preparation and assist in patent filing for intellectual property management of innovations in medical devices.', 570, 630, '601–800', 'Version', '29 Sep 2025', '29 Sep 2028', 'Life Sciences Sector Skill Development Council (LSSSDC)', 'Life Sciences Sector Skill Development Council', 'Research and Development', 'Not Available', 'Apprenticeship Qualification,Dual/Flexi Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"175","Practical":"335","EmployabilitySkills":"60","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "66", "qualification_type": "Apprenticeship Qualification,Dual/Flexi Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-5.5-LS-04429-2025-V2-LSSSDC', 'Human Error Reduction (Behavioral GMP)', 'life-sciences', 'Life Sciences', 5.5, 'This NOS program equips individuals in pharmaceutical manufacturing with the skills to understand, investigate, prevent, and reduce human errors. It covers key aspects of human behaviour, error investigation techniques, and prevention tools such as Root Cause Analysis, Fishbone Diagrams, Poka-Yoke, and SOPs. The program emphasizes leadership, organizational culture, and continuous monitoring for creating a sustainable error-free environment. Through practical exercises and case studies, participants will gain hands-on experience in mitigating errors, improving product quality, safety, and efficiency.', 45, 45, '1–200', 'Version', '29 Sep 2025', '29 Sep 2028', 'Life Sciences Sector Skill Development Council (LSSSDC)', 'Life Sciences Sector Skill Development Council', 'Not Applicable', 'Not Applicable', 'Dual/Flexi Qualification,General Qualification,National Occupational Standard,Upskilling Qualification', 'N.A.', '{"Theory":"20","Practical":"25","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "67", "qualification_type": "Dual/Flexi Qualification,General Qualification,National Occupational Standard,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_04.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-02-MG-046492025-V1-SS', 'Yuva Udyami (Basics)', 'management', 'Management', 2.0, 'Yuva Udyami (Basics) is a CMYUVA Scheme Orientation and Entrepreneurial Capacity Building Qualification developed for the Mukhyamantri Yuva Udyami (Basics) Vikas Abhiyan (CMYUVA) initiative by the Directorate of Industries and Enterprise Promotion, Government of Uttar Pradesh, in line with the respective mission office recommendations. It aims to prepare youth (aged 21–40) for successful enterprise creation by providing structured training before loan disbursement. The program covers entrepreneurship fundamentals, legal compliances, financial and digital literacy, operations management, life skills, and capacity building for sector-specific basic project conception. This qualification ensures that beneficiaries of CMYUVA are not only financially supported but also equipped with practical skills, decision-making ability, and execution readiness to sustain and scale their businesses.', 30, 30, '1–200', 'Version', '07 Oct 2025', '06 Oct 2028', 'Samadhan Samiti', 'Samadhan Samiti, 2nd Floor, Siddhivinayak Building, 27/1/B Samadhan Tower, Gokhale Marg, Lucknow, Uttar Pradesh, Pincode - 226001', 'Entrepreneurship', 'N/A', 'General Qualification', 'N.A.', '{"Theory":"10","Practical":"20","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "1", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_12.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2021/ME/MESC/04873', 'AR/VR Developer', 'media-entertainment', 'Media & Entertainment', 6.0, 'Augmented Reality (AR) developers enhances the user experiences by overlaying digital information on top of the real world. The virtual reality designer develops virtual reality to simulate the user experiences and the complex object interactions or services with one another and with the user.
The individual in this role is to works closely/ guide the various execution team, pre-production team, asset development team, technical team throughout the visualisation design and development process to ensure that the final product will accomplish the object of the project. AR/VR developers are responsible for putting the plan into action, which may include designing AR assets, along with providing support and ongoing maintenance for the user during project life cycle.', 1080, 1230, '1201–2400', 'Version', '30 Dec 2021', '30 Dec 2026', 'Media & Entertainment Skill Council (MESC)', 'Media & Entertainment Skills Council', 'Game Design', 'Entrepreneur, Chief Technology Officer', 'Future Skills Qualification', 'N.A.', '{"Theory":"420","Practical":"600","EmployabilitySkills":"60","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "1", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_21.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2021/ME/MESC/04864', 'Assistant Costume Designer', 'media-entertainment', 'Media & Entertainment', 3.0, 'Assistant Costume Designer assists the Costume designer who designs costumes for a film, stage, production or television shout. The assistant costume designer is to make the characters'' outfits/costumes as per the direction of Costume designer.
Coordinates elements for fittings including all pulled and purchased items. Creates dressing lists as needed for wardrobe and maintains production bible. Attends production meetings and rehearsals as needed.', 510, 600, '401–600', 'Version', '30 Dec 2021', '29 Dec 2025', 'Media & Entertainment Skill Council (MESC)', 'Media & Entertainment Skill Council', 'Costume Designing', '•	Costume Designer at NSQF level 4
•	Costume Supervisor at NSQF Level 5', 'General Qualification', 'N.A.', '{"Theory":"180","Practical":"300","EmployabilitySkills":"30","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "2", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_21.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2021/ME/MESC/04868', 'Cinematographer', 'media-entertainment', 'Media & Entertainment', 5.0, 'A Cinematographer is an artist, using video camera and responsible for transporting or setting up the equipment, shooting, hauling it away, and then creating the movie or film clip/news clip etc.  Apart from capturing the clip individual will also be responsible for video editing, inserting closed captions, graphics, or other on-screen text into a video and special effects to a video. These tasks may vary by type of Videographer.  For example, a wedding Videographer might spend the day talking to the client and shooting the event while a Newspaper Videographer will be filming scenes of human crisis, political news, etc. in all the cases the responsibility of the individual is behind the camera.', 600, 600, '401–600', 'Version', '30 Dec 2021', '29 Dec 2025', 'Media & Entertainment Skill Council (MESC)', 'Media & Entertainment Skills Council', 'Camera Operations, Photography', 'Director of Photography', 'General Qualification', 'N.A.', '{"Theory":"165","Practical":"285","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "3", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_21.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2021/ME/MESC/04865', 'Costume Designer', 'media-entertainment', 'Media & Entertainment', 4.0, 'Costume designer is a person who designs costumes for a film, stage, production, or television shout. The role of the costume designer is to create the characters'' outfits/costumes and balance the scenes with texture and colour, etc.
Costume Designer must deliver initial ideas to Directors about the overall costume vision, character plots and original costume designs, using sketches and fabric samples. They also discuss colour palettes with the Director of Photography and Production Designer. The costume designer may also collaborate with hair stylist, wig master, or makeup artist.', 540, 630, '601–800', 'Version', '30 Dec 2021', '29 Dec 2025', 'Media & Entertainment Skill Council (MESC)', 'Media & Entertainment Skill Council', 'Costume Designing', 'Costume Supervisor, Stylist', 'General Qualification', 'N.A.', '{"Theory":"150","Practical":"330","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "4", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_21.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2021/ME/MESC/04870', 'Event Planner/Event Manager', 'media-entertainment', 'Media & Entertainment', 5.0, 'An event planner is the individual responsible for ensuring an event, wedding, conference, or festival goes to plan and achieves all of the event objectives originally set. They are responsible for envisioning the dream and thereafter planning the execution to a tee with a checklist of items such as identifying suppliers and execution partners, ensuring all suppliers and partners know what is expected of them and what others are delivering; ensuring suppliers turn up on time and that the presenter/performers are booked and on schedule, to wider items such as ensuring that the event adheres to health and safety or sustainability concerns.', 420, 510, '401–600', 'Version', '30 Dec 2021', '29 Dec 2025', 'Media & Entertainment Skill Council (MESC)', 'Media & Entertainment Skills Council', 'Account Management', '•	Account Manager (Horizontal Progression))
•	Account Director
•	Manager (Operations)', 'General Qualification', 'N.A.', '{"Theory":"105","Practical":"255","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "5", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_21.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2021/ME/MESC/04871', 'Game Artist', 'media-entertainment', 'Media & Entertainment', 5.0, 'A game artist is an artist who creates art for one or more types of games. In this role an individual will be liable to create 2D and 3D art for the visual elements of a video game, such as characters, vehicles, props, scenery, background, objects, colours, textures, and clothing.
In video games, game artists are responsible for all  the aspects of game development that call for visual art. Game artists play a vital role and are often credited in role-playing games, collectible card games and video games.', 1050, 1050, '1001–1200', 'Version', '30 Dec 2021', '29 Dec 2025', 'Media & Entertainment Skill Council (MESC)', 'Media & Entertainment Skills Council', 'Game Development', 'Game Tester (Horizontal)
Technical Artist – AR/VR  (Horizontal)
Visual Artist
AR/VR Developer
Entrepreneur', 'General Qualification', 'N.A.', '{"Theory":"315","Practical":"585","EmployabilitySkills":"00","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "6", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_21.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2021/ME/MESC/04866', 'Offset Print Operator', 'media-entertainment', 'Media & Entertainment', 4.0, 'Individuals at this job will provide all printing operation specially for offset printing. The individual will also carry out 3D printing which company offerings and get more customers and sales through print media.', 390, 450, '401–600', 'Version', '30 Dec 2021', '29 Dec 2025', 'Media & Entertainment Skill Council (MESC)', 'Media & Entertainment Skills Council', 'Printing', '•	Printing Supervisor NSQF Level 5
•	General Manager -Print at NSQF Level 7', 'General Qualification', 'N.A.', '{"Theory":"150","Practical":"240","EmployabilitySkills":"60","OJT_Mandatory":"00"}', false, '{}'::text[], '{"source_row": "7", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_21.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2021/ME/MESC/04869', 'Project Manager (OOH) Media', 'media-entertainment', 'Media & Entertainment', 5.0, 'A Project Manager in an OOH Media Company will be responsible for erection of media at selected / licensed site, in compliance of all statutory conditions and as per design & budget. This position manages multiple outdoor media projects as per the business requirement and follows / implements applicable regulatory guidelines.', 480, 540, '401–600', 'Version', '30 Dec 2021', '29 Dec 2025', 'Media & Entertainment Skill Council (MESC)', 'Media & Entertainment Skills Council', 'OOH and Advertising', '•	Head Operations-OOH at NSQF level 6
•	Business Manager -OOH at NSQF Level 7
•	Director-Operations at Level 8', 'General Qualification', 'N.A.', '{"Theory":"210","Practical":"270","EmployabilitySkills":"60","OJT_Mandatory":"00"}', false, '{}'::text[], '{"source_row": "8", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_21.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2021/ME/MESC/04867', 'Still Photographer', 'media-entertainment', 'Media & Entertainment', 4.0, 'A Still photographer, is an artist with the camera using a blend of technical skills and an artistic eye to take pictures, who creates film stills, still photographic images specifically intended for use in the marketing and publicity of feature films. Photographers can work as fine artists, wedding and event photographers, or sell their photos to commercial clients.', 510, 510, '401–600', 'Version', '30 Dec 2021', '29 Dec 2025', 'Media & Entertainment Skill Council (MESC)', 'Media & Entertainment Skills Council', 'Photography', 'Videographer, Cinematographer, Director of Photography', 'General Qualification', 'N.A.', '{"Theory":"180","Practical":"210","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "9", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_21.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2021/ME/MESC/04872', 'Technical Artist – AR/VR', 'media-entertainment', 'Media & Entertainment', 5.0, 'The individual in this job will act as an architecture and overlays AR-VR solution to deliver experience of their project vision to prospective users for analysis, learning and game development purpose. It articulates 3D content products for Virtual & Augmented Reality application with smart technology driven system (hardware) which brings realistic views to users. The Technical Artist also acts as bridge between the artists and programmers, ensuring the art content and features are easily integrated into the environment.', 990, 1140, '1001–1200', 'Version', '30 Dec 2021', '29 Dec 2025', 'Media & Entertainment Skill Council (MESC)', 'Media & Entertainment Skills Council', 'Game Development', 'AR-VR Developer
Entrepreneur', 'Future Skills Qualification', 'N.A.', '{"Theory":"345","Practical":"585","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "10", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_21.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/ME/MESC/05190', 'ACCOUNT EXECUTIVE', 'media-entertainment', 'Media & Entertainment', 4.0, 'The individuals in this job are required to understand advertising requirements from the client and coordinate with the creative teams within the agency to have them executed. The individual may also be required to liaise with external vendors for production of advertisements, in which case they would be required to negotiate an agreeable fee on behalf of the client. The individual is required to present final work products to clients and obtain their approval', 390, 450, '401–600', 'Version', '27 Jan 2022', '25 Jan 2027', 'Media & Entertainment Skill Council (MESC)', 'MESC – Media & Entertainment Skills Council', 'Account Executive', 'Account Manager, Account Director', 'General Qualification', 'N.A.', '{"Theory":"120","Practical":"210","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "11", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_21.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/ME/MESC/05191', 'ADVERTISING OPERATIONS COORDINATOR', 'media-entertainment', 'Media & Entertainment', 4.0, 'The individuals in this job are required to fulfil sales orders for online campaigns, including placing media bought by advertisers/agencies and running it as planned. The individual is also responsible to evaluate the effectiveness of online campaigns, manage the online advertisement hardware and systems and troubleshoot and technical and delivery issues that might arise. The individual must also be equipped with a thorough knowledge of online advertising and advertisement operations, coding languages and trafficking solutions.', 450, 450, '401–600', 'Version', '27 Jan 2022', '25 Jan 2027', 'Media & Entertainment Skill Council (MESC)', 'MESC – Media & Entertainment Skills Council', 'Advertising Operations Coordinator.', 'Manager-Operations/Sales Manager', 'General Qualification', 'N.A.', '{"Theory":"120","Practical":"210","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "12", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_21.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
