INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/ME/MESC/05215', 'SALES EXECUTIVE (Media Org)', 'media-entertainment', 'Media & Entertainment', 4.0, 'Individuals at this job are responsible to close sales transactions with new and existing clients', 450, 450, '401–600', 'Version', '27 Jan 2022', '25 Jan 2027', 'Media & Entertainment Skill Council (MESC)', 'MESC – Media & Entertainment Skills Council', 'The individuals in this job are required to achieve sales targets set by the sales manager. The individual is responsible to acquire new clients, develop proposals for new and existing clients and close sales orders', 'Sales Manager', 'General Qualification', 'N.A.', '{"Theory":"120","Practical":"210","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "36", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_21.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/ME/MESC/05216', 'SCRIPT RESEARCHER', 'media-entertainment', 'Media & Entertainment', 4.0, 'Individuals at this job read and assess the script for the merit of the story, its dramaturgy and overall competence and offer feedback and notes for improvement to make the script production worthy.', 450, 450, '401–600', 'Version', '27 Jan 2022', '25 Jan 2027', 'Media & Entertainment Skill Council (MESC)', 'MESC – Media & Entertainment Skills Council', 'The individuals in this job are required to have a sound understanding of the craft of screenwriting. The individual must be able to read a script and understand the premise and intention embedded in the story. The individual must be able to assess the script and narrative style and identify areas of improvement to enhance the impact and quality of the script.', 'Script Writer
Script Editor', 'General Qualification', 'N.A.', '{"Theory":"135","Practical":"195","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "37", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_21.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/ME/MESC/05217', 'SCRIPT WRITER', 'media-entertainment', 'Media & Entertainment', 5.0, 'Individuals at this job need to write full length scripts that are production-ready. Note: In the Indian film industry, the script is often constructed as a sum of 3 elements: Story, Screenplay and Dialogue and three different individuals usually write these. However, ideally the entire script should be written by one writer (or at least the screenplay and dialogue)', 540, 540, '401–600', 'Version', '27 Jan 2022', '25 Jan 2027', 'Media & Entertainment Skill Council (MESC)', 'MESC – Media & Entertainment Skills Council', 'SCRIPT WRITER', 'SCRIPT EDITOR
Entrepreneurship', 'General Qualification', 'N.A.', '{"Theory":"225","Practical":"255","EmployabilitySkills":"60","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "38", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_21.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
