INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/ME/MESC/05441', 'COMMUNITY JOURNALIST', 'media-entertainment', 'Media & Entertainment', 4.0, 'A Community Journalist helps the correspondent and editorial team in newsroom by circulating or providing local news on different subjects important to community. He/she gathers information by capturing pictures / videos and creates case highlights, news stories, to be used for television, radio or in magazines, newspapers, etc.', 510, 510, '401–600', 'Version', '24 Feb 2022', '23 Feb 2027', 'Media & Entertainment Skill Council (MESC)', 'MESC – Media & Entertainment Skill Council', 'Journalism', 'Feature Writer / Sr. Correspondent', 'General Qualification', 'N.A.', '{"Theory":"150","Practical":"240","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "54", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_21.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
