INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/ME/MESC/05438', 'SALES MANAGER', 'media-entertainment', 'Media & Entertainment', 6.0, 'Individuals at this job are responsible to lead sales activities within the designated area of responsibility', 840, 840, '801–1000', 'Version', '24 Feb 2022', '23 Feb 2027', 'Media & Entertainment Skill Council (MESC)', 'MESC – Media & Entertainment Skill Council', 'The individuals in this job are required to achieve sales targets set by the sales manager. The individual is responsible to acquire new clients, develop proposals for new and existing clients and close sales orders', 'Entrepreneur / Businessman', 'General Qualification', 'N.A.', '{"Theory":"240","Practical":"510","EmployabilitySkills":"60","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "61", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_21.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/ME/MESC/05439', 'SCRIPT EDITOR', 'media-entertainment', 'Media & Entertainment', 6.0, 'Individuals at this job read and assess the script for the merit of the story, its dramaturgy and overall competence and offer feedback and notes for improvement to make the script production worthy.', 840, 840, '801–1000', 'Version', '24 Feb 2022', '23 Feb 2027', 'Media & Entertainment Skill Council (MESC)', 'MESC – Media & Entertainment Skill Council', 'The individuals in this job are required to have a sound understanding of the craft of screenwriting. The individual must be able to read a script and understand the premise and intention embedded in the story. The individual must be able to assess the script and narrative style and identify areas of improvement to enhance the impact and quality of the script.', 'Entrepreneur / Businessman', 'General Qualification', 'N.A.', '{"Theory":"285","Practical":"495","EmployabilitySkills":"60","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "62", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_21.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/ME/MESC/05443', 'Search Engine Marketing Executive', 'media-entertainment', 'Media & Entertainment', 4.0, 'Individuals in this job are responsible for managing all paid search campaigns on all major search engine networks. They are responsible for setting up pay-per-click (PPC) campaigns and execute activities such as keyword research, advertisement copies creation, keywords bidding, set-up of advertisement extensions etc. to drive relevant paid traffic to the website or landing pages.', 540, 540, '401–600', 'Version', '24 Feb 2022', '23 Feb 2027', 'Media & Entertainment Skill Council (MESC)', 'Media & Entertainment Skills Council', 'Marketing, Ad Sales, Traffic', 'Social Media Manager', 'General Qualification', 'N.A.', '{"Theory":"150","Practical":"270","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "63", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_21.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/ME/MESC/05444', 'Social Media Executive', 'media-entertainment', 'Media & Entertainment', 4.0, 'Individuals in this job handle all the social media activities for their company/ multiple clients in order to create brand awareness. It comprises of ideating, coordinating, executing social media campaigns, promotions and advertisements. The individual is responsible for the regular posting, sharing and updating the social media activities on all the major social media networks.', 510, 510, '401–600', 'Version', '24 Feb 2022', '23 Feb 2027', 'Media & Entertainment Skill Council (MESC)', 'Media & Entertainment Skills Council', 'Marketing / Ad Sales/ Traffic', 'Social Media Manager NSQF level 5, Digital Marketing Manager NSQF Level 6', 'General Qualification', 'N.A.', '{"Theory":"120","Practical":"270","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "64", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_21.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/ME/MESC/05440', 'TRAFFIC COORDINATOR (Media Organisations)', 'media-entertainment', 'Media & Entertainment', 4.0, 'The individuals in this job are required to manage inventory and schedule advertisements for a broadcasting company. The individual needs to be well versed with the daily programme schedules and must be able to coordinate with the programming teams, as well as the agencies, to receive information on the duration of programmes/advertisements, to prepare playout schedules and make adjustments in the event of any change.', 540, 540, '401–600', 'Version', '24 Feb 2022', '23 Feb 2027', 'Media & Entertainment Skill Council (MESC)', 'MESC – Media & Entertainment Skills Council', 'Traffic Coordinator (Media Organisations)', 'Not Applicable', 'General Qualification', 'N.A.', '{"Theory":"180","Practical":"300","EmployabilitySkills":"00","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "65", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_21.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/ME/MESC/05442', 'SEARCH ENGINE OPTIMIZATION EXECUTIVE', 'media-entertainment', 'Media & Entertainment', 4.0, 'Individuals at this job carry out the search engine optimization process to increase the organic traffic of the website in all the major search engine networks.
Research list of relevant keywords, implement on-page and off-page search engine optimization activities, track keyword rankings and prepare performance reports for the key stakeholders.', 540, 540, '401–600', 'Version', '24 Feb 2022', '23 Feb 2027', 'Media & Entertainment Skill Council (MESC)', 'Media & Entertainment Skills Council', 'Marketing / Advertising Sales / Traffic', 'Social Media Manager', 'General Qualification', 'N.A.', '{"Theory":"135","Practical":"285","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "66", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_21.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/ME/MESC/05437', 'Sales Director (Media Org.)', 'media-entertainment', 'Media & Entertainment', 6.0, 'The individuals in this job are required to understand business objectives and develop sales plans, forecasts, targets and budgets. The individual is required to finalise the structure of the sales team and oversee their sales efforts to ensure that they are in line with the targets that needs to be achieved. The individual must also manage the key clients of the company and procure new clients.', 840, 840, '801–1000', 'Version', '24 Feb 2022', '23 Feb 2027', 'Media & Entertainment Skill Council (MESC)', 'MESC – Media & Entertainment Skill Council', 'Ad Sales', 'Entrepreneur, Businessman', 'General Qualification', 'N.A.', '{"Theory":"300","Practical":"480","EmployabilitySkills":"60","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "67", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_21.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/ME/MESC/05445', 'Social Media Manager', 'media-entertainment', 'Media & Entertainment', 5.0, 'A social Media Manager is a creative individual whose primary responsibility is to develop and implement a social media marketing plan across all social media platforms. He should be able to handle all the social media activities for his company/ multiple clients. It comprises of ideating, coordinating, executing social media campaigns, promotions and advertisements. He is responsible for the supervision of social media department and ensuring regular posting, sharing and updating the social media activities.', 540, 540, '401–600', 'Version', '24 Feb 2022', '23 Feb 2027', 'Media & Entertainment Skill Council (MESC)', 'Media & Entertainment Skills Council', 'Marketing/ Ad Sales / Traffic', 'Digital Marketing Manager/General Manager Marketing/Vice President (Marketing)/Head-Marketing', 'General Qualification', 'N.A.', '{"Theory":"180","Practical":"300","EmployabilitySkills":"60","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "68", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_21.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/ME/MESC/05697', '3D Printing Operator', 'media-entertainment', 'Media & Entertainment', 4.0, 'A 3D printer operator is a competent individual with technical and creative skills in additive manufacturing. They use computer-aided (CAD) software to develop designs to be 3D printed into finished works.
3D Printing technicians assist in the designing and programming of products, ranging from prosthetic products to 3D miniatures. They may also provide 3D printing maintenance, check 3D renders for customers and run 3D printing tests. 3D printing technicians can also repair, maintain and clean 3D printers.', 510, 570, '401–600', 'Version', '31 Mar 2022', '30 Mar 2027', 'Media & Entertainment Skill Council (MESC)', 'MESC – Media & Entertainment Skills Council', 'Printing', 'Level 5 (Vertical)
Designer / CAD Operator', 'Future Skills Qualification', 'N.A.', '{"Theory":"180","Practical":"270","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "69", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_21.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/ME/MESC/05688', 'Anchor', 'media-entertainment', 'Media & Entertainment', 6.0, 'Individual in this role will work closely with reporters and will be responsible for gathering information, broadcasting newscasts/commentary/biography etc. throughout the day and interviewing guests. He/she shall follow current events and present news stories to audiences in an informative, interesting, and unbiased way.
Anchors are responsible for helping gather information, interviewing live guests, and coordinating between reporters during broadcasts.', 900, 900, '801–1000', 'Version', '31 Mar 2022', '30 Mar 2027', 'Media & Entertainment Skill Council (MESC)', 'MESC – Media & Entertainment Skills Council', 'Journalism', 'Level 7 (Vertical)
Editor-in-Chief
Entrepreneur', 'General Qualification', 'N.A.', '{"Theory":"270","Practical":"570","EmployabilitySkills":"60","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "70", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_21.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
