INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/ME/MESC/05696', 'Media IP (Intellectual Property) Merchandising Director', 'media-entertainment', 'Media & Entertainment', 6.0, 'The Intellectual Property Merchandising Director must combine strong abilities to influence, collaborate, build culture and lead with deep Intellectual Property knowledge and skills so as to advise, inform and execute on behalf of the Participating Institutions, whereas these Institutions have different research strengths, different sizes and budgets and unique management structures, metrics and intellectual property policies, yet all sharing a common goal of accelerating the collective power of Kentucky’s post-secondary institutions.
Individuals at this job is responsible The IP Merchandising Director is responsible to develop, execute and oversee companies intellectual property strategies.', 900, 900, '801–1000', 'Version', '31 Mar 2022', '30 Mar 2027', 'Media & Entertainment Skill Council (MESC)', 'MESC – Media & Entertainment Skills Council', 'Digital Media', 'Level 7 (Vertical)
Entrepreneur', 'General Qualification', 'N.A.', '{"Theory":"330","Practical":"510","EmployabilitySkills":"60","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "78", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_21.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
