INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/ME/MESC/06030', 'Studio Manager', 'media-entertainment', 'Media & Entertainment', 5.0, 'Studio Manager in the Media & Entertainment Industry are able to work in multiple industries and settings such as music, graphic design or television studios. Studio managers are responsible for overseeing film projects, creating effective marketing campaigns, and reviewing daily resource and workload schedules.
Individuals in this job must be able to manage people and time. Studio Managers are well-organized multitaskers who have a habit of accomplishing all the responsibilities that face them. They are well-spoken, have excellent organizational and communication skills and able to motivate their team by showing good leadership.', 900, 900, '801–1000', 'Version', '30 Jun 2022', '29 Jun 2025', 'Media & Entertainment Skill Council (MESC)', 'MESC – Media & Entertainment Skills Council', 'Production', 'Not Applicable', 'General Qualification', 'N.A.', '{"Theory":"315","Practical":"525","EmployabilitySkills":"60","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "96", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_21.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/ME/MESC/06037', 'Video Blogger', 'media-entertainment', 'Media & Entertainment', 4.0, 'The video blogger documents occasions online through video. They may travels to location waits for suitable moment and takes videos and photographs. Attends State functions and parties and takes videos and photographs of important persons arousing special interest of news value for online publication.', 510, 510, '401–600', 'Version', '30 Jun 2022', '29 Jun 2025', 'Media & Entertainment Skill Council (MESC)', 'MESC – Media & Entertainment Skills Council', 'Social Media Manager', 'Social Media Manager', 'General Qualification', 'N.A.', '{"Theory":"180","Practical":"270","EmployabilitySkills":"00","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "97", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_21.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-ME-01255-2023-V1-NFDC', '3D Animator  (TV and Film Making)', 'media-entertainment', 'Media & Entertainment', 4.0, 'This course is a short term skill training program for freshers and amateurs so that they can learn the craft of 3D animation film making and earn a livelihood through employment or freelance assignments.
The objective of the program is to prepare individuals for a job of 3D Animation Designer where they create visual concepts, using computer software or by hand, to communicate ideas that inspire, inform, and captivate consumers and enable them to develop the overall process and production design for various applications such as Film , Game & advertisements, TV series with high visual impact.', 540, 540, '401–600', 'Version', '01 Nov 2023', '31 Oct 2026', 'National Film Development Corporation Ltd', 'National Film Development Corporation
 4th Floor, Soochana Bhawan, CGO Complex, Phase-I, New Delhi-110003', 'Animation', 'Vertical:  3D Designer', 'Multi-Skill Qualification', 'N.A.', '{"Theory":"150","Practical":"240","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "98", "qualification_type": "Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_21.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-ME-01256-2023-V1-NFDC', 'Visual Communication Artist (Static and Motion Graphics)', 'media-entertainment', 'Media & Entertainment', 4.0, 'This course is a short-term skill training program for freshers and amateurs so that they can learn the craft of Graphic Designing & Motion Graphic Design and earn a livelihood through employment or freelance assignments. The objective of the program is to prepare individuals for a job of Graphic Designer/Motion Graphic Artist where they create visual concepts, using computer software or by hand, to communicate ideas that inspire, inform, and captivate consumers and enable them to develop the overall layout and production design for various applications such as logo designs, branding & advertisements, UI/UX layouts, logo animation, explainer videos, channel packaging, etc. with high visual impact.', 480, 480, '401–600', 'Version', '01 Nov 2023', '31 Oct 2026', 'National Film Development Corporation Ltd', 'National Film Development Corporation
4th Floor, Soochana Bhawan, CGO Complex, Phase-I, New Delhi-110003', 'Animation', 'Vertical Progression:  Senior Graphic Designer', 'Multi-Skill Qualification', 'N.A.', '{"Theory":"120","Practical":"210","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "99", "qualification_type": "Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_21.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-4.5-ME-01841-2024-V1-MESC', 'Technical Artist – AR/VR', 'media-entertainment', 'Media & Entertainment', 4.5, 'The individual in this job will act as an architecture and overlays AR-VR solution to deliver experience of their project vision to prospective users for analysis, learning and game development purpose. It articulates 3D content products for Virtual & Augmented Reality application with smart technology driven system (hardware) which brings realistic views to users. The Technical Artist also acts as bridge between the artists and programmers, ensuring the art content and features are easily integrated into the environment.', 510, 510, '401–600', 'Version', '06 Feb 2024', '06 Feb 2026', 'Media & Entertainment Skill Council (MESC)', 'Media & Entertainment Skills Council 
522-524, DLF Tower-A, Jasola, New Delhi
110025', 'Game Development', 'AR-VR Developer, Entrepreneur', 'Future Skills Qualification,General Qualification', 'N.A.', '{"Theory":"150","Practical":"360","EmployabilitySkills":"00","OJT_Mandatory":"00"}', false, '{}'::text[], '{"source_row": "100", "qualification_type": "Future Skills Qualification,General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_21.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-4.5-ME-01800-2024-V1-MESC     V1.0', '3D Digital Game Art', 'media-entertainment', 'Media & Entertainment', 4.5, 'The 3D Digital Game Artist takes a designer’s brief and, through a combination of conceptualization, creativity, selectivity, technical, and specialist skills, completes the brief to the satisfaction of clients. The 3D Digital Game Artist receives, conceptualizes, and interprets design briefs on the basis of their market knowledge and skill sets, and the given scope and limits of the briefs. The skills required of the 3D Digital Game Artist can be broken down further into 2D concept art, texture painting, 3D modelling, rigging, and animating.', 510, 510, '401–600', 'Version', '06 Feb 2024', '06 Feb 2026', 'Media & Entertainment Skill Council (MESC)', 'Media & Entertainment Skills Council 
522-524, DLF Tower-A, Jasola, New Delhi
110025', 'N/A', 'N/A', 'General Qualification', 'N.A.', '{"Theory":"135","Practical":"375","EmployabilitySkills":"00","OJT_Mandatory":"00"}', false, '{}'::text[], '{"source_row": "101", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_21.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
