INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-ME-02419-2024-V1-MSME', 'VFX ASSOCIATE', 'media-entertainment', 'Media & Entertainment', 4.0, 'A VFX Associate course is designed to provide learners with a comprehensive understanding and practical skills in the field of computergenerated imagery (CGI) and visual effects.  This course combines artistic creativity with technical expertise to teach Learners: 
 
● How to create stunning and realistic 3D animations and visual effects for various mediums such as 
   films, television shows, video games, Virtual Reality (VR) and advertisements.
● Learners who attain this qualification can perform 3D animation, Character animation, Game 
   Creation, Visualization in VR, and Special Effects in Film, Tv Shows etc.
● Qualified learners are competent to get an employment in Media and Entertainment sector as per 
    the requirement of MSMEs.
● Qualified learners will become an entrepreneur.', 600, 600, '401–600', 'Version', '30 Apr 2024', '30 Apr 2027', 'MSME Technology Centre, Ministry of Micro Small And Medium Enterprises, New Delhi', 'MSME TECHNOLOGY CENTER', 'Animator', 'VFX Supervisor', 'Cross Sectoral Qualification,General Qualification,Multi-Skill Qualification', 'N.A.', '{"Theory":"120","Practical":"390","EmployabilitySkills":"30","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "110", "qualification_type": "Cross Sectoral Qualification,General Qualification,Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_21.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
