INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-MG-02174-2024-V1-SCMS', 'Rare Earths Extraction Plant Operator', 'mining', 'Mining', 4.0, 'A Rare Earths Extraction Plant Operator is responsible for conducting the extraction of rare earth using appropriate equipment and following the applicable processes including health and safety at the worksite.', 420, 420, '401–600', 'Version', '05 Mar 2024', '04 Mar 2027', 'Skill Council for Mining Sector (SCMS)', 'Skill Council for Mining Sector', 'Placer Mining', 'Vertical Progression -  Rare Earths Extraction Plant Supervisor– Level 4.5
Horizontal Progression - Dredge and Ore Processing Operator– Level 4.0', 'General Qualification', 'N.A.', '{"Theory":"120","Practical":"180","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "11", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-5.5-MG-02929-2024-V1-SCMS', 'Mine Foreman/Overman', 'mining', 'Mining', 5.5, 'The individual in this role is responsible for supervising and monitoring the various mine activities and ensures organizing and monitoring of work flow for various processes. The person is also responsible of managing team and ensure they are following all compliances and regulations as specified by organization.', 750, 930, '801–1000', 'Version', '27 Aug 2024', '26 Aug 2027', 'Skill Council for Mining Sector (SCMS)', 'Skill Council for Mining Sector', 'Drilling/Cutting', 'Manager (Mines) (to be developed) (Level-6.0)', 'General Qualification', 'N.A.', '{"Theory":"210","Practical":"210","EmployabilitySkills":"90","OJT_Mandatory":"240"}', false, '{}'::text[], '{"source_row": "12", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-MG-02928-2024-V1-SCMS', 'Drill Operator {Down-the-hole/Long Hole (DTH/LH)}', 'mining', 'Mining', 3.0, 'The DTH/LH (Down the Hole/Long Hole) Drill Operator is responsible for drilling long holes and down holes in the mines by operating DTH/LH drill rig. They also ensure that the safety systems are working correctly and performing essential maintenance on the DTH/LH drill rig available in underground mines.', 390, 450, '401–600', 'Version', '27 Aug 2024', '26 Aug 2027', 'Skill Council for Mining Sector (SCMS)', 'Skill Council for Mining Sector', 'Drilling/Cutting', 'NSQF Level 4.0 –  Drilling Foreman (to be developed)', 'General Qualification', 'N.A.', '{"Theory":"60","Practical":"150","EmployabilitySkills":"30","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "13", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-MG-02926-2024-V1-SCMS', 'Low Profile Dump Truck (LPDT) Operator', 'mining', 'Mining', 3.0, 'The individual in this role uses the Low Profile Dump Truck (LPDT) for transporting large volumes of loose material such as sand, gravel, crushed rock, coal, ore, etc. to designated place sites, dump yards,
washing/handling plants, etc. The operator is also responsible for discharging its load to the rear, bottom, or on one side efficiently. They also ensure that the safety systems are working correctly and performing
essential maintenance on the LPDT available in underground mines.', 390, 450, '401–600', 'Version', '27 Aug 2024', '26 Aug 2027', 'Skill Council for Mining Sector (SCMS)', 'Skill Council for Mining Sector', 'Loading and Hauling - Underground', 'NSQF Level 4 : Loader Operator-Underground', 'General Qualification', 'N.A.', '{"Theory":"60","Practical":"150","EmployabilitySkills":"30","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "14", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-MG-02927-2024-V1-SCMS', 'Slurry Pump Operator (Mines)', 'mining', 'Mining', 3.0, 'The individual in this role is responsible for transferring material or slurry from one place to another in the mines or from one location to another location for processing, by operating and maintaining the slurry pump unit.', 390, 570, '401–600', 'Version', '27 Aug 2024', '26 Aug 2027', 'Skill Council for Mining Sector (SCMS)', 'Skill Council for Mining Sector', 'Mechanical Services', 'NSQF Level 4.0: Pump Operator-Mining', 'General Qualification', 'N.A.', '{"Theory":"60","Practical":"150","EmployabilitySkills":"30","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "15", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-MG-04053-2025-V2-SCMS', 'Assistant-Mine Surveyor', 'mining', 'Mining', 4.0, 'An Assistant-Mine Surveyor assists in measuring and setting out dimensional control, setting out secondary dimensional work control, and handling resources to assist surveyor.', 480, 600, '401–600', 'Version', '06 May 2025', '06 May 2028', 'Skill Council for Mining Sector (SCMS)', 'Skill Council for Mining Sector', 'Mine Surveying', 'NSQF Level 5 – Mine Surveyor (to be developed)', 'General Qualification', 'N.A.', '{"Theory":"150","Practical":"300","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "16", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-MG-04054-2025-V2-SCMS', 'Bulldozer Operator', 'mining', 'Mining', 3.0, 'The bulldozer operator uses the bulldozer to scoop out soil, move rocks and ore to other site of the location and level the ground. They are also responsible for confirming that the safety systems are working correctly and performing essential maintenance on the bulldozer.', 390, 390, '201–400', 'Version', '06 May 2025', '06 May 2028', 'Skill Council for Mining Sector (SCMS)', 'Skill Council for Mining Sector', 'Loading and Hauling - Opencast', 'Vertical Progression: 
NSQF Level 4.0-Shovel Operator (to be developed)', 'General Qualification', 'N.A.', '{"Theory":"100","Practical":"260","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "17", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-MG-04055-2025-V2-SCMS', 'Dumper/ Tipper Operator', 'mining', 'Mining', 3.0, 'The Dumper/Tipper operator uses the Dumper/Tipper (a heavy specialized truck) for transporting large
volume of loose material such as sand, gravel, crushed rock, coal, over burden, ore etc. to designated
place such as crusher hopper, site, dump yard, washing/handling plant etc. The operator is also responsible for discharging its load to rear, bottom or on one side efficiently. They also ensure that the
safety systems are working correctly and performing essential maintenance on the Dumper/Tipper.', 390, 390, '201–400', 'Version', '06 May 2025', '06 May 2028', 'Skill Council for Mining Sector (SCMS)', 'Skill Council for Mining Sector', 'Loading and Hauling - Opencast', 'NSQF Level 4.0 (Vertical Progression)-Shovel Operator (to be developed)', 'General Qualification', 'N.A.', '{"Theory":"100","Practical":"260","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "18", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-MG-04057-2025-V2-SCMS', 'Jack Hammer Operator', 'mining', 'Mining', 3.0, 'The Jack Hammer Operator drives and controls a Jack Hammer machine in mines (both opencast and
underground) or construction site to drilling a hole in the rock and break up rocks, concretes or mines
surfaces. Directs and facilities scaling of loose rocks and mucking of broken ore or waste rock from the
worksite. Operators are also responsible to ensure all safety systems are in place and performing basic
maintenance on the Jack Hammer.', 390, 510, '401–600', 'Version', '06 May 2025', '06 May 2028', 'Skill Council for Mining Sector (SCMS)', 'Skill Council for Mining Sector', 'Drilling/Cutting', 'NSQF Level 4.0 (Vertical) – Jumbo Drill Operator', 'General Qualification', 'N.A.', '{"Theory":"100","Practical":"260","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "19", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-MG-04059-2025-V2-SCMS', 'Loader Operator (Mining)', 'mining', 'Mining', 3.0, 'The Loader operator uses the Loader - O/C (Opencast mines) for moving aside or loading ROM (Run-OfMine), product etc, into or onto different types of machinery (such as dumper/tipper, conveyor belt, feedhopper etc,).They also ensure that the safety systems are working correctly and perform essential maintenance on the Loader.', 390, 390, '201–400', 'Version', '06 May 2025', '06 May 2028', 'Skill Council for Mining Sector (SCMS)', 'Skill Council for Mining Sector', 'Loading and Hauling-Opencast', 'NSQF Level 4.0 (Vertical)-Shovel Operator (to be developed)', 'General Qualification', 'N.A.', '{"Theory":"100","Practical":"260","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "20", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-MG-04061-2025-V2-SCMS', 'Mine Mechanic/Fitter', 'mining', 'Mining', 3.0, 'A Mine Mechanic or Fitter in a mine is responsible for repair and maintenance of plant and machinery,
medium / light vehicles, drilling machines, pumps, compressors, pneumatic machines, overhaul of crushers and other mechanical equipment and assemblies. A mechanic/fitter most often works with / assists senior technicians.', 390, 630, '601–800', 'Version', '06 May 2025', '06 May 2028', 'Skill Council for Mining Sector (SCMS)', 'Skill Council for Mining Sector', 'Mechanical Services', 'NSQF Level 4.0 (Vertical)-Heavy Earth Moving Machinery (HEMM) Mechanic', 'General Qualification', 'N.A.', '{"Theory":"80","Practical":"280","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "21", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-MG-04065-2025-V2-SCMS', 'Wire Saw Operator', 'mining', 'Mining', 3.0, 'Wire Saw operator drives and operates a Wire Saw machine to cut large dimension stone blocks of granite, marble, limestone, slate, sandstone etc. into smaller blocks. They also ensure that the safety systems are working correctly and perform essential maintenance on the Wire Saw.', 390, 390, '201–400', 'Version', '06 May 2025', '06 Nov 2025', 'Skill Council for Mining Sector (SCMS)', 'Skill Council for Mining Sector', 'Drilling/Cutting', 'NSQF Level 4.0 (Vertical) - Shovel Operator (to be developed)', 'General Qualification', 'N.A.', '{"Theory":"100","Practical":"260","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "22", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-02-MG-04066-2025-V2-SCMS', 'Helper-Opencast Mines', 'mining', 'Mining', 2.0, 'The Helper in an Open Cast Mine assists the Operator/ Fitter/ Technician in handling material, pre-operational checks, servicing Heavy Earth Moving Machinery (HEMM), shifting and operation of open cast machines, and installation and maintenance of electrical systems and equipment.', 240, 330, '201–400', 'Version', '06 May 2025', '06 May 2028', 'Skill Council for Mining Sector (SCMS)', 'Skill Council for Mining Sector', 'Mine Surveying, Drilling/Cutting, Shot firing/Blasting, Loading and Hauling - Opencast, Specialized Operations, HSE Functions, Geological Mapping, Exploration, Mineral Estimation, Planning, Placer Mining, Mechanical Services, Instrumentation and Control Systems, Electrical Services', 'NSQF Level 3.0 (Vertical)-Bulldozer Operator, Dumper/Tipper Operator, Jack Hammer Operator, Loader Operator-Mining, Mine Mechanic/Fitter, Wire Saw Operator, Mechanic-Belt-Conveyor, Grader Operator,  Coal Bed Methane (CBM) Extraction Operator, Slurry Pump Operator (Mines), Mechanic-Fitter (Mineral Sands)', 'General Qualification', 'N.A.', '{"Theory":"60","Practical":"150","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "23", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-02-MG-04067-2025-V2-SCMS', 'Helper-Underground Mines', 'mining', 'Mining', 2.0, 'The Helper in an Underground Mine assists the Operator/ Fitter/ Technician in handling material, pre- operational checks, servicing Heavy Earth Moving Machinery (HEMM), shifting and operation of underground machines, and installation and maintenance of electrical systems and equipment.', 240, 390, '201–400', 'Version', '06 May 2025', '06 May 2028', 'Skill Council for Mining Sector (SCMS)', 'Skill Council for Mining Sector', 'Mine Surveying, Drilling/Cutting, Shot firing/Blasting, Loading and Hauling - Underground, Specialized
Operations, HSE Functions, Electrical Services, Geological Mapping, Exploration, Mineral Estimation,
Planning, Placer Mining, Mechanical Services, Instrumentation and Control Systems', 'NSQF Level 3.0 (Vertical)-Jack Hammer Operator, Mine Mechanic/Fitter, Mechanic-Belt-Conveyor, Grader Operator,  Slurry Pump Operator (Mines), Mechanic-Fitter (Mineral Sands), Drill Operator {Down-the-hole/Long Hole (DTH/LH)}', 'General Qualification', 'N.A.', '{"Theory":"60","Practical":"150","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "24", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-MG-04056-2025-V2-SCMS', 'Heavy Earth Moving Machinery (HEMM) Mechanic', 'mining', 'Mining', 4.0, 'The HEMM Mechanic is responsible for diagnoses, repairs, overhauls and services of Heavy Earth Moving Machinery (HEMM) to keep them in good running order. Also carries out repairs and maintenance of internal combustion engines and the various components of a Heavy Earth Moving Machine like transmission, torque converter, power train, final drive, compressor, hydraulic systems and operational control systems etc. also maintains all the relevant records, draws requirements of consumables and spare parts.', 420, 540, '401–600', 'Version', '06 May 2025', '06 May 2028', 'Skill Council for Mining Sector (SCMS)', 'Skill Council for Mining Sector', 'Mechanical Services', 'NSQF Level 5.0 (Vertical) - Mechanical Supervisor -Workshop (to be developed)', 'General Qualification', 'N.A.', '{"Theory":"80","Practical":"310","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "25", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-MG-04058-2025-V2-SCMS', 'Jumbo Drill Operator', 'mining', 'Mining', 4.0, 'A Jumbo Drill operator is responsible for the operation of a single/double/multi-boom jumbo drilling rig for underground mine development and installation of roof and side support. Jumbo drill operator requires the knowledge of layout of mine workings, cross-sectional dimensions of working face, drilling and blasting pattern and design, roof and side support plan as per approved SSR (Systematic Support Rule), operation and maintenance module of the jumbo drill machine. The individual will be a major contributor in increasing and enhancing the productivity of machine and manpower safety at the workplace.', 480, 540, '401–600', 'Version', '06 May 2025', '06 Nov 2025', 'Skill Council for Mining Sector (SCMS)', 'Skill Council for Mining Sector', 'Drilling/Cutting', 'NSQF Level 5 - Mining Mate/Sirdar', 'General Qualification', 'N.A.', '{"Theory":"120","Practical":"330","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "26", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-MG-04060-2025-V2-SCMS', 'Mine Electrician', 'mining', 'Mining', 4.0, 'Mine Electrician ensures installation, operation and maintenance (O&M) of the electrical substations, equipment and electrical supply system. The role holder also ensures that all the electrical systems and machinery work is in accordance with relevant specifications for opencast and underground mines (including gassy mines).', 420, 600, '401–600', 'Version', '06 May 2025', '06 May 2028', 'Skill Council for Mining Sector (SCMS)', 'Skill Council for Mining Sector', 'Electrical Services', 'NSQF Level 5 (Vertical)- Electrical Supervisor (to be developed)', 'General Qualification', 'N.A.', '{"Theory":"90","Practical":"300","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "27", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-MG-04062-2025-V2-SCMS', 'Mine Welder', 'mining', 'Mining', 4.0, 'A mine welder is responsible for joining various types of metallic frames, structures, jigs, plates, sheets etc. using heating and melting process created through electrical power and gaseous discharge, maintaining process parameters, conducting quality checks on output product and maintaining a safe and healthy working environment.', 480, 630, '601–800', 'Version', '06 May 2025', '06 May 2028', 'Skill Council for Mining Sector (SCMS)', 'Skill Council for Mining Sector', 'Mechanical Services', 'NSQF Level 5 (Vertical) : Mechanical Supervisor – Workshop (to be developed)', 'General Qualification', 'N.A.', '{"Theory":"100","Practical":"350","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "28", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-MG-04063-2025-V2-SCMS', 'Mineral Processing Operator', 'mining', 'Mining', 4.0, 'Mineral Processing Operator is engaged in mineral beneficiation in setting up crushing, screening, straining, washing, precipitating and other processes like leaching, floating and tailing management according to section in which posted and duties assigned and ensure proper working condition.', 420, 600, '401–600', 'Version', '06 May 2025', '06 May 2028', 'Skill Council for Mining Sector (SCMS)', 'Skill Council for Mining Sector', 'Ore Processing', 'NSQF Level 5 - Supervisor - Plant Operations (to be developed)', 'General Qualification', 'N.A.', '{"Theory":"100","Practical":"290","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "29", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-MG-04064-2025-V2-SCMS', 'Mining Mate/Sirdar', 'mining', 'Mining', 5.0, 'The Mining Mate/Sirdar supervises mineral production, oversee the safety of mining operations and
supervises blasting operations in metal/coal mines.', 600, 720, '601–800', 'Version', '06 May 2025', '06 May 2028', 'Skill Council for Mining Sector (SCMS)', 'Skill Council for Mining Sector', 'Drilling/Cutting, Shot firing/Blasting, Loading and Hauling - Opencast, Loading and Hauling - Underground, Specialized Operations', 'NSQF Level 5.5 (Vertical)- Mine Foreman/ Overman', 'General Qualification', 'N.A.', '{"Theory":"190","Practical":"350","EmployabilitySkills":"60","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "30", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_28.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2020/OAFM/MEPSC/03792', 'Hindi Typist', 'office-administration-facility-management', 'Office Administration & Facility Management', 4.0, 'The Hindi Typist, is responsible for formatting and typing various types of documents in Hindi with speed and accuracy. The individual types letters, reports, forms, correspondence, policies, tabular statements, or other documents from rough drafts, handwritten copies, dictated notes, or voice recordings using word processing software or typewriter. The individual also checks documents for errors in spelling, grammar, punctuation and format, and corrects identified errors. The main purpose of the qualification and the target learners is to get unemployed people into work and to upgrade the skills of people already in work.', 390, 450, '401–600', 'Version', '17 Nov 2022', '17 Nov 2025', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Management Entrepreneurship and Professional Skills Council (MEPSC)', 'Office Support', 'Multi-functional Office Executive', 'General Qualification', 'N.A.', '{"Theory":"150","Practical":"180","EmployabilitySkills":"60","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "1", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_55.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/OAFM/MEPSC/06025', 'Assessor (VET and Skills)', 'office-administration-facility-management', 'Office Administration & Facility Management', 5.0, 'The assessor assesses candidates in an area of subject matter expertise in a range of contexts on occupational standards. They co-ordinate with the assessing body, training provider or client organisation to ensure smooth and timely completion of work.', 480, 480, '401–600', 'Version', '30 Jun 2022', '30 Jun 2025', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Management &Entrepreneurship and Professional Skills Council (MEPSC)', 'Assessment', 'Proctor (VET and Skills) (level 5.5), Lead Assessor (VET and Skills) (level 6)', 'Cross Sectoral Qualification', 'N.A.', '{"Theory":"120","Practical":"300","EmployabilitySkills":"60","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "2", "qualification_type": "Cross Sectoral Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_55.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/OAFM/MEPSC/06026', 'Lead Assessor (VET and Skills)', 'office-administration-facility-management', 'Office Administration & Facility Management', 6.0, 'Lead Assessor (VET and Skills) is responsible for Assessor development and undertaking assessment training sessions. The Lead Assessor has a key role in assuring the quality of the assessment tools and methodologies. The Lead Assessor (VET and Skills) should also be able to provide recommendations for continuous improvement in effectiveness of the assessment process', 630, 630, '601–800', 'Version', '30 Jun 2022', '30 Jun 2025', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Assessment', 'Head – Assessment Services', 'Cross Sectoral Qualification', 'N.A.', '{"Theory":"180","Practical":"360","EmployabilitySkills":"90","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "3", "qualification_type": "Cross Sectoral Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_55.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/OAFM/MEPSC/06028', 'Master Trainer (VET and Skills)', 'office-administration-facility-management', 'Office Administration & Facility Management', 6.0, 'The master trainer (VET and Skills)conducts trainer development as well as sessions that require advanced facilitation skills. They have a key role in assuring the quality of end to end training services and providing recommendations for continuous improvement of training effectiveness. They customize training programs as per the specific needs of the target audience to enhance effectiveness', 660, 660, '601–800', 'Version', '30 Jun 2022', '30 Jun 2026', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Management &Entrepreneurship and Professional Skills Council (MEPSC)', 'Training Delivery', 'Head of Training/ Skill Development Coach', 'General Qualification', 'N.A.', '{"Theory":"210","Practical":"360","EmployabilitySkills":"90","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "4", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_55.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/OAFM/MEPSC/06023', 'Instructional Designer (VET and Skills)', 'office-administration-facility-management', 'Office Administration & Facility Management', 6.0, 'An Instructional Designer (VET and Skills) designs training interventions for the transfer of learning as per the identified needs of learners. The person also conducts diagnostic assessments to identify individual training needs and develops training materials to assist trainers and learners. The individual also trains the instructors in using the learning interventions.', 630, 630, '601–800', 'Version', '30 Jun 2022', '30 Jun 2025', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Instructional Designing', 'Head- Research & Development- Assessment Design', 'Cross Sectoral Qualification', 'N.A.', '{"Theory":"210","Practical":"330","EmployabilitySkills":"90","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "5", "qualification_type": "Cross Sectoral Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_55.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/OAFM/MEPSC/06024', 'Trainer (VET and Skills)', 'office-administration-facility-management', 'Office Administration & Facility Management', 5.0, 'The Trainer trains the learners on the occupational standards, using pre-set lesson plans and training materials. They plan for and conduct sessions to impart competency-based skills and knowledge.', 510, 510, '401–600', 'Version', '30 Jun 2022', '30 Jun 2025', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Management &Entrepreneurship and Professional Skills Council (MEPSC)', 'Training Delivery', 'Vertical - Training Consultant/ Master Trainer (VET and Skills),
Horizontal - Assessor (VET and Skills)', 'Cross Sectoral Qualification', 'N.A.', '{"Theory":"150","Practical":"300","EmployabilitySkills":"60","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "6", "qualification_type": "Cross Sectoral Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_55.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/OAFM/MEPSC/06027', 'Training Centre Manager', 'office-administration-facility-management', 'Office Administration & Facility Management', 5.0, 'A Training Centre Manager manages overall centre operations including mobilization, training quality, assessment, placement, documentation, reporting and smooth operations of a training centre. The individual is responsible for implementation of various training programs at the centre.', 570, 570, '401–600', 'Version', '30 Jun 2022', '30 Jun 2025', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Management &Entrepreneurship and Professional Skills Council (MEPSC)', 'Training Delivery', 'Training Consultant', 'Cross Sectoral Qualification', 'N.A.', '{"Theory":"180","Practical":"330","EmployabilitySkills":"60","OJT_Mandatory":"00"}', false, '{}'::text[], '{"source_row": "7", "qualification_type": "Cross Sectoral Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_55.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/OAFM/MEPSC/06151', 'CSR and Sustainability Head', 'office-administration-facility-management', 'Office Administration & Facility Management', 6.0, 'A CSR and SustainabilityHead performs developmental activities aimed at increasing diversity and inclusivity. The work involves developing CSR and Sustainability programs for the company, increasing internal engagement and ensuring a positive impact on all stakeholders.', 630, 630, '601–800', 'Version', '28 Jul 2022', '28 Jul 2025', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Management &Entrepreneurship and Professional Skills Council (MEPSC)', 'Social Welfare', 'Head - Social Welfare and Environment Sustainability (level 6.5)', 'Cross Sectoral Qualification', 'N.A.', '{"Theory":"150","Practical":"420","EmployabilitySkills":"60","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "8", "qualification_type": "Cross Sectoral Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_55.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/OAFM/MEPSC/06150', 'CSR and Sustainability Manager', 'office-administration-facility-management', 'Office Administration & Facility Management', 5.0, 'A CSR and Sustainability Manager performs developmental activities aimed at increasing diversity and inclusivity. The work involves developing CSR and Sustainability programs for the company, increasing internal engagement and ensuring a positive impact on all stakeholders.', 600, 600, '401–600', 'Version', '28 Jul 2022', '28 Jul 2025', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Management &Entrepreneurship and Professional Skills Council (MEPSC)', 'Social Welfare', 'Expert – CSR and Sustainability Projects (Level 5.5) OR CSR and Sustainability Head (Level 6)', 'Cross Sectoral Qualification', 'N.A.', '{"Theory":"270","Practical":"270","EmployabilitySkills":"60","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "9", "qualification_type": "Cross Sectoral Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_55.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/OAFM/MEPSC/06409', 'Office Operations Executive', 'office-administration-facility-management', 'Office Administration & Facility Management', 4.0, 'The Office Operations Executive is a generalist who checks and prepares documents and simple correspondence; records work related information and data; maintains filing; handles general inquiries from visitors and clients; receives phone calls and forwards to respective departments after enquiring from the caller; makes calls as per requirements of the work; adheres to workplace health and safety guidelines and works effectively in co-ordination with team in line with professional practices of the workplace.', 390, 390, '201–400', 'Version', '29 Sep 2022', '29 Sep 2025', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Office Support', 'Multifunctional Office Executive', 'General Qualification', 'N.A.', '{"Theory":"150","Practical":"180","EmployabilitySkills":"60","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "10", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_55.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/ETR/MEPSC/06473', 'Pre-School and Day Care Facilitator', 'office-administration-facility-management', 'Office Administration & Facility Management', 4.0, 'Pre School and Day Care Facilitator is responsible for the education care and holistic development of children 3-6 years old. This is done in a variety of settings, including pre-schools and day care institutions. They use various early childcare and education methodologies and techniques for this purpose. This person should also maintain necessary records and registers.', 420, 420, '401–600', 'Version', '17 Nov 2022', '17 Nov 2025', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Education', 'Special Educator/ Facilitator', 'General Qualification', 'N.A.', '{"Theory":"150","Practical":"210","EmployabilitySkills":"60","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "11", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_55.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/US/MEPSC/06471', 'Nano Entrepreneur (Street Vendor)', 'office-administration-facility-management', 'Office Administration & Facility Management', 3.0, 'A Nano Entrepreneur (Street Vendor) is a person who offers goods for sale to the public without having a permanent built up structure but with a temporary static structure or mobile stall, headload etc. Street vendors may be stationary by occupying space on the pavements or other public/private areas, or may be mobile in the sense that they move from place to place carrying their wares on push carts or in cycles or baskets on their heads, or may sell their wares in moving trains, bus etc.', 300, 300, '201–400', 'Version', '17 Nov 2022', '17 Nov 2025', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Entrepreneurial Skills', 'Franchisee Entrepreneur', 'General Qualification', 'N.A.', '{"Theory":"90","Practical":"180","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "12", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_55.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/BFSI/MEPSC/06472', 'Consultant (Chartered Tax Practitioner)', 'office-administration-facility-management', 'Office Administration & Facility Management', 5.0, 'A Consultant - Chartered Tax Practitioner is the person who prepares clients tax returns in accordance direct & indirect tax regulations for the time being. The3 consultant also helps in tax planning, fulfills other legal compliances of MSMEs and assists in maintaining books of accounts and records and documents.', 510, 570, '401–600', 'Version', '17 Nov 2022', '17 Nov 2025', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Management &Entrepreneurship and Professional Skills Council (MEPSC)', 'Tax Accountant, Other Legal Professionals, Associate Accountants', 'Lead Practitioner - Taxation, Accounts and Finance (Level 5.5); OR Public Accountant (MEP/Q5104) (Level 6)', 'General Qualification', 'N.A.', '{"Theory":"150","Practical":"270","EmployabilitySkills":"90","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "13", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_55.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-4.5-OA-00108-2023-V1-MEPSC', 'Start Up Support Executive', 'office-administration-facility-management', 'Office Administration & Facility Management', 4.5, 'Start-up Support Executive are those professionals who are readily deployable in the supporting services. The Individual play an important role in providing information and assistance to company and partnership queries. The job role offers assistance to registration of company and partnership registration.', 450, 450, '401–600', 'Version', '05 Jan 2023', '05 Jan 2026', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Management &Entrepreneurship and Professional Skills Council (MEPSC)', 'Legal and Compliance', 'Business Support Practitioner', 'General Qualification', 'N.A.', '{"Theory":"120","Practical":"270","EmployabilitySkills":"60","OJT_Mandatory":"00"}', false, '{}'::text[], '{"source_row": "14", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_55.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-OA-00109-2023-V1-MEPSC', 'Sole proprietorship Associate', 'office-administration-facility-management', 'Office Administration & Facility Management', 4.0, 'Sole proprietorship Associate are those professionals who are readily deployable in the consulting services. The Individual play an important role in providing information and assistance to those single individuals who wish to start their own entities. The individual provides services for Registration of PAN, TAN, DSC and GSTIN.', 420, 420, '401–600', 'Version', '05 Jan 2023', '05 Jan 2026', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Management &Entrepreneurship and Professional Skills Council (MEPSC)', 'Legal and Compliance', 'Start-up Support Executive', 'General Qualification', 'N.A.', '{"Theory":"150","Practical":"210","EmployabilitySkills":"60","OJT_Mandatory":"00"}', false, '{}'::text[], '{"source_row": "15", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_55.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-OA-00110-2023-V1-MEPSC', 'Office Executive', 'office-administration-facility-management', 'Office Administration & Facility Management', 4.0, 'The office executive is a generalist who checks and prepares documents, writes simple correspondence, maintains records as well as co-ordinates with various internal and external agencies and follows up for work completion in line with professional practices of the workplace', 390, 390, '201–400', 'Version', '05 Jan 2023', '05 Jan 2026', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Office support', 'Multifunctional Administrative Executive', 'General Qualification', 'N.A.', '{"Theory":"150","Practical":"180","EmployabilitySkills":"60","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "16", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_55.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-ET-00242-2023-V1-MEPSC', 'Training Coordinator (VET & Skills)', 'office-administration-facility-management', 'Office Administration & Facility Management', 4.0, 'The Training Coordinator provides support to the trainers, learners and stakeholders so that the training and other related activities occur smoothly and as per established policy and plans. They are responsible for communications delivery, maintaining training facilities, maintaining of records and coordinating with various service providers like, catering, logistics, housekeeping, electricians, etc.', 420, 420, '401–600', 'Version', '28 Feb 2023', '27 Feb 2026', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Management &Entrepreneurship and Professional Skills Council (MEPSC)', 'Training Support', 'Placement Executive', 'Cross Sectoral Qualification', 'N.A.', '{"Theory":"150","Practical":"210","EmployabilitySkills":"60","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "17", "qualification_type": "Cross Sectoral Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_55.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-5.5-OA-00241-2023-V1-MEPSC', 'Multifunctional Office Executive', 'office-administration-facility-management', 'Office Administration & Facility Management', 5.5, 'A Multifunctional Office Executive performs administrative and office support activities. It involves the upkeep and maintenance of office premises, purchases and vendor management for office supplies, stationery and upkeep, ensuring the comfort of staff and visitors by receiving and forwarding calls, coordination of incoming and outgoing mail and organizing meetings and making travel arrangements for staff.', 570, 570, '401–600', 'Version', '28 Feb 2023', '28 Feb 2026', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Management &Entrepreneurship and Professional Skills Council (MEPSC)', 'Office Support', 'Level 5 - Vendor Management Executive/ Travel Desk Incharge - Domestic and International/
Supervisor - Record keeping and Documentation/ Personal Assistant', 'General Qualification', 'N.A.', '{"Theory":"240","Practical":"240","EmployabilitySkills":"90","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "18", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_55.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-4.5-OA-00243-2023-V1-MEPSC', 'HR Executive- Payroll and Employee Data Management', 'office-administration-facility-management', 'Office Administration & Facility Management', 4.5, 'The HR Executive – Payroll and Employee Data Management maintains employee data for the Human Resource (HR) department and compiles all necessary payroll data, enters it into the organisation’s data system, calculates each employee’s respective pay, computing statutory and tax related entitlements and deductions and co-ordinates with the accounts department for disbursements and fund transfers.', 480, 480, '401–600', 'Version', '28 Feb 2023', '28 Feb 2026', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Management &Entrepreneurship and Professional Skills Council (MEPSC)', 'Human Resource Management', 'Compensation and Benefits Analyst', 'General Qualification', 'N.A.', '{"Theory":"150","Practical":"270","EmployabilitySkills":"60","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "19", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_55.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-4.5-OA-00244-2023-V1-MEPSC', 'Recruitment Executive', 'office-administration-facility-management', 'Office Administration & Facility Management', 4.5, 'The Recruitment Executive is responsible for sourcing, screening and connecting suitable candidates to employers and vice versa.  Upon sourcing a potential match, the executive is also responsible for coordinating and processing applications as per needs of the employer organizations and subsequent coordination between the two parties.', 480, 480, '401–600', 'Version', '28 Feb 2023', '28 Feb 2026', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Human Resource Management', 'Multi-Functional HR executive, Job Analyst / Occupational Analyst', 'General Qualification', 'N.A.', '{"Theory":"150","Practical":"270","EmployabilitySkills":"60","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "20", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_55.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-OA-00245-2023-V1-MEPSC', 'Project Management Associate', 'office-administration-facility-management', 'Office Administration & Facility Management', 4.0, 'The Project Management Associate will assist the project manager in project activities such as planning, leading the team members and implementing the best practices of project management.', 450, 450, '401–600', 'Version', '28 Feb 2023', '28 Feb 2026', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Office Management', 'Assistant Project Manager (Level 4.5), Project Manager  (Level 5)', 'General Qualification', 'N.A.', '{"Theory":"180","Practical":"210","EmployabilitySkills":"60","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "21", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_55.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-06-OA-00546-2023-V1-MEPSC', 'Public Accountant', 'office-administration-facility-management', 'Office Administration & Facility Management', 6.0, 'A Public Accountant is the person who effectively manages financial accounting and reporting, auditing, legal compliance, taxation, finance, and strategic management related functions of the entity and helps management in decision making and financial planning. This qualification leads to the professional membership of The Institute of Certified Public Accountants', 660, 660, '601–800', 'Version', '28 Feb 2023', '28 Feb 2026', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Entrepreneurial Skills', 'Internal Auditor', 'General Qualification', 'N.A.', '{"Theory":"360","Practical":"210","EmployabilitySkills":"90","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "22", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_55.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-OA00374-2023-V1-MEPSC', 'Business Support Practitioner', 'office-administration-facility-management', 'Office Administration & Facility Management', 5.0, 'Business Support Practitioners are professionals entitled to provide tax planning, management, statutory filing and financial services. Providing financial services and filing of statutory compliances fall under some of the major responsibilities of a Business Support Practitioner.', 660, 870, '801–1000', 'Version', '03 May 2023', '02 May 2026', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Legal and Compliance', 'Lead Practitioner-Business Support', 'General Qualification', 'N.A.', '{"Theory":"270","Practical":"300","EmployabilitySkills":"90","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "23", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_55.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-02-PS-00995-2023-V1-MEPSC', 'General Duty Guard cum Watchman', 'office-administration-facility-management', 'Office Administration & Facility Management', 2.0, 'General Duty Guard cum Watchman is entry level staff for assets, which have limited/ no threat. This person should be able to maintain a high degree of alertness and vigilance and report any untoward incident/ observation/ emergency to his/ her superior/ owner. In some cases, he/ she should also be able to intervene/ prevent an untoward incident/ emergency.', 210, 210, '201–400', 'Version', '29 Sep 2023', '29 Sep 2026', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)
20th Floor, Amba Deep, 14, KG Marg, New Delhi – 110 001, India', 'Private Security', 'Security Guard (MEP/Q7101)', 'General Qualification', 'N.A.', '{"Theory":"40","Practical":"80","EmployabilitySkills":"30","OJT_Mandatory":"60","OJT_Recommended":""}', false, '{}'::text[], '{"source_row": "24", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_55.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-05-PS-01053-2023-V1-MEPSC, Version 1', 'Licensee – Security Services', 'office-administration-facility-management', 'Office Administration & Facility Management', 5.0, 'To establish and manage a commercial security agency for provision of various corporate and industrial security services to the various clients in the market.', 30, 30, '1–200', 'Version', '29 Sep 2023', '29 Sep 2026', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Private Security', 'N/A', 'Micro Credentials', 'N.A.', '{"Theory":"30","Practical":"00","EmployabilitySkills":"00","OJT_Mandatory":"00","OJT_Recommended":""}', false, '{}'::text[], '{"source_row": "25", "qualification_type": "Micro Credentials", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_55.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-2.5-PS-00996-2023-V1-MEPSC', 'Guard – Cash Logistics', 'office-administration-facility-management', 'Office Administration & Facility Management', 2.5, 'Guard - Cash Logistics/ Cash Transportation Guard is required to identify the threats and risks on the given routes. The person handles cash in transit; protects and manages the operation of the Cash Vans, as part of the Security Services in terms of the Cash in Transit. Guard - Cash Logistics also should have knowledge of the road.', 240, 240, '201–400', 'Version', '29 Sep 2023', '28 Sep 2026', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)
20th Floor, Amba Deep, 14, KG Marg, New Delhi – 110 001, India', 'Private Security', 'Security Supervisor (MEP/Q7201)', 'General Qualification', 'N.A.', '{"Theory":"45","Practical":"75","EmployabilitySkills":"30","OJT_Mandatory":"90","OJT_Recommended":""}', false, '{}'::text[], '{"source_row": "26", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_55.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2020/OAFM/MEPSC/3609', 'Field Survey Enumerator', 'office-administration-facility-management', 'Office Administration & Facility Management', 4.0, 'The field survey enumerator, collects or verifies data or documents from the respondents such as households / enterprises / establishments. This individual is responsible for conducting the socio-economic surveys with the help of hand-held devices / laptops and blueprint consisting of survey concepts, definitions, procedures, instructions etc. as per guidelines received from multiple clients.  They work on a regular, contractual or commission basis. This is a Qualification Pack (QP) containing National Occupational Standards for the job role – “Field Survey Enumerator”. The main purpose of the qualification and the target learners is to get unemployed people into work and to upgrade the skills of people already in work.', 390, 390, '201–400', 'Version', '17 Nov 2022', '17 Nov 2025', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Management & Entrepreneurship and Professional Skills Council', 'Office Support', 'Survey Supervisor', 'General Qualification', 'N.A.', '{"Theory":"150","Practical":"180","EmployabilitySkills":"60","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "27", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_55.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-ET-02715-2024-V1-MEPSC', 'Entrepreneur (Electives: Women Entrepreneurship / Gender Sensitivity)', 'office-administration-facility-management', 'Office Administration & Facility Management', 5.0, 'An Entrepreneur starts and manages businesses with the purpose of making financial gains by providing products or services to customers. The individual is responsible for securing funds and appropriate authorizations or licenses for starting the business. The person hires and manages personnel and manages various aspects of the business, such as supply, marketing, sales, risks, compliance with regulations, business expansion, etc.', 480, 570, '401–600', 'Version', '29 Sep 2022', '29 Sep 2025', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Management and Entrepreneurship & Professional Skills Council (MEPSC)', 'Entrepreneurial Skills', 'Incubate Entrepreneur', 'Cross Sectoral Qualification', 'N.A.', '{"Theory":"120","Practical":"270","EmployabilitySkills":"90","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "28", "qualification_type": "Cross Sectoral Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_55.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-OA-02520-2024-V1-MEPSC', 'Office Assistant', 'office-administration-facility-management', 'Office Administration & Facility Management', 3.0, 'The Office Assistant, equipped with AI-enhanced productivity tools, assists colleagues with clerical and administrative tasks, optimizing workflows and enhancing office efficiency.', 330, 330, '201–400', 'Version', '30 Apr 2024', '30 Apr 2027', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Office Support', 'Secretary/ Office Executive', 'General Qualification', 'N.A.', '{"Theory":"120","Practical":"150","EmployabilitySkills":"60","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "29", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_55.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-OA-02521-2024-V1-MEPSC', 'Executive - Secretarial Services', 'office-administration-facility-management', 'Office Administration & Facility Management', 4.0, 'The Executive – Secretarial Services serves as a pivotal support to managers and company directors,
employing advanced AI technologies to efficiently manage clerical and administrative duties. Proficient in dictation and transcription, they leverage AI tools to streamline workflows, prioritize tasks effectively, and foster seamless communication within the office. Tasked with handling records, letters, and routine tasks, they play a vital role in ensuring organizational efficiency and productivity.', 420, 420, '401–600', 'Version', '30 Apr 2024', '30 Apr 2027', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Office Support', 'Personal Assistant', 'General Qualification', 'N.A.', '{"Theory":"120","Practical":"240","EmployabilitySkills":"60","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "30", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_55.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-ET-03013-2024-V1-MEPSC', 'Udyami Mitra', 'office-administration-facility-management', 'Office Administration & Facility Management', 3.0, 'Udyami Mita is a community-based mentor who will assist women to become entrepreneurs through
conducting entrepreneurship awareness programs, and entrepreneurship development programs and
individually assisting women with information and links to resources to start and run an enterprise.', 240, 240, '201–400', 'Version', '27 Sep 2024', '27 Sep 2027', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Entrepreneurial Skills', 'Entrepreneur', 'General Qualification', 'N.A.', '{"Theory":"70","Practical":"140","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "31", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_55.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-02-ET-03011-2024-V1-MEPSC', 'Basic of Leadership Development', 'office-administration-facility-management', 'Office Administration & Facility Management', 2.0, 'Imparts skills and competencies required to develop leadership qualities of beneficiaries from marginalized sectors.', 60, 60, '1–200', 'Version', '27 Sep 2024', '27 Sep 2027', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Management & Entrepreneurship and Professional Skills Council', 'Entrepreneurial Skills', 'Not applicable', 'Cross Sectoral Qualification', 'N.A.', '{"Theory":"32","Practical":"28","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "32", "qualification_type": "Cross Sectoral Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_55.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-2.5-ET-03012-2024-V1-MEPSC', 'Entrepreneurial Skills for Women', 'office-administration-facility-management', 'Office Administration & Facility Management', 2.5, 'Provides a comprehensive framework for individuals aspiring to excel in entrepreneurship with a focus on enterprise incubation, setting up an enterprise, entrepreneurial operations, credit linkages, and e-commerce. This standard delineates the essential competencies and skills required to navigate the complexities of establishing and managing successful ventures, offering guidance for training and certification programs aimed at fostering entrepreneurial growth and innovation in diverse contexts.', 120, 120, '1–200', 'Version', '27 Sep 2024', '27 Sep 2027', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Entrepreneurial Skills', 'Not applicable', 'Cross Sectoral Qualification', 'N.A.', '{"Theory":"50","Practical":"70","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "33", "qualification_type": "Cross Sectoral Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_55.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-OA-02868-2024-V1-MEPSC', 'Client Engagement Associate', 'office-administration-facility-management', 'Office Administration & Facility Management', 3.0, 'The Client Engagement Associate uses 21st-century life and employability skills to provide services and/or products to the company’s customers. They are responsible for optimizing the last-mile delivery of the company’s products and/or services and enhancing the happiness quotient of its customers.  They must ensure that all quality and safety parameters of their job role are adhered to. They must strive to create a positive work environment by working with teams, being adaptable and imbibing a growth mindset.', 330, 330, '201–400', 'Version', '27 Aug 2024', '27 Aug 2027', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Customer Service', 'Client Engagement - Sr. Associate (Level 3.5)
Client Engagement - Team Lead (Level 4)', 'Cross Sectoral Qualification', 'N.A.', '{"Theory":"50","Practical":"190","EmployabilitySkills":"30","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "34", "qualification_type": "Cross Sectoral Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_55.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-4.5-OA-02869-2024-V1-MEPSC', 'Documentation Executive (Import- Export)', 'office-administration-facility-management', 'Office Administration & Facility Management', 4.5, 'Documentation Executives (Import – Export) are those professionals who provide information and assistance to those individuals who wish to start their own goods exportation. Assistance involves helping with planning for the beginning of the exporting and importing process, setting up and forwarding the legal proceedings, acquiring approval assistance for export and import proceedings including transportation assistance, consultation regarding trade agreements between different countries, providing advice regarding the exportation and importing of goods to beneficial countries and such other matters.', 540, 540, '401–600', 'Version', '27 Aug 2024', '27 Aug 2027', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Legal and Compliance', 'Business Support Practitioner', 'General Qualification', 'N.A.', '{"Theory":"190","Practical":"260","EmployabilitySkills":"60","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "35", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_55.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, not