INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-02-ET-02991-2024-V1-MEPSC', 'Basics of Financial Literacy', 'office-administration-facility-management', 'Office Administration & Facility Management', 2.0, 'The basics of financial literacy qualification equips individuals with a comprehensive understanding of essential financial concepts, encompassing banking, loans, financial planning, digital payments, insurance, currency management, and safety protocols. This qualification empowers participants to navigate the intricacies of personal finance, and fostering a strong foundation for sound financial decision-making.', 30, 30, '1–200', 'Version', '27 Aug 2024', '27 Aug 2027', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Office Support', 'Not applicable', 'General Qualification', 'N.A.', '{"Theory":"15","Practical":"15","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "36", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_55.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-2.5-ET-02919-2024-V1-MEPSC', 'Fundamentals of Digital Literacy (Office Applications)', 'office-administration-facility-management', 'Office Administration & Facility Management', 2.5, 'Equips learners with essential skills in using the most common and basic Microsoft Office applications such as Word, Excel, and PowerPoint. Participants will gain proficiency in creating and managing documents, spreadsheets, and presentations, enhancing their digital productivity in various professional settings.', 30, 30, '1–200', 'Version', '27 Aug 2024', '27 Aug 2027', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Office Support', 'Not applicable', 'General Qualification', 'N.A.', '{"Theory":"10","Practical":"20","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "37", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_55.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-4.5-OA-02870-2024-V1-MEPSC', 'Digital Sales and Marketing Executive', 'office-administration-facility-management', 'Office Administration & Facility Management', 4.5, 'The Digital Sales and Marketing Executive course prepares individuals to take on key roles in developing and managing digital marketing initiatives. It covers essential topics such as SEO, SEM, content marketing, social media marketing, and data analytics, along with foundational knowledge in management, commerce, and business communication, enabling them to lead and optimize digital marketing efforts.', 1200, 1200, '1001–1200', 'Version', '25 Jul 2024', '25 Jul 2027', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Marketing', 'Not applicable', 'General Qualification', 'N.A.', '{"Theory":"600","Practical":"480","EmployabilitySkills":"120","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "38", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_55.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-OA-02871-2024-V1-MEPSC', 'Advance Course in Digital Sales and Marketing', 'office-administration-facility-management', 'Office Administration & Facility Management', 5.0, 'The Advance Course in Digital Sales and Marketing equips learners with comprehensive skills in digital marketing strategies, including SEO, SEM, email marketing, social media marketing, and the application of generative AI. This course also covers e-commerce marketing, branding, and analytics, preparing individuals to effectively plan and execute digital marketing campaigns and drive online sales.', 1200, 1200, '1001–1200', 'Version', '25 Jul 2024', '25 Jul 2027', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Marketing', 'Not applicable', 'General Qualification', 'N.A.', '{"Theory":"390","Practical":"210","EmployabilitySkills":"0","OJT_Mandatory":"600"}', false, '{}'::text[], '{"source_row": "39", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_55.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-OA-03178-2024-V2-DGT', 'OFFICE MANAGEMENT', 'office-administration-facility-management', 'Office Administration & Facility Management', 4.0, 'The individual will be able to impart theoretical instructions, demonstrate practical skills, evaluate and grade trainees of Office Management and Related trades in ITIs/ Vocational Training Institutes, industrial workshops, etc.', 1350, 1350, '1201–2400', 'Version', '22 Oct 2024', '21 Oct 2027', 'Directorate General of Training (DGT)', 'DGT', 'Secretary/Back Office Support, Manual Training Teacher/ Craft Instructor.', 'Technical Instructor in a vocational training Institute/ technical Institution, Supervisor in Industries', 'General Qualification', 'N.A.', '{"Theory":"450","Practical":"750","EmployabilitySkills":"0","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "40", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_55.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-OA-03222-2024-V2-DGT', 'सचिवीय पद्धति (हिंदी)', 'office-administration-facility-management', 'Office Administration & Facility Management', 4.0, 'व्यक्ति औद्योगिक निर्देशों, आईटीआई / व्यावसायिक प्रशिक्षण संस्थानों आदि में सैद्धांतिक निर्देशों, व्यावहारिक कौशल सचिवीय पद्धति (हिंदी) व्यवसाय के प्रशिक्षुओं को सैद्धांतिक और व्यावहारिक निर्देश प्रदान करने में सक्षम होगा', 1350, 1350, '1201–2400', 'Version', '22 Oct 2024', '21 Oct 2027', 'Directorate General of Training (DGT)', 'DGT', 'मैनुअल प्रशिक्षण शिक्षक / शिल्प प्रशिक्षक, सचिव / बैक ऑफिस सपोर्ट, सचिवों, अन्य, निजी सचिव-सह-आशुलिपिक, पर्सनल सेक्रेटरी', 'व्यावसायिक प्रशिक्षण संस्थानों / तकनीकी संस्थानों में अनुदेशक, उद्योगों में पर्यवेक्षक', 'General Qualification', 'N.A.', '{"Theory":"450","Practical":"750","EmployabilitySkills":"0","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "41", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_55.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-OA-03315-2024-V2-MEPSC', 'Receptionist', 'office-administration-facility-management', 'Office Administration & Facility Management', 3.0, 'The Receptionist qualification will equip the individual with advanced skills in AI-powered tools and modern technologies essential for dynamic office environments. It will provide comprehensive training in digital communication, visitor management, and administrative tasks, enabling the individual to efficiently manage responsibilities while leveraging the latest technological advancements. The qualification will ensure the individual is adept at using AI and digital tools to enhance productivity, streamline operations, and deliver superior service.', 420, 420, '401–600', 'Version', '22 Oct 2024', '22 Oct 2027', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Office Support', 'Executive – Secretarial Services/ Office Operations Executive', 'General Qualification', 'N.A.', '{"Theory":"110","Practical":"190","EmployabilitySkills":"30","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "42", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_55.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-4.5-OA-03429-2024-V1-MEPSC', 'Human Resource Operations Executive', 'office-administration-facility-management', 'Office Administration & Facility Management', 4.5, 'The Human Resource Operations Executive is responsible for managing and overseeing various HR functions including recruitment, selection, employee onboarding, training and development, performance appraisal, and employee relations. This role requires a blend of strategic planning, effective communication, and organizational skills to ensure smooth HR operations and contribute to the overall success of the organization.', 1200, 1200, '1001–1200', 'Version', '17 Dec 2024', '17 Dec 2027', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Human Resource Management', 'HR Supervisor/ Deputy HR Manager', 'General Qualification', 'N.A.', '{"Theory":"730","Practical":"350","EmployabilitySkills":"120","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "43", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_55.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-OA-03430-2024-V1-MEPSC', 'Deputy Human Resources Manager', 'office-administration-facility-management', 'Office Administration & Facility Management', 5.0, 'The Deputy Human Resources Manager is designed to deepen students'' expertise in strategic HR practices and prepare them for high-level operational roles. It focuses on advanced topics such as HR analytics, labour relations, and strategic manpower planning, equipping students with the skills to manage complex HR challenges. Students engage exclusively in industrial training and a comprehensive project report, applying their acquired knowledge in real-world settings to gain practical experience and insights into the HR industry.', 1200, 1200, '1001–1200', 'Version', '17 Dec 2024', '17 Dec 2027', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Human Resource Management', 'HR Manager', 'General Qualification', 'N.A.', '{"Theory":"480","Practical":"120","EmployabilitySkills":"0","OJT_Mandatory":"600"}', false, '{}'::text[], '{"source_row": "44", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_55.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-4.5-OA-03431-2024-V1-MEPSC', 'Business Analytics Executive', 'office-administration-facility-management', 'Office Administration & Facility Management', 4.5, 'The Business Analytics Executive qualification equips learners with essential skills in data analysis, statistical techniques, and business analysis tools such as Power BI, enabling them to support data-driven decision-making in organizations. This qualification focuses on practical applications of analytics in various business domains, preparing individuals for entry-level roles in business analytics.', 1200, 1200, '1001–1200', 'Version', '17 Dec 2024', '17 Dec 2027', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Operations', 'Lead Business Analyst', 'General Qualification', 'N.A.', '{"Theory":"700","Practical":"380","EmployabilitySkills":"120","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "45", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_55.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-OA-03432-2024-V1-MEPSC', 'Lead Business Analyst', 'office-administration-facility-management', 'Office Administration & Facility Management', 5.0, 'Lead Business Analyst qualification equips learners with in-depth skills in data analysis, big data technologies, machine learning, and business intelligence tools such as Python, R, SQL, Tableau, and Hadoop. This qualification is designed to prepare individuals for advanced roles in business analytics, enabling them to lead data-driven decision-making processes and optimize business strategies through sophisticated analytical techniques. It is ideal for those seeking to enhance their expertise in the rapidly evolving field of business analytics.', 1200, 1200, '1001–1200', 'Version', '17 Dec 2024', '17 Dec 2027', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Operations', 'Program Manager', 'General Qualification', 'N.A.', '{"Theory":"670","Practical":"230","EmployabilitySkills":"0","OJT_Mandatory":"300"}', false, '{}'::text[], '{"source_row": "46", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_55.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NA', 'Environment Sustainability Governance (ESG) Specialist', 'office-administration-facility-management', 'Office Administration & Facility Management', 7.0, 'Environment Sustainability Governance (ESG) Specialist helps the professional oversee the development and implementation of strategies to integrate sustainability principles into the organization''s operations and decision-making processes. Responsibilities include establishing ESG goals, tracking performance metrics, engaging with stakeholders, ensuring regulatory compliance, and fostering a culture of corporate responsibility. They also collaborate with senior management to align ESG initiatives with overall business objectives.', 390, 390, '201–400', 'Version', '18 Feb 2025', '18 Feb 2028', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Social Welfare', 'MD/ Chairperson', 'General Qualification', 'N.A.', '{"Theory":"120","Practical":"180","EmployabilitySkills":"30","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "47", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_55.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NAO', 'Design Thinking Executive', 'office-administration-facility-management', 'Office Administration & Facility Management', 5.0, 'Design Thinking Executive is a professional practicing design thinking can apply a human-centred approach effectively at workplace for problem solving, generating new ideas, implementing projects innovatively with a high level of empathy for all involved in the process including users and non-users. The individual would be more hands-on in their approach towards presenting & implementing ideas, working with prototypes from initial stages itself and use both analytical and intuitive capabilities for achieving desired outcomes.', 540, 540, '401–600', 'Version', '18 Feb 2025', '18 Feb 2028', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Business strategy, planning & management', 'Design Thinking Manager/ Senior Design Thinking Manager', 'Cross Sectoral Qualification', 'N.A.', '{"Theory":"150","Practical":"240","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "48", "qualification_type": "Cross Sectoral Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_55.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QM-06-OA-03636-2025-V1-MEPSC', 'Senior Internal Auditor', 'office-administration-facility-management', 'Office Administration & Facility Management', 6.0, 'Senior Internal Auditor assesses management systems, internal controls, and processes to ensure they align with organizational goals and compliance standards. Once areas for improvement are identified, this person recommends solutions and contributes to enhancing overall organizational performance. The individual also assesses risk management practices, financial controls, and governance structures, providing valuable insights to support informed decision-making of management.', 660, 660, '601–800', 'Version', '18 Feb 2025', '18 Feb 2028', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Management and Entrepreneurship & Professional Skills Council (MEPSC)', 'Legal and Compliance', 'Director', 'Cross Sectoral Qualification', 'N.A.', '{"Theory":"210","Practical":"270","EmployabilitySkills":"90","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "49", "qualification_type": "Cross Sectoral Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_55.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-04-PS-03784-2025-V1-MEPSC', 'Drone Operations – Surveillance and Patrolling', 'office-administration-facility-management', 'Office Administration & Facility Management', 4.0, 'A drone operator in surveillance and patrolling would develop competency to possess a blend of technical, operational, and limited analytical skills. The learner would be expected to efficiently monitor designated areas, ensure real time, situation, awareness, and rapid response to suspected potential threats or anomalies by following requisite aviation regulations, security guidelines and data protection protocols while ensuring safe operations and minimal risk to public safety.', 120, 120, '1–200', 'Version', '18 Feb 2025', '18 Feb 2028', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Private Security', 'not applicable', 'Future Skills Qualification', 'N.A.', '{"Theory":"45","Practical":"75","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "50", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_55.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-05-OA-03843-2025-V1-MEPSC', 'Fundamentals of Business Consulting', 'office-administration-facility-management', 'Office Administration & Facility Management', 5.0, 'Fundamentals of Business Consulting equips individuals with the skills to analyse client needs, develop customized solutions, and enhance business performance across various industries. This role involves strategic planning, client relationship management, and the application of consulting frameworks to address complex challenges. Participants will be prepared to provide impactful advice, drive operational improvements, and support clients in achieving their business goals through a mix of analytical, communication, and problem-solving skills.', 30, 30, '1–200', 'Version', '18 Feb 2025', '18 Feb 2028', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Management and Entrepreneurship & Professionals Skills Council (MEPSC)', 'Entrepreneurial Skills', 'not applicable', 'Cross Sectoral Qualification', 'N.A.', '{"Theory":"11","Practical":"19","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "51", "qualification_type": "Cross Sectoral Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_55.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-OA-03516-2025-V2-ASAP', 'Assistant Offset Printing Operator', 'office-administration-facility-management', 'Office Administration & Facility Management', 4.0, 'Individuals will be able to operate single colour or multicolour offset machine and do necessary
settings related with paper, ink and other chemicals. Taking prints to require number of copies
with satisfying all parameter as customer requirements. Printing operator also responsible for
the maintenance and cleaning of cylinders and inking rollers.', 510, 510, '401–600', 'Version', '30 Dec 2021', '18 Feb 2028', 'Additional Skill Acquisition Programme, Government of Kerala', 'Additional Skill Acquisition Programme', 'Assistant Printing Machine Operator / Offset Printing operator', 'PROFESSIONAL PROGRESSION
Assistant offset operator, Offset operator, Senior offset Operator, Asst. Supervisor,
Supervisor,  Asst. Manager, Manager,  Senior Manger, General Manager
ACADEMIC PROGRESSION
On successful completion of course student can join Poly Technique for Diploma in Printing / B-
Tech Through Lateral Entry', 'General Qualification', 'N.A.', '{"Theory":"112","Practical":"248","EmployabilitySkills":"30","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "52", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_09_55.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/CP/PCSC/05731', 'Wood Polisher', 'paints-coatings', 'Paints & Coatings', 4.0, 'The individual assesses the surface quality, advises the customer on any pre-treatment, prepares, cleans and then paints it using appropriate coatings, polishes, and tools to achieve the desired finish.', 570, 570, '401–600', 'Version', '05 Feb 2018', '16 Nov 2025', 'Paints and Coatings Skill Council', 'Paints and Coatings Skill Council', 'Industrial and Decorative Paint Application', 'Wood Polisher with experience can progress to Supervisor Decorative Painting or be self employed and become an entrepreneur. Please see the attached progression chart', 'General Qualification', 'N.A.', '{"Theory":"115","Practical":"320","EmployabilitySkills":"60","OJT_Mandatory":"75"}', false, '{}'::text[], '{"source_row": "1", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_10_20.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/CP/PCSC/06469', 'General Industrial (Liquid) Painter', 'paints-coatings', 'Paints & Coatings', 4.0, 'The individual at work assesses the substrate to be coated, understands colour, chemistry and finish required, prepares the substrate for liquid paint application and coats it using recommended tools and equipment, to achieve the desired finish as per company standards and requirement.', 480, 480, '401–600', 'Version', '03 Mar 2017', '16 Nov 2025', 'Paints and Coatings Skill Council', 'Paints and Coatings Skill Council', 'Industrial Paint Application', 'General Industrial (Liquid) Painter, Supervisor General Industrial (Liquid) Painter.                                
With experience and acquiring additional qualifications can become QC & Testing Supervisor. Please see the attached progression chart', 'General Qualification', 'N.A.', '{"Theory":"105","Practical":"225","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "2", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_10_20.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/CP/PCSC/06470', 'Technical Sales Representative', 'paints-coatings', 'Paints & Coatings', 5.0, 'The Technical Sales Representative is responsible for providing sales support to industrial paints customers, institutional customers and dealers in terms of paint performance, characteristics and application outcomes as well as quality control methods. The individual at work interacts with customers, understands their paint performance requirements, helps select the most appropriate paint, trains on application process, collects feedback on previously sold paint, and offers the most suitable paint solution for a purpose.
The job requires the individual to: have pleasing personality, ability to express technical information in common language and willingness to travel out of town.', 570, 570, '401–600', 'Version', '03 Mar 2017', '16 Nov 2025', 'Paints and Coatings Skill Council', 'Paints and Coatings Skill Council', 'Sales and Marketing', 'Technical Sales Representative with experience and acquiring additional qualifications can become General Manager Sales and Marketing', 'General Qualification', 'N.A.', '{"Theory":"135","Practical":"240","EmployabilitySkills":"90","OJT_Mandatory":"105"}', false, '{}'::text[], '{"source_row": "3", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_10_20.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
