INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03 -PD-00403-2023-V1-SCPWD', 'Warehouse Packer-(Divyangjan)-LD', 'persons-with-disability', 'Persons with Disability', 3.0, 'Warehouse Packer in the Logistics industry is also known as Packer, Floor Staff, Warehouse Associate. Individuals in this role need to pack items that have been picked or require binning. Individuals are responsible for packing items that require additional pre-packing or outbound packaging. Additional responsibilities could at times include loading and unloading cargo, labelling, re-packaging items and documenting cargo that has been moved. The difference in tasks performed under the Packer role thus varies according to the volume of operations, however the core function of the role is to pack items according to the nature of the product either for storage or transportation.', 400, 400, '201–400', 'Version', '03 May 2023', '27 Jan 2026', 'Skill Council for Persons with Disability (SCPwD)', 'Skill Council for Persons with Disability (SCPwD)', 'Packaging', 'Warehouse Executive', 'General Qualification', 'Packaging', '{"Theory":"100","Practical":"200","EmployabilitySkills":"70","OJT_Mandatory":"30"}', true, '{"LD"}'::text[], '{"source_row": "24", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_10_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = E