INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-02-PD-00874-2023-V1-SCPWD', 'Assistant-Sewing Machine Operator (Divyangjan)-MD', 'persons-with-disability', 'Persons with Disability', 2.0, 'A Sewing Machine Operator, is an important job-role associated with Apparel sector, Made-Ups and Home Furnishing Industry. The primary responsibility of a SMO is to stitch specific garments with desired quality.', 780, 780, '601–800', 'Version', '31 Aug 2023', '31 Aug 2026', 'Skill Council for Persons with Disability (SCPwD)', 'Skill Council for Persons with Disability', 'Sewing', 'Specialized Sewing Machine Operator (Level 2)', 'General Qualification', 'N.A.', '{"Theory":"190","Practical":"560","EmployabilitySkills":"30","OJT_Mandatory":"0"}', true, '{"MD"}'::text[], '{"source_row": "31", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_10_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-PD-00885-2023-V1-SCPWD', 'CCTV Video Footage Auditor (Divyangjan) – LD', 'persons-with-disability', 'Persons with Disability', 4.0, 'A CCTV Video Footage Auditor audits, reviews, examines, and minutely inspects CCTV footage daily, at periodic intervals, as per set guidelines, SOPs, and situational awareness. Using specialized CCTV video footage auditing and investigation tools, the auditor ‘looks out’ for exceptions, process violations, abnormalities, performance lapses, behavioral patterns, potential threats, risks, and so on. The auditor de-bugs bytes of visual information and multi-tasks by comparing past incidents. The auditor joins the dots to gain actionable intelligence, and reports the audit findings/ incidents in standardized formats. Part of the job description includes the appropriate tagging of relevant audit findings/incidents and creating well categorized institutional libraries that can quickly be referred to in the future, backing up CCTV video footage at multiple locations for the purpose of disaster recovery, as well as providing business intelligence that accrues from reporting audit findings and incidents using standardized templates', 490, 580, '401–600', 'Version', '31 Aug 2023', '28 Jul 2026', 'Skill Council for Persons with Disability (SCPwD)', 'Skill Council for Persons with Disability', 'Private Security, Personal Security', 'Security Officer', 'General Qualification', 'Management & Entrepreneurship and Professional Skills', '{"Theory":"160","Practical":"260","EmployabilitySkills":"70","OJT_Mandatory":"0"}', true, '{"LD"}'::text[], '{"source_row": "32", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_10_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
