INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-PD-00882-2023-V1-SCPWD', 'HR Executive –Payroll and Employee Data Management  (Divyangjan) -LD', 'persons-with-disability', 'Persons with Disability', 4.0, 'The HR Executive – Payroll and Employee Data Management maintains employee data for the Human Resource (HR) department and compiles all necessary payroll data, enters it into the organisation’s data system, calculates each employee’s respective pay, computing statutory and tax related entitlements and deductions and co-ordinates with the accounts department for disbursements and fund transfers.', 520, 520, '401–600', 'Version', '31 Aug 2023', '28 Feb 2027', 'Skill Council for Persons with Disability (SCPwD)', 'Skill Council for Persons with Disability', 'Human Resource Management', 'Compensation and Benefits Analyst (Level 4)', 'General Qualification', 'Management', '{"Theory":"150","Practical":"270","EmployabilitySkills":"70","OJT_Mandatory":"30"}', true, '{"LD"}'::text[], '{"source_row": "35", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_10_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-PD-00883-2023-V1-SCPWD', 'HR Executive –Payroll and Employee Data Management  (Divyangjan) -SHI', 'persons-with-disability', 'Persons with Disability', 4.0, 'The HR Executive – Payroll and Employee Data Management maintains employee data for the Human Resource (HR) department and compiles all necessary payroll data, enters it into the organisation’s data system, calculates each employee’s respective pay, computing statutory and tax related entitlements and deductions and co-ordinates with the accounts department for disbursements and fund transfers.', 640, 640, '601–800', 'Version', '31 Aug 2023', '28 Feb 2027', 'Skill Council for Persons with Disability (SCPwD)', 'The HR Executive – Payroll and Employee Data Management maintains employee data for the Human Resource (HR) department and compiles all necessary payroll data, enters it into the organisation’s data system, calculates each employee’s respective pay,', 'Human Resource Management', 'Compensation and Benefits Analyst (Level 4)', 'General Qualification', 'Office Management & Professional Skills', '{"Theory":"210","Practical":"330","EmployabilitySkills":"70","OJT_Mandatory":"30"}', true, '{"SHI"}'::text[], '{"source_row": "36", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_10_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, noti