INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-PD-00890-2023-V1-SCPWD', 'Kisan Drone Operator (Divyangjan) - LD', 'persons-with-disability', 'Persons with Disability', 4.0, 'A Kisan Drone Operator/pilot is       responsible for operating and  rendering the specific service using the drone and relevant technologies for agricultural and allied activities. The individuals operating the drone collect and analyse different types of data for enhancing productivity and profitability while ensuring sustainability and protection of the land resources and where applicable deploy the drone to undertake specific activities like spray of Plant protection chemicals/ fertilizer or obtain ground data for other related activities. The individual is also responsible for carrying out regular maintenance of drone', 400, 400, '201–400', 'Version', '01 Aug 2023', '31 Mar 2026', 'Skill Council for Persons with Disability (SCPwD)', 'Skill Council for Persons with Disability', 'Precision Farming', 'Custom Hiring Service Provider (NSQF Level-5)', 'General Qualification', 'Agriculture', '{"Theory":"90","Practical":"120","EmployabilitySkills":"70","OJT_Mandatory":"120"}', true, '{"LD"}'::text[], '{"source_row": "37", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_10_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hour