INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-PD-02205-2024-V1-SCPWD', 'Checker- Inline & Measurement (Divyangjan)-LD', 'persons-with-disability', 'Persons with Disability', 4.0, 'A checker is an important job-role associated with Apparel sector The primary responsibility of a checker is to identify the faults in the fabrics, cut components, garment parts or finished products through visual inspection. As Checker, the individual inspects the accuracy of the dimensions of the stiched parts and the f inished apparel. The primary responsibility of a checker is to measure all the dimension of the apparel and ensure they are free from defects', 480, 480, '401–600', 'Version', '15 Mar 2024', '31 Dec 2025', 'Skill Council for Persons with Disability (SCPwD)', 'Skill Council for Persons with Disability', 'Quality Assurance', 'QC Executive - Sewing Line', 'General Qualification', 'Apparels', '{"Theory":"125","Practical":"295","EmployabilitySkills":"60","OJT_Mandatory":"0"}', true, '{"LD"}'::text[], '{"source_row": "106", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_10_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
