INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-PD-02222-2024-V2-SCPWD', 'Washing Machine Operator (Divyangjan) -SHI', 'persons-with-disability', 'Persons with Disability', 3.0, 'Washing Machine Operator is responsible to perform various types of washings for apparel and garments, made ups and home furnishing articles. The washings are intended to achieve desired finish reflected in terms of improved performance, cleanliness, luster, feel, drape, softness with combinations of time, temperature, process conditions and chemical formulations specific to product class. The operator should be able to interpret and understand technical specifications and ensure correct wash cycle is used for product type.', 490, 490, '401–600', 'Version', '15 Mar 2024', '17 Nov 2026', 'Skill Council for Persons with Disability (SCPwD)', 'Skill Council for Persons with Disability', 'Sampling', 'Processing Supervisor Level 4(Vertical)', 'General Qualification', 'Apparels', '{"Theory":"198","Practical":"222","EmployabilitySkills":"70","OJT_Mandatory":"0"}', true, '{"SHI"}'::text[], '{"source_row": "114", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_10_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
