INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-PD-02517-2024-V1-SCPWD', 'Advertising Traffic Coordinator (Media Organisations) (Divyangjan) - LD', 'persons-with-disability', 'Persons with Disability', 4.0, 'The individuals in this job are required to manage inventory and schedule advertisements for a broadcasting company. The individual needs to be well versed with the daily programme schedules and must be able to coordinate with the programming teams, as well as the agencies, to receive information on the duration of programmes/advertisements, to prepare playout schedules and make adjustments in the event of any change.', 580, 580, '401–600', 'Version', '30 Apr 2024', '23 Feb 2028', 'Skill Council for Persons with Disability (SCPwD)', 'Skill Council for Persons with Disability', 'Traffic Coordinator (Media Organizations)', 'Not Applicable', 'General Qualification', 'Media and Entertainment', '{"Theory":"120","Practical":"330","EmployabilitySkills":"70","OJT_Mandatory":"60"}', true, '{"LD"}'::text[], '{"source_row": "135", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_10_35.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
