INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/OAFM/MEPSC/05426', 'Armed Security Guard', 'private-security', 'Private Security', 4.0, 'Armed Security Guard has to guard designated premises and people by manning the first tier of protection aided by appropriate security devices/ equipment and by timely and efficient use of firearms. The core responsibility includes guarding against theft, criminal acts, emergencies, fire and other contingencies.', 450, 450, '401–600', 'Version', '24 Feb 2022', '24 Feb 2027', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Management &Entrepreneurship and Professional Skills Council (MEPSC)', 'Private Security', 'Personal Security Officer, Security supervisor', 'General Qualification', 'N.A.', '{"Theory":"150","Practical":"240","EmployabilitySkills":"60","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "1", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_12_33.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/SEC/MEPSC/06149', 'CCTV Video Footage Auditor', 'private-security', 'Private Security', 4.0, 'A CCTV Video Footage Auditor audits, reviews, examines, and minutely inspects CCTV footage
daily, at periodic intervals, as per set guidelines, SOPs, and situational awareness. Using
specialized CCTV video footage auditing and investigation tools, the auditor looks out for
exceptions, process violations, abnormalities, performance lapses, behavioral patterns, potential
threats, risks, and so on.', 480, 480, '401–600', 'Version', '17 Nov 2022', '17 Nov 2025', 'Management & Entrepreneurship and Professional Skills Council (MEPSC)', 'Management &Entrepreneurship and Professional Skills Council (MEPSC)', 'CCTV Video Footage Auditor', 'Lead – Security and Site Surveillance', 'General Qualification', 'N.A.', '{"Theory":"210","Practical":"210","EmployabilitySkills":"60","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "2", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_12_33.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-05-OR-02108-2024-V1-MSU', 'Basics of Luxury Brand Management', 'retail', 'Retail', 5.0, 'This qualification equips the candidate with requisite skills and understanding for managing premium and luxury brands. It includes insights into global practices and other luxury segments as well. The candidate will be able to work in senior positions such as  Brand Manager, Marketing Manager, Buyer, Merchandiser and Visual Merchandiser  in premium stores that offer products or services of top-level brands.', 30, 30, '1–200', 'Version', '31 Jan 2024', '30 Jan 2027', 'Medhavi Skill University', 'Medhavi Skills University', 'Luxury Brand', 'N/A', 'General Qualification', 'N.A.', '{"Theory":"15","Practical":"15","EmployabilitySkills":"00","OJT_Mandatory":"00"}', false, '{}'::text[], '{"source_row": "1", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_13_43.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-4.5-OR-02107-2024-V1-MSU', 'Retail Services – Luxury Segment', 'retail', 'Retail', 4.5, 'This qualification equips the candidate with requisite skills and understanding to serve customers of premium and luxury brands. It includes insights into global practices and other luxury segments as well. The candidate will be able to work in senior positions such as Senior Executive-Retail Store, Team leader-Retail Store, supervisor-Retail Store, Boutique Supervisor, etc. in premium stores that offer products or services of top-level brands.', 30, 30, '1–200', 'Version', '31 Jan 2024', '30 Jan 2027', 'Medhavi Skill University', 'Medhavi Skills University', 'Luxury Brand', 'N/A', 'General Qualification', 'N.A.', '{"Theory":"15","Practical":"15","EmployabilitySkills":"00","OJT_Mandatory":"00"}', false, '{}'::text[], '{"source_row": "2", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_13_43.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-4.5-OR-02434-2024-V2-RASCI', 'Junior Supervisor (Sales)', 'retail', 'Retail', 4.5, 'The individual in this job role is responsible for achieving Sales Targets by driving secondary value & volume objectives for the General Trade Channel (GT) and Modern Trade (MT) Channel in the assigned geographical area. Individuals in this role typically supervise a set of salespeople employed by the channel partners. The individual is responsible for the expansion of the sales channel, increasing market share, and training & coaching the salespeople of the distributors / modern retailers. S/he is also responsible for ensuring general trade outstanding collections through distributor sales teams, based on defined norms.', 480, 480, '401–600', 'Version', '21 Jun 2015', '29 Apr 2027', 'Retailers Association Skill Council of India (RASCI)', 'Retailers Association''s Skill Council of India (RASCI)', 'Sales', 'Territory / Area Sales Manager', 'Cross Sectoral Qualification,General Qualification', 'N.A.', '{"Theory":"159","Practical":"201","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "3", "qualification_type": "Cross Sectoral Qualification,General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_13_43.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-OR-02428-2024-V2-RASCI', 'Direct Seller', 'retail', 'Retail', 4.0, 'Individuals in this position work for him/herself to earn income through selling products or services directly to the customers instead of working for an employer that pays a salary/wage. An Individual in this position can also be a Direct Sales Agent / Salesman working to achieve business objectives.', 450, 450, '401–600', 'Version', '05 Feb 2018', '30 Apr 2027', 'Retailers Association Skill Council of India (RASCI)', 'Retailers Association''s Skill Council of India (RASCI)', 'Consumer Sales,Sales', 'Retailer', 'Cross Sectoral Qualification,General Qualification', 'N.A.', '{"Theory":"150","Practical":"180","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "4", "qualification_type": "Cross Sectoral Qualification,General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_13_43.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-OR-02429-2024-V2-RASCI', 'Merchant Relationship Executive', 'retail', 'Retail', 4.0, 'This individual acts as a bridge between the e-commerce marketplace and the seller fraternity. He/she is responsible for profiling, interacting, and acquiring new sellers in the market and thereafter, onboarding them to the e-commerce marketplace. In addition, he/she is also responsible for managing the already on boarded/existing sellers through query resolution and/or any other issues they may face.', 450, 450, '401–600', 'Version', '05 Feb 2018', '29 Apr 2027', 'Retailers Association Skill Council of India (RASCI)', 'Retailers Association’s Skill Council of India (RASCI)', 'Sales operations', 'Merchant Relationship Manager', 'General Qualification', 'N.A.', '{"Theory":"132","Practical":"198","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "5", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_13_43.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-4.5-OR-02430-2024-V2-RASCI.', 'Visual Merchandiser', 'retail', 'Retail', 4.5, 'Individual in this position is responsible for implementing visual merchandising concepts and elements as per guidelines laid down by the head office/store/various brands in the store. This person will also execute merchandising themes and plots as per business need.', 540, 540, '401–600', 'Version', '19 Dec 2018', '29 Apr 2027', 'Retailers Association Skill Council of India (RASCI)', 'Retailers Association’s Skill Council of India (RASCI)', 'Marketing', 'Marketing Manager', 'Apprenticeship Qualification,General Qualification', 'N.A.', '{"Theory":"186","Practical":"234","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "6", "qualification_type": "Apprenticeship Qualification,General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_13_43.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-4.5-OR-02431-2024-V2-RASCI', 'Retailer', 'retail', 'Retail', 4.5, 'Individual in this position also known as Retail Store Owner / Team Leader of a Direct Sales Team. He/ She is the primary or sole operator for the business who employs / engages others for daily operations. In case of direct selling, the individual manages a team and is responsible for selling of goods to consumers away from the fixed retail outlet either from home or any other non-store location.', 540, 540, '401–600', 'Version', '27 Dec 2018', '29 Apr 2027', 'Retailers Association Skill Council of India (RASCI)', 'Retailers Association''s Skill Council of India (RASCI)', 'Consumer Sales', 'Omni-Channel Retailer', 'Cross Sectoral Qualification,General Qualification', 'N.A.', '{"Theory":"181","Practical":"239","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "7", "qualification_type": "Cross Sectoral Qualification,General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_13_43.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-5.5-OR-02432-2024-V2-RASCI', 'Retail Store Manager', 'retail', 'Retail', 5.5, 'Individuals in this role manage the overall operations of the store and ensure its profitability. Thus, this individual is responsible to control operational expenses and ensure the growth of ''top-line'' and ''bottom-line'' set by the organisation. Individual in this position is responsible for supervising and directing the store staff, taking staffing decisions, ensuring product availability, maintaining visual merchandising standards, ensuring customer satisfaction, optimising the store''s financial performance and managing safety and security of the store while adhering to the business and store processes.', 600, 600, '401–600', 'Version', '19 Dec 2018', '29 Apr 2027', 'Retailers Association Skill Council of India (RASCI)', 'Retailers Association''s Skill Council of India (RASCI)', 'Store Operations', 'Cluster Head / Area Head', 'Cross Sectoral Qualification,General Qualification', 'N.A.', '{"Theory":"192","Practical":"258","EmployabilitySkills":"90","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "8", "qualification_type": "Cross Sectoral Qualification,General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_13_43.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-4.5-OR-02433-2024-V2-RASCI.', 'Digital Cataloguer', 'retail', 'Retail', 4.5, 'The individual is responsible for aiding in creation of an attractive digital catalogue and other digital pages with respect to the look and feel of the product and product description. Thus, the accuracy of the information and the correctness of placing products as per buyers directive will be his/her job.', 480, 480, '401–600', 'Version', '19 Dec 2018', '30 Apr 2027', 'Retailers Association Skill Council of India (RASCI)', 'Retailers Association Skill Council of India (RASCI)', 'Sales Operations', 'Marketing Manager E-Commerce', 'Apprenticeship Qualification,Cross Sectoral Qualification,General Qualification', 'N.A.', '{"Theory":"141","Practical":"219","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "9", "qualification_type": "Apprenticeship Qualification,Cross Sectoral Qualification,General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_13_43.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-5.5-OR-02733-2023-V1-RASCI.', 'Marketing Manager (E-Commerce)', 'retail', 'Retail', 5.5, 'This qualification aims to upskill retailers or owners of the small and medium retail enterprises including business leaders, senior managers working in a diverse range of businesses in traditional and organised retail sector. This qualification upskills the individual to diversify their marketing and sales channels by setting up an e-commerce platform for their business and managing it for better business prospects.
They are individuals who operate independently, under limited or no supervision from others, and are responsible for making a range of operational decisions.

The complete qualification or selected NOS units of the qualification can also be integrated into three-year Undergraduate or Four-year Honours and Post Graduate programmes in the streams of commerce and management studies. Such integration will aid in development of competencies in individuals to manage development and implementation of marketing strategies on e-commerce website and social media platform to enhance the business outcomes as entrepreneurs and or business managers during their upcoming career progression.', 630, 630, '601–800', 'Version', '01 Nov 2023', '01 Nov 2026', 'Retailers Association Skill Council of India (RASCI)', 'Retailers Association''s Skill Council of India (RASCI)', 'Sales & Marketing', 'Lead Digital Marketing/ CRM', 'Apprenticeship Qualification,Cross Sectoral Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"220","Practical":"260","EmployabilitySkills":"90","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "10", "qualification_type": "Apprenticeship Qualification,Cross Sectoral Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_13_43.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-04-OR-02920-2024-V1-RASCI', 'Fundamentals of Artificial Intelligence (AI) for Retail', 'retail', 'Retail', 4.0, 'The micro credential helps in developing comprehensive understanding of AI, including its fundamental concepts, and leveraging this knowledge to outline diverse applications within the retail industry including how AI can personalize the customer shopping experience whilst transforming and enhancing retail operations.', 30, 30, '1–200', 'Version', '27 Aug 2024', '27 Aug 2027', 'Retailers Association Skill Council of India (RASCI)', 'Retailers Association''s Skill Council of India (RASCI)', 'Store operations; Sales operations', 'NIL', 'Future Skills Qualification,Micro Credentials', 'N.A.', '{"Theory":"15","Practical":"15","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "11", "qualification_type": "Future Skills Qualification,Micro Credentials", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_13_43.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-OR-02873-2024-V1-RASCI', 'Retail Order Fulfilment Assistant', 'retail', 'Retail', 3.0, 'This individual in the job role receives & stores goods in retail operations, processes customer orders and delivers the products to the customers at their premises in Retail operations and e-commerce working environment. She/ he engages with the customer for various transactions like accepting and processing payments, customer queries, and product returns.', 390, 390, '201–400', 'Version', '04 Mar 2020', '27 Aug 2027', 'Retailers Association Skill Council of India (RASCI)', 'Retailers Association''s Skill Council of India (RASCI)', 'Sales Operations; Store Operations', 'Merchant Relationship Executive', 'Apprenticeship Qualification,Cross Sectoral Qualification,General Qualification,Multi-Skill Qualification', 'N.A.', '{"Theory":"126","Practical":"144","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "12", "qualification_type": "Apprenticeship Qualification,Cross Sectoral Qualification,General Qualification,Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_13_43.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-OR-02874-2024-V1-RASCI', 'Retail Sales Executive', 'retail', 'Retail', 4.0, 'Individuals in this position interact with customers by giving specialized service and product demonstrations to maximize business in a retail environment whilst striving for continuous improvements in levels of services rendered. They also provide service at the cashiering point by processing payments towards purchases made by customers.', 480, 480, '401–600', 'Version', '27 Aug 2024', '27 Aug 2027', 'Retailers Association Skill Council of India (RASCI)', 'Retailers Association''s Skill Council of India (RASCI)', 'Store Operations', 'Visual Merchandiser', 'Apprenticeship Qualification,Cross Sectoral Qualification,General Qualification,Multi-Skill Qualification', 'N.A.', '{"Theory":"171","Practical":"189","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "13", "qualification_type": "Apprenticeship Qualification,Cross Sectoral Qualification,General Qualification,Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_13_43.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-5.5-OR-02875-2024-V1-RASCI', 'Retail Merchandise Manager', 'retail', 'Retail', 5.5, 'This qualification reflects the role of individuals who undertake retail merchandise management activity to deliver profitable results for a retail organisation. They analyse merchandise performance results and follow an organisational strategy to plan and enhance ongoing merchandise performance. 
 
These individuals operate with autonomy, and are responsible for their personal outputs, and undertake decision making independently and in consultation with relevant internal and external stakeholders. Individuals with this qualification can perform roles such as sourcing & purchasing, merchandise planning and merchandise management.

The complete qualification or selected NOS units of the qualification can also be integrated into three-year Undergraduate or Four-year Honours and Post Graduate programmes in the streams of commerce and management studies. Such integration will aid in development of competencies in individuals to manage development and implementation of merchandise strategies as entrepreneurs and or business managers during their upcoming career progression in Retail sector.', 630, 630, '601–800', 'Version', '27 Aug 2024', '27 Aug 2027', 'Retailers Association Skill Council of India (RASCI)', 'Retailers Association''s Skill Council of India (RASCI)', 'Retail and Wholesale Trade Managers', 'Category Manager', 'Apprenticeship Qualification,Future Skills Qualification', 'N.A.', '{"Theory":"219","Practical":"261","EmployabilitySkills":"90","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "14", "qualification_type": "Apprenticeship Qualification,Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_13_43.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-OR-03322-2024-V2-RASCI', 'Retail Sales Assistant', 'retail', 'Retail', 3.0, 'Individuals in this position display merchandise and interact with  customers to understand their needs to service them with sales of relevant product offerings whilst working cordially  within the team and retail organization.', 390, 390, '201–400', 'Version', '19 May 2015', '22 Oct 2027', 'Retailers Association Skill Council of India (RASCI)', 'Retailers Association''s Skill Council of India (RASCI)', 'Store Operations', 'Retail Sales Executive', 'Apprenticeship Qualification,Cross Sectoral Qualification,General Qualification', 'N.A.', '{"Theory":"120","Practical":"150","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "15", "qualification_type": "Apprenticeship Qualification,Cross Sectoral Qualification,General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_13_43.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-OR-03321-2024-V2-RASCI', 'Retail Cashier', 'retail', 'Retail', 3.0, 'Individuals in this position service and process all customer transactions for payments made towards sales done whilst adhering to accounting principles and working cordially within the team and retail organization.', 360, 360, '201–400', 'Version', '19 May 2015', '22 Oct 2027', 'Retailers Association Skill Council of India (RASCI)', 'Retailers Association''s Skill Council of India (RASCI)', 'Store Operations', 'Retail sales Assistant, Retail Sales Executive', 'Apprenticeship Qualification,Cross Sectoral Qualification,General Qualification', 'N.A.', '{"Theory":"100","Practical":"140","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "16", "qualification_type": "Apprenticeship Qualification,Cross Sectoral Qualification,General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_13_43.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-02-OR-03320-2024-V2-RASCI', 'Retail Store Operations Assistant', 'retail', 'Retail', 2.0, 'Individuals in this position receive, move, store, and deliver products whilst working cordially within the team and retail organisation', 330, 330, '201–400', 'Version', '19 May 2015', '22 Oct 2027', 'Retailers Association Skill Council of India (RASCI)', 'Retailers Association''s Skill Council of India (RASCI)', 'Store Operations', 'Retail Sales Assistant', 'Apprenticeship Qualification,General Qualification', 'N.A.', '{"Theory":"100","Practical":"130","EmployabilitySkills":"30","OJT_Mandatory":"70"}', false, '{}'::text[], '{"source_row": "17", "qualification_type": "Apprenticeship Qualification,General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_13_43.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-OR-03325-2024-V2-RASCI', 'Salesperson (Distribution)', 'retail', 'Retail', 3.0, 'Individual in this position visits retail/wholesale outlets as per daily route plan & makes sales call using relevant selling aids like handhelds to increase productivity and achieve sales targets, demonstrate commanding knowledge of the trade being serviced by him/her and the existing competitors. He/she identifies new outlets to increase sales of the products and provide service facilitating resolution of trade problems related to products and company being represented by the salesman. He/she creates demand at point of sale by creating visibility for products putting POSM (Point of sales material) and merchandising elements like countertop/ shelves or racks depending on the category of product he/she sells.', 390, 390, '201–400', 'Version', '19 May 2019', '22 Oct 2027', 'Retailers Association Skill Council of India (RASCI)', 'Retailers Association''s Skill Council of India (RASCI)', 'Sales', 'Junior Supervisor (Sales)', 'Apprenticeship Qualification,Cross Sectoral Qualification,General Qualification', 'N.A.', '{"Theory":"110","Practical":"160","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "18", "qualification_type": "Apprenticeship Qualification,Cross Sectoral Qualification,General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_13_43.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-4.5-OR-03323-2024-V2-RASCI', 'Retail Team Leader', 'retail', 'Retail', 4.5, 'Individuals in this position play a key role in planning and organizing merchandise with a sharp focus on product off‐take and sales whilst leading a team.', 480, 480, '401–600', 'Version', '19 May 2019', '22 Oct 2027', 'Retailers Association Skill Council of India (RASCI)', 'Retailers Association''s Skill Council of India (RASCI)', 'Store Operations', 'Deputy Manager (Retail Store Department)', 'Apprenticeship Qualification,Cross Sectoral Qualification,General Qualification', 'N.A.', '{"Theory":"160","Practical":"200","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "19", "qualification_type": "Apprenticeship Qualification,Cross Sectoral Qualification,General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_13_43.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-OR-03324-2024-V2-RASCI', 'Deputy Manager (Retail Store Department)', 'retail', 'Retail', 5.0, 'Individuals in this position should be able to build/manage a store operations team and also possess a good understanding of customer segments and their product and brand preferences, competition and sales techniques and incentives that effect incremental customer purchases.', 540, 540, '401–600', 'Version', '19 May 2015', '22 Oct 2027', 'Retailers Association Skill Council of India (RASCI)', 'Retailers Association''s Skill Council of India (RASCI)', 'Store Operations', 'Retail Store Manager', 'Apprenticeship Qualification,General Qualification', 'N.A.', '{"Theory":"160","Practical":"260","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "20", "qualification_type": "Apprenticeship Qualification,General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_13_43.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-03-OR-04253-2025-V1-RASCI', 'Fundamentals of Retail Business', 'retail', 'Retail', 3.0, 'This occupational standard outlines the fundamental skills and knowledge required to engage with customers, identify their needs, demonstrate product features and benefits based on those needs, handle basic objections, and assist in the payment process in a retail environment', 60, 60, '1–200', 'Version', '08 May 2025', '08 May 2028', 'Retailers Association Skill Council of India (RASCI)', 'Retailers Association’s Skill Council of India (RASCI)', 'Store Operations', 'N A', 'General Qualification,National Occupational Standard,Upskilling Qualification', 'N.A.', '{"Theory":"25","Practical":"35","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "21", "qualification_type": "General Qualification,National Occupational Standard,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_13_43.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-4.5-OR-04255-2025-V1-RASCI', 'Fundamentals of AI and IoT in Customer Engagement (Omnichannel Retail)', 'retail', 'Retail', 4.5, 'This National Occupational Standard (NOS) outlines the competencies required for professionals in retail who aim to excel in omnichannel strategies for customer experience management, leveraging advanced technologies such as AI and IoT. Its objective is to equip retail managers and executives with the skills to design, implement, and evaluate integrated marketing strategies that enhance customer engagement and satisfaction across multiple channels. This NOS is intended for retail professionals looking to future-proof their operations and drive innovation in a rapidly evolving market.', 120, 120, '1–200', 'Version', '08 May 2025', '08 May 2028', 'Retailers Association Skill Council of India (RASCI)', 'Retailers Association’s Skill Council of India (RASCI)', 'Store operations; Sales operations', 'N A', 'Future Skills Qualification,National Occupational Standard,Upskilling Qualification', 'N.A.', '{"Theory":"50","Practical":"70","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "22", "qualification_type": "Future Skills Qualification,National Occupational Standard,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_13_43.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-4.5-OR-04252-2025-V1-RASCI', 'Introduction to Retail Data Analytics', 'retail', 'Retail', 4.5, 'This occupational standard focuses on essential competencies for effectively collecting, organizing, and analyzing retail data. Participants will learn to utilize tools such as POS systems and spreadsheets to validate data, analyze sales trends, and understand consumer behavior.', 120, 120, '1–200', 'Version', '08 May 2025', '08 May 2028', 'Retailers Association Skill Council of India (RASCI)', 'Retailers Association’s Skill Council of India (RASCI)', 'Store Operations', 'N A', 'Future Skills Qualification,National Occupational Standard,Upskilling Qualification', 'N.A.', '{"Theory":"50","Practical":"70","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "23", "qualification_type": "Future Skills Qualification,National Occupational Standard,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_13_43.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-4.5-OR-04254-2025-V1-RASCI', 'Basics of Product Catalogue Using AI Tools', 'retail', 'Retail', 4.5, 'An individual in this role manages product listings by organizing categories and makes effective use of descriptions, images, and attributes for better searchability. They collaborate with vendors and marketing teams to maintain accurate data, ensure compliance with platform policies, and address issues promptly. By analyzing performance, they prepare reports and recommend updates to boost visibility, customer engagement, and sales.', 90, 90, '1–200', 'Version', '08 May 2025', '08 May 2028', 'Retailers Association Skill Council of India (RASCI)', 'Retailers Association’s Skill Council of India (RASCI)', 'Store operations; Sales operations', 'N A', 'Cross Sectoral Qualification,Future Skills Qualification,National Occupational Standard,Upskilling Qualification', 'N.A.', '{"Theory":"40","Practical":"50","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "24", "qualification_type": "Cross Sectoral Qualification,Future Skills Qualification,National Occupational Standard,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_13_43.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-03-OR-04257-2025-V1-RASCI', 'Sustainable Practices in Packaging and Fixtures', 'retail', 'Retail', 3.0, 'This Micro credential describes the performance criteria, knowledge and understanding including generic skills required to sustainable material in all product packaging, fixtures, equipment and display props. This Occupational Standard applies to teams in Buying, Sourcing and Purchasing Departments who work with suppliers providing the packaging for products and fixtures to the business.  They operate independently, under limited  supervision from others, and are responsible for making operational decisions.', 30, 30, '1–200', 'Version', '08 May 2025', '08 May 2028', 'Retailers Association Skill Council of India (RASCI)', 'Retailers Association’s Skill Council of India (RASCI)', 'Store Operations', 'N A', 'Future Skills Qualification', 'N.A.', '{"Theory":"20","Practical":"10","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "25", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_13_43.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-04-OR-04258-2025-V1-RASCI', 'Customer Engagement for Environmental Sustainability', 'retail', 'Retail', 4.0, 'This Micro credential describes the performance criteria, knowledge and understanding including generic skills required to share the sustainability initiatives done by the business with their customers and providing them an opportunity to do their part to protect the environment', 15, 15, '1–200', 'Version', '08 May 2025', '08 May 2028', 'Retailers Association Skill Council of India (RASCI)', 'Retailers Association’s Skill Council of India (RASCI)', 'Store Operations', 'N A', 'Future Skills Qualification', 'N.A.', '{"Theory":"10","Practical":"05","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "26", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_13_43.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-03-OR-04256-2025-V1-RASCI', 'Sustainable Practices for Retail Store Operations', 'retail', 'Retail', 3.0, 'This occupational standard (OS) describes the performance criteria, knowledge and understanding including generic skills required to ensure sustainable practices are followed in all processes and procedures on a daily basis while managing the store. This Occupational standard applies to the Retail Management Team and Retail Associates who are based in the store.  They operate under regular supervision from others and can provide suggestions for making operational changes & decisions.', 30, 30, '1–200', 'Version', '08 May 2025', '08 May 2028', 'Retailers Association Skill Council of India (RASCI)', 'Retailers Association’s Skill Council of India', 'Store Operations', 'N.A', 'Future Skills Qualification,Micro Credentials,Upskilling Qualification', 'N.A.', '{"Theory":"15","Practical":"15","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "27", "qualification_type": "Future Skills Qualification,Micro Credentials,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_13_43.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-5.5-OR-04251-2025-V1-RASCI', 'Business Data Analyst (Retail)', 'retail', 'Retail', 5.5, 'This qualification reflects the role of a Business Data Analyst (Retail) who works in the retail industry, analyzing data, streamlining business processes, and driving strategic decisions. BA supports various retail operations such as sales, marketing, supply chain, and customer service by providing data-driven insights. Individuals in this role use business intelligence tools, data analytics software, and market research techniques to improve business performance and enhance profitability.', 660, 660, '601–800', 'Version', '08 May 2025', '08 May 2028', 'Retailers Association Skill Council of India (RASCI)', 'Retailers Association’s Skill Council of India', 'Store Operations', 'Retail Analytics Manager', 'Apprenticeship Qualification,Future Skills Qualification', 'N.A.', '{"Theory":"185","Practical":"320","EmployabilitySkills":"90","OJT_Mandatory":"65"}', false, '{}'::text[], '{"source_row": "28", "qualification_type": "Apprenticeship Qualification,Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_13_43.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-RI-00129-2023-V1-RCPSDC', 'Rubber Mixing Supervisor', 'rubber-industry', 'Rubber Industry', 5.0, 'A Rubber Mixing Supervisor is responsible to supervise all the processes involved in rubber mixing operations, such as: prepare the master batch and final batch of rubber compound in Banbury Mixer/Kneader and/or Open Mill. The person is responsible to monitor and manage the mixing area w.r.t machines, equipment, manpower and material.', 600, 600, '401–600', 'Version', '05 Jan 2023', '05 Jan 2026', 'Rubber Chemical & Petrochemical Skills Development Council (RCPSDC)', 'Rubber, Chemical & Petrochemical Skill Development Council', 'Mixing', 'Rubber Products Supervisor, Rubber Products Plant Head', 'General Qualification', 'N.A.', '{"Theory":"210","Practical":"300","EmployabilitySkills":"60","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "1", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_13_51.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-RI-00130-2023-V1-RCPSDC', 'Rubber Moulding and Curing Supervisor', 'rubber-industry', 'Rubber Industry', 5.0, 'A Moulding and Curing Supervisor is responsible to supervise the moulding and curing of rubber products as well as monitor the curing area with respect to machines, equipment, material and workforce.', 600, 600, '401–600', 'Version', '05 Jan 2023', '05 Jan 2026', 'Rubber Chemical & Petrochemical Skills Development Council (RCPSDC)', 'Rubber, Chemical & Petrochemical Skill Development Council', 'Rubber Moulding and Curing Supervisor job role in Moulding and Curing Occupation in rubber products manufacturing process.', 'Shift Incharge', 'General Qualification', 'N.A.', '{"Theory":"210","Practical":"300","EmployabilitySkills":"60","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "2", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_13_51.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-RI-00128-2023-V1-RCPSDC', 'Rubber Warehouse Supervisor', 'rubber-industry', 'Rubber Industry', 5.0, 'A Warehouse Supervisor is responsible for ensuring that the products received in any stores, such as: incoming stores, bonded stores, are matching with the accompanying documents. The person is also responsible to ensure appropriate storage of the material at designated places in the warehouse; facilitating smooth dispatch as per the customer requirement.', 600, 600, '401–600', 'Version', '05 May 2023', '05 May 2026', 'Rubber Chemical & Petrochemical Skills Development Council (RCPSDC)', 'Rubber, Chemical & Petrochemical Skill Development Council', 'Storage & Warehousing', 'Rubber Warehouse Supervisor level role which lead warehouse senior supervisor level in Storage & Warehouse Occupation in rubber manufacturing process.', 'General Qualification', 'N.A.', '{"Theory":"210","Practical":"300","EmployabilitySkills":"60","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "3", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_13_51.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-RI-00393-2023-V1', 'Agar Tree Artificial Inoculation Technician', 'rubber-industry', 'Rubber Industry', 3.0, 'The individual is involved in performing the artificial inoculation process with inoculation machineries and monitoring and testing of formation of black resin in agar wood after artificial inoculation process.', 420, 420, '401–600', 'Version', '29 Mar 2023', '29 Mar 2026', 'Rubber Chemical & Petrochemical Skills Development Council (RCPSDC)', 'Rubber, Chemical & Petro Chemical Skills Development Council', 'Production', 'Field Supervisor in Natural agarwood plantation', 'General Qualification', 'N.A.', '{"Theory":"150","Practical":"210","EmployabilitySkills":"30","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "4", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_13_51.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-2.5-RI-00392-2023-V1-RCPSDC', 'Agarwood Chip Cutter - General Worker', 'rubber-industry', 'Rubber Industry', 2.5, 'The individual in this job is responsible for performing all types of physical work related to Agarwood chipping operations and overall maintenance of the agarwood pieces as specified by the organization.', 540, 540, '401–600', 'Version', '29 Mar 2023', '29 Mar 2026', 'Rubber Chemical & Petrochemical Skills Development Council (RCPSDC)', 'Rubber Chemical & Petro Chemical Skills Development Council', 'Production (Agar)', 'Production - Natural Agarwood plantation (Level 3)', 'Heritage/Traditional Qualification', 'N.A.', '{"Theory":"180","Practical":"240","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "5", "qualification_type": "Heritage/Traditional Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_13_51.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-RI-00396-2023-V1-RCPSDC', 'Chemical Effluent Treatment Plant Operator', 'rubber-industry', 'Rubber Industry', 4.0, 'The individual at work is responsible for operating effluent treatment equipment to remove potentially harmful industrial, agricultural, and domestic contaminants from waste water as per standards.', 630, 630, '601–800', 'Version', '29 Mar 2023', '29 Mar 2026', 'Rubber Chemical & Petrochemical Skills Development Council (RCPSDC)', 'Rubber, Chemical & Petro Chemical Skills Development Council', 'Manufacturing/process', 'Effluent Plant treatment Supervisor (level-5), Effluent plant treatment Manager (level-6)', 'General Qualification', 'N.A.', '{"Theory":"210","Practical":"300","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "6", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_13_51.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-RI-00394-2023-V1-RCPSDC', 'Chemical Plant Assistant Operator', 'rubber-industry', 'Rubber Industry', 3.0, 'The individual at work is responsible for assisting operator with performing chemical manufacturing operations as per applicable standards.', 450, 450, '401–600', 'Version', '29 Mar 2023', '29 Mar 2026', 'Rubber Chemical & Petrochemical Skills Development Council (RCPSDC)', 'Rubber, Chemical & Petro Chemical Skills Development Council', 'Manufacturing/process', 'Chemical Plant Sr. Operator(level-4), Chemical Plant Supervisor (level-5), Chemical Plant Manager(level-6)', 'General Qualification', 'N.A.', '{"Theory":"150","Practical":"210","EmployabilitySkills":"60","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "7", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_13_51.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
