INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-02-RI-03326-2024-V1-RCPSDC', 'Parali Brick Fuel Machine Operator', 'rubber-industry', 'Rubber Industry', 2.0, 'Parali Brick Fuel Machine Operator is responsible for assisting in the process of converting agricultural stubble (parali) into briquettes. The role involves operating and maintaining stubble briquetting machine, handling chemicals, binders and nanomaterials (as per requirement) and ensuring the quality of the final product followed by transporting it to relevant industry. The Parali Brick Fuel Machine Operator will follow safety protocols to ensure a safe and efficient production environment. This role plays a crucial part in reducing stubble burning and promoting sustainable energy practices.', 330, 330, '201–400', 'Version', '22 Oct 2024', '22 Oct 2026', 'Rubber Chemical & Petrochemical Skills Development Council (RCPSDC)', 'Rubber, Chemical and Petrochemical Skill Development Council', 'Waste Management, Storage and Handling, Chemical Application, Manufacturing/process', 'Parali (Stubble) Briquetting Supervisor', 'General Qualification', 'N.A.', '{"Theory":"85","Practical":"185","EmployabilitySkills":"30","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "31", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_13_51.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-RI-03677-2025-V1-RSDC', 'Jr. Technician - Rubberwood Seasoning and Chemical Treatment (Lightwood Furniture)', 'rubber-industry', 'Rubber Industry', 3.0, 'The individual working will be preparing the rubberwood for its use in making lightwood furniture. The person will be responsible for pre-seasoning, chemical treatment, and post-seasoning of rubberwood followed by proper handling and packing process using suitable methods and techniques.', 360, 360, '201–400', 'Version', '18 Feb 2025', '18 Feb 2028', 'Rubber Chemical & Petrochemical Skills Development Council (RCPSDC)', 'Rubber, Chemical and Petrochemical Skill Development Council', 'Chemical Treatment, Production - Rubber Wood, Storage and Handling', 'Technician – Rubberwood Seasoning and Chemical Treatment (Lightwood Furniture)', 'General Qualification', 'N.A.', '{"Theory":"110","Practical":"220","EmployabilitySkills":"30","OJT_Mandatory":"00"}', false, '{}'::text[], '{"source_row": "32", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_13_51.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-RI-03675-2025-V1-RSDC', 'Chemical Safety Supervisor', 'rubber-industry', 'Rubber Industry', 5.0, 'The Chemical Safety Supervisor is responsible for conducting chemical risk assessment followed by
 developing and implementing a safety program. The person is also responsible for conducting safety
 audits and maintaining the related documents as well as performing accident investigation and suggesting
 preventive measures.', 540, 540, '401–600', 'Version', '18 Feb 2025', '18 Feb 2028', 'Rubber Chemical & Petrochemical Skills Development Council (RCPSDC)', 'Rubber, Chemical and Petrochemical Skill Development Council', 'Chemical Safety, Testing and Quality Control', 'Chemical Safety Manager', 'General Qualification', 'N.A.', '{"Theory":"130","Practical":"290","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "33", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_13_51.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-4.5-LT-04165-2025-V1-MSMETC', 'Jr. Technical Supervisor – Sports Shoe Manufacturing', 'rubber-industry', 'Rubber Industry', 4.5, '•	Qualified learners who attain this qualification are capable in Shoe Design & Development, Materials Science, Manufacturing Techniques, Industrial Engineering, Quality Assurance & Control, Production Management, Retailing, Merchandising & Supply Chain, and Sustainability within the fields of Sports Footwear and Allied sectors.
•	Learner can get a job in Design & Development, Production, Quality, Productivity, Costing & Cost Control, Marketing, Retailing & Merchandising fields of Sports Footwear sector and also can able to become an entrepreneur.', 1200, 1200, '1001–1200', 'Version', '08 May 2025', '08 May 2028', 'MSME Technology Centre, Ministry of Micro Small And Medium Enterprises, New Delhi', 'MSME TECHNOLOGY CENTRE', 'Shoemaker', 'Technical Supervisor– Sports Shoe Manufacturing', 'Multi-Skill Qualification', 'N.A.', '{"Theory":"360","Practical":"600","EmployabilitySkills":"120","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "34", "qualification_type": "Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_13_51.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
