INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-SP-00926-2023-V1-SPEFLSC', 'Gym Equipment Service Technician', 'sports-physical-education-fitness-leisure', 'Sports, Physical Education, Fitness & Leisure', 4.0, 'Gym equipment service technician is the advance support professionals to the field technicians who cater to the day-to-day gym equipment repair requirement of various customers. Individuals in this role defines work processes and provides regular advice and guidance. They are also required to perform advance and complex equipment related issues including installing, configuring, diagnosing, repairing, and upgrading all organizational hardware and equipment ensuring optimal customer satisfaction. They also troubleshoot problem areas in a timely and accurate fashion and provide end-user training and assistance where required.', 450, 450, '401–600', 'Version', '31 Aug 2023', '31 Aug 2026', 'Sports, Physical Education, Fitness and Leisure Skills Council (SPEFL)', 'Sports, Physical Education, Fitness and Leisure Sector Skill Council (SPEFL-SC)
207, DLF Galleria Mall, Mayur Vihar Extension, Delhi- 110091', 'Gym Equipment Service', 'Level-5 (Vertical)- Gym Equipment Service Supervisor', 'General Qualification', 'N.A.', '{"Theory":"90","Practical":"210","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "13", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_41.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
