INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-SP-00920-2023-V1-SPEFLSC', 'Yoga Trainer-Sports', 'sports-physical-education-fitness-leisure', 'Sports, Physical Education, Fitness & Leisure', 4.0, 'A yoga trainer is a professional who works with athletes/client to help them improve their physical performance and mental well-being through the practice of basic yoga. The individual, uses yoga to create a positive impact on their performance by reducing stress, improving focus and concentration, and promoting a sense of calm and relaxation.', 450, 450, '401–600', 'Version', '31 Aug 2023', '31 Aug 2026', 'Sports, Physical Education, Fitness and Leisure Skills Council (SPEFL)', 'Sports, Physical Education, Fitness and Leisure Sector Skill Council (SPEFL-SC)
