INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-SP-00679-2023-V1.1-SPEFLSC', 'Advance Lifeguard Open-Water', 'sports-physical-education-fitness-leisure', 'Sports, Physical Education, Fitness & Leisure', 5.0, 'Advance lifeguard - open water works at lakes, rivers, beach and any open water body facility to rescue swimmers from drowning and any other aquatic emergencies. He/She in this role would observe and supervise waterfront and swimming areas to prevent accidents. He/She should know about rescue techniques with and without equipment in open water, navigate water-crafts and follow instructions. The responsibilities also include making swimmers aware of dangerous situations.', 570, 570, '401–600', 'Version', '30 Jun 2022', '30 Jun 2025', 'Sports, Physical Education, Fitness and Leisure Skills Council (SPEFL)', 'Sports, Physical Education, Fitness and Leisure Sector Skill Council (SPEFL-SC)
207, DLF Galleria Mall, Mayur Vihar Extension, Delhi- 110091', 'N/A', 'Level-6 (Vertical)- Beach Captain', 'General Qualification', 'N.A.', '{"Theory":"120","Practical":"210","EmployabilitySkills":"90","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "24", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_41.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
