INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-02-SP-02533-2024-V1-SPEFLSC', 'Essentials of Self-Defense', 'sports-physical-education-fitness-leisure', 'Sports, Physical Education, Fitness & Leisure', 2.0, 'Essentials of self-defense micro credential covers introduction to the self-defense and the basics of personal protection, including situational awareness, physical techniques for escaping grabs or attacks, and legal considerations. These programs emphasize empowerment, confidence-building, and effective strategies to mitigate threats and ensure personal safety in various environments. Participants gain practical skills and knowledge to navigate potentially dangerous situations with assertiveness and resilience.', 7, 7, '1–200', 'Version', '30 Apr 2024', '30 Apr 2027', 'Sports, Physical Education, Fitness and Leisure Skills Council (SPEFL)', 'Sports, Physical Education, Fitness and Leisure Sector Skill Council (SPEFL-SC) 207, DLF Galleria Mall, Mayur Vihar Extension, Delhi- 110091', 'Self-Defense', 'N.A', 'Micro Credentials', 'N.A.', '{"Theory":"1","Practical":"6.5","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "27", "qualification_type": "Micro Credentials", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_41.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-02-SP-02534-2024-V1-SPEFLSC', 'Fundamentals of Physical Fitness', 'sports-physical-education-fitness-leisure', 'Sports, Physical Education, Fitness & Leisure', 2.0, 'The "Fundamentals of Physical Fitness" micro-credential outlines essential core principles and practices vital for a successful career in the fitness industry. This comprehensive program equips learners with an in-depth overview of fitness, providing foundational knowledge on the importance of maintaining physical fitness, exploring various career pathways within the fitness sector, and understanding key aspects of effective fitness training. By completing this micro-credential, participants will be well-prepared to embark on a rewarding career in fitness, armed with the essential skills and knowledge required to promote health and wellness effectively', 15, 15, '1–200', 'Version', '30 Apr 2024', '30 Apr 2027', 'Sports, Physical Education, Fitness and Leisure Skills Council (SPEFL)', 'Sports, Physical Education, Fitness and Leisure Sector Skill Council (SPEFL-SC), 207, DLF Galleria Mall, Mayur Vihar Extension, Delhi- 110091', 'Sports Coaching', 'N.A', 'Micro Credentials', 'N.A.', '{"Theory":"5","Practical":"10","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "28", "qualification_type": "Micro Credentials", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_41.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-02-SP-02535-2024-V1-SPEFLSC', 'Fundamentals of Special Population Fitness', 'sports-physical-education-fitness-leisure', 'Sports, Physical Education, Fitness & Leisure', 2.0, 'The "Fundamentals of Special Population Fitness" micro-credential outlines essential principles and practices vital for a successful career in the fitness industry, specifically focusing on special populations. This micro credential equips learners with an overview of fitness tailored for individuals with unique health conditions, disabilities, or specific needs. It provides foundational knowledge on the importance of maintaining physical fitness within these populations, exploring various career pathways within the fitness sector, and understanding key aspects of effective fitness training for special populations.', 15, 15, '1–200', 'Version', '30 Apr 2024', '30 Apr 2027', 'Sports, Physical Education, Fitness and Leisure Skills Council (SPEFL)', 'Sports, Physical Education, Fitness and Leisure Sector Skill Council (SPEFL-SC), 207, DLF Galleria Mall, Mayur Vihar Extension, Delhi- 110091', 'Sports Coaching', 'N.A', 'Micro Credentials', 'N.A.', '{"Theory":"5","Practical":"10","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "29", "qualification_type": "Micro Credentials", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_41.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_not