INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-03-SP-02537-2024-V1-SPEFLSC', 'Fundamentals of Sports Injury Prevention & First Aid', 'sports-physical-education-fitness-leisure', 'Sports, Physical Education, Fitness & Leisure', 3.0, 'The "Fundamentals of Sports Injury Prevention & First Aid" micro-credential outlines essential principles and practices vital for promoting safety and well-being in sports and physical activities. This micro-credential equips learners with an overview of injury prevention strategies, first aid techniques, and emergency response protocols specific to sports-related injuries. It provides foundational knowledge on recognizing and mitigating potential risks, administering immediate care in the event of an injury, and understanding key aspects of effective sports injury prevention and first aid.', 30, 30, '1–200', 'Version', '30 Apr 2024', '30 Apr 2027', 'Sports, Physical Education, Fitness and Leisure Skills Council (SPEFL)', 'Sports, Physical Education, Fitness and Leisure Sector Skill Council (SPEFL-SC), 207, DLF Galleria Mall, Mayur Vihar Extension, Delhi- 110091', 'Sports Coaching', 'N.A', 'Micro Credentials', 'N.A.', '{"Theory":"10","Practical":"20","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "30", "qualification_type": "Micro Credentials", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_41.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-02-SP-02536-2024-V1-SPEFLSC', 'Fundamentals of Strength and Conditioning', 'sports-physical-education-fitness-leisure', 'Sports, Physical Education, Fitness & Leisure', 2.0, 'The "Fundamentals of Strength and Conditioning" micro-credential outlines essential principles and practices vital for a successful career in the fitness industry, specifically focusing on strength and conditioning. This micro-credential equips learners with an overview of fitness tailored for enhancing athletic performance, improving physical strength, and conditioning. It provides foundational knowledge on the importance of maintaining physical fitness, exploring various career pathways within the fitness sector, and understanding key aspects of effective strength and conditioning training.', 10, 5, '1–200', 'Version', '30 Apr 2024', '30 Apr 2027', 'Sports, Physical Education, Fitness and Leisure Skills Council (SPEFL)', 'Sports, Physical Education, Fitness and Leisure Sector Skill Council (SPEFL-SC), 207, DLF Galleria Mall, Mayur Vihar Extension, Delhi- 110091', 'Sports Coaching', 'N.A', 'Micro Credentials', 'N.A.', '{"Theory":"5","Practical":"10","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "31", "qualification_type": "Micro Credentials", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_41.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-02-SP-02538-2024-V1-SPEFLSC', 'Fundamentals of Yoga', 'sports-physical-education-fitness-leisure', 'Sports, Physical Education, Fitness & Leisure', 2.0, 'The "Fundamentals of Yoga" micro-credential outlines essential principles and practices vital for a successful career in the fitness and wellness industry, specifically focusing on yoga. This micro-credential equips learners with an overview of yoga tailored for enhancing physical and mental well-being, improving flexibility, balance, and mindfulness.', 15, 15, '1–200', 'Version', '30 Apr 2024', '30 Apr 2027', 'Sports, Physical Education, Fitness and Leisure Skills Council (SPEFL)', 'Sports, Physical Education, Fitness and Leisure Sector Skill Council (SPEFL-SC), 207, DLF Galleria Mall, Mayur Vihar Extension, Delhi- 110091', 'Sports Coaching', 'N.A', 'Micro Credentials', 'N.A.', '{"Theory":"5","Practical":"10","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "32", "qualification_type": "Micro Credentials", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_41.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-SP-02948-2024-V2-SPEFLSC', 'General Fitness Trainer', 'sports-physical-education-fitness-leisure', 'Sports, Physical Education, Fitness & Leisure', 4.0, 'A General Fitness Trainer provides support and guidance during workout sessions. They oversee the gym floor, respond to inquiries, and ensure that all equipment is used safely and maintained properly.', 450, 450, '401–600', 'Version', '27 May 2021', '27 Aug 2027', 'Sports, Physical Education, Fitness and Leisure Skills Council (SPEFL)', 'Sports, Physical Education, Fitness & Leisure Skill Council', 'Sports Coaching', 'Level 5- Personal Fitness Trainer, Group Fitness Trainer', 'General Qualification', 'N.A.', '{"Theory":"90","Practical":"180","EmployabilitySkills":"60","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "33", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_41.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-SP-02949-2024-V2-SPEFLSC', 'Personal Fitness Trainer', 'sports-physical-education-fitness-leisure', 'Sports, Physical Education, Fitness & Leisure', 5.0, 'The Personal Fitness Trainer is responsible for assessing the fitness levels, planning personalized workout sessions, and monitoring progress to meet the desired fitness goals of the client.', 600, 600, '401–600', 'Version', '27 Apr 2021', '27 Aug 2027', 'Sports, Physical Education, Fitness and Leisure Skills Council (SPEFL)', 'SPEFL-SC', 'Sports Coaching', 'Level 5.5 Strength and Conditioning Coach', 'General Qualification', 'N.A.', '{"Theory":"150","Practical":"240","EmployabilitySkills":"90","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "34", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_41.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-SP-02950-2024-V2-SPEFLSC', 'Group Fitness Trainer', 'sports-physical-education-fitness-leisure', 'Sports, Physical Education, Fitness & Leisure', 5.0, 'The Group Fitness Trainer is responsible for leading and instructing fitness classes for groups of individuals in various exercise settings, such as gyms, fitness centers, studios, or outdoor venues and ensures that the sessions are engaging, outcome-driven and safe. The individual helps everyone in the group develop various aspects of fitness and wellness.', 570, 570, '401–600', 'Version', '27 May 2021', '27 Aug 2027', 'Sports, Physical Education, Fitness and Leisure Skills Council (SPEFL)', 'SPEFL-SC', 'Sports Coaching', 'Level 5.5 Strength and Conditioning Coach', 'General Qualification', 'N.A.', '{"Theory":"120","Practical":"240","EmployabilitySkills":"90","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "35", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_41.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
