INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-06-SP-02952-2024-V2-SPEFLSC', 'Fitness Centre Head', 'sports-physical-education-fitness-leisure', 'Sports, Physical Education, Fitness & Leisure', 6.0, 'A fitness Centre head oversees the daily operations of the fitness Centre. The person is in charge of marketing, maintaining profitability, managing staff and ensuring customer satisfaction.', 870, 870, '801–1000', 'Version', '27 Apr 2021', '27 Aug 2027', 'Sports, Physical Education, Fitness and Leisure Skills Council (SPEFL)', 'SPEFL-SC', 'Sports Coaching', 'Regional Manager', 'General Qualification', 'N.A.', '{"Theory":"180","Practical":"390","EmployabilitySkills":"120","OJT_Mandatory":"180"}', false, '{}'::text[], '{"source_row": "37", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_41.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-SP-04292-2025-V1-GU', 'Water Sports Trainer', 'sports-physical-education-fitness-leisure', 'Sports, Physical Education, Fitness & Leisure', 4.0, 'Understand the concept of water adventure sports, Classify the water sports, Understand the type of water for water sports activities, Demonstrate proficiency in imparting training in water sports techniques.
Demonstrate proficiency in teaching swimming techniques, including various strokes such as freestyle, breaststroke, backstroke, and butterfly.', 480, 780, '601–800', 'Version', '08 May 2025', '08 May 2028', 'Ganpat University', 'Ganpat University', 'Water Sports Trainer', 'Water Sports Instructor/Coach Level 5.0', 'General Qualification,Multi-Skill Qualification', 'N.A.', '{"Theory":"90","Practical":"300","EmployabilitySkills":"30","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "38", "qualification_type": "General Qualification,Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_41.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
