Cloud RAN', 'Future Skills Qualification', 'N.A.', '{"Theory":"180","Practical":"270","EmployabilitySkills":"60","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "3", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_49.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
