INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-TL-01994-2024-V1-TSSC', 'In-Building Wireless Solution (IBS) Technician', 'telecom', 'Telecom', 4.0, 'The individual at work is responsible for inspecting site readiness and conduct due diligence for survey, planning and installing inbuilding wireless solutions as per the client requirement.  They are also responsible for maintaining and troubleshooting the installed components in the commercial establishments as per the organization’s standards and procedures.', 420, 420, '401–600', 'Version', '31 Jan 2024', '31 Jan 2027', 'Telecom Sector Skill Council (TSSC)', 'Telecom Sector Skill Council', 'In-Building Solution', 'Vertical progression 
