INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-TL-02635-2024-V1-TSSC', 'Drone Data Processor', 'telecom', 'Telecom', 5.0, 'The individual of this job role is responsible for data extraction and collection, encompassing images, videos, thermal, infrared, radio frequency, lidar, and radar inputs, with a focus on generating precise 3D Point Clouds in. xyz and. las formats. The individual is also responsible for Utilizing both local computer and Cloud-based software, the role involves adept data processing, followed by insightful analysis and projection for informed decision-making.', 540, 540, '401–600', 'Version', '30 May 2024', '30 May 2027', 'Telecom Sector Skill Council (TSSC)', 'Telecom Sector Skill Council', 'N/A', 'Drone Telecom Surveyor', 'Apprenticeship Qualification,Future Skills Qualification', 'N.A.', '{"Theory":"90","Practical":"210","EmployabilitySkills":"60","OJT_Mandatory":"180"}', false, '{}'::text[], '{"source_row": "18", "qualification_type": "Apprenticeship Qualification,Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_49.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-03-TL-02998-2024-V1-TSSC', 'Height & Rescue Training (HART)', 'telecom', 'Telecom', 3.0, 'This role involves creating an engaging and informative learning environment, assessing trainee understanding, and ensuring compliance with national and global legislation regarding WAH activities. The trainer will cover various topics such as hazard identification, fall protection systems, equipment inspection, and emergency procedures.', 15, 15, '1–200', 'Version', '27 Aug 2024', '27 Aug 2027', 'Telecom Sector Skill Council (TSSC)', 'Telecom Sector Skill Council', 'Operations and Maintenance - Passive Infrastructure', 'Advanced Height & Rescue Training (HART)', 'Cross Sectoral Qualification,General Qualification,Micro Credentials', 'N.A.', '{"Theory":"5","Practical":"10","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "19", "qualification_type": "Cross Sectoral Qualification,General Qualification,Micro Credentials", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_49.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-04-TL-02986-2024-V1-TSSC', 'Rope Operations, Tactics and Rescue (ROTAR)', 'telecom', 'Telecom', 4.0, 'The Rope Access Technician is aimed at those who have required the skill and knowledge to gain access to difficult areas of height and confined space using ropes and associated equipment. This role involves performing a wide range of repair, maintenance, and inspection tasks across various industries, including telecommunications, offshore oil and gas, renewable energy, power and petrochemical, shipping, and harbors.', 60, 60, '1–200', 'Version', '27 Aug 2024', '27 Aug 2027', 'Telecom Sector Skill Council (TSSC)', 'Telecom Sector Skill Council', 'Operations and Maintenance - Passive Infrastructure', 'Advanced Rope Operations Tactics & Rescue (Level-4.5)', 'Cross Sectoral Qualification,General Qualification,National Occupational Standard,Upskilling Qualification', 'N.A.', '{"Theory":"12","Practical":"48","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "20", "qualification_type": "Cross Sectoral Qualification,General Qualification,National Occupational Standard,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_49.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-04-TL-03344-2024-V1-TSSC', 'Wecare- Electrical Safety (Telecom Equipment)', 'telecom', 'Telecom', 4.0, 'The individual in this job role is responsible for ensuring electrical safety across all telecommunications equipment installations and operations. This role involves developing, implementing, and overseeing electrical safety policies, standards, and procedures specific to tower-based telecommunications installations.', 7, 7, '1–200', 'Version', '22 Oct 2024', '22 Oct 2027', 'Telecom Sector Skill Council (TSSC)', 'Telecom Sector Skill Council', 'Operations and Maintenance - Passive Infrastructure', 'N.A', 'General Qualification,OEM Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"7.50","Practical":"00.00","EmployabilitySkills":"00.00","OJT_Mandatory":"00.00"}', false, '{}'::text[], '{"source_row": "21", "qualification_type": "General Qualification,OEM Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_49.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-4.5-TL-02953-2024-V1-TSSC', 'Assembly Process Technician – Wafer Testing', 'telecom', 'Telecom', 4.5, 'The individual for this job role is responsible for performing various tasks associated with the testing and quality control of semiconductor wafers used in telecom applications. They are also responsible to work with sophisticated testing equipment and follow established procedures to ensure the integrity and performance of the wafers. In addition, the individual also document test results, identify any defects or issues, and collaborate with engineering teams to implement corrective actions. The individual for this job role requires a keen attention to detail and a strong commitment to maintaining high standards of quality.', 450, 450, '401–600', 'Version', '27 Aug 2024', '27 Aug 2025', 'Telecom Sector Skill Council (TSSC)', 'Telecom Sector Skill Council', 'Semiconductor - M&P', 'Assembly Process Sr. Technician- Wafer Thinning & Lapping (Level-5)', 'Apprenticeship Qualification,Future Skills Qualification', 'N.A.', '{"Theory":"60","Practical":"180","EmployabilitySkills":"60","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "22", "qualification_type": "Apprenticeship Qualification,Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_49.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-06-TL-02958-2024-V1-TSSC', 'Reliability & Quality Control Manager', 'telecom', 'Telecom', 6.0, 'The individual for this job role is responsible to evaluate semiconductor products to ensure long-term reliability and consistent quality. The individual is also responsible to conduct stress tests, analyzes failure points, and implements quality control measures. In addition, he also work closely with design and manufacturing teams to recommend improvements that enhance product robustness and reduce defects.', 660, 660, '601–800', 'Version', '27 Aug 2024', '27 Aug 2027', 'Telecom Sector Skill Council (TSSC)', 'Telecom Sector Skill Council', 'Semiconductor – M&P', 'Lead Manager-Packaging (Level-6.5)', 'Apprenticeship Qualification,Future Skills Qualification', 'N.A.', '{"Theory":"180","Practical":"210","EmployabilitySkills":"90","OJT_Mandatory":"180"}', false, '{}'::text[], '{"source_row": "23", "qualification_type": "Apprenticeship Qualification,Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_49.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-06-TL-02957-2024-V1-TSSC', 'Substrate Design and Process Manager', 'telecom', 'Telecom', 6.0, 'The individual for this job role is responsible to develop the structural blueprint for semiconductor substrates. The individual also requires to design substrate layouts that meet electrical and thermal performance criteria while ensuring manufacturability. In addition, the individual also select materials, conducts simulations, collaborates with fabrication teams, and iterates designs based on testing feedback.', 600, 600, '401–600', 'Version', '27 Aug 2024', '27 Aug 2027', 'Telecom Sector Skill Council (TSSC)', 'Telecom Sector Skill Council', 'Semiconductor - M&P', 'Lead Manager -Packaging (6.5)', 'Apprenticeship Qualification,Future Skills Qualification', 'N.A.', '{"Theory":"150","Practical":"180","EmployabilitySkills":"90","OJT_Mandatory":"180"}', false, '{}'::text[], '{"source_row": "24", "qualification_type": "Apprenticeship Qualification,Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_49.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-5.5-TL-02956-2024-V1-TSSC', 'Assembly Process Supervisor- Wafer Dicing', 'telecom', 'Telecom', 5.5, 'The individual for this job role manages the dicing of semiconductor wafers into individual chips. The individual is also optimize dicing processes, selecting appropriate cutting tools, and ensuring the minimization of chip damage. In addition, the individual also analyzes yield data, collaborates with cross-functional teams to improve dicing strategies, and contributes to equipment maintenance protocols.', 570, 570, '401–600', 'Version', '27 Aug 2024', '27 Aug 2025', 'Telecom Sector Skill Council (TSSC)', 'Telecom Sector Skill Council', 'Semiconductor - M&P', 'Substrate Design and Process Manager (Level-6)', 'Apprenticeship Qualification,Future Skills Qualification', 'N.A.', '{"Theory":"150","Practical":"180","EmployabilitySkills":"90","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "25", "qualification_type": "Apprenticeship Qualification,Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_49.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-TL-02955-2024-V1-TSSC', 'Assembly Process Sr. Technician – Laser Marking', 'telecom', 'Telecom', 5.0, 'The individual for this job role is tasked with operating laser machines to accurately etch identification marks on semiconductor wafers. The individual is also responsible to set up laser parameters, ensuring the precision of markings, and maintaining equipment. In addition, he also need to inspect marked wafers for quality and adherence to specifications, documenting the process and outcomes.', 540, 540, '401–600', 'Version', '27 Aug 2024', '27 Aug 2025', 'Telecom Sector Skill Council (TSSC)', 'Telecom Sector Skill Council', 'Semiconductor - M&P', 'Assembly Process Supervisor – Wafer Dicing (Level-5.5)', 'Apprenticeship Qualification,Future Skills Qualification', 'N.A.', '{"Theory":"120","Practical":"210","EmployabilitySkills":"60","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "26", "qualification_type": "Apprenticeship Qualification,Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_49.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-TL-02954-2024-V1-TSSC', 'Assembly Process Sr. Technician – Wafer Thinning & Lapping', 'telecom', 'Telecom', 5.0, 'The individual for this job role is responsible for executing critical processes within the semiconductor assembly line, demonstrating a strong grasp of wafer thinning and lapping techniques. The individual is also responsible to adhere safety protocols to ensure a safe work environment. In addition, they need to maintain high-quality standards through meticulous attention to detail, operate specialized equipment effectively, and troubleshoot common issues independently, seeking support for complex ones. The individual also stays updated on the latest advancements and emerging technologies in the semiconductor industry is essential.', 540, 540, '401–600', 'Version', '27 Aug 2024', '27 Aug 2025', 'Telecom Sector Skill Council (TSSC)', 'Telecom Sector Skill Council', 'Semiconductor - M&P', 'Assembly Process Supervisor- Wafer Dicing (Level-5.5)', 'Apprenticeship Qualification,Future Skills Qualification', 'N.A.', '{"Theory":"90","Practical":"210","EmployabilitySkills":"60","OJT_Mandatory":"180"}', false, '{}'::text[], '{"source_row": "27", "qualification_type": "Apprenticeship Qualification,Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_49.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-TL-04078-2025-V2-TSSC', 'Call Center Executive', 'telecom', 'Telecom', 3.0, 'A Call Center Executive is responsible for addressing customer queries, requests, and complaints through walk-in interactions and telephonic support, ensuring timely resolution. The role also involves promoting and selling the organization''s products and services while maintaining a customer-centric approach.', 420, 420, '401–600', 'Version', '08 May 2025', '30 Apr 2028', 'Telecom Sector Skill Council (TSSC)', 'Telecom Sector Skill Council', 'Customer Service – Service Segment', 'Team Leader - Call Center (Level 4)', 'Apprenticeship Qualification,General Qualification', 'N.A.', '{"Theory":"90","Practical":"180","EmployabilitySkills":"30","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "28", "qualification_type": "Apprenticeship Qualification,General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_49.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-TL-04068-2025-V2-TSSC', 'Broadband Technician', 'telecom', 'Telecom', 4.0, 'A Broadband Technician installs, configures, and tests CPE (modems, routers, switches) for broadband access. The individual ensures seamless connectivity between CPE and end-user devices (CPU, laptop, tablets, Smart/IP TV) at customer premises and troubleshoot connectivity, cable, and equipment issues in coordination with the NOC.', 450, 450, '401–600', 'Version', '08 May 2025', '30 Apr 2028', 'Telecom Sector Skill Council (TSSC)', 'Telecom Sector Skill Council', 'Customer Service - Passive Infrastructure', 'Broadband Supervisor (NSQF Level 5)', 'Apprenticeship Qualification,General Qualification', 'N.A.', '{"Theory":"120","Practical":"180","EmployabilitySkills":"30","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "29", "qualification_type": "Apprenticeship Qualification,General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_49.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-TL-04073-2025-V2-TSSC', 'Android Application Technician – Telecom Devices', 'telecom', 'Telecom', 4.0, 'An Android Application Technician – Telecom Devices is responsible for assisting in the setup, configuration, and basic implementation of Android-based applications on telecom devices. The individual assists in activities such as preparing the development environment, configuring user interfaces using standard layouts, application testing, and providing technical assistance during application deployment. The role focuses on implementing and maintaining existing application components under supervision.', 510, 510, '401–600', 'Version', '08 May 2025', '30 Apr 2028', 'Telecom Sector Skill Council (TSSC)', 'Telecom Sector Skill Council', 'Terminal Equipment Application Developer', 'Android Developer Lead (NSQF Level 5)', 'Apprenticeship Qualification,Future Skills Qualification', 'N.A.', '{"Theory":"120","Practical":"210","EmployabilitySkills":"30","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "30", "qualification_type": "Apprenticeship Qualification,Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_49.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-TL-04070-2025-V2-TSSC', 'In-Store Promoter', 'telecom', 'Telecom', 3.0, 'An In-Store Promoter is responsible for effectively demonstrating and showcasing products using the Features, Advantages, and Benefits (FAB) approach. The individual engages customers by encouraging hands-on interaction with displayed products and addressing inquiries about product specifications and services.', 420, 420, '401–600', 'Version', '08 May 2025', '30 Apr 2028', 'Telecom Sector Skill Council (TSSC)', 'Telecom Sector Skill Council', 'Sales and Distribution - Handset Segment', 'Team Leader- Store (NSQF Level 4)', 'Apprenticeship Qualification,General Qualification', 'N.A.', '{"Theory":"120","Practical":"150","EmployabilitySkills":"30","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "31", "qualification_type": "Apprenticeship Qualification,General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_49.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-TL-04076-2025-V2-TSSC', 'Optical Fiber Splicer', 'telecom', 'Telecom', 3.0, 'An Optical Fiber Splicer is responsible for splicing optical fibers with precision and testing their effectiveness using advanced tools. The individual is required to ensure high-quality connections and maintain accurate records for future reference.', 390, 390, '201–400', 'Version', '08 May 2025', '30 Apr 2028', 'Telecom Sector Skill Council (TSSC)', 'Telecom Sector Skill Council', 'Operations and Maintenance - Passive Infrastructure', 'Optical Fiber Technician (level 4)', 'Apprenticeship Qualification,General Qualification', 'N.A.', '{"Theory":"90","Practical":"120","EmployabilitySkills":"30","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "32", "qualification_type": "Apprenticeship Qualification,General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_49.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-TL-04077-2025-V2-TSSC', 'Optical Fiber Technician', 'telecom', 'Telecom', 4.0, 'An Optical Fiber Technician oversees the installation and commissioning of Optical Fiber Cables (OFCs) and ensures network reliability through proactive maintenance and timely fault rectification. The individual’s responsibilities include periodic preventive maintenance, condition-based repairs, and effective fault management to maintain optimal uptime and service quality.', 480, 480, '401–600', 'Version', '08 May 2025', '30 Apr 2028', 'Telecom Sector Skill Council (TSSC)', 'Telecom Sector Skill Council', 'Operations and Maintenance - Passive Infrastructure', 'Cluster In-Charge (NSQF Level 5)', 'Apprenticeship Qualification,General Qualification', 'N.A.', '{"Theory":"90","Practical":"210","EmployabilitySkills":"30","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "33", "qualification_type": "Apprenticeship Qualification,General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_49.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-TL-04069-2025-V2-TSSC', 'Distributor Sales Representative', 'telecom', 'Telecom', 3.0, 'The individual in this role is responsible for achieving sales targets by selling mobile phones and related accessories, expanding distribution networks, and ensuring retailer satisfaction. The role involves analyzing market trends, addressing retailer queries, managing cash transactions, and traveling extensively as per organizational requirements.', 420, 420, '401–600', 'Version', '08 May 2025', '30 Apr 2028', 'Telecom Sector Skill Council (TSSC)', 'Telecom Sector Skill Council', 'Sales and Distribution - Handset Segment', 'Territory Sales In-charge (Level 4)', 'Apprenticeship Qualification,General Qualification', 'N.A.', '{"Theory":"120","Practical":"150","EmployabilitySkills":"30","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "34", "qualification_type": "Apprenticeship Qualification,General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_49.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-TL-04081-2025-V2-TSSC', 'Telecom Technician - IoT Devices/Systems', 'telecom', 'Telecom', 4.0, 'A Telecom Technician – IoT Devices/Systems is responsible for the on-site installation, configuration, and maintenance of IoT devices (nodes). This includes setting up communication links between nodes and controllers (gateways) and ensuring connectivity to central servers or devices via external communication networks such as WiFi, 4G, or 5G on GSM/CDMA. The individual is also responsible for performing first-level Diagnostics and Investigation (DI) or Damage Recovery (DR).', 510, 510, '401–600', 'Version', '08 May 2025', '30 Apr 2028', 'Telecom Sector Skill Council (TSSC)', 'Telecom Sector Skill Council', 'Network Operation and Maintenance', 'Internet of Things (IOT) – Solution Architecture (End Point Solution) (NSQF Level 5)', 'Apprenticeship Qualification,Future Skills Qualification', 'N.A.', '{"Theory":"120","Practical":"210","EmployabilitySkills":"30","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "35", "qualification_type": "Apprenticeship Qualification,Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_49.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-TL-04084-2025-V2-TSSC', 'Infrastructure Technician-5G Networks', 'telecom', 'Telecom', 4.0, 'An Infrastructure Technician - 5G Networks is responsible for installing the passive infrastructure equipment at 5G network infrastructure sites to ensure power supply to 5G network and transmission equipment. The individual is also responsible for maintaining the passive infrastructure equipment. The person may also carry out regular repair and maintenance of the 5G network infrastructure.', 510, 510, '401–600', 'Version', '08 May 2025', '30 Apr 2028', 'Telecom Sector Skill Council (TSSC)', 'Telecom Sector Skill Council', 'Network (Passive) Installation', 'Cluster In-charge (NSQF Level 5)', 'Apprenticeship Qualification,Future Skills Qualification', 'N.A.', '{"Theory":"120","Practical":"180","EmployabilitySkills":"30","OJT_Mandatory":"180"}', false, '{}'::text[], '{"source_row": "36", "qualification_type": "Apprenticeship Qualification,Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_49.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-TL-04071-2025-V2-TSSC', 'Telecom Customer Care Executive - Repair Center', 'telecom', 'Telecom', 4.0, 'A Telecom Customer Care Executive – Repair Center is responsible for providing in-person customer support, addressing queries, processing service requests, and resolving complaints efficiently. The role involves performing basic troubleshooting of mobile handsets and accessories, coordinating with front-end support teams for issue resolution, and escalating complex cases requiring back-end intervention.', 450, 450, '401–600', 'Version', '08 May 2025', '30 Apr 2028', 'Telecom Sector Skill Council (TSSC)', 'Telecom Sector Skill Council', 'Sales and Distribution - Handset Segment', 'Telecom Customer Care In-charge (NSQF Level 4.5)', 'Apprenticeship Qualification,General Qualification', 'N.A.', '{"Theory":"120","Practical":"150","EmployabilitySkills":"60","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "37", "qualification_type": "Apprenticeship Qualification,General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_49.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-TL-04079-2025-V2-TSSC', 'Field Sales Executive', 'telecom', 'Telecom', 3.0, 'A Field Sales Executive is responsible for visiting customers to deliver prepaid telecom products and services to retailers. The individual’s key responsibilities include achieving monthly revenue targets, expanding distribution networks, ensuring compliance in new customer enrollment, and growing the customer base. Additionally, the role may involve selling broadband subscriptions.', 420, 420, '401–600', 'Version', '08 May 2025', '30 Apr 2028', 'Telecom Sector Skill Council (TSSC)', 'Telecom Sector Skill Council', 'Sales and Distribution – Service Segment', 'Territory Sales In-charge (Level 4)', 'Apprenticeship Qualification,General Qualification', 'N.A.', '{"Theory":"120","Practical":"150","EmployabilitySkills":"30","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "38", "qualification_type": "Apprenticeship Qualification,General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_49.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-TL-04075-2025-V2-TSSC', 'Telecom Tower Site Maintenance Technician', 'telecom', 'Telecom', 4.0, 'A Telecom Tower Site Maintenance Technician is responsible for ensuring the continuous operation of the telecom tower site by performing Level-1 fault repairs, conducting corrective and preventive maintenance, and reporting issues to the supervisor. Additionally, the individual oversees energy and estate management at Level-1 and verify site assets.', 510, 510, '401–600', 'Version', '08 May 2025', '30 Apr 2028', 'Telecom Sector Skill Council (TSSC)', 'Telecom Sector Skill Council', 'Operations and Maintenance - Passive Infrastructure', 'Telecom Tower Site Maintenance Supervisor (NSQF Level 5)', 'Apprenticeship Qualification,Future Skills Qualification', 'N.A.', '{"Theory":"120","Practical":"210","EmployabilitySkills":"30","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "39", "qualification_type": "Apprenticeship Qualification,Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_49.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-TL-04074-2025-V2-TSSC', 'Telecom E-Waste Handler', 'telecom', 'Telecom', 4.0, 'A Telecom E-Waste Handler operates as a micro-entrepreneur, establishing and managing telecom e-waste collection and aggregation centers. They ensure safe handling, segregation, and secure transportation for further processing while promoting sustainable disposal practices. The individual collaborates with stakeholders and utilizes advanced technologies to enhance operational efficiency and regulatory compliance.', 420, 420, '401–600', 'Version', '08 May 2025', '30 Apr 2028', 'Telecom Sector Skill Council (TSSC)', 'Telecom Sector Skill Council', 'E-Waste Management', 'Telecom E-waste Facility In-charge (NSQF Level 5)', 'Apprenticeship Qualification,Future Skills Qualification', 'N.A.', '{"Theory":"90","Practical":"150","EmployabilitySkills":"30","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "40", "qualification_type": "Apprenticeship Qualification,Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_49.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-TL-04090-2025-V2-TSSC', 'Wireless Technician', 'telecom', 'Telecom', 4.0, 'A Wireless Technician is responsible for installing, configuring, and testing Wi-Fi backhaul equipment (5 GHz) and Wi-Fi access points (2.4 GHz) for broadband connectivity. The individual establishes and maintains backhaul connectivity between Wi-Fi nodes and access points across multiple sites. Additionally, the person performs basic troubleshooting to identify, localize, and rectify cable, connectivity, and equipment faults in coordination with the Network Operations Centre (NOC).', 510, 510, '401–600', 'Version', '08 May 2025', '30 Apr 2028', 'Telecom Sector Skill Council (TSSC)', 'Telecom Sector Skill Council', 'Operations and Maintenance - Passive Infrastructure', 'Senior Technician- Telecom Infrastructure (NSQF Level 4.5)', 'Apprenticeship Qualification,Future Skills Qualification', 'N.A.', '{"Theory":"120","Practical":"180","EmployabilitySkills":"60","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "41", "qualification_type": "Apprenticeship Qualification,Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_49.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-TL-04072-2025-V2-TSSC', 'Handheld Devices (Mobile & Accessories) Technician', 'telecom', 'Telecom', 4.0, 'A Handheld Devices (Mobile & Accessories) Technician is responsible for diagnosing and repairing hardware and software issues in mobile phones, tablets, laptops and mobile accessories. The individual also performs basic chip-level repairs and ensures device functionality, maintains quality standards, and adheres to the applicable safety and environmental protocols.', 480, 480, '401–600', 'Version', '08 May 2025', '30 Apr 2028', 'Telecom Sector Skill Council (TSSC)', 'Telecom Sector Skill Council', 'Customer Service - Handset Segment', 'Mobile Phone Repair Sr. Technician (NSQF Level 4.5)', 'Apprenticeship Qualification,General Qualification', 'N.A.', '{"Theory":"120","Practical":"210","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "42", "qualification_type": "Apprenticeship Qualification,General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_49.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-TL-04080-2025-V2-TSSC', 'Optical Network Terminal Technician', 'telecom', 'Telecom', 4.0, 'An Optical Network Terminal Technician is responsible for ensuring the continuous 24x7 operation of Optical Network Terminal (ONT) sites. The role involves performing routine maintenance, troubleshooting and repairing basic faults at ONT sites, promoting digital adoption among the local population, and delivering telecom services efficiently.', 510, 510, '401–600', 'Version', '08 May 2025', '30 Apr 2028', 'Telecom Sector Skill Council (TSSC)', 'Telecom Sector Skill Council', 'Network Operation and Maintenance', 'Cluster In-Charge  (NSQF Level 5)', 'Apprenticeship Qualification,Future Skills Qualification', 'N.A.', '{"Theory":"120","Practical":"210","EmployabilitySkills":"30","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "43", "qualification_type": "Apprenticeship Qualification,Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_49.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-TL-04085-2025-V2-TSSC', 'Telecom Field Operations Coordinator', 'telecom', 'Telecom', 5.0, 'A Telecom Field Operations Coordinator is responsible to ensure a fault-free network by coordinating with the Network Operations Centre (NOC) and the transmission team for periodic maintenance and fault resolution at radio locations. The individual is responsible for accepting new sites from the projects team, ensuring compliance with operational standards, and overseeing network upgrades and modifications. The role involves troubleshooting, preventive maintenance, and ensuring seamless execution of change activities to maintain network stability and performance.', 630, 630, '601–800', 'Version', '08 May 2025', '30 Apr 2028', 'Telecom Sector Skill Council (TSSC)', 'Telecom Sector Skill Council', 'Network Operation and Maintenance', 'Base Station Sub-System (BSS) Support Engineer (NSQF Level 6)', 'Apprenticeship Qualification,General Qualification', 'N.A.', '{"Theory":"180","Practical":"300","EmployabilitySkills":"30","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "44", "qualification_type": "Apprenticeship Qualification,General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_49.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-TL-04086-2025-V2-TSSC', 'Fiber Installation, Testing and Commissioning Technician', 'telecom', 'Telecom', 4.0, 'A Fiber Installation, Testing and Commissioning Technician is responsible for overseeing on-site optical fiber installation, including cable preparation, splicing, connectorization, testing, and troubleshooting while ensuring adherence to industry standards and safety protocols. The individual oversees technicians and splicers, ensuring timely project completion and maintaining high-quality service (QoS) standards.', 510, 510, '401–600', 'Version', '08 May 2025', '30 Apr 2028', 'Telecom Sector Skill Council (TSSC)', 'Telecom Sector Skill Council', 'Operations and Maintenance - Passive Infrastructure', 'Cluster In-Charge (NSQF Level 5)', 'Apprenticeship Qualification,General Qualification', 'N.A.', '{"Theory":"120","Practical":"180","EmployabilitySkills":"30","OJT_Mandatory":"180"}', false, '{}'::text[], '{"source_row": "45", "qualification_type": "Apprenticeship Qualification,General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_49.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-TL-04087-2025-V2-TSSC', 'Line Assembler - Telecom Products', 'telecom', 'Telecom', 3.0, 'A Line Assembler – Telecom Products is responsible for assembling handsets and telecom equipment at various stages of the production or assembly line, following predefined processes and industry standards. The role involves assembling or fitting pre-assembled electronic PCB boards, along with relevant mechanical and electrical components, onto a metal or plastic chassis within an enclosure. This includes attaching the top cover and securing all related hardware components, such as screws, using appropriate tools like electric or pneumatic screwdrivers. The individual is also responsible for following health and safety standards like ESD-safe procedures and applicable sustainability practices.', 450, 450, '401–600', 'Version', '08 May 2025', '30 Apr 2028', 'Telecom Sector Skill Council (TSSC)', 'Telecom Sector Skill Council', 'Communication Electronics', 'Production Line In-charge', 'Apprenticeship Qualification,General Qualification', 'N.A.', '{"Theory":"90","Practical":"180","EmployabilitySkills":"30","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "46", "qualification_type": "Apprenticeship Qualification,General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_49.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-TL-04083-2025-V2-TSSC', 'Fiber to-the Home (FTTH/X) Installer', 'telecom', 'Telecom', 3.0, 'A Fiber to-the Home (FTTH/X) Installer is responsible for implementing fiber optic cabling from the Optical Line Test Set (OLTS) drop point to the customer''s termination point, ensuring seamless last-mile connectivity. The job includes fiber splicing, termination at distribution points, and adherence to structured cabling standards, telecommunication regulations, and network safety norms.', 450, 450, '401–600', 'Version', '08 May 2025', '30 Apr 2028', 'Telecom Sector Skill Council (TSSC)', 'Telecom Sector Skill Council', 'Operations and Maintenance - Passive Infrastructure', 'Optical Fiber Technician (NSQF level 4)', 'Apprenticeship Qualification,General Qualification', 'N.A.', '{"Theory":"120","Practical":"180","EmployabilitySkills":"30","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "47", "qualification_type": "Apprenticeship Qualification,General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_49.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-TL-04091-2025-V2-TSSC', 'Telecom Rigger - 5G and Legacy Networks', 'telecom', 'Telecom', 3.0, 'A Telecom Rigger – 5G and Legacy Networks works under supervision to assist in the installation, maintenance, upgrading, and dismantling of telecom equipment on towers and other structures. The role involves using rigging techniques and installation skills to ensure the safe and efficient handling of telecom infrastructure, including cabling and related components.', 420, 420, '401–600', 'Version', '08 May 2025', '30 Apr 2028', 'Telecom Sector Skill Council (TSSC)', 'Telecom Sector Skill Council', 'Operations and Maintenance - Passive Infrastructure', 'Infrastructure Technician - 5G Networks (Level 4)', 'Apprenticeship Qualification,Future Skills Qualification', 'N.A.', '{"Theory":"90","Practical":"180","EmployabilitySkills":"30","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "48", "qualification_type": "Apprenticeship Qualification,Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_49.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-TL-04092-2025-V2-TSSC', 'Hand Soldering Technician - Telecom Boards', 'telecom', 'Telecom', 3.0, 'A Hand Soldering Technician – Telecom Boards is responsible for soldering and de-soldering components, reworking defects, and cleaning and inspecting telecom boards while following the applicable quality and safety standards.', 450, 450, '401–600', 'Version', '08 May 2025', '30 Apr 2028', 'Telecom Sector Skill Council (TSSC)', 'Telecom Sector Skill Council', 'Communication Electronics', 'Hand Soldering – Senior Technician - Telecom Boards (Level 4)', 'Apprenticeship Qualification,General Qualification', 'N.A.', '{"Theory":"120","Practical":"180","EmployabilitySkills":"30","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "49", "qualification_type": "Apprenticeship Qualification,General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_49.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-TL-04082-2025-V2-TSSC', 'Surface Mount Technology (SMT) - Telecom Technician', 'telecom', 'Telecom', 4.0, 'A Surface Mount Technology (SMT)- Telecom Technician is responsible for executing the complete SMT assembly process, ensuring high-quality telecom Printed Circuit Board (PCB) production. Key responsibilities include screen printing, precise component placement, reflow soldering, cleaning, inspection, and segregation of functional and defective PCBs. The individual also performs repairs and corrections on defective PCBs. The role requires operating and maintaining advanced SMT equipment while optimizing production efficiency and adhering to industry standards for PCB assembly.', 540, 540, '401–600', 'Version', '08 May 2025', '30 Apr 2028', 'Telecom Sector Skill Council (TSSC)', 'Telecom Sector Skill Council', 'Communication Electronics', 'Surface Mount Technology (SMT) Supervisor', 'Apprenticeship Qualification,General Qualification', 'N.A.', '{"Theory":"150","Practical":"210","EmployabilitySkills":"30","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "50", "qualification_type": "Apprenticeship Qualification,General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_49.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-TL-04089-2025-V2-TSSC', 'Technician 5G - Active Network Installation', 'telecom', 'Telecom', 4.0, 'A 5G Technician – Active Network Installation is responsible for installing 5G network equipment at the rack level and performing active network installations. The role also involves identifying and rectifying faults or malfunctions that may arise during the installation process.', 510, 510, '401–600', 'Version', '08 May 2025', '30 Apr 2028', 'Telecom Sector Skill Council (TSSC)', 'Telecom Sector Skill Council', 'Network (Active Components Installation)', 'Project Supervisor - 5G Networks (NSQF Level 5)', 'Apprenticeship Qualification,Future Skills Qualification', 'N.A.', '{"Theory":"150","Practical":"180","EmployabilitySkills":"30","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "51", "qualification_type": "Apprenticeship Qualification,Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_49.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-TL-04088-2025-V2-TSSC', 'Project Supervisor - 5G Networks', 'telecom', 'Telecom', 5.0, 'A Project Supervisor - 5G Networks responsible for ensuring the 5G site is fully operational immediately after successful installation and commissioning, including 5G antennas and MIMO for Next-Generation Nodes (gNodes). They must have expertise in passive and active hardware, as well as software configurations during installation. Additionally, the role involves conducting site acceptance tests, including site audits, VSWR testing, call testing, and verifying antenna positioning (tilt, azimuth, and zenith angles).', 630, 630, '601–800', 'Version', '08 May 2025', '30 Apr 2028', 'Telecom Sector Skill Council (TSSC)', 'Telecom Sector Skill Council', 'Project Engineering', 'System Architect – 5G Cloud RAN (NSQF Level 6)', 'Apprenticeship Qualification,Future Skills Qualification', 'N.A.', '{"Theory":"180","Practical":"270","EmployabilitySkills":"60","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "52", "qualification_type": "Apprenticeship Qualification,Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_49.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-TL-00468- 2025-V2 -TSSC', 'Network Cloud Junior Architect', 'telecom', 'Telecom', 4.0, 'A Network Cloud Junior Architect looks into preparing and executing cloud-based application testing in telecom networks, especially within Software-Defined WAN (SD-WAN) environments. Responsibilities include setting up and maintaining cloud infrastructure using platforms like AWS, Azure, and GCP, configuring testing tools and environments, and ensuring compliance with security and data protection standards. The individual monitors performance, identifies and fixes defects, manages IT and network assets, and maintains inventory using open-source tools. They also coordinate with DevOps teams, optimize resource usage, and ensure documentation and reporting for telecom-grade cloud systems.', 480, 480, '401–600', 'Version', '30 Jun 2022', '30 Jun 2028', 'Telecom Sector Skill Council (TSSC)', 'Telecom Sector Skill Council', 'Network Operation and Maintenance', 'Vertical Progression
●	Machine Learning (ML) Telecom Architect- Level 5', 'Apprenticeship Qualification,Future Skills Qualification', 'N.A.', '{"Theory":"120","Practical":"180","EmployabilitySkills":"30","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "53", "qualification_type": "Apprenticeship Qualification,Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_49.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-TL-00470-2025-V2-TSSC', 'IoT Installation Solution Architect', 'telecom', 'Telecom', 5.0, 'The individual in this job is responsible for conducting the site survey for layout, planning and designing for installation and deployment of IoT sensors/devices, IoT gateways and access layer connectivity in IoT ecosystem to suggest and implement the best IoT solution for the business model.', 540, 540, '401–600', 'Version', '30 Jun 2022', '30 Jun 2028', 'Telecom Sector Skill Council (TSSC)', 'Telecom Sector Skill Council', 'Network Operation and Maintenance', 'Level - 6 (Vertical) - IoT System Architect Manager', 'Apprenticeship Qualification,Future Skills Qualification', 'N.A.', '{"Theory":"120","Practical":"210","EmployabilitySkills":"60","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "54", "qualification_type": "Apprenticeship Qualification,Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_49.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-TL-06067-2025-V2-TSSC', 'IoT Technical Service Operator', 'telecom', 'Telecom', 3.0, 'IoT Technical Service Operators manage IoT systems and devices, ensuring seamless data collection, communication, and functionality. They use specialized platforms, diagnostic tools, and software to optimize system operations, prioritizing real-time data processing, energy efficiency, and secure communication', 390, 390, '201–400', 'Version', '30 Jun 2022', '30 Jun 2028', 'Telecom Sector Skill Council (TSSC)', 'Telecom Sector Skill Council', 'Network Operation and Maintenance', 'Vertical Progression:
●	NSQF Level 4 - Telecom Technician - IoT Devices/Systems', 'Apprenticeship Qualification,Future Skills Qualification', 'N.A.', '{"Theory":"90","Practical":"120","EmployabilitySkills":"30","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "55", "qualification_type": "Apprenticeship Qualification,Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_49.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-5.5-TL-04295-2025-V1-ICES', 'Digital Connectivity Infrastructure (DCI) Designer', 'telecom', 'Telecom', 5.5, 'A Digital Connectivity Infrastructure Designer specializes in integrating digital solutions into physical infrastructure to enable seamless communication and data transfer. They design structured cable systems, wireless networks and digital configurations that connect various components of the infrastructure. Their focus is on creating scalable, efficient and reliable systems that support modern technological demands while ensuring robust connectivity across the entire infrastructure connectivity.', 600, 600, '401–600', 'Version', '08 May 2025', '08 May 2028', 'Integrated Council for Entrepreneurship and Skilling (ICES)', 'The Institution of Civil Engineers Society', 'Digital Connectivity Infrastructure', 'DCI Evaluator (L6)', 'General Qualification', 'N.A.', '{"Theory":"180","Practical":"240","EmployabilitySkills":"60","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "56", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_49.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-TL-00467-2025-V2-TSSC', 'AI & ML - Jr. Telecom Data Analyst', 'telecom', 'Telecom', 4.0, 'An AI & ML – Jr. Telecom Data Analyst supports the implementation of artificial intelligence solutions within telecom operations by collecting, organizing, and analyzing large-scale telecom datasets. The individual in this role assist in developing insights using AI/ML models to improve network performance, customer experience, and operational efficiency.', 450, 450, '401–600', 'Version', '30 Jun 2022', '30 Jun 2028', 'Telecom Sector Skill Council (TSSC)', 'Telecom Sector Skill Council', 'Data Handling - Network Managed Services', 'Vertical Progression: 
● NSQF Level 4.5 – Al & ML- Telecom Data Analyst 
● NSQF Level 5 – Machine Learning (ML) Engineer', 'Apprenticeship Qualification,Future Skills Qualification', 'N.A.', '{"Theory":"120","Practical":"150","EmployabilitySkills":"30","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "57", "qualification_type": "Apprenticeship Qualification,Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_49.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-TL-00466-2025-V2 -TSSC', 'Drone Monitoring and Maintenance Associate', 'telecom', 'Telecom', 3.0, 'A Drone Monitoring and Maintenance Associate is responsible for supporting the operation, monitoring, and upkeep of 5G-enabled drone systems used in telecom applications. The individual manages and analyses real-time drone data, performs routine maintenance and basic troubleshooting of drone hardware and software, and ensures the safe and compliant deployment of drones.', 390, 390, '201–400', 'Version', '30 Jun 2022', '30 Jun 2028', 'Telecom Sector Skill Council (TSSC)', 'Telecom Sector Skill Council', 'Network Operation and Maintenance', 'Vertical Progression:
●	NSQF Level 4 - Drone Technician', 'Apprenticeship Qualification,Future Skills Qualification', 'N.A.', '{"Theory":"90","Practical":"120","EmployabilitySkills":"30","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "58", "qualification_type": "Apprenticeship Qualification,Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_49.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-TL-00464- 2025-V2 -TSSC', 'Technician - Last Mile Active Network', 'telecom', 'Telecom', 4.0, 'A Technician – Last Mile Active Network is responsible for installing, maintaining, and troubleshooting the final segment of network connectivity to end users, ensuring uninterrupted and high-quality service delivery. The individual performs routine checks and technical diagnostics on fibre or copper lines and coordinates with field teams to resolve connectivity issues efficiently. The individual also adheres to safety protocols and company standards during installations and repairs and maintains accurate service records and updates system logs regularly.', 450, 450, '401–600', 'Version', '30 Jun 2022', '30 Jun 2028', 'Telecom Sector Skill Council (TSSC)', 'Telecom Sector Skill Council', 'Network (Active Components Installation)', 'Vertical Progression:
•	NSQF Level 5 – Project Engineer- 5G Network', 'Apprenticeship Qualification,Future Skills Qualification', 'N.A.', '{"Theory":"120","Practical":"150","EmployabilitySkills":"30","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "59", "qualification_type": "Apprenticeship Qualification,Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_49.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-TL-00463-2025-V2-TSSC', 'Smart Devices Installation Operator', 'telecom', 'Telecom', 4.0, 'The Smart Devices Installation Operator is responsible for the installation, configuration, and basic troubleshooting of smart devices in residential, commercial, or industrial settings. The role involves interpreting installation plans, following safety procedures, and ensuring connectivity and optimal functioning of smart systems. The operator works closely with clients and technical teams to ensure seamless deployment and customer satisfaction. All activities must comply with prescribed quality and operational standards.', 390, 390, '201–400', 'Version', '30 Jun 2022', '30 Jun 2028', 'Telecom Sector Skill Council (TSSC)', 'Telecom Sector Skill Council', 'Network (Active Components Installation)', 'Vertical  
•	Level 5: Machine Learning Architect', 'Apprenticeship Qualification,Future Skills Qualification', 'N.A.', '{"Theory":"90","Practical":"120","EmployabilitySkills":"30","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "60", "qualification_type": "Apprenticeship Qualification,Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_49.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-06-TL-046482025-V1-ICES', 'Digital Connectivity Infrastructure (DCI) Evaluator', 'telecom', 'Telecom', 6.0, 'A Digital Connectivity Infrastructure (DCI) Evaluator assesses and certifies the quality, compliance and future-readiness of digital connectivity infrastructure in buildings. They review telecom design, conduct field inspections, verify adherence to regulatory standards like MBBL and NBC and ensure infrastructure supports high-speed connectivity, resilience and scalability for emerging technologies.', 480, 480, '401–600', 'Version', '07 Oct 2025', '07 Oct 2028', 'Integrated Council for Entrepreneurship and Skilling (ICES)', 'Integrated Council for Entrepreneurship and Skilling', 'Digital Connectivity Infrastructure', 'Digital Connectivity Infrastructure (DCI) Property Manager', 'General Qualification', 'N.A.', '{"Theory":"210","Practical":"180","EmployabilitySkills":"60","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "61", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_49.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-TL-04422-2025-V1-TSSC', 'Broadband Network Technician', 'telecom', 'Telecom', 4.0, 'The Broadband Network Technician is responsible for the installation, configuration, testing, and maintenance of broadband network infrastructure, including optical fiber cables (OFC), related passive components, and customer premises equipment (CPE). The role involves splicing, jointing, and termination of fiber cables; configuring broadband connectivity; troubleshooting network and customer faults; and maintaining quality, safety, and documentation standards. The technician works in coordination with the Network Operations Center (NOC), field teams, and customers to ensure uninterrupted broadband services in compliance with organisational and industry norms.', 600, 600, '401–600', 'Version', '30 Sep 2025', '30 Sep 2028', 'Telecom Sector Skill Council (TSSC)', 'Telecom Sector Skill Council', 'Broadband Installation & Maintenance', 'Senior Technician (Broadband Network)', 'General Qualification,OEM Qualification', 'N.A.', '{"Theory":"170","Practical":"250","EmployabilitySkills":"30","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "62", "qualification_type": "General Qualification,OEM Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_49.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-TL-04423-2025-V1-TSSC', 'Wireless Network Technician', 'telecom', 'Telecom', 4.0, 'The individual is responsible for supporting and maintaining wireless network infrastructure, including analysing performance reports, addressing customer complaints, performing maintenance at base station and radio sites, and assisting in the deployment of 5G networks. The role involves defining 5G architecture standards, preparing and verifying hardware, designing spectrum allocation, and implementing 5G New Radio (NR) and Radio Access Network (RAN) elements in compliance with regulatory and operator guidelines. The individual works closely with cross-functional teams to ensure optimal network performance and quality of service.', 600, 600, '401–600', 'Version', '30 Sep 2025', '30 Sep 2028', 'Telecom Sector Skill Council (TSSC)', 'Telecom Sector Skill Council', 'Operations and Maintenance', 'Senior Technician (Wireless Network)', 'General Qualification,OEM Qualification', 'N.A.', '{"Theory":"195","Practical":"225","EmployabilitySkills":"30","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "63", "qualification_type": "General Qualification,OEM Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_49.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-TL-00469-2025-V2-TSSC', 'Machine Learning (ML) - Telecom Architect', 'telecom', 'Telecom', 5.0, 'The ML Telecom Architect is responsible for designing and deploying machine learning models tailored to telecom use cases. The role focuses on developing intelligent systems for detecting fraudulent calls, analyzing suspicious links, and enhancing network security through predictive analytics. A solid understanding of telecom protocols and data flows is essential to identify anomalies and improve system reliability. In addition to fraud detection, the architect will collaborate with network and data science teams to integrate ML solutions into telecom platforms, optimizing real-time decision-making. The candidate should be proficient in supervised and unsupervised learning techniques, with experience in handling large-scale telecom datasets to extract actionable insights.', 540, 540, '401–600', 'Version', '22 Jun 2022', '30 Jun 2028', 'Telecom Sector Skill Council (TSSC)', 'Telecom Sector Skill Council', 'Data Handling – Network Managed Services', 'NSQF Level 6:  AI/ML Program Manager', 'Future Skills Qualification', 'N.A.', '{"Theory":"90","Practical":"210","EmployabilitySkills":"60","OJT_Mandatory":"180"}', false, '{}'::text[], '{"source_row": "64", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_49.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-02-TX-01927-2024-V1.1-TSC', 'Ring Frame Tenter', 'textile-handloom', 'Textile & Handloom', 2.0, 'A ring frame tenter is responsible for carrying out tenting activities in a ring frame machine. A ring frame tenter should be able to creel the roving bobbin, piece the yarn and carry out routine cleaning and preventive maintenance activities to produce defect free yarn and ensure quality ring cops are produced in ring frame machine. This job requires the individual to have thorough knowledge of process flow and material flow in a spinning mill for yarn production and should know about the important functions and operations of a ring frame machine.', 330, 330, '201–400', 'Version', '31 Jan 2024', '31 Jan 2027', 'Textile Sector Skill Council (TSC)', 'Textile Sector Skill council', 'N/A', 'Fitter Spinning', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"90","Practical":"210","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "1", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_57.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-02-TX-01928-2024-V1.1-TSC', 'Ring frame doffer', 'textile-handloom', 'Textile & Handloom', 2.0, 'A ring frame doffer is responsible for carrying out doffing activities in a ring frame machine. A ring frame doffer should be able to prepare for doffing, perform doffing activities, ensuring proper functioning of machine and also ensure minimum time is taken for carrying out doffing activities in ring frame machines.', 330, 330, '201–400', 'Version', '31 Jan 2024', '31 Jan 2027', 'Textile Sector Skill Council (TSC)', 'Textile Sector Skill Council', 'Spinning', 'Assistant Fitter - Spinning', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"90","Practical":"210","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "2", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_57.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-02-TX-02060-2024-V2-TSC', 'Autoconer Tenter', 'textile-handloom', 'Textile & Handloom', 2.0, 'An autoconer tenter is responsible to carry out tenting activities in an autoconer machine. An autoconer tenter should be able to segregate quality cops, creel the cops, ensure proper splicing carry out routine cleaning and maintenance activities, thus producing defect free cone package and ensure proper functioning of autoconer machine. This job requires the individual to have thorough knowledge of process flow and material flow in a spinning mill for yarn production and should know about the important functions and operations of autoconer machine.', 330, 330, '201–400', 'Version', '31 Jan 2024', '31 Jan 2027', 'Textile Sector Skill Council (TSC)', 'Textile Sector Skill Council', 'N/A', 'Fitter Post Spinning', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"90","Practical":"210","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "3", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_57.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-02-TX-01932-2024-V2-TSC', 'Cone Winding Operator-Manual & Assembly Winding', 'textile-handloom', 'Textile & Handloom', 2.0, 'A cone winding operator is responsible to carry out tenting activities in cone winding / assembly winding machine. he/she should be able to segregate quality cops, creel the cops, knotting the yarn, doff the cones, carry out routine cleaning and maintenance activities thus producing defect free cone package and ensure proper functioning of winding machine. This job requires the individual to have thorough knowledge of process flow and material flow in a textile mill for yarn production and should know about the important functions and operations of winding machine.', 330, 330, '201–400', 'Version', '31 Jan 2024', '31 Jan 2027', 'Textile Sector Skill Council (TSC)', 'Textile Sector skill council', 'N/A', 'Assistant Fitter - Spinning', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"90","Practical":"210","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "4", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_57.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-02-TX-01933-2024-V2-TSC', 'TFO Tenter', 'textile-handloom', 'Textile & Handloom', 2.0, 'A Two For One Twister (TFO) tenter is responsible for carrying out tenting activities and ensuring minimum machine stoppage and achieving maximum production in TFO machine. He should be able to creel the paralleled yarn, piece the yarn on breakage, doff the doubled cone package, carry out cleaning and preventive maintenance activities thus producing defect free doubled yarn. This job requires the individual to have thorough knowledge in process flow and material flow in a textile mill for yarn production and should be able to know the important functions and operations of a TFO machine', 330, 330, '201–400', 'Version', '31 Jan 2024', '31 Jan 2027', 'Textile Sector Skill Council (TSC)', 'Textile Sector Skill Council', 'N/A', 'Fitter Post Spinning', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"90","Practical":"210","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "5", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_57.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-02-TX-01941-2024-V2-TSC', 'Shuttle loom operator cum pirn winder', 'textile-handloom', 'Textile & Handloom', 2.0, 'A Shuttle loom operator cum Pirn winder is responsible for carrying out weaving activities in shuttle loom and pirn winding activity in pirn winding machine. The operator should be able to start and stop the shuttle loom, mend broken ends and picks and carry weft replenishment activities to produce defect free fabrics using shuttle loom and wind pirns using the pirn winding machine', 330, 360, '201–400', 'Version', '31 Jan 2024', '31 Jan 2027', 'Textile Sector Skill Council (TSC)', 'Textile Sector Skill council', 'Weaving', 'Assistant Fitter - Weaving', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"75","Practical":"225","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "6", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_57.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-02-TX-01926-2024-V2-TSC', 'Speed Frame Operator - Tenter and Doffer', 'textile-handloom', 'Textile & Handloom', 2.0, 'A Speed frame operator is responsible for carrying out tenting and doffing activities in a speed frame machine. The operator should be able to replenish the sliver cans, piece the broken sliver, piece the broken roving, perform doffing and carry out routine cleaning activities to produce quality roving bobbins in speed frame machine.', 330, 330, '201–400', 'Version', '31 Jan 2024', '31 Jan 2027', 'Textile Sector Skill Council (TSC)', 'Textile Sector Skill council', 'Spinning Preparatory', 'Assistant Fitter - Spinning', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"90","Practical":"210","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "7", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_57.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-02-TX-01929-2024-V2-TSC', 'Open-End Spinning Tenter', 'textile-handloom', 'Textile & Handloom', 2.0, 'An open end spinning tenter is responsible for carrying out tenting activities. This activity ensures minimum machine stoppage and maximum production in an open end spinning machine. An open end spinning tenter should be able to creel the sliver cans, piece the sliver on breakage, doff the cone /cheese package and carry out cleaning and preventive maintenance activities thus producing defect free yarn. This job requires the individual to have thorough knowledge in process flow and material flow in a textile mill for yarn production and should be able to know the important functions and operations of an open end spinning machine.', 330, 330, '201–400', 'Version', '31 Jan 2024', '31 Jan 2027', 'Textile Sector Skill Council (TSC)', 'Textile Sector Skill Council', 'Spinning', 'Assistant Fitter - Spinning', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"90","Practical":"210","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "8", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_57.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-02-TX-01935-2024-V2-TSC', 'Finished Package Checker-cum-Packer - Spinning', 'textile-handloom', 'Textile & Handloom', 2.0, 'A Finished Package Checker-cum-Packer - Spinning is responsible for inspecting all the finished yarn packages after yarn winding process (cone, cheese, etc.), packing inspected yarn packages according to the package specifications and ensuring finished package is within the prescribed limit of weight variation by following the safety and security protocols in a spinning mill.', 330, 390, '201–400', 'Version', '31 Jan 2024', '31 Jan 2027', 'Textile Sector Skill Council (TSC)', 'Textile Sector Skill Council', 'Post Spinning Operations', 'Assistant Fitter - Spinning', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"60","Practical":"240","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "9", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_57.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-02-TX-01922-2024-V2-TSC', 'Carding Operator', 'textile-handloom', 'Textile & Handloom', 2.0, 'A carding operator should be able to operate the carding machine, ensure proper feeding of material in chute/lap feed system, piece the sliver on breakage, doff the cans and transport to the storage area.', 330, 330, '201–400', 'Version', '31 Jan 2024', '31 Jan 2027', 'Textile Sector Skill Council (TSC)', 'Textile Sector Skill Council', 'N/A', 'Fitter Spinning Preparatory', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"90","Practical":"210","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "10", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_57.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-02-TX-01942-2024-V2-TSC', 'Shuttleless Loom Operator', 'textile-handloom', 'Textile & Handloom', 2.0, 'Shuttleless loom operator is a job-role in the weaving department of a textile mill for carrying out weaving activity in shuttleless loom efficiently to get maximum output with minimum defects, giving due importance to safety and environmental aspects. The operator should be able to start the loom, mend broken ends and picks activities to produce defect-free fabrics using shuttleless loom.', 330, 330, '201–400', 'Version', '31 Jan 2024', '31 Jan 2027', 'Textile Sector Skill Council (TSC)', 'Textile Sector Skill Council', 'Weaving', 'Assistant Fitter - Weaving', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"83","Practical":"217","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "11", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_57.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-02-TX-01943-2024-V2-TSC', 'Fabric Checker - Textiles', 'textile-handloom', 'Textile & Handloom', 2.0, 'A Fabric Checker is a job-role in a Weaving department. The responsibility of a fabric checker is to inspect the fabric produced for all types of defects due to yarn or weaving so as to get quality output with minimum defects giving due importance to safety and environment aspects.', 330, 330, '201–400', 'Version', '31 Jan 2024', '31 Jan 2027', 'Textile Sector Skill Council (TSC)', 'Textile Sector Skill Council', 'Post Weaving Operations', 'Assistant Fitter - Weaving', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"75","Practical":"225","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "12", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_57.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-02-TX-01944-2024-V2-TSC', 'Fabric Mender - Textiles', 'textile-handloom', 'Textile & Handloom', 2.0, 'A Fabric mender is a job-role in a Weaving department. The responsibility of a fabric mender is to check and remove / mend the repairable defects in fabric ensuring the fabrics should be defect free and only good quality fabrics are taken for further process.', 330, 330, '201–400', 'Version', '31 Jan 2024', '31 Jan 2027', 'Textile Sector Skill Council (TSC)', 'Textile Sector Skill Council', 'Post – Weaving Operations', 'Assistant Fitter - Weaving', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"75","Practical":"225","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "13", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_57.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-02-TX-01945-2024-V2-TSC', 'Knitting Machine Operator Circular Knitting', 'textile-handloom', 'Textile & Handloom', 2.0, 'A Circular knitting machine operator is responsible for operating industrial Circular knitting machines, repair yarn related faults at the knitting head and fabric press-offs, operate process machines ancillary to the knitting production, identify and sort wastes, and demonstrate knowledge of yarn-related faults in knitted fabrics. This job requires the individual to have thorough knowledge in process flow and material flow in a knitting machine for fabric production and should know the important functions and operations of knitting machines.', 330, 330, '201–400', 'Version', '31 Jan 2024', '31 Jan 2027', 'Textile Sector Skill Council (TSC)', 'Textile Sector Skill Council', 'N/A', 'Assistant Fitter - Knitting', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"90","Practical":"210","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "14", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_57.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-02-TX-01925-2024-V2-TSC', 'Draw Frame Operator', 'textile-handloom', 'Textile & Handloom', 2.0, 'A draw frame operator is responsible to carry out tenting activities on the draw frame machines. The operator should be able to operate the breaker and finisher passage draw frame machines, replenish the sliver cans, piece the sliver on breakage, doff the sliver cans and transport the delivery cans to the storage area.', 330, 330, '201–400', 'Version', '31 Jan 2024', '31 Jan 2027', 'Textile Sector Skill Council (TSC)', 'Textile Sector Skill Council', 'N/A', 'Assistant Fitter - Spinning', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"90","Practical":"210","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "15", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_57.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-02-TX-01948-2024-V2-TSC', 'Cone Winder-cum-Pirn Winder', 'textile-handloom', 'Textile & Handloom', 2.0, 'A cone winder-cum-pirn winder is responsible for winding activities in cone or pirn winding machine. The cone winder should be able to open the hank yarn properly, untangle it, wrap over the winding machine, knot the broken yarn, doff the cones, carry out routine cleaning and maintenance activities thus producing defect free cone or pirn package and ensure proper functioning of the winding machine. This job requires the individual to have thorough knowledge of type of yarns, type of winding machines and should know about the important functions and operations of winding machine.', 330, 330, '201–400', 'Version', '31 Jan 2024', '31 Jan 2027', 'Textile Sector Skill Council (TSC)', 'Textile Sector Skill Council', 'Handloom Preparatory', 'Two Shaft Handloom Weaver', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"90","Practical":"210","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "16", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_57.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-02-TX-01950-2024-V2-TSC', 'Hand Spinning Operator', 'textile-handloom', 'Textile & Handloom', 2.0, 'The hand spinning operator is responsible for spinning fibers under supervision by maintaining health, safety and security, and complying with the workplace requirements in the khadi sector.', 330, 570, '401–600', 'Version', '31 Jan 2024', '31 Jan 2027', 'Textile Sector Skill Council (TSC)', 'Textile Sector Skill Council', 'Handloom Preparatory', 'Two Shaft Handloom Weaver', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"90","Practical":"210","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "17", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_57.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-02-TX-01930-2024-V2-TSC', 'Ring Frame Operator', 'textile-handloom', 'Textile & Handloom', 2.0, 'A Ring Frame Operator is responsible for carrying out tenting and doffing activities in Ring Frame machine. The operator should be able to creel the roving bobbin, piece the broken yarn, perform doffing and carry out routine cleaning activities to produce defect free yarn and ensure quality ring cops are produced in Ring Frame machine.', 330, 330, '201–400', 'Version', '31 Jan 2024', '31 Jan 2027', 'Textile Sector Skill Council (TSC)', 'Textile Sector Skill Council', 'N/A', 'Assistant Fitter - Spinning', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"90","Practical":"210","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "18", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_57.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-02-TX-01934-2024-V2-TSC', 'Winding Tenter', 'textile-handloom', 'Textile & Handloom', 2.0, 'A Winding Tenter is responsible for carryout tenting activities in winding machine. A Winding Tenter should be able to replenish the feed material, attend the malfunctions, perform doffing and carry out routine cleaning activities and ensure defect free cone/ cheese packages are produced in winding machine.', 330, 690, '601–800', 'Version', '31 Jan 2024', '31 Jan 2027', 'Textile Sector Skill Council (TSC)', 'Textile Sector Skill Council', 'Post Spinning Operations', 'Assistant Fitter - Spinning', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"98","Practical":"202","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "19", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_57.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-02-TX-01923-2024-V2-TSC', 'Combing Preparatory Operator', 'textile-handloom', 'Textile & Handloom', 2.0, 'A combing preparatory tenter is responsible to carry out tenting activities in the combing preparatory machine. He should be able to operate the combing preparatory machine, ensure proper feeding of carded or drawing sliver, piece the sliver on breakage, doff the comber laps and transport to the combing area.', 330, 330, '201–400', 'Version', '31 Jan 2024', '31 Jan 2027', 'Textile Sector Skill Council (TSC)', 'Textile Sector Skill Council', 'N/A', 'Assistant Fitter - Spinning', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"98","Practical":"202","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "20", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_57.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-02-TX-01924-2024-V2-TSC', 'Combing Operator', 'textile-handloom', 'Textile & Handloom', 2.0, 'A combing operator is responsible to carry out tenting activities in the comber machine. He should be able to operate the comber, ensure proper feeding of laps, piece the comber lap and sliver on breakage, doff the sliver cans and transport the delivery cans to the storage area', 330, 330, '201–400', 'Version', '31 Jan 2024', '31 Jan 2027', 'Textile Sector Skill Council (TSC)', 'Textile Sector Skill Council', 'N/A', 'Assistant Fitter - Spinning', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"98","Practical":"202","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "21", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_57.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-02-TX-01936-2024-V2-TSC', 'Warper - Direct Warping Machine', 'textile-handloom', 'Textile & Handloom', 2.0, 'A Warper is a job-role in a weaving preparatory department. The responsibility of a Warper is to run the Warping Machine efficiently, carry out routine cleaning and maintenance activities to get maximum output with minimum defects giving due importance to safety. This job requires the individual to have thorough knowledge of process flow and material flow in a Weaving mill for fabric production and should know about the important functions and operations of Warping machine.', 330, 330, '201–400', 'Version', '31 Jan 2024', '31 Jan 2027', 'Textile Sector Skill Council (TSC)', 'Textile Sector Skill Council', 'Weaving Preparatory', 'Assistant Fitter - Weaving', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"98","Practical":"202","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "22", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_57.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-02-TX-01938-2024-V2-TSC', 'Sizing Machine Operator', 'textile-handloom', 'Textile & Handloom', 2.0, 'A Sizing machine operator is responsible for sizing of yarn as per the required parameters in the weaving preparatory department. The responsibility of a Sizing machine operator is to run the Sizing Machine efficiently so as to get maximum output with minimum defects giving due importance to safety and environment aspects. The job requires the individual to have thorough knowledge of process flow and material flow in a Weaving mill for fabric production and should know about the important functions and operations of Sizing machine.', 330, 330, '201–400', 'Version', '31 Jan 2024', '31 Jan 2027', 'Textile Sector Skill Council (TSC)', 'Textile Sector Skill Council', 'Weaving Preparatory', 'Assistant Fitter - Weaving', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"75","Practical":"225","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "23", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_57.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-02-TX-01939-2024-V2-TSC', 'Knotting Machine Operator', 'textile-handloom', 'Textile & Handloom', 2.0, 'A Knotting Machine Operator is a job-role in the weaving preparatory department. The responsibility of a Knotting Machine Operator is to Knot the warp ends in the run out beams with that of the fresh beams. efficiently so as to get quality output with minimum defects giving due importance to safety and environmental aspects.', 330, 330, '201–400', 'Version', '31 Jan 2024', '31 Jan 2027', 'Textile Sector Skill Council (TSC)', 'Textile Sector Skill Council', 'Weaving', 'Assistant Fitter - Weaving', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"75","Practical":"225","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "24", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_57.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-02-TX-01940-2024-V2-TSC', 'Pirn Winding Machine Operator', 'textile-handloom', 'Textile & Handloom', 2.0, 'Pirn Winding Machine Operator, is a job-role in a weaving department. The responsibility of Winder Automatic Pirn Winding Machine is to run the winding machine efficiently so as to get maximum output with minimum defects giving due importance to safety and environmental aspects.', 330, 330, '201–400', 'Version', '31 Jan 2024', '31 Jan 2027', 'Textile Sector Skill Council (TSC)', 'Textile Sector Skill Council', 'Weaving', 'Assistant Fitter - Weaving', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"75","Practical":"225","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "25", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_57.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-02-TX-01946-2024-V2-TSC', 'Knitting Machine Operator Flat Bed Knitting', 'textile-handloom', 'Textile & Handloom', 2.0, 'A Flat Knitting operator is responsible to operate industrial knitting machines, repair yarn-related faults at the knitting head and fabric press-offs, operate process machines ancillary to the knitting production, identify and sort wastes, and demonstrate knowledge of yarn-related faults in knitted fabrics. This job requires the individual to have thorough knowledge in process flow and material flow in a knitting machine for fabric production and should know the important functions and operations of knitting machines.', 330, 330, '201–400', 'Version', '31 Jan 2024', '31 Jan 2027', 'Textile Sector Skill Council (TSC)', 'Textile Sector Skill Council', 'Knitting', 'Assistant Fitter - Knitting', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"90","Practical":"210","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "26", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_57.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-02-TX-01947-2024-V2-TSC', 'Knitting Machine Operator Warp Knitting', 'textile-handloom', 'Textile & Handloom', 2.0, 'A Warp knitting machine operator is responsible for operating the warp knitting machine in a knitting mill. This job requires the individual to have thorough knowledge of process flow and material flow in a knitting mill for fabric production and should know the important functions and operations of warp knitting machines.', 330, 330, '201–400', 'Version', '31 Jan 2024', '31 Jan 2027', 'Textile Sector Skill Council (TSC)', 'Textile Sector Skill Council', 'Knitting', 'Assistant Fitter - Knitting', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"83","Practical":"217","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "27", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_57.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-02-TX-01949-2024-V2-TSC', 'Card Puncher (Automatic Machine)', 'textile-handloom', 'Textile & Handloom', 2.0, 'The card puncher punches customized cards based on the designs created by the designer by special card punching machines using different softwares, and may also do the lacing of the cards for jacquard weaving.', 330, 330, '201–400', 'Version', '31 Jan 2024', '31 Jan 2027', 'Textile Sector Skill Council (TSC)', 'Textile Sector Skill Council', 'Handloom Preparatory', 'Handloom Weaver', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"90","Practical":"210","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "28", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_57.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-02-TX-01937-2024-V2-TSC', 'Size Mixer', 'textile-handloom', 'Textile & Handloom', 2.0, 'A Size Mixer is a job-role in a weaving preparatory department. The responsibility of a Size Mixer is to prepare the size mixing efficiently so as to get quality output with minimum defects giving due importance to safety and environment aspects.', 330, 330, '201–400', 'Version', '31 Mar 2024', '31 Jan 2027', 'Textile Sector Skill Council (TSC)', 'Textile Sector Skill Council', 'Preparatory- Weaving', 'Assistant Fitter - Weaving', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"75","Practical":"225","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "29", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_57.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-TX-01920-2024-V1.1-TSC', 'Handloom Entrepreneur', 'textile-handloom', 'Textile & Handloom', 5.0, 'A Handloom Entrepreneur is responsible for collecting handloom business related market information for planning and decision making, coordinating with the team for operation, finance and administrative activities, designing, delivering and supervising activities to ensure development and delivery of quality handloom products. Entrepreneur in this position often run profitable organizations that own their facilities and equipment.', 570, 570, '401–600', 'Version', '29 Sep 2022', '29 Sep 2025', 'Textile Sector Skill Council (TSC)', 'Textile Sector Skill Council', 'Handloom Business', 'Cluster Development Executive', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"150","Practical":"360","EmployabilitySkills":"60","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "30", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_57.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-3.5-TX-01951-2024-V2-TSC', 'Assistant Design Maker - Textiles', 'textile-handloom', 'Textile & Handloom', 3.5, 'An Assistant design maker - textiles is responsible for developing design using the motif samples or references received from the clients involved in textile manufacturing. The individual may use references from designing books and develop design on the graph paper manually or on computers using different CAD software. The designer needs to note down the preference of the end user in terms of design parameters.', 360, 360, '201–400', 'Version', '31 Jan 2024', '31 Jan 2027', 'Textile Sector Skill Council (TSC)', 'Textile Sector Skill Council', 'Designer', 'Jacquard Designer - Textile', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"90","Practical":"240","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "31", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_57.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-TX-03345-2024-V1-TSC', 'Hank Dyer', 'textile-handloom', 'Textile & Handloom', 3.0, 'A Hank Dyer is responsible for pre-treatment, dyeing and finishing of yarns made of different types fibres such as cotton, viscose, wool, silk and synthetics in the handloom sector. The processes are carried either using traditional methods with little automation or with specially developed machines suitable for the purpose. The processed yarns are expected to match the standard shades for specified properties as well as conform to requirements for desired level of fastness.', 330, 330, '201–400', 'Version', '30 Sep 2021', '22 Oct 2027', 'Textile Sector Skill Council (TSC)', 'TEXTILE SECTOR SKILL COUNCIL', 'Processor', 'Dye Master - Handloom', 'Apprenticeship Qualification,General Qualification,Heritage/Traditional Qualification', 'N.A.', '{"Theory":"90","Practical":"210","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "32", "qualification_type": "Apprenticeship Qualification,General Qualification,Heritage/Traditional Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_57.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-TX-03347-2024-V1-TSC', 'Two Shaft Handloom Weaver', 'textile-handloom', 'Textile & Handloom', 3.0, 'A two shaft handloom weaver produces various types of fabrics in the basic weaves and its derivatives using different kinds of yarns such as cotton, wool, silk, etc. by hand on a fly-shuttle or a throw-shuttle handloom as per the provided yarn and pattern or design specifications.', 330, 330, '201–400', 'Version', '22 Oct 2024', '22 Oct 2027', 'Textile Sector Skill Council (TSC)', 'TEXTILE SECTOR SKILL COUNCIL', 'Weaver', 'Master Weaver', 'Apprenticeship Qualification,General Qualification,Heritage/Traditional Qualification', 'N.A.', '{"Theory":"90","Practical":"210","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "33", "qualification_type": "Apprenticeship Qualification,General Qualification,Heritage/Traditional Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_57.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-TX-03348-2024-V1-TSC', 'Jacquard Weaver', 'textile-handloom', 'Textile & Handloom', 3.0, 'A Jacquard weaver - handloom weaves various types of jacquard woven fabrics and artistic textiles on a jacquard handloom, using different kinds of yarns- cotton/raw silk on a fly-shuttle or throw-shuttle handloom. The jacquard weaver is responsible for carrying out pre-weaving activities mend broken ends, weft picks, change jacquard punch cards and carry weft replenishment activities to produce defect-free jacquard woven fabrics.', 330, 330, '201–400', 'Version', '22 Oct 2024', '22 Oct 2027', 'Textile Sector Skill Council (TSC)', 'TEXTILE SECTOR SKILL COUNCIL', 'Weaver', 'Master Weaver', 'Apprenticeship Qualification,General Qualification,Heritage/Traditional Qualification', 'N.A.', '{"Theory":"90","Practical":"210","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "34", "qualification_type": "Apprenticeship Qualification,General Qualification,Heritage/Traditional Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_57.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-TX-03346-2024-V1-TSC', 'Loin Loom Weaver', 'textile-handloom', 'Textile & Handloom', 3.0, 'A Loin Loom Weaver is the one who weaves various types of fabrics and artistic textiles by hand using a Loin Loom. A weaver can weave basic weaves - Plain and its variations, using different kinds of yarns - cotton/wool/silk on a fly-shuttle or throw-shuttle Loin Loom as per pattern or design provided', 330, 330, '201–400', 'Version', '30 Sep 2021', '22 Oct 2027', 'Textile Sector Skill Council (TSC)', 'TEXTILE SECTOR SKILL COUNCIL', 'Weaver', 'Master Weaver', 'Apprenticeship Qualification,General Qualification,Heritage/Traditional Qualification', 'N.A.', '{"Theory":"90","Practical":"210","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "35", "qualification_type": "Apprenticeship Qualification,General Qualification,Heritage/Traditional Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_57.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-4.5-TX-03192-2024-V2-DGT', 'SPINNING TECHNICIAN', 'textile-handloom', 'Textile & Handloom', 4.5, 'The individual will be able to impart theoretical instructions, demonstrate practical skills, evaluate and grade trainees of Spinning Technician and related trades in ITIs/ Vocational Training Institutes, industrial workshops, etc.', 1350, 1350, '1201–2400', 'Version', '22 Oct 2024', '21 Oct 2027', 'Directorate General of Training (DGT)', 'DGT', 'Manual Training Teacher/ Craft Instructor, Spinning Master', 'Technical Instructor in a vocational training Institute/ technical Institution, Supervisor in Industries', 'General Qualification', 'N.A.', '{"Theory":"450","Practical":"750","EmployabilitySkills":"0","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "36", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_57.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-4.4-TX-03261-2024-V1-IJIRA', 'Jute Manufacturing Technician (Elective 1 Jute Yarn, Elective 2: Jute fabric)', 'textile-handloom', 'Textile & Handloom', 4.0, 'Jute Manufacturing Technician is responsible for efficiently handling modern Spinning machines including preparatory and Jute Batching or modern looms (Rapier, S-4A & one mack etc.) including preparatory and Jute finishing. As  Jute Manufacturing Technician, S/he makes necessary arrangements including checking of quality of jute sliver, jute yarn, jute warp beam and jute weft package availability including its quality. To run efficiently and ensure sustainability of production process S/he requires skill on mechanism of Spreader / Softener, Carding, Drawing and Spinning machine spare parts function, knowledge of different carding action, draft & doubling mechanism of loom, spare parts function, knowledge of different motions of loom, tension control mechanism, lubrication schedule, maintenance, detection of yarn /fabric faults and Testing and Quality Control of Jute yarn, fabric on quality of jute packaging materials.', 510, 720, '601–800', 'Version', '22 Oct 2024', '22 Oct 2027', 'Indian Jute Industries'' Research Association (IJIRA)', 'Indian Jute Industries’ Research Association', 'Production', 'Level 5:  Supervisor (Jute  Manufacturing)', 'General Qualification', 'N.A.', '{"Theory":"60","Practical":"150","EmployabilitySkills":"30","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "37", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_57.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-4.4-TX-03260-2024-V1-IJIRA', 'Junior Quality Control Technician (Jute Production)', 'textile-handloom', 'Textile & Handloom', 4.0, 'Quality Control Technician (Jute Production) should be able to carry out Quality control/Quality assurance processes, understanding product and processes required at various stages of production for meeting the expectations of final customers.
A Quality Assessor carries out quality assurance /quality control procedures in the sampling, pre-production, during production, and post production stages, reports deviations and prevents quality failures.', 480, 480, '401–600', 'Version', '22 Oct 2024', '22 Oct 2027', 'Indian Jute Industries'' Research Association (IJIRA)', 'Indian Jute Industries’ Research Association', 'Quality Control', 'Level 5:  Supervisor (Jute Quality Control )', 'General Qualification', 'N.A.', '{"Theory":"90","Practical":"210","EmployabilitySkills":"30","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "38", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_57.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-4.4-TX-03259-2024-V1-IJIRA', 'Jute Machine Maintenance Technician (Elective 1: Spinning machinery, Elective 2: Weaving Machinery)', 'textile-handloom', 'Textile & Handloom', 4.0, 'Jute Machine Maintenance Technician plays a very important role in:
	The operation of Jute mill machinery used in jute mill and its maintenance requirements.
	Inspecting, repairing and maintaining the machinery and equipment used in the jute mill
	Identifying and diagnosing equipment malfunctions and technical issues
	Elucidate various components of power transmission system present in Jute mill machinery
	Identify the standard maintenance schedule
	Carrying out repairs on damaged or faulty machinery components, such as motors, belts, bearings and other mechanical parts.
	Identify electrical circuits, electronic components and techniques used for Jute Machinery & trouble shooting
	Measure various statistical quality parameters in jute mill maintenance and store record keeping using spread sheet/App.', 510, 720, '601–800', 'Version', '22 Oct 2024', '22 Oct 2027', 'Indian Jute Industries'' Research Association (IJIRA)', 'Indian Jute Industries’ Research Association', 'Machine Maintenance', 'Level 5:   Supervisor (Jute Machinery Maintenance)', 'General Qualification', 'N.A.', '{"Theory":"60","Practical":"120","EmployabilitySkills":"30","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "39", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_57.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-TX-01973-2024-V1-IJIRA', 'Jute Loom Weaving Operator (S4 loom)', 'textile-handloom', 'Textile & Handloom', 3.0, 'Jute Loom Weaving Operator (S4 loom)  is responsible for efficiently operating modern looms (Rapier, S-4A & one mack etc.). As weaver, S/he makes necessary arrangements including checking of quality of jute warp beam and jute weft package availability including its quality. To run efficiently and ensure sustainability of production process S/he is required skill on mechanism of loom, spare parts identification, knowledge of different motions of loom, tension control mechanism, lubrication schedule, maintenance, detection of fabric faults and Testing and Quality Control of Jute yarn, fabric on quality of jute packaging materials.', 300, 300, '201–400', 'Version', '31 Jan 2024', '31 Jan 2027', 'Indian Jute Industries'' Research Association (IJIRA)', 'Indian Jute Industries’ Research Association', 'Weaving', 'Junior level Supervisor (Winding to Finishing)', 'General Qualification', 'N.A.', '{"Theory":"60","Practical":"120","EmployabilitySkills":"30","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "40", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_57.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-02-TX-01921-2024-V2-TSC', 'Blowroom Operator', 'textile-handloom', 'Textile & Handloom', 2.0, 'A blowroom operator is responsible to carry out activities in the sequence of machines in blowroom department. A blowroom operator should be able to operate the sequence of machines in blowroom department, carry out routine cleaning and preventive maintenance activities, ascertaining proper functioning of all machines thus ensuring the opened and cleaned fibre gets transported to the carding department via chute/lap feed system.', 330, 330, '201–400', 'Version', '31 Jan 2024', '31 Jan 2027', 'Textile Sector Skill Council (TSC)', 'TEXTILE SECTOR SKILL COUNCIL', 'Spinning Preparatory', 'Assistant Fitter - Spinning', 'Apprenticeship Qualification,General Qualification,Heritage/Traditional Qualification', 'N.A.', '{"Theory":"98","Practical":"202","EmployabilitySkills":"30","OJT_Mandatory":"00"}', false, '{}'::text[], '{"source_row": "41", "qualification_type": "Apprenticeship Qualification,General Qualification,Heritage/Traditional Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_57.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-TX-03506-2025-V1-IJIRA', 'Junior Technician (Natural Fibre – Geotextile)', 'textile-handloom', 'Textile & Handloom', 3.0, 'Junior Technician (Natural Fibre – Geotextile) should be able to manufacture product, processes and quality required at various geotextile products as per standard', 300, 300, '201–400', 'Version', '18 Feb 2025', '18 Feb 2028', 'Indian Jute Industries'' Research Association (IJIRA)', 'Indian Jute Industries’ Research Association', 'Production (Geotextile)', 'Technician in Geotextile and its Application (Natural Fibre)', 'Future Skills Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"60","Practical":"150","EmployabilitySkills":"30","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "42", "qualification_type": "Future Skills Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_57.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-4.5-TX-03719-2025-V1-IJIRA', 'Fundamentals of Geotextile and its Application (Natural Fibre)', 'textile-handloom', 'Textile & Handloom', 4.5, 'Fundamentals of Geotextile and its Application (Natural Fibre) should be able to understand the emerging trend of Geotextile, Quality control/Quality assurance processes, understanding product and processes required at various stages of geotextile production for meeting the expectations of final customers.', 120, 120, '1–200', 'Version', '18 Feb 2025', '18 Feb 2028', 'Indian Jute Industries'' Research Association (IJIRA)', 'Indian Jute Industries’ Research Association', 'Manufacturing and Application of Geotextile', '-NA', 'Future Skills Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"40","Practical":"80","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "43", "qualification_type": "Future Skills Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_57.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-TX-03703-2025-V2-TSC', 'Warper - Handloom', 'textile-handloom', 'Textile & Handloom', 3.0, 'The Warper - Handloom is responsible for running the warping machine efficiently, taking due safety precautions, in the handloom sector in order to ensure maximum output with minimum defects. The individual is also responsible for carrying out other activities like calculating raw material requirement, creeling, doffing of warp yarns, etc. under the supervision of the weaver.', 330, 330, '201–400', 'Version', '25 Nov 2021', '18 Feb 2028', 'Textile Sector Skill Council (TSC)', 'Textile Sector Skill Council', 'Weaver', 'Handloom Weaver', 'General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"90","Practical":"210","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "44", "qualification_type": "General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_57.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-06-TX-03437-2024-V1-TSC', 'Entrepreneur - Textile Waste Management & Recycling', 'textile-handloom', 'Textile & Handloom', 6.0, 'An Entrepreneur - Textile Waste Management & Recycling is responsible to focus on the kay areas of the textile waste recycling business including business development, operations, compliance, financial management, marketing, innovation, and team leadership, ensuring that the candidate is well-prepared to lead a successful and sustainable recycling operation.', 600, 600, '401–600', 'Version', '17 Dec 2024', '17 Dec 2027', 'Textile Sector Skill Council (TSC)', 'Textile Sector Skill Council', 'Textile Entrepreneur', 'Business Consultant – Textile Waste Recycling', 'Future Skills Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"180","Practical":"360","EmployabilitySkills":"60","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "45", "qualification_type": "Future Skills Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_57.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-02-TX-03438-2024-V1-TSC', 'Textile Waste Recycler - Collection and Segregation', 'textile-handloom', 'Textile & Handloom', 2.0, 'A Textile Waste Recycler - Collector and Segregator is responsible for the collection, sorting, and transportation of textile waste from various sources, ensuring proper handling for recycling. This role plays a critical part in the waste management and recycling industry, contributing to environmental sustainability by reducing textile waste in landfills.', 270, 270, '201–400', 'Version', '17 Dec 2024', '17 Dec 2027', 'Textile Sector Skill Council (TSC)', 'Textile Sector Skill Council', 'Pre Spinning Operations, Preparatory - Weaving', 'Textile Waste Recycler (Horizontal Progression), Senior – Textile Waste Recycling Machine (Vertical Progression)', 'Future Skills Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"60","Practical":"180","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "46", "qualification_type": "Future Skills Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_57.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-02-TX-03439-2024-V1-TSC', 'Textile Waste Recycling Machine Operator', 'textile-handloom', 'Textile & Handloom', 2.0, 'A Textile Waste Recycling Machine Operator is responsible for collection, sorting and shredding of textile waste under supervision by maintaining health, safety and security, and complying with the workplace requirements in the textile waste processing sector.', 270, 420, '401–600', 'Version', '17 Dec 2024', '17 Dec 2027', 'Textile Sector Skill Council (TSC)', 'Textile Sector Skill Council (TSC)', 'Pre Spinning Operations, Preparatory - Weaving', 'Senior – Textile Waste Recycling Machine Operator (Vertical Progression)', 'Future Skills Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"60","Practical":"180","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "47", "qualification_type": "Future Skills Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_57.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-05-TX-01418-2023-V1-TSC', 'Weaving Process Evaluation', 'textile-handloom', 'Textile & Handloom', 5.0, 'The NOS weaving production process evaluation covers the procedures involved in evaluating the weaving process to match the standard quality requirement.', 60, 60, '1–200', 'Version', '30 Nov 2023', '30 Nov 2026', 'Textile Sector Skill Council (TSC)', 'Textile Sector Skill Council (TSC)', 'Weaving Quality Control', 'Not Applicable', 'National Occupational Standard', 'N.A.', '{"Theory":"15","Practical":"45","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "48", "qualification_type": "National Occupational Standard", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_57.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-4.5-TX-01417-2023-V1-TSC', 'Woven Fabric Testing - Physical', 'textile-handloom', 'Textile & Handloom', 4.5, 'The NOS Woven Fabric Testing - Physical deals with the physical testing of woven fabrics to match the standard quality requirement.', 30, 30, '1–200', 'Version', '30 Nov 2023', '30 Nov 2026', 'Textile Sector Skill Council (TSC)', 'Textile Sector Skill Council', 'Weaving – Quality Control', 'Not Applicable', 'National Occupational Standard', 'N.A.', '{"Theory":"9","Practical":"21","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "49", "qualification_type": "National Occupational Standard", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_57.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-02-TX-04104-2025-V2-TSC', 'Kalamkari Artisan', 'textile-handloom', 'Textile & Handloom', 2.0, 'The kalamkari artisan is responsible for designing and creating a kalamkari painting by maintaining tools, health, safety and security, and complying with the workplace requirements in the handloom sector. The person can either work as a freelancer or seek employment in an handloom cooperative/organization.', 270, 270, '201–400', 'Version', '08 May 2025', '08 May 2028', 'Textile Sector Skill Council (TSC)', 'Textile Sector Skill Council', 'Designer', 'Sr. Kalamkari Artisan', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"60","Practical":"180","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "50", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_57.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-02-TX-04105-2025-V2-TSC', 'Ikkat Artisan', 'textile-handloom', 'Textile & Handloom', 2.0, 'The ikkat artisan is responsible for designing, dyeing and weaving by maintaining tools, health, safety and security, and complying with the workplace requirements in the handloom sector. The person can either work as a freelancer or seek employment in an handloom cooperative/organization.', 270, 270, '201–400', 'Version', '08 May 2025', '08 May 2028', 'Textile Sector Skill Council (TSC)', 'Textile Sector Skill Council', 'Designer', 'Sr. Ikkat Artisan', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"60","Practical":"180","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "51", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_57.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-TX-04101-2025-V2-TSC', 'Fitter Spinning Preparatory', 'textile-handloom', 'Textile & Handloom', 4.0, 'The spinning preparatory fitter is responsible for carrying out maintenance activities in all the machines in preparatory department like blowroom, carding, draw frame, combing preparatory, comber and speed frame machines. He/she should carry out all the maintenance aspects such as erecting, dismantling, assembling, leveling, attending & resolving repairs and breakdowns in preparatory department. He/she should also carry out regular preventive maintenance activities thus ensuring proper functioning of all machines.', 450, 450, '401–600', 'Version', '08 May 2025', '08 May 2028', 'Textile Sector Skill Council (TSC)', 'Textile Sector Skill Council', 'Maintenance- Spinning Machines', 'Supervisor - Spinning', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"120","Practical":"300","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "52", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_57.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-TX-04102-2025-V2-TSC', 'Fitter - Ring Spinning', 'textile-handloom', 'Textile & Handloom', 4.0, 'The ring spinning fitter is responsible for carrying out all the maintenance activities in a ring spinning machine. He/she should be able to carry out all the maintenance activities such as erecting, dismantling, assembling, leveling, attending & resolving repairs and breakdowns in a ring spinning machine. The fitter should also carry out regular maintenance activities thus ensuring proper functioning of the machines.', 450, 450, '401–600', 'Version', '08 May 2025', '08 May 2028', 'Textile Sector Skill Council (TSC)', 'Textile Sector Skill Council', 'Maintenance – Spinning Machine', 'Supervisor - Spinning', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"120","Practical":"300","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "53", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_57.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-TX-04103-2025-V2-TSC', 'Fitter - Post Spinning', 'textile-handloom', 'Textile & Handloom', 4.0, 'The post spinning fitter is responsible for carrying out maintenance activities in all the machines in post spinning department such as autoconer, assembly winder, TFO machines etc. He/she should be able to carry out all the maintenance aspects like erecting, dismantling, assembling, leveling, attending & resolving repairs and breakdowns in post spinning department. He/she should also carry out regular preventive maintenance activities thus ensuring proper functioning of all machines.', 450, 450, '401–600', 'Version', '08 May 2025', '08 May 2028', 'Textile Sector Skill Council (TSC)', 'Textile Sector Skill Council', 'Maintenance – Spinning Machine', 'Supervisor - Spinning', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"120","Practical":"300","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "54", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_57.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-02-TX-04106-2025-V2-TSC', 'Fitter Weaving Preparatory', 'textile-handloom', 'Textile & Handloom', 4.0, 'A Fitter-Weaving Preparatory, is a job-role in the weaving preparatory department. The responsibility of a Fitter (Weaving Preparatory) is to maintain all Weaving Preparatory Machines, efficiently so as to get maximum output with minimum defects giving due importance to safety and environment aspects. He/she should carry out all the maintenance aspects such as erecting, dismantling, assembling, leveling, attending & resolving repairs and breakdowns in preparatory department. He/she should also carry out regular preventive maintenance activities thus ensuring proper functioning of all machines.', 450, 450, '401–600', 'Version', '08 May 2025', '08 May 2028', 'Textile Sector Skill Council (TSC)', 'Textile Sector Skill Council', 'Maintenance - Weaving Textiles', 'Supervisor - Weaving', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"120","Practical":"300","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "55", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_57.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-TX-04107-2025-V2-TSC', 'Fitter - Shuttleless Weaving Machine: Air-Jet', 'textile-handloom', 'Textile & Handloom', 4.0, 'A Fitter - Shuttleless Weaving Machine: Air-Jet is a job-role in a weaving department. The responsibility of Fitter - Shuttleless Weaving Machine: AirJet is to maintain the loom efficiently so as to get maximum output with minimum defects, with less cost of production giving due importance to safety and environment aspects. He/she should carry out all the maintenance aspects such as erecting, dismantling, assembling, leveling, attending & resolving repairs and breakdowns in preparatory department. He/she should also carry out regular preventive maintenance activities thus ensuring proper functioning of all machines.', 450, 450, '401–600', 'Version', '08 May 2025', '08 May 2028', 'Textile Sector Skill Council (TSC)', 'Textile Sector Skill Council', 'Maintenance-Weaving Machines', 'Supervisor - Weaving', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"120","Practical":"300","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "56", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_57.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-02-TX-04094-2025-V2-TSC', 'Textile Processing Preparatory Operator', 'textile-handloom', 'Textile & Handloom', 2.0, 'A Textile Processing Preparatory Operator is responsible to do the specified job of pre-treatment of fabric with proper control of parameters to get the desired effect. This job requires the individual to have thorough knowledge of process flow and material flow in a processing mill for fabric production and should know the important functions and operations of machines used in preparatory department of textile processing.', 270, 420, '401–600', 'Version', '08 May 2025', '08 May 2028', 'Textile Sector Skill Council (TSC)', 'Textile Sector Skill Council', 'Pre - Treatment', 'Assistant Fitter - Processing', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"75","Practical":"165","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "57", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_57.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-02-TX-04095-2025-V2-TSC', 'Dyestuff & Chemical Preparation Operator', 'textile-handloom', 'Textile & Handloom', 2.0, 'A Dyestuff & Chemical Preparation Operator is responsible for Weighing, Dissolving & Dispensing of Dyestuff, Chemicals & other auxiliaries used for various purposes in a processing unit. This job requires the individual to have thorough knowledge of process flow and material flow in a processing unit for fabric/fiber/yarn production and should know the importance of weighing & dispensing of various types of dyes & chemicals used in a processing unit.', 270, 270, '201–400', 'Version', '08 May 2025', '08 May 2028', 'Textile Sector Skill Council (TSC)', 'Textile Sector Skill Council', 'Dyeing & Printing', 'Processing Machine Operator', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"75","Practical":"165","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "58", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_57.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-02-TX-04096-2025-V2-TSC', 'Textile Dyeing machine operator', 'textile-handloom', 'Textile & Handloom', 2.0, 'A Dyeing Machine Operator is responsible for pretreatment and dyeing operations. The job requires the individual to have thorough knowledge of process flow and material flow in a processing mill for fabric production and he should know the important functions and operations of textile dyeing machines.', 270, 570, '401–600', 'Version', '08 May 2025', '08 May 2028', 'Textile Sector Skill Council (TSC)', 'Textile Sector Skill Council', 'Dyeing and Printing', 'Assistant Fitter - Processing', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"75","Practical":"165","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "59", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_57.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-02-TX-04097-2025-V2-TSC', 'Textile Printing Machine operator', 'textile-handloom', 'Textile & Handloom', 2.0, 'A Textile Printing Machine operator is responsible for preparation of design screen for printing machine, printing of fabric & smooth operation of machine without damaging either fabric or machine. This job requires the individual to have thorough knowledge of process flow and material flow in a processing mill for fabric production and should know about the important functions and operations of textile printing machine', 270, 270, '201–400', 'Version', '08 May 2025', '08 May 2028', 'Textile Sector Skill Council (TSC)', 'Textile Sector Skill Council', 'Dyeing & Printing', 'Assistant Fitter - Processing', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"75","Practical":"165","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "60", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_57.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-02-TX-04098-2025-V2-TSC', 'Textile Post Processing Machine Operator', 'textile-handloom', 'Textile & Handloom', 2.0, 'A Textile Post Processing Machine Operator is responsible to do the specified job of post processing dyed /bleached, RFD fabric with proper control of parameters to get the desired effect. This job requires the individual to have thorough knowledge of process flow and material flow in a processing mill for fabric production and should know the important functions and operations of textile post processing Machines.', 270, 670, '601–800', 'Version', '08 May 2025', '08 May 2028', 'Textile Sector Skill Council (TSC)', 'Textile Sector Skill Council', 'Textile Finishing', 'Assistant Fitter - Processing', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"75","Practical":"165","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "61", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_57.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-02-TX-04099-2025-V2-TSC', 'Textile Finishing Machine Operator', 'textile-handloom', 'Textile & Handloom', 2.0, 'A Textile Finishing Machine Operator is responsible to do the specified job of drying, heat setting and finishing of fabric with proper control of parameters to get the desired effect. This job requires the individual to have thorough knowledge of process flow and material flow in a processing mill for fabric production and should know the important functions and operations of a finishing machine.', 270, 720, '601–800', 'Version', '08 May 2025', '08 May 2028', 'Textile Sector Skill Council (TSC)', 'Textile Sector Skill Council', 'Textile Finishing', 'Assistant Fitter - Processing', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"75","Practical":"165","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "62", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_57.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-TX-04100-2025-V2-TSC', 'Fitter - Chemical Processing (Textiles)', 'textile-handloom', 'Textile & Handloom', 4.0, 'A Fitter - Chemical Processing (Textiles) is responsible for carrying out maintenance activities of all the machines in processing department like Singeing, CBR, Mercerizing, Drying Range, Jigger, Stenter, Jet dyeing, Soft flow, Calendaring, & finishing machines. He should carry out all the maintenance activities like erecting, dismantling, assembling, leveling, attending & resolving repairs and breakdowns in processing department. He should also carry out regular preventive maintenance activities thus ensuring proper functioning of all machines. This job requires the individual to have thorough knowledge of process flow and material flow in a processing unit for fabric production and should have sound technical knowledge on erecting the different sequence of machines in processing department.', 450, 450, '401–600', 'Version', '08 May 2025', '08 May 2028', 'Textile Sector Skill Council (TSC)', 'Textile Sector Skill Council', 'Maintenance- Processing Machines', 'Supervisor - Processing', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"120","Practical":"300","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "63", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_57.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-TX-04108-2025-V2-TSC', 'Tape Plant Operator', 'textile-handloom', 'Textile & Handloom', 3.0, 'The Tape plant operator is responsible for running the Tape plant under supervision by maintaining health, safety and security in the raffia industry.', 330, 330, '201–400', 'Version', '08 May 2025', '08 May 2028', 'Textile Sector Skill Council (TSC)', 'Textile Sector Skill Council', 'Spinning – Technical Textiles', 'Fitter - Tape Plant Operator', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"90","Practical":"210","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "64", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_57.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
