INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-TX-04110-2025-V2-TSC', 'Circular Loom operator (Shuttle Type)', 'textile-handloom', 'Textile & Handloom', 3.0, 'The Circular loom operator (Shuttle type) is responsible for running the Circular loom (Shuttle type) under supervision by maintaining health, safety and security in the raffia industry.', 330, 330, '201–400', 'Version', '08 May 2025', '08 May 2028', 'Textile Sector Skill Council (TSC)', 'Textile Sector Skill Council', 'Weaving – Technical Textiles', 'Fitter - Circular Loom (Shuttle Type)', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"90","Practical":"210","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "66", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_57.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-02-TX-04111-2025-V2-TSC', 'Jute Selector cum Assorter', 'textile-handloom', 'Textile & Handloom', 2.0, 'The role of a Jute selector cum assorter is to open Jute bale & assort raw jute as per grade, to prepare jute morah of uniform size with due importance to defects & other quality parameters ensuring environmental health and safety aspects. A Jute selector cum assorter can seek employment in a Jute factory.', 270, 270, '201–400', 'Version', '08 May 2025', '08 May 2028', 'Textile Sector Skill Council (TSC)', 'Textile Sector Skill Council', 'Pre-Spinning Operations', 'Assistant Fitter - Jute', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"65","Practical":"175","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "67", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_57.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-02-TX-04112-2025-V2-TSC', 'Jute Carding Operator', 'textile-handloom', 'Textile & Handloom', 2.0, 'A Jute carding operator should be able to operate efficiently the Jute Carding Machine so as to maintain the desired productivity and quality of the carded slivers of jute. A Jute Carding Operator can seek employment in a Jute factory.', 270, 270, '201–400', 'Version', '08 May 2025', '08 May 2028', 'Textile Sector Skill Council (TSC)', 'Textile Sector Skill Council', 'Pre-Spinning Operations', 'Assistant Fitter - Jute', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"65","Practical":"175","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "68", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_57.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-02-TX-04113-2025-V2-TSC', 'Jute Weft Winding Operator', 'textile-handloom', 'Textile & Handloom', 2.0, 'A jute weft winding operator is responsible to operate efficiently the Weft Winding Machine so as to maintain the desired productivity and quality of the Cops of Jute Weft Yarn. A jute weft winding operator can seek employment in a Jute factory.', 270, 270, '201–400', 'Version', '08 May 2025', '08 May 2028', 'Textile Sector Skill Council (TSC)', 'Textile Sector Skill Council', 'Post-Spinning Operations', 'Assistant Fitter - Jute', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"60","Practical":"180","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "69", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_57.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-02-TX-04115-2025-V2-TSC', 'Jute Beaming Operator', 'textile-handloom', 'Textile & Handloom', 2.0, 'The role of a Jute beaming operator is to produce a sized weavers beam containing a wrapped sheet of parallelised wrap yarns of jute from large number of individual spools, according to the number of jute warp yarns required in cloth as per quality and make the weavers beam ready with jute yarns of desired quality. The person can seek employment in a Jute factory.', 270, 270, '201–400', 'Version', '08 May 2025', '08 May 2028', 'Textile Sector Skill Council (TSC)', 'Textile Sector Skill Council', 'Preparatory Weaving', 'Assistant Fitter - Jute', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"82.5","Practical":"157.5","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "70", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_57.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-TX-04285-2025-V1-TSC', 'Operator - Pultrusion (Composites)', 'textile-handloom', 'Textile & Handloom', 3.0, 'The individual at work is responsible for selecting raw materials, right tooling and processes, and ensuring the proper operation of pultrusion machines for the quality manufacturing of Fiber Reinforced Polymer (FRP) products. The key Duties include preparing and mixing resins, monitoring pot life, viscosity of the binding system, and using it within prescribed time, handling and aligning fibers, monitoring and adjusting machine settings, performing quality checks, and adhering to safety protocols to produce high-quality FRP products.', 300, 300, '201–400', 'Version', '08 May 2025', '08 May 2028', 'Textile Sector Skill Council (TSC)', 'Textile Sector Skill Council', 'Technical Textiles', 'Pultrusion supervisor- Composites', 'Apprenticeship Qualification,Future Skills Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"63","Practical":"207","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "71", "qualification_type": "Apprenticeship Qualification,Future Skills Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_57.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-TX-04114-2025-V2-TSC', 'Junior Supervisor - Jute Spinning', 'textile-handloom', 'Textile & Handloom', 4.0, 'The role of a Junior Supervisor – Jute Spinning is to assist the supervisor and to guide the workers for smooth running of jute Spinning and Winding Machines in the Spinning and Winding Departments in jute industry. A Junior Supervisor – Jute Spinning can seek employment in a Jute factory.', 450, 450, '401–600', 'Version', '08 May 2025', '08 May 2028', 'Textile Sector Skill Council (TSC)', 'Textile Sector Skill Council', 'Spinning', 'Supervisor - Jute Spinning', 'Apprenticeship Qualification,General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"120","Practical":"300","EmployabilitySkills":"30","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "72", "qualification_type": "Apprenticeship Qualification,General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_14_57.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/TH/THSC/06410', 'Naturalist (wildlife tourism)', 'tourism-hospitality', 'Tourism & Hospitality', 4.5, 'The primary role is to confidently conduct nature activities like walks and safaris in an ethical and responsible manner in a variety of sites. They lead guests who can have a wide range of interests. Beyond guiding, they strive to broaden interests and encourage guests to adopt sustainable lifestyles.', 750, 750, '601–800', 'Version', '29 Sep 2022', '29 Sep 2025', 'Tourism and Hospitality Skill Council (THSC)', 'Tourism and Hospitality Skill Council', 'Land Based Activities', 'Naturalist (wildlife tourism), Lead Naturalist (wildlife tourism)', 'Future Skills Qualification', 'N.A.', '{"Theory":"156","Practical":"246","EmployabilitySkills":"90","OJT_Mandatory":"258"}', false, '{}'::text[], '{"source_row": "1", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_23.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-TH-00131-2023-V1-THSC', 'Walk Tour Facilitator', 'tourism-hospitality', 'Tourism & Hospitality', 4.0, 'The Walk Tour Facilitator prepares a detailed itinerary and describes the significance of the site with stories and refreshments. the  In case of food walks, the regional cuisine-related story should be given importance.', 450, 450, '401–600', 'Version', '05 Jan 2023', '05 Jan 2026', 'Tourism and Hospitality Skill Council (THSC)', 'Tourism and Hospitality Skill Council', 'Land Based Activities', 'Tour Guide, Tour Manager, General Manager', 'Future Skills Qualification', 'N.A.', '{"Theory":"150","Practical":"240","EmployabilitySkills":"60","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "2", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_23.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-4.5-TH-00143-2023-V1-MSU', 'Rural Tourism Entrepreneur', 'tourism-hospitality', 'Tourism & Hospitality', 4.5, 'This qualification is designed to provide theoretical knowledge and practical skills in rural tourism management such as offering homestay and guided tours to guests.', 540, 540, '401–600', 'Version', '31 Jan 2023', '31 Jan 2026', 'Medhavi Skill University', 'Medhavi Skills University, Sikkim', 'Medhavi Skills University, Sikkim', 'Rural Tourism Village Leader, Hotel Manager, Hotel Owner', 'General Qualification', 'N.A.', '{"Theory":"172","Practical":"308","EmployabilitySkills":"60","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "3", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_23.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-TH-00402-2023-V1-THSC', 'Food styling Photographer', 'tourism-hospitality', 'Tourism & Hospitality', 4.0, 'The individual at work plans, organizes, style, and photograph the food according to the camera perspective. The person can work as a food photographer / food stylist or prop stylist', 480, 480, '401–600', 'Version', '29 Mar 2023', '29 Mar 2026', 'Tourism and Hospitality Skill Council (THSC)', 'Tourism and Hospitality Skill Council', 'Food Production', 'Food styling Photographer, Art Director, Food Photography team/company', 'Future Skills Qualification', 'N.A.', '{"Theory":"150","Practical":"270","EmployabilitySkills":"60","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "4", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_23.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-2.5-TH-00761-2023-V1-THSC', 'Washerman (Dhobi)', 'tourism-hospitality', 'Tourism & Hospitality', 2.5, 'A washerman (dhobi) is  a self-employed  artisan who  work with their hands and provide services of washing and ironing of clothes . They primarily use manual washing techniques, local soaps, wooden stick (thaapi )and coal-based irons in the unorganized sector.', 40, 40, '1–200', 'Version', '14 Sep 2023', '14 Sep 2026', 'Tourism and Hospitality Skill Council (THSC)', 'Tourism and Hospitality Skill Council (THSC)', '---', '---', 'National Occupational Standard', 'N.A.', '{"Theory":"15","Practical":"25","EmployabilitySkills":"00","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "5", "qualification_type": "National Occupational Standard", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_23.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-5.5-TH-01028-2023-V1-MSU', 'Sustainable Tourism Manager', 'tourism-hospitality', 'Tourism & Hospitality', 5.5, 'This is a short-term qualification that prepares individuals to effectively manage and promote sustainable practices within the tourism industry, focusing on environmental, social, and economic impacts.', 570, 570, '401–600', 'Version', '30 Sep 2023', '29 Sep 2026', 'Medhavi Skill University', 'Medhavi Skills University', 'Sustainable Tourism', 'Vertical Progression: Environmental Consultant, Ecotourism Specialist, Sustainable Tourism Consultant, Resort Manager

Horizontal Progression: Local Empowerment Officer, Community Outreach Officer, Sustainable Tourism Development Manager, Sustainable Tourism Certification Manager

Academic Progression: Bachelor/Master''s/Ph.D. in sustainable tourism, environmental management, or sustainable development.', 'General Qualification', 'N.A.', '{"Theory":"150","Practical":"180","EmployabilitySkills":"60","OJT_Mandatory":"180"}', false, '{}'::text[], '{"source_row": "6", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_23.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
