INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-4.5-TH-01827-2024-V1-THSSC', 'Restaurant Service (WorldSkills)', 'tourism-hospitality', 'Tourism & Hospitality', 4.5, 'The restaurant service practitioner provides high quality food and drink service to guests. A food service practitioner generally works in the commercial sector, offering a range of services to customers. There is a direct relationship between the nature and quality of the service required and the payment made by the guest. Therefore, the practitioner has a continuing responsibility to work professionally and interactively with the guest in order to give satisfaction and thus maintain and grow the business. The waiter is the most important person in dealing with guests and creating the right atmosphere in restaurant. It is therefore necessary to have a complete command of serving rules and to know the preparation of special dishes and drinks at the guest’s table or in the bar. Basic requirements are skill and resourcefulness, good manners, good interaction with guests and practical ability.', 510, 510, '401–600', 'Version', '06 Feb 2024', '06 Feb 2026', 'Tourism and Hospitality Skill Council (THSC)', 'Tourism and Hospitality Skill Council
#1216-1220, 12th Floor, Naurang House, Kasturba Gandhi Marg, Connaught Place
New Delhi – 110001, Landline # 011-41608056/8057 Ext.1102', 'Restaurant Service', 'N/A', 'General Qualification', 'N.A.', '{"Theory":"90","Practical":"120","EmployabilitySkills":"00","OJT_Mandatory":"300"}', false, '{}'::text[], '{"source_row": "19", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_23.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-4.5-TH-01825-2024-V1-THSSC', 'Pâtisserie and Confectionery (WORLS SKILLS)', 'tourism-hospitality', 'Tourism & Hospitality', 4.5, 'The Pâtisserie and Confectionery trades have highly skilled professionals who produce a wide range of intricate and predominantly sweet items. They produce various confectionery products such as hand finished chocolates, candies, and petits fours for service in hotels and restaurants or for retail in specialist shops and outlets. Pâtissiers/Confectioners produce a full range of hot and cold desserts, cakes, biscuits, and iced products for service in luxury/boutique hotels, restaurants, and pastry shops for retail sale. They may also produce elaborate display pieces using chocolate, sugar, ice, marzipan, or other decorative materials and ingredients. Some may specialize in producing decorated and themed cakes for special events.', 510, 510, '401–600', 'Version', '06 Feb 2024', '06 Feb 2026', 'Tourism and Hospitality Skill Council (THSC)', 'Tourism and Hospitality Skill Council
#1216-1220, 12th Floor, Naurang House, Kasturba Gandhi Marg, Connaught Place
New Delhi – 110001, Landline # 011-41608056/8057 Ext.1102', 'Food Production and Kitchen', 'N/A', 'General Qualification', 'N.A.', '{"Theory":"78","Practical":"108","EmployabilitySkills":"00","OJT_Mandatory":"324"}', false, '{}'::text[], '{"source_row": "20", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_23.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-4.5-TH-01830-2024-V1-THSSC', 'Hotel Reception (WorldSkills)', 'tourism-hospitality', 'Tourism & Hospitality', 4.5, 'The role of Hotel Receptionist is key to every hotel establishment. At the hotel’s reception area guests receive their first impression of the hotel and therefore of their probable hotel experience. This is where the primary communication with the hotel staff is established. The quality, courtesy and promptness of service can make a great difference, positively or negatively, to the guest’s relationship with the hotel and their satisfaction during their stay. This in turn affects the hotel’s reputation and repeat business.
The Hotel Receptionist works mainly in the hotel’s front office. Hotel receptionists need to use a wide range of skills continuously. These may include knowledge of local and general tourism information, good verbal and written English, computer literacy, good manners and conduct and grooming, excellent communication and social skills, problem solving, competence with figures and cash handling, and the application of procedures for reservations, reception, guest services and check out.', 510, 510, '401–600', 'Version', '06 Feb 2024', '06 Feb 2026', 'Tourism and Hospitality Skill Council (THSC)', 'Tourism and Hospitality Skill Council
#1216-1220, 12th Floor, Naurang House, Kasturba Gandhi Marg, Connaught Place
New Delhi – 110001, Landline # 011-41608056/8057 Ext.1102', 'Front Office Management', 'N/A', 'General Qualification', 'N.A.', '{"Theory":"96","Practical":"114","EmployabilitySkills":"00","OJT_Mandatory":"300"}', false, '{}'::text[], '{"source_row": "21", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_23.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-4.5-TH-01826-2024-V1-THSSC', 'Cooking  (WORLD SKILLS)', 'tourism-hospitality', 'Tourism & Hospitality', 4.5, 'The professional chef can work in a wide range of establishments including high-class and casual restaurants, hotels, welfare caterings such as hospitals and residential homes, theme parks, airlines, ships, clubs, retail HMR and Food To-Go, Fast Food outlets, and industrial canteens; providing catering services to both guests and staff. The range of skills and customer expectations will vary according to the workplace. There is also a direct relationship between the nature and quality of the service provided and the payment made by the customer. The professional chef can also deliver different styles of dining such as fine dining, banqueting, casual dining, cocktail dining, canteen and take-away dining, as well as different styles of food service including plated, a la carte, and set menu service,', 510, 510, '401–600', 'Version', '06 Feb 2024', '06 Feb 2026', 'Tourism and Hospitality Skill Council (THSC)', 'Tourism and Hospitality Skill Council
1216-1220, 12th Floor, Naurang House, Kasturba Gandhi Marg, Connaught Place
New Delhi – 110001, Landline # 011-41608056/8057 Ext.1102', 'Food Production and Kitchen', 'N/A', 'General Qualification', 'N.A.', '{"Theory":"84","Practical":"120","EmployabilitySkills":"00","OJT_Mandatory":"306"}', false, '{}'::text[], '{"source_row": "22", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_23.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-4.5-TH-01829-2024-V1-THSSC', 'Bakery (WorldSkills)', 'tourism-hospitality', 'Tourism & Hospitality', 4.5, 'The baker is a highly skilled professional, with a high level of knowledge about food and nutrition, who produces a wide range of bread and pastry items.
The baker produces all varieties of fresh and tasty bakery products, made of any kind of grains. Different types of fermentation and other processes will be used to turn the raw material into sweet or savory products. For example, wheat bread, rye bread, artisan bread, enriched breads, laminated products, and ingredients to flavor their bakery products. Bakers also produces elaborate displays of decorative breads using creative skills and knowledge.', 510, 510, '401–600', 'Version', '26 Jan 2024', '26 Jan 2026', 'Tourism and Hospitality Skill Council (THSC)', 'Tourism and Hospitality Skill Council', 'Food Production & Kitchen', 'N/A', 'General Qualification', 'N.A.', '{"Theory":"102","Practical":"102","EmployabilitySkills":"00","OJT_Mandatory":"306"}', false, '{}'::text[], '{"source_row": "23", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_23.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
