INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-TH-02437-2024-V2-THSC', 'Assistant Rafting Guide', 'tourism-hospitality', 'Tourism & Hospitality', 3.0, 'An assistant rafting guide is responsible for assisting the rafting guide or senior rafting guide in carrying out the rafting activity, loading, unloading and maintaining the equipment. The assistant rafting guide should have adequate knowledge of river reading, guest management, first-aid and the ability to guide at least Class 2-3 white water.', 360, 360, '201–400', 'Version', '30 Apr 2024', '30 Apr 2027', 'Tourism and Hospitality Skill Council (THSC)', 'Tourism and Hospitality Skill Council', 'Water Based Activities', 'Rafting Guide/ Safety Kayaker', 'General Qualification', 'N.A.', '{"Theory":"90","Practical":"150","EmployabilitySkills":"30","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "60", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_23.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-TH-02460-2024-V2-THSC', 'Cafeteria Incharge (Small  Establishments)', 'tourism-hospitality', 'Tourism & Hospitality', 4.0, 'The individual at work receives a variety of food items and displays them for sale, serves the guests, and
manages day-to-day operations of the cafeteria. The person also arranges for resources and supervises the on-site catering operations', 480, 480, '401–600', 'Version', '30 Apr 2024', '30 Apr 2027', 'Tourism and Hospitality Skill Council (THSC)', 'Tourism and Hospitality Sector Skill Council', 'Catering Services', 'Vertical Progression - Restaurant Manager', 'General Qualification', 'N.A.', '{"Theory":"140","Practical":"130","EmployabilitySkills":"60","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "61", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_23.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-TH-02439-2024-V2-THSC', 'Adventure Travel Guide (Low Altitude)', 'tourism-hospitality', 'Tourism & Hospitality', 4.0, 'An adventure travel guide (low altitude) is responsible for coordination with local logistics, transportation, route finding, navigating and leading small groups across various terrains like desserts, forests, hills and mountains (up to 4,000 mts), in consultation with the trek leader. Usually a local, a adventure travel guide / low altitude trekking guide is well acquainted with the flora, fauna, culture and natural history of a particular region. An adventure travel guide ensures that the safety of the group is maintained while on the route.', 480, 480, '401–600', 'Version', '30 Apr 2024', '30 Apr 2027', 'Tourism and Hospitality Skill Council (THSC)', 'Tourism and Hospitality sector Skill council', 'Mountain Based Activities', 'Adventure Travel Guide ( High Altitude)', 'General Qualification', 'N.A.', '{"Theory":"60","Practical":"150","EmployabilitySkills":"30","OJT_Mandatory":"240"}', false, '{}'::text[], '{"source_row": "62", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_23.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-TH-02447-2024-V2-THSC', 'Himalayan Expedition Pathfinder /HAP', 'tourism-hospitality', 'Tourism & Hospitality', 5.0, 'A Himalayan Expedition Pathfinder (HAP) is responsible for carrying equipment, gear and provisions for trekking and mountaineering expeditions in high altitude regions beyond 4,500 metres. They are qualified mountaineers and assist the high altitude trekking guide/mountaineering instructor with setting up ropes and equipment on technical sections of the route.', 570, 570, '401–600', 'Version', '30 Apr 2024', '30 Apr 2027', 'Tourism and Hospitality Skill Council (THSC)', 'Tourism and Hospitality Sector Skill council', 'Mountain Based Activities', 'Mountaineering Instructor', 'General Qualification', 'N.A.', '{"Theory":"190","Practical":"200","EmployabilitySkills":"60","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "63", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_23.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-TH-02440-2024-V2-THSC', 'Jr. Instructor Rope activities', 'tourism-hospitality', 'Tourism & Hospitality', 4.0, 'An instructor is responsible for conducting the particular activity safely in a controlled and evaluated environment. They supervise and guide the assistant instructors in ropes/cable set up for rock climbing and abseiling, zip lines, high ropes course/low ropes course/challenge course, assessing the condition of the climbing ropes and cables, equipment maintenance, instructing and coaching the tourists on the procedures and techniques of the climb and ensuring the safety of the students/clients.', 420, 420, '401–600', 'Version', '30 Apr 2024', '30 Apr 2027', 'Tourism and Hospitality Skill Council (THSC)', 'Tourism and Hospitality Sector Skill Council', 'Rope Courses', 'Adventure Travel Guide (Low Altitude)', 'General Qualification', 'N.A.', '{"Theory":"90","Practical":"150","EmployabilitySkills":"60","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "64", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_23.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-4.5-TH-02444-2024-V2-THSC', 'Mountain Cuisine Chef', 'tourism-hospitality', 'Tourism & Hospitality', 4.5, 'A mountain cuisine chef is responsible for planning and cooking daily meals for the trekkers/climbers during a trek, raft trip or climbing expedition. The person is responsible for managing the kitchen helpers, cooking stations and ration supplies at every campsite during the trek.', 600, 600, '401–600', 'Version', '30 Apr 2024', '30 Apr 2027', 'Tourism and Hospitality Skill Council (THSC)', 'Tourism and Hospitality Sector Skill Council', 'Mountain Based Activities', 'Himalayan Expedition Pathfinder /HAP', 'General Qualification', 'N.A.', '{"Theory":"150","Practical":"240","EmployabilitySkills":"60","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "65", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_23.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-4.5-TH-02446-2024-V2-THSC', 'Adventure Travel Guide (High Altitude)', 'tourism-hospitality', 'Tourism & Hospitality', 4.5, 'A high altitude trekking guide is usually a local who is well acquainted with the flora, fauna, culture and natural history of a particular area or region especially at high altitudes, (4,000 mts and above) trained in advanced mountaineering and wilderness first aid. The guide is responsible for route finding, navigation, leading small groups in the mountains and assisting the expedition leader in carrying out the trekking or mountaineering expedition. A high altitude trekking guide is also responsible for coordination with local logistics, transportation, porters, pony men, etc., in consultation with the trip/expedition leader.', 420, 420, '401–600', 'Version', '30 Apr 2024', '30 Apr 2027', 'Tourism and Hospitality Skill Council (THSC)', 'Tourism and Hospitality sector skill council', 'Mountain based Activities', 'Mountaineering Instructor', 'General Qualification', 'N.A.', '{"Theory":"60","Practical":"120","EmployabilitySkills":"60","OJT_Mandatory":"180"}', false, '{}'::text[], '{"source_row": "66", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_23.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-4.5-TH-02445-2024-V2-THSC', 'Paragliding Tandem Pilot', 'tourism-hospitality', 'Tourism & Hospitality', 4.5, 'A paragliding tandem pilot is responsible for taking one student/client at a time on an assisted paragliding flight in a controlled and evaluated environment. They plan and prepare for the flight and are responsible for flying along with the student/client while ensuring their safety.', 630, 630, '601–800', 'Version', '30 Apr 2024', '30 Apr 2027', 'Tourism and Hospitality Skill Council (THSC)', 'Tourism and Hospitality Sector Skill Council', 'Air based Activities', 'HAP', 'General Qualification', 'N.A.', '{"Theory":"90","Practical":"180","EmployabilitySkills":"60","OJT_Mandatory":"300"}', false, '{}'::text[], '{"source_row": "67", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_23.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-TH-02438-2024-V2-THSC', 'Parasailing (Equipment) Driver', 'tourism-hospitality', 'Tourism & Hospitality', 3.0, 'A parasailing (equipment) driver is an experienced vehicle or boat driver who is responsible for towing parasailing students/clients to a certain height and bringing them down safely. The parasailing (equipment) driver works in close coordination with the parasailing supervisor who visually supervises the parasailing activity.', 360, 360, '201–400', 'Version', '30 Apr 2024', '30 Apr 2027', 'Tourism and Hospitality Skill Council (THSC)', 'Tourism and Hospitality Sector Skill Council', 'Water Based Activities', 'Parasailing Supervisor', 'General Qualification', 'N.A.', '{"Theory":"90","Practical":"180","EmployabilitySkills":"30","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "68", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_23.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-TH-02450-2024-V2-THSC', 'Parasailing (Equipment) Supervisor', 'tourism-hospitality', 'Tourism & Hospitality', 5.0, 'A Parasailing (Equipment) Supervisor is responsible teaching as well as for safely conducting a parasailing activity for students/clients by monitoring the sources of danger at land/deck, sea and air during every flight. The supervisor works in close coordination with the driver, launcher and receiver. In addition, a Parasailing (Equipment) Supervisor is also responsible for training the staff.', 630, 630, '601–800', 'Version', '30 Apr 2024', '30 Apr 2027', 'Tourism and Hospitality Skill Council (THSC)', 'Tourism and Hospitality Sector Skill Council', 'Water Based Activities', 'This is the Highest position in Parasailing', 'General Qualification', 'N.A.', '{"Theory":"100","Practical":"200","EmployabilitySkills":"60","OJT_Mandatory":"270"}', false, '{}'::text[], '{"source_row": "69", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_23.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-TH-02459-2024-V2-THSC', 'Billing Executive (Facility Management)', 'tourism-hospitality', 'Tourism & Hospitality', 4.0, 'The individual at work manages and maintains accounts payable and receivables, calculates, prepares and processes bills and invoices, maintains budgets and other financial records and issues cheques, and receives payments.', 480, 480, '401–600', 'Version', '30 Apr 2024', '30 Apr 2027', 'Tourism and Hospitality Skill Council (THSC)', 'Tourism and Hospitality Sector Skill Council', 'Property Management Executive', 'Facility Management Executive', 'General Qualification', 'N.A.', '{"Theory":"105","Practical":"165","EmployabilitySkills":"60","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "70", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_23.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-TH-02965-2024-V1-MUR', 'Travel Coordinator', 'tourism-hospitality', 'Tourism & Hospitality', 5.0, 'Travel Coordinator, also known as a travel agent or advisor, is a professional responsible for helping individuals and organizations plan and book their travel experiences. They provide expert advice, make travel arrangements, and ensure that clients have smooth and enjoyable journeys. This includes booking flights, accommodations, ground transportation, tours, and activities, while considering factors such as budget, preferences, and special needs. Travel Coordinators stay updated on travel industry trends, regulations, and destination information to provide the best possible guidance to their clients, making their travel dreams a reality while ensuring a memorable and hassle-free experience.', 630, 630, '601–800', 'Version', '27 Aug 2024', '26 Aug 2027', 'Mewar University', 'Mewar University', 'Travel Coordinator', 'Senior Travel Coordinator, Team Lead or Supervisor, Travel Manager, Entrepreneur', 'General Qualification', 'N.A.', '{"Theory":"160","Practical":"320","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "71", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_23.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-4.5-TH-02966-2024-V1-MUR', 'Culinary Assistant', 'tourism-hospitality', 'Tourism & Hospitality', 4.5, 'Culinary Assistant is a professional responsible for the planning, preparation, and execution of culinary creations in a variety of culinary establishments such as restaurants, hotels, and catering services. They are skilled in culinary techniques, menu planning, and food presentation, ensuring the quality, taste, and safety of dishes while leading kitchen teams, managing kitchen operations, and adhering to food safety regulations. Culinary Assistants create and innovate menus, maintain high standards of food quality and presentation, and contribute to the overall dining experience for customers.', 570, 570, '401–600', 'Version', '27 Aug 2024', '26 Aug 2027', 'Mewar University', 'Mewar University, NH - 48 Gangrar, Chittorgarh, Rajasthan-312901 www.mewaruniversity.org', 'Culinary Assistant', 'Commis Chef, Demis Chef de Partie, Chef de Partie, Sous Chef, Head Chef, Executive Chef, Entrepreneur', 'General Qualification', 'N.A.', '{"Theory":"120","Practical":"330","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "72", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_23.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-TH-02967-2024-V1-MUR', 'Assistant Housekeeper (Hospitality)', 'tourism-hospitality', 'Tourism & Hospitality', 4.0, 'Assistant Housekeeper (Hospitality) is responsible for ensuring the cleanliness, comfort, and hygiene of guest rooms, common areas, and facilities in a hotel. Their duties typically include cleaning and sanitizing rooms, making beds, replenishing supplies, managing inventory, and upholding high cleanliness and safety standards to provide guests with a pleasant and welcoming stay.', 540, 540, '401–600', 'Version', '27 Aug 2024', '26 Aug 2027', 'Mewar University', 'Mewar University, NH - 48 Gangrar, Chittorgarh, Rajasthan-312901 www.mewaruniversity.org', 'Assistant Housekeeper (Hospitality)', 'Housekeeper (Hospitality), Housekeeping Supervisor, Assistant Housekeeping Manager, Housekeeping Manager, Entrepreneur', 'General Qualification', 'N.A.', '{"Theory":"120","Practical":"270","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "73", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_23.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-TH-02968-2024-V1-MUR', 'Assistant Tourist Guide', 'tourism-hospitality', 'Tourism & Hospitality', 4.0, 'Assistant Tourist Guide; guides tourists and visitors to places of interest and explains historical background and importance of site. Accompanies tourists on their excursions to and around places of tourist interest and explains historical, cultural, social, religious and architectural significance of monuments. Answers questions of tourists relating to various economic and social aspects of life or people. May assist tourists in shopping. May act as interpreter to tourists to converse with people and or shopkeepers, hoteliers, etc.', 540, 540, '401–600', 'Version', '27 Aug 2024', '26 Aug 2027', 'Mewar University', 'Mewar University, NH - 48 Gangrar, Chittorgarh, Rajasthan-312901 www.mewaruniversity.org', 'Assistant Tourist Guide', 'Tourist Guide, Travel Consultant, Tour Manager/Director, Entrepreneur', 'General Qualification', 'N.A.', '{"Theory":"80","Practical":"310","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "74", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_23.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-TH-00621-2023-V1-SVSU.', 'Indian Traditional Food Maker', 'tourism-hospitality', 'Tourism & Hospitality', 4.0, 'Indian Traditional Food Maker is responsible for producing traditional Indian food as per standard and carry out other associated tasks to support the same.', 630, 630, '601–800', 'Version', '23 Jun 2023', '23 Jun 2026', 'Shri Vishwakarma Skill University', 'Shri Vishwakarma Skill Universities', 'Commis Indian Kitchen', 'Commis III Indian Kitchen, Commis II Indian Kitchen, Commis I Indian Kitchen, CDP Indian Kitchen', 'General Qualification', 'N.A.', '{"Theory":"90","Practical":"390","EmployabilitySkills":"90","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "75", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_23.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-04-TH-03367-2024-V1-THSC', 'Basics of Hospitality Etiquettes', 'tourism-hospitality', 'Tourism & Hospitality', 4.0, 'This Micro Credential provides customer representatives with essential skills and knowledge in hospitality etiquette. Participants will learn the principles of professional conduct, effective communication, and cultural sensitivity to enhance customer interactions. Through interactive sessions and real-world scenarios, attendees will gain the tools to create positive customer experiences, handle challenging situations gracefully, and uphold the highest standards of service excellence in all customer service-oriented sectors.', 18, 18, '1–200', 'Version', '22 Oct 2024', '22 Oct 2027', 'Tourism and Hospitality Skill Council (THSC)', 'Tourism and Hospitality Skil Council', 'Customer service', 'Customer Service Representatives, Showroom/Dealership staff, Customer care executives', 'General Qualification,Micro Credentials', 'N.A.', '{"Theory":"6","Practical":"12","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "76", "qualification_type": "General Qualification,Micro Credentials", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_23.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-02-TH-02598-2024-V2-RUDSETI', 'Laghu Udyami (Fast Food Stall)', 'tourism-hospitality', 'Tourism & Hospitality', 2.0, 'The Fast-Food Stall Udyami course provides essential skills and knowledge to aspiring entrepreneurs in the food service industry. By covering topics such as food preparation, hygiene, inventory management, financial planning, and marketing, the course empowers individuals to establish and operate successful fast-food businesses.', 90, 90, '1–200', 'Version', '03 Mar 2017', '30 May 2027', 'National Academy of RUDSETI, Karnataka', 'Assessment Body- NAR', 'Run a Fast-Food stall', 'Food Delivery Services and Partner with Apps, Catering Services, Multiple Outlets , Fast-food chain', 'National Occupational Standard', 'N.A.', '{"Theory":"15","Practical":"30","EmployabilitySkills":"30","OJT_Mandatory":"15"}', false, '{}'::text[], '{"source_row": "77", "qualification_type": "National Occupational Standard", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_23.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-TH-03208-2024-V2-DGT', 'CATERING & HOSPITALITY', 'tourism-hospitality', 'Tourism & Hospitality', 4.0, 'The individual will be able to impart theoretical instructions, demonstrate practical skills, evaluate and grade trainees of Catering & Hospitality and related trade in industrial workshops, ITIs/Vocational Training Institutes etc.', 1350, 1350, '1201–2400', 'Version', '22 Oct 2024', '21 Oct 2027', 'Directorate General of Training (DGT)', 'DGT', 'Working Proprietor, Lodging and Catering Services, Manual Training Teacher/Craft Instructor, Cook, Institutional, Cook, Domestic, Cook, Ship, Cooks, Other, Baker (Baking Products),  Bakers, Pastry Cooks and Confectionery Makers, Other, Receptionist (Hotel)/Front Office Associate, Steward, Hotel, Housekeeper (Domestic)', 'Technical Instructor in a vocational training Institute/ technical Institution, Supervisor in Industries', 'General Qualification', 'N.A.', '{"Theory":"450","Practical":"750","EmployabilitySkills":"0","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "78", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_23.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-02-TH-02436-2024-V2-THSC', 'Camping Assistant', 'tourism-hospitality', 'Tourism & Hospitality', 2.0, 'A Camping Assistant is a staff member present on a fixed campsite, expedition or a trek. The prime responsibility of a camping assistant is to set up the campsite with tents and dismantle them, cater to the requirements of tourists at a campsite, as well as help in the kitchen. A camping assistant also ensures that a clean and hygienic environment is maintained at the campsite and during expeditions.', 240, 240, '201–400', 'Version', '30 Apr 2024', '30 Apr 2027', 'Tourism and Hospitality Skill Council (THSC)', 'Tourism and Hospitality Skill Council', 'Mountain-Based Activities', 'Adventure Travel Guide (Low Altitude)', 'General Qualification', 'N.A.', '{"Theory":"80","Practical":"70","EmployabilitySkills":"30","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "79", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_23.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
