INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/TLW/LSC/06379', 'Land Transportation Executive', 'transportation-logistics-warehousing', 'Transportation, Logistics & Warehousing', 4.0, 'The individual will collect order information, conduct analysis of past trends; follow-up with trucking companies, coordinate with client; consolidate orders according to destination and monitor all consignments in real time', 510, 690, '601–800', 'Version', '25 Aug 2022', '25 Aug 2025', 'Logistics Sector Skill Council (LSC)', 'Logistics Sector Skill Council', 'Transport Operations, Vehicle Operations, Documentation and Reporting', 'Land transportation supervisor', 'Future Skills Qualification', 'N.A.', '{"Theory":"170","Practical":"250","EmployabilitySkills":"60","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "3", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_31.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('2022/TLW/LSC/06373', 'Supply Chain Associate', 'transportation-logistics-warehousing', 'Transportation, Logistics & Warehousing', 3.0, 'The individual performs basic picking, kitting, binning, sequencing, line feeding, loading, and unloading activities in the in-plant warehouse. S/he will operate manual/battery operated pallet truck (MHE), will engage in inventory counts and maintain the in-plant warehouse.', 360, 660, '601–800', 'Version', '25 Aug 2022', '25 Aug 2025', 'Logistics Sector Skill Council (LSC)', 'Logistics Sector Skill Council', 'In-plant logistics, Transport Management', 'Supply Chain Executive', 'Future Skills Qualification', 'N.A.', '{"Theory":"130","Practical":"170","EmployabilitySkills":"30","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "4", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_31.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
