INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-TW-00234-2023-V1-LSC', 'Warehouse Executive', 'transportation-logistics-warehousing', 'Transportation, Logistics & Warehousing', 4.0, 'The individual is responsible for updating warehouse data into the ERP system, prepare reports, analyse of data for trends, prepare forecasts, print labels, and coordinate with line functions to ensure seamless operation of warehouse functions', 510, 570, '401–600', 'Version', '28 Feb 2023', '28 Feb 2026', 'Logistics Sector Skill Council (LSC)', 'Logistics Sector Skill Council', 'Warehouse operations ,Documentation and Reporting', 'Warehouse Supervisor', 'Future Skills Qualification', 'N.A.', '{"Theory":"170","Practical":"250","EmployabilitySkills":"60","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "19", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_31.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-TW-00407-2023-V1-LSC', 'Commercial Vehicle Driver - LMO', 'transportation-logistics-warehousing', 'Transportation, Logistics & Warehousing', 4.0, 'Individuals are expected to drive the Liquid Medical Oxygen (LMO) tankers safely and efficiently on the assigned route. This role requires the individual to handle hazardous material and liquid medical oxygen.
S/he should be able to handle most of the routine break downs that could likely be encountered while driving long distances and through difficult terrains. The individual is also expected to achieve other key performance parameters such as fuel efficiency, on time delivery etc', 510, 510, '401–600', 'Version', '28 Feb 2023', '28 Feb 2026', 'Logistics Sector Skill Council (LSC)', 'Logistics Sector Skill Council', 'Vehicle/Transport Operations', 'Land Transportation Supervisor', 'General Qualification', 'N.A.', '{"Theory":"100","Practical":"250","EmployabilitySkills":"60","OJT_Mandatory":"100"}', false, '{}'::text[], '{"source_row": "20", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_31.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-TW-00232-2023-V1-LSC', 'Supply Chain Supervisor¬- Agri Commodities', 'transportation-logistics-warehousing', 'Transportation, Logistics & Warehousing', 5.0, 'The individual is responsible for supervising the day to day operations at the facility by allocating resources, managing activities, and coordinating with clients and upper management/regulatory bodies. S/he is also responsible for measuring and reporting the effectiveness of daily assigned activities and employees'' performance', 630, 870, '801–1000', 'Version', '28 Feb 2023', '28 Feb 2026', 'Logistics Sector Skill Council (LSC)', 'Logistics Sector Skill Council', 'Supply Chain Operations, Distribution Chain Management, Customer relationship management', 'Supply Chain Manager', 'Multi-Skill Qualification', 'N.A.', '{"Theory":"210","Practical":"330","EmployabilitySkills":"60","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "21", "qualification_type": "Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_31.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-TW-00233-2023-V1-LSC', 'Warehouse Associate', 'transportation-logistics-warehousing', 'Transportation, Logistics & Warehousing', 3.0, 'The individual performs basic/advanced picking, packing, labelling, kitting, binning, VAS loading and unloading activities in a warehouse. S/he will operate manual/battery operated pallet truck (MHE) along with using IT systems like RF guns, smart mobiles etc, will engage in inventory counts and maintaining warehouse work area clean', 480, 780, '601–800', 'Version', '28 Feb 2023', '28 Feb 2026', 'Logistics Sector Skill Council (LSC)', 'Logistics Sector Skill Council', 'Warehousing Operations', 'Professional – Upon successful completion of course and after gaining 2 to 3 years of experience, the person can have vertical progression as Warehouse Executive.
Academic – Candidate to clear Class XII through open school and proceed further to Diploma or Graduate and then to Post graduate', 'Future Skills Qualification', 'N.A.', '{"Theory":"170","Practical":"250","EmployabilitySkills":"30","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "22", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_31.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-TW-00235-2023-V1-LSC', 'Warehouse Supervisor', 'transportation-logistics-warehousing', 'Transportation, Logistics & Warehousing', 5.0, 'The individual supervises day-to-day operations at a warehouse by allocating resources, managing activities and coordinating with clients and regulatory bodies. S/he is also responsible for measuring and reporting the effectiveness of warehousing activities and employees’ performance.', 600, 960, '801–1000', 'Version', '28 Feb 2023', '28 Feb 2026', 'Logistics Sector Skill Council (LSC)', 'Logistics Sector Skill Council', 'Warehousing operations, Packaging, Documentation and Reporting', 'Warehouse Manager', 'Future Skills Qualification', 'N.A.', '{"Theory":"160","Practical":"350","EmployabilitySkills":"60","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "23", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_31.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-TW-00229-2023-V1-LSC', 'Courier Executive - Operations', 'transportation-logistics-warehousing', 'Transportation, Logistics & Warehousing', 4.0, 'The individual is responsible for resolving customer queries by co-ordinating with various departments, feeding data into Enterprise Resource Planning (ERP) and analysing them to generate reports. S/he will also undertake retail and institutional sales for courier and provide support for custom clearances for shipments.', 540, 600, '401–600', 'Version', '28 Feb 2023', '28 Feb 2026', 'Logistics Sector Skill Council (LSC)', 'Logistics Sector Skill Council', 'Customer relationship management, Institutional sales, Branch sales, Hub/branch Operations, Documentation and Reporting', 'Courier Supervisor - Operations', 'Multi-Skill Qualification', 'N.A.', '{"Theory":"160","Practical":"290","EmployabilitySkills":"60","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "24", "qualification_type": "Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_31.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-TW-00369-2023-V1-LSC & 1.0', 'Drone Operator – Over Dimensional Cargo', 'transportation-logistics-warehousing', 'Transportation, Logistics & Warehousing', 4.0, 'A Drone Operator - Over Dimensional Cargo (ODC) is responsible for using drones to ensure safety during the transportation of ODC. The individual monitors ODC during its loading, unloading and transit. The person identifies the relevant risks during ODC''s handling and transit and supports in mitigating them. The individual also performs the regular repair and maintenance of drones to keep them operational.', 540, 540, '401–600', 'Version', '03 May 2023', '03 May 2026', 'Logistics Sector Skill Council (LSC)', 'Logistics Sector Skill Council', 'Engineering/Maintenance, Transport Operations', 'Drone Supervisor - ODC', 'Future Skills Qualification', 'N.A.', '{"Theory":"140","Practical":"310","EmployabilitySkills":"60","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "25", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_31.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-TW-00370-2023-V1-LSC & 1.0', 'Drone Operator – Warehouse', 'transportation-logistics-warehousing', 'Transportation, Logistics & Warehousing', 4.0, 'A Drone Operator - Warehouse is responsible for using drones in warehouse logistics operations, such as  inventory management and security surveillance. The individual assembles and prepares the drone for use, performs drone flight simulation and test flight, and maintains the drone in working condition through regular maintenance. The person also collects, analyzes and utilizes relevant data, and follows the appropriate health and safety measures in drone operations.', 510, 570, '401–600', 'Version', '03 May 2023', '03 May 2026', 'Logistics Sector Skill Council (LSC)', 'Logistics Sector Skill Council', 'Engineering/Maintenance, Warehousing Operations', 'Drone Supervisor - Warehouse', 'Future Skills Qualification', 'N.A.', '{"Theory":"120","Practical":"240","EmployabilitySkills":"60","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "26", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_31.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-06-TW-00378-2023-V1-LSC & 1.0', 'Functional Analyst - TMS', 'transportation-logistics-warehousing', 'Transportation, Logistics & Warehousing', 6.0, 'The individual is responsible for working on the Functional and Technical Design of the Transportation Management System. The individual is also responsible for working with Transportation Planners to define the operation process and enabling users to consume Software. The individual should be able to define different user guides used by end users of Transport Management System end users.', 660, 660, '601–800', 'Version', '03 May 2023', '03 May 2026', 'Logistics Sector Skill Council (LSC)', 'Logistics Sector Skill Council', 'Technology, Transport Operations', 'Senior Functional Analyst - TMS', 'Future Skills Qualification', 'N.A.', '{"Theory":"160","Practical":"380","EmployabilitySkills":"90","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "27", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_31.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-06-TW-00377-2023-V1-LSC & 1.0', 'Functional Analyst - WMS', 'transportation-logistics-warehousing', 'Transportation, Logistics & Warehousing', 6.0, 'The individual is responsible for working on the Functional and Technical Design of Warehouse Management System. Individual is also responsible for working with Warehouse End user to define the operation process and enabling users to consume Software. Individual should be able to define different user guides used by warehouse end users.', 660, 660, '601–800', 'Version', '03 May 2023', '03 May 2026', 'Logistics Sector Skill Council (LSC)', 'Logistics Sector Skill Council', 'Technology, Warehousing Operations', 'Senior Functional Analyst - WMS', 'Future Skills Qualification', 'N.A.', '{"Theory":"160","Practical":"380","EmployabilitySkills":"90","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "28", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_31.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-TW-00867-2023-V1-LSC & 1.0', 'Cargo Vehicle Driver (Non-hazardous goods)', 'transportation-logistics-warehousing', 'Transportation, Logistics & Warehousing', 4.0, 'Individuals are expected to drive the cargo vehicles safely and efficiently on the assigned route. S/he should be able to undertake most of the routine maintenance of the vehicle and handle hassles that could likely be encountered while driving long distances and through difficult terrains. The individual is also expected to achieve other key performance parameters such as fuel efficiency, on-time delivery etc.', 360, 540, '401–600', 'Version', '31 Aug 2023', '31 Aug 2026', 'Logistics Sector Skill Council (LSC)', 'Logistics Sector Skill Council', 'Vehicle Operations, Transport Operations', 'Cargo fleet supervisor', 'General Qualification', 'N.A.', '{"Theory":"150","Practical":"210","EmployabilitySkills":"30","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "29", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_31.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-TW-00864-2023-V1-LSC & 1.0', 'Container Repair and Maintenance Supervisor', 'transportation-logistics-warehousing', 'Transportation, Logistics & Warehousing', 5.0, 'The individual is responsible for the overall quality of the survey, repairs and maintenance of all the empty containers that come into the depot.', 600, 720, '601–800', 'Version', '31 Aug 2023', '31 Aug 2026', 'Logistics Sector Skill Council (LSC)', 'Logistics Sector Skill Council', 'Engineering/Maintenance, Port Operations Coordination', 'Container repair and maintenance Manager', 'General Qualification', 'N.A.', '{"Theory":"190","Practical":"320","EmployabilitySkills":"60","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "30", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_31.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-06-TW-00866-2023-V1-LSC & 1.0', 'Packaging Designer', 'transportation-logistics-warehousing', 'Transportation, Logistics & Warehousing', 6.0, 'The Packaging Designer is responsible for designing tertiary packaging - after considering the shape, size, weight, volume & orientation of the item to be packed - to safeguard the product, post manufacturing till delivery to the seller. The individual is responsible for conceptualizing, designing, and building a prototype with packaging materials, considering additional elements such as logistics cost, transit type, time, weather, client specifications etc., to create functional and sustainable packaging.', 660, 780, '601–800', 'Version', '31 Aug 2023', '31 Aug 2026', 'Logistics Sector Skill Council (LSC)', 'Logistics Sector Skill Council', 'Packaging, Engineering, Technology', 'Senior Packaging Designer', 'Future Skills Qualification', 'N.A.', '{"Theory":"180","Practical":"360","EmployabilitySkills":"90","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "31", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_31.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-TW-00865-2023-V1-LSC & 1.0', 'E-commerce Delivery Associate', 'transportation-logistics-warehousing', 'Transportation, Logistics & Warehousing', 3.0, 'E-commerce Delivery Associate delivers packages to customers every day. As a delivery associate, the job role involves delivering packages to homes, retail locations, and other delivery locations. S/he is expected to keep up commitments by exceeding customer expectation and ensuring that customer orders, large or small, are delivered on time at the right place.', 360, 540, '401–600', 'Version', '31 Aug 2023', '31 Aug 2026', 'Logistics Sector Skill Council (LSC)', 'Logistics Sector Skill Council', 'Fulfilment Centre Operations', 'E-commerce operations associate', 'Multi-Skill Qualification', 'N.A.', '{"Theory":"130","Practical":"170","EmployabilitySkills":"30","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "32", "qualification_type": "Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_31.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-TW-01358-2023-V1-LSC', 'E-commerce Micro Entrepreneur', 'transportation-logistics-warehousing', 'Transportation, Logistics & Warehousing', 4.0, 'E-commerce Micro Entrepreneur sells products manufactured by self or by self-help groups, small-scale industries etc. on e-commerce platforms. S/he will handle the end-to-end process, from branding to cataloguing to delivery to the end consumer.', 480, 480, '401–600', 'Version', '30 Nov 2023', '30 Nov 2026', 'Logistics Sector Skill Council (LSC)', 'Logistics Sector Skill Council', 'Entrepreneur, Product Design / Catalogue management', 'E-commerce entrepreneur (Small scale)', 'Cross Sectoral Qualification', 'N.A.', '{"Theory":"140","Practical":"280","EmployabilitySkills":"30","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "33", "qualification_type": "Cross Sectoral Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_31.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-4.5-TW-01356-2023-V1-LSC & 1.0', 'Rail Logistics Executive', 'transportation-logistics-warehousing', 'Transportation, Logistics & Warehousing', 4.5, 'Rail Logistics Executive is responsible for managing the flow of goods and resources of the railway operations, overseeing every stage of the supply chain process - from procurement of goods to shipment and delivery. The individual must have effective communication skills and ensure a larger shift of freight on railways in accordance with the National Logistics Policy.', 510, 510, '401–600', 'Version', '30 Nov 2023', '30 Nov 2026', 'Logistics Sector Skill Council (LSC)', 'Logistics Sector Skill Council', 'Private Freight Terminal Operations, Container Train Operations', 'Rail Logistics Supervisor', 'Future Skills Qualification', 'N.A.', '{"Theory":"150","Practical":"270","EmployabilitySkills":"60","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "34", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_31.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-06-TW-01357-2023-V1-LSC & 1.0', 'Warehouse Data Analyst', 'transportation-logistics-warehousing', 'Transportation, Logistics & Warehousing', 6.0, 'The individual is responsible for working on the warehouse monitoring, reporting, data analysis and bringing business insights into the processes ensuring the warehouse operations improve on a continuous basis.', 630, 630, '601–800', 'Version', '30 Nov 2023', '30 Nov 2026', 'Logistics Sector Skill Council (LSC)', 'Logistics Sector Skill Council', 'Technology', 'Senior Warehouse Data Analyst', 'Future Skills Qualification', 'N.A.', '{"Theory":"165","Practical":"345","EmployabilitySkills":"90","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "35", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_31.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-5.5-TW-02038-2024-V1-LSSC & 1.0', 'Multimodal Transport Planner', 'transportation-logistics-warehousing', 'Transportation, Logistics & Warehousing', 5.5, 'Multimodal Transport Planner is responsible for planning the transport of a shipment using various modes of transportation like railways, maritime routes, and roads. S/he is responsible for restructuring and reconfiguring the logistics strategies, optimising freight operational plans to increase cost efficiency, improve customer service effectiveness and enhance environmental sustainability.', 630, 630, '601–800', 'Version', '31 Jan 2024', '31 Jan 2027', 'Logistics Sector Skill Council (LSC)', 'Logistics Sector Skill Council', 'Transport Management', 'Multimodal Transport Manager', 'Future Skills Qualification', 'N.A.', '{"Theory":"165","Practical":"345","EmployabilitySkills":"90","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "36", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_31.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-5.5-TW-01982-2024-V1-MSU', 'Last Mile Delivery Supervisor', 'transportation-logistics-warehousing', 'Transportation, Logistics & Warehousing', 5.5, 'This is a short-term qualification to meet the growing need for Last Mile Delivery Supervisor in the country.  The Last Mile Delivery Supervisor qualification equips individuals with skills to efficiently manage and optimize the final stage of product delivery. This role involves coordinating transportation, logistics, and communication to ensure timely and accurate distribution. Last Mile Delivery Supervisors oversee the critical process of delivering goods to end customers, enhancing customer satisfaction and operational effectiveness.', 600, 600, '401–600', 'Version', '31 Jan 2024', '30 Jan 2027', 'Medhavi Skill University', 'Medhavi Skills University', 'Product Delivery', 'Vertical Progression: Delivery Operation Manager, Director of Delivery Operations, VP of Delivery Operations, Chief Operating Officer,

Horizontal Progression:  Store Manager, Warehouse Supervisor,

Academic Progression: UG degree in supply chain management, UG degree in business administration, Certified Logistics Professional (CLP)', 'General Qualification', 'N.A.', '{"Theory":"160","Practical":"320","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "37", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_31.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-4.5-TW-01971-2024-V1-TNSDC', 'Junior Supervisor - IoT Application (Supply Chain)', 'transportation-logistics-warehousing', 'Transportation, Logistics & Warehousing', 4.5, 'The  Junior Supervisor - IoT Application (Supply Chain) is responsible for strategizing, implementing, and managing IoT solutions. This role optimizes logistics operations by leveraging IoT technology, ensuring efficient tracking, data analysis, and system integration to enhance productivity, reduce costs, and improve customer satisfaction in the supply chain industry.', 570, 570, '401–600', 'Version', '31 Jan 2024', '31 Jan 2027', 'Tamil Nadu Skill Development Corporation (TNSDC)', 'TAMIL NADU SKILL DEVELOPMENT CORPORATION', 'Application and Reporting', 'Supervisor IoT application (Supply Chain)', 'Future Skills Qualification', 'N.A.', '{"Theory":"170","Practical":"220","EmployabilitySkills":"60","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "38", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_31.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-4.5-TW-01834-2024-V1-LSSC', 'Logistics and Freight Forwarding', 'transportation-logistics-warehousing', 'Transportation, Logistics & Warehousing', 4.5, 'The Logistician / Freight Forwarder manages the movement of goods from one location to another on behalf of a customer. They generally do this on a commercial basis and within a strong legal and financial framework. The modes of transport may include road, rail, air or sea, or a combination of these. The Logistician/Freight Forwarder requires specific expertise to ensure that all necessary documentation conforms to the requirements of customs, insurance and the law (IATA Conventions, Maritime Law, ICC Codes, and any international regulations governing international transportation).', 510, 510, '401–600', 'Version', '06 Feb 2024', '06 Feb 2026', 'Logistics Sector Skill Council (LSC)', 'Logistics Sector Skill Council
No. 480 A, 7th floor Khivraj Complex 2, Anna Salai, Nandanam, Chennai – 600 035', 'Freight Forwarding Operations, Transport Operations', 'This entry should refer to one or more of the following:
Professional progression: access to related qualification(s) at the next NSQF level: Exim Manager
Academic progression: access to related qualification(s) at the next NSQF level:
1.	For a Graduate - Post-Graduation is the next stage of progression
2.	For a Diploma – Graduation is the next stage of progression
3.	For a Class XII – Diploma or Graduation is the next stage of progression
4.	For a Class X - Candidate to clear Class XII through open school and proceed further to Diploma or Graduate and then to Postgraduate', 'General Qualification', 'N.A.', '{"Theory":"140","Practical":"340","EmployabilitySkills":"00","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "39", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_31.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-TW-02193-2024-V1-LSC', 'Air Cargo Booking Executive', 'transportation-logistics-warehousing', 'Transportation, Logistics & Warehousing', 4.0, 'The Air Cargo Booking Executive is responsible for performing functions related to cargo reservations, pricing, capacity optimization, handling of IT systems, freighter planning for general and special cargo. S/he is also tasked with the responsibility of handling general cargo commercial related functions.', 390, 450, '401–600', 'Version', '15 Mar 2024', '15 Mar 2027', 'Logistics Sector Skill Council (LSC)', 'Logistics sector skill council', 'Cargo Commercial', 'Air Cargo Booking Supervisor', 'Cross Sectoral Qualification', 'N.A.', '{"Theory":"120","Practical":"210","EmployabilitySkills":"30","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "40", "qualification_type": "Cross Sectoral Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_31.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-TW-02194-2024-V1-LSC', 'Air Cargo Customer Care Executive', 'transportation-logistics-warehousing', 'Transportation, Logistics & Warehousing', 4.0, 'The Air Cargo Customer Care Executive is responsible for performing functions related to cargo reservations, sales/marketing and customer relations for general and special cargo. S/ he is also tasked with the responsibility of handling business development and general cargo commercial related functions.', 390, 390, '201–400', 'Version', '15 Mar 2024', '15 Mar 2027', 'Logistics Sector Skill Council (LSC)', 'LOGISTICS SECTOR SKILL COUNCIL', 'Cargo Commercial, Customer Support/ Relations', 'Air Cargo Customer Care Supervisor', 'Cross Sectoral Qualification', 'N.A.', '{"Theory":"90","Practical":"210","EmployabilitySkills":"60","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "41", "qualification_type": "Cross Sectoral Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_31.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-5.5-TW-02191-2024-V1-LSC', 'Cold Chain Implementation Specialist', 'transportation-logistics-warehousing', 'Transportation, Logistics & Warehousing', 5.5, 'The individual at work performs market and product demand-supply assessment for cold storage, prepares project execution and cost plan, designs plant layout, manages project execution of cold storage, select vendors and maintains relationship that is strategic to business and commissions the cold storage.', 510, 510, '401–600', 'Version', '15 Mar 2024', '15 Mar 2027', 'Logistics Sector Skill Council (LSC)', 'Logistics sector skill council', 'Projects', 'Cold Chain Specialist (Green Engineering)', 'Future Skills Qualification', 'N.A.', '{"Theory":"140","Practical":"250","EmployabilitySkills":"60","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "42", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_31.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-06-TW-02192-2024-V1-LSC', 'Cold Chain Specialist (Green Engineering)', 'transportation-logistics-warehousing', 'Transportation, Logistics & Warehousing', 6.0, 'The individual at work manages sustainability in cold chain by analyzing data related to energy use,
identifying inefficiencies and implementing ways towards sustainability. The person is also responsible for maintaining equipment for temperature and storage conditions, undertaking water and effluent treatment in the plant and managing control systems of the refrigeration system components.', 600, 600, '401–600', 'Version', '15 Mar 2024', '15 Mar 2027', 'Logistics Sector Skill Council (LSC)', 'Logistics skill council', 'Engineering, Sustainability', 'Senior Green Engineering Specialist', 'Future Skills Qualification', 'N.A.', '{"Theory":"170","Practical":"280","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "43", "qualification_type": "Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_31.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-TW-02473-2024-V1-LSC', 'Green Hydrogen Refuelling Hub Operator', 'transportation-logistics-warehousing', 'Transportation, Logistics & Warehousing', 3.0, 'The Green Hydrogen Refuelling Hub Operator fills vehicles and vessels with liquid and gaseous hydrogen. The individual in this role is responsible for operating the storage and dispensing equipment with safety and ensuring customer assistance at the refuelling hub. The individual will also maintain records, generate reports, and ensure regulatory compliance for optimal hub performance.', 390, 390, '201–400', 'Version', '30 Apr 2024', '30 Apr 2027', 'Logistics Sector Skill Council (LSC)', 'Logistics sector skill council', 'Green Hydrogen Operations/Handling, Hub Operations', 'Shift Supervisor - Hydrogen Refuelling Hub (Level 4); 
Green Hydrogen storage hub senior operator (Level 4)', 'Cross Sectoral Qualification,Future Skills Qualification', 'N.A.', '{"Theory":"100","Practical":"230","EmployabilitySkills":"30","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "44", "qualification_type": "Cross Sectoral Qualification,Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_31.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-TW-02475-2024-V1-LSC', 'Green Hydrogen Storage Hub Senior Operator', 'transportation-logistics-warehousing', 'Transportation, Logistics & Warehousing', 4.0, 'The Green Hydrogen Storage Hub Senior Operator plays a pivotal role in the safe and efficient operation of the Green Hydrogen Storage Facility. The individual in this role is responsible for overseeing loading, unloading, and dispatch activities, ensuring seamless flow of the hub operations. The individual will also be responsible for monitoring the storage tanks and infrastructure, implementing preventive maintenance schedules for optimal functionality, and contributing to the reliability of the sustainable energy hub.', 480, 480, '401–600', 'Version', '30 Apr 2024', '30 Apr 2027', 'Logistics Sector Skill Council (LSC)', 'Logistics Sector Skill Council', 'Green Hydrogen Operations/Handling, Hub Operations', 'Green Hydrogen Storage Hub Supervisor/In-charge', 'Cross Sectoral Qualification,Future Skills Qualification', 'N.A.', '{"Theory":"125","Practical":"295","EmployabilitySkills":"30","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "45", "qualification_type": "Cross Sectoral Qualification,Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_31.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-TW-02474-2024-V1-LSC', 'Green Hydrogen Tube Trailer - Driver', 'transportation-logistics-warehousing', 'Transportation, Logistics & Warehousing', 4.0, 'The Green Hydrogen Tube Trailer Driver will drive specialized tube trailers efficiently on the assigned route and fulfil critical fuelling needs for a sustainable future. The individual will be responsible for safely transporting Green Hydrogen, complying with strict safety regulations and procedures. This role requires the individual to possess relevant technical skills to handle most of the routine breakdowns that could likely be encountered while driving long distances and through various terrains. The individual is also expected to achieve key performance parameters like fuel efficiency, on-time delivery, etc.', 480, 480, '401–600', 'Version', '30 Apr 2024', '30 Apr 2027', 'Logistics Sector Skill Council (LSC)', 'Logistics Sector Skill Council', 'Green Hydrogen Operations/ Handling, Transport Operations , Vehicle Operations', 'Green Hydrogen Dispatcher/ Logistics Coordinator', 'Cross Sectoral Qualification,Future Skills Qualification', 'N.A.', '{"Theory":"120","Practical":"270","EmployabilitySkills":"30","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "46", "qualification_type": "Cross Sectoral Qualification,Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_31.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
