INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-5.5-TW-03310-2024-V1-LSC', 'Green Hydrogen Procurement Manager', 'transportation-logistics-warehousing', 'Transportation, Logistics & Warehousing', 5.5, 'The individual in this job role is responsible for devising procurement strategies, selecting suppliers, and procuring clean energy and other raw materials for the production of Green Hydrogen. Additionally, they handle contracts and supplier relationships, prioritising safety and resource management in the workplace. This role demands meticulous planning, efficient execution, and a commitment to sustainability in energy management.', 600, 600, '401–600', 'Version', '22 Oct 2024', '22 Oct 2027', 'Logistics Sector Skill Council (LSC)', 'Logistics Sector Skill council', 'Supply Chain Operations, Green Hydrogen Operations/ Handling', 'Green Hydrogen Procurement Senior Manager', 'Cross Sectoral Qualification,Future Skills Qualification', 'N.A.', '{"Theory":"160","Practical":"350","EmployabilitySkills":"60","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "57", "qualification_type": "Cross Sectoral Qualification,Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_31.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-TW-03313-2024-V1-LSC', 'Refrigerated Storage Unit Supervisor', 'transportation-logistics-warehousing', 'Transportation, Logistics & Warehousing', 5.0, 'The individual monitors the plant''s technical functioning to ensure that the required storage and plant operating parameters match the product requirements in the event of a change in environmental conditions/variations in external conditions. Additionally, they administer activities in the grading line, pre cooling unit and ripening chamber until products are packaged and ready for dispatch.', 570, 630, '601–800', 'Version', '22 Oct 2024', '22 Oct 2027', 'Logistics Sector Skill Council (LSC)', 'Logistics Sector Skill Council', 'Cold Chain Operations', 'Cold Chain Specialist (Green Engineering), Cold Storage Unit Manager', 'Multi-Skill Qualification', 'N.A.', '{"Theory":"160","Practical":"260","EmployabilitySkills":"60","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "58", "qualification_type": "Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_31.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-06-TW-03311-2024-V1-LSC', 'Green Hydrogen Storage Hub Manager', 'transportation-logistics-warehousing', 'Transportation, Logistics & Warehousing', 6.0, 'Green Hydrogen Storage Hub Manager is responsible for planning and coordinating storage hub operations, ensuring the safe and efficient management of hydrogen storage systems, and driving compliance with environmental and sustainability standards. They will devise and implement strategies, processes, and programs to meet industry standards and regulatory requirements. The individual in this role will also maintain operational records, financial reports, and compliance documentation for audits and inspections. Additionally, they will drive innovation in storage technology, manage legal and contractual obligations, and lead sustainability and environmental impact management efforts.', 600, 600, '401–600', 'Version', '22 Oct 2024', '22 Oct 2027', 'Logistics Sector Skill Council (LSC)', 'Logistics Sector Skill Council', 'Green Hydrogen Operations/ Handling, Hub Operations', 'Green Hydrogen Storage Hub Senior Manager', 'Cross Sectoral Qualification,Future Skills Qualification', 'N.A.', '{"Theory":"180","Practical":"300","EmployabilitySkills":"90","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "59", "qualification_type": "Cross Sectoral Qualification,Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_31.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-06-TW-03312-2024-V1-LSC', 'Green Hydrogen Supply Chain - SHEQ  Manager', 'transportation-logistics-warehousing', 'Transportation, Logistics & Warehousing', 6.0, 'The individual in this job role is responsible for ensuring compliance with occupational Safety, Health, Environment, and Quality (SHEQ) parameters across all functions in the Supply chain of Green Hydrogen. S/he will devise and implement strategies, processes, programs and parameters to meet the standards and regulatory requirements. Their duties will also include assessing and mitigating risks, investigating accidents and near-miss incidents, and driving continuous safety and operational excellence improvement. The SHEQ manager is fully responsible for the maintenance of records and incident reports related to health, safety, and quality and their submission during quality audits.', 630, 630, '601–800', 'Version', '22 Oct 2024', '22 Oct 2027', 'Logistics Sector Skill Council (LSC)', 'Logistics Sector Skill Council', 'Green Hydrogen Operations/ Handling, Liquid Transport Operations, Supply Chain Operations, Documentation and Reporting', 'Green Hydrogen Supply Chain Senior SHEQ Manager', 'Cross Sectoral Qualification,Future Skills Qualification', 'N.A.', '{"Theory":"160","Practical":"320","EmployabilitySkills":"90","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "60", "qualification_type": "Cross Sectoral Qualification,Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_31.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-TW-03314-2024-V1-LSC', 'Reefer Vehicle Operator cum Driver', 'transportation-logistics-warehousing', 'Transportation, Logistics & Warehousing', 4.0, 'The individual at work inspects, maintains and drives the reefer vehicle to the destination, monitors the temperature control logistics in transit by operating the required temperature monitoring device and ensuring a constant check on product safety in transit with respect to its quality, safety and temperature from origin to destination.', 450, 450, '401–600', 'Version', '22 Oct 2024', '22 Oct 2027', 'Logistics Sector Skill Council (LSC)', 'Logistics Sector Skill Council', 'Vehicle Operations, Transport Operations', 'Cold storage unit supervisor', 'General Qualification', 'N.A.', '{"Theory":"160","Practical":"230","EmployabilitySkills":"30","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "61", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_31.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-TW-03515-2025-V1-ASAP', 'Supply Chain and Logistics Analyst', 'transportation-logistics-warehousing', 'Transportation, Logistics & Warehousing', 5.0, '"This course prepares individuals to efficiently manage logistics operations, focusing on inventory
control, transportation, and distribution. It covers essential concepts like supply chain workflows,
performance metrics, and compliance requirements, combining theoretical and practical knowledge.
Learners will acquire mid-level skills, including problem-solving, process optimization, and use of
technology in logistics. The program aligns with NSQF Level 5, enabling participants to pursue
careers in warehousing, procurement, and distribution management."', 540, 540, '401–600', 'Version', '18 Feb 2025', '18 Feb 2028', 'Additional Skill Acquisition Programme, Government of Kerala', 'ADDITIONAL SKILL ACQUISITION PROGRAMME', 'Supply Chain and Logistics Analyst', 'Supply Chain Specialist ,Supply chain  Manager ,E commerce manager,Consultant,Supply Chain Specialist', 'General Qualification', 'N.A.', '{"Theory":"120","Practical":"270","EmployabilitySkills":"60","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "62", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_31.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-TW-03632-2025-V2-LSC', 'Tertiary Goods  Packaging Machine  Operator', 'transportation-logistics-warehousing', 'Transportation, Logistics & Warehousing', 4.0, 'Tertiary Goods Packaging Machine Operators are also known as Goods Packaging Operators or Packaging Machine Operators. Individuals in this role operate packaging equipment and feed packing materials in Automatic Packaging Lines for ambient and other non-hazardous goods. They paste labels onto the sealed packing cases. In large-scale operations, a separate person might do the labelling operation.', 480, 600, '401–600', 'Version', '18 Feb 2025', '18 Feb 2028', 'Logistics Sector Skill Council (LSC)', 'Logistics Sector Skill Council', 'Packaging', 'Warehouse supervisor', 'General Qualification', 'N.A.', '{"Theory":"120","Practical":"240","EmployabilitySkills":"30","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "63", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_31.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-TW-03633-2025-V2-LSC', 'Data Feeder - Warehouse', 'transportation-logistics-warehousing', 'Transportation, Logistics & Warehousing', 4.0, 'Data Feeder – Warehouse is responsible for accurately entering and managing data related to warehouse operations, ensuring the smooth flow of inventory and logistics information into the company''s database or warehouse management system (WMS)/ ERP. In the Logistics industry, a data feeder - warehouse is also known as a system executive, warehouse data executive or warehouse data entry operator. Individuals in this role must electronically process all orders and provide database management support for warehouse operations. Responsibilities include logging orders, maintaining reports, and generating pick lists and schedules.', 450, 510, '401–600', 'Version', '18 Feb 2025', '18 Feb 2028', 'Logistics Sector Skill Council (LSC)', 'Logistics Sector Skill Council', 'Documentation and Reporting, Technology', 'Warehouse Supervisor', 'Cross Sectoral Qualification,Future Skills Qualification', 'N.A.', '{"Theory":"120","Practical":"270","EmployabilitySkills":"30","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "64", "qualification_type": "Cross Sectoral Qualification,Future Skills Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_31.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-05-TW-03634-2025-V2-LSC', 'Key Accounts Management Executive – Courier', 'transportation-logistics-warehousing', 'Transportation, Logistics & Warehousing', 5.0, 'Key Accounts Management Executive - Courier plays a crucial role in developing and nurturing relationships with key clients to drive business growth. They are also known as Key Account assistant managers or Key Consignor Executives. Individuals in this role who work closely with key clients are responsible for maintaining relationships with existing key clients and resolving their issues, identifying prospective key clients, and developing business opportunities with them. They are an integral part of the sales team and manage the relationships with several key clients of an organisation.', 570, 570, '401–600', 'Version', '18 Feb 2025', '18 Feb 2028', 'Logistics Sector Skill Council (LSC)', 'Logistics Sector Skill Council', 'Customer relationship management, Institutional Sales', 'Courier Manager', 'General Qualification', 'N.A.', '{"Theory":"180","Practical":"300","EmployabilitySkills":"60","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "65", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_31.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-TW-03635-2025-V2-LSC', 'Claims coordinator - Warehouse', 'transportation-logistics-warehousing', 'Transportation, Logistics & Warehousing', 4.0, 'Claims coordinator - Warehouse is also known as Warehouse Claims Processor. Individuals in this role are responsible for receiving claims, assessing the goods concerned to ensure the claim is genuine and estimating the reimbursable amount. They are also required to verify all the documents, send the claims to the insurance companies and provide detailed reports to the management.', 420, 420, '401–600', 'Version', '18 Feb 2025', '18 Feb 2028', 'Logistics Sector Skill Council (LSC)', 'Logistics Sector Skill Council', 'Claims Management, Documentation and Reporting', 'Warehouse supervisor', 'General Qualification', 'N.A.', '{"Theory":"120","Practical":"240","EmployabilitySkills":"30","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "66", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_31.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-4.5-TW-03511-2025-V1-DMRCA', 'Junior Engineer – Traction (Metro Rail)', 'transportation-logistics-warehousing', 'Transportation, Logistics & Warehousing', 4.5, 'The Junior Engineer - Traction oversees the installation, operation, and maintenance of Power Supply Installation (PSI) and SCADA systems, ensuring reliable power supply within the traction network. This role includes coordinating Overhead Electrification (OHE) maintenance, coordinating with technical teams, and ensuring adherence to safety protocols for efficient traction system operations.', 510, 510, '401–600', 'Version', '18 Feb 2025', '18 Feb 2028', 'Delhi Metro Rail Academy (DMRA)', 'DMRC Academy', 'Traction', 'Engineer – Traction (Metro Rail)', 'General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"150","Practical":"120","EmployabilitySkills":"30","OJT_Mandatory":"210"}', false, '{}'::text[], '{"source_row": "67", "qualification_type": "General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_31.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-4.5-TW-03512-2025-V1-DMRCA', 'Junior Engineer – Signal (Metro Rail)', 'transportation-logistics-warehousing', 'Transportation, Logistics & Warehousing', 4.5, 'A Junior Engineer - Signal (Metro Rail) oversees metro rail signalling systems&#39; installation, maintenance, and troubleshooting to ensure safe and efficient train operations. The individual’s responsibilities include overseeing point machines, track circuits, interlocking systems, and Platform Screen Doors (PSDs) and coordinating with telecom and power supply teams. It also involves monitoring Automatic Train Protection (ATP) and Automatic Train Supervision (ATS) systems, ensuring compliance with safety protocols, and conducting regular maintenance and emergency response drills.', 510, 510, '401–600', 'Version', '18 Feb 2025', '18 Feb 2028', 'Delhi Metro Rail Academy (DMRA)', 'DMRC Academy', 'Signalling & Telecom', 'Engineer – Signal (Metro Rail) (L6.0)', 'General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"180","Practical":"150","EmployabilitySkills":"30","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "68", "qualification_type": "General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_31.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-4.5-TW-03513-2025-V1', 'Junior Engineer - Rolling Stock (Metro Rail)', 'transportation-logistics-warehousing', 'Transportation, Logistics & Warehousing', 4.5, 'A Junior Engineer - Rolling Stock (Metro Rail) is responsible for overseeing the maintenance and safety compliance of various rolling stock systems. It involves conducting preventive maintenance checks, implementing essential safety and maintenance procedures, and ensuring that rolling stock operates optimally. The individual will also participate in GMSM and MSM simulator training for enhanced diagnostic skills and engage in specialized training across traction, electrical & mechanical (E&M), signaling & telecommunications (S&T), P-way, and related departments to maintain proficiency. An understanding of VCC and pneumatic circuit operations is critical to support safe, efficient rolling stock performance.', 510, 510, '401–600', 'Version', '18 Feb 2025', '18 Feb 2028', 'Delhi Metro Rail Academy (DMRA)', 'DMRC Academy', 'Rolling Stock', 'Engineer – Rolling Stock (Metro Rail) (L6.0)', 'General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"180","Practical":"150","EmployabilitySkills":"30","OJT_Mandatory":"150"}', false, '{}'::text[], '{"source_row": "69", "qualification_type": "General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_31.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-4.5-TW-03514-2025-V1-DMRCA', 'Junior Engineer -Civil (Metro Rail)', 'transportation-logistics-warehousing', 'Transportation, Logistics & Warehousing', 4.5, 'A Junior Engineer - Civil (Metro Rail) is responsible for coordinating railway track maintenance and inspection, including LWR and associated track elements, ensuring adherence to inspection protocols. The individual oversees accident and emergency response, track renewal, and the use of P.Way tools and equipment for track maintenance. The role includes coordinating construction and maintenance activities in Metro projects and conducting site inspections for viaducts, stations, and treatment plants to ensure structural integrity and safety compliance.', 510, 510, '401–600', 'Version', '18 Feb 2025', '18 Feb 2028', 'Delhi Metro Rail Academy (DMRA)', 'DMRC Academy', 'Civil', 'Engineer – Civil (Metro Rail) (L6.0)', 'General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"210","Practical":"150","EmployabilitySkills":"30","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "70", "qualification_type": "General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_31.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-4.5-TW-04144-2025-V1-DMRCA', 'Junior Engineer – Electrical & Mechanical System (Metro Rail)', 'transportation-logistics-warehousing', 'Transportation, Logistics & Warehousing', 4.5, 'A Junior Engineer – Electrical & Mechanical System (Metro Rail) oversees the operation, inspection, and maintenance of Electrical & Mechanical (E&M) systems in metro stations, including underground and elevated setups. The individual ensures energy efficiency, infrastructure management, and compliance with safety standards for escalators and elevators, contributing to smooth station operations. The person coordinates with teams to implement preventive maintenance and address technical issues.', 510, 510, '401–600', 'Version', '08 May 2025', '08 May 2028', 'Delhi Metro Rail Academy (DMRA)', 'DMRC Academy', 'Electrical & Mechanical', 'Engineer – Electrical & Mechanical System (Metro Rail)', 'General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"120","Practical":"150","EmployabilitySkills":"30","OJT_Mandatory":"210"}', false, '{}'::text[], '{"source_row": "71", "qualification_type": "General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_31.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-4.5-TW-04145-2025-V1-DMRCA', 'Supervisor – Operations (Metro Rail)', 'transportation-logistics-warehousing', 'Transportation, Logistics & Warehousing', 4.5, 'A Supervisor - Operations (Metro Rail) oversees metro railway operations, ensuring system efficiency, safety compliance, and smooth service delivery. The role includes managing signaling, telecom, and fare collection systems, supervising station operations, and handling rolling stock and train operations.', 300, 510, '401–600', 'Version', '08 May 2025', '08 May 2028', 'Delhi Metro Rail Academy (DMRA)', 'DMRC Academy', 'Metro Rail Operations', 'Engineer – Operations (Metro Rail)', 'General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"147","Practical":"303","EmployabilitySkills":"30","OJT_Mandatory":"30"}', false, '{}'::text[], '{"source_row": "72", "qualification_type": "General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_31.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-4.5-TW-04143-2025-V1-DMRCA', 'Junior Engineer - Automatic Fare Collection and Telecom Systems (Metro Rail)', 'transportation-logistics-warehousing', 'Transportation, Logistics & Warehousing', 4.5, 'A  Junior Engineer - Automatic Fare Collection and Telecom Systems (Metro Rail) is responsible for performing basic signalling operations, overseeing the installation, operation, and maintenance of Telecom and Automatic Fare Collection (AFC) systems. The role ensures system efficiency, compliance with safety standards, and effective team coordination to maintain uninterrupted metro operations.', 540, 540, '401–600', 'Version', '08 May 2025', '08 May 2028', 'Delhi Metro Rail Academy (DMRA)', 'DMRC Academy', 'Signalling & Telecom', 'Engineer – Automatic Fare Collection and Telecom Systems (Metro Rail)', 'General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"180","Practical":"210","EmployabilitySkills":"30","OJT_Mandatory":"120"}', false, '{}'::text[], '{"source_row": "73", "qualification_type": "General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_31.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-04-TW-04445-2025-V1-ASAP', 'Fundamentals of Q-Commerce', 'transportation-logistics-warehousing', 'Transportation, Logistics & Warehousing', 4.0, 'Fundamentals of Q-Commerce provides a foundational understanding of Quick Commerce, focusing on rapid delivery systems, hyper-local inventory management, and real-time logistics. Learners will explore key technologies and strategies driving speed, efficiency, and customer satisfaction in modern commerce. The program is designed to prepare individuals for emerging roles in the fast-evolving Quick Commerce ecosystem.', 150, 150, '1–200', 'Version', '07 Oct 2025', '07 Oct 2028', 'Additional Skill Acquisition Programme, Government of Kerala', 'Additional Skill Acquisition Programme Kerala', 'Warehouse Management', 'Q-Commerce Operations Executive', 'General Qualification', 'N.A.', '{"Theory":"60","Practical":"90","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "74", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_31.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QM-4-PL-00358-2023-V1-WMPS', 'Jal Vitaran Sanchalak (Water Distribution Operator)', 'water-supply-sewerage-waste-management-remediation-activities', 'Water Supply, Sewerage, Waste Management & Remediation activities', 4.0, 'Jal Vitaran Sanchaalak (Water Distribution Operator) (Multi - Skill) would act as a one stop solution provider who gives various services to communities under the Jal Jeevan Mission scheme such as plumbing installation, maintenance, repair and operations of various plumbing related structures and systems. The person will also mobilize community members and organize for required resources across a specified geographic area with support from Village Water & Sanitation Committee, Gram Panchayat and government bodies. The person carries operations on basic masonry work along with basic electrical installation.', 510, 510, '401–600', 'Version', '13 Jun 2023', '13 Jun 2026', 'Water Management and Plumbing Skill Council (WMPSC)', 'Water Management and Plumbing Skill Council (WMPSC)', 'Plumbing Systems Installations and Maintenance', 'Jal Mitra, Plumbing Supervisor, Plant Supervisor', 'Multi-Skill Qualification', 'N.A.', '{"Theory":"90","Practical":"210","EmployabilitySkills":"30","OJT_Mandatory":"180"}', false, '{}'::text[], '{"source_row": "1", "qualification_type": "Multi-Skill Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_58.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-03-ES-02634-2024-V2-SCGJ', 'Safai Mitra', 'water-supply-sewerage-waste-management-remediation-activities', 'Water Supply, Sewerage, Waste Management & Remediation activities', 3.0, 'Safai Mitra sweeps, cleans and removes garbage from public areas and buildings. In public areas and roads, Safai Mitra sweeps with a broom and / or other suitable equipment to remove dust, debris and garbage. In buildings, he/she sweeps the floor, scrubs the floor using appropriate cleaning solution to remove the fine dust. He/She removes the garbage and aggregates the garbage in the designated areas.', 360, 360, '201–400', 'Version', '27 May 2021', '29 May 2027', 'Skill Council for Green Jobs (SCGJ)', 'Skill Council for Green Jobs', 'Janitor/Housekeeping Attendant', 'Assistant Sanitary Inspector (Level 4)', 'General Qualification', 'N.A.', '{"Theory":"120","Practical":"150","EmployabilitySkills":"30","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "2", "qualification_type": "General Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_58.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-3.5-WS-02940-2024-V1-WMPS', 'Water Treatment Plant Assistant Operator', 'water-supply-sewerage-waste-management-remediation-activities', 'Water Supply, Sewerage, Waste Management & Remediation activities', 3.5, 'A Water Treatment Plant Assistant Operator is responsible for treating wastewater in water treatment plants. The individual carries out various processes for effective water treatment and effluent management in compliance with the applicable environmental regulations. The person uses different water treatment plant equipment and also carries out their basic repair and maintenance.', 420, 420, '401–600', 'Version', '27 Aug 2024', '27 Aug 2027', 'Water Management and Plumbing Skill Council (WMPSC)', 'Water Management and Plumbing Skill Council', 'Water Treatment', 'Plant Operator (L4)', 'General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"90","Practical":"240","EmployabilitySkills":"30","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "3", "qualification_type": "General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_58.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NM-02-WS-03009-2024-V1-WMPSC', 'Fundamentals of Water Quality Analysis: Test Kit Techniques', 'water-supply-sewerage-waste-management-remediation-activities', 'Water Supply, Sewerage, Waste Management & Remediation activities', 2.0, 'This Fundamental course will allow the participants to obtain the necessary skills to analyses water quality based on contaminant levels and chemical composition including pH, dissolved oxygen, turbidity, chlorine level, etc. It covers the use of relevant tools and equipment.', 30, 30, '1–200', 'Version', '27 Aug 2024', '27 Aug 2027', 'Water Management and Plumbing Skill Council (WMPSC)', 'Water Management and Plumbing Skill Council', 'Water Quality Testing', 'N/A', 'Micro Credentials', 'N.A.', '{"Theory":"10","Practical":"20","EmployabilitySkills":"00","OJT_Mandatory":"00"}', false, '{}'::text[], '{"source_row": "4", "qualification_type": "Micro Credentials", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_58.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-WS-02939-2024-V1-WMPS', 'Industrial Wastewater Treatment Plant Operator', 'water-supply-sewerage-waste-management-remediation-activities', 'Water Supply, Sewerage, Waste Management & Remediation activities', 4.0, 'Industrial Wastewater Treatment Plant Operator responsible for operating and maintaining effluent treatment systems, monitoring water quality parameters, conducting routine tests, adjusting chemical dosages, troubleshooting equipment issues, and ensuring compliance with environmental regulations.', 450, 450, '401–600', 'Version', '27 Aug 2024', '27 Aug 2027', 'Water Management and Plumbing Skill Council (WMPSC)', 'Water Management and Plumbing Skill Council', 'Effluent and Wastewater Treatment', 'Plant Supervisor (L5)', 'General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"120","Practical":"240","EmployabilitySkills":"30","OJT_Mandatory":"60"}', false, '{}'::text[], '{"source_row": "5", "qualification_type": "General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_58.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-TH-02938-2024-V1-WMPS', 'Sewage Treatment Plant Operator', 'water-supply-sewerage-waste-management-remediation-activities', 'Water Supply, Sewerage, Waste Management & Remediation activities', 4.0, 'The Sewage Treatment Plant Operator is responsible for the operation, monitoring, and maintenance of sewage treatment plants. They ensure that wastewater is treated effectively and in compliance with environmental regulations. Sewage Treatment Plant Operators perform various tasks to control and maintain the treatment process, troubleshoot issues, and ensure the plant''s efficient and safe operation.', 450, 450, '401–600', 'Version', '27 Aug 2024', '27 Aug 2027', 'Water Management and Plumbing Skill Council (WMPSC)', 'Water Management and Plumbing Skill Council', 'Sewage /Effluent Treatment', 'Plant Supervisor (L5)', 'General Qualification,Upskilling Qualification', 'N.A.', '{"Theory":"90","Practical":"240","EmployabilitySkills":"30","OJT_Mandatory":"90"}', false, '{}'::text[], '{"source_row": "6", "qualification_type": "General Qualification,Upskilling Qualification", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_15_58.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-2.5-WC-00762-2023-V1-FFSC', 'Boat Maker', 'wood-carpentry', 'Wood & Carpentry', 2.5, 'This qualification is designed to upgrade the skills of existing boat makers by providing hands-on training in the safe and effective usage of modern power tools. Participants will learn how to operate various power tools, ensuring precision, efficiency, and safety in boat making tasks. This qualification also included the self-employment skills required in small business planning, management, and expansion for Vishwakarmas. It also includes government support and loans Vishwakarma’s can avail and utilizing the benefits of ecommerce and digital payment applications for their small business', 40, 40, '1–200', 'Version', '14 Sep 2023', '14 Sep 2026', 'Furniture & Fittings Skill Council (FFSC)', 'Furniture & Fittings Skill Council (FFSC)', 'Furniture Installation and After Sales', 'L3 Boat Maker (Advanced)', 'National Occupational Standard', 'N.A.', '{"Theory":"11.5","Practical":"28.5","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "1", "qualification_type": "National Occupational Standard", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_16_08.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('NG-2.5-WC-00763-2023-V1-FFSC', 'Carpenter', 'wood-carpentry', 'Wood & Carpentry', 2.5, 'This qualification is designed to upgrade the skills of existing carpenters by providing hands-on training in the safe and effective usage of modern power tools. Participants will learn how to operate various power tools, ensuring precision, efficiency, and safety in carpentry tasks.  This qualification also included the self-employment skills required in small business planning, management, and expansion for Vishwakarmas. It also includes government support and loans Vishwakarma’s can avail and utilizing the benefits of ecommerce and digital payment applications for their small business.', 40, 40, '1–200', 'Version', '14 Sep 2023', '14 Sep 2026', 'Furniture & Fittings Skill Council (FFSC)', 'Furniture & Fittings Skill Council (FFSC)', 'Furniture Installation and After Sales', 'L3 Carpenter (Advanced)', 'National Occupational Standard', 'N.A.', '{"Theory":"11.5","Practical":"28.5","EmployabilitySkills":"0","OJT_Mandatory":"0"}', false, '{}'::text[], '{"source_row": "2", "qualification_type": "National Occupational Standard", "version": "Version"}'::jsonb, 'Qualifications 02-10-2026 20_16_08.xlsx', true) ON CONFLICT (q_code, title) DO UPDATE SET sector_id = EXCLUDED.sector_id, nsqf_level = EXCLUDED.nsqf_level, description = EXCLUDED.description, min_notional_hours = EXCLUDED.min_notional_hours, max_notional_hours = EXCLUDED.max_notional_hours, notional_hours_range = EXCLUDED.notional_hours_range, is_pwd = EXCLUDED.is_pwd, pwd_categories = EXCLUDED.pwd_categories, updated_at = NOW();
INSERT INTO nsqf_qualifications (q_code, title, sector_id, sector_name, nsqf_level, description, min_notional_hours, max_notional_hours, notional_hours_range, version, originally_approved, valid_till, awarding_body, certifying_bodies, proposed_occupation, progression_pathway, qualification_type, adopted_qualification, training_delivery_hours, is_pwd, pwd_categories, raw_metadata, source_file, is_active) VALUES ('QG-04-WC-00828-2023-V2-FFSC', 'Assistant Carpenter', 'wood-carpentry', 'Wood & Carpentry', 4.0, 'The Assistant Carpenter plays the primary role of assisting in preparing the worksite, fabrication, assembly, finishing, and installation of the products on the worksite. The person is responsible for loading, unloading, moving, and storing required materials, tools, and equipment. The individual will also perform additional tasks as delegated by the senior carpenters in construction, maintenance, repairing, remodeling on the worksite. The Assistant Carpenter reports to the Carpenter.', 570, 570, '401–600', 'Version', '31 Aug 2023', '31 Aug 2026', 'Furniture & Fittings Skill Council (FFSC)', 'Furniture and Fittings Sector Skill Council

Chief Executive Officer
407-408, 4th Floor, DLF City Court, MG Road
Sikenderpur, Gurgaon (Haryana)- 122 002
Tel: 91 124 4513900
Email Id: info@ffsc.in', 'Furniture Installation & After Sales', 'Professional Progression (Vertical):
Carpenter (NSQF Level 4.5)
